window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["行政法"] = {"zhongyiyaofa":[{"i":1,"n":"第一条","txt":"为了继承和弘扬中医药，保障和促进中医药事业发展，保护人民健康，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称中医药，是包括汉族和少数民族医药在内的我国各民族医药的统称，是反映中华民族对生命、健康和疾病的认识，具有悠久历史传统和独特理论及技术方法的医药学体系。"},{"i":3,"n":"第三条","txt":"中医药事业是我国医药卫生事业的重要组成部分。国家大力发展中医药事业，实行中西医并重的方针，建立符合中医药特点的管理制度，充分发挥中医药在我国医药卫生事业中的作用。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将中医药事业纳入国民经济和社会发展规划，建立健全中医药管理体系，统筹推进中医药事业发展。"},{"i":5,"n":"第五条","txt":"国务院中医药主管部门负责全国的中医药管理工作。国务院其他有关部门在各自职责范围内负责与中医药管理有关的工作。"},{"i":6,"n":"第六条","txt":"国家加强中医药服务体系建设，合理规划和配置中医药服务资源，为公民获得中医药服务提供保障。"},{"i":7,"n":"第七条","txt":"国家发展中医药教育，建立适应中医药事业发展需要、规模适宜、结构合理、形式多样的中医药教育体系，培养中医药人才。"},{"i":8,"n":"第八条","txt":"国家支持中医药科学研究和技术开发，鼓励中医药科学技术创新，推广应用中医药科学技术成果，保护中医药知识产权，提高中医药科学技术水平。"},{"i":9,"n":"第九条","txt":"国家支持中医药对外交流与合作，促进中医药的国际传播和应用。"},{"i":10,"n":"第十条","txt":"对在中医药事业中做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府应当将中医医疗机构建设纳入医疗机构设置规划，举办规模适宜的中医医疗机构，扶持有中医药特色和优势的医疗机构发展。"},{"i":12,"n":"第十二条","txt":"政府举办的综合医院、妇幼保健机构和有条件的专科医院、社区卫生服务中心、乡镇卫生院，应当设置中医药科室。"},{"i":13,"n":"第十三条","txt":"国家支持社会力量举办中医医疗机构。"},{"i":14,"n":"第十四条","txt":"举办中医医疗机构应当按照国家有关医疗机构管理的规定办理审批手续，并遵守医疗机构管理的有关规定。"},{"i":15,"n":"第十五条","txt":"从事中医医疗活动的人员应当依照《中华人民共和国执业医师法》的规定，通过中医医师资格考试取得中医医师资格，并进行执业注册。中医医师资格考试的内容应当体现中医药特点。"},{"i":16,"n":"第十六条","txt":"中医医疗机构配备医务人员应当以中医药专业技术人员为主，主要提供中医药服务；经考试取得医师资格的中医医师按照国家有关规定，经培训、考核合格后，可以在执业活动中采用与其专业相关的现代科学技术方法。在医疗活动中采用现代科学技术方法的，应当有利于保持和发挥中医药特色和优势。"},{"i":17,"n":"第十七条","txt":"开展中医药服务，应当以中医药理论为指导，运用中医药技术方法，并符合国务院中医药主管部门制定的中医药服务基本要求。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府应当发展中医药预防、保健服务，并按照国家有关规定将其纳入基本公共卫生服务项目统筹实施。"},{"i":19,"n":"第十九条","txt":"医疗机构发布中医医疗广告，应当经所在地省、自治区、直辖市人民政府中医药主管部门审查批准；未经审查批准，不得发布。发布的中医医疗广告内容应当与经审查批准的内容相符合，并符合《中华人民共和国广告法》的有关规定。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府中医药主管部门应当加强对中医药服务的监督检查，并将下列事项作为监督检查的重点："},{"i":21,"n":"第二十一条","txt":"国家制定中药材种植养殖、采集、贮存和初加工的技术规范、标准，加强对中药材生产流通全过程的质量监督管理，保障中药材质量安全。"},{"i":22,"n":"第二十二条","txt":"国家鼓励发展中药材规范化种植养殖，严格管理农药、肥料等农业投入品的使用，禁止在中药材种植过程中使用剧毒、高毒农药，支持中药材良种繁育，提高中药材质量。"},{"i":23,"n":"第二十三条","txt":"国家建立道地中药材评价体系，支持道地中药材品种选育，扶持道地中药材生产基地建设，加强道地中药材生产基地生态环境保护，鼓励采取地理标志产品保护等措施保护道地中药材。"},{"i":24,"n":"第二十四条","txt":"国务院药品监督管理部门应当组织并加强对中药材质量的监测，定期向社会公布监测结果。国务院有关部门应当协助做好中药材质量监测有关工作。"},{"i":25,"n":"第二十五条","txt":"国家保护药用野生动植物资源，对药用野生动植物资源实行动态监测和定期普查，建立药用野生动植物资源种质基因库，鼓励发展人工种植养殖，支持依法开展珍贵、濒危药用野生动植物的保护、繁育及其相关研究。"},{"i":26,"n":"第二十六条","txt":"在村医疗机构执业的中医医师、具备中药材知识和识别能力的乡村医生，按照国家有关规定可以自种、自采地产中药材并在其执业活动中使用。"},{"i":27,"n":"第二十七条","txt":"国家保护中药饮片传统炮制技术和工艺，支持应用传统工艺炮制中药饮片，鼓励运用现代科学技术开展中药饮片炮制技术研究。"},{"i":28,"n":"第二十八条","txt":"对市场上没有供应的中药饮片，医疗机构可以根据本医疗机构医师处方的需要，在本医疗机构内炮制、使用。医疗机构应当遵守中药饮片炮制的有关规定，对其炮制的中药饮片的质量负责，保证药品安全。医疗机构炮制中药饮片，应当向所在地设区的市级人民政府药品监督管理部门备案。"},{"i":29,"n":"第二十九条","txt":"国家鼓励和支持中药新药的研制和生产。"},{"i":30,"n":"第三十条","txt":"生产符合国家规定条件的来源于古代经典名方的中药复方制剂，在申请药品批准文号时，可以仅提供非临床安全性研究资料。具体管理办法由国务院药品监督管理部门会同中医药主管部门制定。"},{"i":31,"n":"第三十一条","txt":"国家鼓励医疗机构根据本医疗机构临床用药需要配制和使用中药制剂，支持应用传统工艺配制中药制剂，支持以中药制剂为基础研制中药新药。"},{"i":32,"n":"第三十二条","txt":"医疗机构配制的中药制剂品种，应当依法取得制剂批准文号。但是，仅应用传统工艺配制的中药制剂品种，向医疗机构所在地省、自治区、直辖市人民政府药品监督管理部门备案后即可配制，不需要取得制剂批准文号。"},{"i":33,"n":"第三十三条","txt":"中医药教育应当遵循中医药人才成长规律，以中医药内容为主，体现中医药文化特色，注重中医药经典理论和中医药临床实践、现代教育方式和传统教育方式相结合。"},{"i":34,"n":"第三十四条","txt":"国家完善中医药学校教育体系，支持专门实施中医药教育的高等学校、中等职业学校和其他教育机构的发展。"},{"i":35,"n":"第三十五条","txt":"国家发展中医药师承教育，支持有丰富临床经验和技术专长的中医医师、中药专业技术人员在执业、业务活动中带徒授业，传授中医药理论和技术方法，培养中医药专业技术人员。"},{"i":36,"n":"第三十六条","txt":"国家加强对中医医师和城乡基层中医药专业技术人员的培养和培训。"},{"i":37,"n":"第三十七条","txt":"县级以上地方人民政府中医药主管部门应当组织开展中医药继续教育，加强对医务人员，特别是城乡基层医务人员中医药基本知识和技能的培训。"},{"i":38,"n":"第三十八条","txt":"国家鼓励科研机构、高等学校、医疗机构和药品生产企业等，运用现代科学技术和传统中医药研究方法，开展中医药科学研究，加强中西医结合研究，促进中医药理论和技术方法的继承和创新。"},{"i":39,"n":"第三十九条","txt":"国家采取措施支持对中医药古籍文献、著名中医药专家的学术思想和诊疗经验以及民间中医药技术方法的整理、研究和利用。"},{"i":40,"n":"第四十条","txt":"国家建立和完善符合中医药特点的科学技术创新体系、评价体系和管理体制，推动中医药科学技术进步与创新。"},{"i":41,"n":"第四十一条","txt":"国家采取措施，加强对中医药基础理论和辨证论治方法，常见病、多发病、慢性病和重大疑难疾病、重大传染病的中医药防治，以及其他对中医药理论和实践发展有重大促进作用的项目的科学研究。"},{"i":42,"n":"第四十二条","txt":"对具有重要学术价值的中医药理论和技术方法，省级以上人民政府中医药主管部门应当组织遴选本行政区域内的中医药学术传承项目和传承人，并为传承活动提供必要的条件。传承人应当开展传承活动，培养后继人才，收集整理并妥善保存相关的学术资料。属于非物质文化遗产代表性项目的，依照《中华人民共和国非物质文化遗产法》的有关规定开展传承活动。"},{"i":43,"n":"第四十三条","txt":"国家建立中医药传统知识保护数据库、保护名录和保护制度。"},{"i":44,"n":"第四十四条","txt":"国家发展中医养生保健服务，支持社会力量举办规范的中医养生保健机构。中医养生保健服务规范、标准由国务院中医药主管部门制定。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府应当加强中医药文化宣传，普及中医药知识，鼓励组织和个人创作中医药文化和科普作品。"},{"i":46,"n":"第四十六条","txt":"开展中医药文化宣传和知识普及活动，应当遵守国家有关规定。任何组织或者个人不得对中医药作虚假、夸大宣传，不得冒用中医药名义牟取不正当利益。"},{"i":47,"n":"第四十七条","txt":"县级以上人民政府应当为中医药事业发展提供政策支持和条件保障，将中医药事业发展经费纳入本级财政预算。"},{"i":48,"n":"第四十八条","txt":"县级以上人民政府及其有关部门应当按照法定价格管理权限，合理确定中医医疗服务的收费项目和标准，体现中医医疗服务成本和专业技术价值。"},{"i":49,"n":"第四十九条","txt":"县级以上地方人民政府有关部门应当按照国家规定，将符合条件的中医医疗机构纳入基本医疗保险定点医疗机构范围，将符合条件的中医诊疗项目、中药饮片、中成药和医疗机构中药制剂纳入基本医疗保险基金支付范围。"},{"i":50,"n":"第五十条","txt":"国家加强中医药标准体系建设，根据中医药特点对需要统一的技术要求制定标准并及时修订。"},{"i":51,"n":"第五十一条","txt":"开展法律、行政法规规定的与中医药有关的评审、评估、鉴定活动，应当成立中医药评审、评估、鉴定的专门组织，或者有中医药专家参加。"},{"i":52,"n":"第五十二条","txt":"国家采取措施，加大对少数民族医药传承创新、应用发展和人才培养的扶持力度，加强少数民族医疗机构和医师队伍建设，促进和规范少数民族医药事业发展。"},{"i":53,"n":"第五十三条","txt":"县级以上人民政府中医药主管部门及其他有关部门未履行本法规定的职责的，由本级人民政府或者上级人民政府有关部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，中医诊所超出备案范围开展医疗活动的，由所在地县级人民政府中医药主管部门责令改正，没收违法所得，并处一万元以上三万元以下罚款；情节严重的，责令停止执业活动。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，经考核取得医师资格的中医医师超出注册的执业范围从事医疗活动的，由县级以上人民政府中医药主管部门责令暂停六个月以上一年以下执业活动，并处一万元以上三万元以下罚款；情节严重的，吊销执业证书。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，举办中医诊所、炮制中药饮片、委托配制中药制剂应当备案而未备案，或者备案时提供虚假材料的，由中医药主管部门和药品监督管理部门按照各自职责分工责令改正，没收违法所得，并处三万元以下罚款，向社会公告相关信息；拒不改正的，责令停止执业活动或者责令停止炮制中药饮片、委托配制中药制剂活动，其直接责任人员五年内不得从事中医药相关活动。"},{"i":57,"n":"第五十七条","txt":"违反本法规定，发布的中医医疗广告内容与经审查批准的内容不相符的，由原审查部门撤销该广告的审查批准文件，一年内不受理该医疗机构的广告审查申请。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，在中药材种植过程中使用剧毒、高毒农药的，依照有关法律、法规规定给予处罚；情节严重的，可以由公安机关对其直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留。"},{"i":59,"n":"第五十九条","txt":"违反本法规定，造成人身、财产损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"中医药的管理，本法未作规定的，适用《中华人民共和国执业医师法》、《中华人民共和国药品管理法》等相关法律、行政法规的规定。"},{"i":61,"n":"第六十一条","txt":"民族自治地方可以根据《中华人民共和国民族区域自治法》和本法的有关规定，结合实际，制定促进和规范本地方少数民族医药事业发展的办法。"},{"i":62,"n":"第六十二条","txt":"盲人按照国家有关规定取得盲人医疗按摩人员资格的，可以以个人开业的方式或者在医疗机构内提供医疗按摩服务。"},{"i":63,"n":"第六十三条","txt":"本法自2017年7月1日起施行。"}],"yiwujiaoyufa":[{"i":1,"n":"第一条","txt":"为了保障适龄儿童、少年接受义务教育的权利，保证义务教育的实施，提高全民族素质，根据宪法和教育法，制定本法。"},{"i":2,"n":"第二条","txt":"国家实行九年义务教育制度。"},{"i":3,"n":"第三条","txt":"义务教育必须贯彻国家的教育方针，实施素质教育，提高教育质量，使适龄儿童、少年在品德、智力、体质等方面全面发展，为培养有理想、有道德、有文化、有纪律的社会主义建设者和接班人奠定基础。"},{"i":4,"n":"第四条","txt":"凡具有中华人民共和国国籍的适龄儿童、少年，不分性别、民族、种族、家庭财产状况、宗教信仰等，依法享有平等接受义务教育的权利，并履行接受义务教育的义务。"},{"i":5,"n":"第五条","txt":"各级人民政府及其有关部门应当履行本法规定的各项职责，保障适龄儿童、少年接受义务教育的权利。"},{"i":6,"n":"第六条","txt":"国务院和县级以上地方人民政府应当合理配置教育资源，促进义务教育均衡发展，改善薄弱学校的办学条件，并采取措施，保障农村地区、民族地区实施义务教育，保障家庭经济困难的和残疾的适龄儿童、少年接受义务教育。"},{"i":7,"n":"第七条","txt":"义务教育实行国务院领导，省、自治区、直辖市人民政府统筹规划实施，县级人民政府为主管理的体制。"},{"i":8,"n":"第八条","txt":"人民政府教育督导机构对义务教育工作执行法律法规情况、教育教学质量以及义务教育均衡发展状况等进行督导，督导报告向社会公布。"},{"i":9,"n":"第九条","txt":"任何社会组织或者个人有权对违反本法的行为向有关国家机关提出检举或者控告。"},{"i":10,"n":"第十条","txt":"对在义务教育实施工作中做出突出贡献的社会组织和个人，各级人民政府及其有关部门按照有关规定给予表彰、奖励。"},{"i":11,"n":"第十一条","txt":"凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区的儿童，可以推迟到七周岁。"},{"i":12,"n":"第十二条","txt":"适龄儿童、少年免试入学。地方各级人民政府应当保障适龄儿童、少年在户籍所在地学校就近入学。"},{"i":13,"n":"第十三条","txt":"县级人民政府教育行政部门和乡镇人民政府组织和督促适龄儿童、少年入学，帮助解决适龄儿童、少年接受义务教育的困难，采取措施防止适龄儿童、少年辍学。"},{"i":14,"n":"第十四条","txt":"禁止用人单位招用应当接受义务教育的适龄儿童、少年。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府根据本行政区域内居住的适龄儿童、少年的数量和分布状况等因素，按照国家有关规定，制定、调整学校设置规划。新建居民区需要设置学校的，应当与居民区的建设同步进行。"},{"i":16,"n":"第十六条","txt":"学校建设，应当符合国家规定的办学标准，适应教育教学需要；应当符合国家规定的选址要求和建设标准，确保学生和教职工安全。"},{"i":17,"n":"第十七条","txt":"县级人民政府根据需要设置寄宿制学校，保障居住分散的适龄儿童、少年入学接受义务教育。"},{"i":18,"n":"第十八条","txt":"国务院教育行政部门和省、自治区、直辖市人民政府根据需要，在经济发达地区设置接收少数民族适龄儿童、少年的学校（班）。"},{"i":19,"n":"第十九条","txt":"县级以上地方人民政府根据需要设置相应的实施特殊教育的学校（班），对视力残疾、听力语言残疾和智力残疾的适龄儿童、少年实施义务教育。特殊教育学校（班）应当具备适应残疾儿童、少年学习、康复、生活特点的场所和设施。"},{"i":20,"n":"第二十条","txt":"县级以上地方人民政府根据需要，为具有预防未成年人犯罪法规定的严重不良行为的适龄少年设置专门的学校实施义务教育。"},{"i":21,"n":"第二十一条","txt":"对未完成义务教育的未成年犯和被采取强制性教育措施的未成年人应当进行义务教育，所需经费由人民政府予以保障。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府及其教育行政部门应当促进学校均衡发展，缩小学校之间办学条件的差距，不得将学校分为重点学校和非重点学校。学校不得分设重点班和非重点班。"},{"i":23,"n":"第二十三条","txt":"各级人民政府及其有关部门依法维护学校周边秩序，保护学生、教师、学校的合法权益，为学校提供安全保障。"},{"i":24,"n":"第二十四条","txt":"学校应当建立、健全安全制度和应急机制，对学生进行安全教育，加强管理，及时消除隐患，预防发生事故。"},{"i":25,"n":"第二十五条","txt":"学校不得违反国家规定收取费用，不得以向学生推销或者变相推销商品、服务等方式谋取利益。"},{"i":26,"n":"第二十六条","txt":"学校实行校长负责制。校长应当符合国家规定的任职条件。校长由县级人民政府教育行政部门依法聘任。"},{"i":27,"n":"第二十七条","txt":"对违反学校管理制度的学生，学校应当予以批评教育，不得开除。"},{"i":28,"n":"第二十八条","txt":"教师享有法律规定的权利，履行法律规定的义务，应当为人师表，忠诚于人民的教育事业。"},{"i":29,"n":"第二十九条","txt":"教师在教育教学中应当平等对待学生，关注学生的个体差异，因材施教，促进学生的充分发展。"},{"i":30,"n":"第三十条","txt":"教师应当取得国家规定的教师资格。"},{"i":31,"n":"第三十一条","txt":"各级人民政府保障教师工资福利和社会保险待遇，改善教师工作和生活条件；完善农村教师工资经费保障机制。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府应当加强教师培养工作，采取措施发展教师教育。"},{"i":33,"n":"第三十三条","txt":"国务院和地方各级人民政府鼓励和支持城市学校教师和高等学校毕业生到农村地区、民族地区从事义务教育工作。"},{"i":34,"n":"第三十四条","txt":"教育教学工作应当符合教育规律和学生身心发展特点，面向全体学生，教书育人，将德育、智育、体育、美育等有机统一在教育教学活动中，注重培养学生独立思考能力、创新能力和实践能力，促进学生全面发展。"},{"i":35,"n":"第三十五条","txt":"国务院教育行政部门根据适龄儿童、少年身心发展的状况和实际情况，确定教学制度、教育教学内容和课程设置，改革考试制度，并改进高级中等学校招生办法，推进实施素质教育。"},{"i":36,"n":"第三十六条","txt":"学校应当把德育放在首位，寓德育于教育教学之中，开展与学生年龄相适应的社会实践活动，形成学校、家庭、社会相互配合的思想道德教育体系，促进学生养成良好的思想品德和行为习惯。"},{"i":37,"n":"第三十七条","txt":"学校应当保证学生的课外活动时间，组织开展文化娱乐等课外活动。社会公共文化体育设施应当为学校开展课外活动提供便利。"},{"i":38,"n":"第三十八条","txt":"教科书根据国家教育方针和课程标准编写，内容力求精简，精选必备的基础知识、基本技能，经济实用，保证质量。"},{"i":39,"n":"第三十九条","txt":"国家实行教科书审定制度。教科书的审定办法由国务院教育行政部门规定。"},{"i":40,"n":"第四十条","txt":"教科书价格由省、自治区、直辖市人民政府价格行政部门会同同级出版主管部门按照微利原则确定。"},{"i":41,"n":"第四十一条","txt":"国家鼓励教科书循环使用。"},{"i":42,"n":"第四十二条","txt":"国家将义务教育全面纳入财政保障范围，义务教育经费由国务院和地方各级人民政府依照本法规定予以保障。"},{"i":43,"n":"第四十三条","txt":"学校的学生人均公用经费基本标准由国务院财政部门会同教育行政部门制定，并根据经济和社会发展状况适时调整。制定、调整学生人均公用经费基本标准，应当满足教育教学基本需要。"},{"i":44,"n":"第四十四条","txt":"义务教育经费投入实行国务院和地方各级人民政府根据职责共同负担，省、自治区、直辖市人民政府负责统筹落实的体制。农村义务教育所需经费，由各级人民政府根据国务院的规定分项目、按比例分担。"},{"i":45,"n":"第四十五条","txt":"地方各级人民政府在财政预算中将义务教育经费单列。"},{"i":46,"n":"第四十六条","txt":"国务院和省、自治区、直辖市人民政府规范财政转移支付制度，加大一般性转移支付规模和规范义务教育专项转移支付，支持和引导地方各级人民政府增加对义务教育的投入。地方各级人民政府确保将上级人民政府的义务教育转移支付资金按照规定用于义务教育。"},{"i":47,"n":"第四十七条","txt":"国务院和县级以上地方人民政府根据实际需要，设立专项资金，扶持农村地区、民族地区实施义务教育。"},{"i":48,"n":"第四十八条","txt":"国家鼓励社会组织和个人向义务教育捐赠，鼓励按照国家有关基金会管理的规定设立义务教育基金。"},{"i":49,"n":"第四十九条","txt":"义务教育经费严格按照预算规定用于义务教育；任何组织和个人不得侵占、挪用义务教育经费，不得向学校非法收取或者摊派费用。"},{"i":50,"n":"第五十条","txt":"县级以上人民政府建立健全义务教育经费的审计监督和统计公告制度。"},{"i":51,"n":"第五十一条","txt":"国务院有关部门和地方各级人民政府违反本法第六章的规定，未履行对义务教育经费保障职责的，由国务院或者上级地方人民政府责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":52,"n":"第五十二条","txt":"县级以上地方人民政府有下列情形之一的，由上级人民政府责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分："},{"i":53,"n":"第五十三条","txt":"县级以上人民政府或者其教育行政部门有下列情形之一的，由上级人民政府或者其教育行政部门责令限期改正、通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分："},{"i":54,"n":"第五十四条","txt":"有下列情形之一的，由上级人民政府或者上级人民政府教育行政部门、财政部门、价格行政部门和审计机关根据职责分工责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":55,"n":"第五十五条","txt":"学校或者教师在义务教育工作中违反教育法、教师法规定的，依照教育法、教师法的有关规定处罚。"},{"i":56,"n":"第五十六条","txt":"学校违反国家规定收取费用的，由县级人民政府教育行政部门责令退还所收费用；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":57,"n":"第五十七条","txt":"学校有下列情形之一的，由县级人民政府教育行政部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":58,"n":"第五十八条","txt":"适龄儿童、少年的父母或者其他法定监护人无正当理由未依照本法规定送适龄儿童、少年入学接受义务教育的，由当地乡镇人民政府或者县级人民政府教育行政部门给予批评教育，责令限期改正。"},{"i":59,"n":"第五十九条","txt":"有下列情形之一的，依照有关法律、行政法规的规定予以处罚："},{"i":60,"n":"第六十条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"对接受义务教育的适龄儿童、少年不收杂费的实施步骤，由国务院规定。"},{"i":62,"n":"第六十二条","txt":"社会组织或者个人依法举办的民办学校实施义务教育的，依照民办教育促进法有关规定执行；民办教育促进法未作规定的，适用本法。"},{"i":63,"n":"第六十三条","txt":"本法自2006年9月1日起施行。"}],"renkouyujihuashengyufa":[{"i":1,"n":"第一条","txt":"为了实现人口与经济、社会、资源、环境的协调发展，推行计划生育，维护公民的合法权益，促进家庭幸福、民族繁荣与社会进步，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"我国是人口众多的国家，实行计划生育是国家的基本国策。"},{"i":3,"n":"第三条","txt":"开展人口与计划生育工作，应当与增加妇女受教育和就业机会、增进妇女健康、提高妇女地位相结合。"},{"i":4,"n":"第四条","txt":"各级人民政府及其工作人员在推行计划生育工作中应当严格依法行政，文明执法，不得侵犯公民的合法权益。"},{"i":5,"n":"第五条","txt":"国务院领导全国的人口与计划生育工作。"},{"i":6,"n":"第六条","txt":"国务院卫生健康主管部门负责全国计划生育工作和与计划生育有关的人口工作。"},{"i":7,"n":"第七条","txt":"工会、共产主义青年团、妇女联合会及计划生育协会等社会团体、企业事业组织和公民应当协助人民政府开展人口与计划生育工作。"},{"i":8,"n":"第八条","txt":"国家对在人口与计划生育工作中作出显著成绩的组织和个人，给予奖励。"},{"i":9,"n":"第九条","txt":"国务院编制人口发展规划，并将其纳入国民经济和社会发展计划。"},{"i":10,"n":"第十条","txt":"县级以上各级人民政府根据人口发展规划，制定人口与计划生育实施方案并组织实施。"},{"i":11,"n":"第十一条","txt":"人口与计划生育实施方案应当规定调控人口数量，提高人口素质，推动实现适度生育水平，优化人口结构，加强母婴保健和婴幼儿照护服务，促进家庭发展的措施。"},{"i":12,"n":"第十二条","txt":"村民委员会、居民委员会应当依法做好计划生育工作。"},{"i":13,"n":"第十三条","txt":"卫生健康、教育、科技、文化、民政、新闻出版、广播电视等部门应当组织开展人口与计划生育宣传教育。"},{"i":14,"n":"第十四条","txt":"流动人口的计划生育工作由其户籍所在地和现居住地的人民政府共同负责管理，以现居住地为主。"},{"i":15,"n":"第十五条","txt":"国家根据国民经济和社会发展状况逐步提高人口与计划生育经费投入的总体水平。各级人民政府应当保障人口与计划生育工作必要的经费。"},{"i":16,"n":"第十六条","txt":"国家鼓励开展人口与计划生育领域的科学研究和对外交流与合作。"},{"i":17,"n":"第十七条","txt":"公民有生育的权利，也有依法实行计划生育的义务，夫妻双方在实行计划生育中负有共同的责任。"},{"i":18,"n":"第十八条","txt":"国家提倡适龄婚育、优生优育。一对夫妻可以生育三个子女。"},{"i":19,"n":"第十九条","txt":"国家创造条件，保障公民知情选择安全、有效、适宜的避孕节育措施。实施避孕节育手术，应当保证受术者的安全。"},{"i":20,"n":"第二十条","txt":"育龄夫妻自主选择计划生育避孕节育措施，预防和减少非意愿妊娠。"},{"i":21,"n":"第二十一条","txt":"实行计划生育的育龄夫妻免费享受国家规定的基本项目的计划生育技术服务。"},{"i":22,"n":"第二十二条","txt":"禁止歧视、虐待生育女婴的妇女和不育的妇女。"},{"i":23,"n":"第二十三条","txt":"国家对实行计划生育的夫妻，按照规定给予奖励。"},{"i":24,"n":"第二十四条","txt":"国家建立、健全基本养老保险、基本医疗保险、生育保险和社会福利等社会保障制度，促进计划生育。"},{"i":25,"n":"第二十五条","txt":"符合法律、法规规定生育子女的夫妻，可以获得延长生育假的奖励或者其他福利待遇。"},{"i":26,"n":"第二十六条","txt":"妇女怀孕、生育和哺乳期间，按照国家有关规定享受特殊劳动保护并可以获得帮助和补偿。国家保障妇女就业合法权益，为因生育影响就业的妇女提供就业服务。"},{"i":27,"n":"第二十七条","txt":"国家采取财政、税收、保险、教育、住房、就业等支持措施，减轻家庭生育、养育、教育负担。"},{"i":28,"n":"第二十八条","txt":"县级以上各级人民政府综合采取规划、土地、住房、财政、金融、人才等措施，推动建立普惠托育服务体系，提高婴幼儿家庭获得服务的可及性和公平性。"},{"i":29,"n":"第二十九条","txt":"县级以上地方各级人民政府应当在城乡社区建设改造中，建设与常住人口规模相适应的婴幼儿活动场所及配套服务设施。"},{"i":30,"n":"第三十条","txt":"县级以上各级人民政府应当加强对家庭婴幼儿照护的支持和指导，增强家庭的科学育儿能力。"},{"i":31,"n":"第三十一条","txt":"在国家提倡一对夫妻生育一个子女期间，自愿终身只生育一个子女的夫妻，国家发给《独生子女父母光荣证》。"},{"i":32,"n":"第三十二条","txt":"获得《独生子女父母光荣证》的夫妻，独生子女发生意外伤残、死亡的，按照规定获得扶助。县级以上各级人民政府建立、健全对上述人群的生活、养老、医疗、精神慰藉等全方位帮扶保障制度。"},{"i":33,"n":"第三十三条","txt":"地方各级人民政府对农村实行计划生育的家庭发展经济，给予资金、技术、培训等方面的支持、优惠；对实行计划生育的贫困家庭，在扶贫贷款、以工代赈、扶贫项目和社会救济等方面给予优先照顾。"},{"i":34,"n":"第三十四条","txt":"本章规定的奖励和社会保障措施，省、自治区、直辖市和设区的市、自治州的人民代表大会及其常务委员会或者人民政府可以依据本法和有关法律、行政法规的规定，结合当地实际情况，制定具体实施办法。"},{"i":35,"n":"第三十五条","txt":"国家建立婚前保健、孕产期保健制度，防止或者减少出生缺陷，提高出生婴儿健康水平。"},{"i":36,"n":"第三十六条","txt":"各级人民政府应当采取措施，保障公民享有计划生育服务，提高公民的生殖健康水平。"},{"i":37,"n":"第三十七条","txt":"医疗卫生机构应当针对育龄人群开展优生优育知识宣传教育，对育龄妇女开展围孕期、孕产期保健服务，承担计划生育、优生优育、生殖保健的咨询、指导和技术服务，规范开展不孕不育症诊疗。"},{"i":38,"n":"第三十八条","txt":"计划生育技术服务人员应当指导实行计划生育的公民选择安全、有效、适宜的避孕措施。"},{"i":39,"n":"第三十九条","txt":"严禁利用超声技术和其他技术手段进行非医学需要的胎儿性别鉴定；严禁非医学需要的选择性别的人工终止妊娠。"},{"i":40,"n":"第四十条","txt":"违反本法规定，有下列行为之一的，由卫生健康主管部门责令改正，给予警告，没收违法所得；违法所得一万元以上的，处违法所得二倍以上六倍以下的罚款；没有违法所得或者违法所得不足一万元的，处一万元以上三万元以下的罚款；情节严重的，由原发证机关吊销执业证书；构成犯罪的，依法追究刑事责任："},{"i":41,"n":"第四十一条","txt":"托育机构违反托育服务相关标准和规范的，由卫生健康主管部门责令改正，给予警告；拒不改正的，处五千元以上五万元以下的罚款；情节严重的，责令停止托育服务，并处五万元以上十万元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"计划生育技术服务人员违章操作或者延误抢救、诊治，造成严重后果的，依照有关法律、行政法规的规定承担相应的法律责任。"},{"i":43,"n":"第四十三条","txt":"国家机关工作人员在计划生育工作中，有下列行为之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分；有违法所得的，没收违法所得："},{"i":44,"n":"第四十四条","txt":"违反本法规定，不履行协助计划生育管理义务的，由有关地方人民政府责令改正，并给予通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":45,"n":"第四十五条","txt":"拒绝、阻碍卫生健康主管部门及其工作人员依法执行公务的，由卫生健康主管部门给予批评教育并予以制止；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"公民、法人或者其他组织认为行政机关在实施计划生育管理过程中侵犯其合法权益，可以依法申请行政复议或者提起行政诉讼。"},{"i":47,"n":"第四十七条","txt":"中国人民解放军和中国人民武装警察部队执行本法的具体办法，由中央军事委员会依据本法制定。"},{"i":48,"n":"第四十八条","txt":"本法自2002年9月1日起施行。"}],"renminwuzhuangjingchafa":[{"i":1,"n":"第一条","txt":"为了规范和保障人民武装警察部队履行职责，建设强大的现代化人民武装警察部队，维护国家安全和社会稳定，保护公民、法人和其他组织的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"人民武装警察部队是中华人民共和国武装力量的重要组成部分，由党中央、中央军事委员会集中统一领导。"},{"i":3,"n":"第三条","txt":"人民武装警察部队坚持中国共产党的绝对领导，贯彻习近平强军思想，贯彻新时代军事战略方针，按照多能一体、维稳维权的战略要求，加强练兵备战、坚持依法从严、加快建设发展，有效履行职责。"},{"i":4,"n":"第四条","txt":"人民武装警察部队担负执勤、处置突发社会安全事件、防范和处置恐怖活动、海上维权执法、抢险救援和防卫作战以及中央军事委员会赋予的其他任务。"},{"i":5,"n":"第五条","txt":"人民武装警察部队应当遵守宪法和法律，忠于职守，依照本法和其他法律的有关规定履行职责。"},{"i":6,"n":"第六条","txt":"对在执行任务中做出突出贡献的人民武装警察，依照有关法律和中央军事委员会的规定给予表彰和奖励。"},{"i":7,"n":"第七条","txt":"人民武装警察部队实行衔级制度，衔级制度的具体内容由法律另行规定。"},{"i":8,"n":"第八条","txt":"人民武装警察享有法律、法规规定的现役军人的权益。"},{"i":9,"n":"第九条","txt":"人民武装警察部队由内卫部队、机动部队、海警部队和院校、研究机构等组成。"},{"i":10,"n":"第十条","txt":"人民武装警察部队平时执行任务，由中央军事委员会或者中央军事委员会授权人民武装警察部队组织指挥。"},{"i":11,"n":"第十一条","txt":"中央国家机关、县级以上地方人民政府应当与人民武装警察部队建立任务需求和工作协调机制。"},{"i":12,"n":"第十二条","txt":"调动人民武装警察部队执行任务，坚持依法用兵、严格审批的原则，按照指挥关系、职责权限和运行机制组织实施。批准权限和程序由中央军事委员会规定。"},{"i":13,"n":"第十三条","txt":"人民武装警察部队根据执行任务需要，参加中央国家机关、县级以上地方人民政府设立的指挥机构，在指挥机构领导下，依照中央军事委员会有关规定实施组织指挥。"},{"i":14,"n":"第十四条","txt":"中央国家机关、县级以上地方人民政府对人民武装警察部队执勤、处置突发社会安全事件、防范和处置恐怖活动、抢险救援工作进行业务指导。"},{"i":15,"n":"第十五条","txt":"人民武装警察部队主要担负下列执勤任务："},{"i":16,"n":"第十六条","txt":"人民武装警察部队参与处置动乱、暴乱、骚乱、非法聚集事件、群体性事件等突发事件，主要担负下列任务："},{"i":17,"n":"第十七条","txt":"人民武装警察部队参与防范和处置恐怖活动，主要担负下列任务："},{"i":18,"n":"第十八条","txt":"人民武装警察部队参与自然灾害、事故灾难、公共卫生事件等突发事件的抢险救援，主要担负下列任务："},{"i":19,"n":"第十九条","txt":"人民武装警察执行任务时，可以依法采取下列措施："},{"i":20,"n":"第二十条","txt":"人民武装警察执行任务时，发现有下列情形的人员，经现场指挥员同意，应当及时予以控制并移交公安机关、国家安全机关或者其他有管辖权的机关处理："},{"i":21,"n":"第二十一条","txt":"人民武装警察部队协助公安机关、国家安全机关和监狱等执行逮捕、追捕任务，根据所协助机关的决定，协助搜查犯罪嫌疑人、被告人、罪犯的人身和住所以及涉嫌藏匿犯罪嫌疑人、被告人、罪犯或者违法物品的场所、交通工具等。"},{"i":22,"n":"第二十二条","txt":"人民武装警察执行执勤、处置突发社会安全事件、防范和处置恐怖活动任务使用警械和武器，依照人民警察使用警械和武器的规定以及其他有关法律、法规的规定执行。"},{"i":23,"n":"第二十三条","txt":"人民武装警察执行任务，遇有妨碍、干扰的，可以采取必要措施排除阻碍、强制实施。"},{"i":24,"n":"第二十四条","txt":"人民武装警察因执行任务的紧急需要，经出示人民武装警察证件，可以优先乘坐公共交通工具；遇交通阻碍时，优先通行。"},{"i":25,"n":"第二十五条","txt":"人民武装警察因执行任务的需要，在紧急情况下，经现场指挥员出示人民武装警察证件，可以优先使用或者依法征用个人和组织的设备、设施、场地、建筑物、交通工具以及其他物资、器材，任务完成后应当及时归还或者恢复原状，并按照国家有关规定支付费用；造成损失的，按照国家有关规定给予补偿。"},{"i":26,"n":"第二十六条","txt":"人民武装警察部队出境执行防范和处置恐怖活动等任务，依照有关法律、法规和中央军事委员会的规定执行。"},{"i":27,"n":"第二十七条","txt":"人民武装警察应当服从命令、听从指挥，依法履职尽责，坚决完成任务。"},{"i":28,"n":"第二十八条","txt":"人民武装警察遇有公民的人身财产安全受到侵犯或者处于其他危难情形，应当及时救助。"},{"i":29,"n":"第二十九条","txt":"人民武装警察不得有下列行为："},{"i":30,"n":"第三十条","txt":"人民武装警察执行任务，应当按照规定着装，持有人民武装警察证件，按照规定使用摄录器材录像取证、出示证件。"},{"i":31,"n":"第三十一条","txt":"人民武装警察应当举止文明，礼貌待人，遵守社会公德，尊重公民的宗教信仰和民族风俗习惯。"},{"i":32,"n":"第三十二条","txt":"为了保障人民武装警察部队执行任务，中央国家机关、县级以上地方人民政府及其有关部门应当依据职责及时向人民武装警察部队通报下列情报信息："},{"i":33,"n":"第三十三条","txt":"国家建立与经济社会发展相适应、与人民武装警察部队担负任务和建设发展相协调的经费保障机制。所需经费按照国家有关规定列入预算。"},{"i":34,"n":"第三十四条","txt":"执勤目标单位及其上级主管部门应当按照国家有关规定，为担负执勤任务的人民武装警察部队提供执勤设施、生活设施等必要的保障。"},{"i":35,"n":"第三十五条","txt":"在有毒、粉尘、辐射、噪声等严重污染或者高温、低温、缺氧以及其他恶劣环境下的执勤目标单位执行任务的人民武装警察，享有与执勤目标单位工作人员同等的保护条件和福利补助，由执勤目标单位或者其上级主管部门给予保障。"},{"i":36,"n":"第三十六条","txt":"人民武装警察部队的专用标志、制式服装、警械装备、证件、印章，按照中央军事委员会有关规定监制和配备。"},{"i":37,"n":"第三十七条","txt":"人民武装警察部队应当根据执行任务的需要，加强对所属人民武装警察的教育和训练，提高依法执行任务的能力。"},{"i":38,"n":"第三十八条","txt":"人民武装警察因执行任务牺牲、伤残的，按照国家有关军人抚恤优待的规定给予抚恤优待。"},{"i":39,"n":"第三十九条","txt":"人民武装警察部队依法执行任务，公民、法人和其他组织应当给予必要的支持和协助。"},{"i":40,"n":"第四十条","txt":"人民武装警察部队应当对所属单位和人员执行法律、法规和遵守纪律的情况进行监督检查。"},{"i":41,"n":"第四十一条","txt":"人民武装警察受中央军事委员会监察委员会、人民武装警察部队各级监察委员会的监督。"},{"i":42,"n":"第四十二条","txt":"中央军事委员会监察委员会、人民武装警察部队各级监察委员会接到公民、法人和其他组织的检举、控告，或者接到县级以上人民政府及其有关部门对人民武装警察违法违纪行为的情况通报后，应当依法及时查处，按照有关规定将处理结果反馈检举人、控告人或者通报县级以上人民政府及其有关部门。"},{"i":43,"n":"第四十三条","txt":"人民武装警察在执行任务中不履行职责，或者有本法第二十九条所列行为之一的，按照中央军事委员会的有关规定给予处分。"},{"i":44,"n":"第四十四条","txt":"妨碍人民武装警察依法执行任务，有下列行为之一的，由公安机关依法给予治安管理处罚："},{"i":45,"n":"第四十五条","txt":"非法制造、买卖、持有、使用人民武装警察部队专用标志、警械装备、证件、印章的，由公安机关处十五日以下拘留或者警告，可以并处违法所得一倍以上五倍以下的罚款。"},{"i":46,"n":"第四十六条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"人民武装警察部队执行海上维权执法任务，由法律另行规定。"},{"i":48,"n":"第四十八条","txt":"人民武装警察部队执行防卫作战任务，依照中央军事委员会的命令执行。"},{"i":49,"n":"第四十九条","txt":"人民武装警察部队执行戒严任务，依照《中华人民共和国戒严法》的有关规定执行。"},{"i":50,"n":"第五十条","txt":"人民武装警察部队文职人员在执行本法规定的任务时，依法履行人民武装警察的有关职责和义务，享有相应权益。"},{"i":51,"n":"第五十一条","txt":"本法自2020年6月21日起施行。"}],"renminjingchafa":[{"i":1,"n":"第一条","txt":"为了维护国家安全和社会治安秩序，保护公民的合法权益，加强人民警察的队伍建设，从严治警，提高人民警察的素质，保障人民警察依法行使职权，保障改革开放和社会主义现代化建设的顺利进行，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"人民警察的任务是维护国家安全，维护社会治安秩序，保护公民的人身安全、人身自由和合法财产，保护公共财产，预防、制止和惩治违法犯罪活动。"},{"i":3,"n":"第三条","txt":"人民警察必须依靠人民的支持，保持同人民的密切联系，倾听人民的意见和建议，接受人民的监督，维护人民的利益，全心全意为人民服务。"},{"i":4,"n":"第四条","txt":"人民警察必须以宪法和法律为活动准则，忠于职守，清正廉洁，纪律严明，服从命令，严格执法。"},{"i":5,"n":"第五条","txt":"人民警察依法执行职务，受法律保护。"},{"i":6,"n":"第六条","txt":"公安机关的人民警察按照职责分工，依法履行下列职责："},{"i":7,"n":"第七条","txt":"公安机关的人民警察对违反治安管理或者其他公安行政管理法律、法规的个人或者组织，依法可以实施行政强制措施、行政处罚。"},{"i":8,"n":"第八条","txt":"公安机关的人民警察对严重危害社会治安秩序或者威胁公共安全的人员，可以强行带离现场、依法予以拘留或者采取法律规定的其他措施。"},{"i":9,"n":"第九条","txt":"为维护社会治安秩序，公安机关的人民警察对有违法犯罪嫌疑的人员，经出示相应证件，可以当场盘问、检查；经盘问、检查，有下列情形之一的，可以将其带至公安机关，经该公安机关批准，对其继续盘问："},{"i":10,"n":"第十条","txt":"遇有拒捕、暴乱、越狱、抢夺枪支或者其他暴力行为的紧急情况，公安机关的人民警察依照国家有关规定可以使用武器。"},{"i":11,"n":"第十一条","txt":"为制止严重违法犯罪活动的需要，公安机关的人民警察依照国家有关规定可以使用警械。"},{"i":12,"n":"第十二条","txt":"为侦查犯罪活动的需要，公安机关的人民警察可以依法执行拘留、搜查、逮捕或者其他强制措施。"},{"i":13,"n":"第十三条","txt":"公安机关的人民警察因履行职责的紧急需要、经出示相应证件，可以优先乘坐公共交通工具，遇交通阻碍时，优先通行。"},{"i":14,"n":"第十四条","txt":"公安机关的人民警察对严重危害公共安全或者他人人身安全的精神病人，可以采取保护性约束措施。需要送往指定的单位、场所加以监护的，应当报请县级以上人民政府公安机关批准，并及时通知其监护人。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府公安机关，为预防和制止严重危害社会治安秩序的行为，可以在一定的区域和时间，限制人员、车辆的通行或者停留，必要时可以实行交通管制。"},{"i":16,"n":"第十六条","txt":"公安机关因侦查犯罪的需要，根据国家有关规定，经过严格的批准手续，可以采取技术侦察措施。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府公安机关，经上级公安机关和同级人民政府批准，对严重危害社会治安秩序的突发事件，可以根据情况实行现场管制。"},{"i":18,"n":"第十八条","txt":"国家安全机关、监狱、劳动教养管理机关的人民警察和人民法院、人民检察院的司法警察，分别依照有关法律、行政法规的规定履行职权。"},{"i":19,"n":"第十九条","txt":"人民警察在非工作时间，遇有其职责范围内的紧急情况，应当履行职责。"},{"i":20,"n":"第二十条","txt":"人民警察必须做到："},{"i":21,"n":"第二十一条","txt":"人民警察遇到公民人身、财产安全受到侵犯或者处于其他危难情形，应当立即救助；对公民提出解决纠纷的要求，应当给予帮助；对公民的报警案件，应当及时查处。"},{"i":22,"n":"第二十二条","txt":"人民警察不得有下列行为："},{"i":23,"n":"第二十三条","txt":"人民警察必须按照规定着装，佩带人民警察标志或者持有人民警察证件，保持警容严整，举止端庄。"},{"i":24,"n":"第二十四条","txt":"国家根据人民警察的工作性质、任务和特点，规定组织机构设置和职务序列。"},{"i":25,"n":"第二十五条","txt":"人民警察依法实行警衔制度。"},{"i":26,"n":"第二十六条","txt":"担任人民警察应当具备下列条件："},{"i":27,"n":"第二十七条","txt":"录用人民警察，必须按照国家规定，公开考试，严格考核，择优选用。"},{"i":28,"n":"第二十八条","txt":"担任人民警察领导职务的人员，应当具备下列条件："},{"i":29,"n":"第二十九条","txt":"国家发展人民警察教育事业，对人民警察有计划地进行政治思想、法制、警察业务等教育培训。"},{"i":30,"n":"第三十条","txt":"国家根据人民警察的工作性质、任务和特点，分别规定不同岗位的服务年限和不同职务的最高任职年龄。"},{"i":31,"n":"第三十一条","txt":"人民警察个人或者集体在工作中表现突出，有显著成绩和特殊贡献的，给予奖励。奖励分为：嘉奖、三等功、二等功、一等功、授予荣誉称号。"},{"i":32,"n":"第三十二条","txt":"人民警察必须执行上级的决定和命令。"},{"i":33,"n":"第三十三条","txt":"人民警察对超越法律、法规规定的人民警察职责范围的指令，有权拒绝执行，并同时向上级机关报告。"},{"i":34,"n":"第三十四条","txt":"人民警察依法执行职务，公民和组织应当给予支持和协助。公民和组织协助人民警察依法执行职务的行为受法律保护。对协助人民警察执行职务有显著成绩的，给予表彰和奖励。"},{"i":35,"n":"第三十五条","txt":"拒绝或者阻碍人民警察依法执行职务，有下列行为之一的，给予治安管理处罚："},{"i":36,"n":"第三十六条","txt":"人民警察的警用标志、制式服装和警械，由国务院公安部门统一监制，会同其他有关国家机关管理，其他个人和组织不得非法制造、贩卖。"},{"i":37,"n":"第三十七条","txt":"国家保障人民警察的经费。人民警察的经费，按照事权划分的原则，分别列入中央和地方的财政预算。"},{"i":38,"n":"第三十八条","txt":"人民警察工作所必需的通讯、训练设施和交通、消防以及派出所、监管场所等基础设施建设，各级人民政府应当列入基本建设规划和城乡建设总体规划。"},{"i":39,"n":"第三十九条","txt":"国家加强人民警察装备的现代化建设，努力推广、应用先进的科技成果。"},{"i":40,"n":"第四十条","txt":"人民警察实行国家公务员的工资制度，并享受国家规定的警衔津贴和其他津贴、补贴以及保险福利待遇。"},{"i":41,"n":"第四十一条","txt":"人民警察因公致残的，与因公致残的现役军人享受国家同样的抚恤和优待。"},{"i":42,"n":"第四十二条","txt":"人民警察执行职务，依法接受人民检察院和行政监察机关的监督。"},{"i":43,"n":"第四十三条","txt":"人民警察的上级机关对下级机关的执法活动进行监督，发现其作出的处理或者决定有错误的，应当予以撤销或者变更。"},{"i":44,"n":"第四十四条","txt":"人民警察执行职务，必须自觉地接受社会和公民的监督。人民警察机关作出的与公众利益直接有关的规定，应当向公众公布。"},{"i":45,"n":"第四十五条","txt":"人民警察在办理治安案件过程中，遇有下列情形之一的，应当回避，当事人或者其法定代理人也有权要求他们回避："},{"i":46,"n":"第四十六条","txt":"公民或者组织对人民警察的违法、违纪行为，有权向人民警察机关或者人民检察院、行政监察机关检举、控告。受理检举、控告的机关应当及时查处，并将查处结果告知检举人、控告人。"},{"i":47,"n":"第四十七条","txt":"公安机关建立督察制度，对公安机关的人民警察执行法律、法规、遵守纪律的情况进行监督。"},{"i":48,"n":"第四十八条","txt":"人民警察有本法第二十二条所列行为之一的，应当给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"人民警察违反规定使用武器、警械，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，应当依法给予行政处分。"},{"i":50,"n":"第五十条","txt":"人民警察在执行职务中，侵犯公民或者组织的合法权益造成损害的，应当依照《中华人民共和国国家赔偿法》和其他有关法律、法规的规定给予赔偿。"},{"i":51,"n":"第五十一条","txt":"中国人民武装警察部队执行国家赋予的安全保卫任务。"},{"i":52,"n":"第五十二条","txt":"本法自公布之日起施行。1957年6月25日公布的《中华人民共和国人民警察条例》同时废止。"}],"renminjingchajingxiantiaoli":[{"i":1,"n":"第一条","txt":"为了加强人民警察队伍的革命化、现代化、正规化建设，增强人民警察的责任心、荣誉感和组织纪律性，有利于人民警察的指挥、管理和执行职务，根据宪法，制定本条例。"},{"i":2,"n":"第二条","txt":"人民警察实行警衔制度。"},{"i":3,"n":"第三条","txt":"警衔是区分人民警察等级、表明人民警察身份的称号、标志和国家给予人民警察的荣誉。"},{"i":4,"n":"第四条","txt":"人民警察实行警察职务等级编制警衔。"},{"i":5,"n":"第五条","txt":"警衔高的人民警察对警衔低的人民警察，警衔高的为上级。当警衔高的人民警察在职务上隶属于警衔低的人民警察时，职务高的为上级。"},{"i":6,"n":"第六条","txt":"公安部主管人民警察警衔工作。"},{"i":7,"n":"第七条","txt":"人民警察警衔设下列五等十三级："},{"i":8,"n":"第八条","txt":"担任行政职务的人民警察实行下列职务等级编制警衔："},{"i":9,"n":"第九条","txt":"担任专业技术职务的人民警察实行下列职务等级编制警衔："},{"i":10,"n":"第十条","txt":"人民警察警衔按照人民警察职务等级编制警衔授予。"},{"i":11,"n":"第十一条","txt":"授予人民警察警衔，以人民警察现任职务、德才表现、担任现职时间和工作年限为依据。"},{"i":12,"n":"第十二条","txt":"从学校毕业和从社会上招考录用担任人民警察的，或者从其他部门调任人民警察的，根据确定的职务，授予相应的警衔。"},{"i":13,"n":"第十三条","txt":"首次授予人民警察警衔，按照下列规定的权限予以批准："},{"i":14,"n":"第十四条","txt":"二级警督以下的人民警察，在其职务等级编制警衔幅度内，根据本条规定的期限和条件晋级。"},{"i":15,"n":"第十五条","txt":"一级警督以上的人民警察的警衔晋级，在职务等级编制警衔幅度内，根据其德才表现和工作实绩实行选升。"},{"i":16,"n":"第十六条","txt":"人民警察由于职务提升，其警衔低于新任职务等级编制警衔的最低警衔的，应当晋升至新任职务等级编制警衔的最低警衔。"},{"i":17,"n":"第十七条","txt":"警司晋升警督，警督晋升警监，经相应的人民警察院校培训合格后，方可晋升。"},{"i":18,"n":"第十八条","txt":"人民警察警衔晋级的批准权限适用第十三条批准权限的规定。警司、警员提前晋升的，由公安部政治部主任批准。"},{"i":19,"n":"第十九条","txt":"人民警察离休、退休的，其警衔予以保留，但不得佩带标志。"},{"i":20,"n":"第二十条","txt":"人民警察因不胜任现任职务被调任下级职务，其警衔高于新任职务等级编制警衔的最高警衔的，应当调整至新任职务等级编制警衔的最高警衔。调整警衔的批准权限与原警衔的批准权限相同。"},{"i":21,"n":"第二十一条","txt":"人民警察违犯警纪的，可以给予警衔降级的处分。警衔降级的批准权限与原警衔的批准权限相同。人民警察受警衔降级处分后，其警衔晋级的期限按照降级后的警衔等级重新计算。"},{"i":22,"n":"第二十二条","txt":"人民警察被开除公职的，其警衔相应取消。"},{"i":23,"n":"第二十三条","txt":"国家安全部门、劳动改造劳动教养管理部门的人民警察，人民法院、人民检察院的司法警察的警衔工作适用本条例。"},{"i":24,"n":"第二十四条","txt":"人民警察警衔标志的式样和佩带办法，由国务院制定。"},{"i":25,"n":"第二十五条","txt":"本条例的实施办法由国务院制定。"},{"i":26,"n":"第二十六条","txt":"本条例自公布之日起施行。"}],"renminfangkongfa":[{"i":1,"n":"第一条","txt":"为了有效地组织人民防空，保护人民的生命和财产安全，保障社会主义现代化建设的顺利进行，制定本法。"},{"i":2,"n":"第二条","txt":"人民防空是国防的组成部分。国家根据国防需要，动员和组织群众采取防护措施，防范和减轻空袭危害。"},{"i":3,"n":"第三条","txt":"县级以上人民政府应当将人民防空建设纳入国民经济和社会发展计划。"},{"i":4,"n":"第四条","txt":"人民防空经费由国家和社会共同负担。"},{"i":5,"n":"第五条","txt":"国家对人民防空设施建设按照有关规定给予优惠。"},{"i":6,"n":"第六条","txt":"国务院、中央军事委员会领导全国的人民防空工作。"},{"i":7,"n":"第七条","txt":"国家人民防空主管部门管理全国的人民防空工作。"},{"i":8,"n":"第八条","txt":"一切组织和个人都有得到人民防空保护的权利，都必须依法履行人民防空的义务。"},{"i":9,"n":"第九条","txt":"国家保护人民防空设施不受侵害。禁止任何组织或者个人破坏、侵占人民防空设施。"},{"i":10,"n":"第十条","txt":"县级以上人民政府和军事机关对在人民防空工作中做出显著成绩的组织或者个人，给予奖励。"},{"i":11,"n":"第十一条","txt":"城市是人民防空的重点。国家对城市实行分类防护。"},{"i":12,"n":"第十二条","txt":"城市人民政府应当制定防空袭方案及实施计划，必要时可以组织演习。"},{"i":13,"n":"第十三条","txt":"城市人民政府应当制定人民防空工程建设规划，并纳入城市总体规划。"},{"i":14,"n":"第十四条","txt":"城市的地下交通干线以及其他地下工程的建设，应当兼顾人民防空需要。"},{"i":15,"n":"第十五条","txt":"为战时储备粮食、医药、油料和其他必需物资的工程，应当建在地下或者其他隐蔽地点。"},{"i":16,"n":"第十六条","txt":"对重要的经济目标，有关部门必须采取有效防护措施，并制定应急抢险抢修方案。"},{"i":17,"n":"第十七条","txt":"人民防空主管部门应当依照规定对城市和经济目标的人民防空建设进行监督检查。被检查单位应当如实提供情况和必要的资料。"},{"i":18,"n":"第十八条","txt":"人民防空工程包括为保障战时人员与物资掩蔽、人民防空指挥、医疗救护等而单独修建的地下防护建筑，以及结合地面建筑修建的战时可用于防空的地下室。"},{"i":19,"n":"第十九条","txt":"国家对人民防空工程建设，按照不同的防护要求，实行分类指导。"},{"i":20,"n":"第二十条","txt":"建设人民防空工程，应当在保证战时使用效能的前提下，有利于平时的经济建设、群众的生产生活和工程的开发利用。"},{"i":21,"n":"第二十一条","txt":"人民防空指挥工程、公用的人员掩蔽工程和疏散干道工程由人民防空主管部门负责组织修建；医疗救护、物资储备等专用工程由其他有关部门负责组织修建。"},{"i":22,"n":"第二十二条","txt":"城市新建民用建筑，按照国家有关规定修建战时可用于防空的地下室。"},{"i":23,"n":"第二十三条","txt":"人民防空工程建设的设计、施工、质量必须符合国家规定的防护标准和质量标准。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府有关部门对人民防空工程所需的建设用地应当依法予以保障；对人民防空工程连接城市的道路、供电、供热、供水、排水、通信等系统的设施建设，应当提供必要的条件。"},{"i":25,"n":"第二十五条","txt":"人民防空主管部门对人民防空工程的维护管理进行监督检查。"},{"i":26,"n":"第二十六条","txt":"国家鼓励平时利用人民防空工程为经济建设和人民生活服务。平时利用人民防空工程，不得影响其防空效能。"},{"i":27,"n":"第二十七条","txt":"任何组织或者个人不得进行影响人民防空工程使用或者降低人民防空工程防护能力的作业，不得向人民防空工程内排入废水、废气和倾倒废弃物，不得在人民防空工程内生产、储存爆炸、剧毒、易燃、放射性和腐蚀性物品。"},{"i":28,"n":"第二十八条","txt":"任何组织或者个人不得擅自拆除本法第二十一条规定的人民防空工程；确需拆除的，必须报经人民防空主管部门批准，并由拆除单位负责补建或者补偿。"},{"i":29,"n":"第二十九条","txt":"国家保障人民防空通信、警报的畅通，以迅速准确地传递、发放防空警报信号，有效地组织、指挥人民防空。"},{"i":30,"n":"第三十条","txt":"国家人民防空主管部门负责制定全国的人民防空通信、警报建设规划，组织全国的人民防空通信、警报网的建设和管理。"},{"i":31,"n":"第三十一条","txt":"邮电部门、军队通信部门和人民防空主管部门应当按照国家规定的任务和人民防空通信、警报建设规划，对人民防空通信实施保障。"},{"i":32,"n":"第三十二条","txt":"人民防空主管部门建设通信、警报网所需的电路、频率，邮电部门、军队通信部门、无线电管理机构应当予以保障；安装人民防空通信、警报设施，有关单位或者个人应当提供方便条件，不得阻挠。"},{"i":33,"n":"第三十三条","txt":"通信、广播、电视系统，战时必须优先传递、发放防空警报信号。"},{"i":34,"n":"第三十四条","txt":"军队有关部门应当向人民防空主管部门通报空中情报，协助训练有关专业人员。"},{"i":35,"n":"第三十五条","txt":"人民防空通信、警报设施必须保持良好使用状态。"},{"i":36,"n":"第三十六条","txt":"人民防空通信、警报设施平时应当为抢险救灾服务。"},{"i":37,"n":"第三十七条","txt":"人民防空疏散由县级以上人民政府统一组织。"},{"i":38,"n":"第三十八条","txt":"城市人民防空疏散计划，由县级以上人民政府根据需要组织有关部门制定。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府应当组织有关部门和单位，做好城市疏散人口安置和物资储运、供应的准备工作。"},{"i":40,"n":"第四十条","txt":"农村人口在有必要疏散时，由当地人民政府按照就近的原则组织实施。"},{"i":41,"n":"第四十一条","txt":"县级以上地方各级人民政府应当根据人民防空的需要，组织有关部门建立群众防空组织。"},{"i":42,"n":"第四十二条","txt":"群众防空组织由下列部门负责组建："},{"i":43,"n":"第四十三条","txt":"群众防空组织所需装备、器材和经费由人民防空主管部门和组建单位提供。"},{"i":44,"n":"第四十四条","txt":"群众防空组织应当根据人民防空主管部门制定的训练大纲和训练计划进行专业训练。"},{"i":45,"n":"第四十五条","txt":"国家开展人民防空教育，使公民增强国防观念，掌握人民防空的基本知识和技能。"},{"i":46,"n":"第四十六条","txt":"国家人民防空主管部门负责组织制定人民防空教育计划，规定教育内容。"},{"i":47,"n":"第四十七条","txt":"新闻、出版、广播、电影、电视、文化等有关部门应当协助开展人民防空教育。"},{"i":48,"n":"第四十八条","txt":"城市新建民用建筑，违反国家有关规定不修建战时可用于防空的地下室的，由县级以上人民政府人民防空主管部门对当事人给予警告，并责令限期修建，可以并处十万元以下的罚款。"},{"i":49,"n":"第四十九条","txt":"有下列行为之一的，由县级以上人民政府人民防空主管部门对当事人给予警告，并责令限期改正违法行为，可以对个人并处五千元以下的罚款、对单位并处一万元至五万元的罚款；造成损失的，应当依法赔偿损失："},{"i":50,"n":"第五十条","txt":"违反本法规定，故意损坏人民防空设施或者在人民防空工程内生产、储存爆炸、剧毒、易燃、放射性等危险品，尚不构成犯罪的，依照治安管理处罚法的有关规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"人民防空主管部门的工作人员玩忽职守、滥用职权、徇私舞弊或者有其他违法、失职行为构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":52,"n":"第五十二条","txt":"省、自治区、直辖市人民代表大会常务委员会可以根据本法制定实施办法。"},{"i":53,"n":"第五十三条","txt":"本法自1997年1月1日起施行。"}],"chuanranbingfangzhifa":[{"i":1,"n":"第一条","txt":"为了预防、控制和消除传染病的发生与流行，保障公众生命安全和身体健康，防范和化解公共卫生风险，维护国家安全和社会稳定，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"传染病防治工作坚持中国共产党的领导，坚持人民至上、生命至上，坚持预防为主、防治结合的方针，坚持依法防控、科学防控的原则。"},{"i":3,"n":"第三条","txt":"本法所称传染病，分为甲类传染病、乙类传染病、丙类传染病，以及突发原因不明的传染病等其他传染病。"},{"i":4,"n":"第四条","txt":"突发原因不明的传染病需要采取本法规定的甲类传染病预防、控制措施的，国务院疾病预防控制部门及时提出建议，由国务院卫生健康主管部门报经国务院批准后予以公布。"},{"i":5,"n":"第五条","txt":"省级人民政府对本行政区域常见多发的其他传染病，可以根据情况决定按照乙类或者丙类传染病管理并予以公布，报国务院疾病预防控制部门备案。"},{"i":6,"n":"第六条","txt":"国家建立健全传染病防治体制机制，明确属地、部门、单位和个人责任，实行联防联控、群防群控。"},{"i":7,"n":"第七条","txt":"各级人民政府加强对传染病防治工作的领导。"},{"i":8,"n":"第八条","txt":"国务院卫生健康主管部门牵头组织协调全国传染病疫情应对工作，负责全国传染病医疗救治的组织指导工作。国务院疾病预防控制部门负责全国传染病预防、控制的组织指导工作，负责全国传染病疫情应对相关工作。国务院其他有关部门在各自职责范围内负责传染病防治有关工作。"},{"i":9,"n":"第九条","txt":"国务院和县级以上地方人民政府的重大传染病疫情联防联控机制开展疫情会商研判，组织协调、督促推进疫情防控工作。"},{"i":10,"n":"第十条","txt":"国家建立健全城乡一体、上下联动、功能完备的疾病预防控制网络。"},{"i":11,"n":"第十一条","txt":"国家坚持中西医并重，加强中西医结合，充分发挥中医药在传染病防治中的作用。"},{"i":12,"n":"第十二条","txt":"国家支持和鼓励开展传染病防治的科学研究，组织开展传染病防治和公共卫生研究工作以及多学科联合攻关，提高传染病防治的科学技术水平。"},{"i":13,"n":"第十三条","txt":"国家支持和鼓励在传染病防治中运用现代信息技术。"},{"i":14,"n":"第十四条","txt":"中华人民共和国领域内的一切单位和个人应当支持传染病防治工作，接受和配合为预防、控制、消除传染病危害依法采取的调查、采集样本、检验检测、隔离治疗、医学观察等措施，根据传染病预防、控制需要采取必要的防护措施。"},{"i":15,"n":"第十五条","txt":"疾病预防控制部门、街道办事处和乡镇人民政府应当开展群防群控工作，指导居民委员会、村民委员会协助做好城乡社区的传染病预防、控制工作。"},{"i":16,"n":"第十六条","txt":"国家和社会应当关心、帮助传染病患者、病原携带者和疑似患者，使其得到及时救治。"},{"i":17,"n":"第十七条","txt":"采取传染病预防、控制措施，应当依照法定权限和程序，与传染病暴发、流行和可能造成危害的程度、范围等相适应；有多种措施可供选择的，应当选择有利于最大程度保护单位和个人合法权益，且对他人权益损害和生产生活影响较小的措施，并根据情况变化及时调整。"},{"i":18,"n":"第十八条","txt":"国家开展传染病防治健康教育工作，加强传染病防治法治宣传，提高公众传染病防治健康素养和法治意识。"},{"i":19,"n":"第十九条","txt":"国家支持和鼓励开展传染病防治的国际交流与合作。"},{"i":20,"n":"第二十条","txt":"对在传染病防治工作中做出显著成绩和贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":21,"n":"第二十一条","txt":"各级人民政府组织开展爱国卫生运动，完善公共卫生设施，改善人居环境状况，加强社会健康管理，提升全民健康水平。"},{"i":22,"n":"第二十二条","txt":"地方各级人民政府应当有计划地建设和改造城乡公共卫生设施，改善饮用水卫生条件，对污水、污物、粪便进行无害化处置。城市应当按照国家和地方有关标准修建公共厕所、垃圾和粪便无害化处置场以及排水和污水处理系统等公共卫生设施。农村应当逐步改造厕所，建立必要的卫生管理制度。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府农业农村、水利、林业草原等部门依据职责指导、组织控制和消除农田、湖区、河流、牧场、林区、草原地区的鼠害与血吸虫危害，以及其他传播传染病的动物和病媒生物的危害。"},{"i":24,"n":"第二十四条","txt":"国家实行免疫规划制度。政府免费向居民提供免疫规划疫苗。"},{"i":25,"n":"第二十五条","txt":"各级疾病预防控制机构在传染病预防、控制中履行下列职责："},{"i":26,"n":"第二十六条","txt":"二级以上医疗机构应当有专门的科室并指定专门的人员，承担本机构的传染病预防、控制和传染病疫情报告以及责任区域内的传染病预防工作。"},{"i":27,"n":"第二十七条","txt":"医疗机构的基本标准、建筑设计和服务流程应当符合预防医疗机构感染的要求，降低传染病在医疗机构内传播的风险。"},{"i":28,"n":"第二十八条","txt":"国务院疾病预防控制部门拟订国家重点传染病和突发原因不明的传染病预防控制应急预案，由国务院卫生健康主管部门批准、公布。"},{"i":29,"n":"第二十九条","txt":"医疗卫生机构和学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所，应当制定本单位传染病预防控制应急预案。"},{"i":30,"n":"第三十条","txt":"传染病预防控制应急预案应当增强科学性、针对性和可操作性，并根据实际需要和形势变化及时修订。"},{"i":31,"n":"第三十一条","txt":"疾病预防控制机构、医疗机构的实验室和从事病原微生物实验的单位，应当遵守有关病原微生物实验室生物安全的法律、行政法规规定，符合国家规定的条件和技术标准，建立严格的管理制度，对传染病病原体和样本按照规定的措施实行严格管理，严防传染病病原体的实验室感染和扩散。"},{"i":32,"n":"第三十二条","txt":"采供血机构、生物制品生产单位应当严格执行国家有关规定，保证血液、血液制品的质量和安全。"},{"i":33,"n":"第三十三条","txt":"各级人民政府应当加强艾滋病的防治工作，采取预防、控制措施，防止艾滋病的传播。具体办法由国务院制定。"},{"i":34,"n":"第三十四条","txt":"国家建立健全人畜共患传染病防治的协作机制，统筹规划、协同推进预防、控制工作，做好重点人群健康教育、传染病监测、疫情调查处置和信息通报等工作。"},{"i":35,"n":"第三十五条","txt":"国家建立病原微生物菌（毒）种保藏库。"},{"i":36,"n":"第三十六条","txt":"对被传染病病原体污染的水、物品和场所，有关单位和个人应当在疾病预防控制机构的指导下或者按照其提出的卫生要求，进行科学严格消毒处理；拒绝消毒处理的，由当地疾病预防控制部门组织进行强制消毒处理。"},{"i":37,"n":"第三十七条","txt":"在国家确认的自然疫源地计划兴建水利、交通、旅游、能源等大型建设项目的，应当事先由省级以上疾病预防控制机构对施工环境进行卫生调查。建设单位应当根据疾病预防控制机构的意见，采取必要的传染病预防、控制措施。施工期间，建设单位应当设专人负责工地上的卫生防疫工作。施工期间和工程竣工后，疾病预防控制机构应当对可能发生的传染病进行监测。"},{"i":38,"n":"第三十八条","txt":"用于传染病防治的消毒产品、饮用水供水单位供应的饮用水和涉及饮用水卫生安全的产品，应当符合国家卫生标准和卫生规范。"},{"i":39,"n":"第三十九条","txt":"传染病患者、病原携带者和疑似患者应当如实提供相关信息，在治愈前或者在排除传染病嫌疑前，不得从事法律、行政法规和国务院疾病预防控制部门规定禁止从事的易使该传染病扩散的工作。"},{"i":40,"n":"第四十条","txt":"学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所应当落实主体责任，加强传染病预防、控制能力建设，在疾病预防控制机构指导下开展传染病预防、控制工作。"},{"i":41,"n":"第四十一条","txt":"国家加强传染病监测预警工作，建设多点触发、反应快速、权威高效的传染病监测预警体系。"},{"i":42,"n":"第四十二条","txt":"国家建立健全传染病监测制度。"},{"i":43,"n":"第四十三条","txt":"疾病预防控制机构对传染病的发生、流行以及影响其发生、流行的因素进行监测，及时掌握重点传染病流行强度、危害程度以及病原体变异情况。"},{"i":44,"n":"第四十四条","txt":"国家建立跨部门、跨地域的传染病监测信息共享机制，加强卫生健康、疾病预防控制、生态环境、农业农村、海关、市场监督管理、移民管理、林业草原等部门的联动监测和信息共享。"},{"i":45,"n":"第四十五条","txt":"国家建立健全传染病疫情报告制度。"},{"i":46,"n":"第四十六条","txt":"疾病预防控制机构、医疗机构和采供血机构应当建立健全传染病疫情报告管理制度，加强传染病疫情和相关信息报告的培训、日常管理和质量控制，定期对本机构报告的传染病疫情和相关信息以及报告质量进行分析、汇总和通报。"},{"i":47,"n":"第四十七条","txt":"学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所发现传染病患者、疑似患者时，应当按照国务院疾病预防控制部门的规定，向所在地疾病预防控制机构报告有关信息。"},{"i":48,"n":"第四十八条","txt":"任何单位和个人发现传染病患者、疑似患者时，应当及时向附近的疾病预防控制机构、医疗机构或者疾病预防控制部门报告。"},{"i":49,"n":"第四十九条","txt":"疾病预防控制机构应当设立或者指定专门的部门、人员负责传染病疫情信息管理工作，主动收集、分析、调查、核实传染病疫情信息。"},{"i":50,"n":"第五十条","txt":"任何单位或者个人不得干预传染病疫情报告。"},{"i":51,"n":"第五十一条","txt":"对及时发现并报告新发传染病、突发原因不明的传染病的单位和个人，按照国家有关规定给予奖励。"},{"i":52,"n":"第五十二条","txt":"国家建立健全传染病疫情风险评估制度。"},{"i":53,"n":"第五十三条","txt":"国家建立健全传染病预警制度。"},{"i":54,"n":"第五十四条","txt":"县级以上地方人民政府疾病预防控制部门应当及时向本行政区域的疾病预防控制机构和医疗机构通报传染病疫情以及监测、预警的相关信息。接到通报的疾病预防控制机构和医疗机构应当及时报告本机构的主要负责人，并告知本机构的有关人员。"},{"i":55,"n":"第五十五条","txt":"国务院疾病预防控制部门应当及时向省级人民政府疾病预防控制部门和中央军事委员会负责卫生工作的部门通报全国传染病疫情以及监测、预警的相关信息。中央军事委员会负责卫生工作的部门发现传染病疫情时，应当向国务院疾病预防控制部门通报。"},{"i":56,"n":"第五十六条","txt":"县级以上人民政府疾病预防控制部门与同级人民政府教育、公安、民政、司法行政、生态环境、农业农村、市场监督管理、林业草原、中医药等部门建立传染病疫情通报机制，及时共享传染病疫情信息。"},{"i":57,"n":"第五十七条","txt":"国家建立健全传染病疫情信息公布制度。"},{"i":58,"n":"第五十八条","txt":"医疗机构、疾病预防控制机构发现甲类传染病时，应当立即采取下列措施，并向县级以上地方人民政府疾病预防控制部门报告："},{"i":59,"n":"第五十九条","txt":"医疗机构、疾病预防控制机构接到其他单位和个人报告甲类传染病的，有关甲类传染病患者、疑似患者的移交按照国务院疾病预防控制部门的规定执行。"},{"i":60,"n":"第六十条","txt":"医疗机构发现乙类或者丙类传染病患者时，应当根据病情采取必要的治疗和控制传播措施。"},{"i":61,"n":"第六十一条","txt":"医疗机构对本机构内被传染病病原体污染的场所、物品以及医疗废物、医疗污水，应当依照有关法律、行政法规的规定实施消毒和无害化处置。"},{"i":62,"n":"第六十二条","txt":"疾病预防控制机构发现传染病疫情或者接到传染病疫情报告时，应当及时采取下列措施："},{"i":63,"n":"第六十三条","txt":"传染病暴发、流行时，县级以上地方人民政府应当立即组织力量，按照传染病预防控制应急预案进行防治，控制传染源，切断传染病的传播途径；发生重大传染病疫情，经评估必要时，可以采取下列紧急措施："},{"i":64,"n":"第六十四条","txt":"对已经发生甲类传染病病例的场所或者该场所内的特定区域的人员，所在地县级以上地方人民政府可以实施隔离措施，同时向上一级人民政府报告。接到报告的上级人民政府认为实施的隔离措施不适当的，应当立即调整或者撤销。"},{"i":65,"n":"第六十五条","txt":"发生新发传染病、突发原因不明的传染病，县级以上地方人民政府经评估认为确有必要的，可以预先采取本法规定的甲类传染病预防、控制措施，同时向上一级人民政府报告。接到报告的上级人民政府认为预先采取的预防、控制措施不适当的，应当立即调整或者撤销。"},{"i":66,"n":"第六十六条","txt":"因甲类、乙类传染病发生重大传染病疫情时，县级以上地方人民政府报经上一级人民政府决定，可以对进入或者离开本行政区域受影响的相关区域的人员、物资和交通工具实施卫生检疫。"},{"i":67,"n":"第六十七条","txt":"依照本法第六十三条至第六十六条规定采取传染病疫情防控措施时，决定采取措施的机关应当向社会发布公告，明确措施的具体内容、实施范围和实施期限，并进行必要的解释说明。相关疫情防控措施的解除，由原决定机关决定并宣布。"},{"i":68,"n":"第六十八条","txt":"发生甲类传染病时，为了防止该传染病通过交通工具及其乘运的人员、物资传播，省级人民政府可以决定实施交通卫生检疫。具体办法由国务院制定。"},{"i":69,"n":"第六十九条","txt":"发生重大传染病疫情时，根据传染病疫情防控的需要，国务院及其有关部门有权在全国或者跨省级行政区域范围内，县级以上地方人民政府及其有关部门有权在本行政区域内，紧急调集人员或者调用储备物资，临时征用房屋、交通工具以及相关设施、设备、场地和其他物资，要求有关单位和个人提供技术支持。"},{"i":70,"n":"第七十条","txt":"医疗机构、疾病预防控制机构、检验检测机构应当按照传染病检验检测技术规范和标准开展检验检测活动，加强检验检测质量控制。"},{"i":71,"n":"第七十一条","txt":"患甲类传染病、炭疽死亡的，应当将其尸体立即进行卫生处理，就近火化；患其他传染病死亡的，必要时应当将其尸体进行卫生处理后火化或者按照规定深埋。对尸体进行火化或者深埋应当及时告知死者家属。"},{"i":72,"n":"第七十二条","txt":"本法第六十六条规定的受影响的相关区域中被传染病病原体污染或者可能被传染病病原体污染的物品，经消毒可以使用的，应当在疾病预防控制机构的指导下，进行消毒处理后，方可使用、出售和运输。"},{"i":73,"n":"第七十三条","txt":"传染病暴发、流行时，有关生产、供应单位应当及时生产、供应传染病疫情防控所需的药品、医疗器械和其他应急物资。交通运输、邮政、快递经营单位应当优先运送参与传染病疫情防控的人员以及传染病疫情防控所需的药品、医疗器械和其他应急物资。县级以上人民政府有关部门应当做好组织协调工作。"},{"i":74,"n":"第七十四条","txt":"单位和个人认为采取本法第五十八条、第六十三条至第六十六条规定的传染病疫情防控措施侵犯其合法权益的，可以向县级以上地方人民政府或者其指定的部门提出申诉，申诉期间相关措施不停止执行。县级以上地方人民政府应当畅通申诉渠道，完善处理程序，确保有关申诉及时处理。"},{"i":75,"n":"第七十五条","txt":"县级以上人民政府应当加强和完善常态与应急相结合的传染病医疗救治服务网络建设，指定具备传染病救治条件和能力的医疗机构承担传染病救治任务，根据传染病救治需要设置传染病专科医院。"},{"i":76,"n":"第七十六条","txt":"国家建立健全重大传染病疫情医疗救治体系，建立由传染病专科医院、综合医院、中医医院、院前急救机构、临时性救治场所、基层医疗卫生机构、血站等构成的综合医疗救治体系，对传染病患者进行分类救治，加强重症患者医疗救治，提高重大传染病疫情医疗救治能力。"},{"i":77,"n":"第七十七条","txt":"医疗机构应当对传染病患者、疑似患者提供医疗救护、现场救援和接诊治疗，按照规定填写并妥善保管病历记录以及其他有关资料。"},{"i":78,"n":"第七十八条","txt":"医疗机构应当按照传染病诊断标准和治疗要求采取相应措施，充分发挥中西医各自优势，加强中西医结合，提高传染病诊断和救治能力。"},{"i":79,"n":"第七十九条","txt":"国家鼓励传染病防治用药品、医疗器械的研制和创新，对防治传染病急需的药品、医疗器械予以优先审评审批。"},{"i":80,"n":"第八十条","txt":"国家建立重大传染病疫情心理援助制度。县级以上地方人民政府应当组织专业力量，定期开展培训和演练；发生重大传染病疫情时，对传染病患者、接受医学观察的人员、病亡者家属、相关工作人员等重点人群以及社会公众及时提供心理疏导和心理干预等服务。"},{"i":81,"n":"第八十一条","txt":"国家将传染病防治工作纳入国民经济和社会发展规划，县级以上地方人民政府将传染病防治工作纳入本行政区域的国民经济和社会发展规划。"},{"i":82,"n":"第八十二条","txt":"县级以上地方人民政府按照本级政府职责，负责本行政区域传染病预防、控制工作经费。"},{"i":83,"n":"第八十三条","txt":"县级以上人民政府应当按照规定落实疾病预防控制机构基本建设、设备购置、学科建设、人才培养等相关经费；对其他医疗卫生机构承担疾病预防控制任务所需经费按照规定予以保障。"},{"i":84,"n":"第八十四条","txt":"国家加强基层传染病防治体系建设，扶持欠发达地区、民族地区和边境地区的传染病防治工作。"},{"i":85,"n":"第八十五条","txt":"国家加强医疗机构疾病预防控制能力建设，持续提升传染病专科医院、综合医院的传染病监测、检验检测、诊断和救治、科学研究等能力和水平。"},{"i":86,"n":"第八十六条","txt":"国家加强传染病防治人才队伍建设，推动传染病防治相关学科建设。"},{"i":87,"n":"第八十七条","txt":"县级以上人民政府应当加强疾病预防控制信息化建设，将其纳入全民健康信息化建设。"},{"i":88,"n":"第八十八条","txt":"对符合国家规定的传染病医疗费用，基本医疗保险按照规定予以支付。"},{"i":89,"n":"第八十九条","txt":"国家建立健全公共卫生应急物资保障体系，提高传染病疫情防控应急物资保障水平，县级以上人民政府发展改革部门统筹防控应急物资保障工作。"},{"i":90,"n":"第九十条","txt":"国家建立少见罕见传染病和境内已消除的传染病防治能力储备机制，支持相关疾病预防控制机构、医疗机构、科研机构持续开展相关培训、基础性和应用性研究、现场防治等工作，支持相关专家参与国际防控工作，持续保持对上述传染病进行识别、检验检测、诊断和救治的能力。"},{"i":91,"n":"第九十一条","txt":"对从事传染病预防、医疗、科研、教学和现场处理疫情的人员，以及在生产、工作中接触传染病病原体的其他人员，按照国家规定采取有效的卫生防护措施和医疗保健措施，并给予适当的津贴。"},{"i":92,"n":"第九十二条","txt":"县级以上人民政府应当定期研究部署重大传染病疫情防控等疾病预防控制工作，定期向社会发布传染病防治工作报告，向本级人民代表大会常务委员会报告传染病防治工作，依法接受监督。"},{"i":93,"n":"第九十三条","txt":"县级以上人民政府疾病预防控制部门对传染病防治工作履行下列监督检查职责："},{"i":94,"n":"第九十四条","txt":"县级以上人民政府卫生健康主管部门、疾病预防控制部门在履行监督检查职责时，有权进入传染病疫情发生现场及相关单位，开展查阅或者复制有关资料、采集样本、制作现场笔录等调查取证工作。被检查单位应当予以配合，不得拒绝、阻挠。"},{"i":95,"n":"第九十五条","txt":"县级以上地方人民政府疾病预防控制部门在履行监督检查职责时，发现可能被传染病病原体污染的公共饮用水源、食品以及相关物品，如不及时采取控制措施可能导致传染病传播、暴发、流行的，应当采取封闭公共饮用水源、封存食品以及相关物品或者暂停销售的临时控制措施，并予以检验或者进行消毒处理。经检验，对被污染的食品，应当予以销毁；对未被污染的食品或者经消毒处理后可以使用的物品，应当及时解除控制措施。"},{"i":96,"n":"第九十六条","txt":"县级以上人民政府卫生健康主管部门、疾病预防控制部门工作人员依法执行职务时，应当不少于两人，并出示执法证件，填写执法文书。"},{"i":97,"n":"第九十七条","txt":"县级以上人民政府卫生健康主管部门、疾病预防控制部门应当依法建立健全内部监督制度，对其工作人员依据法定职权和程序履行职责的情况进行监督。"},{"i":98,"n":"第九十八条","txt":"县级以上人民政府卫生健康主管部门、疾病预防控制部门和其他有关部门应当依法履行职责，自觉接受社会监督。"},{"i":99,"n":"第九十九条","txt":"卫生健康、疾病预防控制等部门发现涉嫌传染病防治相关犯罪的，应当按照有关规定及时将案件移送公安机关。对移送的案件，公安机关应当及时审查处理。"},{"i":100,"n":"第一百条","txt":"违反本法规定，地方各级人民政府未依法履行报告职责，隐瞒、谎报、缓报、漏报传染病疫情，干预传染病疫情报告，或者在传染病暴发、流行时未依法组织救治、采取控制措施的，由上级人民政府责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":101,"n":"第一百零一条","txt":"违反本法规定，县级以上人民政府卫生健康主管部门、疾病预防控制部门有下列情形之一的，由本级人民政府或者上级人民政府卫生健康主管部门、疾病预防控制部门责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分："},{"i":102,"n":"第一百零二条","txt":"违反本法规定，县级以上人民政府有关部门未依法履行传染病防治、疫情通报和保障职责的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":103,"n":"第一百零三条","txt":"违反本法规定，疾病预防控制机构有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告或者通报批评，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门依法吊销有关责任人员的执业证书："},{"i":104,"n":"第一百零四条","txt":"违反本法规定，医疗机构有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告或者通报批评，可以并处十万元以下罚款；情节严重的，可以由原发证部门或者原备案部门依法吊销医疗机构执业许可证或者责令停止执业活动，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门责令有关责任人员暂停六个月以上一年以下执业活动直至依法吊销执业证书："},{"i":105,"n":"第一百零五条","txt":"违反本法规定，采供血机构未按照规定报告传染病疫情，隐瞒、谎报、缓报、漏报传染病疫情，或者干预传染病疫情报告的，由县级以上人民政府疾病预防控制部门责令改正，给予警告或者通报批评，可以并处十万元以下罚款；情节严重的，可以由原发证部门依法吊销采供血机构的执业许可证，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门责令有关责任人员暂停六个月以上一年以下执业活动直至依法吊销执业证书。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，交通运输、邮政、快递经营单位未优先运送参与传染病疫情防控的人员以及传染病疫情防控所需的药品、医疗器械和其他应急物资的，由交通运输、铁路、民用航空、邮政管理部门依据职责责令改正，给予警告；造成严重后果的，并处一万元以上十万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":107,"n":"第一百零七条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告，没收违法所得，可以并处二十万元以下罚款；情节严重的，可以由原发证部门依法吊销相关许可证，对直接负责的主管人员和其他直接责任人员可以禁止其五年内从事相应生产经营活动："},{"i":108,"n":"第一百零八条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府卫生健康、疾病预防控制等部门依据职责责令改正，给予警告或者通报批评，没收违法所得，可以并处十万元以下罚款；情节严重的，可以由原发证部门依法吊销相关许可证，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门责令有关责任人员暂停六个月以上一年以下执业活动直至依法吊销执业证书："},{"i":109,"n":"第一百零九条","txt":"违反本法规定，在国家确认的自然疫源地兴建水利、交通、旅游、能源等大型建设项目，未经卫生调查进行施工，或者未按照疾病预防控制机构的意见采取必要的传染病预防、控制措施的，由县级以上人民政府疾病预防控制部门责令限期改正，给予警告，并处十万元以上五十万元以下罚款；逾期不改正的，处五十万元以上一百万元以下罚款，提请有关人民政府依据职责权限责令停建、拆除，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":110,"n":"第一百一十条","txt":"违反本法规定，县级以上人民政府卫生健康主管部门、疾病预防控制部门或者其他有关部门未依法履行个人信息保护义务的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":111,"n":"第一百一十一条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告，对违法的单位可以并处二万元以下罚款，对违法的个人可以并处一千元以下罚款；情节严重的，由原发证部门依法吊销相关许可证或者营业执照："},{"i":112,"n":"第一百一十二条","txt":"违反本法规定，造成人身、财产损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":113,"n":"第一百一十三条","txt":"本法中下列用语的含义："},{"i":114,"n":"第一百一十四条","txt":"传染病防治中有关突发公共卫生事件的应对，本法未作规定的，适用有关突发公共卫生事件应对的法律、行政法规规定。"},{"i":115,"n":"第一百一十五条","txt":"本法自2025年9月1日起施行。"}],"tiyufa":[{"i":1,"n":"第一条","txt":"为了促进体育事业，弘扬中华体育精神，培育中华体育文化，发展体育运动，增强人民体质，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"体育工作坚持中国共产党的领导，坚持以人民为中心，以全民健身为基础，普及与提高相结合，推动体育事业均衡、充分发展，推进体育强国和健康中国建设。"},{"i":3,"n":"第三条","txt":"县级以上人民政府应当将体育事业纳入国民经济和社会发展规划。"},{"i":4,"n":"第四条","txt":"国务院体育行政部门主管全国体育工作。国务院其他有关部门在各自的职责范围内管理相关体育工作。"},{"i":5,"n":"第五条","txt":"国家依法保障公民平等参与体育活动的权利，对未成年人、妇女、老年人、残疾人等参加体育活动的权利给予特别保障。"},{"i":6,"n":"第六条","txt":"国家扩大公益性和基础性公共体育服务供给，推动基本公共体育服务均等化，逐步健全全民覆盖、普惠共享、城乡一体的基本公共体育服务体系。"},{"i":7,"n":"第七条","txt":"国家采取财政支持、帮助建设体育设施等措施，扶持革命老区、民族地区、边疆地区、经济欠发达地区体育事业的发展。"},{"i":8,"n":"第八条","txt":"国家鼓励、支持优秀民族、民间、民俗传统体育项目的发掘、整理、保护、推广和创新，定期举办少数民族传统体育运动会。"},{"i":9,"n":"第九条","txt":"开展和参加体育活动，应当遵循依法合规、诚实守信、尊重科学、因地制宜、勤俭节约、保障安全的原则。"},{"i":10,"n":"第十条","txt":"国家优先发展青少年和学校体育，坚持体育和教育融合，文化学习和体育锻炼协调，体魄与人格并重，促进青少年全面发展。"},{"i":11,"n":"第十一条","txt":"国家支持体育产业发展，完善体育产业体系，规范体育市场秩序，鼓励扩大体育市场供给，拓宽体育产业投融资渠道，促进体育消费。"},{"i":12,"n":"第十二条","txt":"国家支持体育科学研究和技术创新，培养体育科技人才，推广应用体育科学技术成果，提高体育科学技术水平。"},{"i":13,"n":"第十三条","txt":"国家对在体育事业发展中做出突出贡献的组织和个人，按照有关规定给予表彰和奖励。"},{"i":14,"n":"第十四条","txt":"国家鼓励开展对外体育交往，弘扬奥林匹克精神，支持参与国际体育运动。"},{"i":15,"n":"第十五条","txt":"每年8月8日全民健身日所在周为体育宣传周。"},{"i":16,"n":"第十六条","txt":"国家实施全民健身战略，构建全民健身公共服务体系，鼓励和支持公民参加健身活动，促进全民健身与全民健康深度融合。"},{"i":17,"n":"第十七条","txt":"国家倡导公民树立和践行科学健身理念，主动学习健身知识，积极参加健身活动。"},{"i":18,"n":"第十八条","txt":"国家推行全民健身计划，制定和实施体育锻炼标准，定期开展公民体质监测和全民健身活动状况调查，开展科学健身指导工作。"},{"i":19,"n":"第十九条","txt":"国家实行社会体育指导员制度。社会体育指导员对全民健身活动进行指导。"},{"i":20,"n":"第二十条","txt":"地方各级人民政府和有关部门应当为全民健身活动提供必要的条件，支持、保障全民健身活动的开展。"},{"i":21,"n":"第二十一条","txt":"国家机关、企业事业单位和工会、共产主义青年团、妇女联合会、残疾人联合会等群团组织应当根据各自特点，组织开展日常体育锻炼和各级各类体育运动会等全民健身活动。"},{"i":22,"n":"第二十二条","txt":"居民委员会、村民委员会以及其他社区组织应当结合实际，组织开展全民健身活动。"},{"i":23,"n":"第二十三条","txt":"全社会应当关心和支持未成年人、妇女、老年人、残疾人参加全民健身活动。各级人民政府应当采取措施，为未成年人、妇女、老年人、残疾人安全参加全民健身活动提供便利和保障。"},{"i":24,"n":"第二十四条","txt":"国家实行青少年和学校体育活动促进计划，健全青少年和学校体育工作制度，培育、增强青少年体育健身意识，推动青少年和学校体育活动的开展和普及，促进青少年身心健康和体魄强健。"},{"i":25,"n":"第二十五条","txt":"教育行政部门和学校应当将体育纳入学生综合素质评价范围，将达到国家学生体质健康标准要求作为教育教学考核的重要内容，培养学生体育锻炼习惯，提升学生体育素养。"},{"i":26,"n":"第二十六条","txt":"学校必须按照国家有关规定开齐开足体育课，确保体育课时不被占用。"},{"i":27,"n":"第二十七条","txt":"学校应当将在校内开展的学生课外体育活动纳入教学计划，与体育课教学内容相衔接，保障学生在校期间每天参加不少于一小时体育锻炼。"},{"i":28,"n":"第二十八条","txt":"国家定期举办全国学生（青年）运动会。地方各级人民政府应当结合实际，定期组织本地区学生（青年）运动会。"},{"i":29,"n":"第二十九条","txt":"国家将体育科目纳入初中、高中学业水平考试范围，建立符合学科特点的考核机制。"},{"i":30,"n":"第三十条","txt":"学校应当建立学生体质健康检查制度。教育、体育和卫生健康行政部门应当加强对学生体质的监测和评估。"},{"i":31,"n":"第三十一条","txt":"学校应当按照国家有关规定，配足合格的体育教师，保障体育教师享受与其他学科教师同等待遇。"},{"i":32,"n":"第三十二条","txt":"学校应当按照国家有关标准配置体育场地、设施和器材，并定期进行检查、维护，适时予以更新。"},{"i":33,"n":"第三十三条","txt":"国家建立健全学生体育活动意外伤害保险机制。"},{"i":34,"n":"第三十四条","txt":"幼儿园应当为学前儿童提供适宜的室内外活动场地和体育设施、器材，开展符合学前儿童特点的体育活动。"},{"i":35,"n":"第三十五条","txt":"各级教育督导机构应当对学校体育实施督导，并向社会公布督导报告。"},{"i":36,"n":"第三十六条","txt":"教育行政部门、体育行政部门和学校应当组织、引导青少年参加体育活动，预防和控制青少年近视、肥胖等不良健康状况，家庭应当予以配合。"},{"i":37,"n":"第三十七条","txt":"体育行政部门会同有关部门引导和规范企业事业单位、社会组织和体育专业人员等为青少年提供体育培训等服务。"},{"i":38,"n":"第三十八条","txt":"各级各类体育运动学校应当对适龄学生依法实施义务教育，并根据国务院体育行政部门制定的教学训练大纲开展业余体育训练。"},{"i":39,"n":"第三十九条","txt":"国家促进竞技体育发展，鼓励运动员提高竞技水平，在体育赛事中创造优异成绩，为国家和人民争取荣誉。"},{"i":40,"n":"第四十条","txt":"国家促进和规范职业体育市场化、职业化发展，提高职业体育赛事能力和竞技水平。"},{"i":41,"n":"第四十一条","txt":"国家加强体育运动学校和体育传统特色学校建设，鼓励、支持开展业余体育训练，培养优秀的竞技体育后备人才。"},{"i":42,"n":"第四十二条","txt":"国家加强对运动员的培养和管理，对运动员进行爱国主义、集体主义和社会主义教育，以及道德、纪律和法治教育。"},{"i":43,"n":"第四十三条","txt":"国家加强体育训练科学技术研究、开发和应用，对运动员实行科学、文明的训练，维护运动员身心健康。"},{"i":44,"n":"第四十四条","txt":"国家依法保障运动员接受文化教育的权利。"},{"i":45,"n":"第四十五条","txt":"国家依法保障运动员选择注册与交流的权利。"},{"i":46,"n":"第四十六条","txt":"国家对优秀运动员在就业和升学方面给予优待。"},{"i":47,"n":"第四十七条","txt":"各级人民政府加强对退役运动员的职业技能培训和社会保障，为退役运动员就业、创业提供指导和服务。"},{"i":48,"n":"第四十八条","txt":"国家实行体育运动水平等级、教练员职称等级和裁判员技术等级制度。"},{"i":49,"n":"第四十九条","txt":"代表国家和地方参加国际、国内重大体育赛事的运动员和运动队，应当按照公开、公平、择优的原则选拔和组建。"},{"i":50,"n":"第五十条","txt":"国家对体育赛事活动实行分级分类管理，具体办法由国务院体育行政部门规定。"},{"i":51,"n":"第五十一条","txt":"体育赛事实行公平竞争的原则。"},{"i":52,"n":"第五十二条","txt":"在中国境内举办的体育赛事，其名称、徽记、旗帜及吉祥物等标志按照国家有关规定予以保护。"},{"i":53,"n":"第五十三条","txt":"国家提倡健康文明、公平竞争的体育运动，禁止在体育运动中使用兴奋剂。"},{"i":54,"n":"第五十四条","txt":"国家建立健全反兴奋剂制度。"},{"i":55,"n":"第五十五条","txt":"国务院体育行政部门负责制定反兴奋剂规范。"},{"i":56,"n":"第五十六条","txt":"国务院体育行政部门会同国务院药品监管、卫生健康、商务、海关等部门制定、公布兴奋剂目录，并动态调整。"},{"i":57,"n":"第五十七条","txt":"国家设立反兴奋剂机构。反兴奋剂机构及其检查人员依照法定程序开展检查，有关单位和人员应当予以配合，任何单位和个人不得干涉。"},{"i":58,"n":"第五十八条","txt":"县级以上人民政府体育行政部门组织开展反兴奋剂宣传、教育工作，提高体育活动参与者和公众的反兴奋剂意识。"},{"i":59,"n":"第五十九条","txt":"国家鼓励开展反兴奋剂科学技术研究，推广先进的反兴奋剂技术、设备和方法。"},{"i":60,"n":"第六十条","txt":"国家根据缔结或者参加的有关国际条约，开展反兴奋剂国际合作，履行反兴奋剂国际义务。"},{"i":61,"n":"第六十一条","txt":"国家鼓励、支持体育组织依照法律法规和章程开展体育活动，推动体育事业发展。"},{"i":62,"n":"第六十二条","txt":"中华全国体育总会和地方各级体育总会是团结各类体育组织和体育工作者、体育爱好者的群众性体育组织，应当在发展体育事业中发挥作用。"},{"i":63,"n":"第六十三条","txt":"中国奥林匹克委员会是以发展体育和推动奥林匹克运动为主要任务的体育组织，代表中国参与国际奥林匹克事务。"},{"i":64,"n":"第六十四条","txt":"体育科学社会团体是体育科学技术工作者的学术性体育社会组织，应当在发展体育科技事业中发挥作用。"},{"i":65,"n":"第六十五条","txt":"全国性单项体育协会是依法登记的体育社会组织，代表中国参加相应的国际单项体育组织，根据章程加入中华全国体育总会、派代表担任中国奥林匹克委员会委员。"},{"i":66,"n":"第六十六条","txt":"单项体育协会应当依法维护会员的合法权益，积极向有关单位反映会员的意见和建议。"},{"i":67,"n":"第六十七条","txt":"单项体育协会应当接受体育行政部门的指导和监管，健全内部治理机制，制定行业规则，加强行业自律。"},{"i":68,"n":"第六十八条","txt":"国家鼓励发展青少年体育俱乐部、社区健身组织等各类自治性体育组织。"},{"i":69,"n":"第六十九条","txt":"国家制定体育产业发展规划，扩大体育产业规模，增强体育产业活力，促进体育产业高质量发展，满足人民群众多样化体育需求。"},{"i":70,"n":"第七十条","txt":"国家支持和规范发展体育用品制造、体育服务等体育产业，促进体育与健康、文化、旅游、养老、科技等融合发展。"},{"i":71,"n":"第七十一条","txt":"国家支持体育用品制造业创新发展，鼓励企业加大研发投入，采用新技术、新工艺、新材料，促进体育用品制造业转型升级。"},{"i":72,"n":"第七十二条","txt":"国家完善职业体育发展体系，拓展职业体育发展渠道，支持运动员、教练员职业化发展，提高职业体育的成熟度和规范化水平。"},{"i":73,"n":"第七十三条","txt":"国家建立健全区域体育产业协调互动机制，推动区域间体育产业资源交流共享，促进区域体育协调发展。"},{"i":74,"n":"第七十四条","txt":"国家鼓励社会资本投入体育产业，建设体育设施，开发体育产品，提供体育服务。"},{"i":75,"n":"第七十五条","txt":"国家鼓励有条件的高等学校设置体育产业相关专业，开展校企合作，加强职业教育和培训，培养体育产业专业人才，形成有效支撑体育产业发展的人才队伍。"},{"i":76,"n":"第七十六条","txt":"国家完善体育产业统计体系，开展体育产业统计监测，定期发布体育产业数据。"},{"i":77,"n":"第七十七条","txt":"县级以上人民政府应当将体育事业经费列入本级预算，建立与国民经济和社会发展相适应的投入机制。"},{"i":78,"n":"第七十八条","txt":"国家鼓励社会力量发展体育事业，鼓励对体育事业的捐赠和赞助，保障参与主体的合法权益。"},{"i":79,"n":"第七十九条","txt":"国家有关部门应当加强对体育资金的管理，任何单位和个人不得侵占、挪用、截留、克扣、私分体育资金。"},{"i":80,"n":"第八十条","txt":"国家支持通过政府购买服务的方式提供公共体育服务，提高公共体育服务水平。"},{"i":81,"n":"第八十一条","txt":"县级以上地方人民政府应当按照国家有关规定，根据本行政区域经济社会发展水平、人口结构、环境条件以及体育事业发展需要，统筹兼顾，优化配置各级各类体育场地设施，优先保障全民健身体育场地设施的建设和配置。"},{"i":82,"n":"第八十二条","txt":"县级以上地方人民政府应当将本行政区域内公共体育场地设施的建设纳入国民经济和社会发展规划、国土空间规划，未经法定程序不得变更。"},{"i":83,"n":"第八十三条","txt":"新建、改建、扩建居住社区，应当按照国家有关规定，同步规划、设计、建设用于居民日常健身的配套体育场地设施。"},{"i":84,"n":"第八十四条","txt":"公共体育场地设施管理单位应当公开向社会开放的办法，并对未成年人、老年人、残疾人等实行优惠。"},{"i":85,"n":"第八十五条","txt":"国家推进体育公园建设，鼓励地方因地制宜发展特色体育公园，推动体育公园免费开放，满足公民体育健身需求。"},{"i":86,"n":"第八十六条","txt":"国家鼓励充分、合理利用旧厂房、仓库、老旧商业设施等闲置资源建设用于公民日常健身的体育场地设施，鼓励和支持机关、学校、企业事业单位的体育场地设施向公众开放。"},{"i":87,"n":"第八十七条","txt":"任何单位和个人不得侵占公共体育场地设施及其建设用地，不得擅自拆除公共体育场地设施，不得擅自改变公共体育场地设施的功能、用途或者妨碍其正常使用。"},{"i":88,"n":"第八十八条","txt":"县级以上地方人民政府应当建立全民健身公共场地设施的维护管理机制，明确管理和维护责任。"},{"i":89,"n":"第八十九条","txt":"国家发展体育专业教育，鼓励有条件的高等学校培养教练员、裁判员、体育教师等各类体育专业人才，鼓励社会力量依法开展体育专业教育。"},{"i":90,"n":"第九十条","txt":"国家鼓励建立健全运动员伤残保险、体育意外伤害保险和场所责任保险制度。"},{"i":91,"n":"第九十一条","txt":"国家建立体育仲裁制度，及时、公正解决体育纠纷，保护当事人的合法权益。"},{"i":92,"n":"第九十二条","txt":"当事人可以根据仲裁协议、体育组织章程、体育赛事规则等，对下列纠纷申请体育仲裁："},{"i":93,"n":"第九十三条","txt":"国务院体育行政部门依照本法组织设立体育仲裁委员会，制定体育仲裁规则。"},{"i":94,"n":"第九十四条","txt":"体育仲裁委员会裁决体育纠纷实行仲裁庭制。仲裁庭组成人数应当是单数，具体组成办法由体育仲裁规则规定。"},{"i":95,"n":"第九十五条","txt":"鼓励体育组织建立内部纠纷解决机制，公平、公正、高效地解决纠纷。"},{"i":96,"n":"第九十六条","txt":"对体育社会组织、运动员管理单位、体育赛事活动组织者的处理决定或者内部纠纷解决机制处理结果不服的，当事人自收到处理决定或者纠纷处理结果之日起二十一日内申请体育仲裁。"},{"i":97,"n":"第九十七条","txt":"体育仲裁裁决书自作出之日起发生法律效力。"},{"i":98,"n":"第九十八条","txt":"有下列情形之一的，当事人可以自收到仲裁裁决书之日起三十日内向体育仲裁委员会所在地的中级人民法院申请撤销裁决："},{"i":99,"n":"第九十九条","txt":"当事人应当履行体育仲裁裁决。一方当事人不履行的，另一方当事人可以依照《中华人民共和国民事诉讼法》的有关规定向人民法院申请执行。"},{"i":100,"n":"第一百条","txt":"需要即时处理的体育赛事活动纠纷，适用体育仲裁特别程序。"},{"i":101,"n":"第一百零一条","txt":"县级以上人民政府体育行政部门和有关部门应当积极履行监督检查职责，发现违反本法规定行为的，应当及时做出处理。对不属于本部门主管事项的，应当及时书面通知并移交相关部门查处。"},{"i":102,"n":"第一百零二条","txt":"县级以上人民政府体育行政部门对体育赛事活动依法进行监管，对赛事活动场地实施现场检查，查阅、复制有关合同、票据、账簿，检查赛事活动组织方案、安全应急预案等材料。"},{"i":103,"n":"第一百零三条","txt":"县级以上人民政府市场监管、体育行政等部门按照各自职责对体育市场进行监督管理。"},{"i":104,"n":"第一百零四条","txt":"国家建立体育项目管理制度，新设体育项目由国务院体育行政部门认定。"},{"i":105,"n":"第一百零五条","txt":"经营高危险性体育项目，应当符合下列条件，并向县级以上地方人民政府体育行政部门提出申请："},{"i":106,"n":"第一百零六条","txt":"举办高危险性体育赛事活动，应当符合下列条件，并向县级以上地方人民政府体育行政部门提出申请："},{"i":107,"n":"第一百零七条","txt":"县级以上地方人民政府应当建立体育执法机制，为体育执法提供必要保障。体育执法情况应当向社会公布，接受社会监督。"},{"i":108,"n":"第一百零八条","txt":"县级以上地方人民政府每届任期内至少向本级人民代表大会或者其常务委员会报告一次全民健身、青少年和学校体育工作。"},{"i":109,"n":"第一百零九条","txt":"国家机关及其工作人员违反本法规定，有下列行为之一的，由其所在单位、主管部门或者上级机关责令改正；对负有责任的领导人员和直接责任人员依法给予处分："},{"i":110,"n":"第一百一十条","txt":"体育组织违反本法规定的，由相关部门责令改正，给予警告，对负有责任的领导人员和直接责任人员依法给予处分；可以限期停止活动，并可责令撤换直接负责的主管人员；情节严重的，予以撤销登记。"},{"i":111,"n":"第一百一十一条","txt":"学校违反本法有关规定的，由有关主管部门责令改正；对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":112,"n":"第一百一十二条","txt":"运动员、教练员、裁判员违反本法规定，有违反体育道德和体育赛事规则，弄虚作假、营私舞弊等行为的，由体育组织按照有关规定给予处理；情节严重、社会影响恶劣的，由县级以上人民政府体育行政部门纳入限制、禁止参加竞技体育活动名单；有违法所得的，没收违法所得，并处一万元以上十万元以下的罚款。"},{"i":113,"n":"第一百一十三条","txt":"体育赛事活动组织者有下列行为之一的，由县级以上地方人民政府体育行政部门责令改正，处五万元以上五十万元以下的罚款；有违法所得的，没收违法所得；情节严重的，给予一年以上三年以下禁止组织体育赛事活动的处罚："},{"i":114,"n":"第一百一十四条","txt":"违反本法规定，侵占、破坏公共体育场地设施的，由县级以上地方人民政府体育行政部门会同有关部门予以制止，责令改正，并可处实际损失五倍以下的罚款。"},{"i":115,"n":"第一百一十五条","txt":"违反本法规定，未经批准临时占用公共体育场地设施的，由县级以上地方人民政府体育行政部门会同有关部门责令限期改正；逾期未改正的，对公共体育场地设施管理单位处十万元以上五十万元以下的罚款；有违法所得的，没收违法所得。"},{"i":116,"n":"第一百一十六条","txt":"未经许可经营高危险性体育项目的，由县级以上地方人民政府体育行政部门会同有关部门责令限期关闭；逾期未关闭的，处十万元以上五十万元以下的罚款；有违法所得的，没收违法所得。"},{"i":117,"n":"第一百一十七条","txt":"运动员违规使用兴奋剂的，由有关体育社会组织、运动员管理单位、体育赛事活动组织者作出取消参赛资格、取消比赛成绩或者禁赛等处理。"},{"i":118,"n":"第一百一十八条","txt":"组织、强迫、欺骗、教唆、引诱运动员在体育运动中使用兴奋剂的，由国务院体育行政部门或者省、自治区、直辖市人民政府体育行政部门没收非法持有的兴奋剂；直接负责的主管人员和其他直接责任人员四年内不得从事体育管理工作和运动员辅助工作；情节严重的，终身不得从事体育管理工作和运动员辅助工作。"},{"i":119,"n":"第一百一十九条","txt":"违反本法规定，造成财产损失或者其他损害的，依法承担民事责任；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":120,"n":"第一百二十条","txt":"任何国家、地区或者组织在国际体育运动中损害中华人民共和国主权、安全、发展利益和尊严的，中华人民共和国可以根据实际情况采取相应措施。"},{"i":121,"n":"第一百二十一条","txt":"中国人民解放军和中国人民武装警察部队开展体育活动的具体办法，由中央军事委员会依照本法制定。"},{"i":122,"n":"第一百二十二条","txt":"本法自2023年1月1日起施行。"}],"cujinkejichengguozhuanhuafa":[{"i":1,"n":"第一条","txt":"为了促进科技成果转化为现实生产力，规范科技成果转化活动，加速科学技术进步，推动经济建设和社会发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称科技成果，是指通过科学研究与技术开发所产生的具有实用价值的成果。职务科技成果，是指执行研究开发机构、高等院校和企业等单位的工作任务，或者主要是利用上述单位的物质技术条件所完成的科技成果。"},{"i":3,"n":"第三条","txt":"科技成果转化活动应当有利于加快实施创新驱动发展战略，促进科技与经济的结合，有利于提高经济效益、社会效益和保护环境、合理利用资源，有利于促进经济建设、社会发展和维护国家安全。"},{"i":4,"n":"第四条","txt":"国家对科技成果转化合理安排财政资金投入，引导社会资金投入，推动科技成果转化资金投入的多元化。"},{"i":5,"n":"第五条","txt":"国务院和地方各级人民政府应当加强科技、财政、投资、税收、人才、产业、金融、政府采购、军民融合等政策协同，为科技成果转化创造良好环境。"},{"i":6,"n":"第六条","txt":"国家鼓励科技成果首先在中国境内实施。中国单位或者个人向境外的组织、个人转让或者许可其实施科技成果的，应当遵守相关法律、行政法规以及国家有关规定。"},{"i":7,"n":"第七条","txt":"国家为了国家安全、国家利益和重大社会公共利益的需要，可以依法组织实施或者许可他人实施相关科技成果。"},{"i":8,"n":"第八条","txt":"国务院科学技术行政部门、经济综合管理部门和其他有关行政部门依照国务院规定的职责，管理、指导和协调科技成果转化工作。"},{"i":9,"n":"第九条","txt":"国务院和地方各级人民政府应当将科技成果的转化纳入国民经济和社会发展计划，并组织协调实施有关科技成果的转化。"},{"i":10,"n":"第十条","txt":"利用财政资金设立应用类科技项目和其他相关科技项目，有关行政部门、管理机构应当改进和完善科研组织管理方式，在制定相关科技规划、计划和编制项目指南时应当听取相关行业、企业的意见；在组织实施应用类科技项目时，应当明确项目承担者的科技成果转化义务，加强知识产权管理，并将科技成果转化和知识产权创造、运用作为立项和验收的重要内容和依据。"},{"i":11,"n":"第十一条","txt":"国家建立、完善科技报告制度和科技成果信息系统，向社会公布科技项目实施情况以及科技成果和相关知识产权信息，提供科技成果信息查询、筛选等公益服务。公布有关信息不得泄露国家秘密和商业秘密。对不予公布的信息，有关部门应当及时告知相关科技项目承担者。"},{"i":12,"n":"第十二条","txt":"对下列科技成果转化项目，国家通过政府采购、研究开发资助、发布产业技术指导目录、示范推广等方式予以支持："},{"i":13,"n":"第十三条","txt":"国家通过制定政策措施，提倡和鼓励采用先进技术、工艺和装备，不断改进、限制使用或者淘汰落后技术、工艺和装备。"},{"i":14,"n":"第十四条","txt":"国家加强标准制定工作，对新技术、新工艺、新材料、新产品依法及时制定国家标准、行业标准，积极参与国际标准的制定，推动先进适用技术推广和应用。"},{"i":15,"n":"第十五条","txt":"各级人民政府组织实施的重点科技成果转化项目，可以由有关部门组织采用公开招标的方式实施转化。有关部门应当对中标单位提供招标时确定的资助或者其他条件。"},{"i":16,"n":"第十六条","txt":"科技成果持有者可以采用下列方式进行科技成果转化："},{"i":17,"n":"第十七条","txt":"国家鼓励研究开发机构、高等院校采取转让、许可或者作价投资等方式，向企业或者其他组织转移科技成果。"},{"i":18,"n":"第十八条","txt":"国家设立的研究开发机构、高等院校对其持有的科技成果，可以自主决定转让、许可或者作价投资，但应当通过协议定价、在技术交易市场挂牌交易、拍卖等方式确定价格。通过协议定价的，应当在本单位公示科技成果名称和拟交易价格。"},{"i":19,"n":"第十九条","txt":"国家设立的研究开发机构、高等院校所取得的职务科技成果，完成人和参加人在不变更职务科技成果权属的前提下，可以根据与本单位的协议进行该项科技成果的转化，并享有协议规定的权益。该单位对上述科技成果转化活动应当予以支持。"},{"i":20,"n":"第二十条","txt":"研究开发机构、高等院校的主管部门以及财政、科学技术等相关行政部门应当建立有利于促进科技成果转化的绩效考核评价体系，将科技成果转化情况作为对相关单位及人员评价、科研资金支持的重要内容和依据之一，并对科技成果转化绩效突出的相关单位及人员加大科研资金支持。"},{"i":21,"n":"第二十一条","txt":"国家设立的研究开发机构、高等院校应当向其主管部门提交科技成果转化情况年度报告，说明本单位依法取得的科技成果数量、实施转化情况以及相关收入分配情况，该主管部门应当按照规定将科技成果转化情况年度报告报送财政、科学技术等相关行政部门。"},{"i":22,"n":"第二十二条","txt":"企业为采用新技术、新工艺、新材料和生产新产品，可以自行发布信息或者委托科技中介服务机构征集其所需的科技成果，或者征寻科技成果转化的合作者。"},{"i":23,"n":"第二十三条","txt":"企业依法有权独立或者与境内外企业、事业单位和其他合作者联合实施科技成果转化。"},{"i":24,"n":"第二十四条","txt":"对利用财政资金设立的具有市场应用前景、产业目标明确的科技项目，政府有关部门、管理机构应当发挥企业在研究开发方向选择、项目实施和成果应用中的主导作用，鼓励企业、研究开发机构、高等院校及其他组织共同实施。"},{"i":25,"n":"第二十五条","txt":"国家鼓励研究开发机构、高等院校与企业相结合，联合实施科技成果转化。"},{"i":26,"n":"第二十六条","txt":"国家鼓励企业与研究开发机构、高等院校及其他组织采取联合建立研究开发平台、技术转移机构或者技术创新联盟等产学研合作方式，共同开展研究开发、成果应用与推广、标准研究与制定等活动。"},{"i":27,"n":"第二十七条","txt":"国家鼓励研究开发机构、高等院校与企业及其他组织开展科技人员交流，根据专业特点、行业领域技术发展需要，聘请企业及其他组织的科技人员兼职从事教学和科研工作，支持本单位的科技人员到企业及其他组织从事科技成果转化活动。"},{"i":28,"n":"第二十八条","txt":"国家支持企业与研究开发机构、高等院校、职业院校及培训机构联合建立学生实习实践培训基地和研究生科研实践工作机构，共同培养专业技术人才和高技能人才。"},{"i":29,"n":"第二十九条","txt":"国家鼓励农业科研机构、农业试验示范单位独立或者与其他单位合作实施农业科技成果转化。"},{"i":30,"n":"第三十条","txt":"国家培育和发展技术市场，鼓励创办科技中介服务机构，为技术交易提供交易场所、信息平台以及信息检索、加工与分析、评估、经纪等服务。"},{"i":31,"n":"第三十一条","txt":"国家支持根据产业和区域发展需要建设公共研究开发平台，为科技成果转化提供技术集成、共性技术研究开发、中间试验和工业性试验、科技成果系统化和工程化开发、技术推广与示范等服务。"},{"i":32,"n":"第三十二条","txt":"国家支持科技企业孵化器、大学科技园等科技企业孵化机构发展，为初创期科技型中小企业提供孵化场地、创业辅导、研究开发与管理咨询等服务。"},{"i":33,"n":"第三十三条","txt":"科技成果转化财政经费，主要用于科技成果转化的引导资金、贷款贴息、补助资金和风险投资以及其他促进科技成果转化的资金用途。"},{"i":34,"n":"第三十四条","txt":"国家依照有关税收法律、行政法规规定对科技成果转化活动实行税收优惠。"},{"i":35,"n":"第三十五条","txt":"国家鼓励银行业金融机构在组织形式、管理机制、金融产品和服务等方面进行创新，鼓励开展知识产权质押贷款、股权质押贷款等贷款业务，为科技成果转化提供金融支持。"},{"i":36,"n":"第三十六条","txt":"国家鼓励保险机构开发符合科技成果转化特点的保险品种，为科技成果转化提供保险服务。"},{"i":37,"n":"第三十七条","txt":"国家完善多层次资本市场，支持企业通过股权交易、依法发行股票和债券等直接融资方式为科技成果转化项目进行融资。"},{"i":38,"n":"第三十八条","txt":"国家鼓励创业投资机构投资科技成果转化项目。"},{"i":39,"n":"第三十九条","txt":"国家鼓励设立科技成果转化基金或者风险基金，其资金来源由国家、地方、企业、事业单位以及其他组织或者个人提供，用于支持高投入、高风险、高产出的科技成果的转化，加速重大科技成果的产业化。"},{"i":40,"n":"第四十条","txt":"科技成果完成单位与其他单位合作进行科技成果转化的，应当依法由合同约定该科技成果有关权益的归属。合同未作约定的，按照下列原则办理："},{"i":41,"n":"第四十一条","txt":"科技成果完成单位与其他单位合作进行科技成果转化的，合作各方应当就保守技术秘密达成协议；当事人不得违反协议或者违反权利人有关保守技术秘密的要求，披露、允许他人使用该技术。"},{"i":42,"n":"第四十二条","txt":"企业、事业单位应当建立健全技术秘密保护制度，保护本单位的技术秘密。职工应当遵守本单位的技术秘密保护制度。"},{"i":43,"n":"第四十三条","txt":"国家设立的研究开发机构、高等院校转化科技成果所获得的收入全部留归本单位，在对完成、转化职务科技成果做出重要贡献的人员给予奖励和报酬后，主要用于科学技术研究开发与成果转化等相关工作。"},{"i":44,"n":"第四十四条","txt":"职务科技成果转化后，由科技成果完成单位对完成、转化该项科技成果做出重要贡献的人员给予奖励和报酬。"},{"i":45,"n":"第四十五条","txt":"科技成果完成单位未规定、也未与科技人员约定奖励和报酬的方式和数额的，按照下列标准对完成、转化职务科技成果做出重要贡献的人员给予奖励和报酬："},{"i":46,"n":"第四十六条","txt":"利用财政资金设立的科技项目的承担者未依照本法规定提交科技报告、汇交科技成果和相关知识产权信息的，由组织实施项目的政府有关部门、管理机构责令改正；情节严重的，予以通报批评，禁止其在一定期限内承担利用财政资金设立的科技项目。"},{"i":47,"n":"第四十七条","txt":"违反本法规定，在科技成果转化活动中弄虚作假，采取欺骗手段，骗取奖励和荣誉称号、诈骗钱财、非法牟利的，由政府有关部门依照管理职责责令改正，取消该奖励和荣誉称号，没收违法所得，并处以罚款。给他人造成经济损失的，依法承担民事赔偿责任。构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"科技服务机构及其从业人员违反本法规定，故意提供虚假的信息、实验结果或者评估意见等欺骗当事人，或者与当事人一方串通欺骗另一方当事人的，由政府有关部门依照管理职责责令改正，没收违法所得，并处以罚款；情节严重的，由工商行政管理部门依法吊销营业执照。给他人造成经济损失的，依法承担民事赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"科学技术行政部门和其他有关部门及其工作人员在科技成果转化中滥用职权、玩忽职守、徇私舞弊的，由任免机关或者监察机关对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"违反本法规定，以唆使窃取、利诱胁迫等手段侵占他人的科技成果，侵犯他人合法权益的，依法承担民事赔偿责任，可以处以罚款；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，职工未经单位允许，泄露本单位的技术秘密，或者擅自转让、变相转让职务科技成果的，参加科技成果转化的有关人员违反与本单位的协议，在离职、离休、退休后约定的期限内从事与原单位相同的科技成果转化活动，给本单位造成经济损失的，依法承担民事赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"本法自1996年10月1日起施行。"}],"baoshouguojiamimifa":[{"i":1,"n":"第一条","txt":"为了保守国家秘密，维护国家安全和利益，保障改革开放和社会主义现代化建设事业的顺利进行，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家秘密是关系国家安全和利益，依照法定程序确定，在一定时间内只限一定范围的人员知悉的事项。"},{"i":3,"n":"第三条","txt":"坚持中国共产党对保守国家秘密（以下简称保密）工作的领导。中央保密工作领导机构领导全国保密工作，研究制定、指导实施国家保密工作战略和重大方针政策，统筹协调国家保密重大事项和重要工作，推进国家保密法治建设。"},{"i":4,"n":"第四条","txt":"保密工作坚持总体国家安全观，遵循党管保密、依法管理，积极防范、突出重点，技管并重、创新发展的原则，既确保国家秘密安全，又便利信息资源合理利用。"},{"i":5,"n":"第五条","txt":"国家秘密受法律保护。"},{"i":6,"n":"第六条","txt":"国家保密行政管理部门主管全国的保密工作。县级以上地方各级保密行政管理部门主管本行政区域的保密工作。"},{"i":7,"n":"第七条","txt":"国家机关和涉及国家秘密的单位（以下简称机关、单位）管理本机关和本单位的保密工作。"},{"i":8,"n":"第八条","txt":"机关、单位应当实行保密工作责任制，依法设置保密工作机构或者指定专人负责保密工作，健全保密管理制度，完善保密防护措施，开展保密宣传教育，加强保密监督检查。"},{"i":9,"n":"第九条","txt":"国家采取多种形式加强保密宣传教育，将保密教育纳入国民教育体系和公务员教育培训体系，鼓励大众传播媒介面向社会进行保密宣传教育，普及保密知识，宣传保密法治，增强全社会的保密意识。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持保密科学技术研究和应用，提升自主创新能力，依法保护保密领域的知识产权。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府应当将保密工作纳入本级国民经济和社会发展规划，所需经费列入本级预算。"},{"i":12,"n":"第十二条","txt":"国家加强保密人才培养和队伍建设，完善相关激励保障机制。"},{"i":13,"n":"第十三条","txt":"下列涉及国家安全和利益的事项，泄露后可能损害国家在政治、经济、国防、外交等领域的安全和利益的，应当确定为国家秘密："},{"i":14,"n":"第十四条","txt":"国家秘密的密级分为绝密、机密、秘密三级。"},{"i":15,"n":"第十五条","txt":"国家秘密及其密级的具体范围（以下简称保密事项范围），由国家保密行政管理部门单独或者会同有关中央国家机关规定。"},{"i":16,"n":"第十六条","txt":"机关、单位主要负责人及其指定的人员为定密责任人，负责本机关、本单位的国家秘密确定、变更和解除工作。"},{"i":17,"n":"第十七条","txt":"确定国家秘密的密级，应当遵守定密权限。"},{"i":18,"n":"第十八条","txt":"机关、单位执行上级确定的国家秘密事项或者办理其他机关、单位确定的国家秘密事项，需要派生定密的，应当根据所执行、办理的国家秘密事项的密级确定。"},{"i":19,"n":"第十九条","txt":"机关、单位对所产生的国家秘密事项，应当按照保密事项范围的规定确定密级，同时确定保密期限和知悉范围；有条件的可以标注密点。"},{"i":20,"n":"第二十条","txt":"国家秘密的保密期限，应当根据事项的性质和特点，按照维护国家安全和利益的需要，限定在必要的期限内；不能确定期限的，应当确定解密的条件。"},{"i":21,"n":"第二十一条","txt":"国家秘密的知悉范围，应当根据工作需要限定在最小范围。"},{"i":22,"n":"第二十二条","txt":"机关、单位对承载国家秘密的纸介质、光介质、电磁介质等载体（以下简称国家秘密载体）以及属于国家秘密的设备、产品，应当作出国家秘密标志。"},{"i":23,"n":"第二十三条","txt":"国家秘密的密级、保密期限和知悉范围，应当根据情况变化及时变更。国家秘密的密级、保密期限和知悉范围的变更，由原定密机关、单位决定，也可以由其上级机关决定。"},{"i":24,"n":"第二十四条","txt":"机关、单位应当每年审核所确定的国家秘密。"},{"i":25,"n":"第二十五条","txt":"机关、单位对是否属于国家秘密或者属于何种密级不明确或者有争议的，由国家保密行政管理部门或者省、自治区、直辖市保密行政管理部门按照国家保密规定确定。"},{"i":26,"n":"第二十六条","txt":"国家秘密载体的制作、收发、传递、使用、复制、保存、维修和销毁，应当符合国家保密规定。"},{"i":27,"n":"第二十七条","txt":"属于国家秘密的设备、产品的研制、生产、运输、使用、保存、维修和销毁，应当符合国家保密规定。"},{"i":28,"n":"第二十八条","txt":"机关、单位应当加强对国家秘密载体的管理，任何组织和个人不得有下列行为："},{"i":29,"n":"第二十九条","txt":"禁止非法复制、记录、存储国家秘密。"},{"i":30,"n":"第三十条","txt":"存储、处理国家秘密的计算机信息系统（以下简称涉密信息系统）按照涉密程度实行分级保护。"},{"i":31,"n":"第三十一条","txt":"机关、单位应当加强对信息系统、信息设备的保密管理，建设保密自监管设施，及时发现并处置安全保密风险隐患。任何组织和个人不得有下列行为："},{"i":32,"n":"第三十二条","txt":"用于保护国家秘密的安全保密产品和保密技术装备应当符合国家保密规定和标准。"},{"i":33,"n":"第三十三条","txt":"报刊、图书、音像制品、电子出版物的编辑、出版、印制、发行，广播节目、电视节目、电影的制作和播放，网络信息的制作、复制、发布、传播，应当遵守国家保密规定。"},{"i":34,"n":"第三十四条","txt":"网络运营者应当加强对其用户发布的信息的管理，配合监察机关、保密行政管理部门、公安机关、国家安全机关对涉嫌泄露国家秘密案件进行调查处理；发现利用互联网及其他公共信息网络发布的信息涉嫌泄露国家秘密的，应当立即停止传输该信息，保存有关记录，向保密行政管理部门或者公安机关、国家安全机关报告；应当根据保密行政管理部门或者公安机关、国家安全机关的要求，删除涉及泄露国家秘密的信息，并对有关设备进行技术处理。"},{"i":35,"n":"第三十五条","txt":"机关、单位应当依法对拟公开的信息进行保密审查，遵守国家保密规定。"},{"i":36,"n":"第三十六条","txt":"开展涉及国家秘密的数据处理活动及其安全监管应当符合国家保密规定。"},{"i":37,"n":"第三十七条","txt":"机关、单位向境外或者向境外在中国境内设立的组织、机构提供国家秘密，任用、聘用的境外人员因工作需要知悉国家秘密的，按照国家有关规定办理。"},{"i":38,"n":"第三十八条","txt":"举办会议或者其他活动涉及国家秘密的，主办单位应当采取保密措施，并对参加人员进行保密教育，提出具体保密要求。"},{"i":39,"n":"第三十九条","txt":"机关、单位应当将涉及绝密级或者较多机密级、秘密级国家秘密的机构确定为保密要害部门，将集中制作、存放、保管国家秘密载体的专门场所确定为保密要害部位，按照国家保密规定和标准配备、使用必要的技术防护设施、设备。"},{"i":40,"n":"第四十条","txt":"军事禁区、军事管理区和属于国家秘密不对外开放的其他场所、部位，应当采取保密措施，未经有关部门批准，不得擅自决定对外开放或者扩大开放范围。"},{"i":41,"n":"第四十一条","txt":"从事涉及国家秘密业务的企业事业单位，应当具备相应的保密管理能力，遵守国家保密规定。"},{"i":42,"n":"第四十二条","txt":"采购涉及国家秘密的货物、服务的机关、单位，直接涉及国家秘密的工程建设、设计、施工、监理等单位，应当遵守国家保密规定。"},{"i":43,"n":"第四十三条","txt":"在涉密岗位工作的人员（以下简称涉密人员），按照涉密程度分为核心涉密人员、重要涉密人员和一般涉密人员，实行分类管理。"},{"i":44,"n":"第四十四条","txt":"机关、单位应当建立健全涉密人员管理制度，明确涉密人员的权利、岗位责任和要求，对涉密人员履行职责情况开展经常性的监督检查。"},{"i":45,"n":"第四十五条","txt":"涉密人员出境应当经有关部门批准，有关机关认为涉密人员出境将对国家安全造成危害或者对国家利益造成重大损失的，不得批准出境。"},{"i":46,"n":"第四十六条","txt":"涉密人员离岗离职应当遵守国家保密规定。机关、单位应当开展保密教育提醒，清退国家秘密载体，实行脱密期管理。涉密人员在脱密期内，不得违反规定就业和出境，不得以任何方式泄露国家秘密；脱密期结束后，应当遵守国家保密规定，对知悉的国家秘密继续履行保密义务。涉密人员严重违反离岗离职及脱密期国家保密规定的，机关、单位应当及时报告同级保密行政管理部门，由保密行政管理部门会同有关部门依法采取处置措施。"},{"i":47,"n":"第四十七条","txt":"国家工作人员或者其他公民发现国家秘密已经泄露或者可能泄露时，应当立即采取补救措施并及时报告有关机关、单位。机关、单位接到报告后，应当立即作出处理，并及时向保密行政管理部门报告。"},{"i":48,"n":"第四十八条","txt":"国家保密行政管理部门依照法律、行政法规的规定，制定保密规章和国家保密标准。"},{"i":49,"n":"第四十九条","txt":"保密行政管理部门依法组织开展保密宣传教育、保密检查、保密技术防护、保密违法案件调查处理工作，对保密工作进行指导和监督管理。"},{"i":50,"n":"第五十条","txt":"保密行政管理部门发现国家秘密确定、变更或者解除不当的，应当及时通知有关机关、单位予以纠正。"},{"i":51,"n":"第五十一条","txt":"保密行政管理部门依法对机关、单位遵守保密法律法规和相关制度的情况进行检查；涉嫌保密违法的，应当及时调查处理或者组织、督促有关机关、单位调查处理；涉嫌犯罪的，应当依法移送监察机关、司法机关处理。"},{"i":52,"n":"第五十二条","txt":"保密行政管理部门在保密检查和案件调查处理中，可以依法查阅有关材料、询问人员、记录情况，先行登记保存有关设施、设备、文件资料等；必要时，可以进行保密技术检测。"},{"i":53,"n":"第五十三条","txt":"办理涉嫌泄露国家秘密案件的机关，需要对有关事项是否属于国家秘密、属于何种密级进行鉴定的，由国家保密行政管理部门或者省、自治区、直辖市保密行政管理部门鉴定。"},{"i":54,"n":"第五十四条","txt":"机关、单位对违反国家保密规定的人员不依法给予处分的，保密行政管理部门应当建议纠正；对拒不纠正的，提请其上一级机关或者监察机关对该机关、单位负有责任的领导人员和直接责任人员依法予以处理。"},{"i":55,"n":"第五十五条","txt":"设区的市级以上保密行政管理部门建立保密风险评估机制、监测预警制度、应急处置制度，会同有关部门开展信息收集、分析、通报工作。"},{"i":56,"n":"第五十六条","txt":"保密协会等行业组织依照法律、行政法规的规定开展活动，推动行业自律，促进行业健康发展。"},{"i":57,"n":"第五十七条","txt":"违反本法规定，有下列情形之一，根据情节轻重，依法给予处分；有违法所得的，没收违法所得："},{"i":58,"n":"第五十八条","txt":"机关、单位违反本法规定，发生重大泄露国家秘密案件的，依法对直接负责的主管人员和其他直接责任人员给予处分。不适用处分的人员，由保密行政管理部门督促其主管部门予以处理。"},{"i":59,"n":"第五十九条","txt":"网络运营者违反本法第三十四条规定的，由公安机关、国家安全机关、电信主管部门、保密行政管理部门按照各自职责分工依法予以处罚。"},{"i":60,"n":"第六十条","txt":"取得保密资质的企业事业单位违反国家保密规定的，由保密行政管理部门责令限期整改，给予警告或者通报批评；有违法所得的，没收违法所得；情节严重的，暂停涉密业务、降低资质等级；情节特别严重的，吊销保密资质。"},{"i":61,"n":"第六十一条","txt":"保密行政管理部门的工作人员在履行保密管理职责中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"中国人民解放军和中国人民武装警察部队开展保密工作的具体规定，由中央军事委员会根据本法制定。"},{"i":64,"n":"第六十四条","txt":"机关、单位对履行职能过程中产生或者获取的不属于国家秘密但泄露后会造成一定不利影响的事项，适用工作秘密管理办法采取必要的保护措施。工作秘密管理办法另行规定。"},{"i":65,"n":"第六十五条","txt":"本法自2024年5月1日起施行。"}],"gonggongtushuguanfa":[{"i":1,"n":"第一条","txt":"为了促进公共图书馆事业发展，发挥公共图书馆功能，保障公民基本文化权益，提高公民科学文化素质和社会文明程度，传承人类文明，坚定文化自信，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称公共图书馆，是指向社会公众免费开放，收集、整理、保存文献信息并提供查询、借阅及相关服务，开展社会教育的公共文化设施。"},{"i":3,"n":"第三条","txt":"公共图书馆是社会主义公共文化服务体系的重要组成部分，应当将推动、引导、服务全民阅读作为重要任务。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将公共图书馆事业纳入本级国民经济和社会发展规划，将公共图书馆建设纳入城乡规划和土地利用总体规划，加大对政府设立的公共图书馆的投入，将所需经费列入本级政府预算，并及时、足额拨付。"},{"i":5,"n":"第五条","txt":"国务院文化主管部门负责全国公共图书馆的管理工作。国务院其他有关部门在各自职责范围内负责与公共图书馆管理有关的工作。"},{"i":6,"n":"第六条","txt":"国家鼓励公民、法人和其他组织依法向公共图书馆捐赠，并依法给予税收优惠。"},{"i":7,"n":"第七条","txt":"国家扶持革命老区、民族地区、边疆地区和贫困地区公共图书馆事业的发展。"},{"i":8,"n":"第八条","txt":"国家鼓励和支持发挥科技在公共图书馆建设、管理和服务中的作用，推动运用现代信息技术和传播技术，提高公共图书馆的服务效能。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持在公共图书馆领域开展国际交流与合作。"},{"i":10,"n":"第十条","txt":"公共图书馆应当遵守有关知识产权保护的法律、行政法规规定，依法保护和使用文献信息。"},{"i":11,"n":"第十一条","txt":"公共图书馆行业组织应当依法制定行业规范，加强行业自律，维护会员合法权益，指导、督促会员提高服务质量。"},{"i":12,"n":"第十二条","txt":"对在公共图书馆事业发展中作出突出贡献的组织和个人，按照国家有关规定给予表彰和奖励。"},{"i":13,"n":"第十三条","txt":"国家建立覆盖城乡、便捷实用的公共图书馆服务网络。公共图书馆服务网络建设坚持政府主导，鼓励社会参与。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府应当设立公共图书馆。"},{"i":15,"n":"第十五条","txt":"设立公共图书馆应当具备下列条件："},{"i":16,"n":"第十六条","txt":"公共图书馆章程应当包括名称、馆址、办馆宗旨、业务范围、管理制度及有关规则、终止程序和剩余财产的处理方案等事项。"},{"i":17,"n":"第十七条","txt":"公共图书馆的设立、变更、终止应当按照国家有关规定办理登记手续。"},{"i":18,"n":"第十八条","txt":"省、自治区、直辖市人民政府文化主管部门应当在其网站上及时公布本行政区域内公共图书馆的名称、馆址、联系方式、馆藏文献信息概况、主要服务内容和方式等信息。"},{"i":19,"n":"第十九条","txt":"政府设立的公共图书馆馆长应当具备相应的文化水平、专业知识和组织管理能力。"},{"i":20,"n":"第二十条","txt":"公共图书馆可以以捐赠者姓名、名称命名文献信息专藏或者专题活动。"},{"i":21,"n":"第二十一条","txt":"公共图书馆终止的，应当依照有关法律、行政法规的规定处理其剩余财产。"},{"i":22,"n":"第二十二条","txt":"国家设立国家图书馆，主要承担国家文献信息战略保存、国家书目和联合目录编制、为国家立法和决策服务、组织全国古籍保护、开展图书馆发展研究和国际交流、为其他图书馆提供业务指导和技术支持等职能。国家图书馆同时具有本法规定的公共图书馆的功能。"},{"i":23,"n":"第二十三条","txt":"国家推动公共图书馆建立健全法人治理结构，吸收有关方面代表、专业人士和社会公众参与管理。"},{"i":24,"n":"第二十四条","txt":"公共图书馆应当根据办馆宗旨和服务对象的需求，广泛收集文献信息；政府设立的公共图书馆还应当系统收集地方文献信息，保存和传承地方文化。"},{"i":25,"n":"第二十五条","txt":"公共图书馆可以通过采购、接受交存或者捐赠等合法方式收集文献信息。"},{"i":26,"n":"第二十六条","txt":"出版单位应当按照国家有关规定向国家图书馆和所在地省级公共图书馆交存正式出版物。"},{"i":27,"n":"第二十七条","txt":"公共图书馆应当按照国家公布的标准、规范对馆藏文献信息进行整理，建立馆藏文献信息目录，并依法通过其网站或者其他方式向社会公开。"},{"i":28,"n":"第二十八条","txt":"公共图书馆应当妥善保存馆藏文献信息，不得随意处置；确需处置的，应当遵守国务院文化主管部门有关处置文献信息的规定。"},{"i":29,"n":"第二十九条","txt":"公共图书馆应当定期对其设施设备进行检查维护，确保正常运行。"},{"i":30,"n":"第三十条","txt":"公共图书馆应当加强馆际交流与合作。国家支持公共图书馆开展联合采购、联合编目、联合服务，实现文献信息的共建共享，促进文献信息的有效利用。"},{"i":31,"n":"第三十一条","txt":"县级人民政府应当因地制宜建立符合当地特点的以县级公共图书馆为总馆，乡镇（街道）综合文化站、村（社区）图书室等为分馆或者基层服务点的总分馆制，完善数字化、网络化服务体系和配送体系，实现通借通还，促进公共图书馆服务向城乡基层延伸。总馆应当加强对分馆和基层服务点的业务指导。"},{"i":32,"n":"第三十二条","txt":"公共图书馆馆藏文献信息属于档案、文物的，公共图书馆可以与档案馆、博物馆、纪念馆等单位相互交换重复件、复制件或者目录，联合举办展览，共同编辑出版有关史料或者进行史料研究。"},{"i":33,"n":"第三十三条","txt":"公共图书馆应当按照平等、开放、共享的要求向社会公众提供服务。"},{"i":34,"n":"第三十四条","txt":"政府设立的公共图书馆应当设置少年儿童阅览区域，根据少年儿童的特点配备相应的专业人员，开展面向少年儿童的阅读指导和社会教育活动，并为学校开展有关课外活动提供支持。有条件的地区可以单独设立少年儿童图书馆。"},{"i":35,"n":"第三十五条","txt":"政府设立的公共图书馆应当根据自身条件，为国家机关制定法律、法规、政策和开展有关问题研究，提供文献信息和相关咨询服务。"},{"i":36,"n":"第三十六条","txt":"公共图书馆应当通过开展阅读指导、读书交流、演讲诵读、图书互换共享等活动，推广全民阅读。"},{"i":37,"n":"第三十七条","txt":"公共图书馆向社会公众提供文献信息，应当遵守有关法律、行政法规的规定，不得向未成年人提供内容不适宜的文献信息。"},{"i":38,"n":"第三十八条","txt":"公共图书馆应当通过其网站或者其他方式向社会公告本馆的服务内容、开放时间、借阅规则等；因故闭馆或者更改开放时间的，除遇不可抗力外，应当提前公告。"},{"i":39,"n":"第三十九条","txt":"政府设立的公共图书馆应当通过流动服务设施、自助服务设施等为社会公众提供便捷服务。"},{"i":40,"n":"第四十条","txt":"国家构建标准统一、互联互通的公共图书馆数字服务网络，支持数字阅读产品开发和数字资源保存技术研究，推动公共图书馆利用数字化、网络化技术向社会公众提供便捷服务。"},{"i":41,"n":"第四十一条","txt":"政府设立的公共图书馆应当加强馆内古籍的保护，根据自身条件采用数字化、影印或者缩微技术等推进古籍的整理、出版和研究利用，并通过巡回展览、公益性讲座、善本再造、创意产品开发等方式，加强古籍宣传，传承发展中华优秀传统文化。"},{"i":42,"n":"第四十二条","txt":"公共图书馆应当改善服务条件、提高服务水平，定期公告服务开展情况，听取读者意见，建立投诉渠道，完善反馈机制，接受社会监督。"},{"i":43,"n":"第四十三条","txt":"公共图书馆应当妥善保护读者的个人信息、借阅信息以及其他可能涉及读者隐私的信息，不得出售或者以其他方式非法向他人提供。"},{"i":44,"n":"第四十四条","txt":"读者应当遵守公共图书馆的相关规定，自觉维护公共图书馆秩序，爱护公共图书馆的文献信息、设施设备，合法利用文献信息；借阅文献信息的，应当按照规定时限归还。"},{"i":45,"n":"第四十五条","txt":"国家采取政府购买服务等措施，对公民、法人和其他组织设立的公共图书馆提供服务给予扶持。"},{"i":46,"n":"第四十六条","txt":"国家鼓励公民参与公共图书馆志愿服务。县级以上人民政府文化主管部门应当对公共图书馆志愿服务给予必要的指导和支持。"},{"i":47,"n":"第四十七条","txt":"国务院文化主管部门和省、自治区、直辖市人民政府文化主管部门应当制定公共图书馆服务规范，对公共图书馆的服务质量和水平进行考核。考核应当吸收社会公众参与。考核结果应当向社会公布，并作为对公共图书馆给予补贴或者奖励等的依据。"},{"i":48,"n":"第四十八条","txt":"国家支持公共图书馆加强与学校图书馆、科研机构图书馆以及其他类型图书馆的交流与合作，开展联合服务。"},{"i":49,"n":"第四十九条","txt":"公共图书馆从事或者允许其他组织、个人在馆内从事危害国家安全、损害社会公共利益活动的，由文化主管部门责令改正，没收违法所得；情节严重的，可以责令停业整顿、关闭；对直接负责的主管人员和其他直接责任人员依法追究法律责任。"},{"i":50,"n":"第五十条","txt":"公共图书馆及其工作人员有下列行为之一的，由文化主管部门责令改正，没收违法所得："},{"i":51,"n":"第五十一条","txt":"出版单位未按照国家有关规定交存正式出版物的，由出版主管部门依照有关出版管理的法律、行政法规规定给予处罚。"},{"i":52,"n":"第五十二条","txt":"文化主管部门或者其他有关部门及其工作人员在公共图书馆管理工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":53,"n":"第五十三条","txt":"损坏公共图书馆的文献信息、设施设备或者未按照规定时限归还所借文献信息，造成财产损失或者其他损害的，依法承担民事责任。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"本法自2018年1月1日起施行。"}],"gonggongwenhuafuwubaozhangfa":[{"i":1,"n":"第一条","txt":"为了加强公共文化服务体系建设，丰富人民群众精神文化生活，传承中华优秀传统文化，弘扬社会主义核心价值观，增强文化自信，促进中国特色社会主义文化繁荣发展，提高全民族文明素质，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称公共文化服务，是指由政府主导、社会力量参与，以满足公民基本文化需求为主要目的而提供的公共文化设施、文化产品、文化活动以及其他相关服务。"},{"i":3,"n":"第三条","txt":"公共文化服务应当坚持社会主义先进文化前进方向，坚持以人民为中心，坚持以社会主义核心价值观为引领；应当按照“百花齐放、百家争鸣”的方针，支持优秀公共文化产品的创作生产，丰富公共文化服务内容。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将公共文化服务纳入本级国民经济和社会发展规划，按照公益性、基本性、均等性、便利性的要求，加强公共文化设施建设，完善公共文化服务体系，提高公共文化服务效能。"},{"i":5,"n":"第五条","txt":"国务院根据公民基本文化需求和经济社会发展水平，制定并调整国家基本公共文化服务指导标准。"},{"i":6,"n":"第六条","txt":"国务院建立公共文化服务综合协调机制，指导、协调、推动全国公共文化服务工作。国务院文化主管部门承担综合协调具体职责。"},{"i":7,"n":"第七条","txt":"国务院文化主管部门、新闻出版广电主管部门依照本法和国务院规定的职责负责全国的公共文化服务工作；国务院其他有关部门在各自职责范围内负责相关公共文化服务工作。"},{"i":8,"n":"第八条","txt":"国家扶助革命老区、民族地区、边疆地区、贫困地区的公共文化服务，促进公共文化服务均衡协调发展。"},{"i":9,"n":"第九条","txt":"各级人民政府应当根据未成年人、老年人、残疾人和流动人口等群体的特点与需求，提供相应的公共文化服务。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持公共文化服务与学校教育相结合，充分发挥公共文化服务的社会教育功能，提高青少年思想道德和科学文化素质。"},{"i":11,"n":"第十一条","txt":"国家鼓励和支持发挥科技在公共文化服务中的作用，推动运用现代信息技术和传播技术，提高公众的科学素养和公共文化服务水平。"},{"i":12,"n":"第十二条","txt":"国家鼓励和支持在公共文化服务领域开展国际合作与交流。"},{"i":13,"n":"第十三条","txt":"国家鼓励和支持公民、法人和其他组织参与公共文化服务。"},{"i":14,"n":"第十四条","txt":"本法所称公共文化设施是指用于提供公共文化服务的建筑物、场地和设备，主要包括图书馆、博物馆、文化馆（站）、美术馆、科技馆、纪念馆、体育场馆、工人文化宫、青少年宫、妇女儿童活动中心、老年人活动中心、乡镇（街道）和村（社区）基层综合性文化服务中心、农家（职工）书屋、公共阅报栏（屏）、广播电视播出传输覆盖设施、公共数字文化服务点等。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府应当将公共文化设施建设纳入本级城乡规划，根据国家基本公共文化服务指导标准、省级基本公共文化服务实施标准，结合当地经济社会发展水平、人口状况、环境条件、文化特色，合理确定公共文化设施的种类、数量、规模以及布局，形成场馆服务、流动服务和数字服务相结合的公共文化设施网络。"},{"i":16,"n":"第十六条","txt":"公共文化设施的建设用地，应当符合土地利用总体规划和城乡规划，并依照法定程序审批。"},{"i":17,"n":"第十七条","txt":"公共文化设施的设计和建设，应当符合实用、安全、科学、美观、环保、节约的要求和国家规定的标准，并配置无障碍设施设备。"},{"i":18,"n":"第十八条","txt":"地方各级人民政府可以采取新建、改建、扩建、合建、租赁、利用现有公共设施等多种方式，加强乡镇（街道）、村（社区）基层综合性文化服务中心建设，推动基层有关公共设施的统一管理、综合利用，并保障其正常运行。"},{"i":19,"n":"第十九条","txt":"任何单位和个人不得擅自拆除公共文化设施，不得擅自改变公共文化设施的功能、用途或者妨碍其正常运行，不得侵占、挪用公共文化设施，不得将公共文化设施用于与公共文化服务无关的商业经营活动。"},{"i":20,"n":"第二十条","txt":"公共文化设施管理单位应当按照国家规定的标准，配置和更新必需的服务内容和设备，加强公共文化设施经常性维护管理工作，保障公共文化设施的正常使用和运转。"},{"i":21,"n":"第二十一条","txt":"公共文化设施管理单位应当建立健全管理制度和服务规范，建立公共文化设施资产统计报告制度和公共文化服务开展情况的年报制度。"},{"i":22,"n":"第二十二条","txt":"公共文化设施管理单位应当建立健全安全管理制度，开展公共文化设施及公众活动的安全评价，依法配备安全保护设备和人员，保障公共文化设施和公众活动安全。"},{"i":23,"n":"第二十三条","txt":"各级人民政府应当建立有公众参与的公共文化设施使用效能考核评价制度，公共文化设施管理单位应当根据评价结果改进工作，提高服务质量。"},{"i":24,"n":"第二十四条","txt":"国家推动公共图书馆、博物馆、文化馆等公共文化设施管理单位根据其功能定位建立健全法人治理结构，吸收有关方面代表、专业人士和公众参与管理。"},{"i":25,"n":"第二十五条","txt":"国家鼓励和支持公民、法人和其他组织兴建、捐建或者与政府部门合作建设公共文化设施，鼓励公民、法人和其他组织依法参与公共文化设施的运营和管理。"},{"i":26,"n":"第二十六条","txt":"公众在使用公共文化设施时，应当遵守公共秩序，爱护公共设施，不得损坏公共设施设备和物品。"},{"i":27,"n":"第二十七条","txt":"各级人民政府应当充分利用公共文化设施，促进优秀公共文化产品的提供和传播，支持开展全民阅读、全民普法、全民健身、全民科普和艺术普及、优秀传统文化传承活动。"},{"i":28,"n":"第二十八条","txt":"设区的市级、县级地方人民政府应当根据国家基本公共文化服务指导标准和省、自治区、直辖市基本公共文化服务实施标准，结合当地实际，制定公布本行政区域公共文化服务目录并组织实施。"},{"i":29,"n":"第二十九条","txt":"公益性文化单位应当完善服务项目、丰富服务内容，创造条件向公众提供免费或者优惠的文艺演出、陈列展览、电影放映、广播电视节目收听收看、阅读服务、艺术培训等，并为公众开展文化活动提供支持和帮助。"},{"i":30,"n":"第三十条","txt":"基层综合性文化服务中心应当加强资源整合，建立完善公共文化服务网络，充分发挥统筹服务功能，为公众提供书报阅读、影视观赏、戏曲表演、普法教育、艺术普及、科学普及、广播播送、互联网上网和群众性文化体育活动等公共文化服务，并根据其功能特点，因地制宜提供其他公共服务。"},{"i":31,"n":"第三十一条","txt":"公共文化设施应当根据其功能、特点，按照国家有关规定，向公众免费或者优惠开放。"},{"i":32,"n":"第三十二条","txt":"国家鼓励和支持机关、学校、企业事业单位的文化体育设施向公众开放。"},{"i":33,"n":"第三十三条","txt":"国家统筹规划公共数字文化建设，构建标准统一、互联互通的公共数字文化服务网络，建设公共文化信息资源库，实现基层网络服务共建共享。"},{"i":34,"n":"第三十四条","txt":"地方各级人民政府应当采取多种方式，因地制宜提供流动文化服务。"},{"i":35,"n":"第三十五条","txt":"国家重点增加农村地区图书、报刊、戏曲、电影、广播电视节目、网络信息内容、节庆活动、体育健身活动等公共文化产品供给，促进城乡公共文化服务均等化。"},{"i":36,"n":"第三十六条","txt":"地方各级人民政府应当根据当地实际情况，在人员流动量较大的公共场所、务工人员较为集中的区域以及留守妇女儿童较为集中的农村地区，配备必要的设施，采取多种形式，提供便利可及的公共文化服务。"},{"i":37,"n":"第三十七条","txt":"国家鼓励公民主动参与公共文化服务，自主开展健康文明的群众性文化体育活动；地方各级人民政府应当给予必要的指导、支持和帮助。"},{"i":38,"n":"第三十八条","txt":"地方各级人民政府应当加强面向在校学生的公共文化服务，支持学校开展适合在校学生特点的文化体育活动，促进德智体美教育。"},{"i":39,"n":"第三十九条","txt":"地方各级人民政府应当支持军队基层文化建设，丰富军营文化体育活动，加强军民文化融合。"},{"i":40,"n":"第四十条","txt":"国家加强民族语言文字文化产品的供给，加强优秀公共文化产品的民族语言文字译制及其在民族地区的传播，鼓励和扶助民族文化产品的创作生产，支持开展具有民族特色的群众性文化体育活动。"},{"i":41,"n":"第四十一条","txt":"国务院和省、自治区、直辖市人民政府制定政府购买公共文化服务的指导性意见和目录。国务院有关部门和县级以上地方人民政府应当根据指导性意见和目录，结合实际情况，确定购买的具体项目和内容，及时向社会公布。"},{"i":42,"n":"第四十二条","txt":"国家鼓励和支持公民、法人和其他组织通过兴办实体、资助项目、赞助活动、提供设施、捐赠产品等方式，参与提供公共文化服务。"},{"i":43,"n":"第四十三条","txt":"国家倡导和鼓励公民、法人和其他组织参与文化志愿服务。"},{"i":44,"n":"第四十四条","txt":"任何组织和个人不得利用公共文化设施、文化产品、文化活动以及其他相关服务，从事危害国家安全、损害社会公共利益和其他违反法律法规的活动。"},{"i":45,"n":"第四十五条","txt":"国务院和地方各级人民政府应当根据公共文化服务的事权和支出责任，将公共文化服务经费纳入本级预算，安排公共文化服务所需资金。"},{"i":46,"n":"第四十六条","txt":"国务院和省、自治区、直辖市人民政府应当增加投入，通过转移支付等方式，重点扶助革命老区、民族地区、边疆地区、贫困地区开展公共文化服务。"},{"i":47,"n":"第四十七条","txt":"免费或者优惠开放的公共文化设施，按照国家规定享受补助。"},{"i":48,"n":"第四十八条","txt":"国家鼓励社会资本依法投入公共文化服务，拓宽公共文化服务资金来源渠道。"},{"i":49,"n":"第四十九条","txt":"国家采取政府购买服务等措施，支持公民、法人和其他组织参与提供公共文化服务。"},{"i":50,"n":"第五十条","txt":"公民、法人和其他组织通过公益性社会团体或者县级以上人民政府及其部门，捐赠财产用于公共文化服务的，依法享受税收优惠。"},{"i":51,"n":"第五十一条","txt":"地方各级人民政府应当按照公共文化设施的功能、任务和服务人口规模，合理设置公共文化服务岗位，配备相应专业人员。"},{"i":52,"n":"第五十二条","txt":"国家鼓励和支持文化专业人员、高校毕业生和志愿者到基层从事公共文化服务工作。"},{"i":53,"n":"第五十三条","txt":"国家鼓励和支持公民、法人和其他组织依法成立公共文化服务领域的社会组织，推动公共文化服务社会化、专业化发展。"},{"i":54,"n":"第五十四条","txt":"国家支持公共文化服务理论研究，加强多层次专业人才教育和培训。"},{"i":55,"n":"第五十五条","txt":"县级以上人民政府应当建立健全公共文化服务资金使用的监督和统计公告制度，加强绩效考评，确保资金用于公共文化服务。任何单位和个人不得侵占、挪用公共文化服务资金。"},{"i":56,"n":"第五十六条","txt":"各级人民政府应当加强对公共文化服务工作的监督检查，建立反映公众文化需求的征询反馈制度和有公众参与的公共文化服务考核评价制度，并将考核评价结果作为确定补贴或者奖励的依据。"},{"i":57,"n":"第五十七条","txt":"各级人民政府及有关部门应当及时公开公共文化服务信息，主动接受社会监督。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，地方各级人民政府和县级以上人民政府有关部门未履行公共文化服务保障职责的，由其上级机关或者监察机关责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":59,"n":"第五十九条","txt":"违反本法规定，地方各级人民政府和县级以上人民政府有关部门，有下列行为之一的，由其上级机关或者监察机关责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":60,"n":"第六十条","txt":"违反本法规定，侵占公共文化设施的建设用地或者擅自改变其用途的，由县级以上地方人民政府土地主管部门、城乡规划主管部门依据各自职责责令限期改正；逾期不改正的，由作出决定的机关依法强制执行，或者依法申请人民法院强制执行。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，公共文化设施管理单位有下列情形之一的，由其主管部门责令限期改正；造成严重后果的，对直接负责的主管人员和其他直接责任人员，依法给予处分："},{"i":62,"n":"第六十二条","txt":"违反本法规定，公共文化设施管理单位有下列行为之一的，由其主管部门或者价格主管部门责令限期改正，没收违法所得，违法所得五千元以上的，并处违法所得两倍以上五倍以下罚款；没有违法所得或者违法所得五千元以下的，可以处一万元以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分："},{"i":63,"n":"第六十三条","txt":"违反本法规定，损害他人民事权益的，依法承担民事责任；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":64,"n":"第六十四条","txt":"境外自然人、法人和其他组织在中国境内从事公共文化服务的，应当符合相关法律、行政法规的规定。"},{"i":65,"n":"第六十五条","txt":"本法自2017年3月1日起施行。"}],"gongwuyuanfa":[{"i":1,"n":"第一条","txt":"为了规范公务员的管理，保障公务员的合法权益，加强对公务员的监督，促进公务员正确履职尽责，建设信念坚定、为民服务、勤政务实、敢于担当、清正廉洁的高素质专业化公务员队伍，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称公务员，是指依法履行公职、纳入国家行政编制、由国家财政负担工资福利的工作人员。"},{"i":3,"n":"第三条","txt":"公务员的义务、权利和管理，适用本法。"},{"i":4,"n":"第四条","txt":"公务员制度坚持中国共产党领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，贯彻社会主义初级阶段的基本路线，贯彻新时代中国共产党的组织路线，坚持党管干部原则。"},{"i":5,"n":"第五条","txt":"公务员的管理，坚持公开、平等、竞争、择优的原则，依照法定的权限、条件、标准和程序进行。"},{"i":6,"n":"第六条","txt":"公务员的管理，坚持监督约束与激励保障并重的原则。"},{"i":7,"n":"第七条","txt":"公务员的任用，坚持德才兼备、以德为先，坚持五湖四海、任人唯贤，坚持事业为上、公道正派，突出政治标准，注重工作实绩。"},{"i":8,"n":"第八条","txt":"国家对公务员实行分类管理，提高管理效能和科学化水平。"},{"i":9,"n":"第九条","txt":"公务员就职时应当依照法律规定公开进行宪法宣誓。"},{"i":10,"n":"第十条","txt":"公务员依法履行职责的行为，受法律保护。"},{"i":11,"n":"第十一条","txt":"公务员工资、福利、保险以及录用、奖励、培训、辞退等所需经费，列入财政预算，予以保障。"},{"i":12,"n":"第十二条","txt":"中央公务员主管部门负责全国公务员的综合管理工作。县级以上地方各级公务员主管部门负责本辖区内公务员的综合管理工作。上级公务员主管部门指导下级公务员主管部门的公务员管理工作。各级公务员主管部门指导同级各机关的公务员管理工作。"},{"i":13,"n":"第十三条","txt":"公务员应当具备下列条件："},{"i":14,"n":"第十四条","txt":"公务员应当履行下列义务："},{"i":15,"n":"第十五条","txt":"公务员享有下列权利："},{"i":16,"n":"第十六条","txt":"国家实行公务员职位分类制度。"},{"i":17,"n":"第十七条","txt":"国家实行公务员职务与职级并行制度，根据公务员职位类别和职责设置公务员领导职务、职级序列。"},{"i":18,"n":"第十八条","txt":"公务员领导职务根据宪法、有关法律和机构规格设置。"},{"i":19,"n":"第十九条","txt":"公务员职级在厅局级以下设置。"},{"i":20,"n":"第二十条","txt":"各机关依照确定的职能、规格、编制限额、职数以及结构比例，设置本机关公务员的具体职位，并确定各职位的工作职责和任职资格条件。"},{"i":21,"n":"第二十一条","txt":"公务员的领导职务、职级应当对应相应的级别。公务员领导职务、职级与级别的对应关系，由国家规定。"},{"i":22,"n":"第二十二条","txt":"国家根据人民警察、消防救援人员以及海关、驻外外交机构等公务员的工作特点，设置与其领导职务、职级相对应的衔级。"},{"i":23,"n":"第二十三条","txt":"录用担任一级主任科员以下及其他相当职级层次的公务员，采取公开考试、严格考察、平等竞争、择优录取的办法。"},{"i":24,"n":"第二十四条","txt":"中央机关及其直属机构公务员的录用，由中央公务员主管部门负责组织。地方各级机关公务员的录用，由省级公务员主管部门负责组织，必要时省级公务员主管部门可以授权设区的市级公务员主管部门组织。"},{"i":25,"n":"第二十五条","txt":"报考公务员，除应当具备本法第十三条规定的条件以外，还应当具备省级以上公务员主管部门规定的拟任职位所要求的资格条件。"},{"i":26,"n":"第二十六条","txt":"下列人员不得录用为公务员："},{"i":27,"n":"第二十七条","txt":"录用公务员，应当在规定的编制限额内，并有相应的职位空缺。"},{"i":28,"n":"第二十八条","txt":"录用公务员，应当发布招考公告。招考公告应当载明招考的职位、名额、报考资格条件、报考需要提交的申请材料以及其他报考须知事项。"},{"i":29,"n":"第二十九条","txt":"招录机关根据报考资格条件对报考申请进行审查。报考者提交的申请材料应当真实、准确。"},{"i":30,"n":"第三十条","txt":"公务员录用考试采取笔试和面试等方式进行，考试内容根据公务员应当具备的基本能力和不同职位类别、不同层级机关分别设置。"},{"i":31,"n":"第三十一条","txt":"招录机关根据考试成绩确定考察人选，并进行报考资格复审、考察和体检。"},{"i":32,"n":"第三十二条","txt":"招录机关根据考试成绩、考察情况和体检结果，提出拟录用人员名单，并予以公示。公示期不少于五个工作日。"},{"i":33,"n":"第三十三条","txt":"录用特殊职位的公务员，经省级以上公务员主管部门批准，可以简化程序或者采用其他测评办法。"},{"i":34,"n":"第三十四条","txt":"新录用的公务员试用期为一年。试用期满合格的，予以任职；不合格的，取消录用。"},{"i":35,"n":"第三十五条","txt":"公务员的考核应当按照管理权限，全面考核公务员的德、能、勤、绩、廉，重点考核政治素质和工作实绩。考核指标根据不同职位类别、不同层级机关分别设置。"},{"i":36,"n":"第三十六条","txt":"公务员的考核分为平时考核、专项考核和定期考核等方式。定期考核以平时考核、专项考核为基础。"},{"i":37,"n":"第三十七条","txt":"非领导成员公务员的定期考核采取年度考核的方式。先由个人按照职位职责和有关要求进行总结，主管领导在听取群众意见后，提出考核等次建议，由本机关负责人或者授权的考核委员会确定考核等次。"},{"i":38,"n":"第三十八条","txt":"定期考核的结果分为优秀、称职、基本称职和不称职四个等次。"},{"i":39,"n":"第三十九条","txt":"定期考核的结果作为调整公务员职位、职务、职级、级别、工资以及公务员奖励、培训、辞退的依据。"},{"i":40,"n":"第四十条","txt":"公务员领导职务实行选任制、委任制和聘任制。公务员职级实行委任制和聘任制。"},{"i":41,"n":"第四十一条","txt":"选任制公务员在选举结果生效时即任当选职务；任期届满不再连任或者任期内辞职、被罢免、被撤职的，其所任职务即终止。"},{"i":42,"n":"第四十二条","txt":"委任制公务员试用期满考核合格，职务、职级发生变化，以及其他情形需要任免职务、职级的，应当按照管理权限和规定的程序任免。"},{"i":43,"n":"第四十三条","txt":"公务员任职应当在规定的编制限额和职数内进行，并有相应的职位空缺。"},{"i":44,"n":"第四十四条","txt":"公务员因工作需要在机关外兼职，应当经有关机关批准，并不得领取兼职报酬。"},{"i":45,"n":"第四十五条","txt":"公务员晋升领导职务，应当具备拟任职务所要求的政治素质、工作能力、文化程度和任职经历等方面的条件和资格。"},{"i":46,"n":"第四十六条","txt":"公务员晋升领导职务，按照下列程序办理："},{"i":47,"n":"第四十七条","txt":"厅局级正职以下领导职务出现空缺且本机关没有合适人选的，可以通过适当方式面向社会选拔任职人选。"},{"i":48,"n":"第四十八条","txt":"公务员晋升领导职务的，应当按照有关规定实行任职前公示制度和任职试用期制度。"},{"i":49,"n":"第四十九条","txt":"公务员职级应当逐级晋升，根据个人德才表现、工作实绩和任职资历，参考民主推荐或者民主测评结果确定人选，经公示后，按照管理权限审批。"},{"i":50,"n":"第五十条","txt":"公务员的职务、职级实行能上能下。对不适宜或者不胜任现任职务、职级的，应当进行调整。"},{"i":51,"n":"第五十一条","txt":"对工作表现突出，有显著成绩和贡献，或者有其他突出事迹的公务员或者公务员集体，给予奖励。奖励坚持定期奖励与及时奖励相结合，精神奖励与物质奖励相结合、以精神奖励为主的原则。"},{"i":52,"n":"第五十二条","txt":"公务员或者公务员集体有下列情形之一的，给予奖励："},{"i":53,"n":"第五十三条","txt":"奖励分为：嘉奖、记三等功、记二等功、记一等功、授予称号。"},{"i":54,"n":"第五十四条","txt":"给予公务员或者公务员集体奖励，按照规定的权限和程序决定或者审批。"},{"i":55,"n":"第五十五条","txt":"按照国家规定，可以向参与特定时期、特定领域重大工作的公务员颁发纪念证书或者纪念章。"},{"i":56,"n":"第五十六条","txt":"公务员或者公务员集体有下列情形之一的，撤销奖励："},{"i":57,"n":"第五十七条","txt":"机关应当对公务员的思想政治、履行职责、作风表现、遵纪守法等情况进行监督，开展勤政廉政教育，建立日常管理监督制度。"},{"i":58,"n":"第五十八条","txt":"公务员应当自觉接受监督，按照规定请示报告工作、报告个人有关事项。"},{"i":59,"n":"第五十九条","txt":"公务员应当遵纪守法，不得有下列行为："},{"i":60,"n":"第六十条","txt":"公务员执行公务时，认为上级的决定或者命令有错误的，可以向上级提出改正或者撤销该决定或者命令的意见；上级不改变该决定或者命令，或者要求立即执行的，公务员应当执行该决定或者命令，执行的后果由上级负责，公务员不承担责任；但是，公务员执行明显违法的决定或者命令的，应当依法承担相应的责任。"},{"i":61,"n":"第六十一条","txt":"公务员因违纪违法应当承担纪律责任的，依照本法给予处分或者由监察机关依法给予政务处分；违纪违法行为情节轻微，经批评教育后改正的，可以免予处分。"},{"i":62,"n":"第六十二条","txt":"处分分为：警告、记过、记大过、降级、撤职、开除。"},{"i":63,"n":"第六十三条","txt":"对公务员的处分，应当事实清楚、证据确凿、定性准确、处理恰当、程序合法、手续完备。"},{"i":64,"n":"第六十四条","txt":"公务员在受处分期间不得晋升职务、职级和级别，其中受记过、记大过、降级、撤职处分的，不得晋升工资档次。"},{"i":65,"n":"第六十五条","txt":"公务员受开除以外的处分，在受处分期间有悔改表现，并且没有再发生违纪违法行为的，处分期满后自动解除。"},{"i":66,"n":"第六十六条","txt":"机关根据公务员工作职责的要求和提高公务员素质的需要，对公务员进行分类分级培训。"},{"i":67,"n":"第六十七条","txt":"机关对新录用人员应当在试用期内进行初任培训；对晋升领导职务的公务员应当在任职前或者任职后一年内进行任职培训；对从事专项工作的公务员应当进行专门业务培训；对全体公务员应当进行提高政治素质和工作能力、更新知识的在职培训，其中对专业技术类公务员应当进行专业技术培训。"},{"i":68,"n":"第六十八条","txt":"公务员的培训实行登记管理。"},{"i":69,"n":"第六十九条","txt":"国家实行公务员交流制度。"},{"i":70,"n":"第七十条","txt":"国有企业、高等院校和科研院所以及其他不参照本法管理的事业单位中从事公务的人员，可以调入机关担任领导职务或者四级调研员以上及其他相当层次的职级。"},{"i":71,"n":"第七十一条","txt":"公务员在不同职位之间转任应当具备拟任职位所要求的资格条件，在规定的编制限额和职数内进行。"},{"i":72,"n":"第七十二条","txt":"根据工作需要，机关可以采取挂职方式选派公务员承担重大工程、重大项目、重点任务或者其他专项工作。"},{"i":73,"n":"第七十三条","txt":"公务员应当服从机关的交流决定。"},{"i":74,"n":"第七十四条","txt":"公务员之间有夫妻关系、直系血亲关系、三代以内旁系血亲关系以及近姻亲关系的，不得在同一机关双方直接隶属于同一领导人员的职位或者有直接上下级领导关系的职位工作，也不得在其中一方担任领导职务的机关从事组织、人事、纪检、监察、审计和财务工作。"},{"i":75,"n":"第七十五条","txt":"公务员担任乡级机关、县级机关、设区的市级机关及其有关部门主要领导职务的，应当按照有关规定实行地域回避。"},{"i":76,"n":"第七十六条","txt":"公务员执行公务时，有下列情形之一的，应当回避："},{"i":77,"n":"第七十七条","txt":"公务员有应当回避情形的，本人应当申请回避；利害关系人有权申请公务员回避。其他人员可以向机关提供公务员需要回避的情况。"},{"i":78,"n":"第七十八条","txt":"法律对公务员回避另有规定的，从其规定。"},{"i":79,"n":"第七十九条","txt":"公务员实行国家统一规定的工资制度。"},{"i":80,"n":"第八十条","txt":"公务员工资包括基本工资、津贴、补贴和奖金。"},{"i":81,"n":"第八十一条","txt":"公务员的工资水平应当与国民经济发展相协调、与社会进步相适应。"},{"i":82,"n":"第八十二条","txt":"公务员按照国家规定享受福利待遇。国家根据经济社会发展水平提高公务员的福利待遇。"},{"i":83,"n":"第八十三条","txt":"公务员依法参加社会保险，按照国家规定享受保险待遇。"},{"i":84,"n":"第八十四条","txt":"任何机关不得违反国家规定自行更改公务员工资、福利、保险政策，擅自提高或者降低公务员的工资、福利、保险待遇。任何机关不得扣减或者拖欠公务员的工资。"},{"i":85,"n":"第八十五条","txt":"公务员辞去公职，应当向任免机关提出书面申请。任免机关应当自接到申请之日起三十日内予以审批，其中对领导成员辞去公职的申请，应当自接到申请之日起九十日内予以审批。"},{"i":86,"n":"第八十六条","txt":"公务员有下列情形之一的，不得辞去公职："},{"i":87,"n":"第八十七条","txt":"担任领导职务的公务员，因工作变动依照法律规定需要辞去现任职务的，应当履行辞职手续。"},{"i":88,"n":"第八十八条","txt":"公务员有下列情形之一的，予以辞退："},{"i":89,"n":"第八十九条","txt":"对有下列情形之一的公务员，不得辞退："},{"i":90,"n":"第九十条","txt":"辞退公务员，按照管理权限决定。辞退决定应当以书面形式通知被辞退的公务员，并应当告知辞退依据和理由。"},{"i":91,"n":"第九十一条","txt":"公务员辞职或者被辞退，离职前应当办理公务交接手续，必要时按照规定接受审计。"},{"i":92,"n":"第九十二条","txt":"公务员达到国家规定的退休年龄或者完全丧失工作能力的，应当退休。"},{"i":93,"n":"第九十三条","txt":"公务员符合下列条件之一的，本人自愿提出申请，经任免机关批准，可以提前退休："},{"i":94,"n":"第九十四条","txt":"公务员退休后，享受国家规定的养老金和其他待遇，国家为其生活和健康提供必要的服务和帮助，鼓励发挥个人专长，参与社会发展。"},{"i":95,"n":"第九十五条","txt":"公务员对涉及本人的下列人事处理不服的，可以自知道该人事处理之日起三十日内向原处理机关申请复核；对复核结果不服的，可以自接到复核决定之日起十五日内，按照规定向同级公务员主管部门或者作出该人事处理的机关的上一级机关提出申诉；也可以不经复核，自知道该人事处理之日起三十日内直接提出申诉："},{"i":96,"n":"第九十六条","txt":"原处理机关应当自接到复核申请书后的三十日内作出复核决定，并以书面形式告知申请人。受理公务员申诉的机关应当自受理之日起六十日内作出处理决定；案情复杂的，可以适当延长，但是延长时间不得超过三十日。"},{"i":97,"n":"第九十七条","txt":"公务员申诉的受理机关审查认定人事处理有错误的，原处理机关应当及时予以纠正。"},{"i":98,"n":"第九十八条","txt":"公务员认为机关及其领导人员侵犯其合法权益的，可以依法向上级机关或者监察机关提出控告。受理控告的机关应当按照规定及时处理。"},{"i":99,"n":"第九十九条","txt":"公务员提出申诉、控告，应当尊重事实，不得捏造事实，诬告、陷害他人。对捏造事实，诬告、陷害他人的，依法追究法律责任。"},{"i":100,"n":"第一百条","txt":"机关根据工作需要，经省级以上公务员主管部门批准，可以对专业性较强的职位和辅助性职位实行聘任制。"},{"i":101,"n":"第一百零一条","txt":"机关聘任公务员可以参照公务员考试录用的程序进行公开招聘，也可以从符合条件的人员中直接选聘。"},{"i":102,"n":"第一百零二条","txt":"机关聘任公务员，应当按照平等自愿、协商一致的原则，签订书面的聘任合同，确定机关与所聘公务员双方的权利、义务。聘任合同经双方协商一致可以变更或者解除。"},{"i":103,"n":"第一百零三条","txt":"聘任合同应当具备合同期限，职位及其职责要求，工资、福利、保险待遇，违约责任等条款。"},{"i":104,"n":"第一百零四条","txt":"机关依据本法和聘任合同对所聘公务员进行管理。"},{"i":105,"n":"第一百零五条","txt":"聘任制公务员与所在机关之间因履行聘任合同发生争议的，可以自争议发生之日起六十日内申请仲裁。"},{"i":106,"n":"第一百零六条","txt":"对有下列违反本法规定情形的，由县级以上领导机关或者公务员主管部门按照管理权限，区别不同情况，分别予以责令纠正或者宣布无效；对负有责任的领导人员和直接责任人员，根据情节轻重，给予批评教育、责令检查、诫勉、组织调整、处分；构成犯罪的，依法追究刑事责任："},{"i":107,"n":"第一百零七条","txt":"公务员辞去公职或者退休的，原系领导成员、县处级以上领导职务的公务员在离职三年内，其他公务员在离职两年内，不得到与原工作业务直接相关的企业或者其他营利性组织任职，不得从事与原工作业务直接相关的营利性活动。"},{"i":108,"n":"第一百零八条","txt":"公务员主管部门的工作人员，违反本法规定，滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，给予处分或者由监察机关依法给予政务处分。"},{"i":109,"n":"第一百零九条","txt":"在公务员录用、聘任等工作中，有隐瞒真实信息、弄虚作假、考试作弊、扰乱考试秩序等行为的，由公务员主管部门根据情节作出考试成绩无效、取消资格、限制报考等处理；情节严重的，依法追究法律责任。"},{"i":110,"n":"第一百一十条","txt":"机关因错误的人事处理对公务员造成名誉损害的，应当赔礼道歉、恢复名誉、消除影响；造成经济损失的，应当依法给予赔偿。"},{"i":111,"n":"第一百一十一条","txt":"本法所称领导成员，是指机关的领导人员，不包括机关内设机构担任领导职务的人员。"},{"i":112,"n":"第一百一十二条","txt":"法律、法规授权的具有公共事务管理职能的事业单位中除工勤人员以外的工作人员，经批准参照本法进行管理。"},{"i":113,"n":"第一百一十三条","txt":"本法自2019年6月1日起施行。"}],"gongzhengfa":[{"i":1,"n":"第一条","txt":"为规范公证活动，保障公证机构和公证员依法履行职责，预防纠纷，保障自然人、法人或者其他组织的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"公证是公证机构根据自然人、法人或者其他组织的申请，依照法定程序对民事法律行为、有法律意义的事实和文书的真实性、合法性予以证明的活动。"},{"i":3,"n":"第三条","txt":"公证机构办理公证，应当遵守法律，坚持客观、公正的原则。"},{"i":4,"n":"第四条","txt":"全国设立中国公证协会，省、自治区、直辖市设立地方公证协会。中国公证协会和地方公证协会是社会团体法人。中国公证协会章程由会员代表大会制定，报国务院司法行政部门备案。"},{"i":5,"n":"第五条","txt":"司法行政部门依照本法规定对公证机构、公证员和公证协会进行监督、指导。"},{"i":6,"n":"第六条","txt":"公证机构是依法设立，不以营利为目的，依法独立行使公证职能、承担民事责任的证明机构。"},{"i":7,"n":"第七条","txt":"公证机构按照统筹规划、合理布局的原则，可以在县、不设区的市、设区的市、直辖市或者市辖区设立；在设区的市、直辖市可以设立一个或者若干个公证机构。公证机构不按行政区划层层设立。"},{"i":8,"n":"第八条","txt":"设立公证机构，应当具备下列条件："},{"i":9,"n":"第九条","txt":"设立公证机构，由所在地的司法行政部门报省、自治区、直辖市人民政府司法行政部门按照规定程序批准后，颁发公证机构执业证书。"},{"i":10,"n":"第十条","txt":"公证机构的负责人应当在有三年以上执业经历的公证员中推选产生，由所在地的司法行政部门核准，报省、自治区、直辖市人民政府司法行政部门备案。"},{"i":11,"n":"第十一条","txt":"根据自然人、法人或者其他组织的申请，公证机构办理下列公证事项："},{"i":12,"n":"第十二条","txt":"根据自然人、法人或者其他组织的申请，公证机构可以办理下列事务："},{"i":13,"n":"第十三条","txt":"公证机构不得有下列行为："},{"i":14,"n":"第十四条","txt":"公证机构应当建立业务、财务、资产等管理制度，对公证员的执业行为进行监督，建立执业过错责任追究制度。"},{"i":15,"n":"第十五条","txt":"公证机构应当参加公证执业责任保险。"},{"i":16,"n":"第十六条","txt":"公证员是符合本法规定的条件，在公证机构从事公证业务的执业人员。"},{"i":17,"n":"第十七条","txt":"公证员的数量根据公证业务需要确定。省、自治区、直辖市人民政府司法行政部门应当根据公证机构的设置情况和公证业务的需要核定公证员配备方案，报国务院司法行政部门备案。"},{"i":18,"n":"第十八条","txt":"担任公证员，应当具备下列条件："},{"i":19,"n":"第十九条","txt":"从事法学教学、研究工作，具有高级职称的人员，或者具有本科以上学历，从事审判、检察、法制工作、法律服务满十年的公务员、律师，已经离开原工作岗位，经考核合格的，可以担任公证员。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，不得担任公证员："},{"i":21,"n":"第二十一条","txt":"担任公证员，应当由符合公证员条件的人员提出申请，经公证机构推荐，由所在地的司法行政部门报省、自治区、直辖市人民政府司法行政部门审核同意后，报请国务院司法行政部门任命，并由省、自治区、直辖市人民政府司法行政部门颁发公证员执业证书。"},{"i":22,"n":"第二十二条","txt":"公证员应当遵纪守法，恪守职业道德，依法履行公证职责，保守执业秘密。"},{"i":23,"n":"第二十三条","txt":"公证员不得有下列行为："},{"i":24,"n":"第二十四条","txt":"公证员有下列情形之一的，由所在地的司法行政部门报省、自治区、直辖市人民政府司法行政部门提请国务院司法行政部门予以免职："},{"i":25,"n":"第二十五条","txt":"自然人、法人或者其他组织申请办理公证，可以向住所地、经常居住地、行为地或者事实发生地的公证机构提出。"},{"i":26,"n":"第二十六条","txt":"自然人、法人或者其他组织可以委托他人办理公证，但遗嘱、生存、收养关系等应当由本人办理公证的除外。"},{"i":27,"n":"第二十七条","txt":"申请办理公证的当事人应当向公证机构如实说明申请公证的事项的有关情况，提供真实、合法、充分的证明材料；提供的证明材料不充分的，公证机构可以要求补充。"},{"i":28,"n":"第二十八条","txt":"公证机构办理公证，应当根据不同公证事项的办证规则，分别审查下列事项："},{"i":29,"n":"第二十九条","txt":"公证机构对申请公证的事项以及当事人提供的证明材料，按照有关办证规则需要核实或者对其有疑义的，应当进行核实，或者委托异地公证机构代为核实，有关单位或者个人应当依法予以协助。"},{"i":30,"n":"第三十条","txt":"公证机构经审查，认为申请提供的证明材料真实、合法、充分，申请公证的事项真实、合法的，应当自受理公证申请之日起十五个工作日内向当事人出具公证书。但是，因不可抗力、补充证明材料或者需要核实有关情况的，所需时间不计算在期限内。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，公证机构不予办理公证："},{"i":32,"n":"第三十二条","txt":"公证书应当按照国务院司法行政部门规定的格式制作，由公证员签名或者加盖签名章并加盖公证机构印章。公证书自出具之日起生效。"},{"i":33,"n":"第三十三条","txt":"公证书需要在国外使用，使用国要求先认证的，应当经中华人民共和国外交部或者外交部授权的机构和有关国家驻中华人民共和国使（领）馆认证。"},{"i":34,"n":"第三十四条","txt":"当事人应当按照规定支付公证费。"},{"i":35,"n":"第三十五条","txt":"公证机构应当将公证文书分类立卷，归档保存。法律、行政法规规定应当公证的事项等重要的公证档案在公证机构保存期满，应当按照规定移交地方档案馆保管。"},{"i":36,"n":"第三十六条","txt":"经公证的民事法律行为、有法律意义的事实和文书，应当作为认定事实的根据，但有相反证据足以推翻该项公证的除外。"},{"i":37,"n":"第三十七条","txt":"对经公证的以给付为内容并载明债务人愿意接受强制执行承诺的债权文书，债务人不履行或者履行不适当的，债权人可以依法向有管辖权的人民法院申请执行。"},{"i":38,"n":"第三十八条","txt":"法律、行政法规规定未经公证的事项不具有法律效力的，依照其规定。"},{"i":39,"n":"第三十九条","txt":"当事人、公证事项的利害关系人认为公证书有错误的，可以向出具该公证书的公证机构提出复查。公证书的内容违法或者与事实不符的，公证机构应当撤销该公证书并予以公告，该公证书自始无效；公证书有其他错误的，公证机构应当予以更正。"},{"i":40,"n":"第四十条","txt":"当事人、公证事项的利害关系人对公证书的内容有争议的，可以就该争议向人民法院提起民事诉讼。"},{"i":41,"n":"第四十一条","txt":"公证机构及其公证员有下列行为之一的，由省、自治区、直辖市或者设区的市人民政府司法行政部门给予警告；情节严重的，对公证机构处一万元以上五万元以下罚款，对公证员处一千元以上五千元以下罚款，并可以给予三个月以上六个月以下停止执业的处罚；有违法所得的，没收违法所得："},{"i":42,"n":"第四十二条","txt":"公证机构及其公证员有下列行为之一的，由省、自治区、直辖市或者设区的市人民政府司法行政部门对公证机构给予警告，并处二万元以上十万元以下罚款，并可以给予一个月以上三个月以下停业整顿的处罚；对公证员给予警告，并处二千元以上一万元以下罚款，并可以给予三个月以上十二个月以下停止执业的处罚；有违法所得的，没收违法所得；情节严重的，由省、自治区、直辖市人民政府司法行政部门吊销公证员执业证书；构成犯罪的，依法追究刑事责任："},{"i":43,"n":"第四十三条","txt":"公证机构及其公证员因过错给当事人、公证事项的利害关系人造成损失的，由公证机构承担相应的赔偿责任；公证机构赔偿后，可以向有故意或者重大过失的公证员追偿。"},{"i":44,"n":"第四十四条","txt":"当事人以及其他个人或者组织有下列行为之一，给他人造成损失的，依法承担民事责任；违反治安管理的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任："},{"i":45,"n":"第四十五条","txt":"中华人民共和国驻外使（领）馆可以依照本法的规定或者中华人民共和国缔结或者参加的国际条约的规定，办理公证。"},{"i":46,"n":"第四十六条","txt":"公证费的收费标准由省、自治区、直辖市人民政府价格主管部门会同同级司法行政部门制定。"},{"i":47,"n":"第四十七条","txt":"本法自2006年3月1日起施行。"}],"bingyifa":[{"i":1,"n":"第一条","txt":"为了规范和加强国家兵役工作，保证公民依法服兵役，保障军队兵员补充和储备，建设巩固国防和强大军队，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责。"},{"i":3,"n":"第三条","txt":"中华人民共和国实行以志愿兵役为主体的志愿兵役与义务兵役相结合的兵役制度。"},{"i":4,"n":"第四条","txt":"兵役工作坚持中国共产党的领导，贯彻习近平强军思想，贯彻新时代军事战略方针，坚持与国家经济社会发展相协调，坚持与国防和军队建设相适应，遵循服从国防需要、聚焦备战打仗、彰显服役光荣、体现权利和义务一致的原则。"},{"i":5,"n":"第五条","txt":"中华人民共和国公民，不分民族、种族、职业、家庭出身、宗教信仰和教育程度，都有义务依照本法的规定服兵役。"},{"i":6,"n":"第六条","txt":"兵役分为现役和预备役。在中国人民解放军服现役的称军人；预编到现役部队或者编入预备役部队服预备役的，称预备役人员。"},{"i":7,"n":"第七条","txt":"军人和预备役人员，必须遵守宪法和法律，履行公民的义务，同时享有公民的权利；由于服兵役而产生的权利和义务，由本法和其他相关法律法规规定。"},{"i":8,"n":"第八条","txt":"军人必须遵守军队的条令和条例，忠于职守，随时为保卫祖国而战斗。"},{"i":9,"n":"第九条","txt":"全国的兵役工作，在国务院、中央军事委员会领导下，由国防部负责。"},{"i":10,"n":"第十条","txt":"县级以上地方人民政府兵役机关应当会同相关部门，加强对本行政区域内兵役工作的组织协调和监督检查。"},{"i":11,"n":"第十一条","txt":"国家加强兵役工作信息化建设，采取有效措施实现有关部门之间信息共享，推进兵役信息收集、处理、传输、存储等技术的现代化，为提高兵役工作质量效益提供支持。"},{"i":12,"n":"第十二条","txt":"国家采取措施，加强兵役宣传教育，增强公民依法服兵役意识，营造服役光荣的良好社会氛围。"},{"i":13,"n":"第十三条","txt":"军人和预备役人员建立功勋的，按照国家和军队关于功勋荣誉表彰的规定予以褒奖。"},{"i":14,"n":"第十四条","txt":"国家实行兵役登记制度。兵役登记包括初次兵役登记和预备役登记。"},{"i":15,"n":"第十五条","txt":"每年十二月三十一日以前年满十八周岁的男性公民，都应当按照兵役机关的安排在当年进行初次兵役登记。"},{"i":16,"n":"第十六条","txt":"经过初次兵役登记的未服现役的公民，符合预备役条件的，县、自治县、不设区的市、市辖区人民政府兵役机关可以根据需要，对其进行预备役登记。"},{"i":17,"n":"第十七条","txt":"退出现役的士兵自退出现役之日起四十日内，退出现役的军官自确定安置地之日起三十日内，到安置地县、自治县、不设区的市、市辖区人民政府兵役机关进行兵役登记信息变更；其中，符合预备役条件，经部队确定需要办理预备役登记的，还应当办理预备役登记。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府兵役机关负责本行政区域兵役登记工作。"},{"i":19,"n":"第十九条","txt":"全国每年征集服现役的士兵的人数、次数、时间和要求，由国务院和中央军事委员会的命令规定。"},{"i":20,"n":"第二十条","txt":"年满十八周岁的男性公民，应当被征集服现役；当年未被征集的，在二十二周岁以前仍可以被征集服现役。普通高等学校毕业生的征集年龄可以放宽至二十四周岁，研究生的征集年龄可以放宽至二十六周岁。"},{"i":21,"n":"第二十一条","txt":"经初次兵役登记并初步审查符合征集条件的公民，称应征公民。"},{"i":22,"n":"第二十二条","txt":"在征集期间，应征公民被征集服现役，同时被机关、团体、企业事业组织招录或者聘用的，应当优先履行服兵役义务；有关机关、团体、企业事业组织应当服从国防和军队建设的需要，支持兵员征集工作。"},{"i":23,"n":"第二十三条","txt":"应征公民是维持家庭生活唯一劳动力的，可以缓征。"},{"i":24,"n":"第二十四条","txt":"应征公民因涉嫌犯罪正在被依法监察调查、侦查、起诉、审判或者被判处徒刑、拘役、管制正在服刑的，不征集。"},{"i":25,"n":"第二十五条","txt":"现役士兵包括义务兵役制士兵和志愿兵役制士兵，义务兵役制士兵称义务兵，志愿兵役制士兵称军士。"},{"i":26,"n":"第二十六条","txt":"义务兵服现役的期限为二年。"},{"i":27,"n":"第二十七条","txt":"义务兵服现役期满，根据军队需要和本人自愿，经批准可以选改为军士；服现役期间表现特别优秀的，经批准可以提前选改为军士。根据军队需要，可以直接从非军事部门具有专业技能的公民中招收军士。"},{"i":28,"n":"第二十八条","txt":"士兵服现役期满，应当退出现役。"},{"i":29,"n":"第二十九条","txt":"士兵服现役的时间自征集工作机构批准入伍之日起算。"},{"i":30,"n":"第三十条","txt":"依照本法第十七条规定经过预备役登记的退出现役的士兵，由部队会同兵役机关根据军队需要，遴选确定服士兵预备役；经过考核，适合担任预备役军官职务的，服军官预备役。"},{"i":31,"n":"第三十一条","txt":"依照本法第十六条规定经过预备役登记的公民，符合士兵预备役条件的，由部队会同兵役机关根据军队需要，遴选确定服士兵预备役。"},{"i":32,"n":"第三十二条","txt":"预备役士兵服预备役的最高年龄，依照其他有关法律规定执行。"},{"i":33,"n":"第三十三条","txt":"现役军官从下列人员中选拔、招收："},{"i":34,"n":"第三十四条","txt":"预备役军官包括下列人员："},{"i":35,"n":"第三十五条","txt":"军官服现役和服预备役的最高年龄，依照其他有关法律规定执行。"},{"i":36,"n":"第三十六条","txt":"现役军官按照规定服现役已满最高年龄或者衔级最高年限的，退出现役；需要延长服现役或者暂缓退出现役的，依照有关法律规定执行。"},{"i":37,"n":"第三十七条","txt":"依照本法第十七条规定经过预备役登记的退出现役的军官、依照本法第十六条规定经过预备役登记的公民，符合军官预备役条件的，由部队会同兵役机关根据军队需要，遴选确定服军官预备役。"},{"i":38,"n":"第三十八条","txt":"根据军队建设的需要，军队院校可以从青年学生中招收学员。招收学员的年龄，不受征集服现役年龄的限制。"},{"i":39,"n":"第三十九条","txt":"学员完成学业达到军队培养目标的，由院校发给毕业证书；按照规定任命为现役军官或者军士。"},{"i":40,"n":"第四十条","txt":"学员未达到军队培养目标或者不符合军队培养要求的，由院校按照国家和军队有关规定发给相应证书，并采取多种方式分流；其中，回入学前户口所在地的学员，就读期间其父母已办理户口迁移手续的，可以回父母现户口所在地，由县、自治县、不设区的市、市辖区的人民政府按照国家有关规定接收安置。"},{"i":41,"n":"第四十一条","txt":"学员被开除学籍的，回入学前户口所在地；就读期间其父母已办理户口迁移手续的，可以回父母现户口所在地，由县、自治县、不设区的市、市辖区的人民政府按照国家有关规定办理。"},{"i":42,"n":"第四十二条","txt":"军队院校从现役士兵中招收的学员，适用本法第三十九条、第四十条、第四十一条的规定。"},{"i":43,"n":"第四十三条","txt":"为了应对国家主权、统一、领土完整、安全和发展利益遭受的威胁，抵抗侵略，各级人民政府、各级军事机关，在平时必须做好战时兵员动员的准备工作。"},{"i":44,"n":"第四十四条","txt":"在国家发布动员令或者国务院、中央军事委员会依照《中华人民共和国国防动员法》采取必要的国防动员措施后，各级人民政府、各级军事机关必须依法迅速实施动员，军人停止退出现役，休假、探亲的军人立即归队，预备役人员随时准备应召服现役，经过预备役登记的公民做好服预备役被征召的准备。"},{"i":45,"n":"第四十五条","txt":"战时根据需要，国务院和中央军事委员会可以决定适当放宽征召男性公民服现役的年龄上限，可以决定延长公民服现役的期限。"},{"i":46,"n":"第四十六条","txt":"战争结束后，需要复员的军人，根据国务院和中央军事委员会的复员命令，分期分批地退出现役，由各级人民政府妥善安置。"},{"i":47,"n":"第四十七条","txt":"国家保障军人享有符合军事职业特点、与其履行职责相适应的工资、津贴、住房、医疗、保险、休假、疗养等待遇。军人的待遇应当与国民经济发展相协调，与社会进步相适应。"},{"i":48,"n":"第四十八条","txt":"预备役人员参战、参加军事训练、担负战备勤务、执行非战争军事行动任务，享受国家规定的伙食、交通等补助。预备役人员是机关、团体、企业事业组织工作人员的，参战、参加军事训练、担负战备勤务、执行非战争军事行动任务期间，所在单位应当保持其原有的工资、奖金和福利待遇。预备役人员的其他待遇保障依照有关法律法规和国家有关规定执行。"},{"i":49,"n":"第四十九条","txt":"军人按照国家有关规定，在医疗、金融、交通、参观游览、法律服务、文化体育设施服务、邮政服务等方面享受优待政策。公民入伍时保留户籍。"},{"i":50,"n":"第五十条","txt":"国家建立义务兵家庭优待金制度。义务兵家庭优待金标准由地方人民政府制定，中央财政给予定额补助。具体补助办法由国务院退役军人工作主管部门、财政部门会同中央军事委员会机关有关部门制定。"},{"i":51,"n":"第五十一条","txt":"现役军官和军士的子女教育，家属的随军、就业创业以及工作调动，享受国家和社会的优待。"},{"i":52,"n":"第五十二条","txt":"预备役人员因参战、参加军事训练、担负战备勤务、执行非战争军事行动任务致残、牺牲的，由当地人民政府依照有关规定给予抚恤优待。"},{"i":53,"n":"第五十三条","txt":"对退出现役的义务兵，国家采取自主就业、安排工作、供养等方式妥善安置。"},{"i":54,"n":"第五十四条","txt":"对退出现役的军士，国家采取逐月领取退役金、自主就业、安排工作、退休、供养等方式妥善安置。"},{"i":55,"n":"第五十五条","txt":"对退出现役的军官，国家采取退休、转业、逐月领取退役金、复员等方式妥善安置；其安置方式的适用条件，依照有关法律法规的规定执行。"},{"i":56,"n":"第五十六条","txt":"残疾军人、患慢性病的军人退出现役后，由安置地的县级以上地方人民政府按照国务院、中央军事委员会的有关规定负责接收安置；其中，患过慢性病旧病复发需要治疗的，由当地医疗机构负责给予治疗，所需医疗和生活费用，本人经济困难的，按照国家规定给予补助。"},{"i":57,"n":"第五十七条","txt":"有服兵役义务的公民有下列行为之一的，由县级人民政府责令限期改正；逾期不改正的，由县级人民政府强制其履行兵役义务，并处以罚款："},{"i":58,"n":"第五十八条","txt":"军人以逃避服兵役为目的，拒绝履行职责或者逃离部队的，按照中央军事委员会的规定给予处分。"},{"i":59,"n":"第五十九条","txt":"机关、团体、企业事业组织拒绝完成本法规定的兵役工作任务的，阻挠公民履行兵役义务的，或者有其他妨害兵役工作行为的，由县级以上地方人民政府责令改正，并可以处以罚款；对单位负有责任的领导人员、直接负责的主管人员和其他直接责任人员，依法予以处罚。"},{"i":60,"n":"第六十条","txt":"扰乱兵役工作秩序，或者阻碍兵役工作人员依法执行职务的，依照《中华人民共和国治安管理处罚法》的规定处罚。"},{"i":61,"n":"第六十一条","txt":"国家工作人员和军人在兵役工作中，有下列行为之一的，依法给予处分："},{"i":62,"n":"第六十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"本法第五十七条、第五十八条、第五十九条规定的处罚，由县级以上地方人民政府兵役机关会同有关部门查明事实，经同级地方人民政府作出处罚决定后，由县级以上地方人民政府兵役机关、发展改革、公安、退役军人工作、卫生健康、教育、人力资源和社会保障等部门按照职责分工具体执行。"},{"i":64,"n":"第六十四条","txt":"本法适用于中国人民武装警察部队。"},{"i":65,"n":"第六十五条","txt":"本法自2021年10月1日起施行。"}],"junshisheshibaohufa":[{"i":1,"n":"第一条","txt":"为了保护军事设施的安全，保障军事设施的使用效能和军事活动的正常进行，加强国防现代化建设，巩固国防，抵御侵略，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称军事设施，是指国家直接用于军事目的的下列建筑、场地和设备："},{"i":3,"n":"第三条","txt":"军事设施保护工作坚持中国共产党的领导。各级人民政府和军事机关应当共同保护军事设施，维护国防利益。"},{"i":4,"n":"第四条","txt":"中华人民共和国的组织和公民都有保护军事设施的义务。"},{"i":5,"n":"第五条","txt":"国家统筹兼顾经济建设、社会发展和军事设施保护，促进经济社会发展和军事设施保护相协调。"},{"i":6,"n":"第六条","txt":"国家对军事设施实行分类保护、确保重点的方针。军事设施的分类和保护标准，由国务院和中央军事委员会规定。"},{"i":7,"n":"第七条","txt":"国家对因设有军事设施、经济建设受到较大影响的地方，采取相应扶持政策和措施。具体办法由国务院和中央军事委员会规定。"},{"i":8,"n":"第八条","txt":"对在军事设施保护工作中做出突出贡献的组织和个人，依照有关法律、法规的规定给予表彰和奖励。"},{"i":9,"n":"第九条","txt":"军事禁区、军事管理区根据军事设施的性质、作用、安全保密的需要和使用效能的要求划定，具体划定标准和确定程序，由国务院和中央军事委员会规定。"},{"i":10,"n":"第十条","txt":"军事禁区、军事管理区由国务院和中央军事委员会确定，或者由有关军事机关根据国务院和中央军事委员会的规定确定。"},{"i":11,"n":"第十一条","txt":"陆地和水域的军事禁区、军事管理区的范围，由省、自治区、直辖市人民政府和有关军级以上军事机关共同划定，或者由省、自治区、直辖市人民政府、国务院有关部门和有关军级以上军事机关共同划定。空中军事禁区和特别重要的陆地、水域军事禁区的范围，由国务院和中央军事委员会划定。"},{"i":12,"n":"第十二条","txt":"军事禁区、军事管理区应当由县级以上地方人民政府按照国家统一规定的样式设置标志牌。"},{"i":13,"n":"第十三条","txt":"军事禁区、军事管理区范围的划定或者调整，应当在确保军事设施安全保密和使用效能的前提下，兼顾经济建设、生态环境保护和当地居民的生产生活。"},{"i":14,"n":"第十四条","txt":"军事禁区、军事管理区范围的划定或者调整，需要征收、征用土地、房屋等不动产，压覆矿产资源，或者使用海域、空域等的，依照有关法律、法规的规定办理。"},{"i":15,"n":"第十五条","txt":"军队为执行任务设置的临时军事设施需要划定陆地、水域临时军事禁区、临时军事管理区范围的，由县级以上地方人民政府和有关团级以上军事机关共同划定，并各自向上一级机关备案。其中，涉及有关海事管理机构职权的，应当在划定前征求其意见。划定之后，由县级以上地方人民政府或者有关海事管理机构予以公告。"},{"i":16,"n":"第十六条","txt":"军事禁区管理单位应当根据具体条件，按照划定的范围，为陆地军事禁区修筑围墙、设置铁丝网等障碍物，为水域军事禁区设置障碍物或者界线标志。"},{"i":17,"n":"第十七条","txt":"禁止陆地、水域军事禁区管理单位以外的人员、车辆、船舶等进入军事禁区，禁止航空器在陆地、水域军事禁区上空进行低空飞行，禁止对军事禁区进行摄影、摄像、录音、勘察、测量、定位、描绘和记述。但是，经有关军事机关批准的除外。"},{"i":18,"n":"第十八条","txt":"在陆地军事禁区内，禁止建造、设置非军事设施，禁止开发利用地下空间。但是，经战区级以上军事机关批准的除外。"},{"i":19,"n":"第十九条","txt":"在陆地、水域军事禁区内采取的防护措施不足以保证军事设施安全保密和使用效能，或者陆地、水域军事禁区内的军事设施具有重大危险因素的，省、自治区、直辖市人民政府和有关军事机关，或者省、自治区、直辖市人民政府、国务院有关部门和有关军事机关根据军事设施性质、地形和当地经济建设、社会发展情况，可以在共同划定陆地、水域军事禁区范围的同时，在禁区外围共同划定安全控制范围，并在其外沿设置安全警戒标志。"},{"i":20,"n":"第二十条","txt":"划定陆地、水域军事禁区外围安全控制范围，不改变原土地及土地附着物、水域的所有权。在陆地、水域军事禁区外围安全控制范围内，当地居民可以照常生产生活，但是不得进行爆破、射击以及其他危害军事设施安全和使用效能的活动。"},{"i":21,"n":"第二十一条","txt":"军事管理区管理单位应当根据具体条件，按照划定的范围，为军事管理区修筑围墙、设置铁丝网或者界线标志。"},{"i":22,"n":"第二十二条","txt":"军事管理区管理单位以外的人员、车辆、船舶等进入军事管理区，或者对军事管理区进行摄影、摄像、录音、勘察、测量、定位、描绘和记述，必须经军事管理区管理单位批准。"},{"i":23,"n":"第二十三条","txt":"在陆地军事管理区内，禁止建造、设置非军事设施，禁止开发利用地下空间。但是，经军级以上军事机关批准的除外。"},{"i":24,"n":"第二十四条","txt":"划为军事管理区的军民合用港口的水域，实行军地分区管理；在地方管理的水域内需要新建非军事设施的，必须事先征得军事设施管理单位的同意。"},{"i":25,"n":"第二十五条","txt":"没有划入军事禁区、军事管理区的军事设施，军事设施管理单位应当采取措施予以保护；军队团级以上管理单位也可以委托当地人民政府予以保护。"},{"i":26,"n":"第二十六条","txt":"在没有划入军事禁区、军事管理区的军事设施一定距离内进行采石、取土、爆破等活动，不得危害军事设施的安全和使用效能。"},{"i":27,"n":"第二十七条","txt":"没有划入军事禁区、军事管理区的作战工程外围应当划定安全保护范围。作战工程的安全保护范围，应当根据作战工程性质、地形和当地经济建设、社会发展情况，由省、自治区、直辖市人民政府和有关军事机关共同划定，或者由省、自治区、直辖市人民政府、国务院有关部门和有关军事机关共同划定。在作战工程布局相对集中的地区，作战工程安全保护范围可以连片划定。县级以上地方人民政府应当按照有关规定为作战工程安全保护范围设置界线标志。"},{"i":28,"n":"第二十八条","txt":"划定作战工程安全保护范围，不改变原土地及土地附着物的所有权。在作战工程安全保护范围内，当地居民可以照常生产生活，但是不得进行开山采石、采矿、爆破；从事修筑建筑物、构筑物、道路和进行农田水利基本建设、采伐林木等活动，不得危害作战工程安全和使用效能。"},{"i":29,"n":"第二十九条","txt":"在军用机场净空保护区域内，禁止修建超出机场净空标准的建筑物、构筑物或者其他设施，不得从事影响飞行安全和机场助航设施使用效能的活动。"},{"i":30,"n":"第三十条","txt":"有关军事机关应当向地方人民政府通报当地军用机场净空保护有关情况和需求。"},{"i":31,"n":"第三十一条","txt":"军民合用机场以及由军队管理的保留旧机场、直升机起落坪的净空保护工作，适用军用机场净空保护的有关规定。"},{"i":32,"n":"第三十二条","txt":"地方各级人民政府和有关军事机关采取委托看管、分段负责等方式，实行军民联防，保护军用管线安全。"},{"i":33,"n":"第三十三条","txt":"在军用无线电固定设施电磁环境保护范围内，禁止建造、设置影响军用无线电固定设施使用效能的设备和电磁障碍物体，不得从事影响军用无线电固定设施电磁环境的活动。"},{"i":34,"n":"第三十四条","txt":"未经国务院和中央军事委员会批准或者国务院和中央军事委员会授权的机关批准，不得拆除、移动边防、海防管控设施，不得在边防、海防管控设施上搭建、设置民用设施。在边防、海防管控设施周边安排建设项目，不得危害边防、海防管控设施安全和使用效能。"},{"i":35,"n":"第三十五条","txt":"任何组织和个人不得损毁或者擅自移动军用测量标志。在军用测量标志周边安排建设项目，不得危害军用测量标志安全和使用效能。"},{"i":36,"n":"第三十六条","txt":"县级以上地方人民政府编制国民经济和社会发展规划、安排可能影响军事设施保护的建设项目，国务院有关部门、地方人民政府编制国土空间规划等规划，应当兼顾军事设施保护的需要，并按照规定书面征求有关军事机关的意见。必要时，可以由地方人民政府会同有关部门、有关军事机关对建设项目进行评估。"},{"i":37,"n":"第三十七条","txt":"军队编制军事设施建设规划、组织军事设施项目建设，应当考虑地方经济建设、生态环境保护和社会发展的需要，符合国土空间规划等规划的总体要求，并进行安全保密环境评估和环境影响评价。涉及国土空间规划等规划的，应当征求国务院有关部门、地方人民政府的意见，尽量避开生态保护红线、自然保护地、地方经济建设热点区域和民用设施密集区域。确实不能避开，需要将生产生活设施拆除或者迁建的，应当依法进行。"},{"i":38,"n":"第三十八条","txt":"县级以上地方人民政府安排建设项目或者开辟旅游景点，应当避开军事设施。确实不能避开，需要将军事设施拆除、迁建或者改作民用的，由省、自治区、直辖市人民政府或者国务院有关部门和战区级军事机关商定，并报国务院和中央军事委员会批准或者国务院和中央军事委员会授权的机关批准；需要将军事设施改建的，由有关军事机关批准。"},{"i":39,"n":"第三十九条","txt":"军事设施因军事任务调整、周边环境变化和自然损毁等原因，失去使用效能并无需恢复重建的，军事设施管理单位应当按照规定程序及时报国务院和中央军事委员会批准或者国务院和中央军事委员会授权的机关批准，予以拆除或者改作民用。"},{"i":40,"n":"第四十条","txt":"军用机场、港口实行军民合用的，需经国务院和中央军事委员会批准。军用码头实行军民合用的，需经省、自治区、直辖市人民政府或者国务院有关部门会同战区级军事机关批准。"},{"i":41,"n":"第四十一条","txt":"军事禁区、军事管理区和没有划入军事禁区、军事管理区的军事设施，县级以上地方人民政府应当会同军事设施管理单位制定具体保护措施，可以公告施行。"},{"i":42,"n":"第四十二条","txt":"各级军事机关应当严格履行保护军事设施的职责，教育军队人员爱护军事设施，保守军事设施秘密，建立健全保护军事设施的规章制度，监督、检查、解决军事设施保护工作中的问题。"},{"i":43,"n":"第四十三条","txt":"军事设施管理单位应当认真执行有关保护军事设施的规章制度，建立军事设施档案，对军事设施进行检查、维护。"},{"i":44,"n":"第四十四条","txt":"军事设施管理单位应当了解掌握军事设施周边建设项目等情况，发现可能危害军事设施安全和使用效能的，应当及时向有关军事机关和当地人民政府主管部门报告，并配合有关部门依法处理。"},{"i":45,"n":"第四十五条","txt":"军事禁区、军事管理区的管理单位应当依照有关法律、法规的规定，保护军事禁区、军事管理区内的生态环境、自然资源和文物。"},{"i":46,"n":"第四十六条","txt":"军事设施管理单位必要时应当向县级以上地方人民政府提供地下、水下军用管线的位置资料。地方进行建设时，当地人民政府应当对地下、水下军用管线予以保护。"},{"i":47,"n":"第四十七条","txt":"各级人民政府应当加强国防和军事设施保护教育，使全体公民增强国防观念，保护军事设施，保守军事设施秘密，制止破坏、危害军事设施的行为。"},{"i":48,"n":"第四十八条","txt":"县级以上地方人民政府应当会同有关军事机关，定期组织检查和评估本行政区域内军事设施保护情况，督促限期整改影响军事设施保护的隐患和问题，完善军事设施保护措施。"},{"i":49,"n":"第四十九条","txt":"国家实行军事设施保护目标责任制和考核评价制度，将军事设施保护目标完成情况作为对地方人民政府、有关军事机关和军事设施管理单位及其负责人考核评价的内容。"},{"i":50,"n":"第五十条","txt":"军事禁区、军事管理区需要公安机关协助维护治安管理秩序的，经国务院和中央军事委员会决定或者由有关军事机关提请省、自治区、直辖市公安机关批准，可以设立公安机构。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，有下列情形之一的，军事设施管理单位的执勤人员应当予以制止："},{"i":52,"n":"第五十二条","txt":"有本法第五十一条所列情形之一，不听制止的，军事设施管理单位依照国家有关规定，可以采取下列措施："},{"i":53,"n":"第五十三条","txt":"违反本法第十七条、第十八条、第二十三条规定，擅自进入水域军事禁区，在水域军事禁区内从事水产养殖、捕捞，在水域军事管理区内从事水产养殖，或者在水域军事管理区内从事捕捞等活动影响军用舰船行动的，由交通运输、渔业等主管部门给予警告，责令离开，没收渔具、渔获物。"},{"i":54,"n":"第五十四条","txt":"违反本法第十八条、第二十三条、第二十四条规定，在陆地、水域军事禁区、军事管理区内建造、设置非军事设施，擅自开发利用陆地军事禁区、军事管理区地下空间，或者在划为军事管理区的军民合用港口地方管理的水域未征得军事设施管理单位同意建造、设置非军事设施的，由住房和城乡建设、自然资源、交通运输、渔业等主管部门责令停止兴建活动，对已建成的责令限期拆除。"},{"i":55,"n":"第五十五条","txt":"违反本法第二十八条第一款规定，在作战工程安全保护范围内开山采石、采矿、爆破的，由自然资源、生态环境等主管部门以及公安机关责令停止违法行为，没收采出的产品和违法所得；修筑建筑物、构筑物、道路或者进行农田水利基本建设影响作战工程安全和使用效能的，由自然资源、生态环境、交通运输、农业农村、住房和城乡建设等主管部门给予警告，责令限期改正。"},{"i":56,"n":"第五十六条","txt":"违反本法第二十八条第三款规定，私自开启封闭的作战工程，破坏作战工程伪装，阻断作战工程通道，将作战工程用于存放非军用物资器材或者种植、养殖等生产活动的，由公安机关以及自然资源等主管部门责令停止违法行为，限期恢复原状。"},{"i":57,"n":"第五十七条","txt":"违反本法第二十八条第四款、第三十四条规定，擅自拆除、迁建、改建作战工程，或者擅自拆除、移动边防、海防管控设施的，由住房和城乡建设主管部门、公安机关等责令停止违法行为，限期恢复原状。"},{"i":58,"n":"第五十八条","txt":"违反本法第二十九条第一款规定，在军用机场净空保护区域内修建超出军用机场净空保护标准的建筑物、构筑物或者其他设施的，由住房和城乡建设、自然资源主管部门责令限期拆除超高部分。"},{"i":59,"n":"第五十九条","txt":"违反本法第三十三条规定，在军用无线电固定设施电磁环境保护范围内建造、设置影响军用无线电固定设施使用效能的设备和电磁障碍物体，或者从事影响军用无线电固定设施电磁环境的活动的，由自然资源、生态环境等主管部门以及无线电管理机构给予警告，责令限期改正；逾期不改正的，查封干扰设备或者强制拆除障碍物。"},{"i":60,"n":"第六十条","txt":"有下列行为之一的，适用《中华人民共和国治安管理处罚法》第二十三条的处罚规定："},{"i":61,"n":"第六十一条","txt":"违反国家规定，故意干扰军用无线电设施正常工作的，或者对军用无线电设施产生有害干扰，拒不按照有关主管部门的要求改正的，依照《中华人民共和国治安管理处罚法》第二十八条的规定处罚。"},{"i":62,"n":"第六十二条","txt":"毁坏边防、海防管控设施以及军事禁区、军事管理区的围墙、铁丝网、界线标志或者其他军事设施的，依照《中华人民共和国治安管理处罚法》第三十三条的规定处罚。"},{"i":63,"n":"第六十三条","txt":"有下列行为之一，构成犯罪的，依法追究刑事责任："},{"i":64,"n":"第六十四条","txt":"军人、军队文职人员和军队其他人员有下列行为之一，按照军队有关规定给予处分；构成犯罪的，依法追究刑事责任："},{"i":65,"n":"第六十五条","txt":"公职人员在军事设施保护工作中有玩忽职守、滥用职权、徇私舞弊等行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":66,"n":"第六十六条","txt":"违反本法规定，破坏、危害军事设施的，属海警机构职权范围的，由海警机构依法处理。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，造成军事设施损失的，依法承担赔偿责任。"},{"i":68,"n":"第六十八条","txt":"战时违反本法的，依法从重追究法律责任。"},{"i":69,"n":"第六十九条","txt":"中国人民武装警察部队所属军事设施的保护，适用本法。"},{"i":70,"n":"第七十条","txt":"国防科技工业重要武器装备的科研、生产、试验、存储等设施的保护，参照本法有关规定执行。具体办法和设施目录由国务院和中央军事委员会规定。"},{"i":71,"n":"第七十一条","txt":"国务院和中央军事委员会根据本法制定实施办法。"},{"i":72,"n":"第七十二条","txt":"本法自2021年8月1日起施行。"}],"junrendiweihequanyibaozhangfa":[{"i":1,"n":"第一条","txt":"为了保障军人地位和合法权益，激励军人履行职责使命，让军人成为全社会尊崇的职业，促进国防和军队现代化建设，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称军人，是指在中国人民解放军服现役的军官、军士、义务兵等人员。"},{"i":3,"n":"第三条","txt":"军人肩负捍卫国家主权、安全、发展利益和保卫人民的和平劳动的神圣职责和崇高使命。"},{"i":4,"n":"第四条","txt":"军人是全社会尊崇的职业。国家和社会尊重、优待军人，保障军人享有与其职业特点、担负职责使命和所做贡献相称的地位和权益，经常开展各种形式的拥军优属活动。"},{"i":5,"n":"第五条","txt":"军人地位和权益保障工作，坚持中国共产党的领导，以服务军队战斗力建设为根本目的，遵循权利与义务相统一、物质保障与精神激励相结合、保障水平与国民经济和社会发展相适应的原则。"},{"i":6,"n":"第六条","txt":"中央军事委员会政治工作部门、国务院退役军人工作主管部门以及中央和国家有关机关、中央军事委员会有关部门按照职责分工做好军人地位和权益保障工作。"},{"i":7,"n":"第七条","txt":"军人地位和权益保障所需经费，由中央和地方按照事权和支出责任相适应的原则列入预算。"},{"i":8,"n":"第八条","txt":"中央和国家有关机关、县级以上地方人民政府及其有关部门、军队各级机关，应当将军人地位和权益保障工作情况作为拥军优属、拥政爱民等工作评比和有关单位负责人以及工作人员考核评价的重要内容。"},{"i":9,"n":"第九条","txt":"国家鼓励和引导群团组织、企业事业单位、社会组织、个人等社会力量依法通过捐赠、志愿服务等方式为军人权益保障提供支持，符合规定条件的，依法享受税收优惠等政策。"},{"i":10,"n":"第十条","txt":"每年8月1日为中国人民解放军建军节。各级人民政府和军队单位应当在建军节组织开展庆祝、纪念等活动。"},{"i":11,"n":"第十一条","txt":"对在军人地位和权益保障工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":12,"n":"第十二条","txt":"军人是中国共产党领导的国家武装力量基本成员，必须忠于祖国，忠于中国共产党，听党指挥，坚决服从命令，认真履行巩固中国共产党的领导和社会主义制度的重要职责使命。"},{"i":13,"n":"第十三条","txt":"军人是人民子弟兵，应当热爱人民，全心全意为人民服务，保卫人民生命财产安全，当遇到人民群众生命财产受到严重威胁时，挺身而出、积极救助。"},{"i":14,"n":"第十四条","txt":"军人是捍卫国家主权、统一、领土完整的坚强力量，应当具备巩固国防、抵抗侵略、保卫祖国所需的战斗精神和能力素质，按照实战要求始终保持戒备状态，苦练杀敌本领，不怕牺牲，能打胜仗，坚决完成任务。"},{"i":15,"n":"第十五条","txt":"军人是中国特色社会主义现代化建设的重要力量，应当积极投身全面建设社会主义现代化国家的事业，依法参加突发事件的应急救援和处置工作。"},{"i":16,"n":"第十六条","txt":"军人享有宪法和法律规定的政治权利，依法参加国家权力机关组成人员选举，依法参加管理国家事务、管理经济和文化事业、管理社会事务。"},{"i":17,"n":"第十七条","txt":"军队实行官兵一致，军人之间在政治和人格上一律平等，应当互相尊重、平等对待。"},{"i":18,"n":"第十八条","txt":"军人必须模范遵守宪法和法律，认真履行宪法和法律规定的公民义务，严格遵守军事法规、军队纪律，作风优良，带头践行社会主义核心价值观。"},{"i":19,"n":"第十九条","txt":"国家为军人履行职责提供保障，军人依法履行职责的行为受法律保护。"},{"i":20,"n":"第二十条","txt":"军人因履行职责享有的特定权益、承担的特定义务，由本法和有关法律法规规定。"},{"i":21,"n":"第二十一条","txt":"军人荣誉是国家、社会对军人献身国防和军队建设、社会主义现代化建设的褒扬和激励，是鼓舞军人士气、提升军队战斗力的精神力量。"},{"i":22,"n":"第二十二条","txt":"军队加强爱国主义、集体主义、革命英雄主义教育，强化军人的荣誉意识，培育有灵魂、有本事、有血性、有品德的新时代革命军人，锻造具有铁一般信仰、铁一般信念、铁一般纪律、铁一般担当的过硬部队。"},{"i":23,"n":"第二十三条","txt":"国家采取多种形式的宣传教育、奖励激励和保障措施，培育军人的职业使命感、自豪感和荣誉感，激发军人建功立业、报效国家的积极性、主动性、创造性。"},{"i":24,"n":"第二十四条","txt":"全社会应当学习中国人民解放军光荣历史，宣传军人功绩和牺牲奉献精神，营造维护军人荣誉的良好氛围。"},{"i":25,"n":"第二十五条","txt":"国家建立健全军人荣誉体系，通过授予勋章、荣誉称号和记功、嘉奖、表彰、颁发纪念章等方式，对做出突出成绩和贡献的军人给予功勋荣誉表彰，褒扬军人为国家和人民做出的奉献和牺牲。"},{"i":26,"n":"第二十六条","txt":"军人经军队单位批准可以接受地方人民政府、群团组织和社会组织等授予的荣誉，以及国际组织和其他国家、军队等授予的荣誉。"},{"i":27,"n":"第二十七条","txt":"获得功勋荣誉表彰的军人享受相应礼遇和待遇。军人执行作战任务获得功勋荣誉表彰的，按照高于平时的原则享受礼遇和待遇。"},{"i":28,"n":"第二十八条","txt":"中央和国家有关机关、地方和军队各级有关机关，以及广播、电视、报刊、互联网等媒体，应当积极宣传军人的先进典型和英勇事迹。"},{"i":29,"n":"第二十九条","txt":"国家和社会尊崇、铭记为国家、人民、民族牺牲的军人，尊敬、礼遇其遗属。"},{"i":30,"n":"第三十条","txt":"国家建立军人礼遇仪式制度。在公民入伍、军人退出现役等时机，应当举行相应仪式；在烈士和因公牺牲军人安葬等场合，应当举行悼念仪式。"},{"i":31,"n":"第三十一条","txt":"地方人民政府应当为军人和烈士、因公牺牲军人、病故军人的遗属的家庭悬挂光荣牌。军人获得功勋荣誉表彰，由当地人民政府有关部门和军事机关给其家庭送喜报，并组织做好宣传工作。"},{"i":32,"n":"第三十二条","txt":"军人的荣誉和名誉受法律保护。"},{"i":33,"n":"第三十三条","txt":"国家建立军人待遇保障制度，保证军人履行职责使命，保障军人及其家庭的生活水平。"},{"i":34,"n":"第三十四条","txt":"国家建立相对独立、特色鲜明、具有比较优势的军人工资待遇制度。军官和军士实行工资制度，义务兵实行供给制生活待遇制度。军人享受个人所得税优惠政策。"},{"i":35,"n":"第三十五条","txt":"国家采取军队保障、政府保障与市场配置相结合，实物保障与货币补贴相结合的方式，保障军人住房待遇。"},{"i":36,"n":"第三十六条","txt":"国家保障军人按照规定享受免费医疗和疾病预防、疗养、康复等待遇。"},{"i":37,"n":"第三十七条","txt":"国家实行体现军人职业特点、与社会保险制度相衔接的军人保险制度，适时补充军人保险项目，保障军人的保险待遇。"},{"i":38,"n":"第三十八条","txt":"军人享有年休假、探亲假等休息休假的权利。对确因工作需要未休假或者未休满假的，给予经济补偿。"},{"i":39,"n":"第三十九条","txt":"国家建立健全军人教育培训体系，保障军人的受教育权利，组织和支持军人参加专业和文化学习培训，提高军人履行职责的能力和退出现役后的就业创业能力。"},{"i":40,"n":"第四十条","txt":"女军人的合法权益受法律保护。军队应当根据女军人的特点，合理安排女军人的工作任务和休息休假，在生育、健康等方面为女军人提供特别保护。"},{"i":41,"n":"第四十一条","txt":"国家对军人的婚姻给予特别保护，禁止任何破坏军人婚姻的行为。"},{"i":42,"n":"第四十二条","txt":"军官和符合规定条件的军士，其配偶、未成年子女和不能独立生活的成年子女可以办理随军落户；符合规定条件的军人父母可以按照规定办理随子女落户。夫妻双方均为军人的，其子女可以选择父母中的一方随军落户。"},{"i":43,"n":"第四十三条","txt":"国家保障军人、军人家属的户籍管理和相关权益。"},{"i":44,"n":"第四十四条","txt":"国家对依法退出现役的军人，依照退役军人保障法律法规的有关规定，给予妥善安置和相应优待保障。"},{"i":45,"n":"第四十五条","txt":"国家和社会尊重军人、军人家庭为国防和军队建设做出的奉献和牺牲，优待军人、军人家属，抚恤优待烈士、因公牺牲军人、病故军人的遗属，保障残疾军人的生活。"},{"i":46,"n":"第四十六条","txt":"军人家属凭有关部门制发的证件享受法律法规规定的优待保障。具体办法由国务院和中央军事委员会有关部门制定。"},{"i":47,"n":"第四十七条","txt":"各级人民政府应当保障抚恤优待对象享受公民普惠待遇，同时享受相应的抚恤优待待遇。"},{"i":48,"n":"第四十八条","txt":"国家实行军人死亡抚恤制度。"},{"i":49,"n":"第四十九条","txt":"国家实行军人残疾抚恤制度。"},{"i":50,"n":"第五十条","txt":"国家对军人家属和烈士、因公牺牲军人、病故军人的遗属予以住房优待。"},{"i":51,"n":"第五十一条","txt":"公立医疗机构应当为军人就医提供优待服务。军人家属和烈士、因公牺牲军人、病故军人的遗属，在军队医疗机构和公立医疗机构就医享受医疗优待。"},{"i":52,"n":"第五十二条","txt":"国家依法保障军人配偶就业安置权益。机关、群团组织、企业事业单位、社会组织和其他组织，应当依法履行接收军人配偶就业安置的义务。"},{"i":53,"n":"第五十三条","txt":"国家鼓励有用工需求的用人单位优先安排随军家属就业。国有企业在新招录职工时，应当按照用工需求的适当比例聘用随军家属；有条件的民营企业在新招录职工时，可以按照用工需求的适当比例聘用随军家属。"},{"i":54,"n":"第五十四条","txt":"国家鼓励和扶持军人配偶自主就业、自主创业。军人配偶从事个体经营的，按照国家有关优惠政策给予支持。"},{"i":55,"n":"第五十五条","txt":"国家对军人子女予以教育优待。地方各级人民政府及其有关部门应当为军人子女提供当地优质教育资源，创造接受良好教育的条件。"},{"i":56,"n":"第五十六条","txt":"军人家属和烈士、因公牺牲军人、病故军人的遗属，符合规定条件申请在国家兴办的光荣院、优抚医院集中供养、住院治疗、短期疗养的，享受优先、优惠待遇；申请到公办养老机构养老的，同等条件下优先安排。"},{"i":57,"n":"第五十七条","txt":"军人、军人家属和烈士、因公牺牲军人、病故军人的遗属，享受参观游览公园、博物馆、纪念馆、展览馆、名胜古迹以及文化和旅游等方面的优先、优惠服务。"},{"i":58,"n":"第五十八条","txt":"地方人民政府和军队单位对因自然灾害、意外事故、重大疾病等原因，基本生活出现严重困难的军人家庭，应当给予救助和慰问。"},{"i":59,"n":"第五十九条","txt":"地方人民政府和军队单位对在未成年子女入学入托、老年人养老等方面遇到困难的军人家庭，应当给予必要的帮扶。"},{"i":60,"n":"第六十条","txt":"军人、军人家属和烈士、因公牺牲军人、病故军人遗属的合法权益受到侵害的，有权向有关国家机关和军队单位提出申诉、控告。负责受理的国家机关和军队单位，应当依法及时处理，不得推诿、拖延。依法向人民法院提起诉讼的，人民法院应当优先立案、审理和执行，人民检察院可以支持起诉。"},{"i":61,"n":"第六十一条","txt":"军人、军人家属和烈士、因公牺牲军人、病故军人的遗属维护合法权益遇到困难的，法律援助机构应当依法优先提供法律援助，司法机关应当依法优先提供司法救助。"},{"i":62,"n":"第六十二条","txt":"侵害军人荣誉、名誉和其他相关合法权益，严重影响军人有效履行职责使命，致使社会公共利益受到损害的，人民检察院可以根据民事诉讼法、行政诉讼法的相关规定提起公益诉讼。"},{"i":63,"n":"第六十三条","txt":"国家机关及其工作人员、军队单位及其工作人员违反本法规定，在军人地位和权益保障工作中滥用职权、玩忽职守、徇私舞弊的，由其所在单位、主管部门或者上级机关责令改正；对负有责任的领导人员和直接责任人员，依法给予处分。"},{"i":64,"n":"第六十四条","txt":"群团组织、企业事业单位、社会组织和其他组织违反本法规定，不履行优待义务的，由有关部门责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，通过大众传播媒介或者其他方式，诋毁、贬损军人荣誉，侮辱、诽谤军人名誉，或者故意毁损、玷污军人的荣誉标识的，由公安、文化和旅游、新闻出版、电影、广播电视、网信或者其他有关主管部门依据各自的职权责令改正，并依法予以处理；造成精神损害的，受害人有权请求精神损害赔偿。"},{"i":66,"n":"第六十六条","txt":"冒领或者以欺诈、伪造证明材料等手段骗取本法规定的相关荣誉、待遇或者抚恤优待的，由有关部门予以取消，依法给予没收违法所得等行政处罚。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，侵害军人的合法权益，造成财产损失或者其他损害的，依法承担民事责任。"},{"i":68,"n":"第六十八条","txt":"本法所称军人家属，是指军人的配偶、父母（扶养人）、未成年子女、不能独立生活的成年子女。"},{"i":69,"n":"第六十九条","txt":"中国人民武装警察部队服现役的警官、警士和义务兵等人员，适用本法。"},{"i":70,"n":"第七十条","txt":"省、自治区、直辖市可以结合本地实际情况，根据本法制定保障军人地位和权益的具体办法。"},{"i":71,"n":"第七十一条","txt":"本法自2021年8月1日起施行。"}],"chujingrujingguanlifa":[{"i":1,"n":"第一条","txt":"为了规范出境入境管理，维护中华人民共和国的主权、安全和社会秩序，促进对外交往和对外开放，制定本法。"},{"i":2,"n":"第二条","txt":"中国公民出境入境、外国人入境出境、外国人在中国境内停留居留的管理，以及交通运输工具出境入境的边防检查，适用本法。"},{"i":3,"n":"第三条","txt":"国家保护中国公民出境入境合法权益。"},{"i":4,"n":"第四条","txt":"公安部、外交部按照各自职责负责有关出境入境事务的管理。"},{"i":5,"n":"第五条","txt":"国家建立统一的出境入境管理信息平台，实现有关管理部门信息共享。"},{"i":6,"n":"第六条","txt":"国家在对外开放的口岸设立出入境边防检查机关。"},{"i":7,"n":"第七条","txt":"经国务院批准，公安部、外交部根据出境入境管理的需要，可以对留存出境入境人员的指纹等人体生物识别信息作出规定。"},{"i":8,"n":"第八条","txt":"履行出境入境管理职责的部门和机构应当切实采取措施，不断提升服务和管理水平，公正执法，便民高效，维护安全、便捷的出境入境秩序。"},{"i":9,"n":"第九条","txt":"中国公民出境入境，应当依法申请办理护照或者其他旅行证件。"},{"i":10,"n":"第十条","txt":"中国公民往来内地与香港特别行政区、澳门特别行政区，中国公民往来大陆与台湾地区，应当依法申请办理通行证件，并遵守本法有关规定。具体管理办法由国务院规定。"},{"i":11,"n":"第十一条","txt":"中国公民出境入境，应当向出入境边防检查机关交验本人的护照或者其他旅行证件等出境入境证件，履行规定的手续，经查验准许，方可出境入境。"},{"i":12,"n":"第十二条","txt":"中国公民有下列情形之一的，不准出境："},{"i":13,"n":"第十三条","txt":"定居国外的中国公民要求回国定居的，应当在入境前向中华人民共和国驻外使馆、领馆或者外交部委托的其他驻外机构提出申请，也可以由本人或者经由国内亲属向拟定居地的县级以上地方人民政府侨务部门提出申请。"},{"i":14,"n":"第十四条","txt":"定居国外的中国公民在中国境内办理金融、教育、医疗、交通、电信、社会保险、财产登记等事务需要提供身份证明的，可以凭本人的护照证明其身份。"},{"i":15,"n":"第十五条","txt":"外国人入境，应当向驻外签证机关申请办理签证，但是本法另有规定的除外。"},{"i":16,"n":"第十六条","txt":"签证分为外交签证、礼遇签证、公务签证、普通签证。"},{"i":17,"n":"第十七条","txt":"签证的登记项目包括：签证种类，持有人姓名、性别、出生日期、入境次数、入境有效期、停留期限，签发日期、地点，护照或者其他国际旅行证件号码等。"},{"i":18,"n":"第十八条","txt":"外国人申请办理签证，应当向驻外签证机关提交本人的护照或者其他国际旅行证件，以及申请事由的相关材料，按照驻外签证机关的要求办理相关手续、接受面谈。"},{"i":19,"n":"第十九条","txt":"外国人申请办理签证需要提供中国境内的单位或者个人出具的邀请函件的，申请人应当按照驻外签证机关的要求提供。出具邀请函件的单位或者个人应当对邀请内容的真实性负责。"},{"i":20,"n":"第二十条","txt":"出于人道原因需要紧急入境，应邀入境从事紧急商务、工程抢修或者具有其他紧急入境需要并持有有关主管部门同意在口岸申办签证的证明材料的外国人，可以在国务院批准办理口岸签证业务的口岸，向公安部委托的口岸签证机关（以下简称口岸签证机关）申请办理口岸签证。"},{"i":21,"n":"第二十一条","txt":"外国人有下列情形之一的，不予签发签证："},{"i":22,"n":"第二十二条","txt":"外国人有下列情形之一的，可以免办签证："},{"i":23,"n":"第二十三条","txt":"有下列情形之一的外国人需要临时入境的，应当向出入境边防检查机关申请办理临时入境手续："},{"i":24,"n":"第二十四条","txt":"外国人入境，应当向出入境边防检查机关交验本人的护照或者其他国际旅行证件、签证或者其他入境许可证明，履行规定的手续，经查验准许，方可入境。"},{"i":25,"n":"第二十五条","txt":"外国人有下列情形之一的，不准入境："},{"i":26,"n":"第二十六条","txt":"对未被准许入境的外国人，出入境边防检查机关应当责令其返回；对拒不返回的，强制其返回。外国人等待返回期间，不得离开限定的区域。"},{"i":27,"n":"第二十七条","txt":"外国人出境，应当向出入境边防检查机关交验本人的护照或者其他国际旅行证件等出境入境证件，履行规定的手续，经查验准许，方可出境。"},{"i":28,"n":"第二十八条","txt":"外国人有下列情形之一的，不准出境："},{"i":29,"n":"第二十九条","txt":"外国人所持签证注明的停留期限不超过一百八十日的，持证人凭签证并按照签证注明的停留期限在中国境内停留。"},{"i":30,"n":"第三十条","txt":"外国人所持签证注明入境后需要办理居留证件的，应当自入境之日起三十日内，向拟居留地县级以上地方人民政府公安机关出入境管理机构申请办理外国人居留证件。"},{"i":31,"n":"第三十一条","txt":"外国人有下列情形之一的，不予签发外国人居留证件："},{"i":32,"n":"第三十二条","txt":"在中国境内居留的外国人申请延长居留期限的，应当在居留证件有效期限届满三十日前向居留地县级以上地方人民政府公安机关出入境管理机构提出申请，按照要求提交申请事由的相关材料。经审查，延期理由合理、充分的，准予延长居留期限；不予延长居留期限的，应当按期离境。"},{"i":33,"n":"第三十三条","txt":"外国人居留证件的登记项目包括：持有人姓名、性别、出生日期、居留事由、居留期限，签发日期、地点，护照或者其他国际旅行证件号码等。"},{"i":34,"n":"第三十四条","txt":"免办签证入境的外国人需要超过免签期限在中国境内停留的，外国船员及其随行家属在中国境内停留需要离开港口所在城市，或者具有需要办理外国人停留证件其他情形的，应当按照规定办理外国人停留证件。"},{"i":35,"n":"第三十五条","txt":"外国人入境后，所持的普通签证、停留居留证件损毁、遗失、被盗抢或者有符合国家规定的事由需要换发、补发的，应当按照规定向停留居留地县级以上地方人民政府公安机关出入境管理机构提出申请。"},{"i":36,"n":"第三十六条","txt":"公安机关出入境管理机构作出的不予办理普通签证延期、换发、补发，不予办理外国人停留居留证件、不予延长居留期限的决定为最终决定。"},{"i":37,"n":"第三十七条","txt":"外国人在中国境内停留居留，不得从事与停留居留事由不相符的活动，并应当在规定的停留居留期限届满前离境。"},{"i":38,"n":"第三十八条","txt":"年满十六周岁的外国人在中国境内停留居留，应当随身携带本人的护照或者其他国际旅行证件，或者外国人停留居留证件，接受公安机关的查验。"},{"i":39,"n":"第三十九条","txt":"外国人在中国境内旅馆住宿的，旅馆应当按照旅馆业治安管理的有关规定为其办理住宿登记，并向所在地公安机关报送外国人住宿登记信息。"},{"i":40,"n":"第四十条","txt":"在中国境内出生的外国婴儿，其父母或者代理人应当在婴儿出生六十日内，持该婴儿的出生证明到父母停留居留地县级以上地方人民政府公安机关出入境管理机构为其办理停留或者居留登记。"},{"i":41,"n":"第四十一条","txt":"外国人在中国境内工作，应当按照规定取得工作许可和工作类居留证件。任何单位和个人不得聘用未取得工作许可和工作类居留证件的外国人。"},{"i":42,"n":"第四十二条","txt":"国务院人力资源社会保障主管部门、外国专家主管部门会同国务院有关部门根据经济社会发展需要和人力资源供求状况制定并定期调整外国人在中国境内工作指导目录。"},{"i":43,"n":"第四十三条","txt":"外国人有下列行为之一的，属于非法就业："},{"i":44,"n":"第四十四条","txt":"根据维护国家安全、公共安全的需要，公安机关、国家安全机关可以限制外国人、外国机构在某些地区设立居住或者办公场所；对已经设立的，可以限期迁离。"},{"i":45,"n":"第四十五条","txt":"聘用外国人工作或者招收外国留学生的单位，应当按照规定向所在地公安机关报告有关信息。"},{"i":46,"n":"第四十六条","txt":"申请难民地位的外国人，在难民地位甄别期间，可以凭公安机关签发的临时身份证明在中国境内停留；被认定为难民的外国人，可以凭公安机关签发的难民身份证件在中国境内停留居留。"},{"i":47,"n":"第四十七条","txt":"对中国经济社会发展作出突出贡献或者符合其他在中国境内永久居留条件的外国人，经本人申请和公安部批准，取得永久居留资格。"},{"i":48,"n":"第四十八条","txt":"取得永久居留资格的外国人，凭永久居留证件在中国境内居留和工作，凭本人的护照和永久居留证件出境入境。"},{"i":49,"n":"第四十九条","txt":"外国人有下列情形之一的，由公安部决定取消其在中国境内永久居留资格："},{"i":50,"n":"第五十条","txt":"出境入境交通运输工具离开、抵达口岸时，应当接受边防检查。对交通运输工具的入境边防检查，在其最先抵达的口岸进行；对交通运输工具的出境边防检查，在其最后离开的口岸进行。特殊情况下，可以在有关主管机关指定的地点进行。"},{"i":51,"n":"第五十一条","txt":"交通运输工具负责人或者交通运输工具出境入境业务代理单位应当按照规定提前向出入境边防检查机关报告入境、出境的交通运输工具抵达、离开口岸的时间和停留地点，如实申报员工、旅客、货物或者物品等信息。"},{"i":52,"n":"第五十二条","txt":"交通运输工具负责人、交通运输工具出境入境业务代理单位应当配合出境入境边防检查，发现违反本法规定行为的，应当立即报告并协助调查处理。"},{"i":53,"n":"第五十三条","txt":"出入境边防检查机关按照规定对处于下列情形之一的出境入境交通运输工具进行监护："},{"i":54,"n":"第五十四条","txt":"因装卸物品、维修作业、参观访问等事由需要上下外国船舶的人员，应当向出入境边防检查机关申请办理登轮证件。"},{"i":55,"n":"第五十五条","txt":"外国船舶、航空器在中国境内应当按照规定的路线、航线行驶。"},{"i":56,"n":"第五十六条","txt":"交通运输工具有下列情形之一的，不准出境入境；已经驶离口岸的，可以责令返回："},{"i":57,"n":"第五十七条","txt":"从事交通运输工具出境入境业务代理的单位，应当向出入境边防检查机关备案。从事业务代理的人员，由所在单位向出入境边防检查机关办理备案手续。"},{"i":58,"n":"第五十八条","txt":"本章规定的当场盘问、继续盘问、拘留审查、限制活动范围、遣送出境措施，由县级以上地方人民政府公安机关或者出入境边防检查机关实施。"},{"i":59,"n":"第五十九条","txt":"对涉嫌违反出境入境管理的人员，可以当场盘问；经当场盘问，有下列情形之一的，可以依法继续盘问："},{"i":60,"n":"第六十条","txt":"外国人有本法第五十九条第一款规定情形之一的，经当场盘问或者继续盘问后仍不能排除嫌疑，需要作进一步调查的，可以拘留审查。"},{"i":61,"n":"第六十一条","txt":"外国人有下列情形之一的，不适用拘留审查，可以限制其活动范围："},{"i":62,"n":"第六十二条","txt":"外国人有下列情形之一的，可以遣送出境："},{"i":63,"n":"第六十三条","txt":"被拘留审查或者被决定遣送出境但不能立即执行的人员，应当羁押在拘留所或者遣返场所。"},{"i":64,"n":"第六十四条","txt":"外国人对依照本法规定对其实施的继续盘问、拘留审查、限制活动范围、遣送出境措施不服的，可以依法申请行政复议，该行政复议决定为最终决定。"},{"i":65,"n":"第六十五条","txt":"对依法决定不准出境或者不准入境的人员，决定机关应当按照规定及时通知出入境边防检查机关；不准出境、入境情形消失的，决定机关应当及时撤销不准出境、入境决定，并通知出入境边防检查机关。"},{"i":66,"n":"第六十六条","txt":"根据维护国家安全和出境入境管理秩序的需要，必要时，出入境边防检查机关可以对出境入境的人员进行人身检查。人身检查应当由两名与受检查人同性别的边防检查人员进行。"},{"i":67,"n":"第六十七条","txt":"签证、外国人停留居留证件等出境入境证件发生损毁、遗失、被盗抢或者签发后发现持证人不符合签发条件等情形的，由签发机关宣布该出境入境证件作废。"},{"i":68,"n":"第六十八条","txt":"对用于组织、运送、协助他人非法出境入境的交通运输工具，以及需要作为办案证据的物品，公安机关可以扣押。"},{"i":69,"n":"第六十九条","txt":"出境入境证件的真伪由签发机关、出入境边防检查机关或者公安机关出入境管理机构认定。"},{"i":70,"n":"第七十条","txt":"本章规定的行政处罚，除本章另有规定外，由县级以上地方人民政府公安机关或者出入境边防检查机关决定；其中警告或者五千元以下罚款，可以由县级以上地方人民政府公安机关出入境管理机构决定。"},{"i":71,"n":"第七十一条","txt":"有下列行为之一的，处一千元以上五千元以下罚款；情节严重的，处五日以上十日以下拘留，可以并处二千元以上一万元以下罚款："},{"i":72,"n":"第七十二条","txt":"协助他人非法出境入境的，处二千元以上一万元以下罚款；情节严重的，处十日以上十五日以下拘留，并处五千元以上二万元以下罚款，有违法所得的，没收违法所得。"},{"i":73,"n":"第七十三条","txt":"弄虚作假骗取签证、停留居留证件等出境入境证件的，处二千元以上五千元以下罚款；情节严重的，处十日以上十五日以下拘留，并处五千元以上二万元以下罚款。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，为外国人出具邀请函件或者其他申请材料的，处五千元以上一万元以下罚款，有违法所得的，没收违法所得，并责令其承担所邀请外国人的出境费用。"},{"i":75,"n":"第七十五条","txt":"中国公民出境后非法前往其他国家或者地区被遣返的，出入境边防检查机关应当收缴其出境入境证件，出境入境证件签发机关自其被遣返之日起六个月至三年以内不予签发出境入境证件。"},{"i":76,"n":"第七十六条","txt":"有下列情形之一的，给予警告，可以并处二千元以下罚款："},{"i":77,"n":"第七十七条","txt":"外国人未经批准，擅自进入限制外国人进入的区域，责令立即离开；情节严重的，处五日以上十日以下拘留。对外国人非法获取的文字记录、音像资料、电子数据和其他物品，予以收缴或者销毁，所用工具予以收缴。"},{"i":78,"n":"第七十八条","txt":"外国人非法居留的，给予警告；情节严重的，处每非法居留一日五百元，总额不超过一万元的罚款或者五日以上十五日以下拘留。"},{"i":79,"n":"第七十九条","txt":"容留、藏匿非法入境、非法居留的外国人，协助非法入境、非法居留的外国人逃避检查，或者为非法居留的外国人违法提供出境入境证件的，处二千元以上一万元以下罚款；情节严重的，处五日以上十五日以下拘留，并处五千元以上二万元以下罚款，有违法所得的，没收违法所得。"},{"i":80,"n":"第八十条","txt":"外国人非法就业的，处五千元以上二万元以下罚款；情节严重的，处五日以上十五日以下拘留，并处五千元以上二万元以下罚款。"},{"i":81,"n":"第八十一条","txt":"外国人从事与停留居留事由不相符的活动，或者有其他违反中国法律、法规规定，不适宜在中国境内继续停留居留情形的，可以处限期出境。"},{"i":82,"n":"第八十二条","txt":"有下列情形之一的，给予警告，可以并处二千元以下罚款："},{"i":83,"n":"第八十三条","txt":"交通运输工具有下列情形之一的，对其负责人处五千元以上五万元以下罚款："},{"i":84,"n":"第八十四条","txt":"交通运输工具有下列情形之一的，对其负责人处二千元以上二万元以下罚款："},{"i":85,"n":"第八十五条","txt":"履行出境入境管理职责的工作人员，有下列行为之一的，依法给予处分："},{"i":86,"n":"第八十六条","txt":"对违反出境入境管理行为处五百元以下罚款的，出入境边防检查机关可以当场作出处罚决定。"},{"i":87,"n":"第八十七条","txt":"对违反出境入境管理行为处罚款的，被处罚人应当自收到处罚决定书之日起十五日内，到指定的银行缴纳罚款。被处罚人在所在地没有固定住所，不当场收缴罚款事后难以执行或者在口岸向指定银行缴纳罚款确有困难的，可以当场收缴。"},{"i":88,"n":"第八十八条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":89,"n":"第八十九条","txt":"本法下列用语的含义："},{"i":90,"n":"第九十条","txt":"经国务院批准，同毗邻国家接壤的省、自治区可以根据中国与有关国家签订的边界管理协定制定地方性法规、地方政府规章，对两国边境接壤地区的居民往来作出规定。"},{"i":91,"n":"第九十一条","txt":"外国驻中国的外交代表机构、领事机构成员以及享有特权和豁免的其他外国人，其入境出境及停留居留管理，其他法律另有规定的，依照其规定。"},{"i":92,"n":"第九十二条","txt":"外国人申请办理签证、外国人停留居留证件等出境入境证件或者申请办理证件延期、变更的，应当按照规定缴纳签证费、证件费。"},{"i":93,"n":"第九十三条","txt":"本法自2013年7月1日起施行。《中华人民共和国外国人入境出境管理法》和《中华人民共和国公民出境入境管理法》同时废止。"}],"yishifa":[{"i":1,"n":"第一条","txt":"为了保障医师合法权益，规范医师执业行为，加强医师队伍建设，保护人民健康，推进健康中国建设，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称医师，是指依法取得医师资格，经注册在医疗卫生机构中执业的专业医务人员，包括执业医师和执业助理医师。"},{"i":3,"n":"第三条","txt":"医师应当坚持人民至上、生命至上，发扬人道主义精神，弘扬敬佑生命、救死扶伤、甘于奉献、大爱无疆的崇高职业精神，恪守职业道德，遵守执业规范，提高执业水平，履行防病治病、保护人民健康的神圣职责。"},{"i":4,"n":"第四条","txt":"国务院卫生健康主管部门负责全国的医师管理工作。国务院教育、人力资源社会保障、中医药等有关部门在各自职责范围内负责有关的医师管理工作。"},{"i":5,"n":"第五条","txt":"每年8月19日为中国医师节。"},{"i":6,"n":"第六条","txt":"国家建立健全医师医学专业技术职称设置、评定和岗位聘任制度，将职业道德、专业实践能力和工作业绩作为重要条件，科学设置有关评定、聘任标准。"},{"i":7,"n":"第七条","txt":"医师可以依法组织和参加医师协会等有关行业组织、专业学术团体。"},{"i":8,"n":"第八条","txt":"国家实行医师资格考试制度。"},{"i":9,"n":"第九条","txt":"具有下列条件之一的，可以参加执业医师资格考试："},{"i":10,"n":"第十条","txt":"具有高等学校相关医学专业专科以上学历，在执业医师指导下，在医疗卫生机构中参加医学专业工作实践满一年的，可以参加执业助理医师资格考试。"},{"i":11,"n":"第十一条","txt":"以师承方式学习中医满三年，或者经多年实践医术确有专长的，经县级以上人民政府卫生健康主管部门委托的中医药专业组织或者医疗卫生机构考核合格并推荐，可以参加中医医师资格考试。"},{"i":12,"n":"第十二条","txt":"医师资格考试成绩合格，取得执业医师资格或者执业助理医师资格，发给医师资格证书。"},{"i":13,"n":"第十三条","txt":"国家实行医师执业注册制度。"},{"i":14,"n":"第十四条","txt":"医师经注册后，可以在医疗卫生机构中按照注册的执业地点、执业类别、执业范围执业，从事相应的医疗卫生服务。"},{"i":15,"n":"第十五条","txt":"医师在二个以上医疗卫生机构定期执业的，应当以一个医疗卫生机构为主，并按照国家有关规定办理相关手续。国家鼓励医师定期定点到县级以下医疗卫生机构，包括乡镇卫生院、村卫生室、社区卫生服务中心等，提供医疗卫生服务，主执业机构应当支持并提供便利。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，不予注册："},{"i":17,"n":"第十七条","txt":"医师注册后有下列情形之一的，注销注册，废止医师执业证书："},{"i":18,"n":"第十八条","txt":"医师变更执业地点、执业类别、执业范围等注册事项的，应当依照本法规定到准予注册的卫生健康主管部门办理变更注册手续。"},{"i":19,"n":"第十九条","txt":"中止医师执业活动二年以上或者本法规定不予注册的情形消失，申请重新执业的，应当由县级以上人民政府卫生健康主管部门或者其委托的医疗卫生机构、行业组织考核合格，并依照本法规定重新注册。"},{"i":20,"n":"第二十条","txt":"医师个体行医应当依法办理审批或者备案手续。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府卫生健康主管部门应当将准予注册和注销注册的人员名单及时予以公告，由省级人民政府卫生健康主管部门汇总，报国务院卫生健康主管部门备案，并按照规定通过网站提供医师注册信息查询服务。"},{"i":22,"n":"第二十二条","txt":"医师在执业活动中享有下列权利："},{"i":23,"n":"第二十三条","txt":"医师在执业活动中履行下列义务："},{"i":24,"n":"第二十四条","txt":"医师实施医疗、预防、保健措施，签署有关医学证明文件，必须亲自诊查、调查，并按照规定及时填写病历等医学文书，不得隐匿、伪造、篡改或者擅自销毁病历等医学文书及有关资料。"},{"i":25,"n":"第二十五条","txt":"医师在诊疗活动中应当向患者说明病情、医疗措施和其他需要告知的事项。需要实施手术、特殊检查、特殊治疗的，医师应当及时向患者具体说明医疗风险、替代医疗方案等情况，并取得其明确同意；不能或者不宜向患者说明的，应当向患者的近亲属说明，并取得其明确同意。"},{"i":26,"n":"第二十六条","txt":"医师开展药物、医疗器械临床试验和其他医学临床研究应当符合国家有关规定，遵守医学伦理规范，依法通过伦理审查，取得书面知情同意。"},{"i":27,"n":"第二十七条","txt":"对需要紧急救治的患者，医师应当采取紧急措施进行诊治，不得拒绝急救处置。"},{"i":28,"n":"第二十八条","txt":"医师应当使用经依法批准或者备案的药品、消毒药剂、医疗器械，采用合法、合规、科学的诊疗方法。"},{"i":29,"n":"第二十九条","txt":"医师应当坚持安全有效、经济合理的用药原则，遵循药品临床应用指导原则、临床诊疗指南和药品说明书等合理用药。"},{"i":30,"n":"第三十条","txt":"执业医师按照国家有关规定，经所在医疗卫生机构同意，可以通过互联网等信息技术提供部分常见病、慢性病复诊等适宜的医疗卫生服务。国家支持医疗卫生机构之间利用互联网等信息技术开展远程医疗合作。"},{"i":31,"n":"第三十一条","txt":"医师不得利用职务之便，索要、非法收受财物或者牟取其他不正当利益；不得对患者实施不必要的检查、治疗。"},{"i":32,"n":"第三十二条","txt":"遇有自然灾害、事故灾难、公共卫生事件和社会安全事件等严重威胁人民生命健康的突发事件时，县级以上人民政府卫生健康主管部门根据需要组织医师参与卫生应急处置和医疗救治，医师应当服从调遣。"},{"i":33,"n":"第三十三条","txt":"在执业活动中有下列情形之一的，医师应当按照有关规定及时向所在医疗卫生机构或者有关部门、机构报告："},{"i":34,"n":"第三十四条","txt":"执业助理医师应当在执业医师的指导下，在医疗卫生机构中按照注册的执业类别、执业范围执业。"},{"i":35,"n":"第三十五条","txt":"参加临床教学实践的医学生和尚未取得医师执业证书、在医疗卫生机构中参加医学专业工作实践的医学毕业生，应当在执业医师监督、指导下参与临床诊疗活动。医疗卫生机构应当为有关医学生、医学毕业生参与临床诊疗活动提供必要的条件。"},{"i":36,"n":"第三十六条","txt":"有关行业组织、医疗卫生机构、医学院校应当加强对医师的医德医风教育。"},{"i":37,"n":"第三十七条","txt":"国家制定医师培养规划，建立适应行业特点和社会需求的医师培养和供需平衡机制，统筹各类医学人才需求，加强全科、儿科、精神科、老年医学等紧缺专业人才培养。"},{"i":38,"n":"第三十八条","txt":"国家建立健全住院医师规范化培训制度，健全临床带教激励机制，保障住院医师培训期间待遇，严格培训过程管理和结业考核。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府卫生健康主管部门和其他有关部门应当制定医师培训计划，采取多种形式对医师进行分级分类培训，为医师接受继续医学教育提供条件。"},{"i":40,"n":"第四十条","txt":"医疗卫生机构应当合理调配人力资源，按照规定和计划保证本机构医师接受继续医学教育。"},{"i":41,"n":"第四十一条","txt":"国家在每年的医学专业招生计划和教育培训计划中，核定一定比例用于定向培养、委托培训，加强基层和艰苦边远地区医师队伍建设。"},{"i":42,"n":"第四十二条","txt":"国家实行医师定期考核制度。"},{"i":43,"n":"第四十三条","txt":"省级以上人民政府卫生健康主管部门负责指导、检查和监督医师考核工作。"},{"i":44,"n":"第四十四条","txt":"国家建立健全体现医师职业特点和技术劳动价值的人事、薪酬、职称、奖励制度。"},{"i":45,"n":"第四十五条","txt":"国家加强疾病预防控制人才队伍建设，建立适应现代化疾病预防控制体系的医师培养和使用机制。"},{"i":46,"n":"第四十六条","txt":"国家采取措施，统筹城乡资源，加强基层医疗卫生队伍和服务能力建设，对乡村医疗卫生人员建立县乡村上下贯通的职业发展机制，通过县管乡用、乡聘村用等方式，将乡村医疗卫生人员纳入县域医疗卫生人员管理。"},{"i":47,"n":"第四十七条","txt":"国家鼓励在村医疗卫生机构中向村民提供预防、保健和一般医疗服务的乡村医生通过医学教育取得医学专业学历；鼓励符合条件的乡村医生参加医师资格考试，依法取得医师资格。"},{"i":48,"n":"第四十八条","txt":"医师有下列情形之一的，按照国家有关规定给予表彰、奖励："},{"i":49,"n":"第四十九条","txt":"县级以上人民政府及其有关部门应当将医疗纠纷预防和处理工作纳入社会治安综合治理体系，加强医疗卫生机构及周边治安综合治理，维护医疗卫生机构良好的执业环境，有效防范和依法打击涉医违法犯罪行为，保护医患双方合法权益。"},{"i":50,"n":"第五十条","txt":"医疗卫生机构应当为医师提供职业安全和卫生防护用品，并采取有效的卫生防护和医疗保健措施。"},{"i":51,"n":"第五十一条","txt":"医疗卫生机构应当为医师合理安排工作时间，落实带薪休假制度，定期开展健康检查。"},{"i":52,"n":"第五十二条","txt":"国家建立完善医疗风险分担机制。医疗机构应当参加医疗责任保险或者建立、参加医疗风险基金。鼓励患者参加医疗意外保险。"},{"i":53,"n":"第五十三条","txt":"新闻媒体应当开展医疗卫生法律、法规和医疗卫生知识的公益宣传，弘扬医师先进事迹，引导公众尊重医师、理性对待医疗卫生风险。"},{"i":54,"n":"第五十四条","txt":"在医师资格考试中有违反考试纪律等行为，情节严重的，一年至三年内禁止参加医师资格考试。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，医师在执业活动中有下列行为之一的，由县级以上人民政府卫生健康主管部门责令改正，给予警告；情节严重的，责令暂停六个月以上一年以下执业活动直至吊销医师执业证书："},{"i":56,"n":"第五十六条","txt":"违反本法规定，医师在执业活动中有下列行为之一的，由县级以上人民政府卫生健康主管部门责令改正，给予警告，没收违法所得，并处一万元以上三万元以下的罚款；情节严重的，责令暂停六个月以上一年以下执业活动直至吊销医师执业证书："},{"i":57,"n":"第五十七条","txt":"违反本法规定，医师未按照注册的执业地点、执业类别、执业范围执业的，由县级以上人民政府卫生健康主管部门或者中医药主管部门责令改正，给予警告，没收违法所得，并处一万元以上三万元以下的罚款；情节严重的，责令暂停六个月以上一年以下执业活动直至吊销医师执业证书。"},{"i":58,"n":"第五十八条","txt":"严重违反医师职业道德、医学伦理规范，造成恶劣社会影响的，由省级以上人民政府卫生健康主管部门吊销医师执业证书或者责令停止非法执业活动，五年直至终身禁止从事医疗卫生服务或者医学临床研究。"},{"i":59,"n":"第五十九条","txt":"违反本法规定，非医师行医的，由县级以上人民政府卫生健康主管部门责令停止非法执业活动，没收违法所得和药品、医疗器械，并处违法所得二倍以上十倍以下的罚款，违法所得不足一万元的，按一万元计算。"},{"i":60,"n":"第六十条","txt":"违反本法规定，阻碍医师依法执业，干扰医师正常工作、生活，或者通过侮辱、诽谤、威胁、殴打等方式，侵犯医师人格尊严、人身安全，构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，医疗卫生机构未履行报告职责，造成严重后果的，由县级以上人民政府卫生健康主管部门给予警告，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，卫生健康主管部门和其他有关部门工作人员或者医疗卫生机构工作人员弄虚作假、滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任；造成人身、财产损害的，依法承担民事责任。"},{"i":64,"n":"第六十四条","txt":"国家采取措施，鼓励具有中等专业学校医学专业学历的人员通过参加更高层次学历教育等方式，提高医学技术能力和水平。"},{"i":65,"n":"第六十五条","txt":"中国人民解放军和中国人民武装警察部队执行本法的具体办法，由国务院、中央军事委员会依据本法制定。"},{"i":66,"n":"第六十六条","txt":"境外人员参加医师资格考试、申请注册、执业或者从事临床示教、临床研究、临床学术交流等活动的具体管理办法，由国务院卫生健康主管部门制定。"},{"i":67,"n":"第六十七条","txt":"本法自2022年3月1日起施行。《中华人民共和国执业医师法》同时废止。"}],"fankongbuzhuyifa":[{"i":1,"n":"第一条","txt":"为了防范和惩治恐怖活动，加强反恐怖主义工作，维护国家安全、公共安全和人民生命财产安全，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家反对一切形式的恐怖主义，依法取缔恐怖活动组织，对任何组织、策划、准备实施、实施恐怖活动，宣扬恐怖主义，煽动实施恐怖活动，组织、领导、参加恐怖活动组织，为恐怖活动提供帮助的，依法追究法律责任。"},{"i":3,"n":"第三条","txt":"本法所称恐怖主义，是指通过暴力、破坏、恐吓等手段，制造社会恐慌、危害公共安全、侵犯人身财产，或者胁迫国家机关、国际组织，以实现其政治、意识形态等目的的主张和行为。"},{"i":4,"n":"第四条","txt":"国家将反恐怖主义纳入国家安全战略，综合施策，标本兼治，加强反恐怖主义的能力建设，运用政治、经济、法律、文化、教育、外交、军事等手段，开展反恐怖主义工作。"},{"i":5,"n":"第五条","txt":"反恐怖主义工作坚持专门工作与群众路线相结合，防范为主、惩防结合和先发制敌、保持主动的原则。"},{"i":6,"n":"第六条","txt":"反恐怖主义工作应当依法进行，尊重和保障人权，维护公民和组织的合法权益。"},{"i":7,"n":"第七条","txt":"国家设立反恐怖主义工作领导机构，统一领导和指挥全国反恐怖主义工作。"},{"i":8,"n":"第八条","txt":"公安机关、国家安全机关和人民检察院、人民法院、司法行政机关以及其他有关国家机关，应当根据分工，实行工作责任制，依法做好反恐怖主义工作。"},{"i":9,"n":"第九条","txt":"任何单位和个人都有协助、配合有关部门开展反恐怖主义工作的义务，发现恐怖活动嫌疑或者恐怖活动嫌疑人员的，应当及时向公安机关或者有关部门报告。"},{"i":10,"n":"第十条","txt":"对举报恐怖活动或者协助防范、制止恐怖活动有突出贡献的单位和个人，以及在反恐怖主义工作中作出其他突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":11,"n":"第十一条","txt":"对在中华人民共和国领域外对中华人民共和国国家、公民或者机构实施的恐怖活动犯罪，或者实施的中华人民共和国缔结、参加的国际条约所规定的恐怖活动犯罪，中华人民共和国行使刑事管辖权，依法追究刑事责任。"},{"i":12,"n":"第十二条","txt":"国家反恐怖主义工作领导机构根据本法第三条的规定，认定恐怖活动组织和人员，由国家反恐怖主义工作领导机构的办事机构予以公告。"},{"i":13,"n":"第十三条","txt":"国务院公安部门、国家安全部门、外交部门和省级反恐怖主义工作领导机构对于需要认定恐怖活动组织和人员的，应当向国家反恐怖主义工作领导机构提出申请。"},{"i":14,"n":"第十四条","txt":"金融机构和特定非金融机构对国家反恐怖主义工作领导机构的办事机构公告的恐怖活动组织和人员的资金或者其他资产，应当立即予以冻结，并按照规定及时向国务院公安部门、国家安全部门和反洗钱行政主管部门报告。"},{"i":15,"n":"第十五条","txt":"被认定的恐怖活动组织和人员对认定不服的，可以通过国家反恐怖主义工作领导机构的办事机构申请复核。国家反恐怖主义工作领导机构应当及时进行复核，作出维持或者撤销认定的决定。复核决定为最终决定。"},{"i":16,"n":"第十六条","txt":"根据刑事诉讼法的规定，有管辖权的中级以上人民法院在审判刑事案件的过程中，可以依法认定恐怖活动组织和人员。对于在判决生效后需要由国家反恐怖主义工作领导机构的办事机构予以公告的，适用本章的有关规定。"},{"i":17,"n":"第十七条","txt":"各级人民政府和有关部门应当组织开展反恐怖主义宣传教育，提高公民的反恐怖主义意识。"},{"i":18,"n":"第十八条","txt":"电信业务经营者、互联网服务提供者应当为公安机关、国家安全机关依法进行防范、调查恐怖活动提供技术接口和解密等技术支持和协助。"},{"i":19,"n":"第十九条","txt":"电信业务经营者、互联网服务提供者应当依照法律、行政法规规定，落实网络安全、信息内容监督制度和安全技术防范措施，防止含有恐怖主义、极端主义内容的信息传播；发现含有恐怖主义、极端主义内容的信息的，应当立即停止传输，保存相关记录，删除相关信息，并向公安机关或者有关部门报告。"},{"i":20,"n":"第二十条","txt":"铁路、公路、水上、航空的货运和邮政、快递等物流运营单位应当实行安全查验制度，对客户身份进行查验，依照规定对运输、寄递物品进行安全检查或者开封验视。对禁止运输、寄递，存在重大安全隐患，或者客户拒绝安全查验的物品，不得运输、寄递。"},{"i":21,"n":"第二十一条","txt":"电信、互联网、金融、住宿、长途客运、机动车租赁等业务经营者、服务提供者，应当对客户身份进行查验。对身份不明或者拒绝身份查验的，不得提供服务。"},{"i":22,"n":"第二十二条","txt":"生产和进口单位应当依照规定对枪支等武器、弹药、管制器具、危险化学品、民用爆炸物品、核与放射物品作出电子追踪标识，对民用爆炸物品添加安检示踪标识物。"},{"i":23,"n":"第二十三条","txt":"发生枪支等武器、弹药、危险化学品、民用爆炸物品、核与放射物品、传染病病原体等物质被盗、被抢、丢失或者其他流失的情形，案发单位应当立即采取必要的控制措施，并立即向公安机关报告，同时依照规定向有关主管部门报告。公安机关接到报告后，应当及时开展调查。有关主管部门应当配合公安机关开展工作。"},{"i":24,"n":"第二十四条","txt":"国务院反洗钱行政主管部门、国务院有关部门、机构依法对金融机构和特定非金融机构履行反恐怖主义融资义务的情况进行监督管理。"},{"i":25,"n":"第二十五条","txt":"审计、财政、税务等部门在依照法律、行政法规的规定对有关单位实施监督检查的过程中，发现资金流入流出涉嫌恐怖主义融资的，应当及时通报公安机关。"},{"i":26,"n":"第二十六条","txt":"海关在对进出境人员携带现金和无记名有价证券实施监管的过程中，发现涉嫌恐怖主义融资的，应当立即通报国务院反洗钱行政主管部门和有管辖权的公安机关。"},{"i":27,"n":"第二十七条","txt":"地方各级人民政府制定、组织实施城乡规划，应当符合反恐怖主义工作的需要。"},{"i":28,"n":"第二十八条","txt":"公安机关和有关部门对宣扬极端主义，利用极端主义危害公共安全、扰乱公共秩序、侵犯人身财产、妨害社会管理的，应当及时予以制止，依法追究法律责任。"},{"i":29,"n":"第二十九条","txt":"对被教唆、胁迫、引诱参与恐怖活动、极端主义活动，或者参与恐怖活动、极端主义活动情节轻微，尚不构成犯罪的人员，公安机关应当组织有关部门、村民委员会、居民委员会、所在单位、就读学校、家庭和监护人对其进行帮教。"},{"i":30,"n":"第三十条","txt":"对恐怖活动罪犯和极端主义罪犯被判处徒刑以上刑罚的，监狱、看守所应当在刑满释放前根据其犯罪性质、情节和社会危害程度，服刑期间的表现，释放后对所居住社区的影响等进行社会危险性评估。进行社会危险性评估，应当听取有关基层组织和原办案机关的意见。经评估具有社会危险性的，监狱、看守所应当向罪犯服刑地的中级人民法院提出安置教育建议，并将建议书副本抄送同级人民检察院。"},{"i":31,"n":"第三十一条","txt":"公安机关应当会同有关部门，将遭受恐怖袭击的可能性较大以及遭受恐怖袭击可能造成重大的人身伤亡、财产损失或者社会影响的单位、场所、活动、设施等确定为防范恐怖袭击的重点目标，报本级反恐怖主义工作领导机构备案。"},{"i":32,"n":"第三十二条","txt":"重点目标的管理单位应当履行下列职责："},{"i":33,"n":"第三十三条","txt":"重点目标的管理单位应当对重要岗位人员进行安全背景审查。对有不适合情形的人员，应当调整工作岗位，并将有关情况通报公安机关。"},{"i":34,"n":"第三十四条","txt":"大型活动承办单位以及重点目标的管理单位应当依照规定，对进入大型活动场所、机场、火车站、码头、城市轨道交通站、公路长途客运站、口岸等重点目标的人员、物品和交通工具进行安全检查。发现违禁品和管制物品，应当予以扣留并立即向公安机关报告；发现涉嫌违法犯罪人员，应当立即向公安机关报告。"},{"i":35,"n":"第三十五条","txt":"对航空器、列车、船舶、城市轨道车辆、公共电汽车等公共交通运输工具，营运单位应当依照规定配备安保人员和相应设备、设施，加强安全检查和保卫工作。"},{"i":36,"n":"第三十六条","txt":"公安机关和有关部门应当掌握重点目标的基础信息和重要动态，指导、监督重点目标的管理单位履行防范恐怖袭击的各项职责。"},{"i":37,"n":"第三十七条","txt":"飞行管制、民用航空、公安等主管部门应当按照职责分工，加强空域、航空器和飞行活动管理，严密防范针对航空器或者利用飞行活动实施的恐怖活动。"},{"i":38,"n":"第三十八条","txt":"各级人民政府和军事机关应当在重点国（边）境地段和口岸设置拦阻隔离网、视频图像采集和防越境报警设施。"},{"i":39,"n":"第三十九条","txt":"出入境证件签发机关、出入境边防检查机关对恐怖活动人员和恐怖活动嫌疑人员，有权决定不准其出境入境、不予签发出境入境证件或者宣布其出境入境证件作废。"},{"i":40,"n":"第四十条","txt":"海关、出入境边防检查机关发现恐怖活动嫌疑人员或者涉嫌恐怖活动物品的，应当依法扣留，并立即移送公安机关或者国家安全机关。"},{"i":41,"n":"第四十一条","txt":"国务院外交、公安、国家安全、发展改革、工业和信息化、商务、旅游等主管部门应当建立境外投资合作、旅游等安全风险评估制度，对中国在境外的公民以及驻外机构、设施、财产加强安全保护，防范和应对恐怖袭击。"},{"i":42,"n":"第四十二条","txt":"驻外机构应当建立健全安全防范制度和应对处置预案，加强对有关人员、设施、财产的安全保护。"},{"i":43,"n":"第四十三条","txt":"国家反恐怖主义工作领导机构建立国家反恐怖主义情报中心，实行跨部门、跨地区情报信息工作机制，统筹反恐怖主义情报信息工作。"},{"i":44,"n":"第四十四条","txt":"公安机关、国家安全机关和有关部门应当依靠群众，加强基层基础工作，建立基层情报信息工作力量，提高反恐怖主义情报信息工作能力。"},{"i":45,"n":"第四十五条","txt":"公安机关、国家安全机关、军事机关在其职责范围内，因反恐怖主义情报信息工作的需要，根据国家有关规定，经过严格的批准手续，可以采取技术侦察措施。"},{"i":46,"n":"第四十六条","txt":"有关部门对于在本法第三章规定的安全防范工作中获取的信息，应当根据国家反恐怖主义情报中心的要求，及时提供。"},{"i":47,"n":"第四十七条","txt":"国家反恐怖主义情报中心、地方反恐怖主义工作领导机构以及公安机关等有关部门应当对有关情报信息进行筛查、研判、核查、监控，认为有发生恐怖事件危险，需要采取相应的安全防范、应对处置措施的，应当及时通报有关部门和单位，并可以根据情况发出预警。有关部门和单位应当根据通报做好安全防范、应对处置工作。"},{"i":48,"n":"第四十八条","txt":"反恐怖主义工作领导机构、有关部门和单位、个人应当对履行反恐怖主义工作职责、义务过程中知悉的国家秘密、商业秘密和个人隐私予以保密。"},{"i":49,"n":"第四十九条","txt":"公安机关接到恐怖活动嫌疑的报告或者发现恐怖活动嫌疑，需要调查核实的，应当迅速进行调查。"},{"i":50,"n":"第五十条","txt":"公安机关调查恐怖活动嫌疑，可以依照有关法律规定对嫌疑人员进行盘问、检查、传唤，可以提取或者采集肖像、指纹、虹膜图像等人体生物识别信息和血液、尿液、脱落细胞等生物样本，并留存其签名。"},{"i":51,"n":"第五十一条","txt":"公安机关调查恐怖活动嫌疑，有权向有关单位和个人收集、调取相关信息和材料。有关单位和个人应当如实提供。"},{"i":52,"n":"第五十二条","txt":"公安机关调查恐怖活动嫌疑，经县级以上公安机关负责人批准，可以查询嫌疑人员的存款、汇款、债券、股票、基金份额等财产，可以采取查封、扣押、冻结措施。查封、扣押、冻结的期限不得超过二个月，情况复杂的，可以经上一级公安机关负责人批准延长一个月。"},{"i":53,"n":"第五十三条","txt":"公安机关调查恐怖活动嫌疑，经县级以上公安机关负责人批准，可以根据其危险程度，责令恐怖活动嫌疑人员遵守下列一项或者多项约束措施："},{"i":54,"n":"第五十四条","txt":"公安机关经调查，发现犯罪事实或者犯罪嫌疑人的，应当依照刑事诉讼法的规定立案侦查。本章规定的有关期限届满，公安机关未立案侦查的，应当解除有关措施。"},{"i":55,"n":"第五十五条","txt":"国家建立健全恐怖事件应对处置预案体系。"},{"i":56,"n":"第五十六条","txt":"应对处置恐怖事件，各级反恐怖主义工作领导机构应当成立由有关部门参加的指挥机构，实行指挥长负责制。反恐怖主义工作领导机构负责人可以担任指挥长，也可以确定公安机关负责人或者反恐怖主义工作领导机构的其他成员单位负责人担任指挥长。"},{"i":57,"n":"第五十七条","txt":"恐怖事件发生后，发生地反恐怖主义工作领导机构应当立即启动恐怖事件应对处置预案，确定指挥长。有关部门和中国人民解放军、中国人民武装警察部队、民兵组织，按照反恐怖主义工作领导机构和指挥长的统一领导、指挥，协同开展打击、控制、救援、救护等现场应对处置工作。"},{"i":58,"n":"第五十八条","txt":"发现恐怖事件或者疑似恐怖事件后，公安机关应当立即进行处置，并向反恐怖主义工作领导机构报告；中国人民解放军、中国人民武装警察部队发现正在实施恐怖活动的，应当立即予以控制并将案件及时移交公安机关。"},{"i":59,"n":"第五十九条","txt":"中华人民共和国在境外的机构、人员、重要设施遭受或者可能遭受恐怖袭击的，国务院外交、公安、国家安全、商务、金融、国有资产监督管理、旅游、交通运输等主管部门应当及时启动应对处置预案。国务院外交部门应当协调有关国家采取相应措施。"},{"i":60,"n":"第六十条","txt":"应对处置恐怖事件，应当优先保护直接受到恐怖活动危害、威胁人员的人身安全。"},{"i":61,"n":"第六十一条","txt":"恐怖事件发生后，负责应对处置的反恐怖主义工作领导机构可以决定由有关部门和单位采取下列一项或者多项应对处置措施："},{"i":62,"n":"第六十二条","txt":"人民警察、人民武装警察以及其他依法配备、携带武器的应对处置人员，对在现场持枪支、刀具等凶器或者使用其他危险方法，正在或者准备实施暴力行为的人员，经警告无效的，可以使用武器；紧急情况下或者警告后可能导致更为严重危害后果的，可以直接使用武器。"},{"i":63,"n":"第六十三条","txt":"恐怖事件发生、发展和应对处置信息，由恐怖事件发生地的省级反恐怖主义工作领导机构统一发布；跨省、自治区、直辖市发生的恐怖事件，由指定的省级反恐怖主义工作领导机构统一发布。"},{"i":64,"n":"第六十四条","txt":"恐怖事件应对处置结束后，各级人民政府应当组织有关部门帮助受影响的单位和个人尽快恢复生活、生产，稳定受影响地区的社会秩序和公众情绪。"},{"i":65,"n":"第六十五条","txt":"当地人民政府应当及时给予恐怖事件受害人员及其近亲属适当的救助，并向失去基本生活条件的受害人员及其近亲属及时提供基本生活保障。卫生、医疗保障等主管部门应当为恐怖事件受害人员及其近亲属提供心理、医疗等方面的援助。"},{"i":66,"n":"第六十六条","txt":"公安机关应当及时对恐怖事件立案侦查，查明事件发生的原因、经过和结果，依法追究恐怖活动组织、人员的刑事责任。"},{"i":67,"n":"第六十七条","txt":"反恐怖主义工作领导机构应当对恐怖事件的发生和应对处置工作进行全面分析、总结评估，提出防范和应对处置改进措施，向上一级反恐怖主义工作领导机构报告。"},{"i":68,"n":"第六十八条","txt":"中华人民共和国根据缔结或者参加的国际条约，或者按照平等互惠原则，与其他国家、地区、国际组织开展反恐怖主义合作。"},{"i":69,"n":"第六十九条","txt":"国务院有关部门根据国务院授权，代表中国政府与外国政府和有关国际组织开展反恐怖主义政策对话、情报信息交流、执法合作和国际资金监管合作。"},{"i":70,"n":"第七十条","txt":"涉及恐怖活动犯罪的刑事司法协助、引渡和被判刑人移管，依照有关法律规定执行。"},{"i":71,"n":"第七十一条","txt":"经与有关国家达成协议，并报国务院批准，国务院公安部门、国家安全部门可以派员出境执行反恐怖主义任务。"},{"i":72,"n":"第七十二条","txt":"通过反恐怖主义国际合作取得的材料可以在行政处罚、刑事诉讼中作为证据使用，但我方承诺不作为证据使用的除外。"},{"i":73,"n":"第七十三条","txt":"国务院和县级以上地方各级人民政府应当按照事权划分，将反恐怖主义工作经费分别列入同级财政预算。"},{"i":74,"n":"第七十四条","txt":"公安机关、国家安全机关和有关部门，以及中国人民解放军、中国人民武装警察部队，应当依照法律规定的职责，建立反恐怖主义专业力量，加强专业训练，配备必要的反恐怖主义专业设备、设施。"},{"i":75,"n":"第七十五条","txt":"对因履行反恐怖主义工作职责或者协助、配合有关部门开展反恐怖主义工作导致伤残或者死亡的人员，按照国家有关规定给予相应的待遇。"},{"i":76,"n":"第七十六条","txt":"因报告和制止恐怖活动，在恐怖活动犯罪案件中作证，或者从事反恐怖主义工作，本人或者其近亲属的人身安全面临危险的，经本人或者其近亲属提出申请，公安机关、有关部门应当采取下列一项或者多项保护措施："},{"i":77,"n":"第七十七条","txt":"国家鼓励、支持反恐怖主义科学研究和技术创新，开发和推广使用先进的反恐怖主义技术、设备。"},{"i":78,"n":"第七十八条","txt":"公安机关、国家安全机关、中国人民解放军、中国人民武装警察部队因履行反恐怖主义职责的紧急需要，根据国家有关规定，可以征用单位和个人的财产。任务完成后应当及时归还或者恢复原状，并依照规定支付相应费用；造成损失的，应当补偿。"},{"i":79,"n":"第七十九条","txt":"组织、策划、准备实施、实施恐怖活动，宣扬恐怖主义，煽动实施恐怖活动，非法持有宣扬恐怖主义的物品，强制他人在公共场所穿戴宣扬恐怖主义的服饰、标志，组织、领导、参加恐怖活动组织，为恐怖活动组织、恐怖活动人员、实施恐怖活动或者恐怖活动培训提供帮助的，依法追究刑事责任。"},{"i":80,"n":"第八十条","txt":"参与下列活动之一，情节轻微，尚不构成犯罪的，由公安机关处十日以上十五日以下拘留，可以并处一万元以下罚款："},{"i":81,"n":"第八十一条","txt":"利用极端主义，实施下列行为之一，情节轻微，尚不构成犯罪的，由公安机关处五日以上十五日以下拘留，可以并处一万元以下罚款："},{"i":82,"n":"第八十二条","txt":"明知他人有恐怖活动犯罪、极端主义犯罪行为，窝藏、包庇，情节轻微，尚不构成犯罪的，或者在司法机关向其调查有关情况、收集有关证据时，拒绝提供的，由公安机关处十日以上十五日以下拘留，可以并处一万元以下罚款。"},{"i":83,"n":"第八十三条","txt":"金融机构和特定非金融机构对国家反恐怖主义工作领导机构的办事机构公告的恐怖活动组织及恐怖活动人员的资金或者其他资产，未立即予以冻结的，由公安机关处二十万元以上五十万元以下罚款，并对直接负责的董事、高级管理人员和其他直接责任人员处十万元以下罚款；情节严重的，处五十万元以上罚款，并对直接负责的董事、高级管理人员和其他直接责任人员，处十万元以上五十万元以下罚款，可以并处五日以上十五日以下拘留。"},{"i":84,"n":"第八十四条","txt":"电信业务经营者、互联网服务提供者有下列情形之一的，由主管部门处二十万元以上五十万元以下罚款，并对其直接负责的主管人员和其他直接责任人员处十万元以下罚款；情节严重的，处五十万元以上罚款，并对其直接负责的主管人员和其他直接责任人员，处十万元以上五十万元以下罚款，可以由公安机关对其直接负责的主管人员和其他直接责任人员，处五日以上十五日以下拘留："},{"i":85,"n":"第八十五条","txt":"铁路、公路、水上、航空的货运和邮政、快递等物流运营单位有下列情形之一的，由主管部门处十万元以上五十万元以下罚款，并对其直接负责的主管人员和其他直接责任人员处十万元以下罚款："},{"i":86,"n":"第八十六条","txt":"电信、互联网、金融业务经营者、服务提供者未按规定对客户身份进行查验，或者对身份不明、拒绝身份查验的客户提供服务的，主管部门应当责令改正；拒不改正的，处二十万元以上五十万元以下罚款，并对其直接负责的主管人员和其他直接责任人员处十万元以下罚款；情节严重的，处五十万元以上罚款，并对其直接负责的主管人员和其他直接责任人员，处十万元以上五十万元以下罚款。"},{"i":87,"n":"第八十七条","txt":"违反本法规定，有下列情形之一的，由主管部门给予警告，并责令改正；拒不改正的，处十万元以下罚款，并对其直接负责的主管人员和其他直接责任人员处一万元以下罚款："},{"i":88,"n":"第八十八条","txt":"防范恐怖袭击重点目标的管理、营运单位违反本法规定，有下列情形之一的，由公安机关给予警告，并责令改正；拒不改正的，处十万元以下罚款，并对其直接负责的主管人员和其他直接责任人员处一万元以下罚款："},{"i":89,"n":"第八十九条","txt":"恐怖活动嫌疑人员违反公安机关责令其遵守的约束措施的，由公安机关给予警告，并责令改正；拒不改正的，处五日以上十五日以下拘留。"},{"i":90,"n":"第九十条","txt":"新闻媒体等单位编造、传播虚假恐怖事件信息，报道、传播可能引起模仿的恐怖活动的实施细节，发布恐怖事件中残忍、不人道的场景，或者未经批准，报道、传播现场应对处置的工作人员、人质身份信息和应对处置行动情况的，由公安机关处二十万元以下罚款，并对其直接负责的主管人员和其他直接责任人员，处五日以上十五日以下拘留，可以并处五万元以下罚款。"},{"i":91,"n":"第九十一条","txt":"拒不配合有关部门开展反恐怖主义安全防范、情报信息、调查、应对处置工作的，由主管部门处二千元以下罚款；造成严重后果的，处五日以上十五日以下拘留，可以并处一万元以下罚款。"},{"i":92,"n":"第九十二条","txt":"阻碍有关部门开展反恐怖主义工作的，由公安机关处五日以上十五日以下拘留，可以并处五万元以下罚款。"},{"i":93,"n":"第九十三条","txt":"单位违反本法规定，情节严重的，由主管部门责令停止从事相关业务、提供相关服务或者责令停产停业；造成严重后果的，吊销有关证照或者撤销登记。"},{"i":94,"n":"第九十四条","txt":"反恐怖主义工作领导机构、有关部门的工作人员在反恐怖主义工作中滥用职权、玩忽职守、徇私舞弊，或者有违反规定泄露国家秘密、商业秘密和个人隐私等行为，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":95,"n":"第九十五条","txt":"对依照本法规定查封、扣押、冻结、扣留、收缴的物品、资金等，经审查发现与恐怖主义无关的，应当及时解除有关措施，予以退还。"},{"i":96,"n":"第九十六条","txt":"有关单位和个人对依照本法作出的行政处罚和行政强制措施决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":97,"n":"第九十七条","txt":"本法自2016年1月1日起施行。2011年10月29日第十一届全国人民代表大会常务委员会第二十三次会议通过的《全国人民代表大会常务委员会关于加强反恐怖工作有关问题的决定》同时废止。"}],"fanshipinlangfeifa":[{"i":1,"n":"第一条","txt":"为了防止食品浪费，保障国家粮食安全，弘扬中华民族传统美德，践行社会主义核心价值观，节约资源，保护环境，促进经济社会可持续发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称食品，是指《中华人民共和国食品安全法》规定的食品，包括各种供人食用或者饮用的食物。"},{"i":3,"n":"第三条","txt":"国家厉行节约，反对浪费。"},{"i":4,"n":"第四条","txt":"各级人民政府应当加强对反食品浪费工作的领导，确定反食品浪费目标任务，建立健全反食品浪费工作机制，组织对食品浪费情况进行监测、调查、分析和评估，加强监督管理，推进反食品浪费工作。"},{"i":5,"n":"第五条","txt":"国务院发展改革部门应当加强对全国反食品浪费工作的组织协调；会同国务院有关部门每年分析评估食品浪费情况，整体部署反食品浪费工作，提出相关工作措施和意见，由各有关部门落实。"},{"i":6,"n":"第六条","txt":"机关、人民团体、国有企业事业单位应当按照国家有关规定，细化完善公务接待、会议、培训等公务活动用餐规范，加强管理，带头厉行节约，反对浪费。"},{"i":7,"n":"第七条","txt":"餐饮服务经营者应当采取下列措施，防止食品浪费："},{"i":8,"n":"第八条","txt":"设有食堂的单位应当建立健全食堂用餐管理制度，制定、实施防止食品浪费措施，加强宣传教育，增强反食品浪费意识。"},{"i":9,"n":"第九条","txt":"学校应当对用餐人员数量、结构进行监测、分析和评估，加强学校食堂餐饮服务管理；选择校外供餐单位的，应当建立健全引进和退出机制，择优选择。"},{"i":10,"n":"第十条","txt":"餐饮外卖平台应当以显著方式提示消费者适量点餐。餐饮服务经营者通过餐饮外卖平台提供服务的，应当在平台页面上向消费者提供食品分量、规格或者建议消费人数等信息。"},{"i":11,"n":"第十一条","txt":"旅游经营者应当引导旅游者文明、健康用餐。旅行社及导游应当合理安排团队用餐，提醒旅游者适量点餐、取餐。有关行业应当将旅游经营者反食品浪费工作情况纳入相关质量标准等级评定指标。"},{"i":12,"n":"第十二条","txt":"超市、商场等食品经营者应当对其经营的食品加强日常检查，对临近保质期的食品分类管理，作特别标示或者集中陈列出售。"},{"i":13,"n":"第十三条","txt":"各级人民政府及其有关部门应当采取措施，反对铺张浪费，鼓励和推动文明、节俭举办活动，形成浪费可耻、节约为荣的氛围。"},{"i":14,"n":"第十四条","txt":"个人应当树立文明、健康、理性、绿色的消费理念，外出就餐时根据个人健康状况、饮食习惯和用餐需求合理点餐、取餐。"},{"i":15,"n":"第十五条","txt":"国家完善粮食和其他食用农产品的生产、储存、运输、加工标准，推广使用新技术、新工艺、新设备，引导适度加工和综合利用，降低损耗。"},{"i":16,"n":"第十六条","txt":"制定和修改有关国家标准、行业标准和地方标准，应当将防止食品浪费作为重要考虑因素，在保证食品安全的前提下，最大程度防止浪费。"},{"i":17,"n":"第十七条","txt":"各级人民政府及其有关部门应当建立反食品浪费监督检查机制，对发现的食品浪费问题及时督促整改。"},{"i":18,"n":"第十八条","txt":"机关事务管理部门会同有关部门建立机关食堂反食品浪费工作成效评估和通报制度，将反食品浪费纳入公共机构节约能源资源考核和节约型机关创建活动内容。"},{"i":19,"n":"第十九条","txt":"食品、餐饮行业协会等应当加强行业自律，依法制定、实施反食品浪费等相关团体标准和行业自律规范，宣传、普及防止食品浪费知识，推广先进典型，引导会员自觉开展反食品浪费活动，对有浪费行为的会员采取必要的自律措施。"},{"i":20,"n":"第二十条","txt":"机关、人民团体、社会组织、企业事业单位和基层群众性自治组织应当将厉行节约、反对浪费作为群众性精神文明创建活动内容，纳入相关创建测评体系和各地市民公约、村规民约、行业规范等，加强反食品浪费宣传教育和科学普及，推动开展“光盘行动”，倡导文明、健康、科学的饮食文化，增强公众反食品浪费意识。"},{"i":21,"n":"第二十一条","txt":"教育行政部门应当指导、督促学校加强反食品浪费教育和管理。"},{"i":22,"n":"第二十二条","txt":"新闻媒体应当开展反食品浪费法律、法规以及相关标准和知识的公益宣传，报道先进典型，曝光浪费现象，引导公众树立正确饮食消费观念，对食品浪费行为进行舆论监督。有关反食品浪费的宣传报道应当真实、公正。"},{"i":23,"n":"第二十三条","txt":"县级以上地方人民政府民政、市场监督管理部门等建立捐赠需求对接机制，引导食品生产经营者等在保证食品安全的前提下向有关社会组织、福利机构、救助机构等组织或者个人捐赠食品。有关组织根据需要，及时接收、分发食品。"},{"i":24,"n":"第二十四条","txt":"产生厨余垃圾的单位、家庭和个人应当依法履行厨余垃圾源头减量义务。"},{"i":25,"n":"第二十五条","txt":"国家组织开展营养状况监测、营养知识普及，引导公民形成科学的饮食习惯，减少不健康饮食引起的疾病风险。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府应当采取措施，对防止食品浪费的科学研究、技术开发等活动予以支持。"},{"i":27,"n":"第二十七条","txt":"任何单位和个人发现食品生产经营者等有食品浪费行为的，有权向有关部门和机关举报。接到举报的部门和机关应当及时依法处理。"},{"i":28,"n":"第二十八条","txt":"违反本法规定，餐饮服务经营者未主动对消费者进行防止食品浪费提示提醒的，由县级以上地方人民政府市场监督管理部门或者县级以上地方人民政府指定的部门责令改正，给予警告。"},{"i":29,"n":"第二十九条","txt":"违反本法规定，设有食堂的单位未制定或者未实施防止食品浪费措施的，由县级以上地方人民政府指定的部门责令改正，给予警告。"},{"i":30,"n":"第三十条","txt":"违反本法规定，广播电台、电视台、网络音视频服务提供者制作、发布、传播宣扬量大多吃、暴饮暴食等浪费食品的节目或者音视频信息的，由广播电视、网信等部门按照各自职责责令改正，给予警告；拒不改正或者情节严重的，处一万元以上十万元以下罚款，并可以责令暂停相关业务、停业整顿，对直接负责的主管人员和其他直接责任人员依法追究法律责任。"},{"i":31,"n":"第三十一条","txt":"省、自治区、直辖市或者设区的市、自治州根据具体情况和实际需要，制定本地方反食品浪费的具体办法。"},{"i":32,"n":"第三十二条","txt":"本法自公布之日起施行。"}],"guojingweishengjianyifa":[{"i":1,"n":"第一条","txt":"为了加强国境卫生检疫工作，防止传染病跨境传播，保障公众生命安全和身体健康，防范和化解公共卫生风险，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国境卫生检疫及相关活动，适用本法。"},{"i":3,"n":"第三条","txt":"本法所称传染病，包括检疫传染病、监测传染病和其他需要在口岸采取相应卫生检疫措施的新发传染病、突发原因不明的传染病。"},{"i":4,"n":"第四条","txt":"国境卫生检疫工作坚持中国共产党的领导，坚持风险管理、科学施策、高效处置的原则，健全常态和应急相结合的口岸传染病防控体系。"},{"i":5,"n":"第五条","txt":"海关总署统一管理全国国境卫生检疫工作。国务院卫生健康主管部门、国务院疾病预防控制部门和其他有关部门依据各自职责做好国境卫生检疫相关工作。"},{"i":6,"n":"第六条","txt":"海关依法履行国境卫生检疫职责，有关单位和个人应当予以配合，不得拒绝或者阻碍。"},{"i":7,"n":"第七条","txt":"国家采取多种措施，加强口岸公共卫生能力建设，不断提升国境卫生检疫工作水平。"},{"i":8,"n":"第八条","txt":"国家加强与其他国家或者地区以及有关国际组织在国境卫生检疫领域的交流合作。"},{"i":9,"n":"第九条","txt":"进境出境的人员、交通运输工具，集装箱等运输设备、货物、行李、邮包等物品及外包装（以下统称货物、物品），应当依法接受检疫查验，经海关准许，方可进境出境。"},{"i":10,"n":"第十条","txt":"进境出境的人员、交通运输工具、货物、物品，应当分别在最先到达的口岸和最后离开的口岸接受检疫查验；货物、物品也可以在海关指定的其他地点接受检疫查验。"},{"i":11,"n":"第十一条","txt":"对进境出境人员，海关可以要求如实申报健康状况及相关信息，进行体温检测、医学巡查，必要时可以查阅旅行证件。"},{"i":12,"n":"第十二条","txt":"海关依据检疫医师提供的检疫查验结果，对判定为检疫传染病染疫人、疑似染疫人的，应当立即采取有效的现场防控措施，并及时通知口岸所在地县级以上地方人民政府疾病预防控制部门。接到通知的疾病预防控制部门应当及时组织将检疫传染病染疫人、疑似染疫人接送至县级以上地方人民政府指定的医疗机构或者其他场所实施隔离治疗或者医学观察。有关医疗机构和场所应当及时接收。"},{"i":13,"n":"第十三条","txt":"进境出境交通运输工具负责人应当按照规定向海关如实申报与检疫查验有关的事项。"},{"i":14,"n":"第十四条","txt":"海关可以登临交通运输工具进行检疫查验，对符合规定条件的，可以采取电讯方式进行检疫查验。"},{"i":15,"n":"第十五条","txt":"进境出境交通运输工具有下列情形之一的，应当实施卫生处理，并接受海关监督；必要时，海关可以会同有关部门对交通运输工具实施隔离："},{"i":16,"n":"第十六条","txt":"海关依据检疫医师提供的检疫查验结果，对没有传播检疫传染病风险或者已经实施有效卫生处理的交通运输工具，签发进境检疫证或者出境检疫证。"},{"i":17,"n":"第十七条","txt":"已经实施检疫查验的交通运输工具在口岸停留期间，发现检疫传染病染疫人、疑似染疫人或者有人非因意外伤害死亡且死因不明的，交通运输工具负责人应当立即向海关报告，海关应当依照本法规定采取相应的措施。"},{"i":18,"n":"第十八条","txt":"海关对过境的交通运输工具不实施检疫查验，但有证据表明该交通运输工具存在传播检疫传染病风险的除外。"},{"i":19,"n":"第十九条","txt":"进境出境货物、物品的收发货人、收寄件人、携运人（携带人）、承运人或者其代理人应当按照规定向海关如实申报与检疫查验有关的事项。"},{"i":20,"n":"第二十条","txt":"对有本法第十五条第一款规定情形的货物、物品，应当实施卫生处理，并接受海关监督；卫生处理完成前，相关货物、物品应当单独存放，未经海关准许不得移运或者提离。"},{"i":21,"n":"第二十一条","txt":"托运尸体、骸骨进境出境的，托运人或者其代理人应当按照规定向海关如实申报，经检疫查验合格后，方可进境出境。"},{"i":22,"n":"第二十二条","txt":"血液等人体组织、病原微生物、生物制品等关系公共卫生安全的货物、物品进境出境，除纳入药品、兽药、医疗器械管理的外，应当由海关事先实施卫生检疫审批，并经检疫查验合格后方可进境出境。"},{"i":23,"n":"第二十三条","txt":"海关根据检疫查验需要，可以请求有关部门和单位协助查询进境出境的人员、交通运输工具、货物、物品等的相关信息，有关部门和单位应当予以协助。海关对查询所获得的信息，不得用于卫生检疫以外的用途。"},{"i":24,"n":"第二十四条","txt":"海关总署应当根据境内外传染病监测和风险评估情况，不断优化检疫查验流程。"},{"i":25,"n":"第二十五条","txt":"海关总署会同国务院疾病预防控制部门，建立跨境传播传染病监测制度，制定口岸传染病监测规划和方案。"},{"i":26,"n":"第二十六条","txt":"各地海关应当按照口岸传染病监测规划和方案，结合对进境出境的人员、交通运输工具、货物、物品等实施检疫查验，系统持续地收集、核对和分析相关数据，对可能跨境传播的传染病的发生、流行及影响因素、发展趋势等进行评估。"},{"i":27,"n":"第二十七条","txt":"各地海关发现传染病，应当采取相应的控制措施，并及时向海关总署报告，同时向口岸所在地县级以上地方人民政府疾病预防控制部门以及移民管理机构通报。县级以上地方人民政府疾病预防控制部门发现传染病，应当及时向当地海关、移民管理机构通报。"},{"i":28,"n":"第二十八条","txt":"海关总署、国务院卫生健康主管部门、国务院疾病预防控制部门应当依据职责及时互相通报传染病相关信息。"},{"i":29,"n":"第二十九条","txt":"海关总署应当根据境外传染病监测情况，对境外传染病疫情风险进行评估，并及时发布相关风险提示信息。"},{"i":30,"n":"第三十条","txt":"海关依照本法以及有关法律、行政法规和国家规定的卫生标准，对口岸和停留在口岸的进境出境交通运输工具的卫生状况实施卫生监督，履行下列职责："},{"i":31,"n":"第三十一条","txt":"口岸运营单位应当建立健全并严格落实相关卫生制度，保证口岸卫生状况符合法律、行政法规和国家规定的卫生标准的要求。"},{"i":32,"n":"第三十二条","txt":"在口岸内从事食品生产经营、饮用水供应服务、公共场所经营的，由海关依法实施卫生许可；食品生产经营者取得卫生许可的，无需另行取得食品生产经营许可。"},{"i":33,"n":"第三十三条","txt":"海关实施卫生监督，发现口岸或者进境出境交通运输工具的卫生状况不符合法律、行政法规和国家规定的卫生标准要求的，有权要求有关单位和个人进行整改，必要时要求其实施卫生处理。"},{"i":34,"n":"第三十四条","txt":"发生重大传染病疫情，需要在口岸采取应急处置措施的，适用本章规定。"},{"i":35,"n":"第三十五条","txt":"发生重大传染病疫情，需要在口岸采取应急处置措施的，海关总署、国务院卫生健康主管部门、国务院疾病预防控制部门应当提请国务院批准启动应急响应。海关总署、国务院卫生健康主管部门、国务院疾病预防控制部门和其他有关部门应当依据各自职责，密切配合开展相关的应急处置工作。"},{"i":36,"n":"第三十六条","txt":"根据重大传染病疫情应急处置需要，经国务院决定，可以采取下列措施："},{"i":37,"n":"第三十七条","txt":"采取本章规定的应急处置措施，应当根据重大传染病疫情防控的实际情况，及时调整或者解除，并予以公布。"},{"i":38,"n":"第三十八条","txt":"海关总署会同国务院有关部门制定并组织实施口岸公共卫生能力建设规划。"},{"i":39,"n":"第三十九条","txt":"国家将国境卫生检疫工作纳入传染病防治体系。"},{"i":40,"n":"第四十条","txt":"国境卫生检疫基础设施建设应当统筹兼顾国境卫生检疫日常工作和重大传染病疫情应急处置的需要。"},{"i":41,"n":"第四十一条","txt":"国家鼓励、支持国境卫生检疫领域的科学研究、技术创新和信息化建设，推动新技术、新设备、新产品和信息化成果的应用，提高国境卫生检疫工作的技术和信息化水平。"},{"i":42,"n":"第四十二条","txt":"海关应当加强国境卫生检疫技术机构建设，为国境卫生检疫工作提供技术和服务支撑。"},{"i":43,"n":"第四十三条","txt":"国境卫生检疫工作人员应当具备与履行职责相适应的专业知识和业务技能。"},{"i":44,"n":"第四十四条","txt":"违反本法规定，进境出境人员不如实申报健康状况、相关信息或者拒绝接受检疫查验的，由海关责令改正，可以给予警告或者处一万元以下的罚款；情节严重的，处一万元以上五万元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"违反本法规定，有下列情形之一的，对交通运输工具负责人，由海关责令改正，给予警告，可以并处五万元以下的罚款；情节严重的，并处五万元以上三十万元以下的罚款："},{"i":46,"n":"第四十六条","txt":"违反本法规定，血液等人体组织、病原微生物、生物制品等关系公共卫生安全的货物、物品进境出境未经检疫审批或者未经检疫查验合格擅自进境出境的，由海关责令改正，给予警告，没收违法所得，并处一万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"违反本法规定，未经许可在口岸从事食品生产经营、饮用水供应服务、公共场所经营的，由海关依照《中华人民共和国食品安全法》等有关法律、行政法规的规定给予处罚。"},{"i":48,"n":"第四十八条","txt":"使用买卖、出借或者伪造、变造的国境卫生检疫单证的，由海关责令改正，处二万元以上十万元以下的罚款。"},{"i":49,"n":"第四十九条","txt":"海关等有关部门、地方人民政府及其工作人员在国境卫生检疫工作中玩忽职守、滥用职权、徇私舞弊的，由上级机关或者所在单位责令改正，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":50,"n":"第五十条","txt":"违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"本法中下列用语的含义："},{"i":52,"n":"第五十二条","txt":"中华人民共和国缔结或者参加的有关卫生检疫的国际条约同本法有不同规定的，适用该国际条约的规定，但中华人民共和国声明保留的条款除外。"},{"i":53,"n":"第五十三条","txt":"从口岸以外经国务院或者国务院授权的部门批准的地点进境出境的人员、交通运输工具、货物、物品的卫生检疫，我国与有关国家或者地区有双边协议的，按照协议办理；没有协议的，按照国家有关规定办理。"},{"i":54,"n":"第五十四条","txt":"经国务院批准，海关总署可以根据境内外传染病监测和风险评估情况，对有关口岸的卫生检疫措施作出便利化安排。"},{"i":55,"n":"第五十五条","txt":"国境卫生检疫及相关活动，本法未作规定的，适用《中华人民共和国传染病防治法》等有关法律、行政法规的规定。"},{"i":56,"n":"第五十六条","txt":"中国人民解放军、中国人民武装警察部队的人员、交通运输工具和装备物资进境出境的卫生检疫工作，依照本法和国务院、中央军事委员会的有关规定办理。"},{"i":57,"n":"第五十七条","txt":"本法自2025年1月1日起施行。"}],"guojiaqingbaofa":[{"i":1,"n":"第一条","txt":"为了加强和保障国家情报工作，维护国家安全和利益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家情报工作坚持总体国家安全观，为国家重大决策提供情报参考，为防范和化解危害国家安全的风险提供情报支持，维护国家政权、主权、统一和领土完整、人民福祉、经济社会可持续发展和国家其他重大利益。"},{"i":3,"n":"第三条","txt":"国家建立健全集中统一、分工协作、科学高效的国家情报体制。"},{"i":4,"n":"第四条","txt":"国家情报工作坚持公开工作与秘密工作相结合、专门工作与群众路线相结合、分工负责与协作配合相结合的原则。"},{"i":5,"n":"第五条","txt":"国家安全机关和公安机关情报机构、军队情报机构（以下统称国家情报工作机构）按照职责分工，相互配合，做好情报工作、开展情报行动。"},{"i":6,"n":"第六条","txt":"国家情报工作机构及其工作人员应当忠于国家和人民，遵守宪法和法律，忠于职守，纪律严明，清正廉洁，无私奉献，坚决维护国家安全和利益。"},{"i":7,"n":"第七条","txt":"任何组织和公民都应当依法支持、协助和配合国家情报工作，保守所知悉的国家情报工作秘密。"},{"i":8,"n":"第八条","txt":"国家情报工作应当依法进行，尊重和保障人权，维护个人和组织的合法权益。"},{"i":9,"n":"第九条","txt":"国家对在国家情报工作中作出重大贡献的个人和组织给予表彰和奖励。"},{"i":10,"n":"第十条","txt":"国家情报工作机构根据工作需要，依法使用必要的方式、手段和渠道，在境内外开展情报工作。"},{"i":11,"n":"第十一条","txt":"国家情报工作机构应当依法搜集和处理境外机构、组织、个人实施或者指使、资助他人实施的，或者境内外机构、组织、个人相勾结实施的危害中华人民共和国国家安全和利益行为的相关情报，为防范、制止和惩治上述行为提供情报依据或者参考。"},{"i":12,"n":"第十二条","txt":"国家情报工作机构可以按照国家有关规定，与有关个人和组织建立合作关系，委托开展相关工作。"},{"i":13,"n":"第十三条","txt":"国家情报工作机构可以按照国家有关规定，开展对外交流与合作。"},{"i":14,"n":"第十四条","txt":"国家情报工作机构依法开展情报工作，可以要求有关机关、组织和公民提供必要的支持、协助和配合。"},{"i":15,"n":"第十五条","txt":"国家情报工作机构根据工作需要，按照国家有关规定，经过严格的批准手续，可以采取技术侦察措施和身份保护措施。"},{"i":16,"n":"第十六条","txt":"国家情报工作机构工作人员依法执行任务时，按照国家有关规定，经过批准，出示相应证件，可以进入限制进入的有关区域、场所，可以向有关机关、组织和个人了解、询问有关情况，可以查阅或者调取有关的档案、资料、物品。"},{"i":17,"n":"第十七条","txt":"国家情报工作机构工作人员因执行紧急任务需要，经出示相应证件，可以享受通行便利。"},{"i":18,"n":"第十八条","txt":"国家情报工作机构根据工作需要，按照国家有关规定，可以提请海关、出入境边防检查等机关提供免检等便利。"},{"i":19,"n":"第十九条","txt":"国家情报工作机构及其工作人员应当严格依法办事，不得超越职权、滥用职权，不得侵犯公民和组织的合法权益，不得利用职务便利为自己或者他人谋取私利，不得泄露国家秘密、商业秘密和个人信息。"},{"i":20,"n":"第二十条","txt":"国家情报工作机构及其工作人员依法开展情报工作，受法律保护。"},{"i":21,"n":"第二十一条","txt":"国家加强国家情报工作机构建设，对其机构设置、人员、编制、经费、资产实行特殊管理，给予特殊保障。"},{"i":22,"n":"第二十二条","txt":"国家情报工作机构应当适应情报工作需要，提高开展情报工作的能力。"},{"i":23,"n":"第二十三条","txt":"国家情报工作机构工作人员因执行任务，或者与国家情报工作机构建立合作关系的人员因协助国家情报工作，其本人或者近亲属人身安全受到威胁时，国家有关部门应当采取必要措施，予以保护、营救。"},{"i":24,"n":"第二十四条","txt":"对为国家情报工作作出贡献并需要安置的人员，国家给予妥善安置。"},{"i":25,"n":"第二十五条","txt":"对因开展国家情报工作或者支持、协助和配合国家情报工作导致伤残或者牺牲、死亡的人员，按照国家有关规定给予相应的抚恤优待。"},{"i":26,"n":"第二十六条","txt":"国家情报工作机构应当建立健全严格的监督和安全审查制度，对其工作人员遵守法律和纪律等情况进行监督，并依法采取必要措施，定期或者不定期进行安全审查。"},{"i":27,"n":"第二十七条","txt":"任何个人和组织对国家情报工作机构及其工作人员超越职权、滥用职权和其他违法违纪行为，有权检举、控告。受理检举、控告的有关机关应当及时查处，并将查处结果告知检举人、控告人。"},{"i":28,"n":"第二十八条","txt":"违反本法规定，阻碍国家情报工作机构及其工作人员依法开展情报工作的，由国家情报工作机构建议相关单位给予处分或者由国家安全机关、公安机关处警告或者十五日以下拘留；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"泄露与国家情报工作有关的国家秘密的，由国家情报工作机构建议相关单位给予处分或者由国家安全机关、公安机关处警告或者十五日以下拘留；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"冒充国家情报工作机构工作人员或者其他相关人员实施招摇撞骗、诈骗、敲诈勒索等行为的，依照《中华人民共和国治安管理处罚法》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"国家情报工作机构及其工作人员有超越职权、滥用职权，侵犯公民和组织的合法权益，利用职务便利为自己或者他人谋取私利，泄露国家秘密、商业秘密和个人信息等违法违纪行为的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"本法自2017年6月28日起施行。"}],"guofangjiaotongfa":[{"i":1,"n":"第一条","txt":"为了加强国防交通建设，促进交通领域军民融合发展，保障国防活动顺利进行，制定本法。"},{"i":2,"n":"第二条","txt":"以满足国防需要为目的，在铁路、道路、水路、航空、管道以及邮政等交通领域进行的规划、建设、管理和资源使用活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家坚持军民融合发展战略，推动军地资源优化配置、合理共享，提高国防交通平时服务、急时应急、战时应战的能力，促进经济建设和国防建设协调发展。"},{"i":4,"n":"第四条","txt":"国家国防交通主管机构负责规划、组织、指导和协调全国的国防交通工作。国家国防交通主管机构的设置和工作职责，由国务院、中央军事委员会规定。"},{"i":5,"n":"第五条","txt":"公民和组织应当依法履行国防交通义务。"},{"i":6,"n":"第六条","txt":"国防交通经费按照事权划分的原则，列入政府预算。"},{"i":7,"n":"第七条","txt":"县级以上人民政府根据国防需要，可以依法征用民用运载工具、交通设施、交通物资等民用交通资源，有关组织和个人应当予以配合，履行相关义务。"},{"i":8,"n":"第八条","txt":"各级人民政府应当将国防交通教育纳入全民国防教育，通过多种形式开展国防交通宣传活动，普及国防交通知识，增强公民的国防交通观念。"},{"i":9,"n":"第九条","txt":"任何组织和个人对在国防交通工作中知悉的国家秘密和商业秘密负有保密义务。"},{"i":10,"n":"第十条","txt":"对在国防交通工作中作出突出贡献的组织和个人，按照国家有关规定给予表彰和奖励。"},{"i":11,"n":"第十一条","txt":"国家加强国防交通信息化建设，为提高国防交通保障能力提供支持。"},{"i":12,"n":"第十二条","txt":"战时和平时特殊情况下，需要在交通领域采取行业管制、为武装力量优先提供交通保障等国防动员措施的，依照《中华人民共和国国防法》、《中华人民共和国国防动员法》等有关法律执行。"},{"i":13,"n":"第十三条","txt":"战时和平时特殊情况下，国家根据需要，设立国防交通联合指挥机构，统筹全国或者局部地区的交通运输资源，统一组织指挥全国或者局部地区的交通运输以及交通设施设备的抢修、抢建与防护。相关组织和个人应当服从统一指挥。"},{"i":14,"n":"第十四条","txt":"国防交通规划包括国防交通工程设施建设规划、国防交通专业保障队伍建设规划、国防交通物资储备规划、国防交通科研规划等。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府应当将国防交通建设纳入国民经济和社会发展规划。"},{"i":16,"n":"第十六条","txt":"国防交通工程设施建设规划，由县级以上人民政府国防交通主管机构会同本级人民政府交通主管部门编制，经本级人民政府发展改革部门审核后，报本级人民政府批准。"},{"i":17,"n":"第十七条","txt":"国防交通专业保障队伍建设规划，由国家国防交通主管机构会同国务院有关部门和军队有关部门编制。"},{"i":18,"n":"第十八条","txt":"国防交通物资储备规划，由国防交通主管机构会同军地有关部门编制。"},{"i":19,"n":"第十九条","txt":"国防交通科研规划，由国家国防交通主管机构会同国务院有关部门和军队有关部门编制。"},{"i":20,"n":"第二十条","txt":"建设国防交通工程设施，应当以国防交通工程设施建设规划为依据，保障战时和平时特殊情况下国防交通畅通。"},{"i":21,"n":"第二十一条","txt":"国防交通工程设施应当按照基本建设程序、相关技术标准和规范以及国防要求进行设计、施工和竣工验收。相关人民政府国防交通主管机构组织军队有关部门参与项目的设计审定、竣工验收等工作。"},{"i":22,"n":"第二十二条","txt":"国防交通工程设施在满足国防活动需要的前提下，应当为经济社会活动提供便利。"},{"i":23,"n":"第二十三条","txt":"国防交通工程设施管理单位负责国防交通工程设施的维护和管理，保持其国防功能。"},{"i":24,"n":"第二十四条","txt":"任何组织和个人进行生产和其他活动，不得影响国防交通工程设施的正常使用，不得危及国防交通工程设施的安全。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府国防交通主管机构负责向本级人民政府交通主管部门以及相关企业事业单位了解交通工程设施建设项目的立项、设计、施工等情况；有关人民政府交通主管部门以及相关企业事业单位应当予以配合。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府国防交通主管机构应当及时向有关军事机关通报交通工程设施建设情况，并征求其贯彻国防要求的意见，汇总后提出需要贯彻国防要求的具体项目。"},{"i":27,"n":"第二十七条","txt":"对需要贯彻国防要求的交通工程设施建设项目，由有关人民政府国防交通主管机构会同本级人民政府发展改革部门、财政部门、交通主管部门和有关军事机关，与建设单位协商确定贯彻国防要求的具体事宜。"},{"i":28,"n":"第二十八条","txt":"各级人民政府对国防交通工程设施建设项目和贯彻国防要求的交通工程设施建设项目，在土地使用、城乡规划、财政、税费等方面，按照国家有关规定给予政策支持。"},{"i":29,"n":"第二十九条","txt":"国家国防交通主管机构应当根据国防需要，会同国务院有关部门和军队有关部门，确定需要贯彻国防要求的民用运载工具的类别和范围，及时向社会公布。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府国防交通主管机构应当向民用运载工具登记管理部门和建造、购置人了解需要贯彻国防要求的民用运载工具的建造、购置、使用等情况，有关公民和组织应当予以配合。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府国防交通主管机构应当及时将掌握的民用运载工具基本情况通报有关军事机关，并征求其贯彻国防要求的意见，汇总后提出需要贯彻国防要求的民用运载工具的具体项目。"},{"i":32,"n":"第三十二条","txt":"对需要贯彻国防要求的民用运载工具的具体项目，由县级以上人民政府国防交通主管机构会同本级人民政府财政部门、交通主管部门和有关军事机关，与有关公民和组织协商确定贯彻国防要求的具体事宜，并签订相关协议。"},{"i":33,"n":"第三十三条","txt":"民用运载工具因贯彻国防要求增加的费用由国家承担。有关部门应当对民用运载工具贯彻国防要求的实施予以支持和保障。"},{"i":34,"n":"第三十四条","txt":"贯彻国防要求的民用运载工具所有权人、承租人、经营人负责民用运载工具的维护和管理，保障其使用效能。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府交通主管部门会同军队有关交通运输部门按照统一计划、集中指挥、迅速准确、安全保密的原则，组织国防运输。"},{"i":36,"n":"第三十六条","txt":"国家以大中型运输企业为主要依托，组织建设战略投送支援力量，增强战略投送能力，为快速组织远距离、大规模国防运输提供有效支持。"},{"i":37,"n":"第三十七条","txt":"各级人民政府和军事机关应当加强国防运输供应、装卸等保障设施建设。"},{"i":38,"n":"第三十八条","txt":"国家驻外机构和我国从事国际运输业务的企业及其境外机构，应当为我国实施国际救援、海上护航和维护国家海外利益的军事行动的船舶、飞机、车辆和人员的补给、休整提供协助。"},{"i":39,"n":"第三十九条","txt":"公民和组织完成国防运输任务所发生的费用，由使用单位按照不低于市场价格的原则支付。具体办法由国务院财政部门、交通主管部门和中央军事委员会后勤保障部规定。"},{"i":40,"n":"第四十条","txt":"军队根据需要，可以在相关交通企业或者交通企业较为集中的地区派驻军事代表，会同有关单位共同完成国防运输和交通保障任务。"},{"i":41,"n":"第四十一条","txt":"各级国防交通主管机构组织人民政府有关部门和有关军事机关制定国防交通保障方案，明确重点交通目标、线路以及保障原则、任务、技术措施和组织措施。"},{"i":42,"n":"第四十二条","txt":"国务院有关部门和县级以上地方人民政府按照职责分工，组织有关企业事业单位实施交通工程设施抢修、抢建和运载工具抢修，保障国防活动顺利进行。有关军事机关应当给予支持和协助。"},{"i":43,"n":"第四十三条","txt":"国防交通保障方案确定的重点交通目标的管理单位和预定承担保障任务的单位，应当根据有关规定编制重点交通目标保障预案，并做好相关准备。"},{"i":44,"n":"第四十四条","txt":"重点交通目标的管理单位和预定承担保障任务的单位，在重点交通目标受到破坏威胁时，应当立即启动保障预案，做好相应准备；在重点交通目标遭受破坏时，应当按照任务分工，迅速组织实施工程加固和抢修、抢建，尽快恢复交通。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府国防交通主管机构会同本级人民政府国土资源、城乡规划等主管部门确定预定抢建重要国防交通工程设施的土地，作为国防交通控制范围，纳入土地利用总体规划和城乡规划。"},{"i":46,"n":"第四十六条","txt":"重点交通目标的对空、对海防御，由军队有关部门纳入对空、对海防御计划，统一组织实施。"},{"i":47,"n":"第四十七条","txt":"因重大军事行动和国防科研生产试验以及与国防相关的保密物资、危险品运输等特殊需要，县级以上人民政府有关部门应当按照规定的权限和程序，在相关地区的陆域、水域、空域采取必要的交通管理措施和安全防护措施。有关军事机关应当给予协助。"},{"i":48,"n":"第四十八条","txt":"县级以上人民政府交通主管部门和有关军事机关、国防交通主管机构应当根据需要，组织相关企业事业单位开展国防交通专业保障队伍的训练、演练。"},{"i":49,"n":"第四十九条","txt":"国防交通专业保障队伍执行国防交通工程设施抢修、抢建、防护和民用运载工具抢修以及人员物资抢运等任务，由县级以上人民政府国防交通主管机构会同本级人民政府交通主管部门统一调配。"},{"i":50,"n":"第五十条","txt":"各级人民政府对承担国防交通保障任务的企业和个人，按照有关规定给予政策支持。"},{"i":51,"n":"第五十一条","txt":"国家建立国防交通物资储备制度，保证战时和平时特殊情况下国防交通顺畅的需要。"},{"i":52,"n":"第五十二条","txt":"国务院交通主管部门和省、自治区、直辖市人民政府国防交通主管机构，应当按照有关规定确定国防交通储备物资储存管理单位，监督检查国防交通储备物资管理工作。"},{"i":53,"n":"第五十三条","txt":"战时和平时特殊情况下执行交通防护和抢修、抢建任务，或者组织重大军事演习，抢险救灾以及国防交通专业保障队伍训练、演练等需要的，可以调用国防交通储备物资。"},{"i":54,"n":"第五十四条","txt":"国防交通储备物资因产品技术升级、更新换代或者主要技术性能低于使用维护要求，丧失储备价值的，可以改变用途或者作报废处理。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府交通主管部门或者国防交通主管机构责令限期改正，对负有直接责任的主管人员和其他直接责任人员依法给予处分；有违法所得的，予以没收，并处违法所得一倍以上五倍以下罚款："},{"i":56,"n":"第五十六条","txt":"国防交通主管机构、有关军事机关以及交通主管部门和其他相关部门的工作人员违反本法规定，有下列情形之一的，对负有直接责任的主管人员和其他直接责任人员依法给予处分："},{"i":57,"n":"第五十七条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"本法所称国防交通工程设施，是指国家为国防目的修建的交通基础设施以及国防交通专用的指挥、检修、装卸、仓储等工程设施。"},{"i":59,"n":"第五十九条","txt":"与国防交通密切相关的信息设施、设备和专业保障队伍的建设、管理、使用活动，适用本法。"},{"i":60,"n":"第六十条","txt":"本法自2017年1月1日起施行。"}],"guofangdongyuanfa-2":[{"i":1,"n":"第一条","txt":"为了加强国防建设，完善国防动员制度，保障国防动员工作的顺利进行，维护国家的主权、统一、领土完整、安全和发展利益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国防动员的准备、实施以及相关活动，适用本法。"},{"i":3,"n":"第三条","txt":"国防动员工作坚持中国共产党的领导，贯彻习近平强军思想，坚持总体国家安全观，贯彻新时代军事战略方针，坚持平战结合、军地协同、寓军于民的方针，遵循统一领导、全民参与、分工协作、分级负责、长期准备、重点建设、统筹兼顾、高效持续的原则。"},{"i":4,"n":"第四条","txt":"国家加强国防动员建设，统筹发展和安全，完善与国防安全需要相适应、与经济社会发展相协调、与突发事件应急机制相衔接的国防动员体系，提升国防动员信息化、智能化水平，增强国防动员潜力和能力，推进国防动员现代化，巩固提高一体化国家战略体系和能力。"},{"i":5,"n":"第五条","txt":"国家实行国防动员工作目标责任制，对中央国家机关有关部门、地方各级人民政府、有关军事机关加强督促、检查。"},{"i":6,"n":"第六条","txt":"国家建立国防动员能力检验评估机制，构建国防动员能力检验评估体系。"},{"i":7,"n":"第七条","txt":"国家建立适应国防动员需要的数据服务保障制度，依法收集、使用与国防动员密切相关的数据，并保障数据安全。"},{"i":8,"n":"第八条","txt":"国家推进先进技术在国防动员中的应用，发展新兴领域国防动员力量。"},{"i":9,"n":"第九条","txt":"国家保障国防动员所需经费。国防动员经费按照中央与地方财政事权和支出责任划分原则，分别列入中央和地方预算。"},{"i":10,"n":"第十条","txt":"组织和公民在和平时期应当依法完成国防动员准备工作；国家决定实施国防动员后，应当完成规定的国防动员任务。"},{"i":11,"n":"第十一条","txt":"任何组织和个人应当对在国防动员工作中知悉的国家秘密、工作秘密、商业秘密和个人隐私、个人信息依法予以保密，不得泄露或者向他人非法提供。"},{"i":12,"n":"第十二条","txt":"国家依法保障参加国防动员活动的组织和个人的合法权益。对在国防动员工作中做出突出贡献的组织和个人，按照有关规定给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"国家的主权、统一、领土完整、安全和发展利益遭受威胁时，全国人民代表大会常务委员会依照宪法和有关法律的规定，决定全国总动员或者局部动员。中华人民共和国主席根据全国人民代表大会常务委员会的决定，发布动员令。"},{"i":14,"n":"第十四条","txt":"国务院、中央军事委员会向全国人民代表大会常务委员会提出实施全国总动员或者局部动员的议案，根据全国人民代表大会常务委员会的决定和中华人民共和国主席发布的动员令，组织国防动员的实施。"},{"i":15,"n":"第十五条","txt":"地方各级人民政府应当贯彻和执行国防动员工作的方针、政策和法律、法规；国家决定实施国防动员后，应当根据上级下达的国防动员任务，组织本行政区域国防动员的实施。"},{"i":16,"n":"第十六条","txt":"县级以上人民政府有关部门、有关军事机关在各自的职责范围内，负责有关的国防动员工作。"},{"i":17,"n":"第十七条","txt":"在党中央集中统一领导下，国家国防动员委员会履行组织、指导、协调全国国防动员工作职能。国家国防动员委员会按照规定的权限和程序议定的事项，由国家国防动员委员会的成员单位和其他有关部门按照各自职责分工组织实施。"},{"i":18,"n":"第十八条","txt":"国防动员委员会的办事机构承担本级国防动员委员会的日常工作，依法履行有关的国防动员职责。"},{"i":19,"n":"第十九条","txt":"国家的主权、统一、领土完整、安全和发展利益遭受的威胁消除后，应当按照决定实施国防动员的权限和程序解除国防动员的实施措施。"},{"i":20,"n":"第二十条","txt":"国家实行国防动员规划制度和国防动员实施预案制度，开展国防动员潜力统计调查。"},{"i":21,"n":"第二十一条","txt":"国家国防动员委员会负责组织拟订国家国防动员规划。国家国防动员委员会成员单位根据职责分工和部署拟订本行业、本领域国防动员相关规划。"},{"i":22,"n":"第二十二条","txt":"国家建立国防动员实施预案体系。"},{"i":23,"n":"第二十三条","txt":"国防动员规划和国防动员实施预案，根据国防动员工作的方针和原则、国防动员潜力状况和军事需求编制。军事需求由有关军事机关按照规定的权限和程序提出。"},{"i":24,"n":"第二十四条","txt":"国防动员规划和国防动员实施预案的审批，按照国家有关规定执行。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府应当将国防动员准备纳入国民经济和社会发展规划。有关军事机关应当将国防动员实施预案纳入战备方案。"},{"i":26,"n":"第二十六条","txt":"国家将国防动员潜力统计调查纳入政府统计调查制度体系，制定国防动员潜力统计调查项目和制度，建立完善国防动员潜力统计资料的动态更新机制，加强国防动员潜力统计调查结果的分析运用。"},{"i":27,"n":"第二十七条","txt":"国家推动经济建设和国防建设协调发展，依托经济社会发展增强国防实力。根据国防动员的需要，与国防密切相关的建设项目和重要产品应当贯彻国防要求，具备国防功能。"},{"i":28,"n":"第二十八条","txt":"与国防密切相关的建设项目和重要产品目录，由国务院发展改革部门、中央军事委员会机关有关部门会同国务院其他有关部门拟定，报国务院、中央军事委员会批准。"},{"i":29,"n":"第二十九条","txt":"列入目录的建设项目和重要产品，应当依照法律、行政法规以及贯彻国防要求的标准和技术规范进行设计、生产、施工、监理、验收和维护，保证建设项目和重要产品的质量效益。"},{"i":30,"n":"第三十条","txt":"企业事业单位、社会组织、个人投资或者参与投资列入目录的建设项目建设或者重要产品研究、开发、制造的，依照法律、行政法规和国家有关规定享受政策支持。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府应当对列入目录的建设项目和重要产品贯彻国防要求工作给予指导和政策支持，有关部门应当按照职责做好有关的管理工作。"},{"i":32,"n":"第三十二条","txt":"国家实行后备兵员储备制度。"},{"i":33,"n":"第三十三条","txt":"后备兵员按照专业对口、便于动员的原则，采取预编到现役部队、编入预备役部队、编入民兵组织或者进行兵役登记等形式储备。"},{"i":34,"n":"第三十四条","txt":"各级人民政府、各级军事机关按照职责分工组织实施后备兵员的储备工作。"},{"i":35,"n":"第三十五条","txt":"国家决定实施国防动员后，县级人民政府兵役机关或者部队应当根据上级的命令，迅速向被征召的后备兵员下达征召通知。"},{"i":36,"n":"第三十六条","txt":"县级以上人民政府有关部门、乡镇人民政府、街道办事处和被征召的后备兵员所在单位，应当协助兵役机关和部队做好征召工作。"},{"i":37,"n":"第三十七条","txt":"国家决定实施国防动员后，预定征召的后备兵员，未经其登记地的县级人民政府兵役机关批准，不得离开登记地；已经离开的，应当立即返回或者原地待命。"},{"i":38,"n":"第三十八条","txt":"后备兵员有《中华人民共和国预备役人员法》第三十八条规定情形的，经其登记地的县级人民政府兵役机关核实，并报上一级兵役机关批准，可以暂缓征召。"},{"i":39,"n":"第三十九条","txt":"预备役人员的征召依照《中华人民共和国预备役人员法》有关规定执行。"},{"i":40,"n":"第四十条","txt":"国家增强战略物资储备能力，构建政府主导、社会共建、多元互补的战略物资储备体系，实行适应国防动员需要的战略物资储备和调用制度。"},{"i":41,"n":"第四十一条","txt":"战略物资储备由国务院有关部门、县级以上地方人民政府按照国家有关规定组织实施。"},{"i":42,"n":"第四十二条","txt":"战略物资按照国家有关规定调用。国家决定实施国防动员后，战略物资的调用由国务院和中央军事委员会或者其授权的机关批准。"},{"i":43,"n":"第四十三条","txt":"各级人民政府、有关军事机关应当鼓励和支持有关企业事业单位、社会组织和个人承担战略物资仓储、运输、配送等任务。国家决定实施国防动员后，承担任务的企业事业单位、社会组织和个人应当优先满足国防动员需要，按照要求完成任务。各级人民政府、有关军事机关依法提供便利条件。"},{"i":44,"n":"第四十四条","txt":"国防动员所需的其他物资的储备和调用，依照有关法律、行政法规的规定执行。"},{"i":45,"n":"第四十五条","txt":"国家建立军品科研、生产和维修保障动员体系，根据战时军事采购和装备保障的需要，储备军品科研、生产和维修保障能力。"},{"i":46,"n":"第四十六条","txt":"国务院有关部门、中央军事委员会机关有关部门组织开展军品产业链、供应链安全评估工作，并根据评估结果采取措施，提升军品产业链、供应链韧性和安全水平。"},{"i":47,"n":"第四十七条","txt":"承担军品科研、转产、扩大生产和维修保障任务的单位，应当根据所承担的国防动员任务，储备所需的设备、材料、配套产品、技术、数据、软件等，建立所需的专业技术队伍，制定和完善预案与措施，定期组织开展演练。"},{"i":48,"n":"第四十八条","txt":"国家注重发挥市场机制作用，鼓励和支持组织和个人参与军品科研、生产和维修保障能力储备。"},{"i":49,"n":"第四十九条","txt":"国家决定实施国防动员后，承担军品科研、转产、扩大生产和维修保障任务的单位，应当按照军事采购合同和转产、扩大生产的要求，组织军品科研、生产，保证军品质量，按时交付，协助军队完成维修保障任务。为军品科研、转产、扩大生产和维修保障任务提供能源、设备、材料、配套产品、技术、数据、软件等的单位，应当优先满足军品科研、转产、扩大生产和维修保障的需要。"},{"i":50,"n":"第五十条","txt":"国家实行战争灾害的预防与救助制度，保护人民生命和财产安全，保障国防动员潜力和持续动员能力。"},{"i":51,"n":"第五十一条","txt":"国家建立军事、经济、社会目标和首脑机关等重要目标分级防护制度。重要目标的分级防护标准由国务院、中央军事委员会规定。"},{"i":52,"n":"第五十二条","txt":"承担重要目标防护任务的单位，应当制定防护计划和抢险抢修预案，组织防护演练，落实防护措施，提高综合防护效能。"},{"i":53,"n":"第五十三条","txt":"县级以上人民政府、有关军事机关应当加强国防动员和应急管理规划、预案、政策及任务的协调对接，做到指挥调度、专业力量、情报信息、物资器材等方面的统筹运用，提高战争灾害预防和救助能力。"},{"i":54,"n":"第五十四条","txt":"国家建立平战结合的医疗卫生救护体系。国家决定实施国防动员后，动员医疗卫生机构和人员，调用药品、器材和设备设施等，保障战时医疗救护、卫生防疫和卫生防护。"},{"i":55,"n":"第五十五条","txt":"国家决定实施国防动员后，人员、物资的疏散和隐蔽，在本行政区域进行的，由本级人民政府决定并组织实施；跨行政区域进行的，由相关行政区域共同的上一级人民政府决定并组织实施。"},{"i":56,"n":"第五十六条","txt":"战争灾害发生时，当地人民政府应当迅速启动应急救助机制，组织力量抢救伤员、安置灾民、保护财产，尽快消除战争灾害后果，恢复正常生产生活秩序。"},{"i":57,"n":"第五十七条","txt":"国家决定实施国防动员后，县级以上人民政府根据国防动员实施的需要，可以动员符合本法规定条件的组织和公民担负国防勤务。"},{"i":58,"n":"第五十八条","txt":"十八周岁至六十周岁的男性公民和十八周岁至五十五周岁的女性公民，应当依法担负国防勤务；但有下列情形之一的，免予担负国防勤务："},{"i":59,"n":"第五十九条","txt":"被确定担负国防勤务的人员，应当服从指挥、履行职责、遵守纪律、保守秘密。担负国防勤务的人员所在单位应当给予支持和协助。"},{"i":60,"n":"第六十条","txt":"交通运输、邮政、电信、网络安全、医药卫生、食品和粮食供应、工程建筑、能源化工、大型水利设施、民用核设施、新闻媒体、国防科研生产和市政设施保障等单位，应当依法担负国防勤务。"},{"i":61,"n":"第六十一条","txt":"组织和公民担负国防勤务，由县级以上人民政府负责组织。"},{"i":62,"n":"第六十二条","txt":"担负国防勤务的人员在执行勤务期间，继续享有原工作单位的工资、津贴和其他福利待遇；没有工作单位的，由当地县级人民政府参照民兵执行战备勤务的补贴标准给予补贴；因执行国防勤务伤亡的，由当地县级人民政府按照《军人抚恤优待条例》等有关规定给予抚恤优待。"},{"i":63,"n":"第六十三条","txt":"国家决定实施国防动员后，储备物资无法及时满足动员需要的，县级以上人民政府可以依法对民用资源进行征收、征用。"},{"i":64,"n":"第六十四条","txt":"任何组织和个人都有接受依法征收、征用民用资源的义务。"},{"i":65,"n":"第六十五条","txt":"下列民用资源免予征收、征用："},{"i":66,"n":"第六十六条","txt":"被征收、征用的民用资源根据军事要求需要进行改造的，由县级以上人民政府会同有关军事机关组织实施。"},{"i":67,"n":"第六十七条","txt":"被征用的民用资源使用完毕，县级以上人民政府应当及时组织返还；经过改造的，应当恢复原使用功能后返还；毁损、灭失的，以及因征收、征用造成直接经济损失的，给予公平、合理的补偿。"},{"i":68,"n":"第六十八条","txt":"中国人民解放军现役部队和预备役部队、中国人民武装警察部队、民兵组织进行军事演习、训练等，需要征用民用资源或者采取临时性管制措施的，按照国务院、中央军事委员会的有关规定执行。"},{"i":69,"n":"第六十九条","txt":"国家普及和加强国防动员宣传教育，增强公民的国防动员观念和依法履行国防动员义务的意识。中央国家机关有关部门、地方有关部门应当依照法律、行政法规和国家有关规定开展国防动员宣传教育工作。有关军事机关协同开展相关工作。"},{"i":70,"n":"第七十条","txt":"机关、团体、企业事业单位和基层群众性自治组织，应当组织所属人员学习和掌握必要的国防知识与技能。"},{"i":71,"n":"第七十一条","txt":"全民国防教育主管部门应当运用各种宣传渠道平台和方式手段进行爱国主义、革命英雄主义宣传教育，激发全体公民的爱国热情。"},{"i":72,"n":"第七十二条","txt":"国家决定实施国防动员后，中央国家机关有关部门、地方有关部门、有关军事机关应当按照职责开展权威信息发布和解读，依法加强各类传播平台管理，规范信息发布和传播秩序，对编造、传播虚假国防动员信息，干扰、破坏国防动员工作秩序的组织和个人，依法予以处理。"},{"i":73,"n":"第七十三条","txt":"国家决定实施国防动员后，根据需要，可以依法在实施国防动员的区域采取下列特别措施："},{"i":74,"n":"第七十四条","txt":"在全国或者部分省、自治区、直辖市实行特别措施，由国务院、中央军事委员会决定并组织实施；在省、自治区、直辖市范围内的部分地区实行特别措施，由国务院、中央军事委员会决定，由特别措施实施区域所在省、自治区、直辖市人民政府和同级军事机关组织实施。"},{"i":75,"n":"第七十五条","txt":"组织实施特别措施的机关应当在规定的权限、区域和时限内实施特别措施。特别措施实施区域内的组织和个人，应当服从组织实施特别措施的机关的管理。"},{"i":76,"n":"第七十六条","txt":"采取国防动员特别措施应当遵循必要、合理原则，并根据情况变化及时调整。"},{"i":77,"n":"第七十七条","txt":"因国家发布动员令，致使诉讼、监察调查、行政复议、仲裁、国家赔偿等活动不能正常进行的，适用有关时效中止和程序中止的规定，法律另有规定的除外。"},{"i":78,"n":"第七十八条","txt":"公民有下列情形之一，由县级人民政府责令限期改正；逾期不改的，强制其履行义务："},{"i":79,"n":"第七十九条","txt":"企业事业单位、社会组织有下列情形之一，由有关人民政府责令限期改正；逾期不改的，强制其履行义务，并可以处以罚款："},{"i":80,"n":"第八十条","txt":"在国防动员工作中有下列情形之一，对负有责任的领导人员和直接责任人员，依法给予处分："},{"i":81,"n":"第八十一条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":82,"n":"第八十二条","txt":"本法自2026年10月1日起施行。"}],"guofangdongyuanfa":[{"i":1,"n":"第一条","txt":"为了加强国防建设，完善国防动员制度，保障国防动员工作的顺利进行，维护国家的主权、统一、领土完整和安全，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国防动员的准备、实施以及相关活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家加强国防动员建设，建立健全与国防安全需要相适应、与经济社会发展相协调、与突发事件应急机制相衔接的国防动员体系，增强国防动员能力。"},{"i":4,"n":"第四条","txt":"国防动员坚持平战结合、军民结合、寓军于民的方针，遵循统一领导、全民参与、长期准备、重点建设、统筹兼顾、有序高效的原则。"},{"i":5,"n":"第五条","txt":"公民和组织在和平时期应当依法完成国防动员准备工作；国家决定实施国防动员后，应当完成规定的国防动员任务。"},{"i":6,"n":"第六条","txt":"国家保障国防动员所需经费。国防动员经费按照事权划分的原则，分别列入中央和地方财政预算。"},{"i":7,"n":"第七条","txt":"国家对在国防动员工作中作出突出贡献的公民和组织，给予表彰和奖励。"},{"i":8,"n":"第八条","txt":"国家的主权、统一、领土完整和安全遭受威胁时，全国人民代表大会常务委员会依照宪法和有关法律的规定，决定全国总动员或者局部动员。国家主席根据全国人民代表大会常务委员会的决定，发布动员令。"},{"i":9,"n":"第九条","txt":"国务院、中央军事委员会共同领导全国的国防动员工作，制定国防动员工作的方针、政策和法规，向全国人民代表大会常务委员会提出实施全国总动员或者局部动员的议案，根据全国人民代表大会常务委员会的决定和国家主席发布的动员令，组织国防动员的实施。"},{"i":10,"n":"第十条","txt":"地方人民政府应当贯彻和执行国防动员工作的方针、政策和法律、法规；国家决定实施国防动员后，应当根据上级下达的国防动员任务，组织本行政区域国防动员的实施。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府有关部门和军队有关部门在各自的职责范围内，负责有关的国防动员工作。"},{"i":12,"n":"第十二条","txt":"国家国防动员委员会在国务院、中央军事委员会的领导下负责组织、指导、协调全国的国防动员工作；按照规定的权限和程序议定的事项，由国务院和中央军事委员会的有关部门按照各自职责分工组织实施。军区国防动员委员会、县级以上地方各级国防动员委员会负责组织、指导、协调本区域的国防动员工作。"},{"i":13,"n":"第十三条","txt":"国防动员委员会的办事机构承担本级国防动员委员会的日常工作，依法履行有关的国防动员职责。"},{"i":14,"n":"第十四条","txt":"国家的主权、统一、领土完整和安全遭受的威胁消除后，应当按照决定实施国防动员的权限和程序解除国防动员的实施措施。"},{"i":15,"n":"第十五条","txt":"国家实行国防动员计划、国防动员实施预案和国防动员潜力统计调查制度。"},{"i":16,"n":"第十六条","txt":"国防动员计划和国防动员实施预案，根据国防动员的方针和原则、国防动员潜力状况和军事需求编制。军事需求由军队有关部门按照规定的权限和程序提出。"},{"i":17,"n":"第十七条","txt":"各级国防动员计划和国防动员实施预案的编制和审批，按照国家有关规定执行。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府应当将国防动员的相关内容纳入国民经济和社会发展计划。军队有关部门应当将国防动员实施预案纳入战备计划。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府统计机构和有关部门应当根据国防动员的需要，准确及时地向本级国防动员委员会的办事机构提供有关统计资料。提供的统计资料不能满足需要时，国防动员委员会办事机构可以依据《中华人民共和国统计法》和国家有关规定组织开展国防动员潜力专项统计调查。"},{"i":20,"n":"第二十条","txt":"国家建立国防动员计划和国防动员实施预案执行情况的评估检查制度。"},{"i":21,"n":"第二十一条","txt":"根据国防动员的需要，与国防密切相关的建设项目和重要产品应当贯彻国防要求，具备国防功能。"},{"i":22,"n":"第二十二条","txt":"与国防密切相关的建设项目和重要产品目录，由国务院经济发展综合管理部门会同国务院其他有关部门以及军队有关部门拟定，报国务院、中央军事委员会批准。"},{"i":23,"n":"第二十三条","txt":"列入目录的建设项目和重要产品，应当依照有关法律、行政法规和贯彻国防要求的技术规范和标准进行设计、生产、施工、监理和验收，保证建设项目和重要产品的质量。"},{"i":24,"n":"第二十四条","txt":"企业事业单位投资或者参与投资列入目录的建设项目建设或者重要产品研究、开发、制造的，依照有关法律、行政法规和国家有关规定，享受补贴或者其他政策优惠。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府应当对列入目录的建设项目和重要产品贯彻国防要求工作给予指导和政策扶持，有关部门应当按照职责做好有关的管理工作。"},{"i":26,"n":"第二十六条","txt":"国家实行预备役人员储备制度。"},{"i":27,"n":"第二十七条","txt":"预备役人员按照专业对口、便于动员的原则，采取预编到现役部队、编入预备役部队、编入民兵组织或者其他形式进行储备。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府兵役机关负责组织实施本行政区域预备役人员的储备工作。县级以上地方人民政府有关部门、预备役人员所在乡（镇）人民政府、街道办事处或者企业事业单位，应当协助兵役机关做好预备役人员储备的有关工作。"},{"i":29,"n":"第二十九条","txt":"预编到现役部队和编入预备役部队的预备役人员、预定征召的其他预备役人员，离开预备役登记地一个月以上的，应当向其预备役登记的兵役机关报告。"},{"i":30,"n":"第三十条","txt":"国家决定实施国防动员后，县级人民政府兵役机关应当根据上级的命令，迅速向被征召的预备役人员下达征召通知。"},{"i":31,"n":"第三十一条","txt":"被征召的预备役人员所在单位应当协助兵役机关做好预备役人员的征召工作。"},{"i":32,"n":"第三十二条","txt":"国家决定实施国防动员后，预定征召的预备役人员，未经其预备役登记地的县级人民政府兵役机关批准，不得离开预备役登记地；已经离开预备役登记地的，接到兵役机关通知后，应当立即返回或者到指定地点报到。"},{"i":33,"n":"第三十三条","txt":"国家实行适应国防动员需要的战略物资储备和调用制度。"},{"i":34,"n":"第三十四条","txt":"承担战略物资储备任务的单位，应当按照国家有关规定和标准对储备物资进行保管和维护，定期调整更换，保证储备物资的使用效能和安全。"},{"i":35,"n":"第三十五条","txt":"战略物资按照国家有关规定调用。国家决定实施国防动员后，战略物资的调用由国务院和中央军事委员会批准。"},{"i":36,"n":"第三十六条","txt":"国防动员所需的其他物资的储备和调用，依照有关法律、行政法规的规定执行。"},{"i":37,"n":"第三十七条","txt":"国家建立军品科研、生产和维修保障动员体系，根据战时军队订货和装备保障的需要，储备军品科研、生产和维修保障能力。"},{"i":38,"n":"第三十八条","txt":"军品科研、生产和维修保障能力储备的种类、布局和规模，由国务院有关主管部门会同军队有关部门提出方案，报国务院、中央军事委员会批准后组织实施。"},{"i":39,"n":"第三十九条","txt":"承担转产、扩大生产军品和维修保障任务的单位，应当根据所担负的国防动员任务，储备所需的设备、材料、配套产品、技术，建立所需的专业技术队伍，制定和完善预案与措施。"},{"i":40,"n":"第四十条","txt":"各级人民政府应当支持和帮助承担转产、扩大生产军品任务的单位开发和应用先进的军民两用技术，推广军民通用的技术标准，提高转产、扩大生产军品的综合保障能力。"},{"i":41,"n":"第四十一条","txt":"国家决定实施国防动员后，承担转产、扩大生产军品任务的单位，应当按照国家军事订货合同和转产、扩大生产的要求，组织军品科研、生产，保证军品质量，按时交付订货，协助军队完成维修保障任务。为转产、扩大生产军品提供能源、材料、设备和配套产品的单位，应当优先满足转产、扩大生产军品的需要。"},{"i":42,"n":"第四十二条","txt":"国家实行战争灾害的预防与救助制度，保护人民生命和财产安全，保障国防动员潜力和持续动员能力。"},{"i":43,"n":"第四十三条","txt":"国家建立军事、经济、社会目标和首脑机关分级防护制度。分级防护标准由国务院、中央军事委员会规定。"},{"i":44,"n":"第四十四条","txt":"承担军事、经济、社会目标和首脑机关防护任务的单位，应当制定防护计划和抢险抢修预案，组织防护演练，落实防护措施，提高综合防护效能。"},{"i":45,"n":"第四十五条","txt":"国家建立平战结合的医疗卫生救护体系。国家决定实施国防动员后，动员医疗卫生人员、调用药品器材和设备设施，保障战时医疗救护和卫生防疫。"},{"i":46,"n":"第四十六条","txt":"国家决定实施国防动员后，人员、物资的疏散和隐蔽，在本行政区域进行的，由本级人民政府决定并组织实施；跨行政区域进行的，由相关行政区域共同的上一级人民政府决定并组织实施。"},{"i":47,"n":"第四十七条","txt":"战争灾害发生时，当地人民政府应当迅速启动应急救助机制，组织力量抢救伤员、安置灾民、保护财产，尽快消除战争灾害后果，恢复正常生产生活秩序。"},{"i":48,"n":"第四十八条","txt":"国家决定实施国防动员后，县级以上人民政府根据国防动员实施的需要，可以动员符合本法规定条件的公民和组织担负国防勤务。"},{"i":49,"n":"第四十九条","txt":"十八周岁至六十周岁的男性公民和十八周岁至五十五周岁的女性公民，应当担负国防勤务；但有下列情形之一的，免予担负国防勤务："},{"i":50,"n":"第五十条","txt":"被确定担负国防勤务的人员，应当服从指挥、履行职责、遵守纪律、保守秘密。担负国防勤务的人员所在单位应当给予支持和协助。"},{"i":51,"n":"第五十一条","txt":"交通运输、邮政、电信、医药卫生、食品和粮食供应、工程建筑、能源化工、大型水利设施、民用核设施、新闻媒体、国防科研生产和市政设施保障等单位，应当依法担负国防勤务。"},{"i":52,"n":"第五十二条","txt":"公民和组织担负国防勤务，由县级以上人民政府负责组织。"},{"i":53,"n":"第五十三条","txt":"担负国防勤务的人员在执行勤务期间，继续享有原工作单位的工资、津贴和其他福利待遇；没有工作单位的，由当地县级人民政府参照民兵执行战备勤务的补贴标准给予补贴；因执行国防勤务伤亡的，由当地县级人民政府依照《军人抚恤优待条例》等有关规定给予抚恤优待。"},{"i":54,"n":"第五十四条","txt":"国家决定实施国防动员后，储备物资无法及时满足动员需要的，县级以上人民政府可以依法对民用资源进行征用。"},{"i":55,"n":"第五十五条","txt":"任何组织和个人都有接受依法征用民用资源的义务。"},{"i":56,"n":"第五十六条","txt":"下列民用资源免予征用："},{"i":57,"n":"第五十七条","txt":"被征用的民用资源根据军事要求需要进行改造的，由县级以上地方人民政府会同有关军事机关组织实施。"},{"i":58,"n":"第五十八条","txt":"被征用的民用资源使用完毕，县级以上地方人民政府应当及时组织返还；经过改造的，应当恢复原使用功能后返还；不能修复或者灭失的，以及因征用造成直接经济损失的，按照国家有关规定给予补偿。"},{"i":59,"n":"第五十九条","txt":"中国人民解放军现役部队和预备役部队、中国人民武装警察部队、民兵组织进行军事演习、训练，需要征用民用资源或者采取临时性管制措施的，按照国务院、中央军事委员会的有关规定执行。"},{"i":60,"n":"第六十条","txt":"各级人民政府应当组织开展国防动员的宣传教育，增强公民的国防观念和依法履行国防义务的意识。有关军事机关应当协助做好国防动员的宣传教育工作。"},{"i":61,"n":"第六十一条","txt":"国家机关、社会团体、企业事业单位和基层群众性自治组织，应当组织所属人员学习和掌握必要的国防知识与技能。"},{"i":62,"n":"第六十二条","txt":"各级人民政府应当运用各种宣传媒体和宣传手段，对公民进行爱国主义、革命英雄主义宣传教育，激发公民的爱国热情，鼓励公民踊跃参战支前，采取多种形式开展拥军优属和慰问活动，按照国家有关规定做好抚恤优待工作。"},{"i":63,"n":"第六十三条","txt":"国家决定实施国防动员后，根据需要，可以依法在实施国防动员的区域采取下列特别措施："},{"i":64,"n":"第六十四条","txt":"在全国或者部分省、自治区、直辖市实行特别措施，由国务院、中央军事委员会决定并组织实施；在省、自治区、直辖市范围内的部分地区实行特别措施，由国务院、中央军事委员会决定，由特别措施实施区域所在省、自治区、直辖市人民政府和同级军事机关组织实施。"},{"i":65,"n":"第六十五条","txt":"组织实施特别措施的机关应当在规定的权限、区域和时限内实施特别措施。特别措施实施区域内的公民和组织，应当服从组织实施特别措施的机关的管理。"},{"i":66,"n":"第六十六条","txt":"采取特别措施不再必要时，应当及时终止。"},{"i":67,"n":"第六十七条","txt":"因国家发布动员令，诉讼、行政复议、仲裁活动不能正常进行的，适用有关时效中止和程序中止的规定，但法律另有规定的除外。"},{"i":68,"n":"第六十八条","txt":"公民有下列行为之一的，由县级人民政府责令限期改正；逾期不改的，强制其履行义务："},{"i":69,"n":"第六十九条","txt":"企业事业单位有下列行为之一的，由有关人民政府责令限期改正；逾期不改的，强制其履行义务，并可以处以罚款："},{"i":70,"n":"第七十条","txt":"有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分："},{"i":71,"n":"第七十一条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"本法自2010年7月1日起施行。"}],"guofangjiaoyufa":[{"i":1,"n":"第一条","txt":"为了普及和加强国防教育，发扬爱国主义精神，促进国防建设和社会主义精神文明建设，根据宪法和《中华人民共和国国防法》、《中华人民共和国教育法》，制定本法。"},{"i":2,"n":"第二条","txt":"国家在全体公民中开展以爱国主义为核心，以履行国防义务为目的，与国防和军队建设有关的理论、知识、技能以及科技、法律、心理等方面的国防教育。"},{"i":3,"n":"第三条","txt":"国防教育坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚持总体国家安全观，培育和践行社会主义核心价值观，铸牢中华民族共同体意识，使全体公民增强国防观念、强化忧患意识、掌握国防知识、提高国防技能，依法履行国防义务。"},{"i":4,"n":"第四条","txt":"坚持中国共产党对国防教育工作的领导，建立集中统一、分工负责、军地协同的国防教育领导体制。"},{"i":5,"n":"第五条","txt":"中央全民国防教育主管部门负责全国国防教育工作的指导、监督和统筹协调。中央国家机关各部门在各自的职责范围内负责国防教育工作。中央军事委员会机关有关部门按照职责分工，协同中央全民国防教育主管部门开展国防教育。"},{"i":6,"n":"第六条","txt":"国防教育贯彻全民参与、长期坚持、讲求实效的方针，实行经常教育与集中教育相结合、普及教育与重点教育相结合、理论教育与行为教育相结合的原则，针对不同对象确定相应的教育内容分类组织实施。"},{"i":7,"n":"第七条","txt":"中华人民共和国公民都有接受国防教育的权利和义务。"},{"i":8,"n":"第八条","txt":"国防动员、兵役、退役军人事务、国防科研生产、边防海防、人民防空、国防交通等工作的主管部门，依照本法和有关法律、法规的规定，开展国防教育。"},{"i":9,"n":"第九条","txt":"中国人民解放军、中国人民武装警察部队按照中央军事委员会的有关规定开展国防教育。"},{"i":10,"n":"第十条","txt":"国家支持、鼓励社会组织和个人开展有益于国防教育的活动。"},{"i":11,"n":"第十一条","txt":"对在国防教育工作中做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。"},{"i":12,"n":"第十二条","txt":"每年九月的第三个星期六为全民国防教育日。"},{"i":13,"n":"第十三条","txt":"学校国防教育是全民国防教育的基础，是实施素质教育的重要内容。"},{"i":14,"n":"第十四条","txt":"小学和初级中学应当将国防教育的内容纳入有关课程，将课堂教学与课外活动相结合，使小学生具备一定的国防意识、初中学生掌握初步的国防知识和国防技能。"},{"i":15,"n":"第十五条","txt":"高中阶段学校应当在有关课程中安排专门的国防教育内容，将课堂教学与军事训练相结合，使学生掌握基本的国防理论、知识和技能，具备基本的国防观念。"},{"i":16,"n":"第十六条","txt":"学校国防教育应当与兵役宣传教育相结合，增强学生依法服兵役的意识，营造服兵役光荣的良好氛围。"},{"i":17,"n":"第十七条","txt":"普通高等学校、高中阶段学校应当按照规定组织学生军事训练。"},{"i":18,"n":"第十八条","txt":"中央全民国防教育主管部门、国务院教育行政部门、中央军事委员会机关有关部门负责全国学生军事训练工作。"},{"i":19,"n":"第十九条","txt":"普通高等学校、高中阶段学校应当按照学生军事训练大纲，加强军事技能训练，磨练学生意志品质，增强组织纪律性，提高军事训练水平。"},{"i":20,"n":"第二十条","txt":"国家机关应当根据各自的工作性质和特点，采取多种形式对工作人员进行国防教育。"},{"i":21,"n":"第二十一条","txt":"负责培训国家工作人员的各类教育机构，应当将国防教育纳入培训计划，设置适当的国防教育课程。"},{"i":22,"n":"第二十二条","txt":"企业事业组织应当将国防教育列入职工教育计划，结合政治教育、业务培训、文化体育等活动，对职工进行国防教育。"},{"i":23,"n":"第二十三条","txt":"省军区（卫戍区、警备区）、军分区（警备区）和县、自治县、不设区的市、市辖区的人民武装部按照国家和军队的有关规定，结合政治教育和组织整顿、军事训练、执行勤务、征兵工作以及重大节日、纪念日活动，对民兵进行国防教育。"},{"i":24,"n":"第二十四条","txt":"居民委员会、村民委员会应当将国防教育纳入社会主义精神文明建设的内容，结合征兵工作、拥军优属以及重大节日、纪念日活动，对居民、村民进行国防教育。"},{"i":25,"n":"第二十五条","txt":"文化和旅游、新闻出版、广播电视、电影、网信等部门和单位应当根据形势和任务的要求，创新宣传报道方式，通过发挥红色资源教育功能、推出优秀文艺作品、宣传发布先进典型、运用新平台新技术新产品等形式和途径开展国防教育。"},{"i":26,"n":"第二十六条","txt":"各地区、各部门应当利用重大节日、纪念日和重大主题活动等，广泛开展群众性国防教育活动；在全民国防教育日集中开展主题鲜明、形式多样的国防教育活动。"},{"i":27,"n":"第二十七条","txt":"英雄烈士纪念设施、革命旧址和其他具有国防教育功能的博物馆、纪念馆、科技馆、文化馆、青少年宫等场所，应当为公民接受国防教育提供便利，对有组织的国防教育活动实行免费或者优惠。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府应当将国防教育纳入国民经济和社会发展规划以及年度计划，将国防教育经费纳入预算。"},{"i":29,"n":"第二十九条","txt":"国家鼓励企业事业组织、社会组织和个人捐赠财产，资助国防教育的开展。"},{"i":30,"n":"第三十条","txt":"国防教育经费和企业事业组织、社会组织、个人资助国防教育的财产，必须用于国防教育事业，任何单位或者个人不得侵占、挪用、克扣。"},{"i":31,"n":"第三十一条","txt":"具备下列条件的场所，可以由设区的市级以上全民国防教育主管部门会同同级军事机关命名为国防教育基地："},{"i":32,"n":"第三十二条","txt":"各级人民政府应当加强对具有国防教育意义的文物的调查、登记和保护工作。"},{"i":33,"n":"第三十三条","txt":"全民国防教育使用统一的国防教育大纲。国防教育大纲由中央全民国防教育主管部门组织制定。"},{"i":34,"n":"第三十四条","txt":"各级全民国防教育主管部门应当组织、协调有关部门做好国防教育教员的选拔、培训和管理工作，加强国防教育师资队伍建设。"},{"i":35,"n":"第三十五条","txt":"中国人民解放军、中国人民武装警察部队应当根据需要，按照有关规定为有组织的国防教育活动选派军事教员，提供必要的军事训练场地、设施、器材和其他便利条件。"},{"i":36,"n":"第三十六条","txt":"国家机关、人民团体、企业事业组织以及社会组织和其他组织违反本法规定，拒不开展国防教育活动的，由有关部门或者上级机关给予批评教育，并责令限期改正；拒不改正，造成恶劣影响的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":37,"n":"第三十七条","txt":"违反本法规定，侵占、挪用、克扣国防教育经费或者企业事业组织、社会组织、个人资助的国防教育财产的，由有关主管部门责令限期归还；对负有责任的领导人员和直接责任人员依法给予处分。不适用处分的人员，由有关主管部门依法予以处理。"},{"i":38,"n":"第三十八条","txt":"侵占、破坏国防教育基地设施，损毁展品、器材的，由有关主管部门给予批评教育，并责令限期改正；有关责任人应当依法承担相应的民事责任；构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":39,"n":"第三十九条","txt":"寻衅滋事，扰乱国防教育工作和活动秩序的，或者盗用国防教育名义骗取钱财的，由有关主管部门给予批评教育，并予以制止；造成人身、财产或者其他损害的，应当依法承担相应的民事责任；构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":40,"n":"第四十条","txt":"负责国防教育的公职人员滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":41,"n":"第四十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"本法自2024年9月21日起施行。"}],"chengxiangguihuafa":[{"i":1,"n":"第一条","txt":"为了加强城乡规划管理，协调城乡空间布局，改善人居环境，促进城乡经济社会全面协调可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"制定和实施城乡规划，在规划区内进行建设活动，必须遵守本法。"},{"i":3,"n":"第三条","txt":"城市和镇应当依照本法制定城市规划和镇规划。城市、镇规划区内的建设活动应当符合规划要求。"},{"i":4,"n":"第四条","txt":"制定和实施城乡规划，应当遵循城乡统筹、合理布局、节约土地、集约发展和先规划后建设的原则，改善生态环境，促进资源、能源节约和综合利用，保护耕地等自然资源和历史文化遗产，保持地方特色、民族特色和传统风貌，防止污染和其他公害，并符合区域人口发展、国防建设、防灾减灾和公共卫生、公共安全的需要。"},{"i":5,"n":"第五条","txt":"城市总体规划、镇总体规划以及乡规划和村庄规划的编制，应当依据国民经济和社会发展规划，并与土地利用总体规划相衔接。"},{"i":6,"n":"第六条","txt":"各级人民政府应当将城乡规划的编制和管理经费纳入本级财政预算。"},{"i":7,"n":"第七条","txt":"经依法批准的城乡规划，是城乡建设和规划管理的依据，未经法定程序不得修改。"},{"i":8,"n":"第八条","txt":"城乡规划组织编制机关应当及时公布经依法批准的城乡规划。但是，法律、行政法规规定不得公开的内容除外。"},{"i":9,"n":"第九条","txt":"任何单位和个人都应当遵守经依法批准并公布的城乡规划，服从规划管理，并有权就涉及其利害关系的建设活动是否符合规划的要求向城乡规划主管部门查询。"},{"i":10,"n":"第十条","txt":"国家鼓励采用先进的科学技术，增强城乡规划的科学性，提高城乡规划实施及监督管理的效能。"},{"i":11,"n":"第十一条","txt":"国务院城乡规划主管部门负责全国的城乡规划管理工作。"},{"i":12,"n":"第十二条","txt":"国务院城乡规划主管部门会同国务院有关部门组织编制全国城镇体系规划，用于指导省域城镇体系规划、城市总体规划的编制。"},{"i":13,"n":"第十三条","txt":"省、自治区人民政府组织编制省域城镇体系规划，报国务院审批。"},{"i":14,"n":"第十四条","txt":"城市人民政府组织编制城市总体规划。"},{"i":15,"n":"第十五条","txt":"县人民政府组织编制县人民政府所在地镇的总体规划，报上一级人民政府审批。其他镇的总体规划由镇人民政府组织编制，报上一级人民政府审批。"},{"i":16,"n":"第十六条","txt":"省、自治区人民政府组织编制的省域城镇体系规划，城市、县人民政府组织编制的总体规划，在报上一级人民政府审批前，应当先经本级人民代表大会常务委员会审议，常务委员会组成人员的审议意见交由本级人民政府研究处理。"},{"i":17,"n":"第十七条","txt":"城市总体规划、镇总体规划的内容应当包括：城市、镇的发展布局，功能分区，用地布局，综合交通体系，禁止、限制和适宜建设的地域范围，各类专项规划等。"},{"i":18,"n":"第十八条","txt":"乡规划、村庄规划应当从农村实际出发，尊重村民意愿，体现地方和农村特色。"},{"i":19,"n":"第十九条","txt":"城市人民政府城乡规划主管部门根据城市总体规划的要求，组织编制城市的控制性详细规划，经本级人民政府批准后，报本级人民代表大会常务委员会和上一级人民政府备案。"},{"i":20,"n":"第二十条","txt":"镇人民政府根据镇总体规划的要求，组织编制镇的控制性详细规划，报上一级人民政府审批。县人民政府所在地镇的控制性详细规划，由县人民政府城乡规划主管部门根据镇总体规划的要求组织编制，经县人民政府批准后，报本级人民代表大会常务委员会和上一级人民政府备案。"},{"i":21,"n":"第二十一条","txt":"城市、县人民政府城乡规划主管部门和镇人民政府可以组织编制重要地块的修建性详细规划。修建性详细规划应当符合控制性详细规划。"},{"i":22,"n":"第二十二条","txt":"乡、镇人民政府组织编制乡规划、村庄规划，报上一级人民政府审批。村庄规划在报送审批前，应当经村民会议或者村民代表会议讨论同意。"},{"i":23,"n":"第二十三条","txt":"首都的总体规划、详细规划应当统筹考虑中央国家机关用地布局和空间安排的需要。"},{"i":24,"n":"第二十四条","txt":"城乡规划组织编制机关应当委托具有相应资质等级的单位承担城乡规划的具体编制工作。"},{"i":25,"n":"第二十五条","txt":"编制城乡规划，应当具备国家规定的勘察、测绘、气象、地震、水文、环境等基础资料。"},{"i":26,"n":"第二十六条","txt":"城乡规划报送审批前，组织编制机关应当依法将城乡规划草案予以公告，并采取论证会、听证会或者其他方式征求专家和公众的意见。公告的时间不得少于三十日。"},{"i":27,"n":"第二十七条","txt":"省域城镇体系规划、城市总体规划、镇总体规划批准前，审批机关应当组织专家和有关部门进行审查。"},{"i":28,"n":"第二十八条","txt":"地方各级人民政府应当根据当地经济社会发展水平，量力而行，尊重群众意愿，有计划、分步骤地组织实施城乡规划。"},{"i":29,"n":"第二十九条","txt":"城市的建设和发展，应当优先安排基础设施以及公共服务设施的建设，妥善处理新区开发与旧区改建的关系，统筹兼顾进城务工人员生活和周边农村经济社会发展、村民生产与生活的需要。"},{"i":30,"n":"第三十条","txt":"城市新区的开发和建设，应当合理确定建设规模和时序，充分利用现有市政基础设施和公共服务设施，严格保护自然资源和生态环境，体现地方特色。"},{"i":31,"n":"第三十一条","txt":"旧城区的改建，应当保护历史文化遗产和传统风貌，合理确定拆迁和建设规模，有计划地对危房集中、基础设施落后等地段进行改建。"},{"i":32,"n":"第三十二条","txt":"城乡建设和发展，应当依法保护和合理利用风景名胜资源，统筹安排风景名胜区及周边乡、镇、村庄的建设。"},{"i":33,"n":"第三十三条","txt":"城市地下空间的开发和利用，应当与经济和技术发展水平相适应，遵循统筹安排、综合开发、合理利用的原则，充分考虑防灾减灾、人民防空和通信等需要，并符合城市规划，履行规划审批手续。"},{"i":34,"n":"第三十四条","txt":"城市、县、镇人民政府应当根据城市总体规划、镇总体规划、土地利用总体规划和年度计划以及国民经济和社会发展规划，制定近期建设规划，报总体规划审批机关备案。"},{"i":35,"n":"第三十五条","txt":"城乡规划确定的铁路、公路、港口、机场、道路、绿地、输配电设施及输电线路走廊、通信设施、广播电视设施、管道设施、河道、水库、水源地、自然保护区、防汛通道、消防通道、核电站、垃圾填埋场及焚烧厂、污水处理厂和公共服务设施的用地以及其他需要依法保护的用地，禁止擅自改变用途。"},{"i":36,"n":"第三十六条","txt":"按照国家规定需要有关部门批准或者核准的建设项目，以划拨方式提供国有土地使用权的，建设单位在报送有关部门批准或者核准前，应当向城乡规划主管部门申请核发选址意见书。"},{"i":37,"n":"第三十七条","txt":"在城市、镇规划区内以划拨方式提供国有土地使用权的建设项目，经有关部门批准、核准、备案后，建设单位应当向城市、县人民政府城乡规划主管部门提出建设用地规划许可申请，由城市、县人民政府城乡规划主管部门依据控制性详细规划核定建设用地的位置、面积、允许建设的范围，核发建设用地规划许可证。"},{"i":38,"n":"第三十八条","txt":"在城市、镇规划区内以出让方式提供国有土地使用权的，在国有土地使用权出让前，城市、县人民政府城乡规划主管部门应当依据控制性详细规划，提出出让地块的位置、使用性质、开发强度等规划条件，作为国有土地使用权出让合同的组成部分。未确定规划条件的地块，不得出让国有土地使用权。"},{"i":39,"n":"第三十九条","txt":"规划条件未纳入国有土地使用权出让合同的，该国有土地使用权出让合同无效；对未取得建设用地规划许可证的建设单位批准用地的，由县级以上人民政府撤销有关批准文件；占用土地的，应当及时退回；给当事人造成损失的，应当依法给予赔偿。"},{"i":40,"n":"第四十条","txt":"在城市、镇规划区内进行建筑物、构筑物、道路、管线和其他工程建设的，建设单位或者个人应当向城市、县人民政府城乡规划主管部门或者省、自治区、直辖市人民政府确定的镇人民政府申请办理建设工程规划许可证。"},{"i":41,"n":"第四十一条","txt":"在乡、村庄规划区内进行乡镇企业、乡村公共设施和公益事业建设的，建设单位或者个人应当向乡、镇人民政府提出申请，由乡、镇人民政府报城市、县人民政府城乡规划主管部门核发乡村建设规划许可证。"},{"i":42,"n":"第四十二条","txt":"城乡规划主管部门不得在城乡规划确定的建设用地范围以外作出规划许可。"},{"i":43,"n":"第四十三条","txt":"建设单位应当按照规划条件进行建设；确需变更的，必须向城市、县人民政府城乡规划主管部门提出申请。变更内容不符合控制性详细规划的，城乡规划主管部门不得批准。城市、县人民政府城乡规划主管部门应当及时将依法变更后的规划条件通报同级土地主管部门并公示。"},{"i":44,"n":"第四十四条","txt":"在城市、镇规划区内进行临时建设的，应当经城市、县人民政府城乡规划主管部门批准。临时建设影响近期建设规划或者控制性详细规划的实施以及交通、市容、安全等的，不得批准。"},{"i":45,"n":"第四十五条","txt":"县级以上地方人民政府城乡规划主管部门按照国务院规定对建设工程是否符合规划条件予以核实。未经核实或者经核实不符合规划条件的，建设单位不得组织竣工验收。"},{"i":46,"n":"第四十六条","txt":"省域城镇体系规划、城市总体规划、镇总体规划的组织编制机关，应当组织有关部门和专家定期对规划实施情况进行评估，并采取论证会、听证会或者其他方式征求公众意见。组织编制机关应当向本级人民代表大会常务委员会、镇人民代表大会和原审批机关提出评估报告并附具征求意见的情况。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，组织编制机关方可按照规定的权限和程序修改省域城镇体系规划、城市总体规划、镇总体规划："},{"i":48,"n":"第四十八条","txt":"修改控制性详细规划的，组织编制机关应当对修改的必要性进行论证，征求规划地段内利害关系人的意见，并向原审批机关提出专题报告，经原审批机关同意后，方可编制修改方案。修改后的控制性详细规划，应当依照本法第十九条、第二十条规定的审批程序报批。控制性详细规划修改涉及城市总体规划、镇总体规划的强制性内容的，应当先修改总体规划。"},{"i":49,"n":"第四十九条","txt":"城市、县、镇人民政府修改近期建设规划的，应当将修改后的近期建设规划报总体规划审批机关备案。"},{"i":50,"n":"第五十条","txt":"在选址意见书、建设用地规划许可证、建设工程规划许可证或者乡村建设规划许可证发放后，因依法修改城乡规划给被许可人合法权益造成损失的，应当依法给予补偿。"},{"i":51,"n":"第五十一条","txt":"县级以上人民政府及其城乡规划主管部门应当加强对城乡规划编制、审批、实施、修改的监督检查。"},{"i":52,"n":"第五十二条","txt":"地方各级人民政府应当向本级人民代表大会常务委员会或者乡、镇人民代表大会报告城乡规划的实施情况，并接受监督。"},{"i":53,"n":"第五十三条","txt":"县级以上人民政府城乡规划主管部门对城乡规划的实施情况进行监督检查，有权采取以下措施："},{"i":54,"n":"第五十四条","txt":"监督检查情况和处理结果应当依法公开，供公众查阅和监督。"},{"i":55,"n":"第五十五条","txt":"城乡规划主管部门在查处违反本法规定的行为时，发现国家机关工作人员依法应当给予行政处分的，应当向其任免机关或者监察机关提出处分建议。"},{"i":56,"n":"第五十六条","txt":"依照本法规定应当给予行政处罚，而有关城乡规划主管部门不给予行政处罚的，上级人民政府城乡规划主管部门有权责令其作出行政处罚决定或者建议有关人民政府责令其给予行政处罚。"},{"i":57,"n":"第五十七条","txt":"城乡规划主管部门违反本法规定作出行政许可的，上级人民政府城乡规划主管部门有权责令其撤销或者直接撤销该行政许可。因撤销行政许可给当事人合法权益造成损失的，应当依法给予赔偿。"},{"i":58,"n":"第五十八条","txt":"对依法应当编制城乡规划而未组织编制，或者未按法定程序编制、审批、修改城乡规划的，由上级人民政府责令改正，通报批评；对有关人民政府负责人和其他直接责任人员依法给予处分。"},{"i":59,"n":"第五十九条","txt":"城乡规划组织编制机关委托不具有相应资质等级的单位编制城乡规划的，由上级人民政府责令改正，通报批评；对有关人民政府负责人和其他直接责任人员依法给予处分。"},{"i":60,"n":"第六十条","txt":"镇人民政府或者县级以上人民政府城乡规划主管部门有下列行为之一的，由本级人民政府、上级人民政府城乡规划主管部门或者监察机关依据职权责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":61,"n":"第六十一条","txt":"县级以上人民政府有关部门有下列行为之一的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":62,"n":"第六十二条","txt":"城乡规划编制单位有下列行为之一的，由所在地城市、县人民政府城乡规划主管部门责令限期改正，处合同约定的规划编制费一倍以上二倍以下的罚款；情节严重的，责令停业整顿，由原发证机关降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任："},{"i":63,"n":"第六十三条","txt":"城乡规划编制单位取得资质证书后，不再符合相应的资质条件的，由原发证机关责令限期改正；逾期不改正的，降低资质等级或者吊销资质证书。"},{"i":64,"n":"第六十四条","txt":"未取得建设工程规划许可证或者未按照建设工程规划许可证的规定进行建设的，由县级以上地方人民政府城乡规划主管部门责令停止建设；尚可采取改正措施消除对规划实施的影响的，限期改正，处建设工程造价百分之五以上百分之十以下的罚款；无法采取改正措施消除影响的，限期拆除，不能拆除的，没收实物或者违法收入，可以并处建设工程造价百分之十以下的罚款。"},{"i":65,"n":"第六十五条","txt":"在乡、村庄规划区内未依法取得乡村建设规划许可证或者未按照乡村建设规划许可证的规定进行建设的，由乡、镇人民政府责令停止建设、限期改正；逾期不改正的，可以拆除。"},{"i":66,"n":"第六十六条","txt":"建设单位或者个人有下列行为之一的，由所在地城市、县人民政府城乡规划主管部门责令限期拆除，可以并处临时建设工程造价一倍以下的罚款："},{"i":67,"n":"第六十七条","txt":"建设单位未在建设工程竣工验收后六个月内向城乡规划主管部门报送有关竣工验收资料的，由所在地城市、县人民政府城乡规划主管部门责令限期补报；逾期不补报的，处一万元以上五万元以下的罚款。"},{"i":68,"n":"第六十八条","txt":"城乡规划主管部门作出责令停止建设或者限期拆除的决定后，当事人不停止建设或者逾期不拆除的，建设工程所在地县级以上地方人民政府可以责成有关部门采取查封施工现场、强制拆除等措施。"},{"i":69,"n":"第六十九条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":70,"n":"第七十条","txt":"本法自2008年1月1日起施行。《中华人民共和国城市规划法》同时废止。"}],"chengshifangdichanguanlifa":[{"i":1,"n":"第一条","txt":"为了加强对城市房地产的管理，维护房地产市场秩序，保障房地产权利人的合法权益，促进房地产业的健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国城市规划区国有土地（以下简称国有土地）范围内取得房地产开发用地的土地使用权，从事房地产开发、房地产交易，实施房地产管理，应当遵守本法。"},{"i":3,"n":"第三条","txt":"国家依法实行国有土地有偿、有限期使用制度。但是，国家在本法规定的范围内划拨国有土地使用权的除外。"},{"i":4,"n":"第四条","txt":"国家根据社会、经济发展水平，扶持发展居民住宅建设，逐步改善居民的居住条件。"},{"i":5,"n":"第五条","txt":"房地产权利人应当遵守法律和行政法规，依法纳税。房地产权利人的合法权益受法律保护，任何单位和个人不得侵犯。"},{"i":6,"n":"第六条","txt":"为了公共利益的需要，国家可以征收国有土地上单位和个人的房屋，并依法给予拆迁补偿，维护被征收人的合法权益；征收个人住宅的，还应当保障被征收人的居住条件。具体办法由国务院规定。"},{"i":7,"n":"第七条","txt":"国务院建设行政主管部门、土地管理部门依照国务院规定的职权划分，各司其职，密切配合，管理全国房地产工作。"},{"i":8,"n":"第八条","txt":"土地使用权出让，是指国家将国有土地使用权（以下简称土地使用权）在一定年限内出让给土地使用者，由土地使用者向国家支付土地使用权出让金的行为。"},{"i":9,"n":"第九条","txt":"城市规划区内的集体所有的土地，经依法征收转为国有土地后，该幅国有土地的使用权方可有偿出让，但法律另有规定的除外。"},{"i":10,"n":"第十条","txt":"土地使用权出让，必须符合土地利用总体规划、城市规划和年度建设用地计划。"},{"i":11,"n":"第十一条","txt":"县级以上地方人民政府出让土地使用权用于房地产开发的，须根据省级以上人民政府下达的控制指标拟订年度出让土地使用权总面积方案，按照国务院规定，报国务院或者省级人民政府批准。"},{"i":12,"n":"第十二条","txt":"土地使用权出让，由市、县人民政府有计划、有步骤地进行。出让的每幅地块、用途、年限和其他条件，由市、县人民政府土地管理部门会同城市规划、建设、房产管理部门共同拟定方案，按照国务院规定，报经有批准权的人民政府批准后，由市、县人民政府土地管理部门实施。"},{"i":13,"n":"第十三条","txt":"土地使用权出让，可以采取拍卖、招标或者双方协议的方式。"},{"i":14,"n":"第十四条","txt":"土地使用权出让最高年限由国务院规定。"},{"i":15,"n":"第十五条","txt":"土地使用权出让，应当签订书面出让合同。"},{"i":16,"n":"第十六条","txt":"土地使用者必须按照出让合同约定，支付土地使用权出让金；未按照出让合同约定支付土地使用权出让金的，土地管理部门有权解除合同，并可以请求违约赔偿。"},{"i":17,"n":"第十七条","txt":"土地使用者按照出让合同约定支付土地使用权出让金的，市、县人民政府土地管理部门必须按照出让合同约定，提供出让的土地；未按照出让合同约定提供出让的土地的，土地使用者有权解除合同，由土地管理部门返还土地使用权出让金，土地使用者并可以请求违约赔偿。"},{"i":18,"n":"第十八条","txt":"土地使用者需要改变土地使用权出让合同约定的土地用途的，必须取得出让方和市、县人民政府城市规划行政主管部门的同意，签订土地使用权出让合同变更协议或者重新签订土地使用权出让合同，相应调整土地使用权出让金。"},{"i":19,"n":"第十九条","txt":"土地使用权出让金应当全部上缴财政，列入预算，用于城市基础设施建设和土地开发。土地使用权出让金上缴和使用的具体办法由国务院规定。"},{"i":20,"n":"第二十条","txt":"国家对土地使用者依法取得的土地使用权，在出让合同约定的使用年限届满前不收回；在特殊情况下，根据社会公共利益的需要，可以依照法律程序提前收回，并根据土地使用者使用土地的实际年限和开发土地的实际情况给予相应的补偿。"},{"i":21,"n":"第二十一条","txt":"土地使用权因土地灭失而终止。"},{"i":22,"n":"第二十二条","txt":"土地使用权出让合同约定的使用年限届满，土地使用者需要继续使用土地的，应当至迟于届满前一年申请续期，除根据社会公共利益需要收回该幅土地的，应当予以批准。经批准准予续期的，应当重新签订土地使用权出让合同，依照规定支付土地使用权出让金。"},{"i":23,"n":"第二十三条","txt":"土地使用权划拨，是指县级以上人民政府依法批准，在土地使用者缴纳补偿、安置等费用后将该幅土地交付其使用，或者将土地使用权无偿交付给土地使用者使用的行为。"},{"i":24,"n":"第二十四条","txt":"下列建设用地的土地使用权，确属必需的，可以由县级以上人民政府依法批准划拨："},{"i":25,"n":"第二十五条","txt":"房地产开发必须严格执行城市规划，按照经济效益、社会效益、环境效益相统一的原则，实行全面规划、合理布局、综合开发、配套建设。"},{"i":26,"n":"第二十六条","txt":"以出让方式取得土地使用权进行房地产开发的，必须按照土地使用权出让合同约定的土地用途、动工开发期限开发土地。超过出让合同约定的动工开发日期满一年未动工开发的，可以征收相当于土地使用权出让金百分之二十以下的土地闲置费；满二年未动工开发的，可以无偿收回土地使用权；但是，因不可抗力或者政府、政府有关部门的行为或者动工开发必需的前期工作造成动工开发迟延的除外。"},{"i":27,"n":"第二十七条","txt":"房地产开发项目的设计、施工，必须符合国家的有关标准和规范。"},{"i":28,"n":"第二十八条","txt":"依法取得的土地使用权，可以依照本法和有关法律、行政法规的规定，作价入股，合资、合作开发经营房地产。"},{"i":29,"n":"第二十九条","txt":"国家采取税收等方面的优惠措施鼓励和扶持房地产开发企业开发建设居民住宅。"},{"i":30,"n":"第三十条","txt":"房地产开发企业是以营利为目的，从事房地产开发和经营的企业。设立房地产开发企业，应当具备下列条件："},{"i":31,"n":"第三十一条","txt":"房地产开发企业的注册资本与投资总额的比例应当符合国家有关规定。"},{"i":32,"n":"第三十二条","txt":"房地产转让、抵押时，房屋的所有权和该房屋占用范围内的土地使用权同时转让、抵押。"},{"i":33,"n":"第三十三条","txt":"基准地价、标定地价和各类房屋的重置价格应当定期确定并公布。具体办法由国务院规定。"},{"i":34,"n":"第三十四条","txt":"国家实行房地产价格评估制度。"},{"i":35,"n":"第三十五条","txt":"国家实行房地产成交价格申报制度。"},{"i":36,"n":"第三十六条","txt":"房地产转让、抵押，当事人应当依照本法第五章的规定办理权属登记。"},{"i":37,"n":"第三十七条","txt":"房地产转让，是指房地产权利人通过买卖、赠与或者其他合法方式将其房地产转移给他人的行为。"},{"i":38,"n":"第三十八条","txt":"下列房地产，不得转让："},{"i":39,"n":"第三十九条","txt":"以出让方式取得土地使用权的，转让房地产时，应当符合下列条件："},{"i":40,"n":"第四十条","txt":"以划拨方式取得土地使用权的，转让房地产时，应当按照国务院规定，报有批准权的人民政府审批。有批准权的人民政府准予转让的，应当由受让方办理土地使用权出让手续，并依照国家有关规定缴纳土地使用权出让金。"},{"i":41,"n":"第四十一条","txt":"房地产转让，应当签订书面转让合同，合同中应当载明土地使用权取得的方式。"},{"i":42,"n":"第四十二条","txt":"房地产转让时，土地使用权出让合同载明的权利、义务随之转移。"},{"i":43,"n":"第四十三条","txt":"以出让方式取得土地使用权的，转让房地产后，其土地使用权的使用年限为原土地使用权出让合同约定的使用年限减去原土地使用者已经使用年限后的剩余年限。"},{"i":44,"n":"第四十四条","txt":"以出让方式取得土地使用权的，转让房地产后，受让人改变原土地使用权出让合同约定的土地用途的，必须取得原出让方和市、县人民政府城市规划行政主管部门的同意，签订土地使用权出让合同变更协议或者重新签订土地使用权出让合同，相应调整土地使用权出让金。"},{"i":45,"n":"第四十五条","txt":"商品房预售，应当符合下列条件："},{"i":46,"n":"第四十六条","txt":"商品房预售的，商品房预购人将购买的未竣工的预售商品房再行转让的问题，由国务院规定。"},{"i":47,"n":"第四十七条","txt":"房地产抵押，是指抵押人以其合法的房地产以不转移占有的方式向抵押权人提供债务履行担保的行为。债务人不履行债务时，抵押权人有权依法以抵押的房地产拍卖所得的价款优先受偿。"},{"i":48,"n":"第四十八条","txt":"依法取得的房屋所有权连同该房屋占用范围内的土地使用权，可以设定抵押权。"},{"i":49,"n":"第四十九条","txt":"房地产抵押，应当凭土地使用权证书、房屋所有权证书办理。"},{"i":50,"n":"第五十条","txt":"房地产抵押，抵押人和抵押权人应当签订书面抵押合同。"},{"i":51,"n":"第五十一条","txt":"设定房地产抵押权的土地使用权是以划拨方式取得的，依法拍卖该房地产后，应当从拍卖所得的价款中缴纳相当于应缴纳的土地使用权出让金的款额后，抵押权人方可优先受偿。"},{"i":52,"n":"第五十二条","txt":"房地产抵押合同签订后，土地上新增的房屋不属于抵押财产。需要拍卖该抵押的房地产时，可以依法将土地上新增的房屋与抵押财产一同拍卖，但对拍卖新增房屋所得，抵押权人无权优先受偿。"},{"i":53,"n":"第五十三条","txt":"房屋租赁，是指房屋所有权人作为出租人将其房屋出租给承租人使用，由承租人向出租人支付租金的行为。"},{"i":54,"n":"第五十四条","txt":"房屋租赁，出租人和承租人应当签订书面租赁合同，约定租赁期限、租赁用途、租赁价格、修缮责任等条款，以及双方的其他权利和义务，并向房产管理部门登记备案。"},{"i":55,"n":"第五十五条","txt":"住宅用房的租赁，应当执行国家和房屋所在城市人民政府规定的租赁政策。租用房屋从事生产、经营活动的，由租赁双方协商议定租金和其他租赁条款。"},{"i":56,"n":"第五十六条","txt":"以营利为目的，房屋所有权人将以划拨方式取得使用权的国有土地上建成的房屋出租的，应当将租金中所含土地收益上缴国家。具体办法由国务院规定。"},{"i":57,"n":"第五十七条","txt":"房地产中介服务机构包括房地产咨询机构、房地产价格评估机构、房地产经纪机构等。"},{"i":58,"n":"第五十八条","txt":"房地产中介服务机构应当具备下列条件："},{"i":59,"n":"第五十九条","txt":"国家实行房地产价格评估人员资格认证制度。"},{"i":60,"n":"第六十条","txt":"国家实行土地使用权和房屋所有权登记发证制度。"},{"i":61,"n":"第六十一条","txt":"以出让或者划拨方式取得土地使用权，应当向县级以上地方人民政府土地管理部门申请登记，经县级以上地方人民政府土地管理部门核实，由同级人民政府颁发土地使用权证书。"},{"i":62,"n":"第六十二条","txt":"房地产抵押时，应当向县级以上地方人民政府规定的部门办理抵押登记。"},{"i":63,"n":"第六十三条","txt":"经省、自治区、直辖市人民政府确定，县级以上地方人民政府由一个部门统一负责房产管理和土地管理工作的，可以制作、颁发统一的房地产权证书，依照本法第六十一条的规定，将房屋的所有权和该房屋占用范围内的土地使用权的确认和变更，分别载入房地产权证书。"},{"i":64,"n":"第六十四条","txt":"违反本法第十一条、第十二条的规定，擅自批准出让或者擅自出让土地使用权用于房地产开发的，由上级机关或者所在单位给予有关责任人员行政处分。"},{"i":65,"n":"第六十五条","txt":"违反本法第三十条的规定，未取得营业执照擅自从事房地产开发业务的，由县级以上人民政府工商行政管理部门责令停止房地产开发业务活动，没收违法所得，可以并处罚款。"},{"i":66,"n":"第六十六条","txt":"违反本法第三十九条第一款的规定转让土地使用权的，由县级以上人民政府土地管理部门没收违法所得，可以并处罚款。"},{"i":67,"n":"第六十七条","txt":"违反本法第四十条第一款的规定转让房地产的，由县级以上人民政府土地管理部门责令缴纳土地使用权出让金，没收违法所得，可以并处罚款。"},{"i":68,"n":"第六十八条","txt":"违反本法第四十五条第一款的规定预售商品房的，由县级以上人民政府房产管理部门责令停止预售活动，没收违法所得，可以并处罚款。"},{"i":69,"n":"第六十九条","txt":"违反本法第五十八条的规定，未取得营业执照擅自从事房地产中介服务业务的，由县级以上人民政府工商行政管理部门责令停止房地产中介服务业务活动，没收违法所得，可以并处罚款。"},{"i":70,"n":"第七十条","txt":"没有法律、法规的依据，向房地产开发企业收费的，上级机关应当责令退回所收取的钱款；情节严重的，由上级机关或者所在单位给予直接责任人员行政处分。"},{"i":71,"n":"第七十一条","txt":"房产管理部门、土地管理部门工作人员玩忽职守、滥用职权，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。"},{"i":72,"n":"第七十二条","txt":"在城市规划区外的国有土地范围内取得房地产开发用地的土地使用权，从事房地产开发、交易活动以及实施房地产管理，参照本法执行。"},{"i":73,"n":"第七十三条","txt":"本法自1995年1月1日起施行。"}],"jibenyiliaoweishengyujiankangcujinfa":[{"i":1,"n":"第一条","txt":"为了发展医疗卫生与健康事业，保障公民享有基本医疗卫生服务，提高公民健康水平，推进健康中国建设，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"从事医疗卫生、健康促进及其监督管理活动，适用本法。"},{"i":3,"n":"第三条","txt":"医疗卫生与健康事业应当坚持以人民为中心，为人民健康服务。"},{"i":4,"n":"第四条","txt":"国家和社会尊重、保护公民的健康权。"},{"i":5,"n":"第五条","txt":"公民依法享有从国家和社会获得基本医疗卫生服务的权利。"},{"i":6,"n":"第六条","txt":"各级人民政府应当把人民健康放在优先发展的战略地位，将健康理念融入各项政策，坚持预防为主，完善健康促进工作体系，组织实施健康促进的规划和行动，推进全民健身，建立健康影响评估制度，将公民主要健康指标改善情况纳入政府目标责任考核。"},{"i":7,"n":"第七条","txt":"国务院和地方各级人民政府领导医疗卫生与健康促进工作。"},{"i":8,"n":"第八条","txt":"国家加强医学基础科学研究，鼓励医学科学技术创新，支持临床医学发展，促进医学科技成果的转化和应用，推进医疗卫生与信息技术融合发展，推广医疗卫生适宜技术，提高医疗卫生服务质量。"},{"i":9,"n":"第九条","txt":"国家大力发展中医药事业，坚持中西医并重、传承与创新相结合，发挥中医药在医疗卫生与健康事业中的独特作用。"},{"i":10,"n":"第十条","txt":"国家合理规划和配置医疗卫生资源，以基层为重点，采取多种措施优先支持县级以下医疗卫生机构发展，提高其医疗卫生服务能力。"},{"i":11,"n":"第十一条","txt":"国家加大对医疗卫生与健康事业的财政投入，通过增加转移支付等方式重点扶持革命老区、民族地区、边疆地区和经济欠发达地区发展医疗卫生与健康事业。"},{"i":12,"n":"第十二条","txt":"国家鼓励和支持公民、法人和其他组织通过依法举办机构和捐赠、资助等方式，参与医疗卫生与健康事业，满足公民多样化、差异化、个性化健康需求。"},{"i":13,"n":"第十三条","txt":"对在医疗卫生与健康事业中做出突出贡献的组织和个人，按照国家规定给予表彰、奖励。"},{"i":14,"n":"第十四条","txt":"国家鼓励和支持医疗卫生与健康促进领域的对外交流合作。"},{"i":15,"n":"第十五条","txt":"基本医疗卫生服务，是指维护人体健康所必需、与经济社会发展水平相适应、公民可公平获得的，采用适宜药物、适宜技术、适宜设备提供的疾病预防、诊断、治疗、护理和康复等服务。"},{"i":16,"n":"第十六条","txt":"国家采取措施，保障公民享有安全有效的基本公共卫生服务，控制影响健康的危险因素，提高疾病的预防控制水平。"},{"i":17,"n":"第十七条","txt":"国务院和省、自治区、直辖市人民政府可以将针对重点地区、重点疾病和特定人群的服务内容纳入基本公共卫生服务项目并组织实施。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府通过举办专业公共卫生机构、基层医疗卫生机构和医院，或者从其他医疗卫生机构购买服务的方式提供基本公共卫生服务。"},{"i":19,"n":"第十九条","txt":"国家建立健全突发事件卫生应急体系，制定和完善应急预案，组织开展突发事件的医疗救治、卫生学调查处置和心理援助等卫生应急工作，有效控制和消除危害。"},{"i":20,"n":"第二十条","txt":"国家建立传染病防控制度，制定传染病防治规划并组织实施，加强传染病监测预警，坚持预防为主、防治结合，联防联控、群防群控、源头防控、综合治理，阻断传播途径，保护易感人群，降低传染病的危害。"},{"i":21,"n":"第二十一条","txt":"国家实行预防接种制度，加强免疫规划工作。居民有依法接种免疫规划疫苗的权利和义务。政府向居民免费提供免疫规划疫苗。"},{"i":22,"n":"第二十二条","txt":"国家建立慢性非传染性疾病防控与管理制度，对慢性非传染性疾病及其致病危险因素开展监测、调查和综合防控干预，及时发现高危人群，为患者和高危人群提供诊疗、早期干预、随访管理和健康教育等服务。"},{"i":23,"n":"第二十三条","txt":"国家加强职业健康保护。县级以上人民政府应当制定职业病防治规划，建立健全职业健康工作机制，加强职业健康监督管理，提高职业病综合防治能力和水平。"},{"i":24,"n":"第二十四条","txt":"国家发展妇幼保健事业，建立健全妇幼健康服务体系，为妇女、儿童提供保健及常见病防治服务，保障妇女、儿童健康。"},{"i":25,"n":"第二十五条","txt":"国家发展老年人保健事业。国务院和省、自治区、直辖市人民政府应当将老年人健康管理和常见病预防等纳入基本公共卫生服务项目。"},{"i":26,"n":"第二十六条","txt":"国家发展残疾预防和残疾人康复事业，完善残疾预防和残疾人康复及其保障体系，采取措施为残疾人提供基本康复服务。"},{"i":27,"n":"第二十七条","txt":"国家建立健全院前急救体系，为急危重症患者提供及时、规范、有效的急救服务。"},{"i":28,"n":"第二十八条","txt":"国家发展精神卫生事业，建设完善精神卫生服务体系，维护和增进公民心理健康，预防、治疗精神障碍。"},{"i":29,"n":"第二十九条","txt":"基本医疗服务主要由政府举办的医疗卫生机构提供。鼓励社会力量举办的医疗卫生机构提供基本医疗服务。"},{"i":30,"n":"第三十条","txt":"国家推进基本医疗服务实行分级诊疗制度，引导非急诊患者首先到基层医疗卫生机构就诊，实行首诊负责制和转诊审核责任制，逐步建立基层首诊、双向转诊、急慢分治、上下联动的机制，并与基本医疗保险制度相衔接。"},{"i":31,"n":"第三十一条","txt":"国家推进基层医疗卫生机构实行家庭医生签约服务，建立家庭医生服务团队，与居民签订协议，根据居民健康状况和医疗需求提供基本医疗卫生服务。"},{"i":32,"n":"第三十二条","txt":"公民接受医疗卫生服务，对病情、诊疗方案、医疗风险、医疗费用等事项依法享有知情同意的权利。"},{"i":33,"n":"第三十三条","txt":"公民接受医疗卫生服务，应当受到尊重。医疗卫生机构、医疗卫生人员应当关心爱护、平等对待患者，尊重患者人格尊严，保护患者隐私。"},{"i":34,"n":"第三十四条","txt":"国家建立健全由基层医疗卫生机构、医院、专业公共卫生机构等组成的城乡全覆盖、功能互补、连续协同的医疗卫生服务体系。"},{"i":35,"n":"第三十五条","txt":"基层医疗卫生机构主要提供预防、保健、健康教育、疾病管理，为居民建立健康档案，常见病、多发病的诊疗以及部分疾病的康复、护理，接收医院转诊患者，向医院转诊超出自身服务能力的患者等基本医疗卫生服务。"},{"i":36,"n":"第三十六条","txt":"各级各类医疗卫生机构应当分工合作，为公民提供预防、保健、治疗、护理、康复、安宁疗护等全方位全周期的医疗卫生服务。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府应当制定并落实医疗卫生服务体系规划，科学配置医疗卫生资源，举办医疗卫生机构，为公民获得基本医疗卫生服务提供保障。"},{"i":38,"n":"第三十八条","txt":"举办医疗机构，应当具备下列条件，按照国家有关规定办理审批或者备案手续："},{"i":39,"n":"第三十九条","txt":"国家对医疗卫生机构实行分类管理。"},{"i":40,"n":"第四十条","txt":"政府举办的医疗卫生机构应当坚持公益性质，所有收支均纳入预算管理，按照医疗卫生服务体系规划合理设置并控制规模。"},{"i":41,"n":"第四十一条","txt":"国家采取多种措施，鼓励和引导社会力量依法举办医疗卫生机构，支持和规范社会力量举办的医疗卫生机构与政府举办的医疗卫生机构开展多种类型的医疗业务、学科建设、人才培养等合作。"},{"i":42,"n":"第四十二条","txt":"国家以建成的医疗卫生机构为基础，合理规划与设置国家医学中心和国家、省级区域性医疗中心，诊治疑难重症，研究攻克重大医学难题，培养高层次医疗卫生人才。"},{"i":43,"n":"第四十三条","txt":"医疗卫生机构应当遵守法律、法规、规章，建立健全内部质量管理和控制制度，对医疗卫生服务质量负责。"},{"i":44,"n":"第四十四条","txt":"国家对医疗卫生技术的临床应用进行分类管理，对技术难度大、医疗风险高，服务能力、人员专业技术水平要求较高的医疗卫生技术实行严格管理。"},{"i":45,"n":"第四十五条","txt":"国家建立权责清晰、管理科学、治理完善、运行高效、监督有力的现代医院管理制度。"},{"i":46,"n":"第四十六条","txt":"医疗卫生机构执业场所是提供医疗卫生服务的公共场所，任何组织或者个人不得扰乱其秩序。"},{"i":47,"n":"第四十七条","txt":"国家完善医疗风险分担机制，鼓励医疗机构参加医疗责任保险或者建立医疗风险基金，鼓励患者参加医疗意外保险。"},{"i":48,"n":"第四十八条","txt":"国家鼓励医疗卫生机构不断改进预防、保健、诊断、治疗、护理和康复的技术、设备与服务，支持开发适合基层和边远地区应用的医疗卫生技术。"},{"i":49,"n":"第四十九条","txt":"国家推进全民健康信息化，推动健康医疗大数据、人工智能等的应用发展，加快医疗卫生信息基础设施建设，制定健康医疗数据采集、存储、分析和应用的技术标准，运用信息技术促进优质医疗卫生资源的普及与共享。"},{"i":50,"n":"第五十条","txt":"发生自然灾害、事故灾难、公共卫生事件和社会安全事件等严重威胁人民群众生命健康的突发事件时，医疗卫生机构、医疗卫生人员应当服从政府部门的调遣，参与卫生应急处置和医疗救治。对致病、致残、死亡的参与人员，按照规定给予工伤或者抚恤、烈士褒扬等相关待遇。"},{"i":51,"n":"第五十一条","txt":"医疗卫生人员应当弘扬敬佑生命、救死扶伤、甘于奉献、大爱无疆的崇高职业精神，遵守行业规范，恪守医德，努力提高专业水平和服务质量。"},{"i":52,"n":"第五十二条","txt":"国家制定医疗卫生人员培养规划，建立适应行业特点和社会需求的医疗卫生人员培养机制和供需平衡机制，完善医学院校教育、毕业后教育和继续教育体系，建立健全住院医师、专科医师规范化培训制度，建立规模适宜、结构合理、分布均衡的医疗卫生队伍。"},{"i":53,"n":"第五十三条","txt":"国家对医师、护士等医疗卫生人员依法实行执业注册制度。医疗卫生人员应当依法取得相应的职业资格。"},{"i":54,"n":"第五十四条","txt":"医疗卫生人员应当遵循医学科学规律，遵守有关临床诊疗技术规范和各项操作规范以及医学伦理规范，使用适宜技术和药物，合理诊疗，因病施治，不得对患者实施过度医疗。"},{"i":55,"n":"第五十五条","txt":"国家建立健全符合医疗卫生行业特点的人事、薪酬、奖励制度，体现医疗卫生人员职业特点和技术劳动价值。"},{"i":56,"n":"第五十六条","txt":"国家建立医疗卫生人员定期到基层和艰苦边远地区从事医疗卫生工作制度。"},{"i":57,"n":"第五十七条","txt":"全社会应当关心、尊重医疗卫生人员，维护良好安全的医疗卫生服务秩序，共同构建和谐医患关系。"},{"i":58,"n":"第五十八条","txt":"国家完善药品供应保障制度，建立工作协调机制，保障药品的安全、有效、可及。"},{"i":59,"n":"第五十九条","txt":"国家实施基本药物制度，遴选适当数量的基本药物品种，满足疾病防治基本用药需求。"},{"i":60,"n":"第六十条","txt":"国家建立健全以临床需求为导向的药品审评审批制度，支持临床急需药品、儿童用药品和防治罕见病、重大疾病等药品的研制、生产，满足疾病防治需求。"},{"i":61,"n":"第六十一条","txt":"国家建立健全药品研制、生产、流通、使用全过程追溯制度，加强药品管理，保证药品质量。"},{"i":62,"n":"第六十二条","txt":"国家建立健全药品价格监测体系，开展成本价格调查，加强药品价格监督检查，依法查处价格垄断、价格欺诈、不正当竞争等违法行为，维护药品价格秩序。"},{"i":63,"n":"第六十三条","txt":"国家建立中央与地方两级医药储备，用于保障重大灾情、疫情及其他突发事件等应急需要。"},{"i":64,"n":"第六十四条","txt":"国家建立健全药品供求监测体系，及时收集和汇总分析药品供求信息，定期公布药品生产、流通、使用等情况。"},{"i":65,"n":"第六十五条","txt":"国家加强对医疗器械的管理，完善医疗器械的标准和规范，提高医疗器械的安全有效水平。"},{"i":66,"n":"第六十六条","txt":"国家加强中药的保护与发展，充分体现中药的特色和优势，发挥其在预防、保健、医疗、康复中的作用。"},{"i":67,"n":"第六十七条","txt":"各级人民政府应当加强健康教育工作及其专业人才培养，建立健康知识和技能核心信息发布制度，普及健康科学知识，向公众提供科学、准确的健康信息。"},{"i":68,"n":"第六十八条","txt":"国家将健康教育纳入国民教育体系。学校应当利用多种形式实施健康教育，普及健康知识、科学健身知识、急救知识和技能，提高学生主动防病的意识，培养学生良好的卫生习惯和健康的行为习惯，减少、改善学生近视、肥胖等不良健康状况。"},{"i":69,"n":"第六十九条","txt":"公民是自己健康的第一责任人，树立和践行对自己健康负责的健康管理理念，主动学习健康知识，提高健康素养，加强健康管理。倡导家庭成员相互关爱，形成符合自身和家庭特点的健康生活方式。"},{"i":70,"n":"第七十条","txt":"国家组织居民健康状况调查和统计，开展体质监测，对健康绩效进行评估，并根据评估结果制定、完善与健康相关的法律、法规、政策和规划。"},{"i":71,"n":"第七十一条","txt":"国家建立疾病和健康危险因素监测、调查和风险评估制度。县级以上人民政府及其有关部门针对影响健康的主要问题，组织开展健康危险因素研究，制定综合防治措施。"},{"i":72,"n":"第七十二条","txt":"国家大力开展爱国卫生运动，鼓励和支持开展爱国卫生月等群众性卫生与健康活动，依靠和动员群众控制和消除健康危险因素，改善环境卫生状况，建设健康城市、健康村镇、健康社区。"},{"i":73,"n":"第七十三条","txt":"国家建立科学、严格的食品、饮用水安全监督管理制度，提高安全水平。"},{"i":74,"n":"第七十四条","txt":"国家建立营养状况监测制度，实施经济欠发达地区、重点人群营养干预计划，开展未成年人和老年人营养改善行动，倡导健康饮食习惯，减少不健康饮食引起的疾病风险。"},{"i":75,"n":"第七十五条","txt":"国家发展全民健身事业，完善覆盖城乡的全民健身公共服务体系，加强公共体育设施建设，组织开展和支持全民健身活动，加强全民健身指导服务，普及科学健身知识和方法。"},{"i":76,"n":"第七十六条","txt":"国家制定并实施未成年人、妇女、老年人、残疾人等的健康工作计划，加强重点人群健康服务。"},{"i":77,"n":"第七十七条","txt":"国家完善公共场所卫生管理制度。县级以上人民政府卫生健康等主管部门应当加强对公共场所的卫生监督。公共场所卫生监督信息应当依法向社会公开。"},{"i":78,"n":"第七十八条","txt":"国家采取措施，减少吸烟对公民健康的危害。"},{"i":79,"n":"第七十九条","txt":"用人单位应当为职工创造有益于健康的环境和条件，严格执行劳动安全卫生等相关规定，积极组织职工开展健身活动，保护职工健康。"},{"i":80,"n":"第八十条","txt":"各级人民政府应当切实履行发展医疗卫生与健康事业的职责，建立与经济社会发展、财政状况和健康指标相适应的医疗卫生与健康事业投入机制，将医疗卫生与健康促进经费纳入本级政府预算，按照规定主要用于保障基本医疗服务、公共卫生服务、基本医疗保障和政府举办的医疗卫生机构建设和运行发展。"},{"i":81,"n":"第八十一条","txt":"县级以上人民政府通过预算、审计、监督执法、社会监督等方式，加强资金的监督管理。"},{"i":82,"n":"第八十二条","txt":"基本医疗服务费用主要由基本医疗保险基金和个人支付。国家依法多渠道筹集基本医疗保险基金，逐步完善基本医疗保险可持续筹资和保障水平调整机制。"},{"i":83,"n":"第八十三条","txt":"国家建立以基本医疗保险为主体，商业健康保险、医疗救助、职工互助医疗和医疗慈善服务等为补充的、多层次的医疗保障体系。"},{"i":84,"n":"第八十四条","txt":"国家建立健全基本医疗保险经办机构与协议定点医疗卫生机构之间的协商谈判机制，科学合理确定基本医疗保险基金支付标准和支付方式，引导医疗卫生机构合理诊疗，促进患者有序流动，提高基本医疗保险基金使用效益。"},{"i":85,"n":"第八十五条","txt":"基本医疗保险基金支付范围由国务院医疗保障主管部门组织制定，并应当听取国务院卫生健康主管部门、中医药主管部门、药品监督管理部门、财政部门等的意见。"},{"i":86,"n":"第八十六条","txt":"国家建立健全机构自治、行业自律、政府监管、社会监督相结合的医疗卫生综合监督管理体系。"},{"i":87,"n":"第八十七条","txt":"县级以上人民政府医疗保障主管部门应当提高医疗保障监管能力和水平，对纳入基本医疗保险基金支付范围的医疗服务行为和医疗费用加强监督管理，确保基本医疗保险基金合理使用、安全可控。"},{"i":88,"n":"第八十八条","txt":"县级以上人民政府应当组织卫生健康、医疗保障、药品监督管理、发展改革、财政等部门建立沟通协商机制，加强制度衔接和工作配合，提高医疗卫生资源使用效率和保障水平。"},{"i":89,"n":"第八十九条","txt":"县级以上人民政府应当定期向本级人民代表大会或者其常务委员会报告基本医疗卫生与健康促进工作，依法接受监督。"},{"i":90,"n":"第九十条","txt":"县级以上人民政府有关部门未履行医疗卫生与健康促进工作相关职责的，本级人民政府或者上级人民政府有关部门应当对其主要负责人进行约谈。"},{"i":91,"n":"第九十一条","txt":"县级以上地方人民政府卫生健康主管部门应当建立医疗卫生机构绩效评估制度，组织对医疗卫生机构的服务质量、医疗技术、药品和医用设备使用等情况进行评估。评估应当吸收行业组织和公众参与。评估结果应当以适当方式向社会公开，作为评价医疗卫生机构和卫生监管的重要依据。"},{"i":92,"n":"第九十二条","txt":"国家保护公民个人健康信息，确保公民个人健康信息安全。任何组织或者个人不得非法收集、使用、加工、传输公民个人健康信息，不得非法买卖、提供或者公开公民个人健康信息。"},{"i":93,"n":"第九十三条","txt":"县级以上人民政府卫生健康主管部门、医疗保障主管部门应当建立医疗卫生机构、人员等信用记录制度，纳入全国信用信息共享平台，按照国家规定实施联合惩戒。"},{"i":94,"n":"第九十四条","txt":"县级以上地方人民政府卫生健康主管部门及其委托的卫生健康监督机构，依法开展本行政区域医疗卫生等行政执法工作。"},{"i":95,"n":"第九十五条","txt":"县级以上人民政府卫生健康主管部门应当积极培育医疗卫生行业组织，发挥其在医疗卫生与健康促进工作中的作用，支持其参与行业管理规范、技术标准制定和医疗卫生评价、评估、评审等工作。"},{"i":96,"n":"第九十六条","txt":"国家建立医疗纠纷预防和处理机制，妥善处理医疗纠纷，维护医疗秩序。"},{"i":97,"n":"第九十七条","txt":"国家鼓励公民、法人和其他组织对医疗卫生与健康促进工作进行社会监督。"},{"i":98,"n":"第九十八条","txt":"违反本法规定，地方各级人民政府、县级以上人民政府卫生健康主管部门和其他有关部门，滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":99,"n":"第九十九条","txt":"违反本法规定，未取得医疗机构执业许可证擅自执业的，由县级以上人民政府卫生健康主管部门责令停止执业活动，没收违法所得和药品、医疗器械，并处违法所得五倍以上二十倍以下的罚款，违法所得不足一万元的，按一万元计算。"},{"i":100,"n":"第一百条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府卫生健康主管部门责令改正，没收违法所得，并处违法所得二倍以上十倍以下的罚款，违法所得不足一万元的，按一万元计算；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":101,"n":"第一百零一条","txt":"违反本法规定，医疗卫生机构等的医疗信息安全制度、保障措施不健全，导致医疗信息泄露，或者医疗质量管理和医疗技术管理制度、安全措施不健全的，由县级以上人民政府卫生健康等主管部门责令改正，给予警告，并处一万元以上五万元以下的罚款；情节严重的，可以责令停止相应执业活动，对直接负责的主管人员和其他直接责任人员依法追究法律责任。"},{"i":102,"n":"第一百零二条","txt":"违反本法规定，医疗卫生人员有下列行为之一的，由县级以上人民政府卫生健康主管部门依照有关执业医师、护士管理和医疗纠纷预防处理等法律、行政法规的规定给予行政处罚："},{"i":103,"n":"第一百零三条","txt":"违反本法规定，参加药品采购投标的投标人以低于成本的报价竞标，或者以欺诈、串通投标、滥用市场支配地位等方式竞标的，由县级以上人民政府医疗保障主管部门责令改正，没收违法所得；中标的，中标无效，处中标项目金额千分之五以上千分之十以下的罚款，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员处对单位罚款数额百分之五以上百分之十以下的罚款；情节严重的，取消其二年至五年内参加药品采购投标的资格并予以公告。"},{"i":104,"n":"第一百零四条","txt":"违反本法规定，以欺诈、伪造证明材料或者其他手段骗取基本医疗保险待遇，或者基本医疗保险经办机构以及医疗机构、药品经营单位等以欺诈、伪造证明材料或者其他手段骗取基本医疗保险基金支出的，由县级以上人民政府医疗保障主管部门依照有关社会保险的法律、行政法规规定给予行政处罚。"},{"i":105,"n":"第一百零五条","txt":"违反本法规定，扰乱医疗卫生机构执业场所秩序，威胁、危害医疗卫生人员人身安全，侵犯医疗卫生人员人格尊严，非法收集、使用、加工、传输公民个人健康信息，非法买卖、提供或者公开公民个人健康信息等，构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":106,"n":"第一百零六条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任；造成人身、财产损害的，依法承担民事责任。"},{"i":107,"n":"第一百零七条","txt":"本法中下列用语的含义："},{"i":108,"n":"第一百零八条","txt":"省、自治区、直辖市和设区的市、自治州可以结合实际，制定本地方发展医疗卫生与健康事业的具体办法。"},{"i":109,"n":"第一百零九条","txt":"中国人民解放军和中国人民武装警察部队的医疗卫生与健康促进工作，由国务院和中央军事委员会依照本法制定管理办法。"},{"i":110,"n":"第一百一十条","txt":"本法自2020年6月1日起施行。"}],"xueweifa":[{"i":1,"n":"第一条","txt":"为了规范学位授予工作，保护学位申请人的合法权益，保障学位质量，培养担当民族复兴大任的时代新人，建设教育强国、科技强国、人才强国，服务全面建设社会主义现代化国家，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家实行学位制度。学位分为学士、硕士、博士，包括学术学位、专业学位等类型，按照学科门类、专业学位类别等授予。"},{"i":3,"n":"第三条","txt":"学位工作坚持中国共产党的领导，全面贯彻国家的教育方针，践行社会主义核心价值观，落实立德树人根本任务，遵循教育规律，坚持公平、公正、公开，坚持学术自由与学术规范相统一，促进创新发展，提高人才自主培养质量。"},{"i":4,"n":"第四条","txt":"拥护中国共产党的领导、拥护社会主义制度的中国公民，在高等学校、科学研究机构学习或者通过国家规定的其他方式接受教育，达到相应学业要求、学术水平或者专业水平的，可以依照本法规定申请相应学位。"},{"i":5,"n":"第五条","txt":"经审批取得相应学科、专业学位授予资格的高等学校、科学研究机构为学位授予单位，其授予学位的学科、专业为学位授予点。学位授予单位可以依照本法规定授予相应学位。"},{"i":6,"n":"第六条","txt":"国务院设立学位委员会，领导全国学位工作。"},{"i":7,"n":"第七条","txt":"国务院学位委员会在国务院教育行政部门设立办事机构，承担国务院学位委员会日常工作。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市人民政府设立省级学位委员会，在国务院学位委员会的指导下，领导本行政区域学位工作。"},{"i":9,"n":"第九条","txt":"学位授予单位设立学位评定委员会，履行下列职责："},{"i":10,"n":"第十条","txt":"学位评定委员会由学位授予单位具有高级专业技术职务的负责人、教学科研人员组成，其组成人员应当为不少于九人的单数。学位评定委员会主席由学位授予单位主要行政负责人担任。"},{"i":11,"n":"第十一条","txt":"学位评定委员会及分委员会的组成人员、任期、职责分工、工作程序等由学位授予单位确定并公布。"},{"i":12,"n":"第十二条","txt":"高等学校、科学研究机构申请学位授予资格，应当具备下列条件："},{"i":13,"n":"第十三条","txt":"依法实施本科教育且具备本法第十二条规定条件的高等学校，可以申请学士学位授予资格。依法实施本科教育、研究生教育且具备本法第十二条规定条件的高等学校、科学研究机构，可以申请硕士、博士学位授予资格。"},{"i":14,"n":"第十四条","txt":"学士学位授予资格，由省级学位委员会审批，报国务院学位委员会备案。"},{"i":15,"n":"第十五条","txt":"申请学位授予资格，应当在国务院学位委员会、省级学位委员会规定的期限内提出。"},{"i":16,"n":"第十六条","txt":"符合条件的学位授予单位，经国务院学位委员会批准，可以自主开展增设硕士、博士学位授予点审核。自主增设的学位授予点，应当报国务院学位委员会审批。具体条件和办法由国务院学位委员会制定。"},{"i":17,"n":"第十七条","txt":"国家立足经济社会发展对各类人才的需求，优化学科结构和学位授予点布局，加强基础学科、新兴学科、交叉学科建设。"},{"i":18,"n":"第十八条","txt":"学位申请人应当拥护中国共产党的领导，拥护社会主义制度，遵守宪法和法律，遵守学术道德和学术规范。"},{"i":19,"n":"第十九条","txt":"接受本科教育，通过规定的课程考核或者修满相应学分，通过毕业论文或者毕业设计等毕业环节审查，表明学位申请人达到下列水平的，授予学士学位："},{"i":20,"n":"第二十条","txt":"接受硕士研究生教育，通过规定的课程考核或者修满相应学分，完成学术研究训练或者专业实践训练，通过学位论文答辩或者规定的实践成果答辩，表明学位申请人达到下列水平的，授予硕士学位："},{"i":21,"n":"第二十一条","txt":"接受博士研究生教育，通过规定的课程考核或者修满相应学分，完成学术研究训练或者专业实践训练，通过学位论文答辩或者规定的实践成果答辩，表明学位申请人达到下列水平的，授予博士学位："},{"i":22,"n":"第二十二条","txt":"学位授予单位应当根据本法第十八条至第二十一条规定的条件，结合本单位学术评价标准，坚持科学的评价导向，在充分听取相关方面意见的基础上，制定各学科、专业的学位授予具体标准并予以公布。"},{"i":23,"n":"第二十三条","txt":"符合本法规定的受教育者，可以按照学位授予单位的要求提交申请材料，申请相应学位。非学位授予单位的应届毕业生，由毕业单位推荐，可以向相关学位授予单位申请学位。"},{"i":24,"n":"第二十四条","txt":"申请学士学位的，由学位评定委员会组织审查，作出是否授予学士学位的决议。"},{"i":25,"n":"第二十五条","txt":"申请硕士、博士学位的，学位授予单位应当在组织答辩前，将学位申请人的学位论文或者实践成果送专家评阅。"},{"i":26,"n":"第二十六条","txt":"学位授予单位应当按照学科、专业组织硕士、博士学位答辩委员会。硕士学位答辩委员会组成人员应当不少于三人。博士学位答辩委员会组成人员应当不少于五人，其中学位授予单位以外的专家应当不少于二人。"},{"i":27,"n":"第二十七条","txt":"学位论文答辩或者实践成果答辩未通过的，经答辩委员会同意，可以在规定期限内修改，重新申请答辩。"},{"i":28,"n":"第二十八条","txt":"学位评定委员会应当根据答辩委员会的决议，在对学位申请进行审核的基础上，作出是否授予硕士、博士学位的决议。"},{"i":29,"n":"第二十九条","txt":"学位授予单位应当根据学位评定委员会授予学士、硕士、博士学位的决议，公布授予学位的人员名单，颁发学位证书，并向省级学位委员会报送学位授予信息。省级学位委员会将本行政区域的学位授予信息报国务院学位委员会备案。"},{"i":30,"n":"第三十条","txt":"学位授予单位应当保存学位申请人的申请材料和学位论文、实践成果等档案资料；博士学位论文应当同时交存国家图书馆和有关专业图书馆。"},{"i":31,"n":"第三十一条","txt":"学位授予单位应当建立本单位学位质量保障制度，加强招生、培养、学位授予等全过程质量管理，及时公开相关信息，接受社会监督，保证授予学位的质量。"},{"i":32,"n":"第三十二条","txt":"学位授予单位应当为研究生配备品行良好、具有较高学术水平或者较强实践能力的教师、科研人员或者专业人员担任指导教师，建立遴选、考核、监督和动态调整机制。"},{"i":33,"n":"第三十三条","txt":"博士学位授予单位应当立足培养高层次创新人才，加强博士学位授予点建设，加大对博士研究生的培养、管理和支持力度，提高授予博士学位的质量。"},{"i":34,"n":"第三十四条","txt":"国务院教育行政部门和省级学位委员会应当在各自职责范围内定期组织专家对已经批准的学位授予单位及学位授予点进行质量评估。对经质量评估确认不能保证所授学位质量的，责令限期整改；情节严重的，由原审批单位撤销相应学位授予资格。"},{"i":35,"n":"第三十五条","txt":"学位授予单位可以根据本单位学科、专业需要，向原审批单位申请撤销相应学位授予点。"},{"i":36,"n":"第三十六条","txt":"国务院教育行政部门应当加强信息化建设，完善学位信息管理系统，依法向社会提供信息服务。"},{"i":37,"n":"第三十七条","txt":"学位申请人、学位获得者在攻读该学位过程中有下列情形之一的，经学位评定委员会决议，学位授予单位不授予学位或者撤销学位："},{"i":38,"n":"第三十八条","txt":"违反本法规定授予学位、颁发学位证书的，由教育行政部门宣布证书无效，并依照《中华人民共和国教育法》的有关规定处理。"},{"i":39,"n":"第三十九条","txt":"学位授予单位拟作出不授予学位或者撤销学位决定的，应当告知学位申请人或者学位获得者拟作出决定的内容及事实、理由、依据，听取其陈述和申辩。"},{"i":40,"n":"第四十条","txt":"学位申请人对专家评阅、答辩、成果认定等过程中相关学术组织或者人员作出的学术评价结论有异议的，可以向学位授予单位申请学术复核。学位授予单位应当自受理学术复核申请之日起三十日内重新组织专家进行复核并作出复核决定，复核决定为最终决定。学术复核的办法由学位授予单位制定。"},{"i":41,"n":"第四十一条","txt":"学位申请人或者学位获得者对不受理其学位申请、不授予其学位或者撤销其学位等行为不服的，可以向学位授予单位申请复核，或者请求有关机关依照法律规定处理。"},{"i":42,"n":"第四十二条","txt":"军队设立学位委员会。军队学位委员会依据本法负责管理军队院校和科学研究机构的学位工作。"},{"i":43,"n":"第四十三条","txt":"对在学术或者专门领域、在推进科学教育和文化交流合作方面做出突出贡献，或者对世界和平与人类发展有重大贡献的个人，可以授予名誉博士学位。"},{"i":44,"n":"第四十四条","txt":"学位授予单位对申请学位的境外个人，依照本法规定的学业要求、学术水平或者专业水平等条件和相关程序授予相应学位。"},{"i":45,"n":"第四十五条","txt":"本法自2025年1月1日起施行。《中华人民共和国学位条例》同时废止。"}],"xueqianjiaoyufa":[{"i":1,"n":"第一条","txt":"为了保障适龄儿童接受学前教育，规范学前教育实施，促进学前教育普及普惠安全优质发展，提高全民族素质，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内实施学前教育，适用本法。"},{"i":3,"n":"第三条","txt":"国家实行学前教育制度。"},{"i":4,"n":"第四条","txt":"学前教育应当坚持中国共产党的领导，坚持社会主义办学方向，贯彻国家的教育方针。"},{"i":5,"n":"第五条","txt":"国家建立健全学前教育保障机制。"},{"i":6,"n":"第六条","txt":"国家推进普及学前教育，构建覆盖城乡、布局合理、公益普惠、安全优质的学前教育公共服务体系。"},{"i":7,"n":"第七条","txt":"全社会应当为适龄儿童接受学前教育、健康快乐成长创造良好环境。"},{"i":8,"n":"第八条","txt":"国务院领导全国学前教育工作。"},{"i":9,"n":"第九条","txt":"县级以上人民政府教育行政部门负责学前教育管理和业务指导工作，配备相应的管理和教研人员。县级以上人民政府卫生健康行政部门、疾病预防控制部门按照职责分工负责监督指导幼儿园卫生保健工作。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持学前教育、儿童发展、特殊教育方面的科学研究，推广研究成果，宣传、普及科学的教育理念和方法。"},{"i":11,"n":"第十一条","txt":"国家鼓励创作、出版、制作和传播有利于学前儿童健康成长的图书、玩具、音乐作品、音像制品等。"},{"i":12,"n":"第十二条","txt":"对在学前教育工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"学前儿童享有生命安全和身心健康、得到尊重和保护照料、依法平等接受学前教育等权利。"},{"i":14,"n":"第十四条","txt":"实施学前教育应当从学前儿童身心发展特点和利益出发，尊重学前儿童人格尊严，倾听、了解学前儿童的意见，平等对待每一个学前儿童，鼓励、引导学前儿童参与家庭、社会和文化生活，促进学前儿童获得全面发展。"},{"i":15,"n":"第十五条","txt":"地方各级人民政府应当采取措施，推动适龄儿童在其父母或者其他监护人的工作或者居住的地区方便就近接受学前教育。"},{"i":16,"n":"第十六条","txt":"父母或者其他监护人应当依法履行抚养与教育儿童的义务，为适龄儿童接受学前教育提供必要条件。"},{"i":17,"n":"第十七条","txt":"普惠性幼儿园应当接收能够适应幼儿园生活的残疾儿童入园，并为其提供帮助和便利。"},{"i":18,"n":"第十八条","txt":"青少年宫、儿童活动中心、图书馆、博物馆、文化馆、美术馆、科技馆、纪念馆、体育场馆等公共文化服务机构和爱国主义教育基地应当提供适合学前儿童身心发展的公益性教育服务，并按照有关规定对学前儿童免费开放。"},{"i":19,"n":"第十九条","txt":"任何单位和个人不得组织学前儿童参与违背学前儿童身心发展规律或者与年龄特点不符的商业性活动、竞赛类活动和其他活动。"},{"i":20,"n":"第二十条","txt":"面向学前儿童的图书、玩具、音像制品、电子产品、网络教育产品和服务等，应当符合学前儿童身心发展规律和年龄特点。"},{"i":21,"n":"第二十一条","txt":"学前儿童的名誉、隐私和其他合法权益受法律保护，任何单位和个人不得侵犯。"},{"i":22,"n":"第二十二条","txt":"县级以上地方人民政府应当统筹当前和长远，根据人口变化和城镇化发展趋势，科学规划和配置学前教育资源，有效满足需求，避免浪费资源。"},{"i":23,"n":"第二十三条","txt":"各级人民政府应当采取措施，扩大普惠性学前教育资源供给，提高学前教育质量。"},{"i":24,"n":"第二十四条","txt":"各级人民政府应当利用财政性经费或者国有资产等举办或者支持举办公办幼儿园。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府应当以县级行政区划为单位制定幼儿园布局规划，将普惠性幼儿园建设纳入城乡公共管理和公共服务设施统一规划，并按照非营利性教育用地性质依法以划拨等方式供地，不得擅自改变用途。"},{"i":26,"n":"第二十六条","txt":"新建居住区等应当按照幼儿园布局规划等相关规划和标准配套建设幼儿园。配套幼儿园应当与首期建设的居住区同步规划、同步设计、同步建设、同步验收、同步交付使用。建设单位应当按照有关规定将配套幼儿园作为公共服务设施移交地方人民政府，用于举办普惠性幼儿园。"},{"i":27,"n":"第二十七条","txt":"地方各级人民政府应当构建以公办幼儿园为主的农村学前教育公共服务体系，保障农村适龄儿童接受普惠性学前教育。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府应当根据本区域内残疾儿童的数量、分布状况和残疾类别，统筹实施多种形式的学前特殊教育，推进融合教育，推动特殊教育学校和有条件的儿童福利机构、残疾儿童康复机构增设学前部或者附设幼儿园。"},{"i":29,"n":"第二十九条","txt":"设立幼儿园，应当具备下列基本条件："},{"i":30,"n":"第三十条","txt":"设立幼儿园经县级人民政府教育行政部门依法审批、取得办学许可证后，依照有关法律、行政法规的规定进行相应法人登记。"},{"i":31,"n":"第三十一条","txt":"幼儿园变更、终止的，应当按照有关规定提前向县级人民政府教育行政部门报告并向社会公告，依法办理相关手续，妥善安置在园儿童。"},{"i":32,"n":"第三十二条","txt":"学前教育机构中的中国共产党基层组织，按照中国共产党章程开展党的活动，加强党的建设。"},{"i":33,"n":"第三十三条","txt":"幼儿园应当保障教职工依法参与民主管理和监督。"},{"i":34,"n":"第三十四条","txt":"任何单位和个人不得利用财政性经费、国有资产、集体资产或者捐赠资产举办或者参与举办营利性民办幼儿园。"},{"i":35,"n":"第三十五条","txt":"社会资本不得通过兼并收购等方式控制公办幼儿园、非营利性民办幼儿园。"},{"i":36,"n":"第三十六条","txt":"幼儿园教师应当爱护儿童，具备优良品德和专业能力，为人师表，忠诚于人民的教育事业。"},{"i":37,"n":"第三十七条","txt":"担任幼儿园教师应当取得幼儿园教师资格；已取得其他教师资格并经县级以上地方人民政府教育行政部门组织的学前教育专业培训合格的，可以在幼儿园任教。"},{"i":38,"n":"第三十八条","txt":"幼儿园园长由其举办者或者决策机构依法任命或者聘任，并报县级人民政府教育行政部门备案。"},{"i":39,"n":"第三十九条","txt":"保育员应当具有国家规定的学历，并经过幼儿保育职业培训。"},{"i":40,"n":"第四十条","txt":"幼儿园教师职务（职称）分为初级、中级和高级。"},{"i":41,"n":"第四十一条","txt":"国务院教育行政部门会同有关部门制定幼儿园教职工配备标准。地方各级人民政府及有关部门按照相关标准保障公办幼儿园及时补充教师，并应当优先满足农村地区、革命老区、民族地区、边疆地区和欠发达地区公办幼儿园的需要。幼儿园及其举办者应当按照相关标准配足配齐教师和其他工作人员。"},{"i":42,"n":"第四十二条","txt":"幼儿园园长、教师、保育员、卫生保健人员、安全保卫人员和其他工作人员应当遵守法律法规和职业道德规范，尊重、爱护和平等对待学前儿童，不断提高专业素养。"},{"i":43,"n":"第四十三条","txt":"幼儿园应当与教职工依法签订聘用合同或者劳动合同，并将合同信息报县级人民政府教育行政部门备案。"},{"i":44,"n":"第四十四条","txt":"幼儿园聘任（聘用）园长、教师、保育员、卫生保健人员、安全保卫人员和其他工作人员时，应当向教育、公安等有关部门查询应聘者是否具有虐待、性侵害、性骚扰、拐卖、暴力伤害、吸毒、赌博等违法犯罪记录；发现其有前述行为记录，或者有酗酒、严重违反师德师风行为等其他可能危害儿童身心安全情形的，不得聘任（聘用）。"},{"i":45,"n":"第四十五条","txt":"幼儿园应当关注教职工的身体、心理状况。幼儿园园长、教师、保育员、卫生保健人员、安全保卫人员和其他工作人员，应当在入职前和入职后每年进行健康检查。"},{"i":46,"n":"第四十六条","txt":"幼儿园及其举办者应当按照国家规定保障教师和其他工作人员的工资福利，依法缴纳社会保险费，改善工作和生活条件，实行同工同酬。"},{"i":47,"n":"第四十七条","txt":"幼儿园教师在职称评定、岗位聘任（聘用）等方面享有与中小学教师同等的待遇。"},{"i":48,"n":"第四十八条","txt":"国务院教育行政部门应当制定高等学校学前教育专业设置标准、质量保证标准和课程教学标准体系，组织实施学前教育专业质量认证，建立培养质量保障机制。"},{"i":49,"n":"第四十九条","txt":"县级以上人民政府教育、卫生健康等有关部门应当按照职责分工制定幼儿园园长、教师、保育员、卫生保健人员等工作人员培训规划，建立培训支持服务体系，开展多种形式的专业培训。"},{"i":50,"n":"第五十条","txt":"幼儿园应当坚持保育和教育相结合的原则，面向全体学前儿童，关注个体差异，注重良好习惯养成，创造适宜的生活和活动环境，有益于学前儿童身心健康发展。"},{"i":51,"n":"第五十一条","txt":"幼儿园应当把保护学前儿童安全放在首位，对学前儿童在园期间的人身安全负有保护责任。"},{"i":52,"n":"第五十二条","txt":"幼儿园发现学前儿童受到侵害、疑似受到侵害或者面临其他危险情形的，应当立即采取保护措施，并向公安、教育等有关部门报告。"},{"i":53,"n":"第五十三条","txt":"幼儿园应当建立科学合理的一日生活制度，保证户外活动时间，做好儿童营养膳食、体格锻炼、全日健康观察、食品安全、卫生与消毒、传染病预防与控制、常见病预防等卫生保健管理工作，加强健康教育。"},{"i":54,"n":"第五十四条","txt":"招收残疾儿童的幼儿园应当配备必要的康复设施、设备和专业康复人员，或者与其他具有康复设施、设备和专业康复人员的特殊教育机构、康复机构合作，根据残疾儿童实际情况开展保育教育。"},{"i":55,"n":"第五十五条","txt":"国务院教育行政部门制定幼儿园教育指导纲要和学前儿童学习与发展指南，地方各级人民政府教育行政部门依据职责组织实施，加强学前教育教学研究和业务指导。"},{"i":56,"n":"第五十六条","txt":"幼儿园应当以学前儿童的生活为基础，以游戏为基本活动，发展素质教育，最大限度支持学前儿童通过亲近自然、实际操作、亲身体验等方式探索学习，促进学前儿童养成良好的品德、行为习惯、安全和劳动意识，健全人格、强健体魄，在健康、语言、社会、科学、艺术等各方面协调发展。"},{"i":57,"n":"第五十七条","txt":"幼儿园应当配备符合相关标准的玩教具和幼儿图书。"},{"i":58,"n":"第五十八条","txt":"幼儿园应当主动与父母或者其他监护人交流学前儿童身心发展状况，指导家庭科学育儿。"},{"i":59,"n":"第五十九条","txt":"幼儿园与小学应当互相衔接配合，共同帮助儿童做好入学准备和入学适应。"},{"i":60,"n":"第六十条","txt":"学前教育实行政府投入为主、家庭合理负担保育教育成本、多渠道筹措经费的投入机制。"},{"i":61,"n":"第六十一条","txt":"学前教育财政补助经费按照中央与地方财政事权和支出责任划分原则，分别列入中央和地方各级预算。中央财政通过转移支付对地方统筹给予支持。省级人民政府应当建立本行政区域内各级人民政府财政补助经费分担机制。"},{"i":62,"n":"第六十二条","txt":"国务院和省级人民政府统筹安排学前教育资金，重点扶持农村地区、革命老区、民族地区、边疆地区和欠发达地区发展学前教育。"},{"i":63,"n":"第六十三条","txt":"地方各级人民政府应当科学核定普惠性幼儿园办园成本，以提供普惠性学前教育服务为衡量标准，统筹制定财政补助和收费政策，合理确定分担比例。"},{"i":64,"n":"第六十四条","txt":"地方各级人民政府应当通过财政补助、购买服务、减免租金、培训教师、教研指导等多种方式，支持普惠性民办幼儿园发展。"},{"i":65,"n":"第六十五条","txt":"国家建立学前教育资助制度，为家庭经济困难的适龄儿童等接受普惠性学前教育提供资助。"},{"i":66,"n":"第六十六条","txt":"国家鼓励自然人、法人和非法人组织通过捐赠、志愿服务等方式支持学前教育事业。"},{"i":67,"n":"第六十七条","txt":"县级以上人民政府及其有关部门应当建立健全幼儿园安全风险防控体系，强化幼儿园周边治安管理和巡逻防控工作，加强对幼儿园安全保卫的监督指导，督促幼儿园加强安全防范建设，及时排查和消除安全隐患，依法保障学前儿童与幼儿园安全。"},{"i":68,"n":"第六十八条","txt":"省级人民政府或者其授权的设区的市级人民政府根据办园成本、经济发展水平和群众承受能力等因素，合理确定公办幼儿园和非营利性民办幼儿园的收费标准，并建立定期调整机制。"},{"i":69,"n":"第六十九条","txt":"幼儿园收取的费用应当主要用于保育和教育活动、保障教职工待遇、促进教职工发展和改善办园条件。学前儿童伙食费应当专款专用。"},{"i":70,"n":"第七十条","txt":"幼儿园应当依法建立健全财务、会计及资产管理制度，严格经费管理，合理使用经费，提高经费使用效益。"},{"i":71,"n":"第七十一条","txt":"县级以上人民政府及其有关部门应当建立健全学前教育经费预算管理和审计监督制度。"},{"i":72,"n":"第七十二条","txt":"县级人民政府教育行政部门应当建立健全各类幼儿园基本信息备案及公示制度，利用互联网等方式定期向社会公布并更新政府学前教育财政投入、幼儿园规划举办等方面信息，以及各类幼儿园的教师和其他工作人员的资质和配备、招生、经费收支、收费标准、保育教育质量等方面信息。"},{"i":73,"n":"第七十三条","txt":"县级以上人民政府教育督导机构对学前教育工作执行法律法规情况、保育教育工作等进行督导。督导报告应当定期向社会公开。"},{"i":74,"n":"第七十四条","txt":"国务院教育行政部门制定幼儿园保育教育质量评估指南。省级人民政府教育行政部门应当完善幼儿园质量评估标准，健全幼儿园质量评估监测体系，将各类幼儿园纳入质量评估范畴，并向社会公布评估结果。"},{"i":75,"n":"第七十五条","txt":"地方各级人民政府及有关部门有下列情形之一的，由上级机关或者有关部门按照职责分工责令限期改正；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分："},{"i":76,"n":"第七十六条","txt":"地方各级人民政府及教育等有关部门的工作人员违反本法规定，滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":77,"n":"第七十七条","txt":"居住区建设单位未按照规定建设、移交配套幼儿园，或者改变配套幼儿园土地用途的，由县级以上地方人民政府自然资源、住房和城乡建设、教育等有关部门按照职责分工责令限期改正，依法给予处罚。"},{"i":78,"n":"第七十八条","txt":"擅自举办幼儿园或者招收学前儿童实施半日制、全日制培训的，由县级人民政府教育等有关部门依照《中华人民共和国教育法》、《中华人民共和国民办教育促进法》的规定予以处理；对非法举办幼儿园的单位和个人，根据情节轻重，五至十年内不受理其举办幼儿园或者其他教育机构的申请。"},{"i":79,"n":"第七十九条","txt":"幼儿园有下列情形之一的，由县级以上地方人民政府教育等有关部门按照职责分工责令限期改正，并予以警告；有违法所得的，退还所收费用后没收违法所得；情节严重的，责令停止招生、吊销办学许可证："},{"i":80,"n":"第八十条","txt":"幼儿园教师或者其他工作人员有下列情形之一的，由所在幼儿园或者县级人民政府教育等有关部门根据情节轻重，依法给予当事人、幼儿园负责人处分，解除聘用合同或者劳动合同；由县级人民政府教育行政部门禁止其一定期限内直至终身从事学前教育工作或者举办幼儿园；情节严重的，吊销其资格证书："},{"i":81,"n":"第八十一条","txt":"在学前教育活动中违反本法规定的行为，本法未规定法律责任，《中华人民共和国教育法》、《中华人民共和国未成年人保护法》、《中华人民共和国劳动法》等法律、行政法规有规定的，依照其规定。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，侵害学前儿童、幼儿园、教职工合法权益，造成人身损害或者财产损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":83,"n":"第八十三条","txt":"小学、特殊教育学校、儿童福利机构、残疾儿童康复机构等附设的幼儿班等学前教育机构适用本法有关规定。"},{"i":84,"n":"第八十四条","txt":"鼓励有条件的幼儿园开设托班，提供托育服务。"},{"i":85,"n":"第八十五条","txt":"本法自2025年6月1日起施行。"}],"mimafa":[{"i":1,"n":"第一条","txt":"为了规范密码应用和管理，促进密码事业发展，保障网络与信息安全，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称密码，是指采用特定变换的方法对信息等进行加密保护、安全认证的技术、产品和服务。"},{"i":3,"n":"第三条","txt":"密码工作坚持总体国家安全观，遵循统一领导、分级负责，创新发展、服务大局，依法管理、保障安全的原则。"},{"i":4,"n":"第四条","txt":"坚持中国共产党对密码工作的领导。中央密码工作领导机构对全国密码工作实行统一领导，制定国家密码工作重大方针政策，统筹协调国家密码重大事项和重要工作，推进国家密码法治建设。"},{"i":5,"n":"第五条","txt":"国家密码管理部门负责管理全国的密码工作。县级以上地方各级密码管理部门负责管理本行政区域的密码工作。"},{"i":6,"n":"第六条","txt":"国家对密码实行分类管理。"},{"i":7,"n":"第七条","txt":"核心密码、普通密码用于保护国家秘密信息，核心密码保护信息的最高密级为绝密级，普通密码保护信息的最高密级为机密级。"},{"i":8,"n":"第八条","txt":"商用密码用于保护不属于国家秘密的信息。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持密码科学技术研究和应用，依法保护密码领域的知识产权，促进密码科学技术进步和创新。"},{"i":10,"n":"第十条","txt":"国家采取多种形式加强密码安全教育，将密码安全教育纳入国民教育体系和公务员教育培训体系，增强公民、法人和其他组织的密码安全意识。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府应当将密码工作纳入本级国民经济和社会发展规划，所需经费列入本级财政预算。"},{"i":12,"n":"第十二条","txt":"任何组织或者个人不得窃取他人加密保护的信息或者非法侵入他人的密码保障系统。"},{"i":13,"n":"第十三条","txt":"国家加强核心密码、普通密码的科学规划、管理和使用，加强制度建设，完善管理措施，增强密码安全保障能力。"},{"i":14,"n":"第十四条","txt":"在有线、无线通信中传递的国家秘密信息，以及存储、处理国家秘密信息的信息系统，应当依照法律、行政法规和国家有关规定使用核心密码、普通密码进行加密保护、安全认证。"},{"i":15,"n":"第十五条","txt":"从事核心密码、普通密码科研、生产、服务、检测、装备、使用和销毁等工作的机构（以下统称密码工作机构）应当按照法律、行政法规、国家有关规定以及核心密码、普通密码标准的要求，建立健全安全管理制度，采取严格的保密措施和保密责任制，确保核心密码、普通密码的安全。"},{"i":16,"n":"第十六条","txt":"密码管理部门依法对密码工作机构的核心密码、普通密码工作进行指导、监督和检查，密码工作机构应当配合。"},{"i":17,"n":"第十七条","txt":"密码管理部门根据工作需要会同有关部门建立核心密码、普通密码的安全监测预警、安全风险评估、信息通报、重大事项会商和应急处置等协作机制，确保核心密码、普通密码安全管理的协同联动和有序高效。"},{"i":18,"n":"第十八条","txt":"国家加强密码工作机构建设，保障其履行工作职责。"},{"i":19,"n":"第十九条","txt":"密码管理部门因工作需要，按照国家有关规定，可以提请公安、交通运输、海关等部门对核心密码、普通密码有关物品和人员提供免检等便利，有关部门应当予以协助。"},{"i":20,"n":"第二十条","txt":"密码管理部门和密码工作机构应当建立健全严格的监督和安全审查制度，对其工作人员遵守法律和纪律等情况进行监督，并依法采取必要措施，定期或者不定期组织开展安全审查。"},{"i":21,"n":"第二十一条","txt":"国家鼓励商用密码技术的研究开发、学术交流、成果转化和推广应用，健全统一、开放、竞争、有序的商用密码市场体系，鼓励和促进商用密码产业发展。"},{"i":22,"n":"第二十二条","txt":"国家建立和完善商用密码标准体系。"},{"i":23,"n":"第二十三条","txt":"国家推动参与商用密码国际标准化活动，参与制定商用密码国际标准，推进商用密码中国标准与国外标准之间的转化运用。"},{"i":24,"n":"第二十四条","txt":"商用密码从业单位开展商用密码活动，应当符合有关法律、行政法规、商用密码强制性国家标准以及该从业单位公开标准的技术要求。"},{"i":25,"n":"第二十五条","txt":"国家推进商用密码检测认证体系建设，制定商用密码检测认证技术规范、规则，鼓励商用密码从业单位自愿接受商用密码检测认证，提升市场竞争力。"},{"i":26,"n":"第二十六条","txt":"涉及国家安全、国计民生、社会公共利益的商用密码产品，应当依法列入网络关键设备和网络安全专用产品目录，由具备资格的机构检测认证合格后，方可销售或者提供。商用密码产品检测认证适用《中华人民共和国网络安全法》的有关规定，避免重复检测认证。"},{"i":27,"n":"第二十七条","txt":"法律、行政法规和国家有关规定要求使用商用密码进行保护的关键信息基础设施，其运营者应当使用商用密码进行保护，自行或者委托商用密码检测机构开展商用密码应用安全性评估。商用密码应用安全性评估应当与关键信息基础设施安全检测评估、网络安全等级测评制度相衔接，避免重复评估、测评。"},{"i":28,"n":"第二十八条","txt":"国务院商务主管部门、国家密码管理部门依法对涉及国家安全、社会公共利益且具有加密保护功能的商用密码实施进口许可，对涉及国家安全、社会公共利益或者中国承担国际义务的商用密码实施出口管制。商用密码进口许可清单和出口管制清单由国务院商务主管部门会同国家密码管理部门和海关总署制定并公布。"},{"i":29,"n":"第二十九条","txt":"国家密码管理部门对采用商用密码技术从事电子政务电子认证服务的机构进行认定，会同有关部门负责政务活动中使用电子签名、数据电文的管理。"},{"i":30,"n":"第三十条","txt":"商用密码领域的行业协会等组织依照法律、行政法规及其章程的规定，为商用密码从业单位提供信息、技术、培训等服务，引导和督促商用密码从业单位依法开展商用密码活动，加强行业自律，推动行业诚信建设，促进行业健康发展。"},{"i":31,"n":"第三十一条","txt":"密码管理部门和有关部门建立日常监管和随机抽查相结合的商用密码事中事后监管制度，建立统一的商用密码监督管理信息平台，推进事中事后监管与社会信用体系相衔接，强化商用密码从业单位自律和社会监督。"},{"i":32,"n":"第三十二条","txt":"违反本法第十二条规定，窃取他人加密保护的信息，非法侵入他人的密码保障系统，或者利用密码从事危害国家安全、社会公共利益、他人合法权益等违法活动的，由有关部门依照《中华人民共和国网络安全法》和其他有关法律、行政法规的规定追究法律责任。"},{"i":33,"n":"第三十三条","txt":"违反本法第十四条规定，未按照要求使用核心密码、普通密码的，由密码管理部门责令改正或者停止违法行为，给予警告；情节严重的，由密码管理部门建议有关国家机关、单位对直接负责的主管人员和其他直接责任人员依法给予处分或者处理。"},{"i":34,"n":"第三十四条","txt":"违反本法规定，发生核心密码、普通密码泄密案件的，由保密行政管理部门、密码管理部门建议有关国家机关、单位对直接负责的主管人员和其他直接责任人员依法给予处分或者处理。"},{"i":35,"n":"第三十五条","txt":"商用密码检测、认证机构违反本法第二十五条第二款、第三款规定开展商用密码检测认证的，由市场监督管理部门会同密码管理部门责令改正或者停止违法行为，给予警告，没收违法所得；违法所得三十万元以上的，可以并处违法所得一倍以上三倍以下罚款；没有违法所得或者违法所得不足三十万元的，可以并处十万元以上三十万元以下罚款；情节严重的，依法吊销相关资质。"},{"i":36,"n":"第三十六条","txt":"违反本法第二十六条规定，销售或者提供未经检测认证或者检测认证不合格的商用密码产品，或者提供未经认证或者认证不合格的商用密码服务的，由市场监督管理部门会同密码管理部门责令改正或者停止违法行为，给予警告，没收违法产品和违法所得；违法所得十万元以上的，可以并处违法所得一倍以上三倍以下罚款；没有违法所得或者违法所得不足十万元的，可以并处三万元以上十万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"关键信息基础设施的运营者违反本法第二十七条第一款规定，未按照要求使用商用密码，或者未按照要求开展商用密码应用安全性评估的，由密码管理部门责令改正，给予警告；拒不改正或者导致危害网络安全等后果的，处十万元以上一百万元以下罚款，对直接负责的主管人员处一万元以上十万元以下罚款。"},{"i":38,"n":"第三十八条","txt":"违反本法第二十八条实施进口许可、出口管制的规定，进出口商用密码的，由国务院商务主管部门或者海关依法予以处罚。"},{"i":39,"n":"第三十九条","txt":"违反本法第二十九条规定，未经认定从事电子政务电子认证服务的，由密码管理部门责令改正或者停止违法行为，给予警告，没收违法产品和违法所得；违法所得三十万元以上的，可以并处违法所得一倍以上三倍以下罚款；没有违法所得或者违法所得不足三十万元的，可以并处十万元以上三十万元以下罚款。"},{"i":40,"n":"第四十条","txt":"密码管理部门和有关部门、单位的工作人员在密码工作中滥用职权、玩忽职守、徇私舞弊，或者泄露、非法向他人提供在履行职责中知悉的商业秘密和个人隐私的，依法给予处分。"},{"i":41,"n":"第四十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任；给他人造成损害的，依法承担民事责任。"},{"i":42,"n":"第四十二条","txt":"国家密码管理部门依照法律、行政法规的规定，制定密码管理规章。"},{"i":43,"n":"第四十三条","txt":"中国人民解放军和中国人民武装警察部队的密码工作管理办法，由中央军事委员会根据本法制定。"},{"i":44,"n":"第四十四条","txt":"本法自2020年1月1日起施行。"}],"juminshenfenzhengfa":[{"i":1,"n":"第一条","txt":"为了证明居住在中华人民共和国境内的公民的身份，保障公民的合法权益，便利公民进行社会活动，维护社会秩序，制定本法。"},{"i":2,"n":"第二条","txt":"居住在中华人民共和国境内的年满十六周岁的中国公民，应当依照本法的规定申请领取居民身份证；未满十六周岁的中国公民，可以依照本法的规定申请领取居民身份证。"},{"i":3,"n":"第三条","txt":"居民身份证登记的项目包括：姓名、性别、民族、出生日期、常住户口所在地住址、公民身份号码、本人相片、指纹信息、证件的有效期和签发机关。"},{"i":4,"n":"第四条","txt":"居民身份证使用规范汉字和符合国家标准的数字符号填写。"},{"i":5,"n":"第五条","txt":"十六周岁以上公民的居民身份证的有效期为十年、二十年、长期。十六周岁至二十五周岁的，发给有效期十年的居民身份证；二十六周岁至四十五周岁的，发给有效期二十年的居民身份证；四十六周岁以上的，发给长期有效的居民身份证。"},{"i":6,"n":"第六条","txt":"居民身份证式样由国务院公安部门制定。居民身份证由公安机关统一制作、发放。"},{"i":7,"n":"第七条","txt":"公民应当自年满十六周岁之日起三个月内，向常住户口所在地的公安机关申请领取居民身份证。"},{"i":8,"n":"第八条","txt":"居民身份证由居民常住户口所在地的县级人民政府公安机关签发。"},{"i":9,"n":"第九条","txt":"香港同胞、澳门同胞、台湾同胞迁入内地定居的，华侨回国定居的，以及外国人、无国籍人在中华人民共和国境内定居并被批准加入或者恢复中华人民共和国国籍的，在办理常住户口登记时，应当依照本法规定申请领取居民身份证。"},{"i":10,"n":"第十条","txt":"申请领取居民身份证，应当填写《居民身份证申领登记表》，交验居民户口簿。"},{"i":11,"n":"第十一条","txt":"国家决定换发新一代居民身份证、居民身份证有效期满、公民姓名变更或者证件严重损坏不能辨认的，公民应当换领新证；居民身份证登记项目出现错误的，公安机关应当及时更正，换发新证；领取新证时，必须交回原证。居民身份证丢失的，应当申请补领。"},{"i":12,"n":"第十二条","txt":"公民申请领取、换领、补领居民身份证，公安机关应当按照规定及时予以办理。公安机关应当自公民提交《居民身份证申领登记表》之日起六十日内发放居民身份证；交通不便的地区，办理时间可以适当延长，但延长的时间不得超过三十日。"},{"i":13,"n":"第十三条","txt":"公民从事有关活动，需要证明身份的，有权使用"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，公民应当出示居民身份证证明身份："},{"i":15,"n":"第十五条","txt":"人民警察依法执行职务，遇有下列情形之一的，经出示执法证件，可以查验居民身份证："},{"i":16,"n":"第十六条","txt":"有下列行为之一的，由公安机关给予警告，并处二百元以下罚款，有违法所得的，没收违法所得："},{"i":17,"n":"第十七条","txt":"有下列行为之一的，由公安机关处二百元以上一千元以下罚款，或者处十日以下拘留，有违法所得的，没收违法所得："},{"i":18,"n":"第十八条","txt":"伪造、变造居民身份证的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"国家机关或者金融、电信、交通、教育、医疗等单位的工作人员泄露在履行职责或者提供服务过程中获得的居民身份证记载的公民个人信息，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关处十日以上十五日以下拘留，并处五千元罚款，有违法所得的，没收违法所得。"},{"i":20,"n":"第二十条","txt":"人民警察有下列行为之一的，根据情节轻重，依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":21,"n":"第二十一条","txt":"公民申请领取、换领、补领居民身份证，应当缴纳证件工本费。居民身份证工本费标准，由国务院价格主管部门会同国务院财政部门核定。"},{"i":22,"n":"第二十二条","txt":"现役的人民解放军军人、人民武装警察申请领取和发放居民身份证的具体办法，由国务院和中央军事委员会另行规定。"},{"i":23,"n":"第二十三条","txt":"本法自2004年1月1日起施行，《中华人民共和国居民身份证条例》同时废止。"}],"lvshifa":[{"i":1,"n":"第一条","txt":"为了完善律师制度，规范律师执业行为，保障律师依法执业，发挥律师在社会主义法制建设中的作用，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称律师，是指依法取得律师执业证书，接受委托或者指定，为当事人提供法律服务的执业人员。"},{"i":3,"n":"第三条","txt":"律师执业必须遵守宪法和法律，恪守律师职业道德和执业纪律。"},{"i":4,"n":"第四条","txt":"司法行政部门依照本法对律师、律师事务所和律师协会进行监督、指导。"},{"i":5,"n":"第五条","txt":"申请律师执业，应当具备下列条件："},{"i":6,"n":"第六条","txt":"申请律师执业，应当向设区的市级或者直辖市的区人民政府司法行政部门提出申请，并提交下列材料："},{"i":7,"n":"第七条","txt":"申请人有下列情形之一的，不予颁发律师执业证书："},{"i":8,"n":"第八条","txt":"具有高等院校本科以上学历，在法律服务人员紧缺领域从事专业工作满十五年，具有高级职称或者同等专业水平并具有相应的专业法律知识的人员，申请专职律师执业的，经国务院司法行政部门考核合格，准予执业。具体办法由国务院规定。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，由省、自治区、直辖市人民政府司法行政部门撤销准予执业的决定，并注销被准予执业人员的律师执业证书："},{"i":10,"n":"第十条","txt":"律师只能在一个律师事务所执业。律师变更执业机构的，应当申请换发律师执业证书。"},{"i":11,"n":"第十一条","txt":"公务员不得兼任执业律师。"},{"i":12,"n":"第十二条","txt":"高等院校、科研机构中从事法学教育、研究工作的人员，符合本法第五条规定条件的，经所在单位同意，依照本法第六条规定的程序，可以申请兼职律师执业。"},{"i":13,"n":"第十三条","txt":"没有取得律师执业证书的人员，不得以律师名义从事法律服务业务；除法律另有规定外，不得从事诉讼代理或者辩护业务。"},{"i":14,"n":"第十四条","txt":"律师事务所是律师的执业机构。设立律师事务所应当具备下列条件："},{"i":15,"n":"第十五条","txt":"设立合伙律师事务所，除应当符合本法第十四条规定的条件外，还应当有三名以上合伙人，设立人应当是具有三年以上执业经历的律师。"},{"i":16,"n":"第十六条","txt":"设立个人律师事务所，除应当符合本法第十四条规定的条件外，设立人还应当是具有五年以上执业经历的律师。设立人对律师事务所的债务承担无限责任。"},{"i":17,"n":"第十七条","txt":"申请设立律师事务所，应当提交下列材料："},{"i":18,"n":"第十八条","txt":"设立律师事务所，应当向设区的市级或者直辖市的区人民政府司法行政部门提出申请，受理申请的部门应当自受理之日起二十日内予以审查，并将审查意见和全部申请材料报送省、自治区、直辖市人民政府司法行政部门。省、自治区、直辖市人民政府司法行政部门应当自收到报送材料之日起十日内予以审核，作出是否准予设立的决定。准予设立的，向申请人颁发律师事务所执业证书；不准予设立的，向申请人书面说明理由。"},{"i":19,"n":"第十九条","txt":"成立三年以上并具有二十名以上执业律师的合伙律师事务所，可以设立分所。设立分所，须经拟设立分所所在地的省、自治区、直辖市人民政府司法行政部门审核。申请设立分所的，依照本法第十八条规定的程序办理。"},{"i":20,"n":"第二十条","txt":"国家出资设立的律师事务所，依法自主开展律师业务，以该律师事务所的全部资产对其债务承担责任。"},{"i":21,"n":"第二十一条","txt":"律师事务所变更名称、负责人、章程、合伙协议的，应当报原审核部门批准。"},{"i":22,"n":"第二十二条","txt":"律师事务所有下列情形之一的，应当终止："},{"i":23,"n":"第二十三条","txt":"律师事务所应当建立健全执业管理、利益冲突审查、收费与财务管理、投诉查处、年度考核、档案管理等制度，对律师在执业活动中遵守职业道德、执业纪律的情况进行监督。"},{"i":24,"n":"第二十四条","txt":"律师事务所应当于每年的年度考核后，向设区的市级或者直辖市的区人民政府司法行政部门提交本所的年度执业情况报告和律师执业考核结果。"},{"i":25,"n":"第二十五条","txt":"律师承办业务，由律师事务所统一接受委托，与委托人签订书面委托合同，按照国家规定统一收取费用并如实入账。"},{"i":26,"n":"第二十六条","txt":"律师事务所和律师不得以诋毁其他律师事务所、律师或者支付介绍费等不正当手段承揽业务。"},{"i":27,"n":"第二十七条","txt":"律师事务所不得从事法律服务以外的经营活动。"},{"i":28,"n":"第二十八条","txt":"律师可以从事下列业务："},{"i":29,"n":"第二十九条","txt":"律师担任法律顾问的，应当按照约定为委托人就有关法律问题提供意见，草拟、审查法律文书，代理参加诉讼、调解或者仲裁活动，办理委托的其他法律事务，维护委托人的合法权益。"},{"i":30,"n":"第三十条","txt":"律师担任诉讼法律事务代理人或者非诉讼法律事务代理人的，应当在受委托的权限内，维护委托人的合法权益。"},{"i":31,"n":"第三十一条","txt":"律师担任辩护人的，应当根据事实和法律，提出犯罪嫌疑人、被告人无罪、罪轻或者减轻、免除其刑事责任的材料和意见，维护犯罪嫌疑人、被告人的诉讼权利和其他合法权益。"},{"i":32,"n":"第三十二条","txt":"委托人可以拒绝已委托的律师为其继续辩护或者代理，同时可以另行委托律师担任辩护人或者代理人。"},{"i":33,"n":"第三十三条","txt":"律师担任辩护人的，有权持律师执业证书、律师事务所证明和委托书或者法律援助公函，依照刑事诉讼法的规定会见在押或者被监视居住的犯罪嫌疑人、被告人。辩护律师会见犯罪嫌疑人、被告人时不被监听。"},{"i":34,"n":"第三十四条","txt":"律师担任辩护人的，自人民检察院对案件审查起诉之日起，有权查阅、摘抄、复制本案的案卷材料。"},{"i":35,"n":"第三十五条","txt":"受委托的律师根据案情的需要，可以申请人民检察院、人民法院收集、调取证据或者申请人民法院通知证人出庭作证。"},{"i":36,"n":"第三十六条","txt":"律师担任诉讼代理人或者辩护人的，其辩论或者辩护的权利依法受到保障。"},{"i":37,"n":"第三十七条","txt":"律师在执业活动中的人身权利不受侵犯。"},{"i":38,"n":"第三十八条","txt":"律师应当保守在执业活动中知悉的国家秘密、商业秘密，不得泄露当事人的隐私。"},{"i":39,"n":"第三十九条","txt":"律师不得在同一案件中为双方当事人担任代理人，不得代理与本人或者其近亲属有利益冲突的法律事务。"},{"i":40,"n":"第四十条","txt":"律师在执业活动中不得有下列行为："},{"i":41,"n":"第四十一条","txt":"曾经担任法官、检察官的律师，从人民法院、人民检察院离任后二年内，不得担任诉讼代理人或者辩护人。"},{"i":42,"n":"第四十二条","txt":"律师、律师事务所应当按照国家规定履行法律援助义务，为受援人提供符合标准的法律服务，维护受援人的合法权益。"},{"i":43,"n":"第四十三条","txt":"律师协会是社会团体法人，是律师的自律性组织。"},{"i":44,"n":"第四十四条","txt":"全国律师协会章程由全国会员代表大会制定，报国务院司法行政部门备案。"},{"i":45,"n":"第四十五条","txt":"律师、律师事务所应当加入所在地的地方律师协会。加入地方律师协会的律师、律师事务所，同时是全国律师协会的会员。"},{"i":46,"n":"第四十六条","txt":"律师协会应当履行下列职责："},{"i":47,"n":"第四十七条","txt":"律师有下列行为之一的，由设区的市级或者直辖市的区人民政府司法行政部门给予警告，可以处五千元以下的罚款；有违法所得的，没收违法所得；情节严重的，给予停止执业三个月以下的处罚："},{"i":48,"n":"第四十八条","txt":"律师有下列行为之一的，由设区的市级或者直辖市的区人民政府司法行政部门给予警告，可以处一万元以下的罚款；有违法所得的，没收违法所得；情节严重的，给予停止执业三个月以上六个月以下的处罚："},{"i":49,"n":"第四十九条","txt":"律师有下列行为之一的，由设区的市级或者直辖市的区人民政府司法行政部门给予停止执业六个月以上一年以下的处罚，可以处五万元以下的罚款；有违法所得的，没收违法所得；情节严重的，由省、自治区、直辖市人民政府司法行政部门吊销其律师执业证书；构成犯罪的，依法追究刑事责任："},{"i":50,"n":"第五十条","txt":"律师事务所有下列行为之一的，由设区的市级或者直辖市的区人民政府司法行政部门视其情节给予警告、停业整顿一个月以上六个月以下的处罚，可以处十万元以下的罚款；有违法所得的，没收违法所得；情节特别严重的，由省、自治区、直辖市人民政府司法行政部门吊销律师事务所执业证书："},{"i":51,"n":"第五十一条","txt":"律师因违反本法规定，在受到警告处罚后一年内又发生应当给予警告处罚情形的，由设区的市级或者直辖市的区人民政府司法行政部门给予停止执业三个月以上一年以下的处罚；在受到停止执业处罚期满后二年内又发生应当给予停止执业处罚情形的，由省、自治区、直辖市人民政府司法行政部门吊销其律师执业证书。"},{"i":52,"n":"第五十二条","txt":"县级人民政府司法行政部门对律师和律师事务所的执业活动实施日常监督管理，对检查发现的问题，责令改正；对当事人的投诉，应当及时进行调查。县级人民政府司法行政部门认为律师和律师事务所的违法行为应当给予行政处罚的，应当向上级司法行政部门提出处罚建议。"},{"i":53,"n":"第五十三条","txt":"受到六个月以上停止执业处罚的律师，处罚期满未逾三年的，不得担任合伙人。"},{"i":54,"n":"第五十四条","txt":"律师违法执业或者因过错给当事人造成损失的，由其所在的律师事务所承担赔偿责任。律师事务所赔偿后，可以向有故意或者重大过失行为的律师追偿。"},{"i":55,"n":"第五十五条","txt":"没有取得律师执业证书的人员以律师名义从事法律服务业务的，由所在地的县级以上地方人民政府司法行政部门责令停止非法执业，没收违法所得，处违法所得一倍以上五倍以下的罚款。"},{"i":56,"n":"第五十六条","txt":"司法行政部门工作人员违反本法规定，滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":57,"n":"第五十七条","txt":"为军队提供法律服务的军队律师，其律师资格的取得和权利、义务及行为准则，适用本法规定。军队律师的具体管理办法，由国务院和中央军事委员会制定。"},{"i":58,"n":"第五十八条","txt":"外国律师事务所在中华人民共和国境内设立机构从事法律服务活动的管理办法，由国务院制定。"},{"i":59,"n":"第五十九条","txt":"律师收费办法，由国务院价格主管部门会同国务院司法行政部门制定。"},{"i":60,"n":"第六十条","txt":"本法自2008年6月1日起施行。"}],"hukoudengjitiaoli":[{"i":1,"n":"第一条","txt":"为了维持社会秩序，保护公民的权利和利益，服务于社会主义建设，制定本条例。"},{"i":2,"n":"第二条","txt":"中华人民共和国公民，都应当依照本条例的规定履行户口登记。"},{"i":3,"n":"第三条","txt":"户口登记工作，由各级公安机关主管。"},{"i":4,"n":"第四条","txt":"户口登记机关应当设立户口登记簿。"},{"i":5,"n":"第五条","txt":"户口登记以户为单位。同主管人共同居住一处的立为一户，以主管人为户主。单身居住的自立一户，以本人为户主。居住在机关、团体、学校、企业、事业等单位内部和公共宿舍的户口共立一户或者分别立户。户主负责按照本条例的规定申报户口登记。"},{"i":6,"n":"第六条","txt":"公民应当在经常居住的地方登记为常住人口，一个公民只能在一个地方登记为常住人口。"},{"i":7,"n":"第七条","txt":"婴儿出生后一个月以内，由户主、亲属、抚养人或者邻居向婴儿常住地户口登记机关申报出生登记。"},{"i":8,"n":"第八条","txt":"公民死亡，城市在葬前，农村在一个月以内，由户主、亲属、抚养人或者邻居向户口登记机关申报死亡登记，注销户口。公民如果在暂住地死亡，由暂住地户口登记机关通知常住地户口登记机关注销户口。"},{"i":9,"n":"第九条","txt":"婴儿出生后，在申报出生登记前死亡的，应当同时申报出生、死亡两项登记。"},{"i":10,"n":"第十条","txt":"公民迁出本户口管辖区，由本人或者户主在迁出前向户口登记机关申报迁出登记，领取迁移证件，注销户口。"},{"i":11,"n":"第十一条","txt":"被征集服现役的公民，在入伍前，由本人或者户主持应征公民入伍通知书向常住地户口登记机关申报迁出登记，注销户口，不发迁移证件。"},{"i":12,"n":"第十二条","txt":"被逮捕的人犯，由逮捕机关在通知人犯家属的同时，通知人犯常住地户口登记机关注销户口。"},{"i":13,"n":"第十三条","txt":"公民迁移，从到达迁入地的时候起，城市在三日以内，农村在十日以内，由本人或者户主持迁移证件向户口登记机关申报迁入登记，缴销迁移证件。"},{"i":14,"n":"第十四条","txt":"被假释、缓刑的犯人，被管制分子和其他依法被剥夺政治权利的人，在迁移的时候，必须经过户口登记机关转报县、市、市辖区人民法院或者公安机关批准，才可以办理迁出登记；到达迁入地后，应当立即向户口登记机关申报迁入登记。"},{"i":15,"n":"第十五条","txt":"公民在常住地市、县范围以外的城市暂住三日以上的，由暂住地的户主或者本人在三日以内向户口登记机关申报暂住登记，离开前申报注销；暂住在旅店的，由旅店设置旅客登记簿随时登记。"},{"i":16,"n":"第十六条","txt":"公民因私事离开常住地外出、暂住的时间超过三个月的，应当向户口登记机关申请延长时间或者办理迁移手续；既无理由延长时间又无迁移条件的，应当返回常住地。"},{"i":17,"n":"第十七条","txt":"户口登记的内容需要变更或者更正的时候，由户主或者本人向户口登记机关申报；户口登记机关审查属实后予以变更或者更正。"},{"i":18,"n":"第十八条","txt":"公民变更姓名，依照下列规定办理："},{"i":19,"n":"第十九条","txt":"公民因结婚、离婚、收养、认领、分户、并户、失踪、寻回或者其他事由引起户口变动的时候，由户主或者本人向户口登记机关申报变更登记。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，根据情节轻重，依法给予治安管理处罚或者追究刑事责任："},{"i":21,"n":"第二十一条","txt":"户口登记机关在户口登记工作中，如果发现有反革命分子和其他犯罪分子，应当提请司法机关依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"户口簿、册、表格、证件，由中华人民共和国公安部统一制定式样，由省、自治区、直辖市公安机关统筹印制。"},{"i":23,"n":"第二十三条","txt":"民族自治地方的自治机关可以根据本条例的精神，结合当地具体情况，制定单行办法。"},{"i":24,"n":"第二十四条","txt":"本条例自公布之日起施行。"}],"huzhaofa":[{"i":1,"n":"第一条","txt":"为了规范中华人民共和国护照的申请、签发和管理，保障中华人民共和国公民出入中华人民共和国国境的权益，促进对外交往，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国护照是中华人民共和国公民出入国境和在国外证明国籍和身份的证件。"},{"i":3,"n":"第三条","txt":"护照分为普通护照、外交护照和公务护照。"},{"i":4,"n":"第四条","txt":"普通护照由公安部出入境管理机构或者公安部委托的县级以上地方人民政府公安机关出入境管理机构以及中华人民共和国驻外使馆、领馆和外交部委托的其他驻外机构签发。"},{"i":5,"n":"第五条","txt":"公民因前往外国定居、探亲、学习、就业、旅行、从事商务活动等非公务原因出国的，由本人向户籍所在地的县级以上地方人民政府公安机关出入境管理机构申请普通护照。"},{"i":6,"n":"第六条","txt":"公民申请普通护照，应当提交本人的居民身份证、户口簿、近期免冠照片以及申请事由的相关材料。国家工作人员因本法第五条规定的原因出境申请普通护照的，还应当按照国家有关规定提交相关证明文件。"},{"i":7,"n":"第七条","txt":"普通护照的登记项目包括：护照持有人的姓名、性别、出生日期、出生地，护照的签发日期、有效期、签发地点和签发机关。"},{"i":8,"n":"第八条","txt":"外交官员、领事官员及其随行配偶、未成年子女和外交信使持用外交护照。"},{"i":9,"n":"第九条","txt":"外交护照、公务护照的登记项目包括：护照持有人的姓名、性别、出生日期、出生地，护照的签发日期、有效期和签发机关。"},{"i":10,"n":"第十条","txt":"护照持有人所持护照的登记事项发生变更时，应当持相关证明材料，向护照签发机关申请护照变更加注。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，护照持有人可以按照规定申请换发或者补发护照："},{"i":12,"n":"第十二条","txt":"护照具备视读与机读两种功能。"},{"i":13,"n":"第十三条","txt":"申请人有下列情形之一的，护照签发机关不予签发护照："},{"i":14,"n":"第十四条","txt":"申请人有下列情形之一的，护照签发机关自其刑罚执行完毕或者被遣返回国之日起六个月至三年以内不予签发护照："},{"i":15,"n":"第十五条","txt":"人民法院、人民检察院、公安机关、国家安全机关、行政监察机关因办理案件需要，可以依法扣押案件当事人的护照。"},{"i":16,"n":"第十六条","txt":"护照持有人丧失中华人民共和国国籍，或者护照遗失、被盗等情形，由护照签发机关宣布该护照作废。"},{"i":17,"n":"第十七条","txt":"弄虚作假骗取护照的，由护照签发机关收缴护照或者宣布护照作废；由公安机关处二千元以上五千元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"为他人提供伪造、变造的护照，或者出售护照的，依法追究刑事责任；尚不够刑事处罚的，由公安机关没收违法所得，处十日以上十五日以下拘留，并处二千元以上五千元以下罚款；非法护照及其印制设备由公安机关收缴。"},{"i":19,"n":"第十九条","txt":"持用伪造或者变造的护照或者冒用他人护照出入国（边）境的，由公安机关依照出境入境管理的法律规定予以处罚；非法护照由公安机关收缴。"},{"i":20,"n":"第二十条","txt":"护照签发机关工作人员在办理护照过程中有下列行为之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":21,"n":"第二十一条","txt":"普通护照由公安部规定式样并监制；外交护照、公务护照由外交部规定式样并监制。"},{"i":22,"n":"第二十二条","txt":"护照签发机关可以收取护照的工本费、加注费。收取的工本费和加注费上缴国库。"},{"i":23,"n":"第二十三条","txt":"短期出国的公民在国外发生护照遗失、被盗或者损毁不能使用等情形，应当向中华人民共和国驻外使馆、领馆或者外交部委托的其他驻外机构申请中华人民共和国旅行证。"},{"i":24,"n":"第二十四条","txt":"公民从事边境贸易、边境旅游服务或者参加边境旅游等情形，可以向公安部委托的县级以上地方人民政府公安机关出入境管理机构申请中华人民共和国出入境通行证。"},{"i":25,"n":"第二十五条","txt":"公民以海员身份出入国境和在国外船舶上从事工作的，应当向交通部委托的海事管理机构申请中华人民共和国海员证。"},{"i":26,"n":"第二十六条","txt":"本法自2007年1月1日起施行。本法施行前签发的护照在有效期内继续有效。"}],"jiaoshifa":[{"i":1,"n":"第一条","txt":"为了保障教师的合法权益，建设具有良好思想品德修养和业务素质的教师队伍，促进社会主义教育事业的发展，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于在各级各类学校和其他教育机构中专门从事教育教学工作的教师。"},{"i":3,"n":"第三条","txt":"教师是履行教育教学职责的专业人员，承担教书育人，培养社会主义事业建设者和接班人、提高民族素质的使命。教师应当忠诚于人民的教育事业。"},{"i":4,"n":"第四条","txt":"各级人民政府应当采取措施，加强教师的思想政治教育和业务培训，改善教师的工作条件和生活条件，保障教师的合法权益，提高教师的社会地位。"},{"i":5,"n":"第五条","txt":"国务院教育行政部门主管全国的教师工作。"},{"i":6,"n":"第六条","txt":"每年九月十日为教师节。"},{"i":7,"n":"第七条","txt":"教师享有下列权利："},{"i":8,"n":"第八条","txt":"教师应当履行下列义务："},{"i":9,"n":"第九条","txt":"为保障教师完成教育教学任务，各级人民政府、教育行政部门、有关部门、学校和其他教育机构应当履行下列职责："},{"i":10,"n":"第十条","txt":"国家实行教师资格制度。"},{"i":11,"n":"第十一条","txt":"取得教师资格应当具备的相应学历是："},{"i":12,"n":"第十二条","txt":"本法实施前已经在学校或者其他教育机构中任教的教师，未具备本法规定学历的，由国务院教育行政部门规定教师资格过渡办法。"},{"i":13,"n":"第十三条","txt":"中小学教师资格由县级以上地方人民政府教育行政部门认定。中等专业学校、技工学校的教师资格由县级以上地方人民政府教育行政部门组织有关主管部门认定。普通高等学校的教师资格由国务院或者省、自治区、直辖市教育行政部门或者由其委托的学校认定。"},{"i":14,"n":"第十四条","txt":"受到剥夺政治权利或者故意犯罪受到有期徒刑以上刑事处罚的，不能取得教师资格；已经取得教师资格的，丧失教师资格。"},{"i":15,"n":"第十五条","txt":"各级师范学校毕业生，应当按照国家有关规定从事教育教学工作。"},{"i":16,"n":"第十六条","txt":"国家实行教师职务制度，具体办法由国务院规定。"},{"i":17,"n":"第十七条","txt":"学校和其他教育机构应当逐步实行教师聘任制。教师的聘任应当遵循双方地位平等的原则，由学校和教师签订聘任合同，明确规定双方的权利、义务和责任。"},{"i":18,"n":"第十八条","txt":"各级人民政府和有关部门应当办好师范教育，并采取措施，鼓励优秀青年进入各级师范学校学习。各级教师进修学校承担培训中小学教师的任务。"},{"i":19,"n":"第十九条","txt":"各级人民政府教育行政部门、学校主管部门和学校应当制定教师培训规划，对教师进行多种形式的思想政治、业务培训。"},{"i":20,"n":"第二十条","txt":"国家机关、企业事业单位和其他社会组织应当为教师的社会调查和社会实践提供方便，给予协助。"},{"i":21,"n":"第二十一条","txt":"各级人民政府应当采取措施，为少数民族地区和边远贫困地区培养、培训教师。"},{"i":22,"n":"第二十二条","txt":"学校或者其他教育机构应当对教师的政治思想、业务水平、工作态度和工作成绩进行考核。"},{"i":23,"n":"第二十三条","txt":"考核应当客观、公正、准确，充分听取教师本人、其他教师以及学生的意见。"},{"i":24,"n":"第二十四条","txt":"教师考核结果是受聘任教、晋升工资、实施奖惩的依据。"},{"i":25,"n":"第二十五条","txt":"教师的平均工资水平应当不低于或者高于国家公务员的平均工资水平，并逐步提高。建立正常晋级增薪制度，具体办法由国务院规定。"},{"i":26,"n":"第二十六条","txt":"中小学教师和职业学校教师享受教龄津贴和其他津贴，具体办法由国务院教育行政部门会同有关部门制定。"},{"i":27,"n":"第二十七条","txt":"地方各级人民政府对教师以及具有中专以上学历的毕业生到少数民族地区和边远贫困地区从事教育教学工作的，应当予以补贴。"},{"i":28,"n":"第二十八条","txt":"地方各级人民政府和国务院有关部门，对城市教师住房的建设、租赁、出售实行优先、优惠。"},{"i":29,"n":"第二十九条","txt":"教师的医疗同当地国家公务员享受同等的待遇；定期对教师进行身体健康检查，并因地制宜安排教师进行休养。"},{"i":30,"n":"第三十条","txt":"教师退休或者退职后，享受国家规定的退休或者退职待遇。"},{"i":31,"n":"第三十一条","txt":"各级人民政府应当采取措施，改善国家补助、集体支付工资的中小学教师的待遇，逐步做到在工资收入上与国家支付工资的教师同工同酬，具体办法由地方各级人民政府根据本地区的实际情况规定。"},{"i":32,"n":"第三十二条","txt":"社会力量所办学校的教师的待遇，由举办者自行确定并予以保障。"},{"i":33,"n":"第三十三条","txt":"教师在教育教学、培养人才、科学研究、教学改革、学校建设、社会服务、勤工俭学等方面成绩优异的，由所在学校予以表彰、奖励。"},{"i":34,"n":"第三十四条","txt":"国家支持和鼓励社会组织或者个人向依法成立的奖励教师的基金组织捐助资金，对教师进行奖励。"},{"i":35,"n":"第三十五条","txt":"侮辱、殴打教师的，根据不同情况，分别给予行政处分或者行政处罚；造成损害的，责令赔偿损失；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"对依法提出申诉、控告、检举的教师进行打击报复的，由其所在单位或者上级机关责令改正；情节严重的，可以根据具体情况给予行政处分。"},{"i":37,"n":"第三十七条","txt":"教师有下列情形之一的，由所在学校、其他教育机构或者教育行政部门给予行政处分或者解聘："},{"i":38,"n":"第三十八条","txt":"地方人民政府对违反本法规定，拖欠教师工资或者侵犯教师其他合法权益的，应当责令其限期改正。"},{"i":39,"n":"第三十九条","txt":"教师对学校或者其他教育机构侵犯其合法权益的，或者对学校或者其他教育机构作出的处理不服的，可以向教育行政部门提出申诉，教育行政部门应当在接到申诉的三十日内，作出处理。"},{"i":40,"n":"第四十条","txt":"本法下列用语的含义是："},{"i":41,"n":"第四十一条","txt":"学校和其他教育机构中的教育教学辅助人员，其他类型的学校的教师和教育教学辅助人员，可以根据实际情况参照本法的有关规定执行。"},{"i":42,"n":"第四十二条","txt":"外籍教师的聘任办法由国务院教育行政部门规定。"},{"i":43,"n":"第四十三条","txt":"本法自1994年1月1日起施行。"}],"jiaoyufa":[{"i":1,"n":"第一条","txt":"为了发展教育事业，提高全民族的素质，促进社会主义物质文明和精神文明建设，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的各级各类教育，适用本法。"},{"i":3,"n":"第三条","txt":"国家坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，遵循宪法确定的基本原则，发展社会主义的教育事业。"},{"i":4,"n":"第四条","txt":"教育是社会主义现代化建设的基础，对提高人民综合素质、促进人的全面发展、增强中华民族创新创造活力、实现中华民族伟大复兴具有决定性意义，国家保障教育事业优先发展。"},{"i":5,"n":"第五条","txt":"教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合，培养德智体美劳全面发展的社会主义建设者和接班人。"},{"i":6,"n":"第六条","txt":"教育应当坚持立德树人，对受教育者加强社会主义核心价值观教育，增强受教育者的社会责任感、创新精神和实践能力。"},{"i":7,"n":"第七条","txt":"教育应当继承和弘扬中华优秀传统文化、革命文化、社会主义先进文化，吸收人类文明发展的一切优秀成果。"},{"i":8,"n":"第八条","txt":"教育活动必须符合国家和社会公共利益。"},{"i":9,"n":"第九条","txt":"中华人民共和国公民有受教育的权利和义务。"},{"i":10,"n":"第十条","txt":"国家根据各少数民族的特点和需要，帮助各少数民族地区发展教育事业。"},{"i":11,"n":"第十一条","txt":"国家适应社会主义市场经济发展和社会进步的需要，推进教育改革，推动各级各类教育协调发展、衔接融通，完善现代国民教育体系，健全终身教育体系，提高教育现代化水平。"},{"i":12,"n":"第十二条","txt":"国家通用语言文字为学校及其他教育机构的基本教育教学语言文字，学校及其他教育机构应当使用国家通用语言文字进行教育教学。"},{"i":13,"n":"第十三条","txt":"国家对发展教育事业做出突出贡献的组织和个人，给予奖励。"},{"i":14,"n":"第十四条","txt":"国务院和地方各级人民政府根据分级管理、分工负责的原则，领导和管理教育工作。"},{"i":15,"n":"第十五条","txt":"国务院教育行政部门主管全国教育工作，统筹规划、协调管理全国的教育事业。"},{"i":16,"n":"第十六条","txt":"国务院和县级以上地方各级人民政府应当向本级人民代表大会或者其常务委员会报告教育工作和教育经费预算、决算情况，接受监督。"},{"i":17,"n":"第十七条","txt":"国家实行学前教育、初等教育、中等教育、高等教育的学校教育制度。"},{"i":18,"n":"第十八条","txt":"国家制定学前教育标准，加快普及学前教育，构建覆盖城乡，特别是农村的学前教育公共服务体系。"},{"i":19,"n":"第十九条","txt":"国家实行九年制义务教育制度。"},{"i":20,"n":"第二十条","txt":"国家实行职业教育制度和继续教育制度。"},{"i":21,"n":"第二十一条","txt":"国家实行国家教育考试制度。"},{"i":22,"n":"第二十二条","txt":"国家实行学业证书制度。"},{"i":23,"n":"第二十三条","txt":"国家实行学位制度。"},{"i":24,"n":"第二十四条","txt":"各级人民政府、基层群众性自治组织和企业事业组织应当采取各种措施，开展扫除文盲的教育工作。"},{"i":25,"n":"第二十五条","txt":"国家实行教育督导制度和学校及其他教育机构教育评估制度。"},{"i":26,"n":"第二十六条","txt":"国家制定教育发展规划，并举办学校及其他教育机构。"},{"i":27,"n":"第二十七条","txt":"设立学校及其他教育机构，必须具备下列基本条件："},{"i":28,"n":"第二十八条","txt":"学校及其他教育机构的设立、变更和终止，应当按照国家有关规定办理审核、批准、注册或者备案手续。"},{"i":29,"n":"第二十九条","txt":"学校及其他教育机构行使下列权利："},{"i":30,"n":"第三十条","txt":"学校及其他教育机构应当履行下列义务："},{"i":31,"n":"第三十一条","txt":"学校及其他教育机构的举办者按照国家有关规定，确定其所举办的学校或者其他教育机构的管理体制。"},{"i":32,"n":"第三十二条","txt":"学校及其他教育机构具备法人条件的，自批准设立或者登记注册之日起取得法人资格。"},{"i":33,"n":"第三十三条","txt":"教师享有法律规定的权利，履行法律规定的义务，忠诚于人民的教育事业。"},{"i":34,"n":"第三十四条","txt":"国家保护教师的合法权益，改善教师的工作条件和生活条件，提高教师的社会地位。"},{"i":35,"n":"第三十五条","txt":"国家实行教师资格、职务、聘任制度，通过考核、奖励、培养和培训，提高教师素质，加强教师队伍建设。"},{"i":36,"n":"第三十六条","txt":"学校及其他教育机构中的管理人员，实行教育职员制度。"},{"i":37,"n":"第三十七条","txt":"受教育者在入学、升学、就业等方面依法享有平等权利。"},{"i":38,"n":"第三十八条","txt":"国家、社会对符合入学条件、家庭经济困难的儿童、少年、青年，提供各种形式的资助。"},{"i":39,"n":"第三十九条","txt":"国家、社会、学校及其他教育机构应当根据残疾人身心特性和需要实施教育，并为其提供帮助和便利。"},{"i":40,"n":"第四十条","txt":"国家、社会、家庭、学校及其他教育机构应当为有违法犯罪行为的未成年人接受教育创造条件。"},{"i":41,"n":"第四十一条","txt":"从业人员有依法接受职业培训和继续教育的权利和义务。"},{"i":42,"n":"第四十二条","txt":"国家鼓励学校及其他教育机构、社会组织采取措施，为公民接受终身教育创造条件。"},{"i":43,"n":"第四十三条","txt":"受教育者享有下列权利："},{"i":44,"n":"第四十四条","txt":"受教育者应当履行下列义务："},{"i":45,"n":"第四十五条","txt":"教育、体育、卫生行政部门和学校及其他教育机构应当完善体育、卫生保健设施，保护学生的身心健康。"},{"i":46,"n":"第四十六条","txt":"国家机关、军队、企业事业组织、社会团体及其他社会组织和个人，应当依法为儿童、少年、青年学生的身心健康成长创造良好的社会环境。"},{"i":47,"n":"第四十七条","txt":"国家鼓励企业事业组织、社会团体及其他社会组织同高等学校、中等职业学校在教学、科研、技术开发和推广等方面进行多种形式的合作。"},{"i":48,"n":"第四十八条","txt":"国家机关、军队、企业事业组织及其他社会组织应当为学校组织的学生实习、社会实践活动提供帮助和便利。"},{"i":49,"n":"第四十九条","txt":"学校及其他教育机构在不影响正常教育教学活动的前提下，应当积极参加当地的社会公益活动。"},{"i":50,"n":"第五十条","txt":"未成年人的父母或者其他监护人应当为其未成年子女或者其他被监护人受教育提供必要条件。"},{"i":51,"n":"第五十一条","txt":"图书馆、博物馆、科技馆、文化馆、美术馆、体育馆（场）等社会公共文化体育设施，以及历史文化古迹和革命纪念馆（地），应当对教师、学生实行优待，为受教育者接受教育提供便利。"},{"i":52,"n":"第五十二条","txt":"国家、社会建立和发展对未成年人进行校外教育的设施。"},{"i":53,"n":"第五十三条","txt":"国家鼓励社会团体、社会文化机构及其他社会组织和个人开展有益于受教育者身心健康的社会文化教育活动。"},{"i":54,"n":"第五十四条","txt":"国家建立以财政拨款为主、其他多种渠道筹措教育经费为辅的体制，逐步增加对教育的投入，保证国家举办的学校教育经费的稳定来源。"},{"i":55,"n":"第五十五条","txt":"国家财政性教育经费支出占国民生产总值的比例应当随着国民经济的发展和财政收入的增长逐步提高。具体比例和实施步骤由国务院规定。"},{"i":56,"n":"第五十六条","txt":"各级人民政府的教育经费支出，按照事权和财权相统一的原则，在财政预算中单独列项。"},{"i":57,"n":"第五十七条","txt":"国务院及县级以上地方各级人民政府应当设立教育专项资金，重点扶持边远贫困地区、少数民族地区实施义务教育。"},{"i":58,"n":"第五十八条","txt":"税务机关依法足额征收教育费附加，由教育行政部门统筹管理，主要用于实施义务教育。"},{"i":59,"n":"第五十九条","txt":"国家采取优惠措施，鼓励和扶持学校在不影响正常教育教学的前提下开展勤工俭学和社会服务，兴办校办产业。"},{"i":60,"n":"第六十条","txt":"国家鼓励境内、境外社会组织和个人捐资助学。"},{"i":61,"n":"第六十一条","txt":"国家财政性教育经费、社会组织和个人对教育的捐赠，必须用于教育，不得挪用、克扣。"},{"i":62,"n":"第六十二条","txt":"国家鼓励运用金融、信贷手段，支持教育事业的发展。"},{"i":63,"n":"第六十三条","txt":"各级人民政府及其教育行政部门应当加强对学校及其他教育机构教育经费的监督管理，提高教育投资效益。"},{"i":64,"n":"第六十四条","txt":"地方各级人民政府及其有关行政部门必须把学校的基本建设纳入城乡建设规划，统筹安排学校的基本建设用地及所需物资，按照国家有关规定实行优先、优惠政策。"},{"i":65,"n":"第六十五条","txt":"各级人民政府对教科书及教学用图书资料的出版发行，对教学仪器、设备的生产和供应，对用于学校教育教学和科学研究的图书资料、教学仪器、设备的进口，按照国家有关规定实行优先、优惠政策。"},{"i":66,"n":"第六十六条","txt":"国家推进教育信息化，加快教育信息基础设施建设，利用信息技术促进优质教育资源普及共享，提高教育教学水平和教育管理水平。"},{"i":67,"n":"第六十七条","txt":"国家鼓励开展教育对外交流与合作，支持学校及其他教育机构引进优质教育资源，依法开展中外合作办学，发展国际教育服务，培养国际化人才。"},{"i":68,"n":"第六十八条","txt":"中国境内公民出国留学、研究、进行学术交流或者任教，依照国家有关规定办理。"},{"i":69,"n":"第六十九条","txt":"中国境外个人符合国家规定的条件并办理有关手续后，可以进入中国境内学校及其他教育机构学习、研究、进行学术交流或者任教，其合法权益受国家保护。"},{"i":70,"n":"第七十条","txt":"中国对境外教育机构颁发的学位证书、学历证书及其他学业证书的承认，依照中华人民共和国缔结或者加入的国际条约办理，或者按照国家有关规定办理。"},{"i":71,"n":"第七十一条","txt":"违反国家有关规定，不按照预算核拨教育经费的，由同级人民政府限期核拨；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":72,"n":"第七十二条","txt":"结伙斗殴、寻衅滋事，扰乱学校及其他教育机构教育教学秩序或者破坏校舍、场地及其他财产的，由公安机关给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"明知校舍或者教育教学设施有危险，而不采取措施，造成人员伤亡或者重大财产损失的，对直接负责的主管人员和其他直接责任人员，依法追究刑事责任。"},{"i":74,"n":"第七十四条","txt":"违反国家有关规定，向学校或者其他教育机构收取费用的，由政府责令退还所收费用；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":75,"n":"第七十五条","txt":"违反国家有关规定，举办学校或者其他教育机构的，由教育行政部门或者其他有关行政部门予以撤销；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":76,"n":"第七十六条","txt":"学校或者其他教育机构违反国家有关规定招收学生的，由教育行政部门或者其他有关行政部门责令退回招收的学生，退还所收费用；对学校、其他教育机构给予警告，可以处违法所得五倍以下罚款；情节严重的，责令停止相关招生资格一年以上三年以下，直至撤销招生资格、吊销办学许可证；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":77,"n":"第七十七条","txt":"在招收学生工作中滥用职权、玩忽职守、徇私舞弊的，由教育行政部门或者其他有关行政部门责令退回招收的不符合入学条件的人员；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"学校及其他教育机构违反国家有关规定向受教育者收取费用的，由教育行政部门或者其他有关行政部门责令退还所收费用；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":79,"n":"第七十九条","txt":"考生在国家教育考试中有下列行为之一的，由组织考试的教育考试机构工作人员在考试现场采取必要措施予以制止并终止其继续参加考试；组织考试的教育考试机构可以取消其相关考试资格或者考试成绩；情节严重的，由教育行政部门责令停止参加相关国家教育考试一年以上三年以下；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任："},{"i":80,"n":"第八十条","txt":"任何组织或者个人在国家教育考试中有下列行为之一，有违法所得的，由公安机关没收违法所得，并处违法所得一倍以上五倍以下罚款；情节严重的，处五日以上十五日以下拘留；构成犯罪的，依法追究刑事责任；属于国家机关工作人员的，还应当依法给予处分："},{"i":81,"n":"第八十一条","txt":"举办国家教育考试，教育行政部门、教育考试机构疏于管理，造成考场秩序混乱、作弊情况严重的，对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":82,"n":"第八十二条","txt":"学校或者其他教育机构违反本法规定，颁发学位证书、学历证书或者其他学业证书的，由教育行政部门或者其他有关行政部门宣布证书无效，责令收回或者予以没收；有违法所得的，没收违法所得；情节严重的，责令停止相关招生资格一年以上三年以下，直至撤销招生资格、颁发证书资格；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":83,"n":"第八十三条","txt":"违反本法规定，侵犯教师、受教育者、学校或者其他教育机构的合法权益，造成损失、损害的，应当依法承担民事责任。"},{"i":84,"n":"第八十四条","txt":"军事学校教育由中央军事委员会根据本法的原则规定。"},{"i":85,"n":"第八十五条","txt":"境外的组织和个人在中国境内办学和合作办学的办法，由国务院规定。"},{"i":86,"n":"第八十六条","txt":"本法自1995年9月1日起施行。"}],"wenwubaohufa":[{"i":1,"n":"第一条","txt":"为了加强对文物的保护，传承中华民族优秀历史文化遗产，促进科学研究工作，进行爱国主义和革命传统教育，增强历史自觉、坚定文化自信，建设社会主义精神文明和物质文明，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"文物受国家保护。本法所称文物，是指人类创造的或者与人类活动有关的，具有历史、艺术、科学价值的下列物质遗存："},{"i":3,"n":"第三条","txt":"文物分为不可移动文物和可移动文物。"},{"i":4,"n":"第四条","txt":"文物工作坚持中国共产党的领导，坚持以社会主义核心价值观为引领，贯彻保护为主、抢救第一、合理利用、加强管理的方针。"},{"i":5,"n":"第五条","txt":"中华人民共和国境内地下、内水和领海中遗存的一切文物，以及中国管辖的其他海域内遗存的起源于中国的和起源国不明的文物，属于国家所有。"},{"i":6,"n":"第六条","txt":"下列可移动文物，属于国家所有："},{"i":7,"n":"第七条","txt":"国有文物所有权受法律保护，不容侵犯。"},{"i":8,"n":"第八条","txt":"一切机关、组织和个人都有依法保护文物的义务。"},{"i":9,"n":"第九条","txt":"国务院文物行政部门主管全国文物保护工作。"},{"i":10,"n":"第十条","txt":"国家发展文物保护事业，贯彻落实保护第一、加强管理、挖掘价值、有效利用、让文物活起来的工作要求。"},{"i":11,"n":"第十一条","txt":"文物是不可再生的文化资源。各级人民政府应当重视文物保护，正确处理经济建设、社会发展与文物保护的关系，确保文物安全。"},{"i":12,"n":"第十二条","txt":"对与中国共产党各个历史时期重大事件、重要会议、重要人物和伟大建党精神等有关的文物，各级人民政府应当采取措施加强保护。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府应当将文物保护事业纳入本级国民经济和社会发展规划，所需经费列入本级预算，确保文物保护事业发展与国民经济和社会发展水平相适应。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府及其文物行政部门应当加强文物普查和专项调查，全面掌握文物资源及保护情况。"},{"i":15,"n":"第十五条","txt":"国家支持和规范文物价值挖掘阐释，促进中华文明起源与发展研究，传承中华优秀传统文化，弘扬革命文化，发展社会主义先进文化，铸牢中华民族共同体意识，提升中华文化影响力。"},{"i":16,"n":"第十六条","txt":"国家加强文物保护的宣传教育，创新传播方式，增强全民文物保护的意识，营造自觉传承中华民族优秀历史文化遗产的社会氛围。"},{"i":17,"n":"第十七条","txt":"国家鼓励开展文物保护的科学研究，推广先进适用的文物保护技术，提高文物保护的科学技术水平。"},{"i":18,"n":"第十八条","txt":"国家鼓励开展文物利用研究，在确保文物安全的前提下，坚持社会效益优先，有效利用文物资源，提供多样化多层次的文化产品与服务。"},{"i":19,"n":"第十九条","txt":"国家健全社会参与机制，调动社会力量参与文化遗产保护的积极性，鼓励引导社会力量投入文化遗产保护。"},{"i":20,"n":"第二十条","txt":"国家支持开展考古、修缮、修复、展览、科学研究、执法、司法等文物保护国际交流与合作，促进人类文明交流互鉴。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府文物行政部门或者有关部门应当公开投诉、举报方式等信息，及时受理并处理涉及文物保护的投诉、举报。"},{"i":22,"n":"第二十二条","txt":"有下列事迹之一的单位或者个人，按照国家有关规定给予表彰、奖励："},{"i":23,"n":"第二十三条","txt":"在文物普查、专项调查或者其他相关工作中发现的不可移动文物，应当及时核定公布为文物保护单位或者登记公布为未定级不可移动文物。公民、组织可以提出核定公布文物保护单位或者登记公布未定级不可移动文物的建议。"},{"i":24,"n":"第二十四条","txt":"在旧城区改建、土地成片开发中，县级以上人民政府应当事先组织进行相关区域内不可移动文物调查，及时开展核定、登记、公布工作，并依法采取保护措施。未经调查，任何单位不得开工建设，防止建设性破坏。"},{"i":25,"n":"第二十五条","txt":"保存文物特别丰富并且具有重大历史价值或者革命纪念意义的城市，由国务院核定公布为历史文化名城。"},{"i":26,"n":"第二十六条","txt":"各级文物保护单位，分别由省、自治区、直辖市人民政府和设区的市级、县级人民政府划定公布必要的保护范围，作出标志说明，建立记录档案，并区别情况分别设置专门机构或者专人负责管理。全国重点文物保护单位的保护范围和记录档案，由省、自治区、直辖市人民政府文物行政部门报国务院文物行政部门备案。"},{"i":27,"n":"第二十七条","txt":"各级人民政府制定有关规划，应当根据文物保护的需要，事先由有关部门会同文物行政部门商定本行政区域内不可移动文物的保护措施，并纳入规划。"},{"i":28,"n":"第二十八条","txt":"在文物保护单位的保护范围内不得进行文物保护工程以外的其他建设工程或者爆破、钻探、挖掘等作业；因特殊情况需要进行的，必须保证文物保护单位的安全。"},{"i":29,"n":"第二十九条","txt":"根据保护文物的实际需要，经省、自治区、直辖市人民政府批准，可以在文物保护单位的周围划出一定的建设控制地带，并予以公布。"},{"i":30,"n":"第三十条","txt":"在文物保护单位的保护范围和建设控制地带内，不得建设污染文物保护单位及其环境的设施，不得进行可能影响文物保护单位安全及其环境的活动。对已有的污染文物保护单位及其环境的设施，依照生态环境有关法律法规的规定处理。"},{"i":31,"n":"第三十一条","txt":"建设工程选址，应当尽可能避开不可移动文物；因特殊情况不能避开的，应当尽可能实施原址保护。"},{"i":32,"n":"第三十二条","txt":"国有不可移动文物由使用人负责修缮、保养；非国有不可移动文物由所有人或者使用人负责修缮、保养，县级以上人民政府可以予以补助。"},{"i":33,"n":"第三十三条","txt":"不可移动文物已经全部毁坏的，应当严格实施遗址保护，不得在原址重建。因文物保护等特殊情况需要在原址重建的，由省、自治区、直辖市人民政府文物行政部门报省、自治区、直辖市人民政府批准；全国重点文物保护单位需要在原址重建的，由省、自治区、直辖市人民政府征得国务院文物行政部门同意后报国务院批准。"},{"i":34,"n":"第三十四条","txt":"国有文物保护单位中的纪念建筑物或者古建筑，除可以建立博物馆、文物保管所或者辟为参观游览场所外，改作其他用途的，设区的市级、县级文物保护单位应当经核定公布该文物保护单位的人民政府文物行政部门征得上一级人民政府文物行政部门同意后，报核定公布该文物保护单位的人民政府批准；省级文物保护单位应当经核定公布该文物保护单位的省、自治区、直辖市人民政府文物行政部门审核同意后，报省、自治区、直辖市人民政府批准；全国重点文物保护单位应当由省、自治区、直辖市人民政府报国务院批准。国有未定级不可移动文物改作其他用途的，应当报告县级人民政府文物行政部门。"},{"i":35,"n":"第三十五条","txt":"国有不可移动文物不得转让、抵押，国家另有规定的，依照其规定。建立博物馆、文物保管所或者辟为参观游览场所的国有不可移动文物，不得改作企业资产经营；其管理机构不得改由企业管理。"},{"i":36,"n":"第三十六条","txt":"非国有不可移动文物不得转让、抵押给外国人、外国组织或者国际组织。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府及其有关部门应当采取措施，在确保文物安全的前提下，因地制宜推动不可移动文物有效利用。"},{"i":38,"n":"第三十八条","txt":"使用不可移动文物，必须遵守不改变文物原状和最小干预的原则，负责保护文物本体及其附属文物的安全，不得损毁、改建、添建或者拆除不可移动文物。"},{"i":39,"n":"第三十九条","txt":"不可移动文物的所有人或者使用人应当加强用火、用电、用气等的消防安全管理，根据不可移动文物的特点，采取有针对性的消防安全措施，提高火灾预防和应急处置能力，确保文物安全。"},{"i":40,"n":"第四十条","txt":"省、自治区、直辖市人民政府可以将地下埋藏、水下遗存的文物分布较为集中，需要整体保护的区域划定为地下文物埋藏区、水下文物保护区，制定具体保护措施，并公告施行。"},{"i":41,"n":"第四十一条","txt":"一切考古发掘工作，必须履行报批手续；从事考古发掘的单位，应当取得国务院文物行政部门颁发的考古发掘资质证书。"},{"i":42,"n":"第四十二条","txt":"从事考古发掘的单位，为了科学研究进行考古发掘，应当提出发掘计划，报国务院文物行政部门批准；对全国重点文物保护单位的考古发掘计划，应当经国务院文物行政部门审核后报国务院批准。国务院文物行政部门在批准或者审核前，应当征求社会科学研究机构及其他科研机构和有关专家的意见。"},{"i":43,"n":"第四十三条","txt":"在可能存在地下文物的区域，县级以上地方人民政府进行土地出让或者划拨前，应当由省、自治区、直辖市人民政府文物行政部门组织从事考古发掘的单位进行考古调查、勘探。可能存在地下文物的区域，由省、自治区、直辖市人民政府文物行政部门及时划定并动态调整。"},{"i":44,"n":"第四十四条","txt":"需要配合进行考古发掘工作的，省、自治区、直辖市人民政府文物行政部门应当在勘探工作的基础上提出发掘计划，报国务院文物行政部门批准。国务院文物行政部门在批准前，应当征求社会科学研究机构及其他科研机构和有关专家的意见。"},{"i":45,"n":"第四十五条","txt":"凡因进行基本建设和生产建设需要的考古调查、勘探、发掘，所需费用由建设单位列入建设工程预算。"},{"i":46,"n":"第四十六条","txt":"在建设工程、农业生产等活动中，任何单位或者个人发现文物或者疑似文物的，应当保护现场，立即报告当地文物行政部门；文物行政部门应当在接到报告后二十四小时内赶赴现场，并在七日内提出处理意见。文物行政部门应当采取措施保护现场，必要时可以通知公安机关或者海上执法机关协助；发现重要文物的，应当立即上报国务院文物行政部门，国务院文物行政部门应当在接到报告后十五日内提出处理意见。"},{"i":47,"n":"第四十七条","txt":"未经国务院文物行政部门报国务院特别许可，任何外国人、外国组织或者国际组织不得在中国境内进行考古调查、勘探、发掘。"},{"i":48,"n":"第四十八条","txt":"考古调查、勘探、发掘的结果，应当如实报告国务院文物行政部门和省、自治区、直辖市人民政府文物行政部门。"},{"i":49,"n":"第四十九条","txt":"根据保证文物安全、进行科学研究和充分发挥文物作用的需要，省、自治区、直辖市人民政府文物行政部门经本级人民政府批准，可以调用本行政区域内的出土、出水文物；国务院文物行政部门经国务院批准，可以调用全国的重要出土、出水文物。"},{"i":50,"n":"第五十条","txt":"国家鼓励和支持文物收藏单位收藏、保护可移动文物，开展文物展览展示、宣传教育和科学研究等活动。"},{"i":51,"n":"第五十一条","txt":"博物馆、图书馆和其他文物收藏单位对其收藏的文物（以下称馆藏文物），必须按照国家有关文物定级标准区分文物等级，设置档案，建立严格的管理制度，并报主管的文物行政部门备案。"},{"i":52,"n":"第五十二条","txt":"文物收藏单位可以通过下列方式取得文物："},{"i":53,"n":"第五十三条","txt":"文物收藏单位应当根据馆藏文物的保护需要，按照国家有关规定建立、健全管理制度，并报主管的文物行政部门备案。未经批准，任何单位或者个人不得调取馆藏文物。"},{"i":54,"n":"第五十四条","txt":"国务院文物行政部门可以调拨全国的国有馆藏文物。省、自治区、直辖市人民政府文物行政部门可以调拨本行政区域内其主管的国有文物收藏单位馆藏文物；调拨国有馆藏一级文物，应当报国务院文物行政部门备案。"},{"i":55,"n":"第五十五条","txt":"文物收藏单位应当改善服务条件，提高服务水平，充分发挥馆藏文物的作用，通过举办展览、科学研究、文化创意等活动，加强对中华民族优秀的历史文化和革命传统的宣传教育；通过借用、交换、在线展览等方式，提高馆藏文物利用效率。"},{"i":56,"n":"第五十六条","txt":"国有文物收藏单位之间因举办展览、科学研究等需借用馆藏文物的，应当报主管的文物行政部门备案；借用馆藏一级文物的，应当同时报国务院文物行政部门备案。"},{"i":57,"n":"第五十七条","txt":"已经依照本法规定建立馆藏文物档案、管理制度的国有文物收藏单位之间可以交换馆藏文物；交换馆藏文物的，应当经省、自治区、直辖市人民政府文物行政部门批准，并报国务院文物行政部门备案。"},{"i":58,"n":"第五十八条","txt":"未依照本法规定建立馆藏文物档案、管理制度的国有文物收藏单位，不得依照本法第五十五条至第五十七条的规定借用、交换其馆藏文物。"},{"i":59,"n":"第五十九条","txt":"依法调拨、交换、借用馆藏文物，取得文物的文物收藏单位可以对提供文物的文物收藏单位给予合理补偿。"},{"i":60,"n":"第六十条","txt":"禁止国有文物收藏单位将馆藏文物赠与、出租、出售或者抵押、质押给其他单位、个人。"},{"i":61,"n":"第六十一条","txt":"国有文物收藏单位不再收藏的文物退出馆藏的办法，由国务院文物行政部门制定并公布。"},{"i":62,"n":"第六十二条","txt":"修复馆藏文物，不得改变馆藏文物的原状；复制、拍摄、拓印馆藏文物，不得对馆藏文物造成损害。修复、复制、拓印馆藏二级文物和馆藏三级文物的，应当报省、自治区、直辖市人民政府文物行政部门批准；修复、复制、拓印馆藏一级文物的，应当报国务院文物行政部门批准。"},{"i":63,"n":"第六十三条","txt":"博物馆、图书馆和其他收藏文物的单位应当按照国家有关规定配备防火、防盗、防自然损坏的设施，并采取相应措施，确保收藏文物的安全。"},{"i":64,"n":"第六十四条","txt":"馆藏一级文物损毁的，应当报国务院文物行政部门核查处理。其他馆藏文物损毁的，应当报省、自治区、直辖市人民政府文物行政部门核查处理；省、自治区、直辖市人民政府文物行政部门应当将核查处理结果报国务院文物行政部门备案。"},{"i":65,"n":"第六十五条","txt":"文物行政部门和国有文物收藏单位的工作人员不得借用国有文物，不得非法侵占国有文物。"},{"i":66,"n":"第六十六条","txt":"国家鼓励公民、组织合法收藏，加强对民间收藏活动的指导、管理和服务。"},{"i":67,"n":"第六十七条","txt":"文物收藏单位以外的公民、组织可以收藏通过下列方式取得的文物："},{"i":68,"n":"第六十八条","txt":"禁止买卖下列文物："},{"i":69,"n":"第六十九条","txt":"国家鼓励文物收藏单位以外的公民、组织将其收藏的文物捐赠给文物收藏单位或者出借给文物收藏单位展览和研究。"},{"i":70,"n":"第七十条","txt":"文物销售单位应当取得省、自治区、直辖市人民政府文物行政部门颁发的文物销售许可证。"},{"i":71,"n":"第七十一条","txt":"依法设立的拍卖企业经营文物拍卖的，应当取得省、自治区、直辖市人民政府文物行政部门颁发的文物拍卖许可证。"},{"i":72,"n":"第七十二条","txt":"文物行政部门的工作人员不得举办或者参与举办文物销售单位或者文物拍卖企业。"},{"i":73,"n":"第七十三条","txt":"文物销售单位不得销售、文物拍卖企业不得拍卖本法第六十八条规定的文物。"},{"i":74,"n":"第七十四条","txt":"省、自治区、直辖市人民政府文物行政部门应当建立文物购销、拍卖信息与信用管理系统，推动文物流通领域诚信建设。文物销售单位购买、销售文物，文物拍卖企业拍卖文物，应当按照国家有关规定作出记录，并于销售、拍卖文物后三十日内报省、自治区、直辖市人民政府文物行政部门备案。"},{"i":75,"n":"第七十五条","txt":"文物行政部门在审核拟拍卖的文物时，可以指定国有文物收藏单位优先购买其中的珍贵文物。购买价格由国有文物收藏单位的代表与文物的委托人协商确定。"},{"i":76,"n":"第七十六条","txt":"银行、冶炼厂、造纸厂以及废旧物资回收单位，应当与当地文物行政部门共同负责拣选掺杂在金银器和废旧物资中的文物。拣选文物除供银行研究所必需的历史货币可以由中国人民银行留用外，应当移交当地文物行政部门。移交拣选文物，应当给予合理补偿。"},{"i":77,"n":"第七十七条","txt":"国有文物、非国有文物中的珍贵文物和国家禁止出境的其他文物，不得出境；依照本法规定出境展览，或者因特殊需要经国务院批准出境的除外。"},{"i":78,"n":"第七十八条","txt":"文物出境，应当经国务院文物行政部门指定的文物进出境审核机构审核。经审核允许出境的文物，由国务院文物行政部门颁发文物出境许可证，从国务院文物行政部门指定的口岸出境。"},{"i":79,"n":"第七十九条","txt":"文物出境展览，应当报国务院文物行政部门批准；一级文物超过国务院规定数量的，应当报国务院批准。"},{"i":80,"n":"第八十条","txt":"文物临时进境，应当向海关申报，并报文物进出境审核机构审核、登记。文物进出境审核机构发现临时进境的文物属于本法第六十八条规定的文物的，应当向国务院文物行政部门报告并通报海关。"},{"i":81,"n":"第八十一条","txt":"国家加强文物追索返还领域的国际合作。国务院文物行政部门依法会同有关部门对因被盗、非法出境等流失境外的文物开展追索；对非法流入中国境内的外国文物，根据有关条约、协定、协议或者对等原则与相关国家开展返还合作。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，地方各级人民政府和县级以上人民政府有关部门及其工作人员，以及其他依法履行公职的人员，滥用职权、玩忽职守、徇私舞弊的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":83,"n":"第八十三条","txt":"有下列行为之一的，由县级以上人民政府文物行政部门责令改正，给予警告；造成文物损坏或者其他严重后果的，对单位处五十万元以上五百万元以下的罚款，对个人处五万元以上五十万元以下的罚款，责令承担相关文物修缮和复原费用，由原发证机关降低资质等级；情节严重的，对单位可以处五百万元以上一千万元以下的罚款，由原发证机关吊销资质证书："},{"i":84,"n":"第八十四条","txt":"在文物保护单位的保护范围或者建设控制地带内建设污染文物保护单位及其环境的设施的，由生态环境主管部门依法给予处罚。"},{"i":85,"n":"第八十五条","txt":"违反本法规定，有下列行为之一的，由县级以上人民政府文物行政部门责令改正，给予警告或者通报批评，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处一万元以上五万元以下的罚款："},{"i":86,"n":"第八十六条","txt":"历史文化名城的布局、环境、历史风貌等遭到严重破坏的，由国务院撤销其历史文化名城称号；历史文化街区、村镇的布局、环境、历史风貌等遭到严重破坏的，由省、自治区、直辖市人民政府撤销其历史文化街区、村镇称号；对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":87,"n":"第八十七条","txt":"有下列行为之一的，由县级以上人民政府文物行政部门责令改正，给予警告或者通报批评，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，可以并处五万元以下的罚款："},{"i":88,"n":"第八十八条","txt":"买卖国家禁止买卖的文物或者将国家禁止出境的文物转让、出租、抵押、质押给境外组织或者个人的，由县级以上人民政府文物行政部门责令改正，没收违法所得、非法经营的文物；违法经营额五千元以上的，并处违法经营额二倍以上十倍以下的罚款；没有违法经营额或者违法经营额不足五千元的，并处一万元以上五万元以下的罚款。"},{"i":89,"n":"第八十九条","txt":"未经许可擅自从事文物商业经营活动的，由县级以上人民政府文物行政部门责令改正，给予警告或者通报批评，没收违法所得、非法经营的文物；违法经营额三万元以上的，并处违法经营额二倍以上十倍以下的罚款；没有违法经营额或者违法经营额不足三万元的，并处五万元以上二十五万元以下的罚款。"},{"i":90,"n":"第九十条","txt":"有下列情形之一的，由县级以上人民政府文物行政部门责令改正，给予警告或者通报批评，没收违法所得、非法经营的文物；违法经营额三万元以上的，并处违法经营额二倍以上十倍以下的罚款；没有违法经营额或者违法经营额不足三万元的，并处五万元以上二十五万元以下的罚款；情节严重的，由原发证机关吊销许可证书："},{"i":91,"n":"第九十一条","txt":"有下列行为之一的，由县级以上人民政府文物行政部门会同公安机关、海上执法机关追缴文物，给予警告；情节严重的，对单位处十万元以上三百万元以下的罚款，对个人处五千元以上五万元以下的罚款："},{"i":92,"n":"第九十二条","txt":"文物进出境未依照本法规定申报的，由海关或者海上执法机关依法给予处罚。"},{"i":93,"n":"第九十三条","txt":"有下列行为之一的，由县级以上人民政府文物行政部门责令改正；情节严重的，对单位处十万元以上三百万元以下的罚款，限制业务活动或者由原发证机关吊销许可证书，对个人处五千元以上五万元以下的罚款："},{"i":94,"n":"第九十四条","txt":"文物行政部门、文物收藏单位、文物销售单位、文物拍卖企业的工作人员，有下列行为之一的，依法给予处分；情节严重的，依法开除公职或者吊销其从业资格证书："},{"i":95,"n":"第九十五条","txt":"单位违反本法规定受到行政处罚，情节严重的，对单位直接负责的主管人员和其他直接责任人员处五千元以上五万元以下的罚款。"},{"i":96,"n":"第九十六条","txt":"违反本法规定，损害他人民事权益的，依法承担民事责任；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":97,"n":"第九十七条","txt":"县级以上人民政府文物行政部门依法实施监督检查，可以采取下列措施："},{"i":98,"n":"第九十八条","txt":"监察委员会、人民法院、人民检察院、公安机关、海关、市场监督管理部门和海上执法机关依法没收的文物应当登记造册，妥善保管，结案后无偿移交文物行政部门，由文物行政部门指定的国有文物收藏单位收藏。"},{"i":99,"n":"第九十九条","txt":"因违反本法规定造成文物严重损害或者存在严重损害风险，致使社会公共利益受到侵害的，人民检察院可以依照有关诉讼法的规定提起公益诉讼。"},{"i":100,"n":"第一百条","txt":"文物保护有关行政许可的条件、期限等，本法未作规定的，适用《中华人民共和国行政许可法》和有关法律、行政法规的规定。"},{"i":101,"n":"第一百零一条","txt":"本法自2025年3月1日起施行。"}],"qiangzhiguanlifa":[{"i":1,"n":"第一条","txt":"为了加强枪支管理，维护社会治安秩序，保障公共安全，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的枪支管理，适用本法。"},{"i":3,"n":"第三条","txt":"国家严格管制枪支。禁止任何单位或者个人违反法律规定持有、制造（包括变造、装配）、买卖、运输、出租、出借枪支。"},{"i":4,"n":"第四条","txt":"国务院公安部门主管全国的枪支管理工作。县级以上地方各级人民政府公安机关主管本行政区域内的枪支管理工作。上级人民政府公安机关监督下级人民政府公安机关的枪支管理工作。"},{"i":5,"n":"第五条","txt":"公安机关、国家安全机关、监狱、劳动教养机关的人民警察，人民法院的司法警察，人民检察院的司法警察和担负案件侦查任务的检察人员，海关的缉私人员，在依法履行职责时确有必要使用枪支的，可以配备公务用枪。"},{"i":6,"n":"第六条","txt":"下列单位可以配置民用枪支："},{"i":7,"n":"第七条","txt":"配备公务用枪，由国务院公安部门或者省级人民政府公安机关审批。"},{"i":8,"n":"第八条","txt":"专门从事射击竞技体育运动的单位配置射击运动枪支，由国务院体育行政主管部门提出，由国务院公安部门审批。营业性射击场配置射击运动枪支，由省级人民政府公安机关报国务院公安部门批准。"},{"i":9,"n":"第九条","txt":"狩猎场配置猎枪，凭省级以上人民政府林业行政主管部门的批准文件，报省级以上人民政府公安机关审批，由设区的市级人民政府公安机关核发民用枪支配购证件。"},{"i":10,"n":"第十条","txt":"野生动物保护、饲养、科研单位申请配置猎枪、麻醉注射枪的，应当凭其所在地的县级人民政府野生动物行政主管部门核发的狩猎证或者特许猎捕证和单位营业执照，向所在地的县级人民政府公安机关提出；猎民申请配置猎枪的，应当凭其所在地的县级人民政府野生动物行政主管部门核发的狩猎证和个人身份证件，向所在地的县级人民政府公安机关提出；牧民申请配置猎枪的，应当凭个人身份证件，向所在地的县级人民政府公安机关提出。"},{"i":11,"n":"第十一条","txt":"配购猎枪、麻醉注射枪的单位和个人，必须在配购枪支后三十日内向核发民用枪支配购证件的公安机关申请领取民用枪支持枪证件。"},{"i":12,"n":"第十二条","txt":"营业性射击场、狩猎场配置的民用枪支不得携带出营业性射击场、狩猎场。"},{"i":13,"n":"第十三条","txt":"国家对枪支的制造、配售实行特别许可制度。未经许可，任何单位或者个人不得制造、买卖枪支。"},{"i":14,"n":"第十四条","txt":"公务用枪，由国家指定的企业制造。"},{"i":15,"n":"第十五条","txt":"制造民用枪支的企业，由国务院有关主管部门提出，由国务院公安部门确定。"},{"i":16,"n":"第十六条","txt":"国家对制造、配售民用枪支的数量，实行限额管理。"},{"i":17,"n":"第十七条","txt":"制造民用枪支的企业不得超过限额制造民用枪支，所制造的民用枪支必须全部交由指定的民用枪支配售企业配售，不得自行销售。配售民用枪支的企业应当在配售限额内，配售指定的企业制造的民用枪支。"},{"i":18,"n":"第十八条","txt":"制造民用枪支的企业，必须严格按照国家规定的技术标准制造民用枪支，不得改变民用枪支的性能和结构；必须在民用枪支指定部位铸印制造厂的厂名、枪种代码和国务院公安部门统一编制的枪支序号，不得制造无号、重号、假号的民用枪支。"},{"i":19,"n":"第十九条","txt":"配售民用枪支，必须核对配购证件，严格按照配购证件载明的品种、型号和数量配售；配售弹药，必须核对持枪证件。民用枪支配售企业必须按照国务院公安部门的规定建立配售帐册，长期保管备查。"},{"i":20,"n":"第二十条","txt":"公安机关对制造、配售民用枪支的企业制造、配售、储存和帐册登记等情况，必须进行定期检查；必要时，可以派专人驻厂对制造企业进行监督、检查。"},{"i":21,"n":"第二十一条","txt":"民用枪支的研制和定型，由国务院有关业务主管部门会同国务院公安部门组织实施。"},{"i":22,"n":"第二十二条","txt":"禁止制造、销售仿真枪。"},{"i":23,"n":"第二十三条","txt":"配备、配置枪支的单位和个人必须妥善保管枪支，确保枪支安全。"},{"i":24,"n":"第二十四条","txt":"使用枪支的人员，必须掌握枪支的性能，遵守使用枪支的有关规定，保证枪支的合法、安全使用。使用公务用枪的人员，必须经过专门培训。"},{"i":25,"n":"第二十五条","txt":"配备、配置枪支的单位和个人必须遵守下列规定："},{"i":26,"n":"第二十六条","txt":"配备公务用枪的人员不再符合持枪条件时，由所在单位收回枪支和持枪证件。"},{"i":27,"n":"第二十七条","txt":"不符合国家技术标准、不能安全使用的枪支，应当报废。配备、持有枪支的单位和个人应当将报废的枪支连同持枪证件上缴核发持枪证件的公安机关；未及时上缴的，由公安机关收缴。报废的枪支应当及时销毁。"},{"i":28,"n":"第二十八条","txt":"国家对枪支实行查验制度。持有枪支的单位和个人，应当在公安机关指定的时间、地点接受查验。公安机关在查验时，必须严格审查持枪单位和个人是否符合本法规定的条件，检查枪支状况及使用情况；对违法使用枪支、不符合持枪条件或者枪支应当报废的，必须收缴枪支和持枪证件。拒不接受查验的，枪支和持枪证件由公安机关收缴。"},{"i":29,"n":"第二十九条","txt":"为了维护社会治安秩序的特殊需要，经国务院公安部门批准，县级以上地方各级人民政府公安机关可以对局部地区合法配备、配置的枪支采取集中保管等特别管制措施。"},{"i":30,"n":"第三十条","txt":"任何单位或者个人未经许可，不得运输枪支。需要运输枪支的，必须向公安机关如实申报运输枪支的品种、数量和运输的路线、方式，领取枪支运输许可证件。在本省、自治区、直辖市内运输的，向运往地设区的市级人民政府公安机关申请领取枪支运输许可证件；跨省、自治区、直辖市运输的，向运往地省级人民政府公安机关申请领取枪支运输许可证件。"},{"i":31,"n":"第三十一条","txt":"运输枪支必须依照规定使用安全可靠的封闭式运输设备，由专人押运；途中停留住宿的，必须报告当地公安机关。"},{"i":32,"n":"第三十二条","txt":"严禁邮寄枪支，或者在邮寄的物品中夹带枪支。"},{"i":33,"n":"第三十三条","txt":"国家严格管理枪支的入境和出境。任何单位或者个人未经许可，不得私自携带枪支入境、出境。"},{"i":34,"n":"第三十四条","txt":"外国驻华外交代表机构、领事机构的人员携带枪支入境，必须事先报经中华人民共和国外交部批准；携带枪支出境，应当事先照会中华人民共和国外交部，办理有关手续。"},{"i":35,"n":"第三十五条","txt":"外国体育代表团入境参加射击竞技体育活动，或者中国体育代表团出境参加射击竞技体育活动，需要携带射击运动枪支入境、出境的，必须经国务院体育行政主管部门批准。"},{"i":36,"n":"第三十六条","txt":"本法第三十四条、第三十五条规定以外的其他人员携带枪支入境、出境，应当事先经国务院公安部门批准。"},{"i":37,"n":"第三十七条","txt":"经批准携带枪支入境的，入境时，应当凭批准文件在入境地边防检查站办理枪支登记，申请领取枪支携运许可证件，向海关申报，海关凭枪支携运许可证件放行；到达目的地后，凭枪支携运许可证件向设区的市级人民政府公安机关申请换发持枪证件。"},{"i":38,"n":"第三十八条","txt":"外国交通运输工具携带枪支入境或者过境的，交通运输工具负责人必须向边防检查站申报，由边防检查站加封，交通运输工具出境时予以启封。"},{"i":39,"n":"第三十九条","txt":"违反本法规定，未经许可制造、买卖或者运输枪支的，依照刑法有关规定追究刑事责任。"},{"i":40,"n":"第四十条","txt":"依法被指定、确定的枪支制造企业、销售企业，违反本法规定，有下列行为之一的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员依照刑法有关规定追究刑事责任；公安机关可以责令其停业整顿或者吊销其枪支制造许可证件、枪支配售许可证件："},{"i":41,"n":"第四十一条","txt":"违反本法规定，非法持有、私藏枪支的，非法运输、携带枪支入境、出境的，依照刑法有关规定追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"违反本法规定，运输枪支未使用安全可靠的运输设备、不设专人押运、枪支弹药未分开运输或者运输途中停留住宿不报告公安机关，情节严重的，依照刑法有关规定追究刑事责任；未构成犯罪的，由公安机关对直接责任人员处十五日以下拘留。"},{"i":43,"n":"第四十三条","txt":"违反枪支管理规定，出租、出借公务用枪的，依照刑法有关规定处罚。"},{"i":44,"n":"第四十四条","txt":"违反本法规定，有下列行为之一的，由公安机关对个人或者单位负有直接责任的主管人员和其他直接责任人员处警告或者十五日以下拘留；构成犯罪的，依法追究刑事责任："},{"i":45,"n":"第四十五条","txt":"公安机关工作人员有下列行为之一的，依法追究刑事责任；未构成犯罪的，依法给予行政处分："},{"i":46,"n":"第四十六条","txt":"本法所称枪支，是指以火药或者压缩气体等为动力，利用管状器具发射金属弹丸或者其他物质，足以致人伤亡或者丧失知觉的各种枪支。"},{"i":47,"n":"第四十七条","txt":"单位和个人为开展游艺活动，可以配置口径不超过4.5毫米的气步枪。具体管理办法由国务院公安部门制定。"},{"i":48,"n":"第四十八条","txt":"制造、配售、运输枪支的主要零部件和用于枪支的弹药，适用本法的有关规定。"},{"i":49,"n":"第四十九条","txt":"枪支管理证件由国务院公安部门制定。"},{"i":50,"n":"第五十条","txt":"本法自1996年10月1日起施行。"}],"heanquanfa":[{"i":1,"n":"第一条","txt":"为了保障核安全，预防与应对核事故，安全利用核能，保护公众和从业人员的安全与健康，保护生态环境，促进经济社会可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域内，对核设施、核材料及相关放射性废物采取充分的预防、保护、缓解和监管等安全措施，防止由于技术原因、人为原因或者自然灾害造成核事故，最大限度减轻核事故情况下的放射性后果的活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家坚持理性、协调、并进的核安全观，加强核安全能力建设，保障核事业健康发展。"},{"i":4,"n":"第四条","txt":"从事核事业必须遵循确保安全的方针。"},{"i":5,"n":"第五条","txt":"核设施营运单位对核安全负全面责任。"},{"i":6,"n":"第六条","txt":"国务院核安全监督管理部门负责核安全的监督管理。"},{"i":7,"n":"第七条","txt":"国务院核安全监督管理部门会同国务院有关部门编制国家核安全规划，报国务院批准后组织实施。"},{"i":8,"n":"第八条","txt":"国家坚持从高从严建立核安全标准体系。"},{"i":9,"n":"第九条","txt":"国家制定核安全政策，加强核安全文化建设。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持核安全相关科学技术的研究、开发和利用，加强知识产权保护，注重核安全人才的培养。"},{"i":11,"n":"第十一条","txt":"任何单位和个人不得危害核设施、核材料安全。"},{"i":12,"n":"第十二条","txt":"国家加强对核设施、核材料的安全保卫工作。"},{"i":13,"n":"第十三条","txt":"国家组织开展与核安全有关的国际交流与合作，完善核安全国际合作机制，防范和应对核恐怖主义威胁，履行中华人民共和国缔结或者参加的国际公约所规定的义务。"},{"i":14,"n":"第十四条","txt":"国家对核设施的选址、建设进行统筹规划，科学论证，合理布局。"},{"i":15,"n":"第十五条","txt":"核设施营运单位应当具备保障核设施安全运行的能力，并符合下列条件："},{"i":16,"n":"第十六条","txt":"核设施营运单位应当依照法律、行政法规和标准的要求，设置核设施纵深防御体系，有效防范技术原因、人为原因和自然灾害造成的威胁，确保核设施安全。"},{"i":17,"n":"第十七条","txt":"核设施营运单位和为其提供设备、工程以及服务等的单位应当建立并实施质量保证体系，有效保证设备、工程和服务等的质量，确保设备的性能满足核安全标准的要求，工程和服务等满足核安全相关要求。"},{"i":18,"n":"第十八条","txt":"核设施营运单位应当严格控制辐射照射，确保有关人员免受超过国家规定剂量限值的辐射照射，确保辐射照射保持在合理、可行和尽可能低的水平。"},{"i":19,"n":"第十九条","txt":"核设施营运单位应当对核设施周围环境中所含的放射性核素的种类、浓度以及核设施流出物中的放射性核素总量实施监测，并定期向国务院环境保护主管部门和所在地省、自治区、直辖市人民政府环境保护主管部门报告监测结果。"},{"i":20,"n":"第二十条","txt":"核设施营运单位应当按照国家有关规定，制定培训计划，对从业人员进行核安全教育和技能培训并进行考核。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府应当对国家规划确定的核动力厂等重要核设施的厂址予以保护，在规划期内不得变更厂址用途。"},{"i":22,"n":"第二十二条","txt":"国家建立核设施安全许可制度。"},{"i":23,"n":"第二十三条","txt":"核设施营运单位应当对地质、地震、气象、水文、环境和人口分布等因素进行科学评估，在满足核安全技术评价要求的前提下，向国务院核安全监督管理部门提交核设施选址安全分析报告，经审查符合核安全要求后，取得核设施场址选择审查意见书。"},{"i":24,"n":"第二十四条","txt":"核设施设计应当符合核安全标准，采用科学合理的构筑物、系统和设备参数与技术要求，提供多样保护和多重屏障，确保核设施运行可靠、稳定和便于操作，满足核安全要求。"},{"i":25,"n":"第二十五条","txt":"核设施建造前，核设施营运单位应当向国务院核安全监督管理部门提出建造申请，并提交下列材料："},{"i":26,"n":"第二十六条","txt":"核设施营运单位取得核设施建造许可证后，应当确保核设施整体性能满足核安全标准的要求。"},{"i":27,"n":"第二十七条","txt":"核设施首次装投料前，核设施营运单位应当向国务院核安全监督管理部门提出运行申请，并提交下列材料："},{"i":28,"n":"第二十八条","txt":"核设施运行许可证有效期届满需要继续运行的，核设施营运单位应当于有效期届满前五年，向国务院核安全监督管理部门提出延期申请，并对其是否符合核安全标准进行论证、验证，经审查批准后，方可继续运行。"},{"i":29,"n":"第二十九条","txt":"核设施终止运行后，核设施营运单位应当采取安全的方式进行停闭管理，保证停闭期间的安全，确保退役所需的基本功能、技术人员和文件。"},{"i":30,"n":"第三十条","txt":"核设施退役前，核设施营运单位应当向国务院核安全监督管理部门提出退役申请，并提交下列材料："},{"i":31,"n":"第三十一条","txt":"进口核设施，应当满足中华人民共和国有关核安全法律、行政法规和标准的要求，并报国务院核安全监督管理部门审查批准。"},{"i":32,"n":"第三十二条","txt":"国务院核安全监督管理部门应当依照法定条件和程序，对核设施安全许可申请组织安全技术审查，满足核安全要求的，在技术审查完成之日起二十日内，依法作出准予许可的决定。"},{"i":33,"n":"第三十三条","txt":"国务院核安全监督管理部门组织安全技术审查时，应当委托与许可申请单位没有利益关系的技术支持单位进行技术审评。受委托的技术支持单位应当对其技术评价结论的真实性、准确性负责。"},{"i":34,"n":"第三十四条","txt":"国务院核安全监督管理部门成立核安全专家委员会，为核安全决策提供咨询意见。"},{"i":35,"n":"第三十五条","txt":"国家建立核设施营运单位核安全报告制度，具体办法由国务院有关部门制定。"},{"i":36,"n":"第三十六条","txt":"为核设施提供核安全设备设计、制造、安装和无损检验服务的单位，应当向国务院核安全监督管理部门申请许可。境外机构为境内核设施提供核安全设备设计、制造、安装和无损检验服务的，应当向国务院核安全监督管理部门申请注册。"},{"i":37,"n":"第三十七条","txt":"核设施操纵人员以及核安全设备焊接人员、无损检验人员等特种工艺人员应当按照国家规定取得相应资格证书。"},{"i":38,"n":"第三十八条","txt":"核设施营运单位和其他有关单位持有核材料，应当按照规定的条件依法取得许可，并采取下列措施，防止核材料被盗、破坏、丢失、非法转让和使用，保障核材料的安全与合法利用："},{"i":39,"n":"第三十九条","txt":"产生、贮存、运输、后处理乏燃料的单位应当采取措施确保乏燃料的安全，并对持有的乏燃料承担核安全责任。"},{"i":40,"n":"第四十条","txt":"放射性废物应当实行分类处置。"},{"i":41,"n":"第四十一条","txt":"核设施营运单位、放射性废物处理处置单位应当对放射性废物进行减量化、无害化处理、处置，确保永久安全。"},{"i":42,"n":"第四十二条","txt":"国务院核工业主管部门会同国务院有关部门和省、自治区、直辖市人民政府编制低、中水平放射性废物处置场所的选址规划，报国务院批准后组织实施。"},{"i":43,"n":"第四十三条","txt":"国家建立放射性废物管理许可制度。"},{"i":44,"n":"第四十四条","txt":"核设施营运单位应当对其产生的放射性固体废物和不能经净化排放的放射性废液进行处理，使其转变为稳定的、标准化的固体废物后，及时送交放射性废物处置单位处置。"},{"i":45,"n":"第四十五条","txt":"放射性废物处置单位应当按照国家放射性污染防治标准的要求，对其接收的放射性废物进行处置。"},{"i":46,"n":"第四十六条","txt":"国家建立放射性废物处置设施关闭制度。"},{"i":47,"n":"第四十七条","txt":"放射性废物处置设施关闭前，放射性废物处置单位应当编制放射性废物处置设施关闭安全监护计划，报国务院核安全监督管理部门批准。"},{"i":48,"n":"第四十八条","txt":"核设施营运单位应当按照国家规定缴纳乏燃料处理处置费用，列入生产成本。"},{"i":49,"n":"第四十九条","txt":"国家对核材料、放射性废物的运输实行分类管理，采取有效措施，保障运输安全。"},{"i":50,"n":"第五十条","txt":"国家保障核材料、放射性废物的公路、铁路、水路等运输，国务院有关部门应当加强对公路、铁路、水路等运输的管理，制定具体的保障措施。"},{"i":51,"n":"第五十一条","txt":"国务院核工业主管部门负责协调乏燃料运输管理活动，监督有关保密措施。"},{"i":52,"n":"第五十二条","txt":"核材料、放射性废物的托运人应当在运输中采取有效的辐射防护和安全保卫措施，对运输中的核安全负责。"},{"i":53,"n":"第五十三条","txt":"通过公路、铁路、水路等运输核材料、放射性废物，本法没有规定的，适用相关法律、行政法规和规章关于放射性物品运输、危险货物运输的规定。"},{"i":54,"n":"第五十四条","txt":"国家设立核事故应急协调委员会，组织、协调全国的核事故应急管理工作。"},{"i":55,"n":"第五十五条","txt":"国务院核工业主管部门承担国家核事故应急协调委员会日常工作，牵头制定国家核事故应急预案，经国务院批准后组织实施。国家核事故应急协调委员会成员单位根据国家核事故应急预案部署，制定本单位核事故应急预案，报国务院核工业主管部门备案。"},{"i":56,"n":"第五十六条","txt":"核设施营运单位应当按照应急预案，配备应急设备，开展应急工作人员培训和演练，做好应急准备。"},{"i":57,"n":"第五十七条","txt":"国家建立核事故应急准备金制度，保障核事故应急准备与响应工作所需经费。核事故应急准备金管理办法，由国务院制定。"},{"i":58,"n":"第五十八条","txt":"国家对核事故应急实行分级管理。"},{"i":59,"n":"第五十九条","txt":"国家核事故应急协调委员会按照国家核事故应急预案部署，组织协调国务院有关部门、地方人民政府、核设施营运单位实施核事故应急救援工作。"},{"i":60,"n":"第六十条","txt":"国务院核工业主管部门或者省、自治区、直辖市人民政府指定的部门负责发布核事故应急信息。"},{"i":61,"n":"第六十一条","txt":"各级人民政府及其有关部门、核设施营运单位等应当按照国务院有关规定和授权，组织开展核事故后的恢复行动、损失评估等工作。"},{"i":62,"n":"第六十二条","txt":"核材料、放射性废物运输的应急应当纳入所经省、自治区、直辖市场外核事故应急预案或者辐射应急预案。发生核事故时，由事故发生地省、自治区、直辖市人民政府负责应急响应。"},{"i":63,"n":"第六十三条","txt":"国务院有关部门及核设施所在地省、自治区、直辖市人民政府指定的部门应当在各自职责范围内依法公开核安全相关信息。"},{"i":64,"n":"第六十四条","txt":"核设施营运单位应当公开本单位核安全管理制度和相关文件、核设施安全状况、流出物和周围环境辐射监测数据、年度核安全报告等信息。具体办法由国务院核安全监督管理部门制定。"},{"i":65,"n":"第六十五条","txt":"对依法公开的核安全信息，应当通过政府公告、网站以及其他便于公众知晓的方式，及时向社会公开。"},{"i":66,"n":"第六十六条","txt":"核设施营运单位应当就涉及公众利益的重大核安全事项通过问卷调查、听证会、论证会、座谈会，或者采取其他形式征求利益相关方的意见，并以适当形式反馈。"},{"i":67,"n":"第六十七条","txt":"核设施营运单位应当采取下列措施，开展核安全宣传活动："},{"i":68,"n":"第六十八条","txt":"公民、法人和其他组织有权对存在核安全隐患或者违反核安全法律、行政法规的行为，向国务院核安全监督管理部门或者其他有关部门举报。"},{"i":69,"n":"第六十九条","txt":"涉及国家秘密、商业秘密和个人信息的政府信息公开，按照国家有关规定执行。"},{"i":70,"n":"第七十条","txt":"国家建立核安全监督检查制度。"},{"i":71,"n":"第七十一条","txt":"国务院核安全监督管理部门和其他有关部门应当加强核安全监管能力建设，提高核安全监管水平。"},{"i":72,"n":"第七十二条","txt":"国务院核安全监督管理部门和其他有关部门进行核安全监督检查时，有权采取下列措施："},{"i":73,"n":"第七十三条","txt":"对国务院核安全监督管理部门和其他有关部门依法进行的监督检查，从事核安全活动的单位应当予以配合，如实说明情况，提供必要资料，不得拒绝、阻挠。"},{"i":74,"n":"第七十四条","txt":"核安全监督检查人员应当忠于职守，勤勉尽责，秉公执法。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，有下列情形之一的，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":76,"n":"第七十六条","txt":"违反本法规定，危害核设施、核材料安全，或者编造、散布核安全虚假信息，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，有下列情形之一的，由国务院核安全监督管理部门或者其他有关部门责令改正，给予警告；情节严重的，处二十万元以上一百万元以下的罚款；拒不改正的，责令停止建设或者停产整顿："},{"i":78,"n":"第七十八条","txt":"违反本法规定，在规划限制区内建设可能威胁核设施安全的易燃、易爆、腐蚀性物品的生产、贮存设施或者人口密集场所的，由国务院核安全监督管理部门责令限期拆除，恢复原状，处十万元以上五十万元以下的罚款。"},{"i":79,"n":"第七十九条","txt":"违反本法规定，核设施营运单位有下列情形之一的，由国务院核安全监督管理部门责令改正，处一百万元以上五百万元以下的罚款；拒不改正的，责令停止建设或者停产整顿；有违法所得的，没收违法所得；造成环境污染的，责令限期采取治理措施消除污染，逾期不采取措施的，指定有能力的单位代为履行，所需费用由污染者承担；对直接负责的主管人员和其他直接责任人员，处五万元以上二十万元以下的罚款："},{"i":80,"n":"第八十条","txt":"违反本法规定，核设施营运单位有下列情形之一的，由国务院核安全监督管理部门责令改正，给予警告；情节严重的，处五十万元以上二百万元以下的罚款；造成环境污染的，责令限期采取治理措施消除污染，逾期不采取措施的，指定有能力的单位代为履行，所需费用由污染者承担："},{"i":81,"n":"第八十一条","txt":"违反本法规定，核设施营运单位未对核设施周围环境中所含的放射性核素的种类、浓度或者核设施流出物中的放射性核素总量实施监测，或者未按照规定报告监测结果的，由国务院环境保护主管部门或者所在地省、自治区、直辖市人民政府环境保护主管部门责令改正，处十万元以上五十万元以下的罚款。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，受委托的技术支持单位出具虚假技术评价结论的，由国务院核安全监督管理部门处二十万元以上一百万元以下的罚款；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员处十万元以上二十万元以下的罚款。"},{"i":83,"n":"第八十三条","txt":"违反本法规定，有下列情形之一的，由国务院核安全监督管理部门责令改正，处五十万元以上一百万元以下的罚款；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员处二万元以上十万元以下的罚款："},{"i":84,"n":"第八十四条","txt":"违反本法规定，核设施营运单位或者核安全设备制造、安装、无损检验单位聘用未取得相应资格证书的人员从事与核设施安全专业技术有关的工作的，由国务院核安全监督管理部门责令改正，处十万元以上五十万元以下的罚款；拒不改正的，暂扣或者吊销许可证，对直接负责的主管人员和其他直接责任人员处二万元以上十万元以下的罚款。"},{"i":85,"n":"第八十五条","txt":"违反本法规定，未经许可持有核材料的，由国务院核工业主管部门没收非法持有的核材料，并处十万元以上五十万元以下的罚款；有违法所得的，没收违法所得。"},{"i":86,"n":"第八十六条","txt":"违反本法规定，有下列情形之一的，由国务院核安全监督管理部门责令改正，处十万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款；造成环境污染的，责令限期采取治理措施消除污染，逾期不采取措施的，指定有能力的单位代为履行，所需费用由污染者承担："},{"i":87,"n":"第八十七条","txt":"违反本法规定，核设施营运单位有下列情形之一的，由国务院核安全监督管理部门责令改正，处十万元以上五十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，处二万元以上五万元以下的罚款："},{"i":88,"n":"第八十八条","txt":"违反本法规定，核设施营运单位未按照规定公开相关信息的，由国务院核安全监督管理部门责令改正；拒不改正的，处十万元以上五十万元以下的罚款。"},{"i":89,"n":"第八十九条","txt":"违反本法规定，对国务院核安全监督管理部门或者其他有关部门依法进行的监督检查，从事核安全活动的单位拒绝、阻挠的，由国务院核安全监督管理部门或者其他有关部门责令改正，可以处十万元以上五十万元以下的罚款；拒不改正的，暂扣或者吊销其许可证；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":90,"n":"第九十条","txt":"因核事故造成他人人身伤亡、财产损失或者环境损害的，核设施营运单位应当按照国家核损害责任制度承担赔偿责任，但能够证明损害是因战争、武装冲突、暴乱等情形造成的除外。"},{"i":91,"n":"第九十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":92,"n":"第九十二条","txt":"军工、军事核安全，由国务院、中央军事委员会依照本法规定的原则另行规定。"},{"i":93,"n":"第九十三条","txt":"本法中下列用语的含义："},{"i":94,"n":"第九十四条","txt":"本法自2018年1月1日起施行。"}],"danganfa":[{"i":1,"n":"第一条","txt":"为了加强档案管理，规范档案收集、整理工作，有效保护和利用档案，提高档案信息化建设水平，推进国家治理体系和治理能力现代化，为中国特色社会主义事业服务，制定本法。"},{"i":2,"n":"第二条","txt":"从事档案收集、整理、保护、利用及其监督管理活动，适用本法。"},{"i":3,"n":"第三条","txt":"坚持中国共产党对档案工作的领导。各级人民政府应当加强档案工作，把档案事业纳入国民经济和社会发展规划，将档案事业发展经费列入政府预算，确保档案事业发展与国民经济和社会发展水平相适应。"},{"i":4,"n":"第四条","txt":"档案工作实行统一领导、分级管理的原则，维护档案完整与安全，便于社会各方面的利用。"},{"i":5,"n":"第五条","txt":"一切国家机关、武装力量、政党、团体、企业事业单位和公民都有保护档案的义务，享有依法利用档案的权利。"},{"i":6,"n":"第六条","txt":"国家鼓励和支持档案科学研究和技术创新，促进科技成果在档案收集、整理、保护、利用等方面的转化和应用，推动档案科技进步。"},{"i":7,"n":"第七条","txt":"国家鼓励社会力量参与和支持档案事业的发展。"},{"i":8,"n":"第八条","txt":"国家档案主管部门主管全国的档案工作，负责全国档案事业的统筹规划和组织协调，建立统一制度，实行监督和指导。"},{"i":9,"n":"第九条","txt":"机关、团体、企业事业单位和其他组织应当确定档案机构或者档案工作人员负责管理本单位的档案，并对所属单位的档案工作实行监督和指导。"},{"i":10,"n":"第十条","txt":"中央和县级以上地方各级各类档案馆，是集中管理档案的文化事业机构，负责收集、整理、保管和提供利用各自分管范围内的档案。"},{"i":11,"n":"第十一条","txt":"国家加强档案工作人才培养和队伍建设，提高档案工作人员业务素质。"},{"i":12,"n":"第十二条","txt":"按照国家规定应当形成档案的机关、团体、企业事业单位和其他组织，应当建立档案工作责任制，依法健全档案管理制度。"},{"i":13,"n":"第十三条","txt":"直接形成的对国家和社会具有保存价值的下列材料，应当纳入归档范围："},{"i":14,"n":"第十四条","txt":"应当归档的材料，按照国家有关规定定期向本单位档案机构或者档案工作人员移交，集中管理，任何个人不得拒绝归档或者据为己有。"},{"i":15,"n":"第十五条","txt":"机关、团体、企业事业单位和其他组织应当按照国家有关规定，定期向档案馆移交档案，档案馆不得拒绝接收。"},{"i":16,"n":"第十六条","txt":"机关、团体、企业事业单位和其他组织发生机构变动或者撤销、合并等情形时，应当按照规定向有关单位或者档案馆移交档案。"},{"i":17,"n":"第十七条","txt":"档案馆除按照国家有关规定接收移交的档案外，还可以通过接受捐献、购买、代存等方式收集档案。"},{"i":18,"n":"第十八条","txt":"博物馆、图书馆、纪念馆等单位保存的文物、文献信息同时是档案的，依照有关法律、行政法规的规定，可以由上述单位自行管理。"},{"i":19,"n":"第十九条","txt":"档案馆以及机关、团体、企业事业单位和其他组织的档案机构应当建立科学的管理制度，便于对档案的利用；按照国家有关规定配置适宜档案保存的库房和必要的设施、设备，确保档案的安全；采用先进技术，实现档案管理的现代化。"},{"i":20,"n":"第二十条","txt":"涉及国家秘密的档案的管理和利用，密级的变更和解密，应当依照有关保守国家秘密的法律、行政法规规定办理。"},{"i":21,"n":"第二十一条","txt":"鉴定档案保存价值的原则、保管期限的标准以及销毁档案的程序和办法，由国家档案主管部门制定。"},{"i":22,"n":"第二十二条","txt":"非国有企业、社会服务机构等单位和个人形成的档案，对国家和社会具有重要保存价值或者应当保密的，档案所有者应当妥善保管。对保管条件不符合要求或者存在其他原因可能导致档案严重损毁和不安全的，省级以上档案主管部门可以给予帮助，或者经协商采取指定档案馆代为保管等确保档案完整和安全的措施；必要时，可以依法收购或者征购。"},{"i":23,"n":"第二十三条","txt":"禁止买卖属于国家所有的档案。"},{"i":24,"n":"第二十四条","txt":"档案馆和机关、团体、企业事业单位以及其他组织委托档案整理、寄存、开发利用和数字化等服务的，应当与符合条件的档案服务企业签订委托协议，约定服务的范围、质量和技术标准等内容，并对受托方进行监督。"},{"i":25,"n":"第二十五条","txt":"属于国家所有的档案和本法第二十二条规定的档案及其复制件，禁止擅自运送、邮寄、携带出境或者通过互联网传输出境。确需出境的，按照国家有关规定办理审批手续。"},{"i":26,"n":"第二十六条","txt":"国家档案主管部门应当建立健全突发事件应对活动相关档案收集、整理、保护、利用工作机制。"},{"i":27,"n":"第二十七条","txt":"县级以上各级档案馆的档案，应当自形成之日起满二十五年向社会开放。经济、教育、科技、文化等类档案，可以少于二十五年向社会开放；涉及国家安全或者重大利益以及其他到期不宜开放的档案，可以多于二十五年向社会开放。国家鼓励和支持其他档案馆向社会开放档案。档案开放的具体办法由国家档案主管部门制定，报国务院批准。"},{"i":28,"n":"第二十八条","txt":"档案馆应当通过其网站或者其他方式定期公布开放档案的目录，不断完善利用规则，创新服务形式，强化服务功能，提高服务水平，积极为档案的利用创造条件，简化手续，提供便利。"},{"i":29,"n":"第二十九条","txt":"机关、团体、企业事业单位和其他组织以及公民根据经济建设、国防建设、教学科研和其他工作的需要，可以按照国家有关规定，利用档案馆未开放的档案以及有关机关、团体、企业事业单位和其他组织保存的档案。"},{"i":30,"n":"第三十条","txt":"馆藏档案的开放审核，由档案馆会同档案形成单位或者移交单位共同负责。尚未移交进馆档案的开放审核，由档案形成单位或者保管单位负责，并在移交时附具意见。"},{"i":31,"n":"第三十一条","txt":"向档案馆移交、捐献、寄存档案的单位和个人，可以优先利用该档案，并可以对档案中不宜向社会开放的部分提出限制利用的意见，档案馆应当予以支持，提供便利。"},{"i":32,"n":"第三十二条","txt":"属于国家所有的档案，由国家授权的档案馆或者有关机关公布；未经档案馆或者有关机关同意，任何单位和个人无权公布。非国有企业、社会服务机构等单位和个人形成的档案，档案所有者有权公布。"},{"i":33,"n":"第三十三条","txt":"档案馆应当根据自身条件，为国家机关制定法律、法规、政策和开展有关问题研究，提供支持和便利。"},{"i":34,"n":"第三十四条","txt":"国家鼓励档案馆开发利用馆藏档案，通过开展专题展览、公益讲座、媒体宣传等活动，进行爱国主义、集体主义、中国特色社会主义教育，传承发展中华优秀传统文化，继承革命文化，发展社会主义先进文化，增强文化自信，弘扬社会主义核心价值观。"},{"i":35,"n":"第三十五条","txt":"各级人民政府应当将档案信息化纳入信息化发展规划，保障电子档案、传统载体档案数字化成果等档案数字资源的安全保存和有效利用。"},{"i":36,"n":"第三十六条","txt":"机关、团体、企业事业单位和其他组织应当积极推进电子档案管理信息系统建设，与办公自动化系统、业务系统等相互衔接。"},{"i":37,"n":"第三十七条","txt":"电子档案应当来源可靠、程序规范、要素合规。"},{"i":38,"n":"第三十八条","txt":"国家鼓励和支持档案馆和机关、团体、企业事业单位以及其他组织推进传统载体档案数字化。已经实现数字化的，应当对档案原件妥善保管。"},{"i":39,"n":"第三十九条","txt":"电子档案应当通过符合安全管理要求的网络或者存储介质向档案馆移交。"},{"i":40,"n":"第四十条","txt":"档案馆负责档案数字资源的收集、保存和提供利用。有条件的档案馆应当建设数字档案馆。"},{"i":41,"n":"第四十一条","txt":"国家推进档案信息资源共享服务平台建设，推动档案数字资源跨区域、跨部门共享利用。"},{"i":42,"n":"第四十二条","txt":"档案主管部门依照法律、行政法规有关档案管理的规定，可以对档案馆和机关、团体、企业事业单位以及其他组织的下列情况进行检查："},{"i":43,"n":"第四十三条","txt":"档案主管部门根据违法线索进行检查时，在符合安全保密要求的前提下，可以检查有关库房、设施、设备，查阅有关材料，询问有关人员，记录有关情况，有关单位和个人应当配合。"},{"i":44,"n":"第四十四条","txt":"档案馆和机关、团体、企业事业单位以及其他组织发现本单位存在档案安全隐患的，应当及时采取补救措施，消除档案安全隐患。发生档案损毁、信息泄露等情形的，应当及时向档案主管部门报告。"},{"i":45,"n":"第四十五条","txt":"档案主管部门发现档案馆和机关、团体、企业事业单位以及其他组织存在档案安全隐患的，应当责令限期整改，消除档案安全隐患。"},{"i":46,"n":"第四十六条","txt":"任何单位和个人对档案违法行为，有权向档案主管部门和有关机关举报。"},{"i":47,"n":"第四十七条","txt":"档案主管部门及其工作人员应当按照法定的职权和程序开展监督检查工作，做到科学、公正、严格、高效，不得利用职权牟取利益，不得泄露履职过程中知悉的国家秘密、商业秘密或者个人隐私。"},{"i":48,"n":"第四十八条","txt":"单位或者个人有下列行为之一，由县级以上档案主管部门、有关机关对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":49,"n":"第四十九条","txt":"利用档案馆的档案，有本法第四十八条第一项、第二项、第四项违法行为之一的，由县级以上档案主管部门给予警告，并对单位处一万元以上十万元以下的罚款，对个人处五百元以上五千元以下的罚款。"},{"i":50,"n":"第五十条","txt":"违反本法规定，擅自运送、邮寄、携带或者通过互联网传输禁止出境的档案或者其复制件出境的，由海关或者有关部门予以没收、阻断传输，并对单位处一万元以上十万元以下的罚款，对个人处五百元以上五千元以下的罚款；并将没收、阻断传输的档案或者其复制件移交档案主管部门。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任；造成财产损失或者其他损害的，依法承担民事责任。"},{"i":52,"n":"第五十二条","txt":"中国人民解放军和中国人民武装警察部队的档案工作，由中央军事委员会依照本法制定管理办法。"},{"i":53,"n":"第五十三条","txt":"本法自2021年1月1日起施行。"}],"minbanjiaoyucujinfa":[{"i":1,"n":"第一条","txt":"为实施科教兴国战略，促进民办教育事业的健康发展，维护民办学校和受教育者的合法权益，根据宪法和教育法制定本法。"},{"i":2,"n":"第二条","txt":"国家机构以外的社会组织或者个人，利用非国家财政性经费，面向社会举办学校及其他教育机构的活动，适用本法。本法未作规定的，依照教育法和其他有关教育法律执行。"},{"i":3,"n":"第三条","txt":"民办教育事业属于公益性事业，是社会主义教育事业的组成部分。"},{"i":4,"n":"第四条","txt":"民办学校应当遵守法律、法规，贯彻国家的教育方针，保证教育质量，致力于培养社会主义建设事业的各类人才。"},{"i":5,"n":"第五条","txt":"民办学校与公办学校具有同等的法律地位，国家保障民办学校的办学自主权。"},{"i":6,"n":"第六条","txt":"国家鼓励捐资办学。"},{"i":7,"n":"第七条","txt":"国务院教育行政部门负责全国民办教育工作的统筹规划、综合协调和宏观管理。"},{"i":8,"n":"第八条","txt":"县级以上地方各级人民政府教育行政部门主管本行政区域内的民办教育工作。"},{"i":9,"n":"第九条","txt":"民办学校中的中国共产党基层组织，按照中国共产党章程的规定开展党的活动，加强党的建设。"},{"i":10,"n":"第十条","txt":"举办民办学校的社会组织，应当具有法人资格。"},{"i":11,"n":"第十一条","txt":"设立民办学校应当符合当地教育发展的需求，具备教育法和其他有关法律、法规规定的条件。"},{"i":12,"n":"第十二条","txt":"举办实施学历教育、学前教育、自学考试助学及其他文化教育的民办学校，由县级以上人民政府教育行政部门按照国家规定的权限审批；举办实施以职业技能为主的职业资格培训、职业技能培训的民办学校，由县级以上人民政府人力资源社会保障行政部门按照国家规定的权限审批，并抄送同级教育行政部门备案。"},{"i":13,"n":"第十三条","txt":"申请筹设民办学校，举办者应当向审批机关提交下列材料："},{"i":14,"n":"第十四条","txt":"审批机关应当自受理筹设民办学校的申请之日起三十日内以书面形式作出是否同意的决定。"},{"i":15,"n":"第十五条","txt":"申请正式设立民办学校的，举办者应当向审批机关提交下列材料："},{"i":16,"n":"第十六条","txt":"具备办学条件，达到设置标准的，可以直接申请正式设立，并应当提交本法第十三条和第十五条（三）、（四）、（五）项规定的材料。"},{"i":17,"n":"第十七条","txt":"申请正式设立民办学校的，审批机关应当自受理之日起三个月内以书面形式作出是否批准的决定，并送达申请人；其中申请正式设立民办高等学校的，审批机关也可以自受理之日起六个月内以书面形式作出是否批准的决定，并送达申请人。"},{"i":18,"n":"第十八条","txt":"审批机关对批准正式设立的民办学校发给办学许可证。"},{"i":19,"n":"第十九条","txt":"民办学校的举办者可以自主选择设立非营利性或者营利性民办学校。但是，不得设立实施义务教育的营利性民办学校。"},{"i":20,"n":"第二十条","txt":"民办学校应当设立学校理事会、董事会或者其他形式的决策机构并建立相应的监督机制。"},{"i":21,"n":"第二十一条","txt":"学校理事会或者董事会由举办者或者其代表、校长、教职工代表等人员组成。其中三分之一以上的理事或者董事应当具有五年以上教育教学经验。"},{"i":22,"n":"第二十二条","txt":"学校理事会或者董事会行使下列职权："},{"i":23,"n":"第二十三条","txt":"民办学校的法定代表人由理事长、董事长或者校长担任。"},{"i":24,"n":"第二十四条","txt":"民办学校参照同级同类公办学校校长任职的条件聘任校长，年龄可以适当放宽。"},{"i":25,"n":"第二十五条","txt":"民办学校校长负责学校的教育教学和行政管理工作，行使下列职权："},{"i":26,"n":"第二十六条","txt":"民办学校对招收的学生，根据其类别、修业年限、学业成绩，可以根据国家有关规定发给学历证书、结业证书或者培训合格证书。"},{"i":27,"n":"第二十七条","txt":"民办学校依法通过以教师为主体的教职工代表大会等形式，保障教职工参与民主管理和监督。"},{"i":28,"n":"第二十八条","txt":"民办学校的教师、受教育者与公办学校的教师、受教育者具有同等的法律地位。"},{"i":29,"n":"第二十九条","txt":"民办学校聘任的教师，应当具有国家规定的任教资格。"},{"i":30,"n":"第三十条","txt":"民办学校应当对教师进行思想品德教育和业务培训。"},{"i":31,"n":"第三十一条","txt":"民办学校应当依法保障教职工的工资、福利待遇和其他合法权益，并为教职工缴纳社会保险费。"},{"i":32,"n":"第三十二条","txt":"民办学校教职工在业务培训、职务聘任、教龄和工龄计算、表彰奖励、社会活动等方面依法享有与公办学校教职工同等权利。"},{"i":33,"n":"第三十三条","txt":"民办学校依法保障受教育者的合法权益。"},{"i":34,"n":"第三十四条","txt":"民办学校的受教育者在升学、就业、社会优待以及参加先进评选等方面享有与同级同类公办学校的受教育者同等权利。"},{"i":35,"n":"第三十五条","txt":"民办学校应当依法建立财务、会计制度和资产管理制度，并按照国家有关规定设置会计帐簿。"},{"i":36,"n":"第三十六条","txt":"民办学校对举办者投入民办学校的资产、国有资产、受赠的财产以及办学积累，享有法人财产权。"},{"i":37,"n":"第三十七条","txt":"民办学校存续期间，所有资产由民办学校依法管理和使用，任何组织和个人不得侵占。"},{"i":38,"n":"第三十八条","txt":"民办学校收取费用的项目和标准根据办学成本、市场需求等因素确定，向社会公示，并接受有关主管部门的监督。"},{"i":39,"n":"第三十九条","txt":"民办学校资产的使用和财务管理受审批机关和其他有关部门的监督。"},{"i":40,"n":"第四十条","txt":"教育行政部门及有关部门应当对民办学校的教育教学工作、教师培训工作进行指导。"},{"i":41,"n":"第四十一条","txt":"教育行政部门及有关部门依法对民办学校实行督导，建立民办学校信息公示和信用档案制度，促进提高办学质量；组织或者委托社会中介组织评估办学水平和教育质量，并将评估结果向社会公布。"},{"i":42,"n":"第四十二条","txt":"民办学校的招生简章和广告，应当报审批机关备案。"},{"i":43,"n":"第四十三条","txt":"民办学校侵犯受教育者的合法权益，受教育者及其亲属有权向教育行政部门和其他有关部门申诉，有关部门应当及时予以处理。"},{"i":44,"n":"第四十四条","txt":"国家支持和鼓励社会中介组织为民办学校提供服务。"},{"i":45,"n":"第四十五条","txt":"县级以上各级人民政府可以设立专项资金，用于资助民办学校的发展，奖励和表彰有突出贡献的集体和个人。"},{"i":46,"n":"第四十六条","txt":"县级以上各级人民政府可以采取购买服务、助学贷款、奖助学金和出租、转让闲置的国有资产等措施对民办学校予以扶持；对非营利性民办学校还可以采取政府补贴、基金奖励、捐资激励等扶持措施。"},{"i":47,"n":"第四十七条","txt":"民办学校享受国家规定的税收优惠政策；其中，非营利性民办学校享受与公办学校同等的税收优惠政策。"},{"i":48,"n":"第四十八条","txt":"民办学校依照国家有关法律、法规，可以接受公民、法人或者其他组织的捐赠。"},{"i":49,"n":"第四十九条","txt":"国家鼓励金融机构运用信贷手段，支持民办教育事业的发展。"},{"i":50,"n":"第五十条","txt":"人民政府委托民办学校承担义务教育任务，应当按照委托协议拨付相应的教育经费。"},{"i":51,"n":"第五十一条","txt":"新建、扩建非营利性民办学校，人民政府应当按照与公办学校同等原则，以划拨等方式给予用地优惠。新建、扩建营利性民办学校，人民政府应当按照国家规定供给土地。"},{"i":52,"n":"第五十二条","txt":"国家采取措施，支持和鼓励社会组织和个人到少数民族地区、边远贫困地区举办民办学校，发展教育事业。"},{"i":53,"n":"第五十三条","txt":"民办学校的分立、合并，在进行财务清算后，由学校理事会或者董事会报审批机关批准。"},{"i":54,"n":"第五十四条","txt":"民办学校举办者的变更，须由举办者提出，在进行财务清算后，经学校理事会或者董事会同意，报审批机关核准。"},{"i":55,"n":"第五十五条","txt":"民办学校名称、层次、类别的变更，由学校理事会或者董事会报审批机关批准。"},{"i":56,"n":"第五十六条","txt":"民办学校有下列情形之一的，应当终止："},{"i":57,"n":"第五十七条","txt":"民办学校终止时，应当妥善安置在校学生。实施义务教育的民办学校终止时，审批机关应当协助学校安排学生继续就学。"},{"i":58,"n":"第五十八条","txt":"民办学校终止时，应当依法进行财务清算。"},{"i":59,"n":"第五十九条","txt":"对民办学校的财产按照下列顺序清偿："},{"i":60,"n":"第六十条","txt":"终止的民办学校，由审批机关收回办学许可证和销毁印章，并注销登记。"},{"i":61,"n":"第六十一条","txt":"民办学校在教育活动中违反教育法、教师法规定的，依照教育法、教师法的有关规定给予处罚。"},{"i":62,"n":"第六十二条","txt":"民办学校有下列行为之一的，由县级以上人民政府教育行政部门、人力资源社会保障行政部门或者其他有关部门责令限期改正，并予以警告；有违法所得的，退还所收费用后没收违法所得；情节严重的，责令停止招生、吊销办学许可证；构成犯罪的，依法追究刑事责任："},{"i":63,"n":"第六十三条","txt":"县级以上人民政府教育行政部门、人力资源社会保障行政部门或者其他有关部门有下列行为之一的，由上级机关责令其改正；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予处分；造成经济损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任："},{"i":64,"n":"第六十四条","txt":"违反国家有关规定擅自举办民办学校的，由所在地县级以上地方人民政府教育行政部门或者人力资源社会保障行政部门会同同级公安、民政或者市场监督管理等有关部门责令停止办学、退还所收费用，并对举办者处违法所得一倍以上五倍以下罚款；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":65,"n":"第六十五条","txt":"本法所称的民办学校包括依法举办的其他民办教育机构。"},{"i":66,"n":"第六十六条","txt":"境外的组织和个人在中国境内合作办学的办法，由国务院规定。"},{"i":67,"n":"第六十七条","txt":"本法自2003年9月1日起施行。1997年7月31日国务院颁布的《社会力量办学条例》同时废止。"}],"qixiangfa":[{"i":1,"n":"第一条","txt":"为了发展气象事业，规范气象工作，准确、及时地发布气象预报，防御气象灾害，合理开发利用和保护气候资源，为经济建设、国防建设、社会发展和人民生活提供气象服务，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域从事气象探测、预报、服务和气象灾害防御、气候资源利用、气象科学技术研究等活动，应当遵守本法。"},{"i":3,"n":"第三条","txt":"气象事业是经济建设、国防建设、社会发展和人民生活的基础性公益事业，气象工作应当把公益性气象服务放在首位。"},{"i":4,"n":"第四条","txt":"县、市气象主管机构所属的气象台站应当主要为农业生产服务，及时主动提供保障当地农业生产所需的公益性气象信息服务。"},{"i":5,"n":"第五条","txt":"国务院气象主管机构负责全国的气象工作。地方各级气象主管机构在上级气象主管机构和本级人民政府的领导下，负责本行政区域内的气象工作。"},{"i":6,"n":"第六条","txt":"从事气象业务活动，应当遵守国家制定的气象技术标准、规范和规程。"},{"i":7,"n":"第七条","txt":"国家鼓励和支持气象科学技术研究、气象科学知识普及，培养气象人才，推广先进的气象科学技术，保护气象科技成果，加强国际气象合作与交流，发展气象信息产业，提高气象工作水平。"},{"i":8,"n":"第八条","txt":"外国的组织和个人在中华人民共和国领域和中华人民共和国管辖的其他海域从事气象活动，必须经国务院气象主管机构会同有关部门批准。"},{"i":9,"n":"第九条","txt":"国务院气象主管机构应当组织有关部门编制气象探测设施、气象信息专用传输设施、大型气象专用技术装备等重要气象设施的建设规划，报国务院批准后实施。气象设施建设规划的调整、修改，必须报国务院批准。"},{"i":10,"n":"第十条","txt":"重要气象设施建设项目应当符合重要气象设施建设规划要求，并在项目建议书和可行性研究报告批准前，征求国务院气象主管机构或者省、自治区、直辖市气象主管机构的意见。"},{"i":11,"n":"第十一条","txt":"国家依法保护气象设施，任何组织或者个人不得侵占、损毁或者擅自移动气象设施。"},{"i":12,"n":"第十二条","txt":"未经依法批准，任何组织或者个人不得迁移气象台站；确因实施城市规划或者国家重点工程建设，需要迁移国家基准气候站、基本气象站的，应当报经国务院气象主管机构批准；需要迁移其他气象台站的，应当报经省、自治区、直辖市气象主管机构批准。迁建费用由建设单位承担。"},{"i":13,"n":"第十三条","txt":"气象专用技术装备应当符合国务院气象主管机构规定的技术要求，并经国务院气象主管机构审查合格；未经审查或者审查不合格的，不得在气象业务中使用。"},{"i":14,"n":"第十四条","txt":"气象计量器具应当依照《中华人民共和国计量法》的有关规定，经气象计量检定机构检定。未经检定、检定不合格或者超过检定有效期的气象计量器具，不得使用。"},{"i":15,"n":"第十五条","txt":"各级气象主管机构所属的气象台站，应当按照国务院气象主管机构的规定，进行气象探测并向有关气象主管机构汇交气象探测资料。未经上级气象主管机构批准，不得中止气象探测。"},{"i":16,"n":"第十六条","txt":"国务院其他有关部门和省、自治区、直辖市人民政府其他有关部门所属的气象台站及其他从事气象探测的组织和个人，应当按照国家有关规定向国务院气象主管机构或者省、自治区、直辖市气象主管机构汇交所获得的气象探测资料。"},{"i":17,"n":"第十七条","txt":"在中华人民共和国内水、领海和中华人民共和国管辖的其他海域的海上钻井平台和具有中华人民共和国国籍的在国际航线上飞行的航空器、远洋航行的船舶，应当按照国家有关规定进行气象探测并报告气象探测信息。"},{"i":18,"n":"第十八条","txt":"基本气象探测资料以外的气象探测资料需要保密的，其密级的确定、变更和解密以及使用，依照《中华人民共和国保守国家秘密法》的规定执行。"},{"i":19,"n":"第十九条","txt":"国家依法保护气象探测环境，任何组织和个人都有保护气象探测环境的义务。"},{"i":20,"n":"第二十条","txt":"禁止下列危害气象探测环境的行为："},{"i":21,"n":"第二十一条","txt":"新建、扩建、改建建设工程，应当避免危害气象探测环境；确实无法避免的，建设单位应当事先征得省、自治区、直辖市气象主管机构的同意，并采取相应的措施后，方可建设。"},{"i":22,"n":"第二十二条","txt":"国家对公众气象预报和灾害性天气警报实行统一发布制度。"},{"i":23,"n":"第二十三条","txt":"各级气象主管机构所属的气象台站应当根据需要，发布农业气象预报、城市环境气象预报、火险气象等级预报等专业气象预报，并配合军事气象部门进行国防建设所需的气象服务工作。"},{"i":24,"n":"第二十四条","txt":"各级广播、电视台站和省级人民政府指定的报纸，应当安排专门的时间或者版面，每天播发或者刊登公众气象预报或者灾害性天气警报。"},{"i":25,"n":"第二十五条","txt":"广播、电视、报纸、电信等媒体向社会传播气象预报和灾害性天气警报，必须使用气象主管机构所属的气象台站提供的适时气象信息，并标明发布时间和气象台站的名称。通过传播气象信息获得的收益，应当提取一部分支持气象事业的发展。"},{"i":26,"n":"第二十六条","txt":"信息产业部门应当与气象主管机构密切配合，确保气象通信畅通，准确、及时地传递气象情报、气象预报和灾害性天气警报。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府应当加强气象灾害监测、预警系统建设，组织有关部门编制气象灾害防御规划，并采取有效措施，提高防御气象灾害的能力。有关组织和个人应当服从人民政府的指挥和安排，做好气象灾害防御工作。"},{"i":28,"n":"第二十八条","txt":"各级气象主管机构应当组织对重大灾害性天气的跨地区、跨部门的联合监测、预报工作，及时提出气象灾害防御措施，并对重大气象灾害作出评估，为本级人民政府组织防御气象灾害提供决策依据。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府应当根据防御气象灾害的需要，制定气象灾害防御方案，并根据气象主管机构提供的气象信息，组织实施气象灾害防御方案，避免或者减轻气象灾害。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府应当加强对人工影响天气工作的领导，并根据实际情况，有组织、有计划地开展人工影响天气工作。"},{"i":31,"n":"第三十一条","txt":"各级气象主管机构应当加强对雷电灾害防御工作的组织管理，并会同有关部门指导对可能遭受雷击的建筑物、构筑物和其他设施安装的雷电灾害防护装置的检测工作。"},{"i":32,"n":"第三十二条","txt":"国务院气象主管机构负责全国气候资源的综合调查、区划工作，组织进行气候监测、分析、评价，并对可能引起气候恶化的大气成分进行监测，定期发布全国气候状况公报。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府应当根据本地区气候资源的特点，对气候资源开发利用的方向和保护的重点作出规划。"},{"i":34,"n":"第三十四条","txt":"各级气象主管机构应当组织对城市规划、国家重点建设工程、重大区域性经济开发项目和大型太阳能、风能等气候资源开发利用项目进行气候可行性论证。"},{"i":35,"n":"第三十五条","txt":"违反本法规定，有下列行为之一的，由有关气象主管机构按照权限责令停止违法行为，限期恢复原状或者采取其他补救措施，可以并处五万元以下的罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任："},{"i":36,"n":"第三十六条","txt":"违反本法规定，使用不符合技术要求的气象专用技术装备，造成危害的，由有关气象主管机构按照权限责令改正，给予警告，可以并处五万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本法规定，安装不符合使用要求的雷电灾害防护装置的，由有关气象主管机构责令改正，给予警告。使用不符合使用要求的雷电灾害防护装置给他人造成损失的，依法承担赔偿责任。"},{"i":38,"n":"第三十八条","txt":"违反本法规定，有下列行为之一的，由有关气象主管机构按照权限责令改正，给予警告，可以并处五万元以下的罚款："},{"i":39,"n":"第三十九条","txt":"违反本法规定，不具备省、自治区、直辖市气象主管机构规定的条件实施人工影响天气作业的，或者实施人工影响天气作业使用不符合国务院气象主管机构要求的技术标准的作业设备的，由有关气象主管机构按照权限责令改正，给予警告，可以并处十万元以下的罚款；给他人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"各级气象主管机构及其所属气象台站的工作人员由于玩忽职守，导致重大漏报、错报公众气象预报、灾害性天气警报，以及丢失或者毁坏原始气象探测资料、伪造气象资料等事故的，依法给予行政处分；致使国家利益和人民生命财产遭受重大损失，构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本法中下列用语的含义是："},{"i":42,"n":"第四十二条","txt":"气象台站和其他开展气象有偿服务的单位，从事气象有偿服务的范围、项目、收费等具体管理办法，由国务院依据本法规定。"},{"i":43,"n":"第四十三条","txt":"中国人民解放军气象工作的管理办法，由中央军事委员会制定。"},{"i":44,"n":"第四十四条","txt":"中华人民共和国缔结或者参加的有关气象活动的国际条约与本法有不同规定的，适用该国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":45,"n":"第四十五条","txt":"本法自2000年1月1日起施行。1994年8月18日国务院发布的《中华人民共和国气象条例》同时废止。"}],"zhianguanlichufafa":[{"i":1,"n":"第一条","txt":"为了维护社会治安秩序，保障公共安全，保护公民、法人和其他组织的合法权益，规范和保障公安机关及其人民警察依法履行治安管理职责，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"治安管理工作坚持中国共产党的领导，坚持综合治理。"},{"i":3,"n":"第三条","txt":"扰乱公共秩序，妨害公共安全，侵犯人身权利、财产权利，妨害社会管理，具有社会危害性，依照《中华人民共和国刑法》的规定构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由公安机关依照本法给予治安管理处罚。"},{"i":4,"n":"第四条","txt":"治安管理处罚的程序，适用本法的规定；本法没有规定的，适用《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》的有关规定。"},{"i":5,"n":"第五条","txt":"在中华人民共和国领域内发生的违反治安管理行为，除法律有特别规定的外，适用本法。"},{"i":6,"n":"第六条","txt":"治安管理处罚必须以事实为依据，与违反治安管理的事实、性质、情节以及社会危害程度相当。"},{"i":7,"n":"第七条","txt":"国务院公安部门负责全国的治安管理工作。县级以上地方各级人民政府公安机关负责本行政区域内的治安管理工作。"},{"i":8,"n":"第八条","txt":"违反治安管理行为对他人造成损害的，除依照本法给予治安管理处罚外，行为人或者其监护人还应当依法承担民事责任。"},{"i":9,"n":"第九条","txt":"对于因民间纠纷引起的打架斗殴或者损毁他人财物等违反治安管理行为，情节较轻的，公安机关可以调解处理。"},{"i":10,"n":"第十条","txt":"治安管理处罚的种类分为："},{"i":11,"n":"第十一条","txt":"办理治安案件所查获的毒品、淫秽物品等违禁品，赌具、赌资，吸食、注射毒品的用具以及直接用于实施违反治安管理行为的本人所有的工具，应当收缴，按照规定处理。"},{"i":12,"n":"第十二条","txt":"已满十四周岁不满十八周岁的人违反治安管理的，从轻或者减轻处罚；不满十四周岁的人违反治安管理的，不予处罚，但是应当责令其监护人严加管教。"},{"i":13,"n":"第十三条","txt":"精神病人、智力残疾人在不能辨认或者不能控制自己行为的时候违反治安管理的，不予处罚，但是应当责令其监护人加强看护管理和治疗。间歇性的精神病人在精神正常的时候违反治安管理的，应当给予处罚。尚未完全丧失辨认或者控制自己行为能力的精神病人、智力残疾人违反治安管理的，应当给予处罚，但是可以从轻或者减轻处罚。"},{"i":14,"n":"第十四条","txt":"盲人或者又聋又哑的人违反治安管理的，可以从轻、减轻或者不予处罚。"},{"i":15,"n":"第十五条","txt":"醉酒的人违反治安管理的，应当给予处罚。"},{"i":16,"n":"第十六条","txt":"有两种以上违反治安管理行为的，分别决定，合并执行处罚。行政拘留处罚合并执行的，最长不超过二十日。"},{"i":17,"n":"第十七条","txt":"共同违反治安管理的，根据行为人在违反治安管理行为中所起的作用，分别处罚。"},{"i":18,"n":"第十八条","txt":"单位违反治安管理的，对其直接负责的主管人员和其他直接责任人员依照本法的规定处罚。其他法律、行政法规对同一行为规定给予单位处罚的，依照其规定处罚。"},{"i":19,"n":"第十九条","txt":"为了免受正在进行的不法侵害而采取的制止行为，造成损害的，不属于违反治安管理行为，不受处罚；制止行为明显超过必要限度，造成较大损害的，依法给予处罚，但是应当减轻处罚；情节较轻的，不予处罚。"},{"i":20,"n":"第二十条","txt":"违反治安管理有下列情形之一的，从轻、减轻或者不予处罚："},{"i":21,"n":"第二十一条","txt":"违反治安管理行为人自愿向公安机关如实陈述自己的违法行为，承认违法事实，愿意接受处罚的，可以依法从宽处理。"},{"i":22,"n":"第二十二条","txt":"违反治安管理有下列情形之一的，从重处罚："},{"i":23,"n":"第二十三条","txt":"违反治安管理行为人有下列情形之一，依照本法应当给予行政拘留处罚的，不执行行政拘留处罚："},{"i":24,"n":"第二十四条","txt":"对依照本法第十二条规定不予处罚或者依照本法第二十三条规定不执行行政拘留处罚的未成年人，公安机关依照《中华人民共和国预防未成年人犯罪法》的规定采取相应矫治教育等措施。"},{"i":25,"n":"第二十五条","txt":"违反治安管理行为在六个月以内没有被公安机关发现的，不再处罚。"},{"i":26,"n":"第二十六条","txt":"有下列行为之一的，处警告或者五百元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款："},{"i":27,"n":"第二十七条","txt":"在法律、行政法规规定的国家考试中，有下列行为之一，扰乱考试秩序的，处违法所得一倍以上五倍以下罚款，没有违法所得或者违法所得不足一千元的，处一千元以上三千元以下罚款；情节较重的，处五日以上十五日以下拘留："},{"i":28,"n":"第二十八条","txt":"有下列行为之一，扰乱体育、文化等大型群众性活动秩序的，处警告或者五百元以下罚款；情节严重的，处五日以上十日以下拘留，可以并处一千元以下罚款："},{"i":29,"n":"第二十九条","txt":"有下列行为之一的，处五日以上十日以下拘留，可以并处一千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款："},{"i":30,"n":"第三十条","txt":"有下列行为之一的，处五日以上十日以下拘留或者一千元以下罚款；情节较重的，处十日以上十五日以下拘留，可以并处二千元以下罚款："},{"i":31,"n":"第三十一条","txt":"有下列行为之一的，处十日以上十五日以下拘留，可以并处二千元以下罚款；情节较轻的，处五日以上十日以下拘留，可以并处一千元以下罚款："},{"i":32,"n":"第三十二条","txt":"违反国家规定，有下列行为之一的，处五日以上十日以下拘留；情节严重的，处十日以上十五日以下拘留："},{"i":33,"n":"第三十三条","txt":"有下列行为之一，造成危害的，处五日以下拘留；情节较重的，处五日以上十五日以下拘留："},{"i":34,"n":"第三十四条","txt":"组织、领导传销活动的，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。"},{"i":35,"n":"第三十五条","txt":"有下列行为之一的，处五日以上十日以下拘留或者一千元以上三千元以下罚款；情节较重的，处十日以上十五日以下拘留，可以并处五千元以下罚款："},{"i":36,"n":"第三十六条","txt":"违反国家规定，制造、买卖、储存、运输、邮寄、携带、使用、提供、处置爆炸性、毒害性、放射性、腐蚀性物质或者传染病病原体等危险物质的，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。"},{"i":37,"n":"第三十七条","txt":"爆炸性、毒害性、放射性、腐蚀性物质或者传染病病原体等危险物质被盗、被抢或者丢失，未按规定报告的，处五日以下拘留；故意隐瞒不报的，处五日以上十日以下拘留。"},{"i":38,"n":"第三十八条","txt":"非法携带枪支、弹药或者弩、匕首等国家规定的管制器具的，处五日以下拘留，可以并处一千元以下罚款；情节较轻的，处警告或者五百元以下罚款。"},{"i":39,"n":"第三十九条","txt":"有下列行为之一的，处十日以上十五日以下拘留；情节较轻的，处五日以下拘留："},{"i":40,"n":"第四十条","txt":"盗窃、损坏、擅自移动使用中的航空设施，或者强行进入航空器驾驶舱的，处十日以上十五日以下拘留。"},{"i":41,"n":"第四十一条","txt":"有下列行为之一的，处五日以上十日以下拘留，可以并处一千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款："},{"i":42,"n":"第四十二条","txt":"擅自进入铁路、城市轨道交通防护网或者火车、城市轨道交通列车来临时在铁路、城市轨道交通线路上行走坐卧，抢越铁路、城市轨道，影响行车安全的，处警告或者五百元以下罚款。"},{"i":43,"n":"第四十三条","txt":"有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节严重的，处十日以上十五日以下拘留，可以并处一千元以下罚款："},{"i":44,"n":"第四十四条","txt":"举办体育、文化等大型群众性活动，违反有关规定，有发生安全事故危险，经公安机关责令改正而拒不改正或者无法改正的，责令停止活动，立即疏散；对其直接负责的主管人员和其他直接责任人员处五日以上十日以下拘留，并处一千元以上三千元以下罚款；情节较重的，处十日以上十五日以下拘留，并处三千元以上五千元以下罚款，可以同时责令六个月至一年以内不得举办大型群众性活动。"},{"i":45,"n":"第四十五条","txt":"旅馆、饭店、影剧院、娱乐场、体育场馆、展览馆或者其他供社会公众活动的场所违反安全规定，致使该场所有发生安全事故危险，经公安机关责令改正而拒不改正的，对其直接负责的主管人员和其他直接责任人员处五日以下拘留；情节较重的，处五日以上十日以下拘留。"},{"i":46,"n":"第四十六条","txt":"违反有关法律法规关于飞行空域管理规定，飞行民用无人驾驶航空器、航空运动器材，或者升放无人驾驶自由气球、系留气球等升空物体，情节较重的，处五日以上十日以下拘留。"},{"i":47,"n":"第四十七条","txt":"有下列行为之一的，处十日以上十五日以下拘留，并处一千元以上二千元以下罚款；情节较轻的，处五日以上十日以下拘留，并处一千元以下罚款："},{"i":48,"n":"第四十八条","txt":"组织、胁迫未成年人在不适宜未成年人活动的经营场所从事陪酒、陪唱等有偿陪侍活动的，处十日以上十五日以下拘留，并处五千元以下罚款；情节较轻的，处五日以下拘留或者五千元以下罚款。"},{"i":49,"n":"第四十九条","txt":"胁迫、诱骗或者利用他人乞讨的，处十日以上十五日以下拘留，可以并处二千元以下罚款。"},{"i":50,"n":"第五十条","txt":"有下列行为之一的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款："},{"i":51,"n":"第五十一条","txt":"殴打他人的，或者故意伤害他人身体的，处五日以上十日以下拘留，并处五百元以上一千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款。"},{"i":52,"n":"第五十二条","txt":"猥亵他人的，处五日以上十日以下拘留；猥亵精神病人、智力残疾人、不满十四周岁的人或者有其他严重情节的，处十日以上十五日以下拘留。"},{"i":53,"n":"第五十三条","txt":"有下列行为之一的，处五日以下拘留或者警告；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款："},{"i":54,"n":"第五十四条","txt":"强买强卖商品，强迫他人提供服务或者强迫他人接受服务的，处五日以上十日以下拘留，并处三千元以上五千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款。"},{"i":55,"n":"第五十五条","txt":"煽动民族仇恨、民族歧视，或者在出版物、信息网络中刊载民族歧视、侮辱内容的，处十日以上十五日以下拘留，可以并处三千元以下罚款；情节较轻的，处五日以下拘留或者三千元以下罚款。"},{"i":56,"n":"第五十六条","txt":"违反国家有关规定，向他人出售或者提供个人信息的，处十日以上十五日以下拘留；情节较轻的，处五日以下拘留。"},{"i":57,"n":"第五十七条","txt":"冒领、隐匿、毁弃、倒卖、私自开拆或者非法检查他人邮件、快件的，处警告或者一千元以下罚款；情节较重的，处五日以上十日以下拘留。"},{"i":58,"n":"第五十八条","txt":"盗窃、诈骗、哄抢、抢夺或者敲诈勒索的，处五日以上十日以下拘留或者二千元以下罚款；情节较重的，处十日以上十五日以下拘留，可以并处三千元以下罚款。"},{"i":59,"n":"第五十九条","txt":"故意损毁公私财物的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处三千元以下罚款。"},{"i":60,"n":"第六十条","txt":"以殴打、侮辱、恐吓等方式实施学生欺凌，违反治安管理的，公安机关应当依照本法、《中华人民共和国预防未成年人犯罪法》的规定，给予治安管理处罚、采取相应矫治教育等措施。"},{"i":61,"n":"第六十一条","txt":"有下列行为之一的，处警告或者五百元以下罚款；情节严重的，处五日以上十日以下拘留，可以并处一千元以下罚款："},{"i":62,"n":"第六十二条","txt":"冒充国家机关工作人员招摇撞骗的，处十日以上十五日以下拘留，可以并处一千元以下罚款；情节较轻的，处五日以上十日以下拘留。"},{"i":63,"n":"第六十三条","txt":"有下列行为之一的，处十日以上十五日以下拘留，可以并处五千元以下罚款；情节较轻的，处五日以上十日以下拘留，可以并处三千元以下罚款："},{"i":64,"n":"第六十四条","txt":"船舶擅自进入、停靠国家禁止、限制进入的水域或者岛屿的，对船舶负责人及有关责任人员处一千元以上二千元以下罚款；情节严重的，处五日以下拘留，可以并处二千元以下罚款。"},{"i":65,"n":"第六十五条","txt":"有下列行为之一的，处十日以上十五日以下拘留，可以并处五千元以下罚款；情节较轻的，处五日以上十日以下拘留或者一千元以上三千元以下罚款："},{"i":66,"n":"第六十六条","txt":"煽动、策划非法集会、游行、示威，不听劝阻的，处十日以上十五日以下拘留。"},{"i":67,"n":"第六十七条","txt":"从事旅馆业经营活动不按规定登记住宿人员姓名、有效身份证件种类和号码等信息的，或者为身份不明、拒绝登记身份信息的人提供住宿服务的，对其直接负责的主管人员和其他直接责任人员处五百元以上一千元以下罚款；情节较轻的，处警告或者五百元以下罚款。"},{"i":68,"n":"第六十八条","txt":"房屋出租人将房屋出租给身份不明、拒绝登记身份信息的人的，或者不按规定登记承租人姓名、有效身份证件种类和号码等信息的，处五百元以上一千元以下罚款；情节较轻的，处警告或者五百元以下罚款。"},{"i":69,"n":"第六十九条","txt":"娱乐场所和公章刻制、机动车修理、报废机动车回收行业经营者违反法律法规关于要求登记信息的规定，不登记信息的，处警告；拒不改正或者造成后果的，对其直接负责的主管人员和其他直接责任人员处五日以下拘留或者三千元以下罚款。"},{"i":70,"n":"第七十条","txt":"非法安装、使用、提供窃听、窃照专用器材的，处五日以下拘留或者一千元以上三千元以下罚款；情节较重的，处五日以上十日以下拘留，并处三千元以上五千元以下罚款。"},{"i":71,"n":"第七十一条","txt":"有下列行为之一的，处一千元以上三千元以下罚款；情节严重的，处五日以上十日以下拘留，并处一千元以上三千元以下罚款："},{"i":72,"n":"第七十二条","txt":"有下列行为之一的，处五日以上十日以下拘留，可以并处一千元以下罚款；情节较轻的，处警告或者一千元以下罚款："},{"i":73,"n":"第七十三条","txt":"有下列行为之一的，处警告或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款："},{"i":74,"n":"第七十四条","txt":"依法被关押的违法行为人脱逃的，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。"},{"i":75,"n":"第七十五条","txt":"有下列行为之一的，处警告或者五百元以下罚款；情节较重的，处五日以上十日以下拘留，并处五百元以上一千元以下罚款："},{"i":76,"n":"第七十六条","txt":"有下列行为之一的，处一千元以上二千元以下罚款；情节严重的，处十日以上十五日以下拘留，可以并处二千元以下罚款："},{"i":77,"n":"第七十七条","txt":"有下列行为之一的，处五日以上十日以下拘留；情节严重的，处十日以上十五日以下拘留，可以并处二千元以下罚款："},{"i":78,"n":"第七十八条","txt":"卖淫、嫖娼的，处十日以上十五日以下拘留，可以并处五千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款。"},{"i":79,"n":"第七十九条","txt":"引诱、容留、介绍他人卖淫的，处十日以上十五日以下拘留，可以并处五千元以下罚款；情节较轻的，处五日以下拘留或者一千元以上二千元以下罚款。"},{"i":80,"n":"第八十条","txt":"制作、运输、复制、出售、出租淫秽的书刊、图片、影片、音像制品等淫秽物品或者利用信息网络、电话以及其他通讯工具传播淫秽信息的，处十日以上十五日以下拘留，可以并处五千元以下罚款；情节较轻的，处五日以下拘留或者一千元以上三千元以下罚款。"},{"i":81,"n":"第八十一条","txt":"有下列行为之一的，处十日以上十五日以下拘留，并处一千元以上二千元以下罚款："},{"i":82,"n":"第八十二条","txt":"以营利为目的，为赌博提供条件的，或者参与赌博赌资较大的，处五日以下拘留或者一千元以下罚款；情节严重的，处十日以上十五日以下拘留，并处一千元以上五千元以下罚款。"},{"i":83,"n":"第八十三条","txt":"有下列行为之一的，处十日以上十五日以下拘留，可以并处五千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款："},{"i":84,"n":"第八十四条","txt":"有下列行为之一的，处十日以上十五日以下拘留，可以并处三千元以下罚款；情节较轻的，处五日以下拘留或者一千元以下罚款："},{"i":85,"n":"第八十五条","txt":"引诱、教唆、欺骗或者强迫他人吸食、注射毒品的，处十日以上十五日以下拘留，并处一千元以上五千元以下罚款。"},{"i":86,"n":"第八十六条","txt":"违反国家规定，非法生产、经营、购买、运输用于制造毒品的原料、配剂的，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。"},{"i":87,"n":"第八十七条","txt":"旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，在公安机关查处吸毒、赌博、卖淫、嫖娼活动时，为违法犯罪行为人通风报信的，或者以其他方式为上述活动提供条件的，处十日以上十五日以下拘留；情节较轻的，处五日以下拘留或者一千元以上二千元以下罚款。"},{"i":88,"n":"第八十八条","txt":"违反关于社会生活噪声污染防治的法律法规规定，产生社会生活噪声，经基层群众性自治组织、业主委员会、物业服务人、有关部门依法劝阻、调解和处理未能制止，继续干扰他人正常生活、工作和学习的，处五日以下拘留或者一千元以下罚款；情节严重的，处五日以上十日以下拘留，可以并处一千元以下罚款。"},{"i":89,"n":"第八十九条","txt":"饲养动物，干扰他人正常生活的，处警告；警告后不改正的，或者放任动物恐吓他人的，处一千元以下罚款。"},{"i":90,"n":"第九十条","txt":"公安机关对报案、控告、举报或者违反治安管理行为人主动投案，以及其他国家机关移送的违反治安管理案件，应当立即立案并进行调查；认为不属于违反治安管理行为的，应当告知报案人、控告人、举报人、投案人，并说明理由。"},{"i":91,"n":"第九十一条","txt":"公安机关及其人民警察对治安案件的调查，应当依法进行。严禁刑讯逼供或者采用威胁、引诱、欺骗等非法手段收集证据。"},{"i":92,"n":"第九十二条","txt":"公安机关办理治安案件，有权向有关单位和个人收集、调取证据。有关单位和个人应当如实提供证据。"},{"i":93,"n":"第九十三条","txt":"在办理刑事案件过程中以及其他执法办案机关在移送案件前依法收集的物证、书证、视听资料、电子数据等证据材料，可以作为治安案件的证据使用。"},{"i":94,"n":"第九十四条","txt":"公安机关及其人民警察在办理治安案件时，对涉及的国家秘密、商业秘密、个人隐私或者个人信息，应当予以保密。"},{"i":95,"n":"第九十五条","txt":"人民警察在办理治安案件过程中，遇有下列情形之一的，应当回避；违反治安管理行为人、被侵害人或者其法定代理人也有权要求他们回避："},{"i":96,"n":"第九十六条","txt":"需要传唤违反治安管理行为人接受调查的，经公安机关办案部门负责人批准，使用传唤证传唤。对现场发现的违反治安管理行为人，人民警察经出示人民警察证，可以口头传唤，但应当在询问笔录中注明。"},{"i":97,"n":"第九十七条","txt":"对违反治安管理行为人，公安机关传唤后应当及时询问查证，询问查证的时间不得超过八小时；涉案人数众多、违反治安管理行为人身份不明的，询问查证的时间不得超过十二小时；情况复杂，依照本法规定可能适用行政拘留处罚的，询问查证的时间不得超过二十四小时。在执法办案场所询问违反治安管理行为人，应当全程同步录音录像。"},{"i":98,"n":"第九十八条","txt":"询问笔录应当交被询问人核对；对没有阅读能力的，应当向其宣读。记载有遗漏或者差错的，被询问人可以提出补充或者更正。被询问人确认笔录无误后，应当签名、盖章或者按指印，询问的人民警察也应当在笔录上签名。"},{"i":99,"n":"第九十九条","txt":"人民警察询问被侵害人或者其他证人，可以在现场进行，也可以到其所在单位、住处或者其提出的地点进行；必要时，也可以通知其到公安机关提供证言。"},{"i":100,"n":"第一百条","txt":"违反治安管理行为人、被侵害人或者其他证人在异地的，公安机关可以委托异地公安机关代为询问，也可以通过公安机关的视频系统远程询问。"},{"i":101,"n":"第一百零一条","txt":"询问聋哑的违反治安管理行为人、被侵害人或者其他证人，应当有通晓手语等交流方式的人提供帮助，并在笔录上注明。"},{"i":102,"n":"第一百零二条","txt":"为了查明案件事实，确定违反治安管理行为人、被侵害人的某些特征、伤害情况或者生理状态，需要对其人身进行检查，提取或者采集肖像、指纹信息和血液、尿液等生物样本的，经公安机关办案部门负责人批准后进行。对已经提取、采集的信息或者样本，不得重复提取、采集。提取或者采集被侵害人的信息或者样本，应当征得被侵害人或者其监护人同意。"},{"i":103,"n":"第一百零三条","txt":"公安机关对与违反治安管理行为有关的场所或者违反治安管理行为人的人身、物品可以进行检查。检查时，人民警察不得少于二人，并应当出示人民警察证。"},{"i":104,"n":"第一百零四条","txt":"检查的情况应当制作检查笔录，由检查人、被检查人和见证人签名、盖章或者按指印；被检查人不在场或者被检查人、见证人拒绝签名的，人民警察应当在笔录上注明。"},{"i":105,"n":"第一百零五条","txt":"公安机关办理治安案件，对与案件有关的需要作为证据的物品，可以扣押；对被侵害人或者善意第三人合法占有的财产，不得扣押，应当予以登记，但是对其中与案件有关的必须鉴定的物品，可以扣押，鉴定后应当立即解除。对与案件无关的物品，不得扣押。"},{"i":106,"n":"第一百零六条","txt":"为了查明案情，需要解决案件中有争议的专门性问题的，应当指派或者聘请具有专门知识的人员进行鉴定；鉴定人鉴定后，应当写出鉴定意见，并且签名。"},{"i":107,"n":"第一百零七条","txt":"为了查明案情，人民警察可以让违反治安管理行为人、被侵害人和其他证人对与违反治安管理行为有关的场所、物品进行辨认，也可以让被侵害人、其他证人对违反治安管理行为人进行辨认，或者让违反治安管理行为人对其他违反治安管理行为人进行辨认。"},{"i":108,"n":"第一百零八条","txt":"公安机关进行询问、辨认、勘验，实施行政强制措施等调查取证工作时，人民警察不得少于二人。"},{"i":109,"n":"第一百零九条","txt":"治安管理处罚由县级以上地方人民政府公安机关决定；其中警告、一千元以下的罚款，可以由公安派出所决定。"},{"i":110,"n":"第一百一十条","txt":"对决定给予行政拘留处罚的人，在处罚前已经采取强制措施限制人身自由的时间，应当折抵。限制人身自由一日，折抵行政拘留一日。"},{"i":111,"n":"第一百一十一条","txt":"公安机关查处治安案件，对没有本人陈述，但其他证据能够证明案件事实的，可以作出治安管理处罚决定。但是，只有本人陈述，没有其他证据证明的，不能作出治安管理处罚决定。"},{"i":112,"n":"第一百一十二条","txt":"公安机关作出治安管理处罚决定前，应当告知违反治安管理行为人拟作出治安管理处罚的内容及事实、理由、依据，并告知违反治安管理行为人依法享有的权利。"},{"i":113,"n":"第一百一十三条","txt":"治安案件调查结束后，公安机关应当根据不同情况，分别作出以下处理："},{"i":114,"n":"第一百一十四条","txt":"有下列情形之一的，在公安机关作出治安管理处罚决定之前，应当由从事治安管理处罚决定法制审核的人员进行法制审核；未经法制审核或者审核未通过的，不得作出决定："},{"i":115,"n":"第一百一十五条","txt":"公安机关作出治安管理处罚决定的，应当制作治安管理处罚决定书。决定书应当载明下列内容："},{"i":116,"n":"第一百一十六条","txt":"公安机关应当向被处罚人宣告治安管理处罚决定书，并当场交付被处罚人；无法当场向被处罚人宣告的，应当在二日以内送达被处罚人。决定给予行政拘留处罚的，应当及时通知被处罚人的家属。"},{"i":117,"n":"第一百一十七条","txt":"公安机关作出吊销许可证件、处四千元以上罚款的治安管理处罚决定或者采取责令停业整顿措施前，应当告知违反治安管理行为人有权要求举行听证；违反治安管理行为人要求听证的，公安机关应当及时依法举行听证。"},{"i":118,"n":"第一百一十八条","txt":"公安机关办理治安案件的期限，自立案之日起不得超过三十日；案情重大、复杂的，经上一级公安机关批准，可以延长三十日。期限延长以二次为限。公安派出所办理的案件需要延长期限的，由所属公安机关批准。"},{"i":119,"n":"第一百一十九条","txt":"违反治安管理行为事实清楚，证据确凿，处警告或者五百元以下罚款的，可以当场作出治安管理处罚决定。"},{"i":120,"n":"第一百二十条","txt":"当场作出治安管理处罚决定的，人民警察应当向违反治安管理行为人出示人民警察证，并填写处罚决定书。处罚决定书应当当场交付被处罚人；有被侵害人的，并应当将决定书送达被侵害人。"},{"i":121,"n":"第一百二十一条","txt":"被处罚人、被侵害人对公安机关依照本法规定作出的治安管理处罚决定，作出的收缴、追缴决定，或者采取的有关限制性、禁止性措施等不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":122,"n":"第一百二十二条","txt":"对被决定给予行政拘留处罚的人，由作出决定的公安机关送拘留所执行；执行期满，拘留所应当按时解除拘留，发给解除拘留证明书。"},{"i":123,"n":"第一百二十三条","txt":"受到罚款处罚的人应当自收到处罚决定书之日起十五日以内，到指定的银行或者通过电子支付系统缴纳罚款。但是，有下列情形之一的，人民警察可以当场收缴罚款："},{"i":124,"n":"第一百二十四条","txt":"人民警察当场收缴的罚款，应当自收缴罚款之日起二日以内，交至所属的公安机关；在水上、旅客列车上当场收缴的罚款，应当自抵岸或者到站之日起二日以内，交至所属的公安机关；公安机关应当自收到罚款之日起二日以内将罚款缴付指定的银行。"},{"i":125,"n":"第一百二十五条","txt":"人民警察当场收缴罚款的，应当向被处罚人出具省级以上人民政府财政部门统一制发的专用票据；不出具统一制发的专用票据的，被处罚人有权拒绝缴纳罚款。"},{"i":126,"n":"第一百二十六条","txt":"被处罚人不服行政拘留处罚决定，申请行政复议、提起行政诉讼的，遇有参加升学考试、子女出生或者近亲属病危、死亡等情形的，可以向公安机关提出暂缓执行行政拘留的申请。公安机关认为暂缓执行行政拘留不致发生社会危险的，由被处罚人或者其近亲属提出符合本法第一百二十七条规定条件的担保人，或者按每日行政拘留二百元的标准交纳保证金，行政拘留的处罚决定暂缓执行。"},{"i":127,"n":"第一百二十七条","txt":"担保人应当符合下列条件："},{"i":128,"n":"第一百二十八条","txt":"担保人应当保证被担保人不逃避行政拘留处罚的执行。"},{"i":129,"n":"第一百二十九条","txt":"被决定给予行政拘留处罚的人交纳保证金，暂缓行政拘留或者出所后，逃避行政拘留处罚的执行的，保证金予以没收并上缴国库，已经作出的行政拘留决定仍应执行。"},{"i":130,"n":"第一百三十条","txt":"行政拘留的处罚决定被撤销，行政拘留处罚开始执行，或者出所后继续执行的，公安机关收取的保证金应当及时退还交纳人。"},{"i":131,"n":"第一百三十一条","txt":"公安机关及其人民警察应当依法、公正、严格、高效办理治安案件，文明执法，不得徇私舞弊、玩忽职守、滥用职权。"},{"i":132,"n":"第一百三十二条","txt":"公安机关及其人民警察办理治安案件，禁止对违反治安管理行为人打骂、虐待或者侮辱。"},{"i":133,"n":"第一百三十三条","txt":"公安机关及其人民警察办理治安案件，应当自觉接受社会和公民的监督。"},{"i":134,"n":"第一百三十四条","txt":"公安机关作出治安管理处罚决定，发现被处罚人是公职人员，依照《中华人民共和国公职人员政务处分法》的规定需要给予政务处分的，应当依照有关规定及时通报监察机关等有关单位。"},{"i":135,"n":"第一百三十五条","txt":"公安机关依法实施罚款处罚，应当依照有关法律、行政法规的规定，实行罚款决定与罚款收缴分离；收缴的罚款应当全部上缴国库，不得返还、变相返还，不得与经费保障挂钩。"},{"i":136,"n":"第一百三十六条","txt":"违反治安管理的记录应当予以封存，不得向任何单位和个人提供或者公开，但有关国家机关为办案需要或者有关单位根据国家规定进行查询的除外。依法进行查询的单位，应当对被封存的违法记录的情况予以保密。"},{"i":137,"n":"第一百三十七条","txt":"公安机关应当履行同步录音录像运行安全管理职责，完善技术措施，定期维护设施设备，保障录音录像设备运行连续、稳定、安全。"},{"i":138,"n":"第一百三十八条","txt":"公安机关及其人民警察不得将在办理治安案件过程中获得的个人信息，依法提取、采集的相关信息、样本用于与治安管理、查处犯罪无关的用途，不得出售、提供给其他单位或者个人。"},{"i":139,"n":"第一百三十九条","txt":"人民警察办理治安案件，有下列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任："},{"i":140,"n":"第一百四十条","txt":"公安机关及其人民警察违法行使职权，侵犯公民、法人和其他组织合法权益的，应当赔礼道歉；造成损害的，应当依法承担赔偿责任。"},{"i":141,"n":"第一百四十一条","txt":"其他法律中规定由公安机关给予行政拘留处罚的，其处罚程序适用本法规定。"},{"i":142,"n":"第一百四十二条","txt":"海警机构履行海上治安管理职责，行使本法规定的公安机关的职权，但是法律另有规定的除外。"},{"i":143,"n":"第一百四十三条","txt":"本法所称以上、以下、以内，包括本数。"},{"i":144,"n":"第一百四十四条","txt":"本法自2026年1月1日起施行。"}],"cehuifa":[{"i":1,"n":"第一条","txt":"为了加强测绘管理，促进测绘事业发展，保障测绘事业为经济建设、国防建设、社会发展和生态保护服务，维护国家地理信息安全，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域从事测绘活动，应当遵守本法。"},{"i":3,"n":"第三条","txt":"测绘事业是经济建设、国防建设、社会发展的基础性事业。各级人民政府应当加强对测绘工作的领导。"},{"i":4,"n":"第四条","txt":"国务院测绘地理信息主管部门负责全国测绘工作的统一监督管理。国务院其他有关部门按照国务院规定的职责分工，负责本部门有关的测绘工作。"},{"i":5,"n":"第五条","txt":"从事测绘活动，应当使用国家规定的测绘基准和测绘系统，执行国家规定的测绘技术规范和标准。"},{"i":6,"n":"第六条","txt":"国家鼓励测绘科学技术的创新和进步，采用先进的技术和设备，提高测绘水平，推动军民融合，促进测绘成果的应用。国家加强测绘科学技术的国际交流与合作。"},{"i":7,"n":"第七条","txt":"各级人民政府和有关部门应当加强对国家版图意识的宣传教育，增强公民的国家版图意识。新闻媒体应当开展国家版图意识的宣传。教育行政部门、学校应当将国家版图意识教育纳入中小学教学内容，加强爱国主义教育。"},{"i":8,"n":"第八条","txt":"外国的组织或者个人在中华人民共和国领域和中华人民共和国管辖的其他海域从事测绘活动，应当经国务院测绘地理信息主管部门会同军队测绘部门批准，并遵守中华人民共和国有关法律、行政法规的规定。"},{"i":9,"n":"第九条","txt":"国家设立和采用全国统一的大地基准、高程基准、深度基准和重力基准，其数据由国务院测绘地理信息主管部门审核，并与国务院其他有关部门、军队测绘部门会商后，报国务院批准。"},{"i":10,"n":"第十条","txt":"国家建立全国统一的大地坐标系统、平面坐标系统、高程系统、地心坐标系统和重力测量系统，确定国家大地测量等级和精度以及国家基本比例尺地图的系列和基本精度。具体规范和要求由国务院测绘地理信息主管部门会同国务院其他有关部门、军队测绘部门制定。"},{"i":11,"n":"第十一条","txt":"因建设、城市规划和科学研究的需要，国家重大工程项目和国务院确定的大城市确需建立相对独立的平面坐标系统的，由国务院测绘地理信息主管部门批准；其他确需建立相对独立的平面坐标系统的，由省、自治区、直辖市人民政府测绘地理信息主管部门批准。"},{"i":12,"n":"第十二条","txt":"国务院测绘地理信息主管部门和省、自治区、直辖市人民政府测绘地理信息主管部门应当会同本级人民政府其他有关部门，按照统筹建设、资源共享的原则，建立统一的卫星导航定位基准服务系统，提供导航定位基准信息公共服务。"},{"i":13,"n":"第十三条","txt":"建设卫星导航定位基准站的，建设单位应当按照国家有关规定报国务院测绘地理信息主管部门或者省、自治区、直辖市人民政府测绘地理信息主管部门备案。国务院测绘地理信息主管部门应当汇总全国卫星导航定位基准站建设备案情况，并定期向军队测绘部门通报。"},{"i":14,"n":"第十四条","txt":"卫星导航定位基准站的建设和运行维护应当符合国家标准和要求，不得危害国家安全。"},{"i":15,"n":"第十五条","txt":"基础测绘是公益性事业。国家对基础测绘实行分级管理。"},{"i":16,"n":"第十六条","txt":"国务院测绘地理信息主管部门会同国务院其他有关部门、军队测绘部门组织编制全国基础测绘规划，报国务院批准后组织实施。"},{"i":17,"n":"第十七条","txt":"军队测绘部门负责编制军事测绘规划，按照国务院、中央军事委员会规定的职责分工负责编制海洋基础测绘规划，并组织实施。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府应当将基础测绘纳入本级国民经济和社会发展年度计划，将基础测绘工作所需经费列入本级政府预算。"},{"i":19,"n":"第十九条","txt":"基础测绘成果应当定期更新，经济建设、国防建设、社会发展和生态保护急需的基础测绘成果应当及时更新。"},{"i":20,"n":"第二十条","txt":"中华人民共和国国界线的测绘，按照中华人民共和国与相邻国家缔结的边界条约或者协定执行，由外交部组织实施。中华人民共和国地图的国界线标准样图，由外交部和国务院测绘地理信息主管部门拟定，报国务院批准后公布。"},{"i":21,"n":"第二十一条","txt":"行政区域界线的测绘，按照国务院有关规定执行。省、自治区、直辖市和自治州、县、自治县、市行政区域界线的标准画法图，由国务院民政部门和国务院测绘地理信息主管部门拟定，报国务院批准后公布。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府测绘地理信息主管部门应当会同本级人民政府不动产登记主管部门，加强对不动产测绘的管理。"},{"i":23,"n":"第二十三条","txt":"城乡建设领域的工程测量活动，与房屋产权、产籍相关的房屋面积的测量，应当执行由国务院住房城乡建设主管部门、国务院测绘地理信息主管部门组织编制的测量技术规范。"},{"i":24,"n":"第二十四条","txt":"建立地理信息系统，应当采用符合国家标准的基础地理信息数据。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府测绘地理信息主管部门应当根据突发事件应对工作需要，及时提供地图、基础地理信息数据等测绘成果，做好遥感监测、导航定位等应急测绘保障工作。"},{"i":26,"n":"第二十六条","txt":"县级以上人民政府测绘地理信息主管部门应当会同本级人民政府其他有关部门依法开展地理国情监测，并按照国家有关规定严格管理、规范使用地理国情监测成果。"},{"i":27,"n":"第二十七条","txt":"国家对从事测绘活动的单位实行测绘资质管理制度。"},{"i":28,"n":"第二十八条","txt":"国务院测绘地理信息主管部门和省、自治区、直辖市人民政府测绘地理信息主管部门按照各自的职责负责测绘资质审查、发放测绘资质证书。具体办法由国务院测绘地理信息主管部门商国务院其他有关部门规定。"},{"i":29,"n":"第二十九条","txt":"测绘单位不得超越资质等级许可的范围从事测绘活动，不得以其他测绘单位的名义从事测绘活动，不得允许其他单位以本单位的名义从事测绘活动。"},{"i":30,"n":"第三十条","txt":"从事测绘活动的专业技术人员应当具备相应的执业资格条件。具体办法由国务院测绘地理信息主管部门会同国务院人力资源社会保障主管部门规定。"},{"i":31,"n":"第三十一条","txt":"测绘人员进行测绘活动时，应当持有测绘作业证件。"},{"i":32,"n":"第三十二条","txt":"测绘单位的测绘资质证书、测绘专业技术人员的执业证书和测绘人员的测绘作业证件的式样，由国务院测绘地理信息主管部门统一规定。"},{"i":33,"n":"第三十三条","txt":"国家实行测绘成果汇交制度。国家依法保护测绘成果的知识产权。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府测绘地理信息主管部门应当积极推进公众版测绘成果的加工和编制工作，通过提供公众版测绘成果、保密技术处理等方式，促进测绘成果的社会化应用。"},{"i":35,"n":"第三十五条","txt":"使用财政资金的测绘项目和涉及测绘的其他使用财政资金的项目，有关部门在批准立项前应当征求本级人民政府测绘地理信息主管部门的意见；有适宜测绘成果的，应当充分利用已有的测绘成果，避免重复测绘。"},{"i":36,"n":"第三十六条","txt":"基础测绘成果和国家投资完成的其他测绘成果，用于政府决策、国防建设和公共服务的，应当无偿提供。"},{"i":37,"n":"第三十七条","txt":"中华人民共和国领域和中华人民共和国管辖的其他海域的位置、高程、深度、面积、长度等重要地理信息数据，由国务院测绘地理信息主管部门审核，并与国务院其他有关部门、军队测绘部门会商后，报国务院批准，由国务院或者国务院授权的部门公布。"},{"i":38,"n":"第三十八条","txt":"地图的编制、出版、展示、登载及更新应当遵守国家有关地图编制标准、地图内容表示、地图审核的规定。"},{"i":39,"n":"第三十九条","txt":"测绘单位应当对完成的测绘成果质量负责。县级以上人民政府测绘地理信息主管部门应当加强对测绘成果质量的监督管理。"},{"i":40,"n":"第四十条","txt":"国家鼓励发展地理信息产业，推动地理信息产业结构调整和优化升级，支持开发各类地理信息产品，提高产品质量，推广使用安全可信的地理信息技术和设备。"},{"i":41,"n":"第四十一条","txt":"任何单位和个人不得损毁或者擅自移动永久性测量标志和正在使用中的临时性测量标志，不得侵占永久性测量标志用地，不得在永久性测量标志安全控制范围内从事危害测量标志安全和使用效能的活动。"},{"i":42,"n":"第四十二条","txt":"永久性测量标志的建设单位应当对永久性测量标志设立明显标记，并委托当地有关单位指派专人负责保管。"},{"i":43,"n":"第四十三条","txt":"进行工程建设，应当避开永久性测量标志；确实无法避开，需要拆迁永久性测量标志或者使永久性测量标志失去使用效能的，应当经省、自治区、直辖市人民政府测绘地理信息主管部门批准；涉及军用控制点的，应当征得军队测绘部门的同意。所需迁建费用由工程建设单位承担。"},{"i":44,"n":"第四十四条","txt":"测绘人员使用永久性测量标志，应当持有测绘作业证件，并保证测量标志的完好。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府应当采取有效措施加强测量标志的保护工作。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府测绘地理信息主管部门应当会同本级人民政府其他有关部门建立地理信息安全管理制度和技术防控体系，并加强对地理信息安全的监督管理。"},{"i":47,"n":"第四十七条","txt":"地理信息生产、保管、利用单位应当对属于国家秘密的地理信息的获取、持有、提供、利用情况进行登记并长期保存，实行可追溯管理。"},{"i":48,"n":"第四十八条","txt":"县级以上人民政府测绘地理信息主管部门应当对测绘单位实行信用管理，并依法将其信用信息予以公示。"},{"i":49,"n":"第四十九条","txt":"县级以上人民政府测绘地理信息主管部门应当建立健全随机抽查机制，依法履行监督检查职责，发现涉嫌违反本法规定行为的，可以依法采取下列措施："},{"i":50,"n":"第五十条","txt":"违反本法规定，县级以上人民政府测绘地理信息主管部门或者其他有关部门工作人员利用职务上的便利收受他人财物、其他好处或者玩忽职守，对不符合法定条件的单位核发测绘资质证书，不依法履行监督管理职责，或者发现违法行为不予查处的，对负有责任的领导人员和直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"违反本法规定，外国的组织或者个人未经批准，或者未与中华人民共和国有关部门、单位合作，擅自从事测绘活动的，责令停止违法行为，没收违法所得、测绘成果和测绘工具，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上一百万元以下的罚款，限期出境或者驱逐出境；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，未经批准擅自建立相对独立的平面坐标系统，或者采用不符合国家标准的基础地理信息数据建立地理信息系统的，给予警告，责令改正，可以并处五十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":53,"n":"第五十三条","txt":"违反本法规定，卫星导航定位基准站建设单位未报备案的，给予警告，责令限期改正；逾期不改正的，处十万元以上三十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，卫星导航定位基准站的建设和运行维护不符合国家标准、要求的，给予警告，责令限期改正，没收违法所得和测绘成果，并处三十万元以上五十万元以下的罚款；逾期不改正的，没收相关设备；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，未取得测绘资质证书，擅自从事测绘活动的，责令停止违法行为，没收违法所得和测绘成果，并处测绘约定报酬一倍以上二倍以下的罚款；情节严重的，没收测绘工具。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，测绘单位有下列行为之一的，责令停止违法行为，没收违法所得和测绘成果，处测绘约定报酬一倍以上二倍以下的罚款，并可以责令停业整顿或者降低测绘资质等级；情节严重的，吊销测绘资质证书："},{"i":57,"n":"第五十七条","txt":"违反本法规定，测绘项目的招标单位让不具有相应资质等级的测绘单位中标，或者让测绘单位低于测绘成本中标的，责令改正，可以处测绘约定报酬二倍以下的罚款。招标单位的工作人员利用职务上的便利，索取他人财物，或者非法收受他人财物为他人谋取利益的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，中标的测绘单位向他人转让测绘项目的，责令改正，没收违法所得，处测绘约定报酬一倍以上二倍以下的罚款，并可以责令停业整顿或者降低测绘资质等级；情节严重的，吊销测绘资质证书。"},{"i":59,"n":"第五十九条","txt":"违反本法规定，未取得测绘执业资格，擅自从事测绘活动的，责令停止违法行为，没收违法所得和测绘成果，对其所在单位可以处违法所得二倍以下的罚款；情节严重的，没收测绘工具；造成损失的，依法承担赔偿责任。"},{"i":60,"n":"第六十条","txt":"违反本法规定，不汇交测绘成果资料的，责令限期汇交；测绘项目出资人逾期不汇交的，处重测所需费用一倍以上二倍以下的罚款；承担国家投资的测绘项目的单位逾期不汇交的，处五万元以上二十万元以下的罚款，并处暂扣测绘资质证书，自暂扣测绘资质证书之日起六个月内仍不汇交的，吊销测绘资质证书；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，擅自发布中华人民共和国领域和中华人民共和国管辖的其他海域的重要地理信息数据的，给予警告，责令改正，可以并处五十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，编制、出版、展示、登载、更新的地图或者互联网地图服务不符合国家有关地图管理规定的，依法给予行政处罚、处分；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，测绘成果质量不合格的，责令测绘单位补测或者重测；情节严重的，责令停业整顿，并处降低测绘资质等级或者吊销测绘资质证书；造成损失的，依法承担赔偿责任。"},{"i":64,"n":"第六十四条","txt":"违反本法规定，有下列行为之一的，给予警告，责令改正，可以并处二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，依法给予处分；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任："},{"i":65,"n":"第六十五条","txt":"违反本法规定，地理信息生产、保管、利用单位未对属于国家秘密的地理信息的获取、持有、提供、利用情况进行登记、长期保存的，给予警告，责令改正，可以并处二十万元以下的罚款；泄露国家秘密的，责令停业整顿，并处降低测绘资质等级或者吊销测绘资质证书；构成犯罪的，依法追究刑事责任。"},{"i":66,"n":"第六十六条","txt":"本法规定的降低测绘资质等级、暂扣测绘资质证书、吊销测绘资质证书的行政处罚，由颁发测绘资质证书的部门决定；其他行政处罚，由县级以上人民政府测绘地理信息主管部门决定。"},{"i":67,"n":"第六十七条","txt":"军事测绘管理办法由中央军事委员会根据本法规定。"},{"i":68,"n":"第六十八条","txt":"本法自2017年7月1日起施行。"}],"haishangjiaotonganquanfa":[{"i":1,"n":"第一条","txt":"为了加强海上交通管理，维护海上交通秩序，保障生命财产安全，维护国家权益，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国管辖海域内从事航行、停泊、作业以及其他与海上交通安全相关的活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家依法保障交通用海。"},{"i":4,"n":"第四条","txt":"国务院交通运输主管部门主管全国海上交通安全工作。"},{"i":5,"n":"第五条","txt":"各级人民政府及有关部门应当支持海上交通安全工作，加强海上交通安全的宣传教育，提高全社会的海上交通安全意识。"},{"i":6,"n":"第六条","txt":"国家依法保障船员的劳动安全和职业健康，维护船员的合法权益。"},{"i":7,"n":"第七条","txt":"从事船舶、海上设施航行、停泊、作业以及其他与海上交通相关活动的单位、个人，应当遵守有关海上交通安全的法律、行政法规、规章以及强制性标准和技术规范；依法享有获得航海保障和海上救助的权利，承担维护海上交通安全和保护海洋生态环境的义务。"},{"i":8,"n":"第八条","txt":"国家鼓励和支持先进科学技术在海上交通安全工作中的应用，促进海上交通安全现代化建设，提高海上交通安全科学技术水平。"},{"i":9,"n":"第九条","txt":"中国籍船舶、在中华人民共和国管辖海域设置的海上设施、船运集装箱，以及国家海事管理机构确定的关系海上交通安全的重要船用设备、部件和材料，应当符合有关法律、行政法规、规章以及强制性标准和技术规范的要求，经船舶检验机构检验合格，取得相应证书、文书。证书、文书的清单由国家海事管理机构制定并公布。"},{"i":10,"n":"第十条","txt":"船舶依照有关船舶登记的法律、行政法规的规定向海事管理机构申请船舶国籍登记、取得国籍证书后，方可悬挂中华人民共和国国旗航行、停泊、作业。"},{"i":11,"n":"第十一条","txt":"中国籍船舶所有人、经营人或者管理人应当建立并运行安全营运和防治船舶污染管理体系。"},{"i":12,"n":"第十二条","txt":"中国籍国际航行船舶的所有人、经营人或者管理人应当依照国务院交通运输主管部门的规定建立船舶保安制度，制定船舶保安计划，并按照船舶保安计划配备船舶保安设备，定期开展演练。"},{"i":13,"n":"第十三条","txt":"中国籍船员和海上设施上的工作人员应当接受海上交通安全以及相应岗位的专业教育、培训。"},{"i":14,"n":"第十四条","txt":"中国籍船舶的所有人、经营人或者管理人应当为其国际航行船舶向海事管理机构申请取得海事劳工证书。船舶取得海事劳工证书应当符合下列条件："},{"i":15,"n":"第十五条","txt":"海事管理机构依照有关船员管理的法律、行政法规的规定，对单位从事海船船员培训业务进行管理。"},{"i":16,"n":"第十六条","txt":"国务院交通运输主管部门和其他有关部门、有关县级以上地方人民政府应当建立健全船员境外突发事件预警和应急处置机制，制定船员境外突发事件应急预案。"},{"i":17,"n":"第十七条","txt":"本章第九条至第十二条、第十四条规定适用的船舶范围由有关法律、行政法规具体规定，或者由国务院交通运输主管部门拟定并报国务院批准后公布。"},{"i":18,"n":"第十八条","txt":"国务院交通运输主管部门统筹规划和管理海上交通资源，促进海上交通资源的合理开发和有效利用。"},{"i":19,"n":"第十九条","txt":"海事管理机构根据海域的自然状况、海上交通状况以及海上交通安全管理的需要，划定、调整并及时公布船舶定线区、船舶报告区、交通管制区、禁航区、安全作业区和港外锚地等海上交通功能区域。"},{"i":20,"n":"第二十条","txt":"建设海洋工程、海岸工程影响海上交通安全的，应当根据情况配备防止船舶碰撞的设施、设备并设置专用航标。"},{"i":21,"n":"第二十一条","txt":"国家建立完善船舶定位、导航、授时、通信和远程监测等海上交通支持服务系统，为船舶、海上设施提供信息服务。"},{"i":22,"n":"第二十二条","txt":"任何单位、个人不得损坏海上交通支持服务系统或者妨碍其工作效能。建设建筑物、构筑物，使用设施设备可能影响海上交通支持服务系统正常使用的，建设单位、所有人或者使用人应当与相关海上交通支持服务系统的管理单位协商，作出妥善安排。"},{"i":23,"n":"第二十三条","txt":"国务院交通运输主管部门应当采取必要的措施，保障海上交通安全无线电通信设施的合理布局和有效覆盖，规划本系统（行业）海上无线电台（站）的建设布局和台址，核发船舶制式无线电台执照及电台识别码。"},{"i":24,"n":"第二十四条","txt":"船舶在中华人民共和国管辖海域内通信需要使用岸基无线电台（站）转接的，应当通过依法设置的境内海岸无线电台（站）或者卫星关口站进行转接。"},{"i":25,"n":"第二十五条","txt":"天文、气象、海洋等有关单位应当及时预报、播发和提供航海天文、世界时、海洋气象、海浪、海流、潮汐、冰情等信息。"},{"i":26,"n":"第二十六条","txt":"国务院交通运输主管部门统一布局、建设和管理公用航标。海洋工程、海岸工程的建设单位、所有人或者经营人需要设置、撤除专用航标，移动专用航标位置或者改变航标灯光、功率等的，应当报经海事管理机构同意。需要设置临时航标的，应当符合海事管理机构确定的航标设置点。"},{"i":27,"n":"第二十七条","txt":"任何单位、个人发现下列情形之一的，应当立即向海事管理机构报告；涉及航道管理机构职责或者专用航标的，海事管理机构应当及时通报航道管理机构或者专用航标的所有人："},{"i":28,"n":"第二十八条","txt":"海事管理机构应当依据海上交通安全管理的需要，就具有紧迫性、危险性的情况发布航行警告，就其他影响海上交通安全的情况发布航行通告。"},{"i":29,"n":"第二十九条","txt":"海事管理机构应当及时向船舶、海上设施播发海上交通安全信息。"},{"i":30,"n":"第三十条","txt":"下列船舶在国务院交通运输主管部门划定的引航区内航行、停泊或者移泊的，应当向引航机构申请引航："},{"i":31,"n":"第三十一条","txt":"引航机构应当及时派遣具有相应能力、经验的引航员为船舶提供引航服务。"},{"i":32,"n":"第三十二条","txt":"国务院交通运输主管部门根据船舶、海上设施和港口面临的保安威胁情形，确定并及时发布保安等级。船舶、海上设施和港口应当根据保安等级采取相应的保安措施。"},{"i":33,"n":"第三十三条","txt":"船舶航行、停泊、作业，应当持有有效的船舶国籍证书及其他法定证书、文书，配备依照有关规定出版的航海图书资料，悬挂相关国家、地区或者组织的旗帜，标明船名、船舶识别号、船籍港、载重线标志。"},{"i":34,"n":"第三十四条","txt":"船长应当在船舶开航前检查并在开航时确认船员适任、船舶适航、货物适载，并了解气象和海况信息以及海事管理机构发布的航行通告、航行警告及其他警示信息，落实相应的应急措施，不得冒险开航。"},{"i":35,"n":"第三十五条","txt":"船舶应当在其船舶检验证书载明的航区内航行、停泊、作业。"},{"i":36,"n":"第三十六条","txt":"船舶在航行中应当按照有关规定开启船舶的自动识别、航行数据记录、远程识别和跟踪、通信等与航行安全、保安、防治污染相关的装置，并持续进行显示和记录。"},{"i":37,"n":"第三十七条","txt":"船舶应当配备航海日志、轮机日志、无线电记录簿等航行记录，按照有关规定全面、真实、及时记录涉及海上交通安全的船舶操作以及船舶航行、停泊、作业中的重要事件，并妥善保管相关记录簿。"},{"i":38,"n":"第三十八条","txt":"船长负责管理和指挥船舶。在保障海上生命安全、船舶保安和防治船舶污染方面，船长有权独立作出决定。"},{"i":39,"n":"第三十九条","txt":"为了保障船舶和在船人员的安全，船长有权在职责范围内对涉嫌在船上进行违法犯罪活动的人员采取禁闭或者其他必要的限制措施，并防止其隐匿、毁灭、伪造证据。"},{"i":40,"n":"第四十条","txt":"发现在船人员患有或者疑似患有严重威胁他人健康的传染病的，船长应当立即启动相应的应急预案，在职责范围内对相关人员采取必要的隔离措施，并及时报告有关主管部门。"},{"i":41,"n":"第四十一条","txt":"船长在航行中死亡或者因故不能履行职责的，应当由驾驶员中职务最高的人代理船长职务；船舶在下一个港口开航前，其所有人、经营人或者管理人应当指派新船长接任。"},{"i":42,"n":"第四十二条","txt":"船员应当按照有关航行、值班的规章制度和操作规程以及船长的指令操纵、管理船舶，保持安全值班，不得擅离职守。船员履行在船值班职责前和值班期间，不得摄入可能影响安全值班的食品、药品或者其他物品。"},{"i":43,"n":"第四十三条","txt":"船舶进出港口、锚地或者通过桥区水域、海峡、狭水道、重要渔业水域、通航船舶密集的区域、船舶定线区、交通管制区，应当加强瞭望、保持安全航速，并遵守前述区域的特殊航行规则。"},{"i":44,"n":"第四十四条","txt":"船舶不得违反规定进入或者穿越禁航区。"},{"i":45,"n":"第四十五条","txt":"船舶载运或者拖带超长、超高、超宽、半潜的船舶、海上设施或者其他物体航行，应当采取拖拽部位加强、护航等特殊的安全保障措施，在开航前向海事管理机构报告航行计划，并按有关规定显示信号、悬挂标志；拖带移动式平台、浮船坞等大型海上设施的，还应当依法交验船舶检验机构出具的拖航检验证书。"},{"i":46,"n":"第四十六条","txt":"国际航行船舶进出口岸，应当依法向海事管理机构申请许可并接受海事管理机构及其他口岸查验机构的监督检查。海事管理机构应当自受理申请之日起五个工作日内作出许可或者不予许可的决定。"},{"i":47,"n":"第四十七条","txt":"船舶应当在符合安全条件的码头、泊位、装卸站、锚地、安全作业区停泊。船舶停泊不得危及其他船舶、海上设施的安全。"},{"i":48,"n":"第四十八条","txt":"在中华人民共和国管辖海域内进行施工作业，应当经海事管理机构许可，并核定相应安全作业区。取得海上施工作业许可，应当符合下列条件："},{"i":49,"n":"第四十九条","txt":"从事体育、娱乐、演练、试航、科学观测等水上水下活动，应当遵守海上交通安全管理规定；可能影响海上交通安全的，应当提前十个工作日将活动涉及的海域范围报告海事管理机构。"},{"i":50,"n":"第五十条","txt":"海上施工作业或者水上水下活动结束后，有关单位、个人应当及时消除可能妨碍海上交通安全的隐患。"},{"i":51,"n":"第五十一条","txt":"碍航物的所有人、经营人或者管理人应当按照有关强制性标准和技术规范的要求及时设置警示标志，向海事管理机构报告碍航物的名称、形状、尺寸、位置和深度，并在海事管理机构限定的期限内打捞清除。碍航物的所有人放弃所有权的，不免除其打捞清除义务。"},{"i":52,"n":"第五十二条","txt":"有下列情形之一，对海上交通安全有较大影响的，海事管理机构应当根据具体情况采取停航、限速或者划定交通管制区等相应交通管制措施并向社会公告："},{"i":53,"n":"第五十三条","txt":"国务院交通运输主管部门为维护海上交通安全、保护海洋环境，可以会同有关主管部门采取必要措施，防止和制止外国籍船舶在领海的非无害通过。"},{"i":54,"n":"第五十四条","txt":"下列外国籍船舶进出中华人民共和国领海，应当向海事管理机构报告："},{"i":55,"n":"第五十五条","txt":"除依照本法规定获得进入口岸许可外，外国籍船舶不得进入中华人民共和国内水；但是，因人员病急、机件故障、遇难、避风等紧急情况未及获得许可的可以进入。"},{"i":56,"n":"第五十六条","txt":"中华人民共和国军用船舶执行军事任务、公务船舶执行公务，遇有紧急情况，在保证海上交通安全的前提下，可以不受航行、停泊、作业有关规则的限制。"},{"i":57,"n":"第五十七条","txt":"除进行抢险或者生命救助外，客船应当按照船舶检验证书核定的载客定额载运乘客，货船载运货物应当符合船舶检验证书核定的载重线和载货种类，不得载运乘客。"},{"i":58,"n":"第五十八条","txt":"客船载运乘客不得同时载运危险货物。"},{"i":59,"n":"第五十九条","txt":"客船应当在显著位置向乘客明示安全须知，设置安全标志和警示，并向乘客介绍救生用具的使用方法以及在紧急情况下应当采取的应急措施。乘客应当遵守安全乘船要求。"},{"i":60,"n":"第六十条","txt":"海上渡口所在地的县级以上地方人民政府应当建立健全渡口安全管理责任制，制定海上渡口的安全管理办法，监督、指导海上渡口经营者落实安全主体责任，维护渡运秩序，保障渡运安全。"},{"i":61,"n":"第六十一条","txt":"船舶载运货物，应当按照有关法律、行政法规、规章以及强制性标准和技术规范的要求安全装卸、积载、隔离、系固和管理。"},{"i":62,"n":"第六十二条","txt":"船舶载运危险货物，应当持有有效的危险货物适装证书，并根据危险货物的特性和应急措施的要求，编制危险货物应急处置预案，配备相应的消防、应急设备和器材。"},{"i":63,"n":"第六十三条","txt":"托运人托运危险货物，应当将其正式名称、危险性质以及应当采取的防护措施通知承运人，并按照有关法律、行政法规、规章以及强制性标准和技术规范的要求妥善包装，设置明显的危险品标志和标签。"},{"i":64,"n":"第六十四条","txt":"船舶载运危险货物进出港口，应当符合下列条件，经海事管理机构许可，并向海事管理机构报告进出港口和停留的时间等事项："},{"i":65,"n":"第六十五条","txt":"船舶、海上设施从事危险货物运输或者装卸、过驳作业，应当编制作业方案，遵守有关强制性标准和安全作业操作规程，采取必要的预防措施，防止发生安全事故。"},{"i":66,"n":"第六十六条","txt":"海上遇险人员依法享有获得生命救助的权利。生命救助优先于环境和财产救助。"},{"i":67,"n":"第六十七条","txt":"海上搜救工作应当坚持政府领导、统一指挥、属地为主、专群结合、就近快速的原则。"},{"i":68,"n":"第六十八条","txt":"国家建立海上搜救协调机制，统筹全国海上搜救应急反应工作，研究解决海上搜救工作中的重大问题，组织协调重大海上搜救应急行动。协调机制由国务院有关部门、单位和有关军事机关组成。"},{"i":69,"n":"第六十九条","txt":"沿海县级以上地方人民政府应当安排必要的海上搜救资金，保障搜救工作的正常开展。"},{"i":70,"n":"第七十条","txt":"海上搜救中心各成员单位应当在海上搜救中心统一组织、协调、指挥下，根据各自职责，承担海上搜救应急、抢险救灾、支持保障、善后处理等工作。"},{"i":71,"n":"第七十一条","txt":"国家设立专业海上搜救队伍，加强海上搜救力量建设。专业海上搜救队伍应当配备专业搜救装备，建立定期演练和日常培训制度，提升搜救水平。"},{"i":72,"n":"第七十二条","txt":"船舶、海上设施、航空器及人员在海上遇险的，应当立即报告海上搜救中心，不得瞒报、谎报海上险情。"},{"i":73,"n":"第七十三条","txt":"发生碰撞事故的船舶、海上设施，应当互通名称、国籍和登记港，在不严重危及自身安全的情况下尽力救助对方人员，不得擅自离开事故现场水域或者逃逸。"},{"i":74,"n":"第七十四条","txt":"遇险的船舶、海上设施及其所有人、经营人或者管理人应当采取有效措施防止、减少生命财产损失和海洋环境污染。"},{"i":75,"n":"第七十五条","txt":"船舶、海上设施、航空器收到求救信号或者发现有人遭遇生命危险的，在不严重危及自身安全的情况下，应当尽力救助遇险人员。"},{"i":76,"n":"第七十六条","txt":"海上搜救中心接到险情报告后，应当立即进行核实，及时组织、协调、指挥政府有关部门、专业搜救队伍、社会有关单位等各方力量参加搜救，并指定现场指挥。参加搜救的船舶、海上设施、航空器及人员应当服从现场指挥，及时报告搜救动态和搜救结果。"},{"i":77,"n":"第七十七条","txt":"遇险船舶、海上设施、航空器或者遇险人员应当服从海上搜救中心和现场指挥的指令，及时接受救助。"},{"i":78,"n":"第七十八条","txt":"海上事故或者险情发生后，有关地方人民政府应当及时组织医疗机构为遇险人员提供紧急医疗救助，为获救人员提供必要的生活保障，并组织有关方面采取善后措施。"},{"i":79,"n":"第七十九条","txt":"在中华人民共和国缔结或者参加的国际条约规定由我国承担搜救义务的海域内开展搜救，依照本章规定执行。"},{"i":80,"n":"第八十条","txt":"船舶、海上设施发生海上交通事故，应当及时向海事管理机构报告，并接受调查。"},{"i":81,"n":"第八十一条","txt":"海上交通事故根据造成的损害后果分为特别重大事故、重大事故、较大事故和一般事故。事故等级划分的人身伤亡标准依照有关安全生产的法律、行政法规的规定确定；事故等级划分的直接经济损失标准，由国务院交通运输主管部门会同国务院有关部门根据海上交通事故中的特殊情况确定，报国务院批准后公布施行。"},{"i":82,"n":"第八十二条","txt":"特别重大海上交通事故由国务院或者国务院授权的部门组织事故调查组进行调查，海事管理机构应当参与或者配合开展调查工作。"},{"i":83,"n":"第八十三条","txt":"调查海上交通事故，应当全面、客观、公正、及时，依法查明事故事实和原因，认定事故责任。"},{"i":84,"n":"第八十四条","txt":"海事管理机构可以根据事故调查处理需要拆封、拆解当事船舶的航行数据记录装置或者读取其记录的信息，要求船舶驶向指定地点或者禁止其离港，扣留船舶或者海上设施的证书、文书、物品、资料等并妥善保管。有关人员应当配合事故调查。"},{"i":85,"n":"第八十五条","txt":"海上交通事故调查组应当自事故发生之日起九十日内提交海上交通事故调查报告；特殊情况下，经负责组织事故调查组的部门负责人批准，提交事故调查报告的期限可以适当延长，但延长期限最长不得超过九十日。事故技术鉴定所需时间不计入事故调查期限。"},{"i":86,"n":"第八十六条","txt":"中国籍船舶在中华人民共和国管辖海域外发生海上交通事故的，应当及时向海事管理机构报告事故情况并接受调查。"},{"i":87,"n":"第八十七条","txt":"船舶、海上设施在海上遭遇恶劣天气、海况以及意外事故，造成或者可能造成损害，需要说明并记录时间、海域以及所采取的应对措施等具体情况的，可以向海事管理机构申请办理海事声明签注。海事管理机构应当依照规定提供签注服务。"},{"i":88,"n":"第八十八条","txt":"海事管理机构对在中华人民共和国管辖海域内从事航行、停泊、作业以及其他与海上交通安全相关的活动，依法实施监督检查。"},{"i":89,"n":"第八十九条","txt":"海事管理机构实施监督检查可以采取登船检查、查验证书、现场检查、询问有关人员、电子监控等方式。"},{"i":90,"n":"第九十条","txt":"海事管理机构对船舶、海上设施实施监督检查时，应当避免、减少对其正常作业的影响。"},{"i":91,"n":"第九十一条","txt":"船舶、海上设施对港口安全具有威胁的，海事管理机构应当责令立即或者限期改正、限制操作，责令驶往指定地点、禁止进港或者将其驱逐出港。"},{"i":92,"n":"第九十二条","txt":"外国籍船舶可能威胁中华人民共和国内水、领海安全的，海事管理机构有权责令其离开。"},{"i":93,"n":"第九十三条","txt":"任何单位、个人有权向海事管理机构举报妨碍海上交通安全的行为。海事管理机构接到举报后，应当及时进行核实、处理。"},{"i":94,"n":"第九十四条","txt":"海事管理机构在监督检查中，发现船舶、海上设施有违反其他法律、行政法规行为的，应当依法及时通报或者移送有关主管部门处理。"},{"i":95,"n":"第九十五条","txt":"船舶、海上设施未持有有效的证书、文书的，由海事管理机构责令改正，对违法船舶或者海上设施的所有人、经营人或者管理人处三万元以上三十万元以下的罚款，对船长和有关责任人员处三千元以上三万元以下的罚款；情节严重的，暂扣船长、责任船员的船员适任证书十八个月至三十个月，直至吊销船员适任证书；对船舶持有的伪造、变造证书、文书，予以没收；对存在严重安全隐患的船舶，可以依法予以没收。"},{"i":96,"n":"第九十六条","txt":"船舶或者海上设施有下列情形之一的，由海事管理机构责令改正，对违法船舶或者海上设施的所有人、经营人或者管理人处二万元以上二十万元以下的罚款，对船长和有关责任人员处二千元以上二万元以下的罚款；情节严重的，吊销违法船舶所有人、经营人或者管理人的有关证书、文书，暂扣船长、责任船员的船员适任证书十二个月至二十四个月，直至吊销船员适任证书："},{"i":97,"n":"第九十七条","txt":"在船舶上工作未持有船员适任证书、船员健康证明或者所持船员适任证书、健康证明不符合要求的，由海事管理机构对船舶的所有人、经营人或者管理人处一万元以上十万元以下的罚款，对责任船员处三千元以上三万元以下的罚款；情节严重的，对船舶的所有人、经营人或者管理人处三万元以上三十万元以下的罚款，暂扣责任船员的船员适任证书六个月至十二个月，直至吊销船员适任证书。"},{"i":98,"n":"第九十八条","txt":"以欺骗、贿赂等不正当手段为中国籍船舶取得相关证书、文书的，由海事管理机构撤销有关许可，没收相关证书、文书，对船舶所有人、经营人或者管理人处四万元以上四十万元以下的罚款。"},{"i":99,"n":"第九十九条","txt":"船员未保持安全值班，违反规定摄入可能影响安全值班的食品、药品或者其他物品，或者有其他违反海上船员值班规则的行为的，由海事管理机构对船长、责任船员处一千元以上一万元以下的罚款，或者暂扣船员适任证书三个月至十二个月；情节严重的，吊销船长、责任船员的船员适任证书。"},{"i":100,"n":"第一百条","txt":"有下列情形之一的，由海事管理机构责令改正；情节严重的，处三万元以上十万元以下的罚款："},{"i":101,"n":"第一百零一条","txt":"有下列情形之一的，由海事管理机构责令改正，对有关责任人员处三万元以下的罚款；情节严重的，处三万元以上十万元以下的罚款，并暂扣责任船员的船员适任证书一个月至三个月："},{"i":102,"n":"第一百零二条","txt":"船舶未依照本法规定申请引航的，由海事管理机构对违法船舶的所有人、经营人或者管理人处五万元以上五十万元以下的罚款，对船长处一千元以上一万元以下的罚款；情节严重的，暂扣有关船舶证书三个月至十二个月，暂扣船长的船员适任证书一个月至三个月。"},{"i":103,"n":"第一百零三条","txt":"船舶在海上航行、停泊、作业，有下列情形之一的，由海事管理机构责令改正，对违法船舶的所有人、经营人或者管理人处二万元以上二十万元以下的罚款，对船长、责任船员处二千元以上二万元以下的罚款，暂扣船员适任证书三个月至十二个月；情节严重的，吊销船长、责任船员的船员适任证书："},{"i":104,"n":"第一百零四条","txt":"国际航行船舶未经许可进出口岸的，由海事管理机构对违法船舶的所有人、经营人或者管理人处三千元以上三万元以下的罚款，对船长、责任船员或者其他责任人员，处二千元以上二万元以下的罚款；情节严重的，吊销船长、责任船员的船员适任证书。"},{"i":105,"n":"第一百零五条","txt":"船舶、海上设施未经许可从事海上施工作业，或者未按照许可要求、超出核定的安全作业区进行作业的，由海事管理机构责令改正，对违法船舶、海上设施的所有人、经营人或者管理人处三万元以上三十万元以下的罚款，对船长、责任船员处三千元以上三万元以下的罚款，或者暂扣船员适任证书六个月至十二个月；情节严重的，吊销船长、责任船员的船员适任证书。"},{"i":106,"n":"第一百零六条","txt":"碍航物的所有人、经营人或者管理人有下列情形之一的，由海事管理机构责令改正，处二万元以上二十万元以下的罚款；逾期未改正的，海事管理机构有权依法实施代履行，代履行的费用由碍航物的所有人、经营人或者管理人承担："},{"i":107,"n":"第一百零七条","txt":"外国籍船舶进出中华人民共和国内水、领海违反本法规定的，由海事管理机构对违法船舶的所有人、经营人或者管理人处五万元以上五十万元以下的罚款，对船长处一万元以上三万元以下的罚款。"},{"i":108,"n":"第一百零八条","txt":"载运危险货物的船舶有下列情形之一的，海事管理机构应当责令改正，对违法船舶的所有人、经营人或者管理人处五万元以上五十万元以下的罚款，对船长、责任船员或者其他责任人员，处五千元以上五万元以下的罚款；情节严重的，责令停止作业或者航行，暂扣船长、责任船员的船员适任证书六个月至十二个月，直至吊销船员适任证书："},{"i":109,"n":"第一百零九条","txt":"托运人托运危险货物，有下列情形之一的，由海事管理机构责令改正，处五万元以上三十万元以下的罚款："},{"i":110,"n":"第一百一十条","txt":"船舶、海上设施遇险或者发生海上交通事故后未履行报告义务，或者存在瞒报、谎报情形的，由海事管理机构对违法船舶、海上设施的所有人、经营人或者管理人处三千元以上三万元以下的罚款，对船长、责任船员处二千元以上二万元以下的罚款，暂扣船员适任证书六个月至二十四个月；情节严重的，对违法船舶、海上设施的所有人、经营人或者管理人处一万元以上十万元以下的罚款，吊销船长、责任船员的船员适任证书。"},{"i":111,"n":"第一百一十一条","txt":"船舶发生海上交通事故后逃逸的，由海事管理机构对违法船舶的所有人、经营人或者管理人处十万元以上五十万元以下的罚款，对船长、责任船员处五千元以上五万元以下的罚款并吊销船员适任证书，受处罚者终身不得重新申请。"},{"i":112,"n":"第一百一十二条","txt":"船舶、海上设施不依法履行海上救助义务，不服从海上搜救中心指挥的，由海事管理机构对船舶、海上设施的所有人、经营人或者管理人处三万元以上三十万元以下的罚款，暂扣船长、责任船员的船员适任证书六个月至十二个月，直至吊销船员适任证书。"},{"i":113,"n":"第一百一十三条","txt":"有关单位、个人拒绝、阻碍海事管理机构监督检查，或者在接受监督检查时弄虚作假的，由海事管理机构处二千元以上二万元以下的罚款，暂扣船长、责任船员的船员适任证书六个月至二十四个月，直至吊销船员适任证书。"},{"i":114,"n":"第一百一十四条","txt":"交通运输主管部门、海事管理机构及其他有关部门的工作人员违反本法规定，滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":115,"n":"第一百一十五条","txt":"因海上交通事故引发民事纠纷的，当事人可以依法申请仲裁或者向人民法院提起诉讼。"},{"i":116,"n":"第一百一十六条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；造成人身、财产损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":117,"n":"第一百一十七条","txt":"本法下列用语的含义是："},{"i":118,"n":"第一百一十八条","txt":"公务船舶检验、船员配备的具体办法由国务院交通运输主管部门会同有关主管部门另行制定。"},{"i":119,"n":"第一百一十九条","txt":"海上军事管辖区和军用船舶、海上设施的内部海上交通安全管理，军用航标的设立和管理，以及为军事目的进行作业或者水上水下活动的管理，由中央军事委员会另行制定管理办法。"},{"i":120,"n":"第一百二十条","txt":"外国籍公务船舶在中华人民共和国领海航行、停泊、作业，违反中华人民共和国法律、行政法规的，依照有关法律、行政法规的规定处理。"},{"i":121,"n":"第一百二十一条","txt":"中华人民共和国缔结或者参加的国际条约同本法有不同规定的，适用国际条约的规定，但中华人民共和国声明保留的条款除外。"},{"i":122,"n":"第一百二十二条","txt":"本法自2021年9月1日起施行。"}],"haiguanguanxiantiaoli":[{"i":1,"n":"第一条","txt":"为了加强海关队伍建设，增强海关工作人员的责任感、荣誉感和组织纪律性，有利于海关工作人员依法履行职责，根据宪法，制定本条例。"},{"i":2,"n":"第二条","txt":"海关实行关衔制度。海关总署、分署、特派员办公室、各直属海关、隶属海关和办事处的国家公务员可以授予海关关衔。"},{"i":3,"n":"第三条","txt":"关衔是区分海关工作人员等级、表明海关工作人员身份的称号、标志和国家给予海关工作人员的荣誉。"},{"i":4,"n":"第四条","txt":"海关工作人员实行职务等级编制关衔。"},{"i":5,"n":"第五条","txt":"关衔高的海关工作人员对关衔低的海关工作人员，关衔高的为上级。当关衔高的海关工作人员在职务上隶属于关衔低的海关工作人员时，职务高的为上级。"},{"i":6,"n":"第六条","txt":"海关总署主管关衔工作。"},{"i":7,"n":"第七条","txt":"海关关衔设下列五等十三级："},{"i":8,"n":"第八条","txt":"海关工作人员实行下列职务等级编制关衔："},{"i":9,"n":"第九条","txt":"关衔的授予以海关工作人员现任职务、德才表现、任职时间和工作年限为依据。"},{"i":10,"n":"第十条","txt":"海关招考录用海关工作人员或者从其他部门调任海关工作人员，在确定职务后授予相应的关衔。"},{"i":11,"n":"第十一条","txt":"关衔按照下列规定权限批准授予："},{"i":12,"n":"第十二条","txt":"二级关务督察以下关衔的海关工作人员，在其职务等级编制关衔幅度内，按照下列期限晋级："},{"i":13,"n":"第十三条","txt":"二级关务督察以下关衔的海关工作人员，晋级期限届满，经考核具备晋级条件的，应当逐级晋升；不具备晋级条件的，应当延期晋升。在工作中有突出功绩的，经批准可以提前晋升。"},{"i":14,"n":"第十四条","txt":"一级关务督察以上关衔的海关工作人员晋级，在职务等级编制关衔幅度内，根据其德才表现和工作实绩实行选升。"},{"i":15,"n":"第十五条","txt":"海关工作人员提升职务，其关衔低于新任职务等级编制关衔的最低关衔的，应当晋升至新任职务等级编制关衔的最低关衔。"},{"i":16,"n":"第十六条","txt":"关务员晋升关务督办，关务督办晋升关务督察，关务督察晋升关务监督，经培训合格后，方可晋升。"},{"i":17,"n":"第十七条","txt":"关衔晋级的批准权限适用本条例第十一条的规定。"},{"i":18,"n":"第十八条","txt":"海关工作人员退休后，其关衔予以保留，但不得佩带标志。"},{"i":19,"n":"第十九条","txt":"海关工作人员因不胜任现任职务被调任下级职务的，其关衔高于新任职务等级编制关衔的最高关衔的，应当降级至新任职务等级编制关衔的最高关衔。关衔降级的批准权限与原关衔的批准权限相同。"},{"i":20,"n":"第二十条","txt":"海关工作人员受到降级、撤职行政处分的，应当相应降低关衔。关衔降级的批准权限与原关衔的批准权限相同。关衔降级后，其关衔晋级的期限按照降级后的关衔等级重新计算。"},{"i":21,"n":"第二十一条","txt":"海关工作人员受到开除行政处分的，因犯罪被依法判处剥夺政治权利或者有期徒刑以上刑罚的，其关衔相应取消，并且不再履行批准手续。"},{"i":22,"n":"第二十二条","txt":"海关关衔标志式样和佩带办法，由国务院规定。"},{"i":23,"n":"第二十三条","txt":"本条例自公布之日起施行。"}],"haiguanfa":[{"i":1,"n":"第一条","txt":"为了维护国家的主权和利益，加强海关监督管理，促进对外经济贸易和科技文化交往，保障社会主义现代化建设，特制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国海关是国家的进出关境（以下简称进出境）监督管理机关。海关依照本法和其他有关法律、行政法规，监管进出境的运输工具、货物、行李物品、邮递物品和其他物品（以下简称进出境运输工具、货物、物品），征收关税和其他税、费，查缉走私，并编制海关统计和办理其他海关业务。"},{"i":3,"n":"第三条","txt":"国务院设立海关总署，统一管理全国海关。"},{"i":4,"n":"第四条","txt":"国家在海关总署设立专门侦查走私犯罪的公安机构，配备专职缉私警察，负责对其管辖的走私犯罪案件的侦查、拘留、执行逮捕、预审。"},{"i":5,"n":"第五条","txt":"国家实行联合缉私、统一处理、综合治理的缉私体制。海关负责组织、协调、管理查缉走私工作。有关规定由国务院另行制定。"},{"i":6,"n":"第六条","txt":"海关可以行使下列权力："},{"i":7,"n":"第七条","txt":"各地方、各部门应当支持海关依法行使职权，不得非法干预海关的执法活动。"},{"i":8,"n":"第八条","txt":"进出境运输工具、货物、物品，必须通过设立海关的地点进境或者出境。在特殊情况下，需要经过未设立海关的地点临时进境或者出境的，必须经国务院或者国务院授权的机关批准，并依照本法规定办理海关手续。"},{"i":9,"n":"第九条","txt":"进出口货物，除另有规定的外，可以由进出口货物收发货人自行办理报关纳税手续，也可以由进出口货物收发货人委托报关企业办理报关纳税手续。"},{"i":10,"n":"第十条","txt":"报关企业接受进出口货物收发货人的委托，以委托人的名义办理报关手续的，应当向海关提交由委托人签署的授权委托书，遵守本法对委托人的各项规定。"},{"i":11,"n":"第十一条","txt":"进出口货物收发货人、报关企业办理报关手续，应当依法向海关备案。"},{"i":12,"n":"第十二条","txt":"海关依法执行职务，有关单位和个人应当如实回答询问，并予以配合，任何单位和个人不得阻挠。"},{"i":13,"n":"第十三条","txt":"海关建立对违反本法规定逃避海关监管行为的举报制度。"},{"i":14,"n":"第十四条","txt":"进出境运输工具到达或者驶离设立海关的地点时，运输工具负责人应当向海关如实申报，交验单证，并接受海关监管和检查。"},{"i":15,"n":"第十五条","txt":"进境运输工具在进境以后向海关申报以前，出境运输工具在办结海关手续以后出境以前，应当按照交通主管机关规定的路线行进；交通主管机关没有规定的，由海关指定。"},{"i":16,"n":"第十六条","txt":"进出境船舶、火车、航空器到达和驶离时间、停留地点、停留期间更换地点以及装卸货物、物品时间，运输工具负责人或者有关交通运输部门应当事先通知海关。"},{"i":17,"n":"第十七条","txt":"运输工具装卸进出境货物、物品或者上下进出境旅客，应当接受海关监管。"},{"i":18,"n":"第十八条","txt":"海关检查进出境运输工具时，运输工具负责人应当到场，并根据海关的要求开启舱室、房间、车门；有走私嫌疑的，并应当开拆可能藏匿走私货物、物品的部位，搬移货物、物料。"},{"i":19,"n":"第十九条","txt":"进境的境外运输工具和出境的境内运输工具，未向海关办理手续并缴纳关税，不得转让或者移作他用。"},{"i":20,"n":"第二十条","txt":"进出境船舶和航空器兼营境内客、货运输，应当符合海关监管要求。"},{"i":21,"n":"第二十一条","txt":"沿海运输船舶、渔船和从事海上作业的特种船舶，未经海关同意，不得载运或者换取、买卖、转让进出境货物、物品。"},{"i":22,"n":"第二十二条","txt":"进出境船舶和航空器，由于不可抗力的原因，被迫在未设立海关的地点停泊、降落或者抛掷、起卸货物、物品，运输工具负责人应当立即报告附近海关。"},{"i":23,"n":"第二十三条","txt":"进口货物自进境起到办结海关手续止，出口货物自向海关申报起到出境止，过境、转运和通运货物自进境起到出境止，应当接受海关监管。"},{"i":24,"n":"第二十四条","txt":"进口货物的收货人、出口货物的发货人应当向海关如实申报，交验进出口许可证件和有关单证。国家限制进出口的货物，没有进出口许可证件的，不予放行，具体处理办法由国务院规定。"},{"i":25,"n":"第二十五条","txt":"办理进出口货物的海关申报手续，应当采用纸质报关单和电子数据报关单的形式。"},{"i":26,"n":"第二十六条","txt":"海关接受申报后，报关单证及其内容不得修改或者撤销，但符合海关规定情形的除外。"},{"i":27,"n":"第二十七条","txt":"进口货物的收货人经海关同意，可以在申报前查看货物或者提取货样。需要依法检疫的货物，应当在检疫合格后提取货样。"},{"i":28,"n":"第二十八条","txt":"进出口货物应当接受海关查验。海关查验货物时，进口货物的收货人、出口货物的发货人应当到场，并负责搬移货物，开拆和重封货物的包装。海关认为必要时，可以径行开验、复验或者提取货样。"},{"i":29,"n":"第二十九条","txt":"除海关特准的外，进出口货物在收发货人缴清税款或者提供担保后，由海关签印放行。"},{"i":30,"n":"第三十条","txt":"进口货物的收货人自运输工具申报进境之日起超过三个月未向海关申报的，其进口货物由海关提取依法变卖处理，所得价款在扣除运输、装卸、储存等费用和税款后，尚有余款的，自货物依法变卖之日起一年内，经收货人申请，予以发还；其中属于国家对进口有限制性规定，应当提交许可证件而不能提供的，不予发还。逾期无人申请或者不予发还的，上缴国库。"},{"i":31,"n":"第三十一条","txt":"按照法律、行政法规、国务院或者海关总署规定暂时进口或者暂时出口的货物，应当在六个月内复运出境或者复运进境；需要延长复运出境或者复运进境期限的，应当根据海关总署的规定办理延期手续。"},{"i":32,"n":"第三十二条","txt":"经营保税货物的储存、加工、装配、展示、运输、寄售业务和经营免税商店，应当符合海关监管要求，经海关批准，并办理注册手续。"},{"i":33,"n":"第三十三条","txt":"企业从事加工贸易，应当按照海关总署的规定向海关备案。加工贸易制成品单位耗料量由海关按照有关规定核定。"},{"i":34,"n":"第三十四条","txt":"经国务院批准在中华人民共和国境内设立的保税区等海关特殊监管区域，由海关按照国家有关规定实施监管。"},{"i":35,"n":"第三十五条","txt":"进口货物应当由收货人在货物的进境地海关办理海关手续，出口货物应当由发货人在货物的出境地海关办理海关手续。"},{"i":36,"n":"第三十六条","txt":"过境、转运和通运货物，运输工具负责人应当向进境地海关如实申报，并应当在规定期限内运输出境。"},{"i":37,"n":"第三十七条","txt":"海关监管货物，未经海关许可，不得开拆、提取、交付、发运、调换、改装、抵押、质押、留置、转让、更换标记、移作他用或者进行其他处置。"},{"i":38,"n":"第三十八条","txt":"经营海关监管货物仓储业务的企业，应当经海关注册，并按照海关规定，办理收存、交付手续。"},{"i":39,"n":"第三十九条","txt":"进出境集装箱的监管办法、打捞进出境货物和沉船的监管办法、边境小额贸易进出口货物的监管办法，以及本法未具体列明的其他进出境货物的监管办法，由海关总署或者由海关总署会同国务院有关部门另行制定。"},{"i":40,"n":"第四十条","txt":"国家对进出境货物、物品有禁止性或者限制性规定的，海关依据法律、行政法规、国务院的规定或者国务院有关部门依据法律、行政法规的授权作出的规定实施监管。具体监管办法由海关总署制定。"},{"i":41,"n":"第四十一条","txt":"进出口货物的原产地按照国家有关原产地规则的规定确定。"},{"i":42,"n":"第四十二条","txt":"进出口货物的商品归类按照国家有关商品归类的规定确定。"},{"i":43,"n":"第四十三条","txt":"海关可以根据对外贸易经营者提出的书面申请，对拟作进口或者出口的货物预先作出商品归类等行政裁定。"},{"i":44,"n":"第四十四条","txt":"海关依照法律、行政法规的规定，对与进出境货物有关的知识产权实施保护。"},{"i":45,"n":"第四十五条","txt":"自进出口货物放行之日起三年内或者在保税货物、减免税进口货物的海关监管期限内及其后的三年内，海关可以对与进出口货物直接有关的企业、单位的会计帐簿、会计凭证、报关单证以及其他有关资料和有关进出口货物实施稽查。具体办法由国务院规定。"},{"i":46,"n":"第四十六条","txt":"个人携带进出境的行李物品、邮寄进出境的物品，应当以自用、合理数量为限，并接受海关监管。"},{"i":47,"n":"第四十七条","txt":"进出境物品的所有人应当向海关如实申报，并接受海关查验。"},{"i":48,"n":"第四十八条","txt":"进出境邮袋的装卸、转运和过境，应当接受海关监管。邮政企业应当向海关递交邮件路单。"},{"i":49,"n":"第四十九条","txt":"邮运进出境的物品，经海关查验放行后，有关经营单位方可投递或者交付。"},{"i":50,"n":"第五十条","txt":"经海关登记准予暂时免税进境或者暂时免税出境的物品，应当由本人复带出境或者复带进境。"},{"i":51,"n":"第五十一条","txt":"进出境物品所有人声明放弃的物品、在海关规定期限内未办理海关手续或者无人认领的物品，以及无法投递又无法退回的进境邮递物品，由海关依照本法第三十条的规定处理。"},{"i":52,"n":"第五十二条","txt":"享有外交特权和豁免的外国机构或者人员的公务用品或者自用物品进出境，依照有关法律、行政法规的规定办理。"},{"i":53,"n":"第五十三条","txt":"准许进出口的货物、进出境物品，由海关依法征收关税。"},{"i":54,"n":"第五十四条","txt":"进口货物的收货人、出口货物的发货人、进出境物品的所有人，是关税的纳税义务人。"},{"i":55,"n":"第五十五条","txt":"进出口货物的完税价格，由海关以该货物的成交价格为基础审查确定。成交价格不能确定时，完税价格由海关依法估定。"},{"i":56,"n":"第五十六条","txt":"下列进出口货物、进出境物品，减征或者免征关税："},{"i":57,"n":"第五十七条","txt":"特定地区、特定企业或者有特定用途的进出口货物，可以减征或者免征关税。特定减税或者免税的范围和办法由国务院规定。"},{"i":58,"n":"第五十八条","txt":"本法第五十六条、第五十七条第一款规定范围以外的临时减征或者免征关税，由国务院决定。"},{"i":59,"n":"第五十九条","txt":"暂时进口或者暂时出口的货物，以及特准进口的保税货物，在货物收发货人向海关缴纳相当于税款的保证金或者提供担保后，准予暂时免纳关税。"},{"i":60,"n":"第六十条","txt":"进出口货物的纳税义务人，应当自海关填发税款缴款书之日起十五日内缴纳税款；逾期缴纳的，由海关征收滞纳金。纳税义务人、担保人超过三个月仍未缴纳的，经直属海关关长或者其授权的隶属海关关长批准，海关可以采取下列强制措施："},{"i":61,"n":"第六十一条","txt":"进出口货物的纳税义务人在规定的纳税期限内有明显的转移、藏匿其应税货物以及其他财产迹象的，海关可以责令纳税义务人提供担保；纳税义务人不能提供纳税担保的，经直属海关关长或者其授权的隶属海关关长批准，海关可以采取下列税收保全措施："},{"i":62,"n":"第六十二条","txt":"进出口货物、进出境物品放行后，海关发现少征或者漏征税款，应当自缴纳税款或者货物、物品放行之日起一年内，向纳税义务人补征。因纳税义务人违反规定而造成的少征或者漏征，海关在三年以内可以追征。"},{"i":63,"n":"第六十三条","txt":"海关多征的税款，海关发现后应当立即退还；纳税义务人自缴纳税款之日起一年内，可以要求海关退还。"},{"i":64,"n":"第六十四条","txt":"纳税义务人同海关发生纳税争议时，应当缴纳税款，并可以依法申请行政复议；对复议决定仍不服的，可以依法向人民法院提起诉讼。"},{"i":65,"n":"第六十五条","txt":"进口环节海关代征税的征收管理，适用关税征收管理的规定。"},{"i":66,"n":"第六十六条","txt":"在确定货物的商品归类、估价和提供有效报关单证或者办结其他海关手续前，收发货人要求放行货物的，海关应当在其提供与其依法应当履行的法律义务相适应的担保后放行。法律、行政法规规定可以免除担保的除外。"},{"i":67,"n":"第六十七条","txt":"具有履行海关事务担保能力的法人、其他组织或者公民，可以成为担保人。法律规定不得为担保人的除外。"},{"i":68,"n":"第六十八条","txt":"担保人可以以下列财产、权利提供担保："},{"i":69,"n":"第六十九条","txt":"担保人应当在担保期限内承担担保责任。担保人履行担保责任的，不免除被担保人应当办理有关海关手续的义务。"},{"i":70,"n":"第七十条","txt":"海关事务担保管理办法，由国务院规定。"},{"i":71,"n":"第七十一条","txt":"海关履行职责，必须遵守法律，维护国家利益，依照法定职权和法定程序严格执法，接受监督。"},{"i":72,"n":"第七十二条","txt":"海关工作人员必须秉公执法，廉洁自律，忠于职守，文明服务，不得有下列行为："},{"i":73,"n":"第七十三条","txt":"海关应当根据依法履行职责的需要，加强队伍建设，使海关工作人员具有良好的政治、业务素质。"},{"i":74,"n":"第七十四条","txt":"海关总署应当实行海关关长定期交流制度。"},{"i":75,"n":"第七十五条","txt":"海关及其工作人员的行政执法活动，依法接受监察机关的监督；缉私警察进行侦查活动，依法接受人民检察院的监督。"},{"i":76,"n":"第七十六条","txt":"审计机关依法对海关的财政收支进行审计监督，对海关办理的与国家财政收支有关的事项，有权进行专项审计调查。"},{"i":77,"n":"第七十七条","txt":"上级海关应当对下级海关的执法活动依法进行监督。上级海关认为下级海关作出的处理或者决定不适当的，可以依法予以变更或者撤销。"},{"i":78,"n":"第七十八条","txt":"海关应当依照本法和其他有关法律、行政法规的规定，建立健全内部监督制度，对其工作人员执行法律、行政法规和遵守纪律的情况，进行监督检查。"},{"i":79,"n":"第七十九条","txt":"海关内部负责审单、查验、放行、稽查和调查等主要岗位的职责权限应当明确，并相互分离、相互制约。"},{"i":80,"n":"第八十条","txt":"任何单位和个人均有权对海关及其工作人员的违法、违纪行为进行控告、检举。收到控告、检举的机关有权处理的，应当依法按照职责分工及时查处。收到控告、检举的机关和负责查处的机关应当为控告人、检举人保密。"},{"i":81,"n":"第八十一条","txt":"海关工作人员在调查处理违法案件时，遇有下列情形之一的，应当回避："},{"i":82,"n":"第八十二条","txt":"违反本法及有关法律、行政法规，逃避海关监管，偷逃应纳税款、逃避国家有关进出境的禁止性或者限制性管理，有下列情形之一的，是走私行为："},{"i":83,"n":"第八十三条","txt":"有下列行为之一的，按走私行为论处，依照本法第八十二条的规定处罚："},{"i":84,"n":"第八十四条","txt":"伪造、变造、买卖海关单证，与走私人通谋为走私人提供贷款、资金、帐号、发票、证明、海关单证，与走私人通谋为走私人提供运输、保管、邮寄或者其他方便，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由海关没收违法所得，并处罚款。"},{"i":85,"n":"第八十五条","txt":"个人携带、邮寄超过合理数量的自用物品进出境，未依法向海关申报的，责令补缴关税，可以处以罚款。"},{"i":86,"n":"第八十六条","txt":"违反本法规定有下列行为之一的，可以处以罚款，有违法所得的，没收违法所得："},{"i":87,"n":"第八十七条","txt":"海关准予从事有关业务的企业，违反本法有关规定的，由海关责令改正，可以给予警告，暂停其从事有关业务，直至撤销注册。"},{"i":88,"n":"第八十八条","txt":"未向海关备案从事报关业务的，海关可以处以罚款。"},{"i":89,"n":"第八十九条","txt":"报关企业非法代理他人报关的，由海关责令改正，处以罚款；情节严重的，禁止其从事报关活动。"},{"i":90,"n":"第九十条","txt":"进出口货物收发货人、报关企业向海关工作人员行贿的，由海关禁止其从事报关活动，并处以罚款；构成犯罪的，依法追究刑事责任。"},{"i":91,"n":"第九十一条","txt":"违反本法规定进出口侵犯中华人民共和国法律、行政法规保护的知识产权的货物的，由海关依法没收侵权货物，并处以罚款；构成犯罪的，依法追究刑事责任。"},{"i":92,"n":"第九十二条","txt":"海关依法扣留的货物、物品、运输工具，在人民法院判决或者海关处罚决定作出之前，不得处理。但是，危险品或者鲜活、易腐、易失效等不宜长期保存的货物、物品以及所有人申请先行变卖的货物、物品、运输工具，经直属海关关长或者其授权的隶属海关关长批准，可以先行依法变卖，变卖所得价款由海关保存，并通知其所有人。"},{"i":93,"n":"第九十三条","txt":"当事人逾期不履行海关的处罚决定又不申请复议或者向人民法院提起诉讼的，作出处罚决定的海关可以将其保证金抵缴或者将其被扣留的货物、物品、运输工具依法变价抵缴，也可以申请人民法院强制执行。"},{"i":94,"n":"第九十四条","txt":"海关在查验进出境货物、物品时，损坏被查验的货物、物品的，应当赔偿实际损失。"},{"i":95,"n":"第九十五条","txt":"海关违法扣留货物、物品、运输工具，致使当事人的合法权益受到损失的，应当依法承担赔偿责任。"},{"i":96,"n":"第九十六条","txt":"海关工作人员有本法第七十二条所列行为之一的，依法给予行政处分；有违法所得的，依法没收违法所得；构成犯罪的，依法追究刑事责任。"},{"i":97,"n":"第九十七条","txt":"海关的财政收支违反法律、行政法规规定的，由审计机关以及有关部门依照法律、行政法规的规定作出处理；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":98,"n":"第九十八条","txt":"未按照本法规定为控告人、检举人、举报人保密的，对直接负责的主管人员和其他直接责任人员，由所在单位或者有关单位依法给予行政处分。"},{"i":99,"n":"第九十九条","txt":"海关工作人员在调查处理违法案件时，未按照本法规定进行回避的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分。"},{"i":100,"n":"第一百条","txt":"本法下列用语的含义："},{"i":101,"n":"第一百零一条","txt":"经济特区等特定地区同境内其他地区之间往来的运输工具、货物、物品的监管办法，由国务院另行规定。"},{"i":102,"n":"第一百零二条","txt":"本法自1987年7月1日起施行。1951年4月18日中央人民政府公布的《中华人民共和国暂行海关法》同时废止。"}],"haijingfa":[{"i":1,"n":"第一条","txt":"为了规范和保障海警机构履行职责，维护国家主权、安全和海洋权益，保护公民、法人和其他组织的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"人民武装警察部队海警部队即海警机构，统一履行海上维权执法职责。"},{"i":3,"n":"第三条","txt":"海警机构在中华人民共和国管辖海域（以下简称我国管辖海域）及其上空开展海上维权执法活动，适用本法。"},{"i":4,"n":"第四条","txt":"海上维权执法工作坚持中国共产党的领导，贯彻总体国家安全观，遵循依法管理、综合治理、规范高效、公正文明的原则。"},{"i":5,"n":"第五条","txt":"海上维权执法工作的基本任务是开展海上安全保卫，维护海上治安秩序，打击海上走私、偷渡，在职责范围内对海洋资源开发利用、海洋生态环境保护、海洋渔业生产作业等活动进行监督检查，预防、制止和惩治海上违法犯罪活动。"},{"i":6,"n":"第六条","txt":"海警机构及其工作人员依法执行职务受法律保护，任何组织和个人不得非法干涉、拒绝和阻碍。"},{"i":7,"n":"第七条","txt":"海警机构工作人员应当遵守宪法和法律，崇尚荣誉，忠于职守，纪律严明，严格执法，清正廉洁。"},{"i":8,"n":"第八条","txt":"国家建立陆海统筹、分工合作、科学高效的海上维权执法协作配合机制。国务院有关部门、沿海地方人民政府、军队有关部门和海警机构应当相互加强协作配合，做好海上维权执法工作。"},{"i":9,"n":"第九条","txt":"对在海上维权执法活动中做出突出贡献的组织和个人，依照有关法律、法规的规定给予表彰和奖励。"},{"i":10,"n":"第十条","txt":"国家在沿海地区按照行政区划和任务区域编设中国海警局海区分局和直属局、省级海警局、市级海警局和海警工作站，分别负责所管辖区域的有关海上维权执法工作。中国海警局按照国家有关规定领导所属海警机构开展海上维权执法工作。"},{"i":11,"n":"第十一条","txt":"海警机构管辖区域应当根据海上维权执法工作的需要合理划定和调整，可以不受行政区划限制。"},{"i":12,"n":"第十二条","txt":"海警机构依法履行下列职责："},{"i":13,"n":"第十三条","txt":"海警机构接到因海上自然灾害、事故灾难等紧急求助，应当及时通报有关主管部门，并积极开展应急救援和救助。"},{"i":14,"n":"第十四条","txt":"中央国家机关按照国家有关规定对海上维权执法工作实行业务指导。"},{"i":15,"n":"第十五条","txt":"中国海警局及其海区分局按照国家有关规定，协调指导沿海地方人民政府海上执法队伍开展海域使用、海岛保护开发、海洋生态环境保护、海洋渔业管理等相关执法工作。"},{"i":16,"n":"第十六条","txt":"为维护海上安全和秩序，海警机构有权依法对在我国管辖海域航行、停泊、作业的外国船舶进行识别查证，判明船舶的基本信息及其航行、作业的基本情况。对有违法嫌疑的外国船舶，海警机构有权采取跟踪监视等措施。"},{"i":17,"n":"第十七条","txt":"对非法进入我国领海及其以内海域的外国船舶，海警机构有权责令其立即离开，或者采取扣留、强制驱离、强制拖离等措施。"},{"i":18,"n":"第十八条","txt":"海警机构执行海上安全保卫任务，可以对在我国管辖海域航行、停泊、作业的船舶依法登临、检查。"},{"i":19,"n":"第十九条","txt":"海警机构因处置海上突发事件的紧急需要，可以采取下列措施："},{"i":20,"n":"第二十条","txt":"未经我国主管机关批准，外国组织和个人在我国管辖海域和岛礁建造建筑物、构筑物，以及布设各类固定或者浮动装置的，海警机构有权责令其停止上述违法行为或者限期拆除；对拒不停止违法行为或者逾期不拆除的，海警机构有权予以制止或者强制拆除。"},{"i":21,"n":"第二十一条","txt":"对外国军用船舶和用于非商业目的的外国政府船舶在我国管辖海域违反我国法律、法规的行为，海警机构有权采取必要的警戒和管制措施予以制止，责令其立即离开相关海域；对拒不离开并造成严重危害或者威胁的，海警机构有权采取强制驱离、强制拖离等措施。"},{"i":22,"n":"第二十二条","txt":"国家主权、主权权利和管辖权在海上正在受到外国组织和个人的不法侵害或者面临不法侵害的紧迫危险时，海警机构有权依照本法和其他相关法律、法规，采取包括使用武器在内的一切必要措施制止侵害、排除危险。"},{"i":23,"n":"第二十三条","txt":"海警机构对违反海上治安、海关、海洋资源开发利用、海洋生态环境保护、海洋渔业管理等法律、法规、规章的组织和个人，依法实施包括限制人身自由在内的行政处罚、行政强制或者法律、法规规定的其他措施。"},{"i":24,"n":"第二十四条","txt":"海警机构因开展行政执法需要登临、检查、拦截、紧追相关船舶的，依照本法第十八条规定执行。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一，省级海警局以上海警机构可以在我国管辖海域划定海上临时警戒区，限制或者禁止船舶、人员通行、停留："},{"i":26,"n":"第二十六条","txt":"对涉嫌违法正在接受调查处理的船舶，海警机构可以责令其暂停航行、作业，在指定地点停泊或者禁止其离港。必要时，海警机构可以将嫌疑船舶押解至指定地点接受调查处理。"},{"i":27,"n":"第二十七条","txt":"国际组织、外国组织和个人的船舶经我国主管机关批准在我国管辖海域从事渔业生产作业以及其他自然资源勘查开发、海洋科学研究、海底电（光）缆和管道铺设等活动的，海警机构应当依法进行监管，可以派出执法人员随船监管。"},{"i":28,"n":"第二十八条","txt":"为预防、制止和惩治在我国陆地领土、内水或者领海内违反有关安全、海关、财政、卫生或者入境出境管理法律、法规的行为，海警机构有权在毗连区行使管制权，依法实施行政强制措施或者法律、法规规定的其他措施。"},{"i":29,"n":"第二十九条","txt":"违法事实确凿，并有下列情形之一，海警机构执法人员可以当场作出处罚决定："},{"i":30,"n":"第三十条","txt":"对不适用当场处罚，但事实清楚，当事人自愿认错认罚，且对违法事实和法律适用没有异议的海上行政案件，海警机构征得当事人书面同意后，可以通过简化取证方式和审核审批等措施快速办理。"},{"i":31,"n":"第三十一条","txt":"海上行政案件有下列情形之一，不适用快速办理："},{"i":32,"n":"第三十二条","txt":"海警机构实施行政强制措施前，执法人员应当向本单位负责人报告并经批准。情况紧急，需要在海上当场实施行政强制措施的，应当在二十四小时内向本单位负责人报告，抵岸后及时补办批准手续；因不可抗力无法在二十四小时内向本单位负责人报告的，应当在不可抗力影响消除后二十四小时内向本单位负责人报告。海警机构负责人认为不应当采取行政强制措施的，应当立即解除。"},{"i":33,"n":"第三十三条","txt":"当事人逾期不履行处罚决定的，作出处罚决定的海警机构可以依法采取下列措施："},{"i":34,"n":"第三十四条","txt":"各级海警机构对海上行政案件的管辖分工，由中国海警局规定。"},{"i":35,"n":"第三十五条","txt":"海警机构办理海上行政案件时，有证据证明当事人在海上实施将物品倒入海中等故意毁灭证据的行为，给海警机构举证造成困难的，可以结合其他证据，推定有关违法事实成立，但是当事人有证据足以推翻的除外。"},{"i":36,"n":"第三十六条","txt":"海警机构开展巡航、警戒、拦截、紧追等海上执法工作，使用标示有专用标志的执法船舶、航空器的，即为表明身份。"},{"i":37,"n":"第三十七条","txt":"海警机构开展海上行政执法的程序，本法未作规定的，适用《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》、《中华人民共和国治安管理处罚法》等有关法律的规定。"},{"i":38,"n":"第三十八条","txt":"海警机构办理海上发生的刑事案件，依照《中华人民共和国刑事诉讼法》和本法的有关规定行使侦查权，采取侦查措施和刑事强制措施。"},{"i":39,"n":"第三十九条","txt":"海警机构在立案后，对于危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、重大毒品犯罪或者其他严重危害社会的犯罪案件，依照《中华人民共和国刑事诉讼法》和有关规定，经过严格的批准手续，可以采取技术侦查措施，按照规定交由有关机关执行。"},{"i":40,"n":"第四十条","txt":"应当逮捕的犯罪嫌疑人在逃，海警机构可以按照规定发布通缉令，采取有效措施，追捕归案。"},{"i":41,"n":"第四十一条","txt":"海警机构因办理海上刑事案件需要登临、检查、拦截、紧追相关船舶的，依照本法第十八条规定执行。"},{"i":42,"n":"第四十二条","txt":"海警机构、人民检察院、人民法院依法对海上刑事案件的犯罪嫌疑人、被告人决定取保候审的，由被取保候审人居住地的海警机构执行。被取保候审人居住地未设海警机构的，当地公安机关应当协助执行。"},{"i":43,"n":"第四十三条","txt":"海警机构、人民检察院、人民法院依法对海上刑事案件的犯罪嫌疑人、被告人决定监视居住的，由海警机构在被监视居住人住处执行；被监视居住人在负责办案的海警机构所在的市、县没有固定住处的，可以在指定的居所执行。对于涉嫌危害国家安全犯罪、恐怖活动犯罪，在住处执行可能有碍侦查的，经上一级海警机构批准，也可以在指定的居所执行。但是，不得在羁押场所、专门的办案场所执行。"},{"i":44,"n":"第四十四条","txt":"海警工作站负责侦查发生在本管辖区域内的海上刑事案件。"},{"i":45,"n":"第四十五条","txt":"海警机构办理海上刑事案件，需要提请批准逮捕或者移送起诉的，应当向所在地相应人民检察院提请或者移送。"},{"i":46,"n":"第四十六条","txt":"有下列情形之一，海警机构工作人员可以使用警械或者现场的其他装备、工具："},{"i":47,"n":"第四十七条","txt":"有下列情形之一，经警告无效的，海警机构工作人员可以使用手持武器："},{"i":48,"n":"第四十八条","txt":"有下列情形之一，海警机构工作人员除可以使用手持武器外，还可以使用舰载或者机载武器："},{"i":49,"n":"第四十九条","txt":"海警机构工作人员依法使用武器，来不及警告或者警告后可能导致更为严重危害后果的，可以直接使用武器。"},{"i":50,"n":"第五十条","txt":"海警机构工作人员应当根据违法犯罪行为和违法犯罪行为人的危险性质、程度和紧迫性，合理判断使用武器的必要限度，尽量避免或者减少不必要的人员伤亡、财产损失。"},{"i":51,"n":"第五十一条","txt":"海警机构工作人员使用警械和武器，本法未作规定的，依照人民警察使用警械和武器的规定以及其他有关法律、法规的规定执行。"},{"i":52,"n":"第五十二条","txt":"国家建立与海警机构担负海上维权执法任务和建设发展相适应的经费保障机制。所需经费按照国家有关规定列入预算。"},{"i":53,"n":"第五十三条","txt":"国务院有关部门、沿海县级以上地方人民政府及其有关部门在编制国土空间规划和相关专项规划时，应当统筹海上维权执法工作需求，按照国家有关规定对海警机构执法办案、执勤训练、生活等场地和设施建设等予以保障。"},{"i":54,"n":"第五十四条","txt":"海警机构因海上维权执法紧急需要，可以依照法律、法规、规章的规定优先使用或者征用组织和个人的交通工具、通信工具、场地，用后应当及时归还，并支付适当费用；造成损失的，按照国家有关规定给予补偿。"},{"i":55,"n":"第五十五条","txt":"海警机构应当优化力量体系，建强人才队伍，加强教育培训，保障海警机构工作人员具备履行法定职责的知识、技能和素质，提高海上维权执法专业能力。"},{"i":56,"n":"第五十六条","txt":"国家加强海上维权执法装备体系建设，保障海警机构配备与其履行职责相适应的船舶、航空器、武器以及其他装备。"},{"i":57,"n":"第五十七条","txt":"海警机构应当加强信息化建设，运用现代信息技术，促进执法公开，强化便民服务，提高海上维权执法工作效率。"},{"i":58,"n":"第五十八条","txt":"海警机构分别与相应的外交（外事）、公安、自然资源、生态环境、交通运输、渔业渔政、应急管理、海关等主管部门，以及人民法院、人民检察院和军队有关部门建立信息共享和工作协作配合机制。"},{"i":59,"n":"第五十九条","txt":"海警机构因开展海上维权执法工作需要，可以向有关主管部门提出协助请求。协助请求属于有关主管部门职责范围内的，有关主管部门应当配合。"},{"i":60,"n":"第六十条","txt":"海警机构对依法决定行政拘留的违法行为人和拘留审查的外国人，以及决定刑事拘留、执行逮捕的犯罪嫌疑人，分别送海警机构所在地拘留所或者看守所执行。"},{"i":61,"n":"第六十一条","txt":"海警机构对依法扣押、扣留的涉案财物，应当妥善保管，不得损毁或者擅自处理。但是，对下列货物、物品，经市级海警局以上海警机构负责人批准，可以先行依法拍卖或者变卖并通知所有人，所有人不明确的，通知其他当事人："},{"i":62,"n":"第六十二条","txt":"海警机构对应当退还所有人或者其他当事人的涉案财物，通知所有人或者其他当事人在六个月内领取；所有人不明确的，应当采取公告方式告知所有人认领。在通知所有人、其他当事人或者公告后六个月内无人认领的，按无主财物处理，依法拍卖或者变卖后将所得款项上缴国库。遇有特殊情况的，可以延期处理，延长期限最长不超过三个月。"},{"i":63,"n":"第六十三条","txt":"中国海警局根据中华人民共和国缔结、参加的国际条约或者按照对等、互利的原则，开展海上执法国际合作；在规定权限内组织或者参与有关海上执法国际条约实施工作，商签海上执法合作性文件。"},{"i":64,"n":"第六十四条","txt":"海警机构开展海上执法国际合作的主要任务是参与处置涉外海上突发事件，协调解决海上执法争端，管控海上危机，与外国海上执法机构和有关国际组织合作打击海上违法犯罪活动，保护海洋资源环境，共同维护国际和地区海洋公共安全和秩序。"},{"i":65,"n":"第六十五条","txt":"海警机构可以与外国海上执法机构和有关国际组织开展下列海上执法国际合作："},{"i":66,"n":"第六十六条","txt":"海警机构及其工作人员应当依照法律、法规规定的条件、权限和程序履行职责、行使职权，不得滥用职权、玩忽职守、徇私舞弊，不得侵犯组织和个人的合法权益。"},{"i":67,"n":"第六十七条","txt":"海警机构应当尊重和依法保障公民、法人和其他组织对海警机构执法工作的知情权、参与权和监督权，增强执法工作透明度和公信力。"},{"i":68,"n":"第六十八条","txt":"海警机构询问、讯问、继续盘问、辨认违法犯罪嫌疑人以及对违法犯罪嫌疑人进行安全检查、信息采集等执法活动，应当在办案场所进行。紧急情况下必须在现场进行询问、讯问或者有其他不宜在办案场所进行询问、讯问的情形除外。"},{"i":69,"n":"第六十九条","txt":"海警机构及其工作人员开展海上维权执法工作，依法接受检察机关、军队监察机关的监督。"},{"i":70,"n":"第七十条","txt":"人民政府及其有关部门、公民、法人和其他组织对海警机构及其工作人员的违法违纪行为，有权向检察机关、军队监察机关通报、检举、控告。对海警机构及其工作人员正在发生的违法违纪或者失职行为，可以通过海上报警服务平台进行投诉、举报。"},{"i":71,"n":"第七十一条","txt":"上级海警机构应当对下级海警机构的海上维权执法工作进行监督，发现其作出的处理措施或者决定有错误的，有权撤销、变更或者责令下级海警机构撤销、变更；发现其不履行法定职责的，有权责令其依法履行。"},{"i":72,"n":"第七十二条","txt":"中国海警局应当建立健全海上维权执法工作监督机制和执法过错责任追究制度。"},{"i":73,"n":"第七十三条","txt":"有下列阻碍海警机构及其工作人员依法执行职务的行为之一，由公安机关或者海警机构依照《中华人民共和国治安管理处罚法》关于阻碍人民警察依法执行职务的规定予以处罚："},{"i":74,"n":"第七十四条","txt":"海警机构工作人员在执行职务中，有下列行为之一，按照中央军事委员会的有关规定给予处分："},{"i":75,"n":"第七十五条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":76,"n":"第七十六条","txt":"组织和个人对海警机构作出的行政行为不服的，有权依照《中华人民共和国行政复议法》的规定向上一级海警机构申请行政复议；或者依照《中华人民共和国行政诉讼法》的规定向有管辖权的人民法院提起行政诉讼。"},{"i":77,"n":"第七十七条","txt":"海警机构及其工作人员违法行使职权，侵犯组织和个人合法权益造成损害的，应当依照《中华人民共和国国家赔偿法》和其他有关法律、法规的规定给予赔偿。"},{"i":78,"n":"第七十八条","txt":"本法下列用语的含义是："},{"i":79,"n":"第七十九条","txt":"外国在海上执法方面对我国公民、法人和其他组织采取歧视性的禁止、限制或者其他特别措施的，海警机构可以按照国家有关规定采取相应的对等措施。"},{"i":80,"n":"第八十条","txt":"本法规定的对船舶的维权执法措施适用于海上各种固定或者浮动建筑、装置，固定或者移动式平台。"},{"i":81,"n":"第八十一条","txt":"海警机构依照法律、法规和我国缔结、参加的国际条约，在我国管辖海域以外的区域执行执法任务时，相关程序可以参照本法有关规定执行。"},{"i":82,"n":"第八十二条","txt":"中国海警局根据法律、行政法规和国务院、中央军事委员会的决定，就海上维权执法事项制定规章，并按照规定备案。"},{"i":83,"n":"第八十三条","txt":"海警机构依照《中华人民共和国国防法》、《中华人民共和国人民武装警察法》等有关法律、军事法规和中央军事委员会的命令，执行防卫作战等任务。"},{"i":84,"n":"第八十四条","txt":"本法自2021年2月1日起施行。"}],"xiaofangjiuyuanxiantiaoli":[{"i":1,"n":"第一条","txt":"为了加强国家综合性消防救援队伍正规化、专业化、职业化建设，增强消防救援人员的责任感、荣誉感和组织纪律性，有利于国家综合性消防救援队伍的指挥、管理和依法履行职责，根据宪法，制定本条例。"},{"i":2,"n":"第二条","txt":"国家综合性消防救援队伍实行消防救援衔制度。"},{"i":3,"n":"第三条","txt":"消防救援衔是表明消防救援人员身份、区分消防救援人员等级的称号和标志，是国家给予消防救援人员的荣誉和相应待遇的依据。"},{"i":4,"n":"第四条","txt":"消防救援衔高的人员对消防救援衔低的人员，消防救援衔高的为上级。消防救援衔高的人员在职务上隶属于消防救援衔低的人员时，担任领导职务或者领导职务高的为上级。"},{"i":5,"n":"第五条","txt":"国务院应急管理部门主管消防救援衔工作。"},{"i":6,"n":"第六条","txt":"消防救援衔按照管理指挥人员、专业技术人员和消防员分别设置。"},{"i":7,"n":"第七条","txt":"管理指挥人员消防救援衔设下列三等十一级："},{"i":8,"n":"第八条","txt":"专业技术人员消防救援衔设下列二等八级，在消防救援衔前冠以“专业技术”："},{"i":9,"n":"第九条","txt":"消防员消防救援衔设下列三等八级："},{"i":10,"n":"第十条","txt":"管理指挥人员按照下列职务等级编制消防救援衔："},{"i":11,"n":"第十一条","txt":"专业技术人员按照下列职务等级编制消防救援衔："},{"i":12,"n":"第十二条","txt":"消防员按照下列工作年限编制消防救援衔："},{"i":13,"n":"第十三条","txt":"授予消防救援衔，以消防救援人员现任职务、德才表现、学历学位、任职时间和工作年限为依据。"},{"i":14,"n":"第十四条","txt":"初任管理指挥人员、专业技术人员，按照下列规定首次授予消防救援衔："},{"i":15,"n":"第十五条","txt":"初任消防员，按照下列规定首次授予消防救援衔："},{"i":16,"n":"第十六条","txt":"首次授予管理指挥人员、专业技术人员消防救援衔，按照下列规定的权限予以批准："},{"i":17,"n":"第十七条","txt":"首次授予消防员消防救援衔，按照下列规定的权限予以批准："},{"i":18,"n":"第十八条","txt":"消防救援衔一般根据职务等级调整情况或者工作年限逐级晋升。"},{"i":19,"n":"第十九条","txt":"管理指挥人员、专业技术人员的消防救援衔晋升，一般与其职务等级晋升一致。"},{"i":20,"n":"第二十条","txt":"管理指挥人员、专业技术人员消防救援衔晋升，按照下列规定的权限予以批准："},{"i":21,"n":"第二十一条","txt":"消防员消防救援衔晋升，按照下列规定的权限予以批准："},{"i":22,"n":"第二十二条","txt":"消防救援人员在消防救援工作中做出重大贡献、德才表现突出的，其消防救援衔可以提前晋升。"},{"i":23,"n":"第二十三条","txt":"消防救援人员退休后，其消防救援衔予以保留。"},{"i":24,"n":"第二十四条","txt":"消防救援人员因不胜任现任职务被调任下级职务的，其消防救援衔应当调整至相应衔级，调整的批准权限与原衔级的批准权限相同。"},{"i":25,"n":"第二十五条","txt":"消防救援人员受到降级、撤职处分的，应当相应降低消防救援衔，降级的批准权限与原衔级的批准权限相同。"},{"i":26,"n":"第二十六条","txt":"消防救援人员受到开除处分的，以及因犯罪被依法判处剥夺政治权利或者有期徒刑以上刑罚的，其消防救援衔相应取消。"},{"i":27,"n":"第二十七条","txt":"消防救援衔标志式样和佩带办法，由国务院制定。"},{"i":28,"n":"第二十八条","txt":"本条例自2018年10月27日起施行。"}],"xiaofangfa":[{"i":1,"n":"第一条","txt":"为了预防火灾和减少火灾危害，加强应急救援工作，保护人身、财产安全，维护公共安全，制定本法。"},{"i":2,"n":"第二条","txt":"消防工作贯彻预防为主、防消结合的方针，按照政府统一领导、部门依法监管、单位全面负责、公民积极参与的原则，实行消防安全责任制，建立健全社会化的消防工作网络。"},{"i":3,"n":"第三条","txt":"国务院领导全国的消防工作。地方各级人民政府负责本行政区域内的消防工作。"},{"i":4,"n":"第四条","txt":"国务院应急管理部门对全国的消防工作实施监督管理。县级以上地方人民政府应急管理部门对本行政区域内的消防工作实施监督管理，并由本级人民政府消防救援机构负责实施。军事设施的消防工作，由其主管单位监督管理，消防救援机构协助；矿井地下部分、核电厂、海上石油天然气设施的消防工作，由其主管单位监督管理。"},{"i":5,"n":"第五条","txt":"任何单位和个人都有维护消防安全、保护消防设施、预防火灾、报告火警的义务。任何单位和成年人都有参加有组织的灭火工作的义务。"},{"i":6,"n":"第六条","txt":"各级人民政府应当组织开展经常性的消防宣传教育，提高公民的消防安全意识。"},{"i":7,"n":"第七条","txt":"国家鼓励、支持消防科学研究和技术创新，推广使用先进的消防和应急救援技术、设备；鼓励、支持社会力量开展消防公益活动。"},{"i":8,"n":"第八条","txt":"地方各级人民政府应当将包括消防安全布局、消防站、消防供水、消防通信、消防车通道、消防装备等内容的消防规划纳入城乡规划，并负责组织实施。"},{"i":9,"n":"第九条","txt":"建设工程的消防设计、施工必须符合国家工程建设消防技术标准。建设、设计、施工、工程监理等单位依法对建设工程的消防设计、施工质量负责。"},{"i":10,"n":"第十条","txt":"对按照国家工程建设消防技术标准需要进行消防设计的建设工程，实行建设工程消防设计审查验收制度。"},{"i":11,"n":"第十一条","txt":"国务院住房和城乡建设主管部门规定的特殊建设工程，建设单位应当将消防设计文件报送住房和城乡建设主管部门审查，住房和城乡建设主管部门依法对审查的结果负责。"},{"i":12,"n":"第十二条","txt":"特殊建设工程未经消防设计审查或者审查不合格的，建设单位、施工单位不得施工；其他建设工程，建设单位未提供满足施工需要的消防设计图纸及技术资料的，有关部门不得发放施工许可证或者批准开工报告。"},{"i":13,"n":"第十三条","txt":"国务院住房和城乡建设主管部门规定应当申请消防验收的建设工程竣工，建设单位应当向住房和城乡建设主管部门申请消防验收。"},{"i":14,"n":"第十四条","txt":"建设工程消防设计审查、消防验收、备案和抽查的具体办法，由国务院住房和城乡建设主管部门规定。"},{"i":15,"n":"第十五条","txt":"公众聚集场所投入使用、营业前消防安全检查实行告知承诺管理。公众聚集场所在投入使用、营业前，建设单位或者使用单位应当向场所所在地的县级以上地方人民政府消防救援机构申请消防安全检查，作出场所符合消防技术标准和管理规定的承诺，提交规定的材料，并对其承诺和材料的真实性负责。"},{"i":16,"n":"第十六条","txt":"机关、团体、企业、事业等单位应当履行下列消防安全职责："},{"i":17,"n":"第十七条","txt":"县级以上地方人民政府消防救援机构应当将发生火灾可能性较大以及发生火灾可能造成重大的人身伤亡或者财产损失的单位，确定为本行政区域内的消防安全重点单位，并由应急管理部门报本级人民政府备案。"},{"i":18,"n":"第十八条","txt":"同一建筑物由两个以上单位管理或者使用的，应当明确各方的消防安全责任，并确定责任人对共用的疏散通道、安全出口、建筑消防设施和消防车通道进行统一管理。"},{"i":19,"n":"第十九条","txt":"生产、储存、经营易燃易爆危险品的场所不得与居住场所设置在同一建筑物内，并应当与居住场所保持安全距离。"},{"i":20,"n":"第二十条","txt":"举办大型群众性活动，承办人应当依法向公安机关申请安全许可，制定灭火和应急疏散预案并组织演练，明确消防安全责任分工，确定消防安全管理人员，保持消防设施和消防器材配置齐全、完好有效，保证疏散通道、安全出口、疏散指示标志、应急照明和消防车通道符合消防技术标准和管理规定。"},{"i":21,"n":"第二十一条","txt":"禁止在具有火灾、爆炸危险的场所吸烟、使用明火。因施工等特殊情况需要使用明火作业的，应当按照规定事先办理审批手续，采取相应的消防安全措施；作业人员应当遵守消防安全规定。"},{"i":22,"n":"第二十二条","txt":"生产、储存、装卸易燃易爆危险品的工厂、仓库和专用车站、码头的设置，应当符合消防技术标准。易燃易爆气体和液体的充装站、供应站、调压站，应当设置在符合消防安全要求的位置，并符合防火防爆要求。"},{"i":23,"n":"第二十三条","txt":"生产、储存、运输、销售、使用、销毁易燃易爆危险品，必须执行消防技术标准和管理规定。"},{"i":24,"n":"第二十四条","txt":"消防产品必须符合国家标准；没有国家标准的，必须符合行业标准。禁止生产、销售或者使用不合格的消防产品以及国家明令淘汰的消防产品。"},{"i":25,"n":"第二十五条","txt":"产品质量监督部门、工商行政管理部门、消防救援机构应当按照各自职责加强对消防产品质量的监督检查。"},{"i":26,"n":"第二十六条","txt":"建筑构件、建筑材料和室内装修、装饰材料的防火性能必须符合国家标准；没有国家标准的，必须符合行业标准。"},{"i":27,"n":"第二十七条","txt":"电器产品、燃气用具的产品标准，应当符合消防安全的要求。"},{"i":28,"n":"第二十八条","txt":"任何单位、个人不得损坏、挪用或者擅自拆除、停用消防设施、器材，不得埋压、圈占、遮挡消火栓或者占用防火间距，不得占用、堵塞、封闭疏散通道、安全出口、消防车通道。人员密集场所的门窗不得设置影响逃生和灭火救援的障碍物。"},{"i":29,"n":"第二十九条","txt":"负责公共消防设施维护管理的单位，应当保持消防供水、消防通信、消防车通道等公共消防设施的完好有效。在修建道路以及停电、停水、截断通信线路时有可能影响消防队灭火救援的，有关单位必须事先通知当地消防救援机构。"},{"i":30,"n":"第三十条","txt":"地方各级人民政府应当加强对农村消防工作的领导，采取措施加强公共消防设施建设，组织建立和督促落实消防安全责任制。"},{"i":31,"n":"第三十一条","txt":"在农业收获季节、森林和草原防火期间、重大节假日期间以及火灾多发季节，地方各级人民政府应当组织开展有针对性的消防宣传教育，采取防火措施，进行消防安全检查。"},{"i":32,"n":"第三十二条","txt":"乡镇人民政府、城市街道办事处应当指导、支持和帮助村民委员会、居民委员会开展群众性的消防工作。村民委员会、居民委员会应当确定消防安全管理人，组织制定防火安全公约，进行防火安全检查。"},{"i":33,"n":"第三十三条","txt":"国家鼓励、引导公众聚集场所和生产、储存、运输、销售易燃易爆危险品的企业投保火灾公众责任保险；鼓励保险公司承保火灾公众责任保险。"},{"i":34,"n":"第三十四条","txt":"消防设施维护保养检测、消防安全评估等消防技术服务机构应当符合从业条件，执业人员应当依法获得相应的资格；依照法律、行政法规、国家标准、行业标准和执业准则，接受委托提供消防技术服务，并对服务质量负责。"},{"i":35,"n":"第三十五条","txt":"各级人民政府应当加强消防组织建设，根据经济社会发展的需要，建立多种形式的消防组织，加强消防技术人才培养，增强火灾预防、扑救和应急救援的能力。"},{"i":36,"n":"第三十六条","txt":"县级以上地方人民政府应当按照国家规定建立国家综合性消防救援队、专职消防队，并按照国家标准配备消防装备，承担火灾扑救工作。"},{"i":37,"n":"第三十七条","txt":"国家综合性消防救援队、专职消防队按照国家规定承担重大灾害事故和其他以抢救人员生命为主的应急救援工作。"},{"i":38,"n":"第三十八条","txt":"国家综合性消防救援队、专职消防队应当充分发挥火灾扑救和应急救援专业力量的骨干作用；按照国家规定，组织实施专业技能训练，配备并维护保养装备器材，提高火灾扑救和应急救援的能力。"},{"i":39,"n":"第三十九条","txt":"下列单位应当建立单位专职消防队，承担本单位的火灾扑救工作："},{"i":40,"n":"第四十条","txt":"专职消防队的建立，应当符合国家有关规定，并报当地消防救援机构验收。"},{"i":41,"n":"第四十一条","txt":"机关、团体、企业、事业等单位以及村民委员会、居民委员会根据需要，建立志愿消防队等多种形式的消防组织，开展群众性自防自救工作。"},{"i":42,"n":"第四十二条","txt":"消防救援机构应当对专职消防队、志愿消防队等消防组织进行业务指导；根据扑救火灾的需要，可以调动指挥专职消防队参加火灾扑救工作。"},{"i":43,"n":"第四十三条","txt":"县级以上地方人民政府应当组织有关部门针对本行政区域内的火灾特点制定应急预案，建立应急反应和处置机制，为火灾扑救和应急救援工作提供人员、装备等保障。"},{"i":44,"n":"第四十四条","txt":"任何人发现火灾都应当立即报警。任何单位、个人都应当无偿为报警提供便利，不得阻拦报警。严禁谎报火警。"},{"i":45,"n":"第四十五条","txt":"消防救援机构统一组织和指挥火灾现场扑救，应当优先保障遇险人员的生命安全。"},{"i":46,"n":"第四十六条","txt":"国家综合性消防救援队、专职消防队参加火灾以外的其他重大灾害事故的应急救援工作，由县级以上人民政府统一领导。"},{"i":47,"n":"第四十七条","txt":"消防车、消防艇前往执行火灾扑救或者应急救援任务，在确保安全的前提下，不受行驶速度、行驶路线、行驶方向和指挥信号的限制，其他车辆、船舶以及行人应当让行，不得穿插超越；收费公路、桥梁免收车辆通行费。交通管理指挥人员应当保证消防车、消防艇迅速通行。"},{"i":48,"n":"第四十八条","txt":"消防车、消防艇以及消防器材、装备和设施，不得用于与消防和应急救援工作无关的事项。"},{"i":49,"n":"第四十九条","txt":"国家综合性消防救援队、专职消防队扑救火灾、应急救援，不得收取任何费用。"},{"i":50,"n":"第五十条","txt":"对因参加扑救火灾或者应急救援受伤、致残或者死亡的人员，按照国家有关规定给予医疗、抚恤。"},{"i":51,"n":"第五十一条","txt":"消防救援机构有权根据需要封闭火灾现场，负责调查火灾原因，统计火灾损失。"},{"i":52,"n":"第五十二条","txt":"地方各级人民政府应当落实消防工作责任制，对本级人民政府有关部门履行消防安全职责的情况进行监督检查。"},{"i":53,"n":"第五十三条","txt":"消防救援机构应当对机关、团体、企业、事业等单位遵守消防法律、法规的情况依法进行监督检查。公安派出所可以负责日常消防监督检查、开展消防宣传教育，具体办法由国务院公安部门规定。"},{"i":54,"n":"第五十四条","txt":"消防救援机构在消防监督检查中发现火灾隐患的，应当通知有关单位或者个人立即采取措施消除隐患；不及时消除隐患可能严重威胁公共安全的，消防救援机构应当依照规定对危险部位或者场所采取临时查封措施。"},{"i":55,"n":"第五十五条","txt":"消防救援机构在消防监督检查中发现城乡消防安全布局、公共消防设施不符合消防安全要求，或者发现本地区存在影响公共安全的重大火灾隐患的，应当由应急管理部门书面报告本级人民政府。"},{"i":56,"n":"第五十六条","txt":"住房和城乡建设主管部门、消防救援机构及其工作人员应当按照法定的职权和程序进行消防设计审查、消防验收、备案抽查和消防安全检查，做到公正、严格、文明、高效。"},{"i":57,"n":"第五十七条","txt":"住房和城乡建设主管部门、消防救援机构及其工作人员执行职务，应当自觉接受社会和公民的监督。"},{"i":58,"n":"第五十八条","txt":"违反本法规定，有下列行为之一的，由住房和城乡建设主管部门、消防救援机构按照各自职权责令停止施工、停止使用或者停产停业，并处三万元以上三十万元以下罚款："},{"i":59,"n":"第五十九条","txt":"违反本法规定，有下列行为之一的，由住房和城乡建设主管部门责令改正或者停止施工，并处一万元以上十万元以下罚款："},{"i":60,"n":"第六十条","txt":"单位违反本法规定，有下列行为之一的，责令改正，处五千元以上五万元以下罚款："},{"i":61,"n":"第六十一条","txt":"生产、储存、经营易燃易爆危险品的场所与居住场所设置在同一建筑物内，或者未与居住场所保持安全距离的，责令停产停业，并处五千元以上五万元以下罚款。"},{"i":62,"n":"第六十二条","txt":"有下列行为之一的，依照《中华人民共和国治安管理处罚法》的规定处罚："},{"i":63,"n":"第六十三条","txt":"违反本法规定，有下列行为之一的，处警告或者五百元以下罚款；情节严重的，处五日以下拘留："},{"i":64,"n":"第六十四条","txt":"违反本法规定，有下列行为之一，尚不构成犯罪的，处十日以上十五日以下拘留，可以并处五百元以下罚款；情节较轻的，处警告或者五百元以下罚款："},{"i":65,"n":"第六十五条","txt":"违反本法规定，生产、销售不合格的消防产品或者国家明令淘汰的消防产品的，由产品质量监督部门或者工商行政管理部门依照《中华人民共和国产品质量法》的规定从重处罚。"},{"i":66,"n":"第六十六条","txt":"电器产品、燃气用具的安装、使用及其线路、管路的设计、敷设、维护保养、检测不符合消防技术标准和管理规定的，责令限期改正；逾期不改正的，责令停止使用，可以并处一千元以上五千元以下罚款。"},{"i":67,"n":"第六十七条","txt":"机关、团体、企业、事业等单位违反本法第十六条、第十七条、第十八条、第二十一条第二款规定的，责令限期改正；逾期不改正的，对其直接负责的主管人员和其他直接责任人员依法给予处分或者给予警告处罚。"},{"i":68,"n":"第六十八条","txt":"人员密集场所发生火灾，该场所的现场工作人员不履行组织、引导在场人员疏散的义务，情节严重，尚不构成犯罪的，处五日以上十日以下拘留。"},{"i":69,"n":"第六十九条","txt":"消防设施维护保养检测、消防安全评估等消防技术服务机构，不具备从业条件从事消防技术服务活动或者出具虚假文件的，由消防救援机构责令改正，处五万元以上十万元以下罚款，并对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下罚款；不按照国家标准、行业标准开展消防技术服务活动的，责令改正，处五万元以下罚款，并对直接负责的主管人员和其它直接责任人员处一万元以下罚款；有违法所得的，并处没收违法所得；给他人造成损失的，依法承担赔偿责任；情节严重的，依法责令停止执业或者吊销相应资格；造成重大损失的，由相关部门吊销营业执照，并对有关责任人员采取终身市场禁入措施。"},{"i":70,"n":"第七十条","txt":"本法规定的行政处罚，除应当由公安机关依照《中华人民共和国治安管理处罚法》的有关规定决定的外，由住房和城乡建设主管部门、消防救援机构按照各自职权决定。"},{"i":71,"n":"第七十一条","txt":"住房和城乡建设主管部门、消防救援机构的工作人员滥用职权、玩忽职守、徇私舞弊，有下列行为之一，尚不构成犯罪的，依法给予处分："},{"i":72,"n":"第七十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":73,"n":"第七十三条","txt":"本法下列用语的含义："},{"i":74,"n":"第七十四条","txt":"本法自2009年5月1日起施行。"}],"xianxiefa":[{"i":1,"n":"第一条","txt":"为保证医疗临床用血需要和安全，保障献血者和用血者身体健康，发扬人道主义精神，促进社会主义物质文明和精神文明建设，制定本法。"},{"i":2,"n":"第二条","txt":"国家实行无偿献血制度。"},{"i":3,"n":"第三条","txt":"地方各级人民政府领导本行政区域内的献血工作，统一规划并负责组织、协调有关部门共同做好献血工作。"},{"i":4,"n":"第四条","txt":"县级以上各级人民政府卫生行政部门监督管理献血工作。"},{"i":5,"n":"第五条","txt":"各级人民政府采取措施广泛宣传献血的意义，普及献血的科学知识，开展预防和控制经血液途径传播的疾病的教育。"},{"i":6,"n":"第六条","txt":"国家机关、军队、社会团体、企业事业组织、居民委员会、村民委员会，应当动员和组织本单位或者本居住区的适龄公民参加献血。"},{"i":7,"n":"第七条","txt":"国家鼓励国家工作人员、现役军人和高等学校在校学生率先献血，为树立社会新风尚作表率。"},{"i":8,"n":"第八条","txt":"血站是采集、提供临床用血的机构，是不以营利为目的的公益性组织。设立血站向公民采集血液，必须经国务院卫生行政部门或者省、自治区、直辖市人民政府卫生行政部门批准。血站应当为献血者提供各种安全、卫生、便利的条件。血站的设立条件和管理办法由国务院卫生行政部门制定。"},{"i":9,"n":"第九条","txt":"血站对献血者必须免费进行必要的健康检查；身体状况不符合献血条件的，血站应当向其说明情况，不得采集血液。献血者的身体健康条件由国务院卫生行政部门规定。"},{"i":10,"n":"第十条","txt":"血站采集血液必须严格遵守有关操作规程和制度，采血必须由具有采血资格的医务人员进行，一次性采血器材用后必须销毁，确保献血者的身体健康。"},{"i":11,"n":"第十一条","txt":"无偿献血的血液必须用于临床，不得买卖。血站、医疗机构不得将无偿献血的血液出售给单采血浆站或者血液制品生产单位。"},{"i":12,"n":"第十二条","txt":"临床用血的包装、储存、运输，必须符合国家规定的卫生标准和要求。"},{"i":13,"n":"第十三条","txt":"医疗机构对临床用血必须进行核查，不得将不符合国家规定标准的血液用于临床。"},{"i":14,"n":"第十四条","txt":"公民临床用血时只交付用于血液的采集、储存、分离、检验等费用；具体收费标准由国务院卫生行政部门会同国务院价格主管部门制定。"},{"i":15,"n":"第十五条","txt":"为保障公民临床急救用血的需要，国家提倡并指导择期手术的患者自身储血，动员家庭、亲友、所在单位以及社会互助献血。"},{"i":16,"n":"第十六条","txt":"医疗机构临床用血应当制定用血计划，遵循合理、科学的原则，不得浪费和滥用血液。"},{"i":17,"n":"第十七条","txt":"各级人民政府和红十字会对积极参加献血和在献血工作中做出显著成绩的单位和个人，给予奖励。"},{"i":18,"n":"第十八条","txt":"有下列行为之一的，由县级以上地方人民政府卫生行政部门予以取缔，没收违法所得，可以并处十万元以下的罚款；构成犯罪的，依法追究刑事责任："},{"i":19,"n":"第十九条","txt":"血站违反有关操作规程和制度采集血液，由县级以上地方人民政府卫生行政部门责令改正；给献血者健康造成损害的，应当依法赔偿，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"临床用血的包装、储存、运输，不符合国家规定的卫生标准和要求的，由县级以上地方人民政府卫生行政部门责令改正，给予警告，可以并处一万元以下的罚款。"},{"i":21,"n":"第二十一条","txt":"血站违反本法的规定，向医疗机构提供不符合国家规定标准的血液的，由县级以上人民政府卫生行政部门责令改正；情节严重，造成经血液途径传播的疾病传播或者有传播严重危险的，限期整顿，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"医疗机构的医务人员违反本法规定，将不符合国家规定标准的血液用于患者的，由县级以上地方人民政府卫生行政部门责令改正；给患者健康造成损害的，应当依法赔偿，对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"卫生行政部门及其工作人员在献血、用血的监督管理工作中，玩忽职守，造成严重后果，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":24,"n":"第二十四条","txt":"本法自1998年10月1日起施行。"}],"xianyijunguanfa":[{"i":1,"n":"第一条","txt":"为了建设一支革命化、年轻化、知识化、专业化的现役军官队伍，以利于人民解放军完成国家赋予的任务，制定本法。"},{"i":2,"n":"第二条","txt":"人民解放军现役军官（以下简称军官）是被任命为排级以上职务或者初级以上专业技术职务，并被授予相应军衔的现役军人。"},{"i":3,"n":"第三条","txt":"军官是国家工作人员的组成部分。"},{"i":4,"n":"第四条","txt":"军官的选拔和使用，坚持任人唯贤、德才兼备、注重实绩、适时交流的原则，实行民主监督，尊重群众公论。"},{"i":5,"n":"第五条","txt":"国家按照优待现役军人的原则，确定军官的各种待遇。"},{"i":6,"n":"第六条","txt":"军官符合本法规定的退出现役条件的，应当退出现役。"},{"i":7,"n":"第七条","txt":"人民解放军总政治部主管全军的军官管理工作，团级以上单位的政治机关主管本单位的军官管理工作。"},{"i":8,"n":"第八条","txt":"军官必须具备下列基本条件："},{"i":9,"n":"第九条","txt":"军官的来源："},{"i":10,"n":"第十条","txt":"人民解放军实行经院校培训提拔军官的制度。"},{"i":11,"n":"第十一条","txt":"各级首长和政治机关应当按照分工对所属军官进行考核。"},{"i":12,"n":"第十二条","txt":"军官职务的任免权限："},{"i":13,"n":"第十三条","txt":"在执行作战、抢险救灾等紧急任务时，上级首长有权暂时免去违抗命令、不履行职责或者不称职的所属军官的职务，并可以临时指派其他军人代理；因其他原因，军官职务出现空缺时，上级首长也可以临时指派军人代理。"},{"i":14,"n":"第十四条","txt":"作战部队的军事、政治、后勤、装备军官平时任职的最高年龄分别为："},{"i":15,"n":"第十五条","txt":"作战部队以外单位的副团职以下军官和大军区级职务军官，任职的最高年龄依照本法第十四条第一款的相应规定执行；正团职军官，任职的最高年龄为五十岁；师级职务军官，任职的最高年龄为五十五岁；副军职和正军职军官，任职的最高年龄分别为五十八岁和六十岁。"},{"i":16,"n":"第十六条","txt":"专业技术军官平时任职的最高年龄分别为："},{"i":17,"n":"第十七条","txt":"担任排、连、营、团、师（旅）、军级主官职务的军官，平时任职的最低年限分别为三年。"},{"i":18,"n":"第十八条","txt":"机关和院校的股长、科长、处长、局长、部长及相当领导职务的军官，任职的最低年限参照本法第十七条的规定执行。"},{"i":19,"n":"第十九条","txt":"专业技术军官平时任职的最低年限，按照中央军事委员会的有关规定执行。"},{"i":20,"n":"第二十条","txt":"军官任职满最低年限后，才能根据编制缺额和本人德才条件逐职晋升。"},{"i":21,"n":"第二十一条","txt":"军官晋升职务，应当具备拟任职务所要求的任职经历、文化程度、院校培训等资格。具体条件由中央军事委员会规定。"},{"i":22,"n":"第二十二条","txt":"军官职务应当按照编制员额和编制职务等级任命。"},{"i":23,"n":"第二十三条","txt":"军官经考核不称职的，应当调任下级职务或者改做其他工作，并按照新任职务确定待遇。"},{"i":24,"n":"第二十四条","txt":"担任师、军、大军区级职务的军官，正职和副职平时任职的最高年限分别为十年。任职满最高年限的，应当免去现任职务。"},{"i":25,"n":"第二十五条","txt":"根据国防建设的需要，军队可以向非军事部门派遣军官，执行军队交付的任务。"},{"i":26,"n":"第二十六条","txt":"军官可以按照中央军事委员会的规定改任文职干部。"},{"i":27,"n":"第二十七条","txt":"军官应当在不同岗位或者不同单位之间进行交流，具体办法由中央军事委员会根据本法规定。"},{"i":28,"n":"第二十八条","txt":"军官在一个岗位任职满下列年限的，应当交流："},{"i":29,"n":"第二十九条","txt":"在艰苦地区工作的军官向其他地区交流，按照中央军事委员会的有关规定执行。"},{"i":30,"n":"第三十条","txt":"军官之间有夫妻关系、直系血亲关系、三代以内旁系血亲关系以及近姻亲关系的，不得担任有直接上下级或者间隔一级领导关系的职务，不得在同一单位担任双方直接隶属于同一首长的职务，也不得在担任领导职务一方的机关任职。"},{"i":31,"n":"第三十一条","txt":"军官不得在其原籍所在地的军分区（师级警备区）和县、市、市辖区的人民武装部担任主官职务，但是工作特别需要的除外。"},{"i":32,"n":"第三十二条","txt":"军官在执行职务时，涉及本人或者涉及与本人有本法第三十条所列亲属关系人员的利益关系的，应当回避，但是执行作战任务和其他紧急任务的除外。"},{"i":33,"n":"第三十三条","txt":"军官在作战和军队建设中做出突出贡献或者取得显著成绩，以及为国家和人民做出其他较大贡献的，按照中央军事委员会的规定给予奖励。"},{"i":34,"n":"第三十四条","txt":"军官违反军纪的，按照中央军事委员会的规定给予处分。"},{"i":35,"n":"第三十五条","txt":"对被撤职的军官，根据其所犯错误的具体情况，任命新的职务；未任命新的职务的，应当确定职务等级待遇。"},{"i":36,"n":"第三十六条","txt":"军官违反法律，构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"军官实行职务军衔等级工资制和定期增资制度，按照国家和军队的有关规定享受津贴和补贴，并随着国民经济的发展适时调整。具体标准和办法由中央军事委员会规定。"},{"i":38,"n":"第三十八条","txt":"军官享受公费医疗待遇。有关部门应当做好军官的医疗保健工作，妥善安排军官的治病和疗养。"},{"i":39,"n":"第三十九条","txt":"军官住房实行公寓住房与自有住房相结合的保障制度。军官按照规定住用公寓住房或者购买自有住房，享受相应的住房补贴和优惠待遇。"},{"i":40,"n":"第四十条","txt":"军官享受休假待遇。上级首长应当每年按照规定安排军官休假。"},{"i":41,"n":"第四十一条","txt":"军官的家属随军、就业、工作调动和子女教育，享受国家和社会优待。"},{"i":42,"n":"第四十二条","txt":"军官牺牲、病故后，其随军家属移交政府安置管理。具体办法由国务院和中央军事委员会规定。"},{"i":43,"n":"第四十三条","txt":"军事、政治、后勤、装备军官平时服现役的最低年限分别为："},{"i":44,"n":"第四十四条","txt":"专业技术军官平时服现役的最低年限分别为："},{"i":45,"n":"第四十五条","txt":"军官未达到平时服现役的最低年限的，不得退出现役。但是有下列情形之一的，应当提前退出现役："},{"i":46,"n":"第四十六条","txt":"军官达到平时服现役的最高年龄的，应当退出现役。"},{"i":47,"n":"第四十七条","txt":"军官未达到平时服现役的最高年龄，有下列情形之一的，应当退出现役："},{"i":48,"n":"第四十八条","txt":"军官退出现役的批准权限与军官职务的任免权限相同。"},{"i":49,"n":"第四十九条","txt":"军官退出现役后，采取转业由政府安排工作和职务，或者由政府协助就业、发给退役金的方式安置；有的也可以采取复员或者退休的方式安置。"},{"i":50,"n":"第五十条","txt":"军官达到服现役的最高年龄，符合国家规定的离休条件的，可以离职休养。因工作需要或者其他原因，经过批准，可以提前或者推迟离休。"},{"i":51,"n":"第五十一条","txt":"军官退出现役后的安置管理具体办法由国务院和中央军事委员会规定。"},{"i":52,"n":"第五十二条","txt":"人民解放军总政治部根据本法制定实施办法，报国务院和中央军事委员会批准后施行。"},{"i":53,"n":"第五十三条","txt":"中国人民武装警察部队现役警官适用本法，具体办法由国务院和中央军事委员会规定。"},{"i":54,"n":"第五十四条","txt":"本法（原称《中国人民解放军现役军官服役条例》）自1989年1月1日起施行。1978年8月18日第五届全国人民代表大会常务委员会批准、1978年8月19日国务院和中央军事委员会颁布的《中国人民解放军干部服役条例》同时废止。"}],"dianyingchanyecujinfa":[{"i":1,"n":"第一条","txt":"为了促进电影产业健康繁荣发展，弘扬社会主义核心价值观，规范电影市场秩序，丰富人民群众精神文化生活，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事电影创作、摄制、发行、放映等活动（以下统称电影活动），适用本法。"},{"i":3,"n":"第三条","txt":"从事电影活动，应当坚持为人民服务、为社会主义服务，坚持社会效益优先，实现社会效益与经济效益相统一。"},{"i":4,"n":"第四条","txt":"国家坚持以人民为中心的创作导向，坚持百花齐放、百家争鸣的方针，尊重和保障电影创作自由，倡导电影创作贴近实际、贴近生活、贴近群众，鼓励创作思想性、艺术性、观赏性相统一的优秀电影。"},{"i":5,"n":"第五条","txt":"国务院应当将电影产业发展纳入国民经济和社会发展规划。县级以上地方人民政府根据当地实际情况将电影产业发展纳入本级国民经济和社会发展规划。"},{"i":6,"n":"第六条","txt":"国家鼓励电影科技的研发、应用，制定并完善电影技术标准，构建以企业为主体、市场为导向、产学研相结合的电影技术创新体系。"},{"i":7,"n":"第七条","txt":"与电影有关的知识产权受法律保护，任何组织和个人不得侵犯。"},{"i":8,"n":"第八条","txt":"国务院电影主管部门负责全国的电影工作；县级以上地方人民政府电影主管部门负责本行政区域内的电影工作。"},{"i":9,"n":"第九条","txt":"电影行业组织依法制定行业自律规范，开展业务交流，加强职业道德教育，维护其成员的合法权益。"},{"i":10,"n":"第十条","txt":"国家支持建立电影评价体系，鼓励开展电影评论。"},{"i":11,"n":"第十一条","txt":"国家鼓励开展平等、互利的电影国际合作与交流，支持参加境外电影节（展）。"},{"i":12,"n":"第十二条","txt":"国家鼓励电影剧本创作和题材、体裁、形式、手段等创新，鼓励电影学术研讨和业务交流。"},{"i":13,"n":"第十三条","txt":"拟摄制电影的法人、其他组织应当将电影剧本梗概向国务院电影主管部门或者省、自治区、直辖市人民政府电影主管部门备案；其中，涉及重大题材或者国家安全、外交、民族、宗教、军事等方面题材的，应当按照国家有关规定将电影剧本报送审查。"},{"i":14,"n":"第十四条","txt":"法人、其他组织经国务院电影主管部门批准，可以与境外组织合作摄制电影；但是，不得与从事损害我国国家尊严、荣誉和利益，危害社会稳定，伤害民族感情等活动的境外组织合作，也不得聘用有上述行为的个人参加电影摄制。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府电影主管部门应当协调公安、文物保护、风景名胜区管理等部门，为法人、其他组织依照本法从事电影摄制活动提供必要的便利和帮助。"},{"i":16,"n":"第十六条","txt":"电影不得含有下列内容："},{"i":17,"n":"第十七条","txt":"法人、其他组织应当将其摄制完成的电影送国务院电影主管部门或者省、自治区、直辖市人民政府电影主管部门审查。"},{"i":18,"n":"第十八条","txt":"进行电影审查应当组织不少于五名专家进行评审，由专家提出评审意见。法人、其他组织对专家评审意见有异议的，国务院电影主管部门或者省、自治区、直辖市人民政府电影主管部门可以另行组织专家再次评审。专家的评审意见应当作为作出审查决定的重要依据。"},{"i":19,"n":"第十九条","txt":"取得电影公映许可证的电影需要变更内容的，应当依照本法规定重新报送审查。"},{"i":20,"n":"第二十条","txt":"摄制电影的法人、其他组织应当将取得的电影公映许可证标识置于电影的片头处；电影放映可能引起未成年人等观众身体或者心理不适的，应当予以提示。"},{"i":21,"n":"第二十一条","txt":"摄制完成的电影取得电影公映许可证，方可参加电影节（展）。拟参加境外电影节（展）的，送展法人、其他组织应当在该境外电影节（展）举办前，将相关材料报国务院电影主管部门或者省、自治区、直辖市人民政府电影主管部门备案。"},{"i":22,"n":"第二十二条","txt":"公民、法人和其他组织可以承接境外电影的洗印、加工、后期制作等业务，并报省、自治区、直辖市人民政府电影主管部门备案，但是不得承接含有损害我国国家尊严、荣誉和利益，危害社会稳定，伤害民族感情等内容的境外电影的相关业务。"},{"i":23,"n":"第二十三条","txt":"国家设立的电影档案机构依法接收、收集、整理、保管并向社会开放电影档案。"},{"i":24,"n":"第二十四条","txt":"企业具有与所从事的电影发行活动相适应的人员、资金条件的，经国务院电影主管部门或者所在地省、自治区、直辖市人民政府电影主管部门批准，可以从事电影发行活动。"},{"i":25,"n":"第二十五条","txt":"依照本法规定负责电影发行、放映活动审批的电影主管部门，应当自受理申请之日起三十日内，作出批准或者不批准的决定。对符合条件的，予以批准，颁发电影发行经营许可证或者电影放映经营许可证，并予以公布；对不符合条件的，不予批准，书面通知申请人并说明理由。"},{"i":26,"n":"第二十六条","txt":"企业、个人从事电影流动放映活动，应当将企业名称或者经营者姓名、地址、联系方式、放映设备等向经营区域所在地县级人民政府电影主管部门备案。"},{"i":27,"n":"第二十七条","txt":"国家加大对农村电影放映的扶持力度，由政府出资建立完善农村电影公益放映服务网络，积极引导社会资金投资农村电影放映，不断改善农村地区观看电影条件，统筹保障农村地区群众观看电影需求。"},{"i":28,"n":"第二十八条","txt":"国务院教育、电影主管部门可以共同推荐有利于未成年人健康成长的电影，并采取措施支持接受义务教育的学生免费观看，由所在学校组织安排。"},{"i":29,"n":"第二十九条","txt":"电影院应当合理安排由境内法人、其他组织所摄制电影的放映场次和时段，并且放映的时长不得低于年放映电影时长总和的三分之二。"},{"i":30,"n":"第三十条","txt":"电影院的设施、设备以及用于流动放映的设备应当符合电影放映技术的国家标准。"},{"i":31,"n":"第三十一条","txt":"未经权利人许可，任何人不得对正在放映的电影进行录音录像。发现进行录音录像的，电影院工作人员有权予以制止，并要求其删除；对拒不听从的，有权要求其离场。"},{"i":32,"n":"第三十二条","txt":"国家鼓励电影院在向观众明示的电影开始放映时间之前放映公益广告。"},{"i":33,"n":"第三十三条","txt":"电影院应当遵守治安、消防、公共场所卫生等法律、行政法规，维护放映场所的公共秩序和环境卫生，保障观众的安全与健康。"},{"i":34,"n":"第三十四条","txt":"电影发行企业、电影院等应当如实统计电影销售收入，提供真实准确的统计数据，不得采取制造虚假交易、虚报瞒报销售收入等不正当手段，欺骗、误导观众，扰乱电影市场秩序。"},{"i":35,"n":"第三十五条","txt":"在境内举办涉外电影节（展），须经国务院电影主管部门或者省、自治区、直辖市人民政府电影主管部门批准。"},{"i":36,"n":"第三十六条","txt":"国家支持下列电影的创作、摄制："},{"i":37,"n":"第三十七条","txt":"国家引导相关文化产业专项资金、基金加大对电影产业的投入力度，根据不同阶段和时期电影产业的发展情况，结合财力状况和经济社会发展需要，综合考虑、统筹安排财政资金对电影产业的支持，并加强对相关资金、基金使用情况的审计。"},{"i":38,"n":"第三十八条","txt":"国家实施必要的税收优惠政策，促进电影产业发展，具体办法由国务院财税主管部门依照税收法律、行政法规的规定制定。"},{"i":39,"n":"第三十九条","txt":"县级以上地方人民政府应当依据人民群众需求和电影市场发展需要，将电影院建设和改造纳入国民经济和社会发展规划、土地利用总体规划和城乡规划等。"},{"i":40,"n":"第四十条","txt":"国家鼓励金融机构为从事电影活动以及改善电影基础设施提供融资服务，依法开展与电影有关的知识产权质押融资业务，并通过信贷等方式支持电影产业发展。"},{"i":41,"n":"第四十一条","txt":"国家鼓励法人、其他组织通过到境外合作摄制电影等方式进行跨境投资，依法保障其对外贸易、跨境融资和投资等合理用汇需求。"},{"i":42,"n":"第四十二条","txt":"国家实施电影人才扶持计划。"},{"i":43,"n":"第四十三条","txt":"国家采取措施，扶持农村地区、边疆地区、贫困地区和民族地区开展电影活动。"},{"i":44,"n":"第四十四条","txt":"国家对优秀电影的外语翻译制作予以支持，并综合利用外交、文化、教育等对外交流资源开展电影的境外推广活动。"},{"i":45,"n":"第四十五条","txt":"国家鼓励社会力量以捐赠、资助等方式支持电影产业发展，并依法给予优惠。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府电影主管部门应当加强对电影活动的日常监督管理，受理对违反本法规定的行为的投诉、举报，并及时核实、处理、答复；将从事电影活动的单位和个人因违反本法规定受到行政处罚的情形记入信用档案，并向社会公布。"},{"i":47,"n":"第四十七条","txt":"违反本法规定擅自从事电影摄制、发行、放映活动的，由县级以上人民政府电影主管部门予以取缔，没收电影片和违法所得以及从事违法活动的专用工具、设备；违法所得五万元以上的，并处违法所得五倍以上十倍以下的罚款；没有违法所得或者违法所得不足五万元的，可以并处二十五万元以下的罚款。"},{"i":48,"n":"第四十八条","txt":"有下列情形之一的，由原发证机关吊销有关许可证、撤销有关批准或者证明文件；县级以上人民政府电影主管部门没收违法所得；违法所得五万元以上的，并处违法所得五倍以上十倍以下的罚款；没有违法所得或者违法所得不足五万元的，可以并处二十五万元以下的罚款："},{"i":49,"n":"第四十九条","txt":"有下列情形之一的，由原发证机关吊销许可证；县级以上人民政府电影主管部门没收电影片和违法所得；违法所得五万元以上的，并处违法所得十倍以上二十倍以下的罚款；没有违法所得或者违法所得不足五万元的，可以并处五十万元以下的罚款："},{"i":50,"n":"第五十条","txt":"承接含有损害我国国家尊严、荣誉和利益，危害社会稳定，伤害民族感情等内容的境外电影的洗印、加工、后期制作等业务的，由县级以上人民政府电影主管部门责令停止违法活动，没收电影片和违法所得；违法所得五万元以上的，并处违法所得三倍以上五倍以下的罚款；没有违法所得或者违法所得不足五万元的，可以并处十五万元以下的罚款。情节严重的，由电影主管部门通报工商行政管理部门，由工商行政管理部门吊销营业执照。"},{"i":51,"n":"第五十一条","txt":"电影发行企业、电影院等有制造虚假交易、虚报瞒报销售收入等行为，扰乱电影市场秩序的，由县级以上人民政府电影主管部门责令改正，没收违法所得，处五万元以上五十万元以下的罚款；违法所得五十万元以上的，处违法所得一倍以上五倍以下的罚款。情节严重的，责令停业整顿；情节特别严重的，由原发证机关吊销许可证。"},{"i":52,"n":"第五十二条","txt":"法人或者其他组织未经许可擅自在境内举办涉外电影节（展）的，由国务院电影主管部门或者省、自治区、直辖市人民政府电影主管部门责令停止违法活动，没收参展的电影片和违法所得；违法所得五万元以上的，并处违法所得五倍以上十倍以下的罚款；没有违法所得或者违法所得不足五万元的，可以并处二十五万元以下的罚款；情节严重的，自受到处罚之日起五年内不得举办涉外电影节（展）。"},{"i":53,"n":"第五十三条","txt":"法人、其他组织或者个体工商户因违反本法规定被吊销许可证的，自吊销许可证之日起五年内不得从事该项业务活动；其法定代表人或者主要负责人自吊销许可证之日起五年内不得担任从事电影活动的法人、其他组织的法定代表人或者主要负责人。"},{"i":54,"n":"第五十四条","txt":"有下列情形之一的，依照有关法律、行政法规及国家有关规定予以处罚："},{"i":55,"n":"第五十五条","txt":"县级以上人民政府电影主管部门或者其他有关部门的工作人员有下列情形之一，尚不构成犯罪的，依法给予处分："},{"i":56,"n":"第五十六条","txt":"违反本法规定，造成人身、财产损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府电影主管部门及其工作人员应当严格依照本法规定的处罚种类和幅度，根据违法行为的性质和具体情节行使行政处罚权，具体办法由国务院电影主管部门制定。"},{"i":58,"n":"第五十八条","txt":"当事人对县级以上人民政府电影主管部门以及其他有关部门依照本法作出的行政行为不服的，可以依法申请行政复议或者提起行政诉讼。其中，对国务院电影主管部门作出的不准予电影公映的决定不服的，应当先依法申请行政复议，对行政复议决定不服的可以提起行政诉讼。"},{"i":59,"n":"第五十九条","txt":"境外资本在中华人民共和国境内设立从事电影活动的企业的，按照国家有关规定执行。"},{"i":60,"n":"第六十条","txt":"本法自2017年3月1日起施行。"}],"yimiaoguanlifa":[{"i":1,"n":"第一条","txt":"为了加强疫苗管理，保证疫苗质量和供应，规范预防接种，促进疫苗行业发展，保障公众健康，维护公共卫生安全，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事疫苗研制、生产、流通和预防接种及其监督管理活动，适用本法。本法未作规定的，适用《中华人民共和国药品管理法》、《中华人民共和国传染病防治法》等法律、行政法规的规定。"},{"i":3,"n":"第三条","txt":"国家对疫苗实行最严格的管理制度，坚持安全第一、风险管理、全程管控、科学监管、社会共治。"},{"i":4,"n":"第四条","txt":"国家坚持疫苗产品的战略性和公益性。"},{"i":5,"n":"第五条","txt":"疫苗上市许可持有人应当加强疫苗全生命周期质量管理，对疫苗的安全性、有效性和质量可控性负责。"},{"i":6,"n":"第六条","txt":"国家实行免疫规划制度。"},{"i":7,"n":"第七条","txt":"县级以上人民政府应当将疫苗安全工作和预防接种工作纳入本级国民经济和社会发展规划，加强疫苗监督管理能力建设，建立健全疫苗监督管理工作机制。"},{"i":8,"n":"第八条","txt":"国务院药品监督管理部门负责全国疫苗监督管理工作。国务院卫生健康主管部门负责全国预防接种监督管理工作。国务院其他有关部门在各自职责范围内负责与疫苗有关的监督管理工作。"},{"i":9,"n":"第九条","txt":"国务院和省、自治区、直辖市人民政府建立部门协调机制，统筹协调疫苗监督管理有关工作，定期分析疫苗安全形势，加强疫苗监督管理，保障疫苗供应。"},{"i":10,"n":"第十条","txt":"国家实行疫苗全程电子追溯制度。"},{"i":11,"n":"第十一条","txt":"疫苗研制、生产、检验等过程中应当建立健全生物安全管理制度，严格控制生物安全风险，加强菌毒株等病原微生物的生物安全管理，保护操作人员和公众的健康，保证菌毒株等病原微生物用途合法、正当。"},{"i":12,"n":"第十二条","txt":"各级人民政府及其有关部门、疾病预防控制机构、接种单位、疫苗上市许可持有人和疫苗行业协会等应当通过全国儿童预防接种日等活动定期开展疫苗安全法律、法规以及预防接种知识等的宣传教育、普及工作。"},{"i":13,"n":"第十三条","txt":"疫苗行业协会应当加强行业自律，建立健全行业规范，推动行业诚信体系建设，引导和督促会员依法开展生产经营等活动。"},{"i":14,"n":"第十四条","txt":"国家根据疾病流行情况、人群免疫状况等因素，制定相关研制规划，安排必要资金，支持多联多价等新型疫苗的研制。"},{"i":15,"n":"第十五条","txt":"国家鼓励疫苗上市许可持有人加大研制和创新资金投入，优化生产工艺，提升质量控制水平，推动疫苗技术进步。"},{"i":16,"n":"第十六条","txt":"开展疫苗临床试验，应当经国务院药品监督管理部门依法批准。"},{"i":17,"n":"第十七条","txt":"疫苗临床试验申办者应当制定临床试验方案，建立临床试验安全监测与评价制度，审慎选择受试者，合理设置受试者群体和年龄组，并根据风险程度采取有效措施，保护受试者合法权益。"},{"i":18,"n":"第十八条","txt":"开展疫苗临床试验，应当取得受试者的书面知情同意；受试者为无民事行为能力人的，应当取得其监护人的书面知情同意；受试者为限制民事行为能力人的，应当取得本人及其监护人的书面知情同意。"},{"i":19,"n":"第十九条","txt":"在中国境内上市的疫苗应当经国务院药品监督管理部门批准，取得药品注册证书；申请疫苗注册，应当提供真实、充分、可靠的数据、资料和样品。"},{"i":20,"n":"第二十条","txt":"应对重大突发公共卫生事件急需的疫苗或者国务院卫生健康主管部门认定急需的其他疫苗，经评估获益大于风险的，国务院药品监督管理部门可以附条件批准疫苗注册申请。"},{"i":21,"n":"第二十一条","txt":"国务院药品监督管理部门在批准疫苗注册申请时，对疫苗的生产工艺、质量控制标准和说明书、标签予以核准。"},{"i":22,"n":"第二十二条","txt":"国家对疫苗生产实行严格准入制度。"},{"i":23,"n":"第二十三条","txt":"疫苗上市许可持有人的法定代表人、主要负责人应当具有良好的信用记录，生产管理负责人、质量管理负责人、质量受权人等关键岗位人员应当具有相关专业背景和从业经历。"},{"i":24,"n":"第二十四条","txt":"疫苗应当按照经核准的生产工艺和质量控制标准进行生产和检验，生产全过程应当符合药品生产质量管理规范的要求。"},{"i":25,"n":"第二十五条","txt":"疫苗上市许可持有人应当建立完整的生产质量管理体系，持续加强偏差管理，采用信息化手段如实记录生产、检验过程中形成的所有数据，确保生产全过程持续符合法定要求。"},{"i":26,"n":"第二十六条","txt":"国家实行疫苗批签发制度。"},{"i":27,"n":"第二十七条","txt":"申请疫苗批签发应当按照规定向批签发机构提供批生产及检验记录摘要等资料和同批号产品等样品。进口疫苗还应当提供原产地证明、批签发证明；在原产地免予批签发的，应当提供免予批签发证明。"},{"i":28,"n":"第二十八条","txt":"预防、控制传染病疫情或者应对突发事件急需的疫苗，经国务院药品监督管理部门批准，免予批签发。"},{"i":29,"n":"第二十九条","txt":"疫苗批签发应当逐批进行资料审核和抽样检验。疫苗批签发检验项目和检验频次应当根据疫苗质量风险评估情况进行动态调整。"},{"i":30,"n":"第三十条","txt":"批签发机构在批签发过程中发现疫苗存在重大质量风险的，应当及时向国务院药品监督管理部门和省、自治区、直辖市人民政府药品监督管理部门报告。"},{"i":31,"n":"第三十一条","txt":"对生产工艺偏差、质量差异、生产过程中的故障和事故以及采取的措施，疫苗上市许可持有人应当如实记录，并在相应批产品申请批签发的文件中载明；可能影响疫苗质量的，疫苗上市许可持有人应当立即采取措施，并向省、自治区、直辖市人民政府药品监督管理部门报告。"},{"i":32,"n":"第三十二条","txt":"国家免疫规划疫苗由国务院卫生健康主管部门会同国务院财政部门等组织集中招标或者统一谈判，形成并公布中标价格或者成交价格，各省、自治区、直辖市实行统一采购。"},{"i":33,"n":"第三十三条","txt":"疫苗的价格由疫苗上市许可持有人依法自主合理制定。疫苗的价格水平、差价率、利润率应当保持在合理幅度。"},{"i":34,"n":"第三十四条","txt":"省级疾病预防控制机构应当根据国家免疫规划和本行政区域疾病预防、控制需要，制定本行政区域免疫规划疫苗使用计划，并按照国家有关规定向组织采购疫苗的部门报告，同时报省、自治区、直辖市人民政府卫生健康主管部门备案。"},{"i":35,"n":"第三十五条","txt":"疫苗上市许可持有人应当按照采购合同约定，向疾病预防控制机构供应疫苗。"},{"i":36,"n":"第三十六条","txt":"疫苗上市许可持有人应当按照采购合同约定，向疾病预防控制机构或者疾病预防控制机构指定的接种单位配送疫苗。"},{"i":37,"n":"第三十七条","txt":"疾病预防控制机构、接种单位、疫苗上市许可持有人、疫苗配送单位应当遵守疫苗储存、运输管理规范，保证疫苗质量。"},{"i":38,"n":"第三十八条","txt":"疫苗上市许可持有人在销售疫苗时，应当提供加盖其印章的批签发证明复印件或者电子文件；销售进口疫苗的，还应当提供加盖其印章的进口药品通关单复印件或者电子文件。"},{"i":39,"n":"第三十九条","txt":"疫苗上市许可持有人应当按照规定，建立真实、准确、完整的销售记录，并保存至疫苗有效期满后不少于五年备查。"},{"i":40,"n":"第四十条","txt":"疾病预防控制机构、接种单位应当建立疫苗定期检查制度，对存在包装无法识别、储存温度不符合要求、超过有效期等问题的疫苗，采取隔离存放、设置警示标志等措施，并按照国务院药品监督管理部门、卫生健康主管部门、生态环境主管部门的规定处置。疾病预防控制机构、接种单位应当如实记录处置情况，处置记录应当保存至疫苗有效期满后不少于五年备查。"},{"i":41,"n":"第四十一条","txt":"国务院卫生健康主管部门制定国家免疫规划；国家免疫规划疫苗种类由国务院卫生健康主管部门会同国务院财政部门拟订，报国务院批准后公布。"},{"i":42,"n":"第四十二条","txt":"国务院卫生健康主管部门应当制定、公布预防接种工作规范，强化预防接种规范化管理。"},{"i":43,"n":"第四十三条","txt":"各级疾病预防控制机构应当按照各自职责，开展与预防接种相关的宣传、培训、技术指导、监测、评价、流行病学调查、应急处置等工作。"},{"i":44,"n":"第四十四条","txt":"接种单位应当具备下列条件："},{"i":45,"n":"第四十五条","txt":"医疗卫生人员实施接种，应当告知受种者或者其监护人所接种疫苗的品种、作用、禁忌、不良反应以及现场留观等注意事项，询问受种者的健康状况以及是否有接种禁忌等情况，并如实记录告知和询问情况。受种者或者其监护人应当如实提供受种者的健康状况和接种禁忌等情况。有接种禁忌不能接种的，医疗卫生人员应当向受种者或者其监护人提出医学建议，并如实记录提出医学建议情况。"},{"i":46,"n":"第四十六条","txt":"医疗卫生人员应当按照国务院卫生健康主管部门的规定，真实、准确、完整记录疫苗的品种、上市许可持有人、最小包装单位的识别信息、有效期、接种时间、实施接种的医疗卫生人员、受种者等接种信息，确保接种信息可追溯、可查询。接种记录应当保存至疫苗有效期满后不少于五年备查。"},{"i":47,"n":"第四十七条","txt":"国家对儿童实行预防接种证制度。在儿童出生后一个月内，其监护人应当到儿童居住地承担预防接种工作的接种单位或者出生医院为其办理预防接种证。接种单位或者出生医院不得拒绝办理。监护人应当妥善保管预防接种证。"},{"i":48,"n":"第四十八条","txt":"儿童入托、入学时，托幼机构、学校应当查验预防接种证，发现未按照规定接种免疫规划疫苗的，应当向儿童居住地或者托幼机构、学校所在地承担预防接种工作的接种单位报告，并配合接种单位督促其监护人按照规定补种。疾病预防控制机构应当为托幼机构、学校查验预防接种证等提供技术指导。"},{"i":49,"n":"第四十九条","txt":"接种单位接种免疫规划疫苗不得收取任何费用。"},{"i":50,"n":"第五十条","txt":"县级以上地方人民政府卫生健康主管部门根据传染病监测和预警信息，为预防、控制传染病暴发、流行，报经本级人民政府决定，并报省级以上人民政府卫生健康主管部门备案，可以在本行政区域进行群体性预防接种。"},{"i":51,"n":"第五十一条","txt":"传染病暴发、流行时，县级以上地方人民政府或者其卫生健康主管部门需要采取应急接种措施的，依照法律、行政法规的规定执行。"},{"i":52,"n":"第五十二条","txt":"预防接种异常反应，是指合格的疫苗在实施规范接种过程中或者实施规范接种后造成受种者机体组织器官、功能损害，相关各方均无过错的药品不良反应。"},{"i":53,"n":"第五十三条","txt":"国家加强预防接种异常反应监测。预防接种异常反应监测方案由国务院卫生健康主管部门会同国务院药品监督管理部门制定。"},{"i":54,"n":"第五十四条","txt":"接种单位、医疗机构等发现疑似预防接种异常反应的，应当按照规定向疾病预防控制机构报告。"},{"i":55,"n":"第五十五条","txt":"对疑似预防接种异常反应，疾病预防控制机构应当按照规定及时报告，组织调查、诊断，并将调查、诊断结论告知受种者或者其监护人。对调查、诊断结论有争议的，可以根据国务院卫生健康主管部门制定的鉴定办法申请鉴定。"},{"i":56,"n":"第五十六条","txt":"国家实行预防接种异常反应补偿制度。实施接种过程中或者实施接种后出现受种者死亡、严重残疾、器官组织损伤等损害，属于预防接种异常反应或者不能排除的，应当给予补偿。补偿范围实行目录管理，并根据实际情况进行动态调整。"},{"i":57,"n":"第五十七条","txt":"疫苗上市许可持有人应当建立健全疫苗全生命周期质量管理体系，制定并实施疫苗上市后风险管理计划，开展疫苗上市后研究，对疫苗的安全性、有效性和质量可控性进行进一步确证。"},{"i":58,"n":"第五十八条","txt":"疫苗上市许可持有人应当对疫苗进行质量跟踪分析，持续提升质量控制标准，改进生产工艺，提高生产工艺稳定性。"},{"i":59,"n":"第五十九条","txt":"疫苗上市许可持有人应当根据疫苗上市后研究、预防接种异常反应等情况持续更新说明书、标签，并按照规定申请核准或者备案。"},{"i":60,"n":"第六十条","txt":"疫苗上市许可持有人应当建立疫苗质量回顾分析和风险报告制度，每年将疫苗生产流通、上市后研究、风险管理等情况按照规定如实向国务院药品监督管理部门报告。"},{"i":61,"n":"第六十一条","txt":"国务院药品监督管理部门可以根据实际情况，责令疫苗上市许可持有人开展上市后评价或者直接组织开展上市后评价。"},{"i":62,"n":"第六十二条","txt":"国务院药品监督管理部门可以根据疾病预防、控制需要和疫苗行业发展情况，组织对疫苗品种开展上市后评价，发现该疫苗品种的产品设计、生产工艺、安全性、有效性或者质量可控性明显劣于预防、控制同种疾病的其他疫苗品种的，应当注销该品种所有疫苗的药品注册证书并废止相应的国家药品标准。"},{"i":63,"n":"第六十三条","txt":"县级以上人民政府应当将疫苗安全工作、购买免疫规划疫苗和预防接种工作以及信息化建设等所需经费纳入本级政府预算，保证免疫规划制度的实施。"},{"i":64,"n":"第六十四条","txt":"省、自治区、直辖市人民政府根据本行政区域传染病流行趋势，在国务院卫生健康主管部门确定的传染病预防、控制项目范围内，确定本行政区域与预防接种相关的项目，并保证项目的实施。"},{"i":65,"n":"第六十五条","txt":"国务院卫生健康主管部门根据各省、自治区、直辖市国家免疫规划疫苗使用计划，向疫苗上市许可持有人提供国家免疫规划疫苗需求信息，疫苗上市许可持有人根据疫苗需求信息合理安排生产。"},{"i":66,"n":"第六十六条","txt":"国家将疫苗纳入战略物资储备，实行中央和省级两级储备。"},{"i":67,"n":"第六十七条","txt":"各级财政安排用于预防接种的经费应当专款专用，任何单位和个人不得挪用、挤占。"},{"i":68,"n":"第六十八条","txt":"国家实行疫苗责任强制保险制度。"},{"i":69,"n":"第六十九条","txt":"传染病暴发、流行时，相关疫苗上市许可持有人应当及时生产和供应预防、控制传染病的疫苗。交通运输单位应当优先运输预防、控制传染病的疫苗。县级以上人民政府及其有关部门应当做好组织、协调、保障工作。"},{"i":70,"n":"第七十条","txt":"药品监督管理部门、卫生健康主管部门按照各自职责对疫苗研制、生产、流通和预防接种全过程进行监督管理，监督疫苗上市许可持有人、疾病预防控制机构、接种单位等依法履行义务。"},{"i":71,"n":"第七十一条","txt":"国家建设中央和省级两级职业化、专业化药品检查员队伍，加强对疫苗的监督检查。"},{"i":72,"n":"第七十二条","txt":"疫苗质量管理存在安全隐患，疫苗上市许可持有人等未及时采取措施消除的，药品监督管理部门可以采取责任约谈、限期整改等措施。"},{"i":73,"n":"第七十三条","txt":"疫苗存在或者疑似存在质量问题的，疫苗上市许可持有人、疾病预防控制机构、接种单位应当立即停止销售、配送、使用，必要时立即停止生产，按照规定向县级以上人民政府药品监督管理部门、卫生健康主管部门报告。卫生健康主管部门应当立即组织疾病预防控制机构和接种单位采取必要的应急处置措施，同时向上级人民政府卫生健康主管部门报告。药品监督管理部门应当依法采取查封、扣押等措施。对已经销售的疫苗，疫苗上市许可持有人应当及时通知相关疾病预防控制机构、疫苗配送单位、接种单位，按照规定召回，如实记录召回和通知情况，疾病预防控制机构、疫苗配送单位、接种单位应当予以配合。"},{"i":74,"n":"第七十四条","txt":"疫苗上市许可持有人应当建立信息公开制度，按照规定在其网站上及时公开疫苗产品信息、说明书和标签、药品相关质量管理规范执行情况、批签发情况、召回情况、接受检查和处罚情况以及投保疫苗责任强制保险情况等信息。"},{"i":75,"n":"第七十五条","txt":"国务院药品监督管理部门会同国务院卫生健康主管部门等建立疫苗质量、预防接种等信息共享机制。"},{"i":76,"n":"第七十六条","txt":"国家实行疫苗安全信息统一公布制度。"},{"i":77,"n":"第七十七条","txt":"任何单位和个人有权依法了解疫苗信息，对疫苗监督管理工作提出意见、建议。"},{"i":78,"n":"第七十八条","txt":"县级以上人民政府应当制定疫苗安全事件应急预案，对疫苗安全事件分级、处置组织指挥体系与职责、预防预警机制、处置程序、应急保障措施等作出规定。"},{"i":79,"n":"第七十九条","txt":"违反本法规定，构成犯罪的，依法从重追究刑事责任。"},{"i":80,"n":"第八十条","txt":"生产、销售的疫苗属于假药的，由省级以上人民政府药品监督管理部门没收违法所得和违法生产、销售的疫苗以及专门用于违法生产疫苗的原料、辅料、包装材料、设备等物品，责令停产停业整顿，吊销药品注册证书，直至吊销药品生产许可证等，并处违法生产、销售疫苗货值金额十五倍以上五十倍以下的罚款，货值金额不足五十万元的，按五十万元计算。"},{"i":81,"n":"第八十一条","txt":"有下列情形之一的，由省级以上人民政府药品监督管理部门没收违法所得和违法生产、销售的疫苗以及专门用于违法生产疫苗的原料、辅料、包装材料、设备等物品，责令停产停业整顿，并处违法生产、销售疫苗货值金额十五倍以上五十倍以下的罚款，货值金额不足五十万元的，按五十万元计算；情节严重的，吊销药品相关批准证明文件，直至吊销药品生产许可证等，对法定代表人、主要负责人、直接负责的主管人员和关键岗位人员以及其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入百分之五十以上十倍以下的罚款，十年内直至终身禁止从事药品生产经营活动，由公安机关处五日以上十五日以下拘留："},{"i":82,"n":"第八十二条","txt":"除本法另有规定的情形外，疫苗上市许可持有人或者其他单位违反药品相关质量管理规范的，由县级以上人民政府药品监督管理部门责令改正，给予警告；拒不改正的，处二十万元以上五十万元以下的罚款；情节严重的，处五十万元以上三百万元以下的罚款，责令停产停业整顿，直至吊销药品相关批准证明文件、药品生产许可证等，对法定代表人、主要负责人、直接负责的主管人员和关键岗位人员以及其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入百分之五十以上五倍以下的罚款，十年内直至终身禁止从事药品生产经营活动。"},{"i":83,"n":"第八十三条","txt":"违反本法规定，疫苗上市许可持有人有下列情形之一的，由省级以上人民政府药品监督管理部门责令改正，给予警告；拒不改正的，处二十万元以上五十万元以下的罚款；情节严重的，责令停产停业整顿，并处五十万元以上二百万元以下的罚款："},{"i":84,"n":"第八十四条","txt":"违反本法规定，批签发机构有下列情形之一的，由国务院药品监督管理部门责令改正，给予警告，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至降级处分："},{"i":85,"n":"第八十五条","txt":"疾病预防控制机构、接种单位、疫苗上市许可持有人、疫苗配送单位违反疫苗储存、运输管理规范有关冷链储存、运输要求的，由县级以上人民政府药品监督管理部门责令改正，给予警告，对违法储存、运输的疫苗予以销毁，没收违法所得；拒不改正的，对接种单位、疫苗上市许可持有人、疫苗配送单位处二十万元以上一百万元以下的罚款；情节严重的，对接种单位、疫苗上市许可持有人、疫苗配送单位处违法储存、运输疫苗货值金额十倍以上三十倍以下的罚款，货值金额不足十万元的，按十万元计算，责令疫苗上市许可持有人、疫苗配送单位停产停业整顿，直至吊销药品相关批准证明文件、药品生产许可证等，对疫苗上市许可持有人、疫苗配送单位的法定代表人、主要负责人、直接负责的主管人员和关键岗位人员以及其他责任人员依照本法第八十二条规定给予处罚。"},{"i":86,"n":"第八十六条","txt":"疾病预防控制机构、接种单位、疫苗上市许可持有人、疫苗配送单位有本法第八十五条规定以外的违反疫苗储存、运输管理规范行为的，由县级以上人民政府药品监督管理部门责令改正，给予警告，没收违法所得；拒不改正的，对接种单位、疫苗上市许可持有人、疫苗配送单位处十万元以上三十万元以下的罚款；情节严重的，对接种单位、疫苗上市许可持有人、疫苗配送单位处违法储存、运输疫苗货值金额三倍以上十倍以下的罚款，货值金额不足十万元的，按十万元计算。"},{"i":87,"n":"第八十七条","txt":"违反本法规定，疾病预防控制机构、接种单位有下列情形之一的，由县级以上人民政府卫生健康主管部门责令改正，给予警告，没收违法所得；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分，责令负有责任的医疗卫生人员暂停一年以上十八个月以下执业活动；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，由原发证部门吊销负有责任的医疗卫生人员的执业证书："},{"i":88,"n":"第八十八条","txt":"违反本法规定，疾病预防控制机构、接种单位有下列情形之一的，由县级以上人民政府卫生健康主管部门责令改正，给予警告；情节严重的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分，责令负有责任的医疗卫生人员暂停六个月以上一年以下执业活动；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，由原发证部门吊销负有责任的医疗卫生人员的执业证书："},{"i":89,"n":"第八十九条","txt":"疾病预防控制机构、接种单位、医疗机构未按照规定报告疑似预防接种异常反应、疫苗安全事件等，或者未按照规定对疑似预防接种异常反应组织调查、诊断等的，由县级以上人民政府卫生健康主管部门责令改正，给予警告；情节严重的，对接种单位、医疗机构处五万元以上五十万元以下的罚款，对疾病预防控制机构、接种单位、医疗机构的主要负责人、直接负责的主管人员和其他直接责任人员依法给予警告直至撤职处分；造成严重后果的，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予开除处分，由原发证部门吊销负有责任的医疗卫生人员的执业证书。"},{"i":90,"n":"第九十条","txt":"疾病预防控制机构、接种单位违反本法规定收取费用的，由县级以上人民政府卫生健康主管部门监督其将违法收取的费用退还给原缴费的单位或者个人，并由县级以上人民政府市场监督管理部门依法给予处罚。"},{"i":91,"n":"第九十一条","txt":"违反本法规定，未经县级以上地方人民政府卫生健康主管部门指定擅自从事免疫规划疫苗接种工作、从事非免疫规划疫苗接种工作不符合条件或者未备案的，由县级以上人民政府卫生健康主管部门责令改正，给予警告，没收违法所得和违法持有的疫苗，责令停业整顿，并处十万元以上一百万元以下的罚款，对主要负责人、直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":92,"n":"第九十二条","txt":"监护人未依法保证适龄儿童按时接种免疫规划疫苗的，由县级人民政府卫生健康主管部门批评教育，责令改正。"},{"i":93,"n":"第九十三条","txt":"编造、散布虚假疫苗安全信息，或者在接种单位寻衅滋事，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":94,"n":"第九十四条","txt":"县级以上地方人民政府在疫苗监督管理工作中有下列情形之一的，对直接负责的主管人员和其他直接责任人员依法给予降级或者撤职处分；情节严重的，依法给予开除处分；造成严重后果的，其主要负责人应当引咎辞职："},{"i":95,"n":"第九十五条","txt":"药品监督管理部门、卫生健康主管部门等部门在疫苗监督管理工作中有下列情形之一的，对直接负责的主管人员和其他直接责任人员依法给予降级或者撤职处分；情节严重的，依法给予开除处分；造成严重后果的，其主要负责人应当引咎辞职："},{"i":96,"n":"第九十六条","txt":"因疫苗质量问题造成受种者损害的，疫苗上市许可持有人应当依法承担赔偿责任。"},{"i":97,"n":"第九十七条","txt":"本法下列用语的含义是："},{"i":98,"n":"第九十八条","txt":"国家鼓励疫苗生产企业按照国际采购要求生产、出口疫苗。"},{"i":99,"n":"第九十九条","txt":"出入境预防接种及所需疫苗的采购，由国境卫生检疫机关商国务院财政部门另行规定。"},{"i":100,"n":"第一百条","txt":"本法自2019年12月1日起施行。"}],"jianyufa-2":[{"i":1,"n":"第一条","txt":"为了规范和保障监狱正确执行刑罚，依法惩罚和改造罪犯，预防和减少犯罪，促进更高水平的平安中国和法治中国建设，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"监狱是国家的刑罚执行机关。"},{"i":3,"n":"第三条","txt":"监狱工作坚持中国共产党的领导，坚持总体国家安全观，建立公正、法治、文明、廉洁、高效的监狱刑罚执行体制。"},{"i":4,"n":"第四条","txt":"监狱工作应当坚持惩罚和改造相结合、教育和劳动相结合，以改造人为宗旨，坚持依法管理，尊重和保障人权，将罪犯改造成为守法公民，促进其重新融入社会。"},{"i":5,"n":"第五条","txt":"国务院司法行政部门主管全国的监狱工作。"},{"i":6,"n":"第六条","txt":"人民检察院对监狱执行刑罚的活动，依法实行监督。"},{"i":7,"n":"第七条","txt":"国家保障监狱的建设和运行，监狱经费按照规定列入预算。"},{"i":8,"n":"第八条","txt":"监狱实行狱务公开，依法及时准确公开执行刑罚的法律依据、程序、结果，主动接受监督。涉及国家秘密、个人隐私的信息，以及公开后可能危及国家安全、社会稳定和监狱秩序的信息，不予公开。"},{"i":9,"n":"第九条","txt":"国家鼓励、支持监狱和刑罚执行的理论研究和人才培养，为监狱工作高质量发展提供理论支撑、人才保障。"},{"i":10,"n":"第十条","txt":"对在监狱工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":11,"n":"第十一条","txt":"监狱的设置、撤销、迁移，由国务院司法行政部门批准。"},{"i":12,"n":"第十二条","txt":"监狱建设应当根据改造罪犯工作的需要，按照国家有关规定，坚持统筹规划、合理布局，做到功能完善、规模适度。"},{"i":13,"n":"第十三条","txt":"监狱依法使用的土地、矿产资源和其他自然资源以及监狱的财产，受法律保护，任何组织或者个人不得侵占、破坏。"},{"i":14,"n":"第十四条","txt":"监狱应当加强信息化建设，运用现代科学技术，提高监狱管理水平和罪犯改造工作质量。"},{"i":15,"n":"第十五条","txt":"监狱的外围武装警戒由人民武装警察部队负责，具体任务范围依照国家有关规定执行。"},{"i":16,"n":"第十六条","txt":"监狱根据监管需要，设立警戒设施。监狱周围设警戒隔离带，未经准许，任何人不得进入。"},{"i":17,"n":"第十七条","txt":"监狱周围的国家机关、社会团体、企业事业单位和基层组织，应当协助监狱做好安全警戒工作。"},{"i":18,"n":"第十八条","txt":"监狱安全纳入所在地人民政府安全工作体系。监狱、人民武装警察部队、公安机关、卫生健康、疾病预防控制和应急管理等有关单位在监狱反恐防暴、押解罪犯、疾病防治、防灾减灾救灾等工作中，应当分工负责、协同处置。"},{"i":19,"n":"第十九条","txt":"监狱设监狱长、政治委员各一人，副监狱长若干人，并根据实际需要设置必要的工作机构，配备其他监狱管理人员。"},{"i":20,"n":"第二十条","txt":"监狱人民警察应当对党忠诚、服务人民、执法公正、纪律严明，严格遵守宪法和法律。"},{"i":21,"n":"第二十一条","txt":"国家推进高素质监狱人民警察队伍建设。对监狱人民警察应当有计划地进行培训。有关部门应当加强对监狱人民警察的管理、监督、培训和职业保障。"},{"i":22,"n":"第二十二条","txt":"监狱人民警察依法履行下列职责："},{"i":23,"n":"第二十三条","txt":"监狱人民警察不得有下列行为："},{"i":24,"n":"第二十四条","txt":"司法行政部门建立警务督察制度，对监狱人民警察执行法律、法规和遵守纪律的情况进行监督。"},{"i":25,"n":"第二十五条","txt":"监狱及其上级机关对监狱人民警察依法履行职责的行为予以维护。"},{"i":26,"n":"第二十六条","txt":"监狱应当保障罪犯在服刑期间依法享有的权利不受侵犯。"},{"i":27,"n":"第二十七条","txt":"监狱依法保障罪犯的生命健康，发现罪犯患病的，应当按照规定给予治疗。"},{"i":28,"n":"第二十八条","txt":"罪犯必须严格遵守法律、法规和监规纪律，服从管理，接受教育。"},{"i":29,"n":"第二十九条","txt":"罪犯收监后，监狱应当告知其依法享有的权利和必须履行的义务。"},{"i":30,"n":"第三十条","txt":"罪犯依法提出法律援助申请的，监狱应当按照规定将申请及时转交法律援助机构。"},{"i":31,"n":"第三十一条","txt":"监狱依据人民法院的生效判决、裁定、决定对罪犯执行刑罚。"},{"i":32,"n":"第三十二条","txt":"罪犯被交付执行刑罚时，公安机关应当将下列法律文书同时送达监狱："},{"i":33,"n":"第三十三条","txt":"罪犯收监时，监狱应当严格对其人身和所携带的物品进行检查。违禁品依法予以没收；其他物品征得罪犯同意后转交其近亲属或者监护人，罪犯不同意转交或者无法转交的由监狱代为保管。"},{"i":34,"n":"第三十四条","txt":"罪犯收监后，监狱应当对其进行身体检查，发现身体有伤残或者严重疾病的，应当询问情况，做好记录。经检查，对于具有暂予监外执行情形的，监狱可以提出书面建议，报省、自治区、直辖市监狱管理机关批准。"},{"i":35,"n":"第三十五条","txt":"监狱应当建立罪犯档案，做好有关材料的收集归档和安全保管工作。"},{"i":36,"n":"第三十六条","txt":"依法应当由国家安全机关负责送交监狱执行刑罚的罪犯，由国家安全机关依照本法第三十一条、第三十二条、第三十五条有关公安机关的规定送交监狱。"},{"i":37,"n":"第三十七条","txt":"罪犯收监后，监狱应当通知罪犯家属或者监护人。罪犯无家属、监护人或者无法通知其家属、监护人的，监狱应当通知罪犯户籍所在地或者居住地居民委员会、村民委员会。通知书应当自收监之日起五个工作日以内发出。"},{"i":38,"n":"第三十八条","txt":"罪犯不得携带子女在监狱内服刑。"},{"i":39,"n":"第三十九条","txt":"罪犯对生效的判决、裁定不服提出申诉的，人民检察院或者人民法院收到申诉材料后，应当在规定期限内作出处理，并按照规定将处理结果书面告知监狱和罪犯。"},{"i":40,"n":"第四十条","txt":"罪犯提出的控告、检举，由监狱处理的，应当在三个月以内处理完毕；转送监察机关、人民检察院或者公安机关处理的，监察机关、人民检察院或者公安机关收到监狱转递的材料后，应当在规定期限内作出处理，并按照规定将处理结果书面告知监狱。"},{"i":41,"n":"第四十一条","txt":"监狱收到罪犯的申诉、控告、检举材料后，需要转送其他机关处理的，应当在五个工作日以内转递，不得扣压。"},{"i":42,"n":"第四十二条","txt":"监狱在执行刑罚过程中，认为判决、裁定、决定可能有错误的，应当提请人民检察院或者作出生效裁判的人民法院处理，人民检察院或者作出生效裁判的人民法院应当自收到监狱提请处理意见书之日起三个月以内将处理结果通知监狱。案情复杂或者情况特殊需要延长的，延长时间不超过三个月。"},{"i":43,"n":"第四十三条","txt":"监狱、人民法院、人民检察院不得将罪犯依法提出申诉、控告、检举，作为认定罪犯不服从管教、没有悔改表现的依据。"},{"i":44,"n":"第四十四条","txt":"对于被判处无期徒刑、有期徒刑在监狱内服刑的罪犯，符合《中华人民共和国刑事诉讼法》规定的暂予监外执行条件的，可以暂予监外执行。"},{"i":45,"n":"第四十五条","txt":"暂予监外执行，由监狱提出书面建议，报省、自治区、直辖市监狱管理机关批准，并抄送人民检察院。人民检察院可以向监狱管理机关提出书面意见。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市监狱管理机关批准暂予监外执行的，应当将暂予监外执行决定书送达监狱和执行地社区矫正机构，并抄送同级人民检察院、作出生效裁判的人民法院以及社区矫正执行地公安机关。"},{"i":47,"n":"第四十七条","txt":"对暂予监外执行的罪犯，依法实行社区矫正，由社区矫正机构负责执行。原关押监狱应当自收到暂予监外执行决定书之日起十日以内将罪犯移送社区矫正机构，通报罪犯改造情况，并及时将罪犯移送情况通报人民检察院。"},{"i":48,"n":"第四十八条","txt":"暂予监外执行的罪犯具有《中华人民共和国刑事诉讼法》规定的应当收监情形的，社区矫正机构应当向执行地或者原批准暂予监外执行的监狱管理机关提出收监执行建议，监狱管理机关应当依法作出决定；刑期届满的，由原关押或者接收罪犯档案的监狱依法办理刑满释放手续。"},{"i":49,"n":"第四十九条","txt":"被判处无期徒刑、有期徒刑的罪犯，在服刑期间确有悔改或者立功表现，符合法律规定的减刑条件的，根据监狱考核的结果，可以减刑；有下列重大立功表现之一的，应当减刑："},{"i":50,"n":"第五十条","txt":"监狱提出减刑、假释建议，应当经监狱减刑假释评审委员会评审。评审后同意对罪犯提请减刑、假释的，应当在监狱内进行公示。公示期为五个工作日。公示期内，罪犯对公示内容提出异议的，监狱减刑假释评审委员会应当进行复核。公示无异议或者经复核异议不成立的，经监狱负责人集体讨论决定提出减刑、假释建议。"},{"i":51,"n":"第五十一条","txt":"有期徒刑减刑建议由监狱提请所在地中级人民法院裁定；无期徒刑减为有期徒刑的，由监狱提出减刑建议，报经省、自治区、直辖市监狱管理机关审核同意后，提请高级人民法院裁定。减刑建议书应当抄送人民检察院。人民检察院可以向人民法院提出书面意见。"},{"i":52,"n":"第五十二条","txt":"被判处死刑缓期二年执行的罪犯，在死刑缓期执行期间，符合法律规定的减为无期徒刑、有期徒刑条件的，死刑缓期执行期满时，所在监狱应当及时提出减刑建议，报经省、自治区、直辖市监狱管理机关审核同意后，提请高级人民法院裁定。"},{"i":53,"n":"第五十三条","txt":"被判处有期徒刑和被减为有期徒刑的罪犯，符合法律规定的假释条件的，由监狱提请所在地中级人民法院裁定；被判处无期徒刑和被减为无期徒刑的罪犯，符合法律规定的假释条件的，由监狱提出假释建议，报经省、自治区、直辖市监狱管理机关审核同意后，提请高级人民法院裁定。假释建议书应当抄送人民检察院。人民检察院可以向人民法院提出书面意见。"},{"i":54,"n":"第五十四条","txt":"人民法院裁定假释的，监狱应当按期假释并发给假释证明书。"},{"i":55,"n":"第五十五条","txt":"人民法院审理减刑、假释案件，应当作出是否予以减刑、假释的裁定。对监狱提请减刑幅度作出调整或者不予减刑、假释的，应当在裁定书中说明理由。"},{"i":56,"n":"第五十六条","txt":"对不符合法律规定的减刑、假释条件的罪犯，不得减刑、假释。"},{"i":57,"n":"第五十七条","txt":"监狱、人民法院、人民检察院应当依法及时公正办理罪犯减刑、假释案件，充分发挥减刑、假释在刑罚执行中的作用。"},{"i":58,"n":"第五十八条","txt":"监狱在罪犯服刑期满或者假释之前，应当对其进行一定时间的出监教育，以巩固教育改造成果，提高其出狱后尽快适应社会生活的能力，促进其顺利回归社会。"},{"i":59,"n":"第五十九条","txt":"罪犯服刑期满或者被赦免后，监狱应当按期释放，发给释放证明书，并与罪犯户籍所在地或者居住地县级安置帮教机构做好人员衔接。"},{"i":60,"n":"第六十条","txt":"对刑满释放人员，户籍所在地或者居住地人民政府组织开展教育引导，鼓励支持其自主创业、自谋职业，引导其参加社会保险，促进其重新融入社会。"},{"i":61,"n":"第六十一条","txt":"国家鼓励、引导和支持社会力量参与刑满释放人员安置帮教工作。"},{"i":62,"n":"第六十二条","txt":"刑满释放人员依法享有与其他公民平等的权利，在就业、就学和享受社会保障等方面不受歧视。"},{"i":63,"n":"第六十三条","txt":"监狱对男犯和女犯、成年犯和未成年犯实行分开关押和管理。"},{"i":64,"n":"第六十四条","txt":"对未成年犯、女犯、老年犯、病犯、残疾犯的管理，应当照顾其生理、心理特点。"},{"i":65,"n":"第六十五条","txt":"监狱人民警察遇有下列情形之一的，可以使用约束性警械："},{"i":66,"n":"第六十六条","txt":"监狱人民警察和人民武装警察部队的执勤人员遇有罪犯暴乱、脱逃、拒捕、行凶、抢夺武器或者实施其他暴力行为的紧急情况，经警告无效，非使用武器不能制止的，按照国家有关规定，可以使用武器。"},{"i":67,"n":"第六十七条","txt":"监狱人民警察使用警械、武器，应当以制止罪犯实施本法第六十五条、第六十六条行为为限度；本法第六十五条、第六十六条所列情形消失或者发现罪犯不适宜继续被约束控制的，应当立即停止使用。造成罪犯身体损伤的，应当及时予以救治。"},{"i":68,"n":"第六十八条","txt":"监狱应当依法保障罪犯的通信权利。"},{"i":69,"n":"第六十九条","txt":"罪犯在监狱服刑期间，按照规定，可以与亲属、监护人通话、会见；与其他人员通话、会见有利于罪犯改造的，经监狱批准也可以通话、会见。"},{"i":70,"n":"第七十条","txt":"罪犯在监狱服刑期间可以与本人及其法定代理人、近亲属委托或者法律援助机构指派的律师会见。罪犯与其辩护律师会见时不被监听。"},{"i":71,"n":"第七十一条","txt":"通话、会见过程中有违反规定行为的，监狱人民警察应当立即制止、给予警告，不听劝阻或者情节严重的，监狱人民警察应当终止通话、会见。"},{"i":72,"n":"第七十二条","txt":"监狱应当设立医疗机构和生活、卫生设施，建立罪犯生活、卫生制度。"},{"i":73,"n":"第七十三条","txt":"罪犯的生活标准按实物量计算，由国家规定。"},{"i":74,"n":"第七十四条","txt":"罪犯的被服和必要的生活用品由监狱统一配发。"},{"i":75,"n":"第七十五条","txt":"罪犯收取物品和钱款，应当经监狱批准、检查。"},{"i":76,"n":"第七十六条","txt":"对罪犯与特定风俗习惯有关的特殊生活习惯，应当根据实际情况予以照顾。"},{"i":77,"n":"第七十七条","txt":"罪犯居住的监舍应当符合坚固、通风、透光、清洁、保暖、防暑的要求。"},{"i":78,"n":"第七十八条","txt":"在天气条件允许的情况下，监狱应当保证罪犯每日适当的户外活动时间。"},{"i":79,"n":"第七十九条","txt":"国家保障罪犯基本医疗。罪犯基本医疗的药品目录、医疗服务项目目录和医用耗材目录参照当地基本医疗保险有关规定执行。"},{"i":80,"n":"第八十条","txt":"罪犯在监狱服刑期间，有关其入狱前、刑满释放后参加社会保险的接续问题，按照国家有关规定办理，监狱和有关部门应当给予协助。具体办法由国务院司法行政部门会同人力资源社会保障、医疗保障等部门制定。"},{"i":81,"n":"第八十一条","txt":"罪犯在监狱服刑期间死亡的，监狱应当立即通知罪犯的近亲属或者监护人，并立即通知人民检察院。"},{"i":82,"n":"第八十二条","txt":"监狱应当按照有关规定建立罪犯的日常考核制度，考核结果作为对罪犯奖励和处罚的依据。"},{"i":83,"n":"第八十三条","txt":"罪犯有下列情形之一的，监狱可以给予表扬、物质奖励或者记功："},{"i":84,"n":"第八十四条","txt":"罪犯有下列破坏监管秩序情形之一的，监狱可以给予警告、记过或者禁闭："},{"i":85,"n":"第八十五条","txt":"被判处有期徒刑和被减为有期徒刑的罪犯，执行有期徒刑二分之一以上，在服刑期间一贯表现好，离开监狱没有再犯罪危险的，经本人书面承诺和亲属担保，监狱可以准其离监探亲。"},{"i":86,"n":"第八十六条","txt":"被判处有期徒刑和被减为有期徒刑的罪犯，其配偶、直系亲属或者监护人病危、死亡的，或者家中发生重大变故，确需本人离监处理的，经本人书面申请，监狱可以根据情况特许其离监探望或者处理，由监狱人民警察押解。"},{"i":87,"n":"第八十七条","txt":"监察机关、人民法院、人民检察院、公安机关、国家安全机关因办案需要将罪犯解回调查、侦查、起诉、审判的，应当经省、自治区、直辖市监狱管理机关批准。"},{"i":88,"n":"第八十八条","txt":"罪犯在服刑期间故意犯罪的，依法从重处罚。"},{"i":89,"n":"第八十九条","txt":"罪犯在监狱内涉嫌犯罪的案件，由监狱立案侦查。侦查终结后，犯罪事实清楚，证据确实、充分的，出具起诉意见书，连同案卷、证据材料一并移送人民检察院。"},{"i":90,"n":"第九十条","txt":"监狱发现在押罪犯脱逃，应当即时将其抓获；不能即时抓获的，应当立即通知公安机关，由公安机关负责追捕，监狱密切配合。"},{"i":91,"n":"第九十一条","txt":"监狱办理罪犯监狱内涉嫌犯罪案件，需要相关刑事技术支持、在监狱外采取侦查措施和刑事强制措施的，公安机关等有关单位应当依法提供协助。"},{"i":92,"n":"第九十二条","txt":"监狱应当创新教育改造方式方法，不断推进教育改造工作科学化、专业化、社会化。"},{"i":93,"n":"第九十三条","txt":"教育改造罪犯，实行因人施教、分类教育、以理服人的原则，采取集体教育与个别教育相结合、狱内教育与社会教育相结合的方法。"},{"i":94,"n":"第九十四条","txt":"监狱应当对罪犯进行行为规范教育，督促其遵守日常管理制度，养成良好的行为习惯。"},{"i":95,"n":"第九十五条","txt":"监狱应当对罪犯进行法治、道德、形势、政策、前途等内容的思想教育，进行爱国主义、集体主义教育和中华优秀传统文化教育，引导罪犯树立社会主义核心价值观，增强法治意识、纪律意识、道德意识，认罪服法，自觉接受改造。"},{"i":96,"n":"第九十六条","txt":"监狱应当对罪犯开展心理健康教育，根据需要进行心理咨询、危机干预和心理矫治。"},{"i":97,"n":"第九十七条","txt":"监狱应当根据不同情况，对罪犯进行扫盲教育、义务教育，对达到学业要求的，由学校颁发相应的学业证书。鼓励罪犯参加职业教育和学历继续教育，经考试合格的，由有关部门、单位颁发相应证书。"},{"i":98,"n":"第九十八条","txt":"监狱根据经济社会发展和罪犯释放后就业的需要，组织罪犯参加职业技能培训，经考核合格的，由有关部门、单位颁发相应证书。"},{"i":99,"n":"第九十九条","txt":"监狱应当设立教室、图书阅览室等必要的教育设施和活动场所，配备必要的书籍、报刊杂志、广播电视接收设备。"},{"i":100,"n":"第一百条","txt":"监狱应当加强同有关国家机关、社会团体、部队、企业事业单位和社会各界人士的联系和合作，为教育改造罪犯、促进刑满释放人员重新融入社会创造条件和提供帮助。"},{"i":101,"n":"第一百零一条","txt":"监狱应当利用自身的设施条件，配合有关方面开展法治宣传和预防犯罪教育，并为高等院校、研究机构等开展监狱和刑罚执行的理论研究和人才培养提供支持和便利。"},{"i":102,"n":"第一百零二条","txt":"监狱根据罪犯劳动能力、身体健康状况等个人情况和教育改造需要，合理确定劳动项目、任务，使其矫正恶习，养成劳动习惯，学习劳动技能，并为释放后就业创造条件。"},{"i":103,"n":"第一百零三条","txt":"监狱对罪犯的劳动时间，参照国家有关劳动工时的规定执行。"},{"i":104,"n":"第一百零四条","txt":"监狱对参加劳动的罪犯，应当按照有关规定给予报酬并执行国家有关劳动保护的规定。"},{"i":105,"n":"第一百零五条","txt":"罪犯在劳动中致伤、致残或者死亡的，由监狱按照有关规定处理，具体规定由国务院司法行政部门会同财政、人力资源社会保障部门制定。"},{"i":106,"n":"第一百零六条","txt":"未成年犯应当在未成年犯管教所执行刑罚。"},{"i":107,"n":"第一百零七条","txt":"未成年犯年满十八周岁时，剩余刑期不超过二年的，仍可以留在未成年犯管教所执行剩余刑期。"},{"i":108,"n":"第一百零八条","txt":"未成年犯管教所应当依法保障未成年犯的合法权益，尊重未成年犯的人格尊严，创造有益于未成年犯身心健康、积极向上的改造环境。"},{"i":109,"n":"第一百零九条","txt":"未成年犯管教所应当配备具有法学、教育学、心理学等相关专业背景，经过专门培训，熟悉未成年人身心特点的人民警察。"},{"i":110,"n":"第一百一十条","txt":"对未成年犯执行刑罚应当实行教育、感化、挽救的方针，以教育改造为主。未成年犯的劳动，应当符合未成年人的特点，以学习文化和劳动技能为主。"},{"i":111,"n":"第一百一十一条","txt":"未成年犯的通信、会见、离监探亲和特许离监，条件可以比照成年犯适当放宽。"},{"i":112,"n":"第一百一十二条","txt":"未成年犯管教所应当建立心理矫治机构，对未成年犯进行心理测试，根据未成年犯的心理特征，定期开展心理辅导、心理咨询等活动，促进其身心健康发展。"},{"i":113,"n":"第一百一十三条","txt":"未成年犯管教所应当配合学校等教育机构，为未成年犯接受义务教育和其他教育提供必要的条件。"},{"i":114,"n":"第一百一十四条","txt":"未成年犯管教所应当加强同未成年犯的监护人、家庭成员和有利于未成年犯教育改造的其他人员的联系，引导他们协同做好未成年犯教育改造工作。"},{"i":115,"n":"第一百一十五条","txt":"监狱应当依照有关法律规定对符合封存条件的未成年犯的犯罪记录及相关案件信息予以封存，除司法机关为办案需要或者有关单位根据国家规定查询外，不得将未成年犯的犯罪记录及相关案件信息提供给任何单位或者个人。"},{"i":116,"n":"第一百一十六条","txt":"对未成年犯的管理和教育改造，本章未作规定的，适用本法的有关规定。"},{"i":117,"n":"第一百一十七条","txt":"监狱人民警察有本法第二十三条所列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":118,"n":"第一百一十八条","txt":"单位或者个人有下列行为之一，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任："},{"i":119,"n":"第一百一十九条","txt":"监狱保障外国籍罪犯的合法权益，保障其在刑罚执行活动中得到公平公正对待。"},{"i":120,"n":"第一百二十条","txt":"本法所称以上、以下、以内，包括本数。"},{"i":121,"n":"第一百二十一条","txt":"本法自2026年11月1日起施行。"}],"jianyufa":[{"i":1,"n":"第一条","txt":"为了正确执行刑罚，惩罚和改造罪犯，预防和减少犯罪，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"监狱是国家的刑罚执行机关。"},{"i":3,"n":"第三条","txt":"监狱对罪犯实行惩罚和改造相结合、教育和劳动相结合的原则，将罪犯改造成为守法公民。"},{"i":4,"n":"第四条","txt":"监狱对罪犯应当依法监管，根据改造罪犯的需要，组织罪犯从事生产劳动，对罪犯进行思想教育、文化教育、技术教育。"},{"i":5,"n":"第五条","txt":"监狱的人民警察依法管理监狱、执行刑罚、对罪犯进行教育改造等活动，受法律保护。"},{"i":6,"n":"第六条","txt":"人民检察院对监狱执行刑罚的活动是否合法，依法实行监督。"},{"i":7,"n":"第七条","txt":"罪犯的人格不受侮辱，其人身安全、合法财产和辩护、申诉、控告、检举以及其他未被依法剥夺或者限制的权利不受侵犯。"},{"i":8,"n":"第八条","txt":"国家保障监狱改造罪犯所需经费。监狱的人民警察经费、罪犯改造经费、罪犯生活费、狱政设施经费及其他专项经费，列入国家预算。"},{"i":9,"n":"第九条","txt":"监狱依法使用的土地、矿产资源和其他自然资源以及监狱的财产，受法律保护，任何组织或者个人不得侵占、破坏。"},{"i":10,"n":"第十条","txt":"国务院司法行政部门主管全国的监狱工作。"},{"i":11,"n":"第十一条","txt":"监狱的设置、撤销、迁移，由国务院司法行政部门批准。"},{"i":12,"n":"第十二条","txt":"监狱设监狱长一人、副监狱长若干人，并根据实际需要设置必要的工作机构和配备其他监狱管理人员。"},{"i":13,"n":"第十三条","txt":"监狱的人民警察应当严格遵守宪法和法律，忠于职守，秉公执法，严守纪律，清正廉洁。"},{"i":14,"n":"第十四条","txt":"监狱的人民警察不得有下列行为："},{"i":15,"n":"第十五条","txt":"人民法院对被判处死刑缓期二年执行、无期徒刑、有期徒刑的罪犯，应当将执行通知书、判决书送达羁押该罪犯的公安机关，公安机关应当自收到执行通知书、判决书之日起一个月内将该罪犯送交监狱执行刑罚。"},{"i":16,"n":"第十六条","txt":"罪犯被交付执行刑罚时，交付执行的人民法院应当将人民检察院的起诉书副本、人民法院的判决书、执行通知书、结案登记表同时送达监狱。监狱没有收到上述文件的，不得收监；上述文件不齐全或者记载有误的，作出生效判决的人民法院应当及时补充齐全或者作出更正；对其中可能导致错误收监的，不予收监。"},{"i":17,"n":"第十七条","txt":"罪犯被交付执行刑罚，符合本法第十六条规定的，应当予以收监。罪犯收监后，监狱应当对其进行身体检查。经检查，对于具有暂予监外执行情形的，监狱可以提出书面意见，报省级以上监狱管理机关批准。"},{"i":18,"n":"第十八条","txt":"罪犯收监，应当严格检查其人身和所携带的物品。非生活必需品，由监狱代为保管或者征得罪犯同意退回其家属，违禁品予以没收。"},{"i":19,"n":"第十九条","txt":"罪犯不得携带子女在监内服刑。"},{"i":20,"n":"第二十条","txt":"罪犯收监后，监狱应当通知罪犯家属。通知书应当自收监之日起五日内发出。"},{"i":21,"n":"第二十一条","txt":"罪犯对生效的判决不服的，可以提出申诉。"},{"i":22,"n":"第二十二条","txt":"对罪犯提出的控告、检举材料，监狱应当及时处理或者转送公安机关或者人民检察院处理，公安机关或者人民检察院应当将处理结果通知监狱。"},{"i":23,"n":"第二十三条","txt":"罪犯的申诉、控告、检举材料，监狱应当及时转递，不得扣压。"},{"i":24,"n":"第二十四条","txt":"监狱在执行刑罚过程中，根据罪犯的申诉，认为判决可能有错误的，应当提请人民检察院或者人民法院处理，人民检察院或者人民法院应当自收到监狱提请处理意见书之日起六个月内将处理结果通知监狱。"},{"i":25,"n":"第二十五条","txt":"对于被判处无期徒刑、有期徒刑在监内服刑的罪犯，符合刑事诉讼法规定的监外执行条件的，可以暂予监外执行。"},{"i":26,"n":"第二十六条","txt":"暂予监外执行，由监狱提出书面意见，报省、自治区、直辖市监狱管理机关批准。批准机关应当将批准的暂予监外执行决定通知公安机关和原判人民法院，并抄送人民检察院。"},{"i":27,"n":"第二十七条","txt":"对暂予监外执行的罪犯，依法实行社区矫正，由社区矫正机构负责执行。原关押监狱应当及时将罪犯在监内改造情况通报负责执行的社区矫正机构。"},{"i":28,"n":"第二十八条","txt":"暂予监外执行的罪犯具有刑事诉讼法规定的应当收监的情形的，社区矫正机构应当及时通知监狱收监；刑期届满的，由原关押监狱办理释放手续。罪犯在暂予监外执行期间死亡的，社区矫正机构应当及时通知原关押监狱。"},{"i":29,"n":"第二十九条","txt":"被判处无期徒刑、有期徒刑的罪犯，在服刑期间确有悔改或者立功表现的，根据监狱考核的结果，可以减刑。有下列重大立功表现之一的，应当减刑："},{"i":30,"n":"第三十条","txt":"减刑建议由监狱向人民法院提出，人民法院应当自收到减刑建议书之日起一个月内予以审核裁定；案情复杂或者情况特殊的，可以延长一个月。减刑裁定的副本应当抄送人民检察院。"},{"i":31,"n":"第三十一条","txt":"被判处死刑缓期二年执行的罪犯，在死刑缓期执行期间，符合法律规定的减为无期徒刑、有期徒刑条件的，二年期满时，所在监狱应当及时提出减刑建议，报经省、自治区、直辖市监狱管理机关审核后，提请高级人民法院裁定。"},{"i":32,"n":"第三十二条","txt":"被判处无期徒刑、有期徒刑的罪犯，符合法律规定的假释条件的，由监狱根据考核结果向人民法院提出假释建议，人民法院应当自收到假释建议书之日起一个月内予以审核裁定；案情复杂或者情况特殊的，可以延长一个月。假释裁定的副本应当抄送人民检察院。"},{"i":33,"n":"第三十三条","txt":"人民法院裁定假释的，监狱应当按期假释并发给假释证明书。"},{"i":34,"n":"第三十四条","txt":"对不符合法律规定的减刑、假释条件的罪犯，不得以任何理由将其减刑、假释。"},{"i":35,"n":"第三十五条","txt":"罪犯服刑期满，监狱应当按期释放并发给释放证明书。"},{"i":36,"n":"第三十六条","txt":"罪犯释放后，公安机关凭释放证明书办理户籍登记。"},{"i":37,"n":"第三十七条","txt":"对刑满释放人员，当地人民政府帮助其安置生活。"},{"i":38,"n":"第三十八条","txt":"刑满释放人员依法享有与其他公民平等的权利。"},{"i":39,"n":"第三十九条","txt":"监狱对成年男犯、女犯和未成年犯实行分开关押和管理，对未成年犯和女犯的改造，应当照顾其生理、心理特点。"},{"i":40,"n":"第四十条","txt":"女犯由女性人民警察直接管理。"},{"i":41,"n":"第四十一条","txt":"监狱的武装警戒由人民武装警察部队负责，具体办法由国务院、中央军事委员会规定。"},{"i":42,"n":"第四十二条","txt":"监狱发现在押罪犯脱逃，应当即时将其抓获，不能即时抓获的，应当立即通知公安机关，由公安机关负责追捕，监狱密切配合。"},{"i":43,"n":"第四十三条","txt":"监狱根据监管需要，设立警戒设施。监狱周围设警戒隔离带，未经准许，任何人不得进入。"},{"i":44,"n":"第四十四条","txt":"监区、作业区周围的机关、团体、企业事业单位和基层组织，应当协助监狱做好安全警戒工作。"},{"i":45,"n":"第四十五条","txt":"监狱遇有下列情形之一的，可以使用戒具："},{"i":46,"n":"第四十六条","txt":"人民警察和人民武装警察部队的执勤人员遇有下列情形之一，非使用武器不能制止的，按照国家有关规定，可以使用武器："},{"i":47,"n":"第四十七条","txt":"罪犯在服刑期间可以与他人通信，但是来往信件应当经过监狱检查。监狱发现有碍罪犯改造内容的信件，可以扣留。罪犯写给监狱的上级机关和司法机关的信件，不受检查。"},{"i":48,"n":"第四十八条","txt":"罪犯在监狱服刑期间，按照规定，可以会见亲属、监护人。"},{"i":49,"n":"第四十九条","txt":"罪犯收受物品和钱款，应当经监狱批准、检查。"},{"i":50,"n":"第五十条","txt":"罪犯的生活标准按实物量计算，由国家规定。"},{"i":51,"n":"第五十一条","txt":"罪犯的被服由监狱统一配发。"},{"i":52,"n":"第五十二条","txt":"对少数民族罪犯的特殊生活习惯，应当予以照顾。"},{"i":53,"n":"第五十三条","txt":"罪犯居住的监舍应当坚固、通风、透光、清洁、保暖。"},{"i":54,"n":"第五十四条","txt":"监狱应当设立医疗机构和生活、卫生设施，建立罪犯生活、卫生制度。罪犯的医疗保健列入监狱所在地区的卫生、防疫计划。"},{"i":55,"n":"第五十五条","txt":"罪犯在服刑期间死亡的，监狱应当立即通知罪犯家属和人民检察院、人民法院。罪犯因病死亡的，由监狱作出医疗鉴定。人民检察院对监狱的医疗鉴定有疑义的，可以重新对死亡原因作出鉴定。罪犯家属有疑义的，可以向人民检察院提出。罪犯非正常死亡的，人民检察院应当立即检验，对死亡原因作出鉴定。"},{"i":56,"n":"第五十六条","txt":"监狱应当建立罪犯的日常考核制度，考核的结果作为对罪犯奖励和处罚的依据。"},{"i":57,"n":"第五十七条","txt":"罪犯有下列情形之一的，监狱可以给予表扬、物质奖励或者记功："},{"i":58,"n":"第五十八条","txt":"罪犯有下列破坏监管秩序情形之一的，监狱可以给予警告、记过或者禁闭："},{"i":59,"n":"第五十九条","txt":"罪犯在服刑期间故意犯罪的，依法从重处罚。"},{"i":60,"n":"第六十条","txt":"对罪犯在监狱内犯罪的案件，由监狱进行侦查。侦查终结后，写出起诉意见书，连同案卷材料、证据一并移送人民检察院。"},{"i":61,"n":"第六十一条","txt":"教育改造罪犯，实行因人施教、分类教育，以理服人的原则，采取集体教育与个别教育相结合、狱内教育与社会教育相结合的方法。"},{"i":62,"n":"第六十二条","txt":"监狱应当对罪犯进行法制、道德、形势、政策、前途等内容的思想教育。"},{"i":63,"n":"第六十三条","txt":"监狱应当根据不同情况，对罪犯进行扫盲教育、初等教育和初级中等教育，经考试合格的，由教育部门发给相应的学业证书。"},{"i":64,"n":"第六十四条","txt":"监狱应当根据监狱生产和罪犯释放后就业的需要，对罪犯进行职业技术教育，经考核合格的，由劳动部门发给相应的技术等级证书。"},{"i":65,"n":"第六十五条","txt":"监狱鼓励罪犯自学，经考试合格的，由有关部门发给相应的证书。"},{"i":66,"n":"第六十六条","txt":"罪犯的文化和职业技术教育，应当列入所在地区教育规划。监狱应当设立教室、图书阅览室等必要的教育设施。"},{"i":67,"n":"第六十七条","txt":"监狱应当组织罪犯开展适当的体育活动和文化娱乐活动。"},{"i":68,"n":"第六十八条","txt":"国家机关、社会团体、部队、企业事业单位和社会各界人士以及罪犯的亲属，应当协助监狱做好对罪犯的教育改造工作。"},{"i":69,"n":"第六十九条","txt":"有劳动能力的罪犯，必须参加劳动。"},{"i":70,"n":"第七十条","txt":"监狱根据罪犯的个人情况，合理组织劳动，使其矫正恶习，养成劳动习惯，学会生产技能，并为释放后就业创造条件。"},{"i":71,"n":"第七十一条","txt":"监狱对罪犯的劳动时间，参照国家有关劳动工时的规定执行；在季节性生产等特殊情况下，可以调整劳动时间。"},{"i":72,"n":"第七十二条","txt":"监狱对参加劳动的罪犯，应当按照有关规定给予报酬并执行国家有关劳动保护的规定。"},{"i":73,"n":"第七十三条","txt":"罪犯在劳动中致伤、致残或者死亡的，由监狱参照国家劳动保险的有关规定处理。"},{"i":74,"n":"第七十四条","txt":"对未成年犯应当在未成年犯管教所执行刑罚。"},{"i":75,"n":"第七十五条","txt":"对未成年犯执行刑罚应当以教育改造为主。未成年犯的劳动，应当符合未成年人的特点，以学习文化和生产技能为主。"},{"i":76,"n":"第七十六条","txt":"未成年犯年满十八周岁时，剩余刑期不超过二年的，仍可以留在未成年犯管教所执行剩余刑期。"},{"i":77,"n":"第七十七条","txt":"对未成年犯的管理和教育改造，本章未作规定的，适用本法的有关规定。"},{"i":78,"n":"第七十八条","txt":"本法自公布之日起施行。"}],"shequjiaozhengfa":[{"i":1,"n":"第一条","txt":"为了推进和规范社区矫正工作，保障刑事判决、刑事裁定和暂予监外执行决定的正确执行，提高教育矫正质量，促进社区矫正对象顺利融入社会，预防和减少犯罪，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"对被判处管制、宣告缓刑、假释和暂予监外执行的罪犯，依法实行社区矫正。"},{"i":3,"n":"第三条","txt":"社区矫正工作坚持监督管理与教育帮扶相结合，专门机关与社会力量相结合，采取分类管理、个别化矫正，有针对性地消除社区矫正对象可能重新犯罪的因素，帮助其成为守法公民。"},{"i":4,"n":"第四条","txt":"社区矫正对象应当依法接受社区矫正，服从监督管理。"},{"i":5,"n":"第五条","txt":"国家支持社区矫正机构提高信息化水平，运用现代信息技术开展监督管理和教育帮扶。社区矫正工作相关部门之间依法进行信息共享。"},{"i":6,"n":"第六条","txt":"各级人民政府应当将社区矫正经费列入本级政府预算。"},{"i":7,"n":"第七条","txt":"对在社区矫正工作中做出突出贡献的组织、个人，按照国家有关规定给予表彰、奖励。"},{"i":8,"n":"第八条","txt":"国务院司法行政部门主管全国的社区矫正工作。县级以上地方人民政府司法行政部门主管本行政区域内的社区矫正工作。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府根据需要设置社区矫正机构，负责社区矫正工作的具体实施。社区矫正机构的设置和撤销，由县级以上地方人民政府司法行政部门提出意见，按照规定的权限和程序审批。"},{"i":10,"n":"第十条","txt":"社区矫正机构应当配备具有法律等专业知识的专门国家工作人员（以下称社区矫正机构工作人员），履行监督管理、教育帮扶等执法职责。"},{"i":11,"n":"第十一条","txt":"社区矫正机构根据需要，组织具有法律、教育、心理、社会工作等专业知识或者实践经验的社会工作者开展社区矫正相关工作。"},{"i":12,"n":"第十二条","txt":"居民委员会、村民委员会依法协助社区矫正机构做好社区矫正工作。"},{"i":13,"n":"第十三条","txt":"国家鼓励、支持企业事业单位、社会组织、志愿者等社会力量依法参与社区矫正工作。"},{"i":14,"n":"第十四条","txt":"社区矫正机构工作人员应当严格遵守宪法和法律，忠于职守，严守纪律，清正廉洁。"},{"i":15,"n":"第十五条","txt":"社区矫正机构工作人员和其他参与社区矫正工作的人员依法开展社区矫正工作，受法律保护。"},{"i":16,"n":"第十六条","txt":"国家推进高素质的社区矫正工作队伍建设。社区矫正机构应当加强对社区矫正工作人员的管理、监督、培训和职业保障，不断提高社区矫正工作的规范化、专业化水平。"},{"i":17,"n":"第十七条","txt":"社区矫正决定机关判处管制、宣告缓刑、裁定假释、决定或者批准暂予监外执行时应当确定社区矫正执行地。"},{"i":18,"n":"第十八条","txt":"社区矫正决定机关根据需要，可以委托社区矫正机构或者有关社会组织对被告人或者罪犯的社会危险性和对所居住社区的影响，进行调查评估，提出意见，供决定社区矫正时参考。居民委员会、村民委员会等组织应当提供必要的协助。"},{"i":19,"n":"第十九条","txt":"社区矫正决定机关判处管制、宣告缓刑、裁定假释、决定或者批准暂予监外执行，应当按照刑法、刑事诉讼法等法律规定的条件和程序进行。"},{"i":20,"n":"第二十条","txt":"社区矫正决定机关应当自判决、裁定或者决定生效之日起五日内通知执行地社区矫正机构，并在十日内送达有关法律文书，同时抄送人民检察院和执行地公安机关。社区矫正决定地与执行地不在同一地方的，由执行地社区矫正机构将法律文书转送所在地的人民检察院、公安机关。"},{"i":21,"n":"第二十一条","txt":"人民法院判处管制、宣告缓刑、裁定假释的社区矫正对象，应当自判决、裁定生效之日起十日内到执行地社区矫正机构报到。"},{"i":22,"n":"第二十二条","txt":"社区矫正机构应当依法接收社区矫正对象，核对法律文书、核实身份、办理接收登记、建立档案，并宣告社区矫正对象的犯罪事实、执行社区矫正的期限以及应当遵守的规定。"},{"i":23,"n":"第二十三条","txt":"社区矫正对象在社区矫正期间应当遵守法律、行政法规，履行判决、裁定、暂予监外执行决定等法律文书确定的义务，遵守国务院司法行政部门关于报告、会客、外出、迁居、保外就医等监督管理规定，服从社区矫正机构的管理。"},{"i":24,"n":"第二十四条","txt":"社区矫正机构应当根据裁判内容和社区矫正对象的性别、年龄、心理特点、健康状况、犯罪原因、犯罪类型、犯罪情节、悔罪表现等情况，制定有针对性的矫正方案，实现分类管理、个别化矫正。矫正方案应当根据社区矫正对象的表现等情况相应调整。"},{"i":25,"n":"第二十五条","txt":"社区矫正机构应当根据社区矫正对象的情况，为其确定矫正小组，负责落实相应的矫正方案。"},{"i":26,"n":"第二十六条","txt":"社区矫正机构应当了解掌握社区矫正对象的活动情况和行为表现。社区矫正机构可以通过通信联络、信息化核查、实地查访等方式核实有关情况，有关单位和个人应当予以配合。"},{"i":27,"n":"第二十七条","txt":"社区矫正对象离开所居住的市、县或者迁居，应当报经社区矫正机构批准。社区矫正机构对于有正当理由的，应当批准；对于因正常工作和生活需要经常性跨市、县活动的，可以根据情况，简化批准程序和方式。"},{"i":28,"n":"第二十八条","txt":"社区矫正机构根据社区矫正对象的表现，依照有关规定对其实施考核奖惩。社区矫正对象认罪悔罪、遵守法律法规、服从监督管理、接受教育表现突出的，应当给予表扬。社区矫正对象违反法律法规或者监督管理规定的，应当视情节依法给予训诫、警告、提请公安机关予以治安管理处罚，或者依法提请撤销缓刑、撤销假释、对暂予监外执行的收监执行。"},{"i":29,"n":"第二十九条","txt":"社区矫正对象有下列情形之一的，经县级司法行政部门负责人批准，可以使用电子定位装置，加强监督管理："},{"i":30,"n":"第三十条","txt":"社区矫正对象失去联系的，社区矫正机构应当立即组织查找，公安机关等有关单位和人员应当予以配合协助。查找到社区矫正对象后，应当区别情形依法作出处理。"},{"i":31,"n":"第三十一条","txt":"社区矫正机构发现社区矫正对象正在实施违反监督管理规定的行为或者违反人民法院禁止令等违法行为的，应当立即制止；制止无效的，应当立即通知公安机关到场处置。"},{"i":32,"n":"第三十二条","txt":"社区矫正对象有被依法决定拘留、强制隔离戒毒、采取刑事强制措施等限制人身自由情形的，有关机关应当及时通知社区矫正机构。"},{"i":33,"n":"第三十三条","txt":"社区矫正对象符合刑法规定的减刑条件的，社区矫正机构应当向社区矫正执行地的中级以上人民法院提出减刑建议，并将减刑建议书抄送同级人民检察院。"},{"i":34,"n":"第三十四条","txt":"开展社区矫正工作，应当保障社区矫正对象的合法权益。社区矫正的措施和方法应当避免对社区矫正对象的正常工作和生活造成不必要的影响；非依法律规定，不得限制或者变相限制社区矫正对象的人身自由。"},{"i":35,"n":"第三十五条","txt":"县级以上地方人民政府及其有关部门应当通过多种形式为教育帮扶社区矫正对象提供必要的场所和条件，组织动员社会力量参与教育帮扶工作。"},{"i":36,"n":"第三十六条","txt":"社区矫正机构根据需要，对社区矫正对象进行法治、道德等教育，增强其法治观念，提高其道德素质和悔罪意识。"},{"i":37,"n":"第三十七条","txt":"社区矫正机构可以协调有关部门和单位，依法对就业困难的社区矫正对象开展职业技能培训、就业指导，帮助社区矫正对象中的在校学生完成学业。"},{"i":38,"n":"第三十八条","txt":"居民委员会、村民委员会可以引导志愿者和社区群众，利用社区资源，采取多种形式，对有特殊困难的社区矫正对象进行必要的教育帮扶。"},{"i":39,"n":"第三十九条","txt":"社区矫正对象的监护人、家庭成员，所在单位或者就读学校应当协助社区矫正机构做好对社区矫正对象的教育。"},{"i":40,"n":"第四十条","txt":"社区矫正机构可以通过公开择优购买社区矫正社会工作服务或者其他社会服务，为社区矫正对象在教育、心理辅导、职业技能培训、社会关系改善等方面提供必要的帮扶。"},{"i":41,"n":"第四十一条","txt":"国家鼓励企业事业单位、社会组织为社区矫正对象提供就业岗位和职业技能培训。招用符合条件的社区矫正对象的企业，按照规定享受国家优惠政策。"},{"i":42,"n":"第四十二条","txt":"社区矫正机构可以根据社区矫正对象的个人特长，组织其参加公益活动，修复社会关系，培养社会责任感。"},{"i":43,"n":"第四十三条","txt":"社区矫正对象可以按照国家有关规定申请社会救助、参加社会保险、获得法律援助，社区矫正机构应当给予必要的协助。"},{"i":44,"n":"第四十四条","txt":"社区矫正对象矫正期满或者被赦免的，社区矫正机构应当向社区矫正对象发放解除社区矫正证明书，并通知社区矫正决定机关、所在地的人民检察院、公安机关。"},{"i":45,"n":"第四十五条","txt":"社区矫正对象被裁定撤销缓刑、假释，被决定收监执行，或者社区矫正对象死亡的，社区矫正终止。"},{"i":46,"n":"第四十六条","txt":"社区矫正对象具有刑法规定的撤销缓刑、假释情形的，应当由人民法院撤销缓刑、假释。"},{"i":47,"n":"第四十七条","txt":"被提请撤销缓刑、假释的社区矫正对象可能逃跑或者可能发生社会危险的，社区矫正机构可以在提出撤销缓刑、假释建议的同时，提请人民法院决定对其予以逮捕。"},{"i":48,"n":"第四十八条","txt":"人民法院应当在收到社区矫正机构撤销缓刑、假释建议书后三十日内作出裁定，将裁定书送达社区矫正机构和公安机关，并抄送人民检察院。"},{"i":49,"n":"第四十九条","txt":"暂予监外执行的社区矫正对象具有刑事诉讼法规定的应当予以收监情形的，社区矫正机构应当向执行地或者原社区矫正决定机关提出收监执行建议，并将建议书抄送人民检察院。"},{"i":50,"n":"第五十条","txt":"被裁定撤销缓刑、假释和被决定收监执行的社区矫正对象逃跑的，由公安机关追捕，社区矫正机构、有关单位和个人予以协助。"},{"i":51,"n":"第五十一条","txt":"社区矫正对象在社区矫正期间死亡的，其监护人、家庭成员应当及时向社区矫正机构报告。社区矫正机构应当及时通知社区矫正决定机关、所在地的人民检察院、公安机关。"},{"i":52,"n":"第五十二条","txt":"社区矫正机构应当根据未成年社区矫正对象的年龄、心理特点、发育需要、成长经历、犯罪原因、家庭监护教育条件等情况，采取针对性的矫正措施。"},{"i":53,"n":"第五十三条","txt":"未成年社区矫正对象的监护人应当履行监护责任，承担抚养、管教等义务。"},{"i":54,"n":"第五十四条","txt":"社区矫正机构工作人员和其他依法参与社区矫正工作的人员对履行职责过程中获得的未成年人身份信息应当予以保密。"},{"i":55,"n":"第五十五条","txt":"对未完成义务教育的未成年社区矫正对象，社区矫正机构应当通知并配合教育部门为其完成义务教育提供条件。未成年社区矫正对象的监护人应当依法保证其按时入学接受并完成义务教育。"},{"i":56,"n":"第五十六条","txt":"共产主义青年团、妇女联合会、未成年人保护组织应当依法协助社区矫正机构做好未成年人社区矫正工作。"},{"i":57,"n":"第五十七条","txt":"未成年社区矫正对象在复学、升学、就业等方面依法享有与其他未成年人同等的权利，任何单位和个人不得歧视。有歧视行为的，应当由教育、人力资源和社会保障等部门依法作出处理。"},{"i":58,"n":"第五十八条","txt":"未成年社区矫正对象在社区矫正期间年满十八周岁的，继续按照未成年人社区矫正有关规定执行。"},{"i":59,"n":"第五十九条","txt":"社区矫正对象在社区矫正期间有违反监督管理规定行为的，由公安机关依照《中华人民共和国治安管理处罚法》的规定给予处罚；具有撤销缓刑、假释或者暂予监外执行收监情形的，应当依法作出处理。"},{"i":60,"n":"第六十条","txt":"社区矫正对象殴打、威胁、侮辱、骚扰、报复社区矫正机构工作人员和其他依法参与社区矫正工作的人员及其近亲属，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关依法给予治安管理处罚。"},{"i":61,"n":"第六十一条","txt":"社区矫正机构工作人员和其他国家工作人员有下列行为之一的，应当给予处分；构成犯罪的，依法追究刑事责任："},{"i":62,"n":"第六十二条","txt":"人民检察院发现社区矫正工作违反法律规定的，应当依法提出纠正意见、检察建议。有关单位应当将采纳纠正意见、检察建议的情况书面回复人民检察院，没有采纳的应当说明理由。"},{"i":63,"n":"第六十三条","txt":"本法自2020年7月1日起施行。"}],"jindufa":[{"i":1,"n":"第一条","txt":"为了预防和惩治毒品违法犯罪行为，保护公民身心健康，维护社会秩序，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称毒品，是指鸦片、海洛因、甲基苯丙胺（冰毒）、吗啡、大麻、可卡因，以及国家规定管制的其他能够使人形成瘾癖的麻醉药品和精神药品。"},{"i":3,"n":"第三条","txt":"禁毒是全社会的共同责任。国家机关、社会团体、企业事业单位以及其他组织和公民，应当依照本法和有关法律的规定，履行禁毒职责或者义务。"},{"i":4,"n":"第四条","txt":"禁毒工作实行预防为主，综合治理，禁种、禁制、禁贩、禁吸并举的方针。"},{"i":5,"n":"第五条","txt":"国务院设立国家禁毒委员会，负责组织、协调、指导全国的禁毒工作。"},{"i":6,"n":"第六条","txt":"县级以上各级人民政府应当将禁毒工作纳入国民经济和社会发展规划，并将禁毒经费列入本级财政预算。"},{"i":7,"n":"第七条","txt":"国家鼓励对禁毒工作的社会捐赠，并依法给予税收优惠。"},{"i":8,"n":"第八条","txt":"国家鼓励开展禁毒科学技术研究，推广先进的缉毒技术、装备和戒毒方法。"},{"i":9,"n":"第九条","txt":"国家鼓励公民举报毒品违法犯罪行为。各级人民政府和有关部门应当对举报人予以保护，对举报有功人员以及在禁毒工作中有突出贡献的单位和个人，给予表彰和奖励。"},{"i":10,"n":"第十条","txt":"国家鼓励志愿人员参与禁毒宣传教育和戒毒社会服务工作。地方各级人民政府应当对志愿人员进行指导、培训，并提供必要的工作条件。"},{"i":11,"n":"第十一条","txt":"国家采取各种形式开展全民禁毒宣传教育，普及毒品预防知识，增强公民的禁毒意识，提高公民自觉抵制毒品的能力。"},{"i":12,"n":"第十二条","txt":"各级人民政府应当经常组织开展多种形式的禁毒宣传教育。"},{"i":13,"n":"第十三条","txt":"教育行政部门、学校应当将禁毒知识纳入教育、教学内容，对学生进行禁毒宣传教育。公安机关、司法行政部门和卫生行政部门应当予以协助。"},{"i":14,"n":"第十四条","txt":"新闻、出版、文化、广播、电影、电视等有关单位，应当有针对性地面向社会进行禁毒宣传教育。"},{"i":15,"n":"第十五条","txt":"飞机场、火车站、长途汽车站、码头以及旅店、娱乐场所等公共场所的经营者、管理者，负责本场所的禁毒宣传教育，落实禁毒防范措施，预防毒品违法犯罪行为在本场所内发生。"},{"i":16,"n":"第十六条","txt":"国家机关、社会团体、企业事业单位以及其他组织，应当加强对本单位人员的禁毒宣传教育。"},{"i":17,"n":"第十七条","txt":"居民委员会、村民委员会应当协助人民政府以及公安机关等部门，加强禁毒宣传教育，落实禁毒防范措施。"},{"i":18,"n":"第十八条","txt":"未成年人的父母或者其他监护人应当对未成年人进行毒品危害的教育，防止其吸食、注射毒品或者进行其他毒品违法犯罪活动。"},{"i":19,"n":"第十九条","txt":"国家对麻醉药品药用原植物种植实行管制。禁止非法种植罂粟、古柯植物、大麻植物以及国家规定管制的可以用于提炼加工毒品的其他原植物。禁止走私或者非法买卖、运输、携带、持有未经灭活的毒品原植物种子或者幼苗。"},{"i":20,"n":"第二十条","txt":"国家确定的麻醉药品药用原植物种植企业，必须按照国家有关规定种植麻醉药品药用原植物。"},{"i":21,"n":"第二十一条","txt":"国家对麻醉药品和精神药品实行管制，对麻醉药品和精神药品的实验研究、生产、经营、使用、储存、运输实行许可和查验制度。"},{"i":22,"n":"第二十二条","txt":"国家对麻醉药品、精神药品和易制毒化学品的进口、出口实行许可制度。国务院有关部门应当按照规定的职责，对进口、出口麻醉药品、精神药品和易制毒化学品依法进行管理。禁止走私麻醉药品、精神药品和易制毒化学品。"},{"i":23,"n":"第二十三条","txt":"发生麻醉药品、精神药品和易制毒化学品被盗、被抢、丢失或者其他流入非法渠道的情形，案发单位应当立即采取必要的控制措施，并立即向公安机关报告，同时依照规定向有关主管部门报告。"},{"i":24,"n":"第二十四条","txt":"禁止非法传授麻醉药品、精神药品和易制毒化学品的制造方法。公安机关接到举报或者发现非法传授麻醉药品、精神药品和易制毒化学品制造方法的，应当及时依法查处。"},{"i":25,"n":"第二十五条","txt":"麻醉药品、精神药品和易制毒化学品管理的具体办法，由国务院规定。"},{"i":26,"n":"第二十六条","txt":"公安机关根据查缉毒品的需要，可以在边境地区、交通要道、口岸以及飞机场、火车站、长途汽车站、码头对来往人员、物品、货物以及交通工具进行毒品和易制毒化学品检查，民航、铁路、交通部门应当予以配合。"},{"i":27,"n":"第二十七条","txt":"娱乐场所应当建立巡查制度，发现娱乐场所内有毒品违法犯罪活动的，应当立即向公安机关报告。"},{"i":28,"n":"第二十八条","txt":"对依法查获的毒品，吸食、注射毒品的用具，毒品违法犯罪的非法所得及其收益，以及直接用于实施毒品违法犯罪行为的本人所有的工具、设备、资金，应当收缴，依照规定处理。"},{"i":29,"n":"第二十九条","txt":"反洗钱行政主管部门应当依法加强对可疑毒品犯罪资金的监测。反洗钱行政主管部门和其他依法负有反洗钱监督管理职责的部门、机构发现涉嫌毒品犯罪的资金流动情况，应当及时向侦查机关报告，并配合侦查机关做好侦查、调查工作。"},{"i":30,"n":"第三十条","txt":"国家建立健全毒品监测和禁毒信息系统，开展毒品监测和禁毒信息的收集、分析、使用、交流工作。"},{"i":31,"n":"第三十一条","txt":"国家采取各种措施帮助吸毒人员戒除毒瘾，教育和挽救吸毒人员。"},{"i":32,"n":"第三十二条","txt":"公安机关可以对涉嫌吸毒的人员进行必要的检测，被检测人员应当予以配合；对拒绝接受检测的，经县级以上人民政府公安机关或者其派出机构负责人批准，可以强制检测。"},{"i":33,"n":"第三十三条","txt":"对吸毒成瘾人员，公安机关可以责令其接受社区戒毒，同时通知吸毒人员户籍所在地或者现居住地的城市街道办事处、乡镇人民政府。社区戒毒的期限为三年。"},{"i":34,"n":"第三十四条","txt":"城市街道办事处、乡镇人民政府负责社区戒毒工作。城市街道办事处、乡镇人民政府可以指定有关基层组织，根据戒毒人员本人和家庭情况，与戒毒人员签订社区戒毒协议，落实有针对性的社区戒毒措施。公安机关和司法行政、卫生行政、民政等部门应当对社区戒毒工作提供指导和协助。"},{"i":35,"n":"第三十五条","txt":"接受社区戒毒的戒毒人员应当遵守法律、法规，自觉履行社区戒毒协议，并根据公安机关的要求，定期接受检测。"},{"i":36,"n":"第三十六条","txt":"吸毒人员可以自行到具有戒毒治疗资质的医疗机构接受戒毒治疗。"},{"i":37,"n":"第三十七条","txt":"医疗机构根据戒毒治疗的需要，可以对接受戒毒治疗的戒毒人员进行身体和所携带物品的检查；对在治疗期间有人身危险的，可以采取必要的临时保护性约束措施。"},{"i":38,"n":"第三十八条","txt":"吸毒成瘾人员有下列情形之一的，由县级以上人民政府公安机关作出强制隔离戒毒的决定："},{"i":39,"n":"第三十九条","txt":"怀孕或者正在哺乳自己不满一周岁婴儿的妇女吸毒成瘾的，不适用强制隔离戒毒。不满十六周岁的未成年人吸毒成瘾的，可以不适用强制隔离戒毒。"},{"i":40,"n":"第四十条","txt":"公安机关对吸毒成瘾人员决定予以强制隔离戒毒的，应当制作强制隔离戒毒决定书，在执行强制隔离戒毒前送达被决定人，并在送达后二十四小时以内通知被决定人的家属、所在单位和户籍所在地公安派出所；被决定人不讲真实姓名、住址，身份不明的，公安机关应当自查清其身份后通知。"},{"i":41,"n":"第四十一条","txt":"对被决定予以强制隔离戒毒的人员，由作出决定的公安机关送强制隔离戒毒场所执行。"},{"i":42,"n":"第四十二条","txt":"戒毒人员进入强制隔离戒毒场所戒毒时，应当接受对其身体和所携带物品的检查。"},{"i":43,"n":"第四十三条","txt":"强制隔离戒毒场所应当根据戒毒人员吸食、注射毒品的种类及成瘾程度等，对戒毒人员进行有针对性的生理、心理治疗和身体康复训练。"},{"i":44,"n":"第四十四条","txt":"强制隔离戒毒场所应当根据戒毒人员的性别、年龄、患病等情况，对戒毒人员实行分别管理。"},{"i":45,"n":"第四十五条","txt":"强制隔离戒毒场所应当根据戒毒治疗的需要配备执业医师。强制隔离戒毒场所的执业医师具有麻醉药品和精神药品处方权的，可以按照有关技术规范对戒毒人员使用麻醉药品、精神药品。"},{"i":46,"n":"第四十六条","txt":"戒毒人员的亲属和所在单位或者就读学校的工作人员，可以按照有关规定探访戒毒人员。戒毒人员经强制隔离戒毒场所批准，可以外出探视配偶、直系亲属。"},{"i":47,"n":"第四十七条","txt":"强制隔离戒毒的期限为二年。"},{"i":48,"n":"第四十八条","txt":"对于被解除强制隔离戒毒的人员，强制隔离戒毒的决定机关可以责令其接受不超过三年的社区康复。"},{"i":49,"n":"第四十九条","txt":"县级以上地方各级人民政府根据戒毒工作的需要，可以开办戒毒康复场所；对社会力量依法开办的公益性戒毒康复场所应当给予扶持，提供必要的便利和帮助。"},{"i":50,"n":"第五十条","txt":"公安机关、司法行政部门对被依法拘留、逮捕、收监执行刑罚以及被依法采取强制性教育措施的吸毒人员，应当给予必要的戒毒治疗。"},{"i":51,"n":"第五十一条","txt":"省、自治区、直辖市人民政府卫生行政部门会同公安机关、药品监督管理部门依照国家有关规定，根据巩固戒毒成果的需要和本行政区域艾滋病流行情况，可以组织开展戒毒药物维持治疗工作。"},{"i":52,"n":"第五十二条","txt":"戒毒人员在入学、就业、享受社会保障等方面不受歧视。有关部门、组织和人员应当在入学、就业、享受社会保障等方面对戒毒人员给予必要的指导和帮助。"},{"i":53,"n":"第五十三条","txt":"中华人民共和国根据缔结或者参加的国际条约或者按照对等原则，开展禁毒国际合作。"},{"i":54,"n":"第五十四条","txt":"国家禁毒委员会根据国务院授权，负责组织开展禁毒国际合作，履行国际禁毒公约义务。"},{"i":55,"n":"第五十五条","txt":"涉及追究毒品犯罪的司法协助，由司法机关依照有关法律的规定办理。"},{"i":56,"n":"第五十六条","txt":"国务院有关部门应当按照各自职责，加强与有关国家或者地区执法机关以及国际组织的禁毒情报信息交流，依法开展禁毒执法合作。"},{"i":57,"n":"第五十七条","txt":"通过禁毒国际合作破获毒品犯罪案件的，中华人民共和国政府可以与有关国家分享查获的非法所得、由非法所得获得的收益以及供毒品犯罪使用的财物或者财物变卖所得的款项。"},{"i":58,"n":"第五十八条","txt":"国务院有关部门根据国务院授权，可以通过对外援助等渠道，支持有关国家实施毒品原植物替代种植、发展替代产业。"},{"i":59,"n":"第五十九条","txt":"有下列行为之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予治安管理处罚："},{"i":60,"n":"第六十条","txt":"有下列行为之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予治安管理处罚："},{"i":61,"n":"第六十一条","txt":"容留他人吸食、注射毒品或者介绍买卖毒品，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由公安机关处十日以上十五日以下拘留，可以并处三千元以下罚款；情节较轻的，处五日以下拘留或者五百元以下罚款。"},{"i":62,"n":"第六十二条","txt":"吸食、注射毒品的，依法给予治安管理处罚。吸毒人员主动到公安机关登记或者到有资质的医疗机构接受戒毒治疗的，不予处罚。"},{"i":63,"n":"第六十三条","txt":"在麻醉药品、精神药品的实验研究、生产、经营、使用、储存、运输、进口、出口以及麻醉药品药用原植物种植活动中，违反国家规定，致使麻醉药品、精神药品或者麻醉药品药用原植物流入非法渠道，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依照有关法律、行政法规的规定给予处罚。"},{"i":64,"n":"第六十四条","txt":"在易制毒化学品的生产、经营、购买、运输或者进口、出口活动中，违反国家规定，致使易制毒化学品流入非法渠道，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依照有关法律、行政法规的规定给予处罚。"},{"i":65,"n":"第六十五条","txt":"娱乐场所及其从业人员实施毒品违法犯罪行为，或者为进入娱乐场所的人员实施毒品违法犯罪行为提供条件，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依照有关法律、行政法规的规定给予处罚。"},{"i":66,"n":"第六十六条","txt":"未经批准，擅自从事戒毒治疗业务的，由卫生行政部门责令停止违法业务活动，没收违法所得和使用的药品、医疗器械等物品；构成犯罪的，依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"戒毒医疗机构发现接受戒毒治疗的戒毒人员在治疗期间吸食、注射毒品，不向公安机关报告的，由卫生行政部门责令改正；情节严重的，责令停业整顿。"},{"i":68,"n":"第六十八条","txt":"强制隔离戒毒场所、医疗机构、医师违反规定使用麻醉药品、精神药品，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依照有关法律、行政法规的规定给予处罚。"},{"i":69,"n":"第六十九条","txt":"公安机关、司法行政部门或者其他有关主管部门的工作人员在禁毒工作中有下列行为之一，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分："},{"i":70,"n":"第七十条","txt":"有关单位及其工作人员在入学、就业、享受社会保障等方面歧视戒毒人员的，由教育行政部门、劳动行政部门责令改正；给当事人造成损失的，依法承担赔偿责任。"},{"i":71,"n":"第七十一条","txt":"本法自2008年6月1日起施行。《全国人民代表大会常务委员会关于禁毒的决定》同时废止。"}],"kexuejishujinbufa":[{"i":1,"n":"第一条","txt":"为了全面促进科学技术进步，发挥科学技术第一生产力、创新第一动力、人才第一资源的作用，促进科技成果向现实生产力转化，推动科技创新支撑和引领经济社会发展，全面建设社会主义现代化国家，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"坚持中国共产党对科学技术事业的全面领导。"},{"i":3,"n":"第三条","txt":"科学技术进步工作应当面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康，为促进经济社会发展、维护国家安全和推动人类可持续发展服务。"},{"i":4,"n":"第四条","txt":"国家完善高效、协同、开放的国家创新体系，统筹科技创新与制度创新，健全社会主义市场经济条件下新型举国体制，充分发挥市场配置创新资源的决定性作用，更好发挥政府作用，优化科技资源配置，提高资源利用效率，促进各类创新主体紧密合作、创新要素有序流动、创新生态持续优化，提升体系化能力和重点突破能力，增强创新体系整体效能。"},{"i":5,"n":"第五条","txt":"国家统筹发展和安全，提高科技安全治理能力，健全预防和化解科技安全风险的制度机制，加强科学技术研究、开发与应用活动的安全管理，支持国家安全领域科技创新，增强科技创新支撑国家安全的能力和水平。"},{"i":6,"n":"第六条","txt":"国家鼓励科学技术研究开发与高等教育、产业发展相结合，鼓励学科交叉融合和相互促进。"},{"i":7,"n":"第七条","txt":"国家遵循科学技术活动服务国家目标与鼓励自由探索相结合的原则，超前部署重大基础研究、有重大产业应用前景的前沿技术研究和社会公益性技术研究，支持基础研究、前沿技术研究和社会公益性技术研究持续、稳定发展，加强原始创新和关键核心技术攻关，加快实现高水平科技自立自强。"},{"i":8,"n":"第八条","txt":"国家保障开展科学技术研究开发的自由，鼓励科学探索和技术创新，保护科学技术人员自由探索等合法权益。"},{"i":9,"n":"第九条","txt":"学校及其他教育机构应当坚持理论联系实际，注重培养受教育者的独立思考能力、实践能力、创新能力和批判性思维，以及追求真理、崇尚创新、实事求是的科学精神。"},{"i":10,"n":"第十条","txt":"科学技术人员是社会主义现代化建设事业的重要人才力量，应当受到全社会的尊重。"},{"i":11,"n":"第十一条","txt":"国家营造有利于科技创新的社会环境，鼓励机关、群团组织、企业事业单位、社会组织和公民参与和支持科学技术进步活动。"},{"i":12,"n":"第十二条","txt":"国家发展科学技术普及事业，普及科学技术知识，加强科学技术普及基础设施和能力建设，提高全体公民特别是青少年的科学文化素质。"},{"i":13,"n":"第十三条","txt":"国家制定和实施知识产权战略，建立和完善知识产权制度，营造尊重知识产权的社会环境，保护知识产权，激励自主创新。"},{"i":14,"n":"第十四条","txt":"国家建立和完善有利于创新的科学技术评价制度。"},{"i":15,"n":"第十五条","txt":"国务院领导全国科学技术进步工作，制定中长期科学和技术发展规划、科技创新规划，确定国家科学技术重大项目、与科学技术密切相关的重大项目。中长期科学和技术发展规划、科技创新规划应当明确指导方针，发挥战略导向作用，引导和统筹科技发展布局、资源配置和政策制定。"},{"i":16,"n":"第十六条","txt":"国务院科学技术行政部门负责全国科学技术进步工作的宏观管理、统筹协调、服务保障和监督实施；国务院其他有关部门在各自的职责范围内，负责有关的科学技术进步工作。"},{"i":17,"n":"第十七条","txt":"国家建立科学技术进步工作协调机制，研究科学技术进步工作中的重大问题，协调国家科学技术计划项目的设立及相互衔接，协调科学技术资源配置、科学技术研究开发机构的整合以及科学技术研究开发与高等教育、产业发展相结合等重大事项。"},{"i":18,"n":"第十八条","txt":"每年5月30日为全国科技工作者日。"},{"i":19,"n":"第十九条","txt":"国家加强基础研究能力建设，尊重科学发展规律和人才成长规律，强化项目、人才、基地系统布局，为基础研究发展提供良好的物质条件和有力的制度保障。"},{"i":20,"n":"第二十条","txt":"国家财政建立稳定支持基础研究的投入机制。"},{"i":21,"n":"第二十一条","txt":"国家设立自然科学基金，资助基础研究，支持人才培养和团队建设。确定国家自然科学基金资助项目，应当坚持宏观引导、自主申请、平等竞争、同行评审、择优支持的原则。"},{"i":22,"n":"第二十二条","txt":"国家完善学科布局和知识体系建设，推进学科交叉融合，促进基础研究与应用研究协调发展。"},{"i":23,"n":"第二十三条","txt":"国家加大基础研究人才培养力度，强化对基础研究人才的稳定支持，提高基础研究人才队伍质量和水平。"},{"i":24,"n":"第二十四条","txt":"国家强化基础研究基地建设。"},{"i":25,"n":"第二十五条","txt":"国家支持高等学校加强基础学科建设和基础研究人才培养，增强基础研究自主布局能力，推动高等学校基础研究高质量发展。"},{"i":26,"n":"第二十六条","txt":"国家鼓励以应用研究带动基础研究，促进基础研究与应用研究、成果转化融通发展。"},{"i":27,"n":"第二十七条","txt":"国家建立和完善科研攻关协调机制，围绕经济社会发展、国家安全重大需求和人民生命健康，加强重点领域项目、人才、基地、资金一体化配置，推动产学研紧密合作，推动关键核心技术自主可控。"},{"i":28,"n":"第二十八条","txt":"国家完善关键核心技术攻关举国体制，组织实施体现国家战略需求的科学技术重大任务，系统布局具有前瞻性、战略性的科学技术重大项目，超前部署关键核心技术研发。"},{"i":29,"n":"第二十九条","txt":"国家加强面向产业发展需求的共性技术平台和科学技术研究开发机构建设，鼓励地方围绕发展需求建设应用研究科学技术研究开发机构。"},{"i":30,"n":"第三十条","txt":"国家加强科技成果中试、工程化和产业化开发及应用，加快科技成果转化为现实生产力。"},{"i":31,"n":"第三十一条","txt":"国家鼓励企业、科学技术研究开发机构、高等学校和其他组织建立优势互补、分工明确、成果共享、风险共担的合作机制，按照市场机制联合组建研究开发平台、技术创新联盟、创新联合体等，协同推进研究开发与科技成果转化，提高科技成果转移转化成效。"},{"i":32,"n":"第三十二条","txt":"利用财政性资金设立的科学技术计划项目所形成的科技成果，在不损害国家安全、国家利益和重大社会公共利益的前提下，授权项目承担者依法取得相关知识产权，项目承担者可以依法自行投资实施转化、向他人转让、联合他人共同实施转化、许可他人使用或者作价投资等。"},{"i":33,"n":"第三十三条","txt":"国家实行以增加知识价值为导向的分配政策，按照国家有关规定推进知识产权归属和权益分配机制改革，探索赋予科学技术人员职务科技成果所有权或者长期使用权制度。"},{"i":34,"n":"第三十四条","txt":"国家鼓励利用财政性资金设立的科学技术计划项目所形成的知识产权首先在境内使用。"},{"i":35,"n":"第三十五条","txt":"国家鼓励新技术应用，按照包容审慎原则，推动开展新技术、新产品、新服务、新模式应用试验，为新技术、新产品应用创造条件。"},{"i":36,"n":"第三十六条","txt":"国家鼓励和支持农业科学技术的应用研究，传播和普及农业科学技术知识，加快农业科技成果转化和产业化，促进农业科学技术进步，利用农业科学技术引领乡村振兴和农业农村现代化。"},{"i":37,"n":"第三十七条","txt":"国家推动科学技术研究开发与产品、服务标准制定相结合，科学技术研究开发与产品设计、制造相结合；引导科学技术研究开发机构、高等学校、企业和社会组织共同推进国家重大技术创新产品、服务标准的研究、制定和依法采用，参与国际标准制定。"},{"i":38,"n":"第三十八条","txt":"国家培育和发展统一开放、互联互通、竞争有序的技术市场，鼓励创办从事技术评估、技术经纪和创新创业服务等活动的中介服务机构，引导建立社会化、专业化、网络化、信息化和智能化的技术交易服务体系和创新创业服务体系，推动科技成果的应用和推广。"},{"i":39,"n":"第三十九条","txt":"国家建立以企业为主体，以市场为导向，企业同科学技术研究开发机构、高等学校紧密合作的技术创新体系，引导和扶持企业技术创新活动，支持企业牵头国家科技攻关任务，发挥企业在技术创新中的主体作用，推动企业成为技术创新决策、科研投入、组织科研和成果转化的主体，促进各类创新要素向企业集聚，提高企业技术创新能力。"},{"i":40,"n":"第四十条","txt":"国家鼓励企业开展下列活动："},{"i":41,"n":"第四十一条","txt":"国家鼓励企业加强原始创新，开展技术合作与交流，增加研究开发和技术创新的投入，自主确立研究开发课题，开展技术创新活动。"},{"i":42,"n":"第四十二条","txt":"国家完善多层次资本市场，建立健全促进科技创新的机制，支持符合条件的科技型企业利用资本市场推动自身发展。"},{"i":43,"n":"第四十三条","txt":"下列企业按照国家有关规定享受税收优惠："},{"i":44,"n":"第四十四条","txt":"国家对公共研究开发平台和科学技术中介、创新创业服务机构的建设和运营给予支持。"},{"i":45,"n":"第四十五条","txt":"国家保护企业研究开发所取得的知识产权。企业应当不断提高知识产权质量和效益，增强自主创新能力和市场竞争能力。"},{"i":46,"n":"第四十六条","txt":"国有企业应当建立健全有利于技术创新的研究开发投入制度、分配制度和考核评价制度，完善激励约束机制。"},{"i":47,"n":"第四十七条","txt":"县级以上地方人民政府及其有关部门应当创造公平竞争的市场环境，推动企业技术进步。"},{"i":48,"n":"第四十八条","txt":"国家统筹规划科学技术研究开发机构布局，建立和完善科学技术研究开发体系。"},{"i":49,"n":"第四十九条","txt":"自然人、法人和非法人组织有权依法设立科学技术研究开发机构。境外的组织或者个人可以在中国境内依法独立设立科学技术研究开发机构，也可以与中国境内的组织或者个人联合设立科学技术研究开发机构。"},{"i":50,"n":"第五十条","txt":"科学技术研究开发机构享有下列权利："},{"i":51,"n":"第五十一条","txt":"科学技术研究开发机构应当依法制定章程，按照章程规定的职能定位和业务范围开展科学技术研究开发活动；加强科研作风学风建设，建立和完善科研诚信、科技伦理管理制度，遵守科学研究活动管理规范；不得组织、参加、支持迷信活动。"},{"i":52,"n":"第五十二条","txt":"利用财政性资金设立的科学技术研究开发机构，应当建立职责明确、评价科学、开放有序、管理规范的现代院所制度，实行院长或者所长负责制，建立科学技术委员会咨询制和职工代表大会监督制等制度，并吸收外部专家参与管理、接受社会监督；院长或者所长的聘用引入竞争机制。"},{"i":53,"n":"第五十三条","txt":"国家完善利用财政性资金设立的科学技术研究开发机构的评估制度，评估结果作为机构设立、支持、调整、终止的依据。"},{"i":54,"n":"第五十四条","txt":"利用财政性资金设立的科学技术研究开发机构，应当建立健全科学技术资源开放共享机制，促进科学技术资源的有效利用。"},{"i":55,"n":"第五十五条","txt":"国家鼓励企业和其他社会力量自行创办科学技术研究开发机构，保障其合法权益。"},{"i":56,"n":"第五十六条","txt":"国家支持发展新型研究开发机构等新型创新主体，完善投入主体多元化、管理制度现代化、运行机制市场化、用人机制灵活化的发展模式，引导新型创新主体聚焦科学研究、技术创新和研发服务。"},{"i":57,"n":"第五十七条","txt":"国家营造尊重人才、爱护人才的社会环境，公正平等、竞争择优的制度环境，待遇适当、保障有力的生活环境，为科学技术人员潜心科研创造良好条件。"},{"i":58,"n":"第五十八条","txt":"国家加快战略人才力量建设，优化科学技术人才队伍结构，完善战略科学家、科技领军人才等创新人才和团队的培养、发现、引进、使用、评价机制，实施人才梯队、科研条件、管理机制等配套政策。"},{"i":59,"n":"第五十九条","txt":"国家完善创新人才教育培养机制，在基础教育中加强科学兴趣培养，在职业教育中加强技术技能人才培养，强化高等教育资源配置与科学技术领域创新人才培养的结合，加强完善战略性科学技术人才储备。"},{"i":60,"n":"第六十条","txt":"各级人民政府、企业事业单位和社会组织应当采取措施，完善体现知识、技术等创新要素价值的收益分配机制，优化收入结构，建立工资稳定增长机制，提高科学技术人员的工资水平；对有突出贡献的科学技术人员给予优厚待遇和荣誉激励。"},{"i":61,"n":"第六十一条","txt":"各级人民政府和企业事业单位应当保障科学技术人员接受继续教育的权利，并为科学技术人员的合理、畅通、有序流动创造环境和条件，发挥其专长。"},{"i":62,"n":"第六十二条","txt":"科学技术人员可以根据其学术水平和业务能力选择工作单位、竞聘相应的岗位，取得相应的职务或者职称。"},{"i":63,"n":"第六十三条","txt":"国家实行科学技术人员分类评价制度，对从事不同科学技术活动的人员实行不同的评价标准和方式，突出创新价值、能力、贡献导向，合理确定薪酬待遇、配置学术资源、设置评价周期，形成有利于科学技术人员潜心研究和创新的人才评价体系，激发科学技术人员创新活力。"},{"i":64,"n":"第六十四条","txt":"科学技术行政等有关部门和企业事业单位应当完善科学技术人员管理制度，增强服务意识和保障能力，简化管理流程，避免重复性检查和评估，减轻科学技术人员项目申报、材料报送、经费报销等方面的负担，保障科学技术人员科研时间。"},{"i":65,"n":"第六十五条","txt":"科学技术人员在艰苦、边远地区或者恶劣、危险环境中工作，所在单位应当按照国家有关规定给予补贴，提供其岗位或者工作场所应有的职业健康卫生保护和安全保障，为其接受继续教育、业务培训等提供便利条件。"},{"i":66,"n":"第六十六条","txt":"青年科学技术人员、少数民族科学技术人员、女性科学技术人员等在竞聘专业技术职务、参与科学技术评价、承担科学技术研究开发项目、接受继续教育等方面享有平等权利。鼓励老年科学技术人员在科学技术进步中发挥积极作用。"},{"i":67,"n":"第六十七条","txt":"科学技术人员应当大力弘扬爱国、创新、求实、奉献、协同、育人的科学家精神，坚守工匠精神，在各类科学技术活动中遵守学术和伦理规范，恪守职业道德，诚实守信；不得在科学技术活动中弄虚作假，不得参加、支持迷信活动。"},{"i":68,"n":"第六十八条","txt":"国家鼓励科学技术人员自由探索、勇于承担风险，营造鼓励创新、宽容失败的良好氛围。原始记录等能够证明承担探索性强、风险高的科学技术研究开发项目的科学技术人员已经履行了勤勉尽责义务仍不能完成该项目的，予以免责。"},{"i":69,"n":"第六十九条","txt":"科研诚信记录作为对科学技术人员聘任专业技术职务或者职称、审批科学技术人员申请科学技术研究开发项目、授予科学技术奖励等的重要依据。"},{"i":70,"n":"第七十条","txt":"科学技术人员有依法创办或者参加科学技术社会团体的权利。"},{"i":71,"n":"第七十一条","txt":"国家统筹科学技术资源区域空间布局，推动中央科学技术资源与地方发展需求紧密衔接，采取多种方式支持区域科技创新。"},{"i":72,"n":"第七十二条","txt":"县级以上地方人民政府应当支持科学技术研究和应用，为促进科技成果转化创造条件，为推动区域创新发展提供良好的创新环境。"},{"i":73,"n":"第七十三条","txt":"县级以上人民政府及其有关部门制定的与产业发展相关的科学技术计划，应当体现产业发展的需求。"},{"i":74,"n":"第七十四条","txt":"国务院可以根据需要批准建立国家高新技术产业开发区、国家自主创新示范区等科技园区，并对科技园区的建设、发展给予引导和扶持，使其形成特色和优势，发挥集聚和示范带动效应。"},{"i":75,"n":"第七十五条","txt":"国家鼓励有条件的县级以上地方人民政府根据国家发展战略和地方发展需要，建设重大科技创新基地与平台，培育创新创业载体，打造区域科技创新高地。"},{"i":76,"n":"第七十六条","txt":"国家建立区域科技创新合作机制和协同互助机制，鼓励地方各级人民政府及其有关部门开展跨区域创新合作，促进各类创新要素合理流动和高效集聚。"},{"i":77,"n":"第七十七条","txt":"国家重大战略区域可以依托区域创新平台，构建利益分享机制，促进人才、技术、资金等要素自由流动，推动科学仪器设备、科技基础设施、科学工程和科技信息资源等开放共享，提高科技成果区域转化效率。"},{"i":78,"n":"第七十八条","txt":"国家鼓励地方积极探索区域科技创新模式，尊重区域科技创新集聚规律，因地制宜选择具有区域特色的科技创新发展路径。"},{"i":79,"n":"第七十九条","txt":"国家促进开放包容、互惠共享的国际科学技术合作与交流，支撑构建人类命运共同体。"},{"i":80,"n":"第八十条","txt":"中华人民共和国政府发展同外国政府、国际组织之间的科学技术合作与交流。"},{"i":81,"n":"第八十一条","txt":"国家鼓励企业事业单位、社会组织通过多种途径建设国际科技创新合作平台，提供国际科技创新合作服务。"},{"i":82,"n":"第八十二条","txt":"国家采取多种方式支持国内外优秀科学技术人才合作研发，应对人类面临的共同挑战，探索科学前沿。"},{"i":83,"n":"第八十三条","txt":"国家扩大科学技术计划对外开放合作，鼓励在华外资企业、外籍科学技术人员等承担和参与科学技术计划项目，完善境外科学技术人员参与国家科学技术计划项目的机制。"},{"i":84,"n":"第八十四条","txt":"国家完善相关社会服务和保障措施，鼓励在国外工作的科学技术人员回国，吸引外籍科学技术人员到中国从事科学技术研究开发工作。"},{"i":85,"n":"第八十五条","txt":"国家加大财政性资金投入，并制定产业、金融、税收、政府采购等政策，鼓励、引导社会资金投入，推动全社会科学技术研究开发经费持续稳定增长。"},{"i":86,"n":"第八十六条","txt":"国家逐步提高科学技术经费投入的总体水平；国家财政用于科学技术经费的增长幅度，应当高于国家财政经常性收入的增长幅度。全社会科学技术研究开发经费应当占国内生产总值适当的比例，并逐步提高。"},{"i":87,"n":"第八十七条","txt":"财政性科学技术资金应当主要用于下列事项的投入："},{"i":88,"n":"第八十八条","txt":"设立国家科学技术计划，应当按照国家需求，聚焦国家重大战略任务，遵循科学研究、技术创新和成果转化规律。"},{"i":89,"n":"第八十九条","txt":"国家设立基金，资助中小企业开展技术创新，推动科技成果转化与应用。"},{"i":90,"n":"第九十条","txt":"从事下列活动的，按照国家有关规定享受税收优惠："},{"i":91,"n":"第九十一条","txt":"对境内自然人、法人和非法人组织的科技创新产品、服务，在功能、质量等指标能够满足政府采购需求的条件下，政府采购应当购买；首次投放市场的，政府采购应当率先购买，不得以商业业绩为由予以限制。"},{"i":92,"n":"第九十二条","txt":"国家鼓励金融机构开展知识产权质押融资业务，鼓励和引导金融机构在信贷、投资等方面支持科学技术应用和高新技术产业发展，鼓励保险机构根据高新技术产业发展的需要开发保险品种，促进新技术应用。"},{"i":93,"n":"第九十三条","txt":"国家遵循统筹规划、优化配置的原则，整合和设置国家科学技术研究实验基地。"},{"i":94,"n":"第九十四条","txt":"国家根据科学技术进步的需要，按照统筹规划、突出共享、优化配置、综合集成、政府主导、多方共建的原则，统筹购置大型科学仪器、设备，并开展对以财政性资金为主购置的大型科学仪器、设备的联合评议工作。"},{"i":95,"n":"第九十五条","txt":"国家加强学术期刊建设，完善科研论文和科学技术信息交流机制，推动开放科学的发展，促进科学技术交流和传播。"},{"i":96,"n":"第九十六条","txt":"国家鼓励国内外的组织或者个人捐赠财产、设立科学技术基金，资助科学技术研究开发和科学技术普及。"},{"i":97,"n":"第九十七条","txt":"利用财政性资金设立的科学技术研究开发机构、高等学校和企业，在推进科技管理改革、开展科学技术研究开发、实施科技成果转化活动过程中，相关负责人锐意创新探索，出现决策失误、偏差，但尽到合理注意义务和监督管理职责，未牟取非法利益的，免除其决策责任。"},{"i":98,"n":"第九十八条","txt":"国家加强科技法治化建设和科研作风学风建设，建立和完善科研诚信制度和科技监督体系，健全科技伦理治理体制，营造良好科技创新环境。"},{"i":99,"n":"第九十九条","txt":"国家完善科学技术决策的规则和程序，建立规范的咨询和决策机制，推进决策的科学化、民主化和法治化。"},{"i":100,"n":"第一百条","txt":"国家加强财政性科学技术资金绩效管理，提高资金配置效率和使用效益。财政性科学技术资金的管理和使用情况，应当接受审计机关、财政部门的监督检查。"},{"i":101,"n":"第一百零一条","txt":"国家建立科学技术计划项目分类管理机制，强化对项目实效的考核评价。利用财政性资金设立的科学技术计划项目，应当坚持问题导向、目标导向、需求导向进行立项，按照国家有关规定择优确定项目承担者。"},{"i":102,"n":"第一百零二条","txt":"国务院科学技术行政部门应当会同国务院有关主管部门，建立科学技术研究基地、科学仪器设备等资产和科学技术文献、科学技术数据、科学技术自然资源、科学技术普及资源等科学技术资源的信息系统和资源库，及时向社会公布科学技术资源的分布、使用情况。"},{"i":103,"n":"第一百零三条","txt":"国家建立科技伦理委员会，完善科技伦理制度规范，加强科技伦理教育和研究，健全审查、评估、监管体系。"},{"i":104,"n":"第一百零四条","txt":"国家加强科研诚信建设，建立科学技术项目诚信档案及科研诚信管理信息系统，坚持预防与惩治并举、自律与监督并重，完善对失信行为的预防、调查、处理机制。"},{"i":105,"n":"第一百零五条","txt":"国家建立健全科学技术统计调查制度和国家创新调查制度，掌握国家科学技术活动基本情况，监测和评价国家创新能力。"},{"i":106,"n":"第一百零六条","txt":"国家实行科学技术保密制度，加强科学技术保密能力建设，保护涉及国家安全和利益的科学技术秘密。"},{"i":107,"n":"第一百零七条","txt":"禁止危害国家安全、损害社会公共利益、危害人体健康、违背科研诚信和科技伦理的科学技术研究开发和应用活动。"},{"i":108,"n":"第一百零八条","txt":"违反本法规定，科学技术行政等有关部门及其工作人员，以及其他依法履行公职的人员滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":109,"n":"第一百零九条","txt":"违反本法规定，滥用职权阻挠、限制、压制科学技术研究开发活动，或者利用职权打压、排挤、刁难科学技术人员的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":110,"n":"第一百一十条","txt":"违反本法规定，虚报、冒领、贪污、挪用、截留用于科学技术进步的财政性资金或者社会捐赠资金的，由有关主管部门责令改正，追回有关财政性资金，责令退还捐赠资金，给予警告或者通报批评，并可以暂停拨款，终止或者撤销相关科学技术活动；情节严重的，依法处以罚款，禁止一定期限内承担或者参与财政性资金支持的科学技术活动；对直接负责的主管人员和其他直接责任人员依法给予行政处罚和处分。"},{"i":111,"n":"第一百一十一条","txt":"违反本法规定，利用财政性资金和国有资本购置大型科学仪器、设备后，不履行大型科学仪器、设备等科学技术资源共享使用义务的，由有关主管部门责令改正，给予警告或者通报批评，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":112,"n":"第一百一十二条","txt":"违反本法规定，进行危害国家安全、损害社会公共利益、危害人体健康、违背科研诚信和科技伦理的科学技术研究开发和应用活动的，由科学技术人员所在单位或者有关主管部门责令改正；获得用于科学技术进步的财政性资金或者有违法所得的，由有关主管部门终止或者撤销相关科学技术活动，追回财政性资金，没收违法所得；情节严重的，由有关主管部门向社会公布其违法行为，依法给予行政处罚和处分，禁止一定期限内承担或者参与财政性资金支持的科学技术活动、申请相关科学技术活动行政许可；对直接负责的主管人员和其他直接责任人员依法给予行政处罚和处分。"},{"i":113,"n":"第一百一十三条","txt":"违反本法规定，从事科学技术活动违反科学技术活动管理规范的，由有关主管部门责令限期改正，并可以追回有关财政性资金，给予警告或者通报批评，暂停拨款、终止或者撤销相关财政性资金支持的科学技术活动；情节严重的，禁止一定期限内承担或者参与财政性资金支持的科学技术活动，取消一定期限内财政性资金支持的科学技术活动管理资格；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":114,"n":"第一百一十四条","txt":"违反本法规定，骗取国家科学技术奖励的，由主管部门依法撤销奖励，追回奖章、证书和奖金等，并依法给予处分。"},{"i":115,"n":"第一百一十五条","txt":"违反本法规定的行为，本法未作行政处罚规定，其他有关法律、行政法规有规定的，依照其规定；造成财产损失或者其他损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":116,"n":"第一百一十六条","txt":"涉及国防科学技术进步的其他有关事项，由国务院、中央军事委员会规定。"},{"i":117,"n":"第一百一十七条","txt":"本法自2022年1月1日起施行。"}],"tufashijianyingduifa":[{"i":1,"n":"第一条","txt":"为了预防和减少突发事件的发生，控制、减轻和消除突发事件引起的严重社会危害，提高突发事件预防和应对能力，规范突发事件应对活动，保护人民生命财产安全，维护国家安全、公共安全、生态环境安全和社会秩序，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称突发事件，是指突然发生，造成或者可能造成严重社会危害，需要采取应急处置措施予以应对的自然灾害、事故灾难、公共卫生事件和社会安全事件。"},{"i":3,"n":"第三条","txt":"按照社会危害程度、影响范围等因素，突发自然灾害、事故灾难、公共卫生事件分为特别重大、重大、较大和一般四级。法律、行政法规或者国务院另有规定的，从其规定。"},{"i":4,"n":"第四条","txt":"突发事件应对工作坚持中国共产党的领导，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，建立健全集中统一、高效权威的中国特色突发事件应对工作领导体制，完善党委领导、政府负责、部门联动、军地联合、社会协同、公众参与、科技支撑、法治保障的治理体系。"},{"i":5,"n":"第五条","txt":"突发事件应对工作应当坚持总体国家安全观，统筹发展与安全；坚持人民至上、生命至上；坚持依法科学应对，尊重和保障人权；坚持预防为主、预防与应急相结合。"},{"i":6,"n":"第六条","txt":"国家建立有效的社会动员机制，组织动员企业事业单位、社会组织、志愿者等各方力量依法有序参与突发事件应对工作，增强全民的公共安全和防范风险的意识，提高全社会的避险救助能力。"},{"i":7,"n":"第七条","txt":"国家建立健全突发事件信息发布制度。有关人民政府和部门应当及时向社会公布突发事件相关信息和有关突发事件应对的决定、命令、措施等信息。"},{"i":8,"n":"第八条","txt":"国家建立健全突发事件新闻采访报道制度。有关人民政府和部门应当做好新闻媒体服务引导工作，支持新闻媒体开展采访报道和舆论监督。"},{"i":9,"n":"第九条","txt":"国家建立突发事件应对工作投诉、举报制度，公布统一的投诉、举报方式。"},{"i":10,"n":"第十条","txt":"突发事件应对措施应当与突发事件可能造成的社会危害的性质、程度和范围相适应；有多种措施可供选择的，应当选择有利于最大程度地保护公民、法人和其他组织权益，且对他人权益损害和生态环境影响较小的措施，并根据情况变化及时调整，做到科学、精准、有效。"},{"i":11,"n":"第十一条","txt":"国家在突发事件应对工作中，应当对未成年人、老年人、残疾人、孕产期和哺乳期的妇女、需要及时就医的伤病人员等群体给予特殊、优先保护。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府及其部门为应对突发事件的紧急需要，可以征用单位和个人的设备、设施、场地、交通工具等财产。被征用的财产在使用完毕或者突发事件应急处置工作结束后，应当及时返还。财产被征用或者征用后毁损、灭失的，应当给予公平、合理的补偿。"},{"i":13,"n":"第十三条","txt":"因依法采取突发事件应对措施，致使诉讼、监察调查、行政复议、仲裁、国家赔偿等活动不能正常进行的，适用有关时效中止和程序中止的规定，法律另有规定的除外。"},{"i":14,"n":"第十四条","txt":"中华人民共和国政府在突发事件的预防与应急准备、监测与预警、应急处置与救援、事后恢复与重建等方面，同外国政府和有关国际组织开展合作与交流。"},{"i":15,"n":"第十五条","txt":"对在突发事件应对工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":16,"n":"第十六条","txt":"国家建立统一指挥、专常兼备、反应灵敏、上下联动的应急管理体制和综合协调、分类管理、分级负责、属地管理为主的工作体系。"},{"i":17,"n":"第十七条","txt":"县级人民政府对本行政区域内突发事件的应对管理工作负责。突发事件发生后，发生地县级人民政府应当立即采取措施控制事态发展，组织开展应急救援和处置工作，并立即向上一级人民政府报告，必要时可以越级上报，具备条件的，应当进行网络直报或者自动速报。"},{"i":18,"n":"第十八条","txt":"突发事件涉及两个以上行政区域的，其应对管理工作由有关行政区域共同的上一级人民政府负责，或者由各有关行政区域的上一级人民政府共同负责。共同负责的人民政府应当按照国家有关规定，建立信息共享和协调配合机制。根据共同应对突发事件的需要，地方人民政府之间可以建立协同应对机制。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府是突发事件应对管理工作的行政领导机关。"},{"i":20,"n":"第二十条","txt":"突发事件应急指挥机构在突发事件应对过程中可以依法发布有关突发事件应对的决定、命令、措施。突发事件应急指挥机构发布的决定、命令、措施与设立它的人民政府发布的决定、命令、措施具有同等效力，法律责任由设立它的人民政府承担。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府应急管理部门和卫生健康、公安等有关部门应当在各自职责范围内做好有关突发事件应对管理工作，并指导、协助下级人民政府及其相应部门做好有关突发事件的应对管理工作。"},{"i":22,"n":"第二十二条","txt":"乡级人民政府、街道办事处应当明确专门工作力量，负责突发事件应对有关工作。"},{"i":23,"n":"第二十三条","txt":"公民、法人和其他组织有义务参与突发事件应对工作。"},{"i":24,"n":"第二十四条","txt":"中国人民解放军、中国人民武装警察部队和民兵组织依照本法和其他有关法律、行政法规、军事法规的规定以及国务院、中央军事委员会的命令，参加突发事件的应急救援和处置工作。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府及其设立的突发事件应急指挥机构发布的有关突发事件应对的决定、命令、措施，应当及时报本级人民代表大会常务委员会备案；突发事件应急处置工作结束后，应当向本级人民代表大会常务委员会作出专项工作报告。"},{"i":26,"n":"第二十六条","txt":"国家建立健全突发事件应急预案体系。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府应急管理部门指导突发事件应急预案体系建设，综合协调应急预案衔接工作，增强有关应急预案的衔接性和实效性。"},{"i":28,"n":"第二十八条","txt":"应急预案应当根据本法和其他有关法律、法规的规定，针对突发事件的性质、特点和可能造成的社会危害，具体规定突发事件应对管理工作的组织指挥体系与职责和突发事件的预防与预警机制、处置程序、应急保障措施以及事后恢复与重建措施等内容。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府应当将突发事件应对工作纳入国民经济和社会发展规划。县级以上人民政府有关部门应当制定突发事件应急体系建设规划。"},{"i":30,"n":"第三十条","txt":"国土空间规划等规划应当符合预防、处置突发事件的需要，统筹安排突发事件应对工作所必需的设备和基础设施建设，合理确定应急避难、封闭隔离、紧急医疗救治等场所，实现日常使用和应急使用的相互转换。"},{"i":31,"n":"第三十一条","txt":"国务院应急管理部门会同卫生健康、自然资源、住房城乡建设等部门统筹、指导全国应急避难场所的建设和管理工作，建立健全应急避难场所标准体系。县级以上地方人民政府负责本行政区域内应急避难场所的规划、建设和管理工作。"},{"i":32,"n":"第三十二条","txt":"国家建立健全突发事件风险评估体系，对可能发生的突发事件进行综合性评估，有针对性地采取有效防范措施，减少突发事件的发生，最大限度减轻突发事件的影响。"},{"i":33,"n":"第三十三条","txt":"县级人民政府应当对本行政区域内容易引发自然灾害、事故灾难和公共卫生事件的危险源、危险区域进行调查、登记、风险评估，定期进行检查、监控，并责令有关单位采取安全防范措施。"},{"i":34,"n":"第三十四条","txt":"县级人民政府及其有关部门、乡级人民政府、街道办事处、居民委员会、村民委员会应当及时调解处理可能引发社会安全事件的矛盾纠纷。"},{"i":35,"n":"第三十五条","txt":"所有单位应当建立健全安全管理制度，定期开展危险源辨识评估，制定安全防范措施；定期检查本单位各项安全防范措施的落实情况，及时消除事故隐患；掌握并及时处理本单位存在的可能引发社会安全事件的问题，防止矛盾激化和事态扩大；对本单位可能发生的突发事件和采取安全防范措施的情况，应当按照规定及时向所在地人民政府或者有关部门报告。"},{"i":36,"n":"第三十六条","txt":"矿山、金属冶炼、建筑施工单位和易燃易爆物品、危险化学品、放射性物品等危险物品的生产、经营、运输、储存、使用单位，应当制定具体应急预案，配备必要的应急救援器材、设备和物资，并对生产经营场所、有危险物品的建筑物、构筑物及周边环境开展隐患排查，及时采取措施管控风险和消除隐患，防止发生突发事件。"},{"i":37,"n":"第三十七条","txt":"公共交通工具、公共场所和其他人员密集场所的经营单位或者管理单位应当制定具体应急预案，为交通工具和有关场所配备报警装置和必要的应急救援设备、设施，注明其使用方法，并显著标明安全撤离的通道、路线，保证安全通道、出口的畅通。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府应当建立健全突发事件应对管理培训制度，对人民政府及其有关部门负有突发事件应对管理职责的工作人员以及居民委员会、村民委员会有关人员定期进行培训。"},{"i":39,"n":"第三十九条","txt":"国家综合性消防救援队伍是应急救援的综合性常备骨干力量，按照国家有关规定执行综合应急救援任务。县级以上人民政府有关部门可以根据实际需要设立专业应急救援队伍。"},{"i":40,"n":"第四十条","txt":"地方各级人民政府、县级以上人民政府有关部门、有关单位应当为其组建的应急救援队伍购买人身意外伤害保险，配备必要的防护装备和器材，防范和减少应急救援人员的人身伤害风险。"},{"i":41,"n":"第四十一条","txt":"中国人民解放军、中国人民武装警察部队和民兵组织应当有计划地组织开展应急救援的专门训练。"},{"i":42,"n":"第四十二条","txt":"县级人民政府及其有关部门、乡级人民政府、街道办事处应当组织开展面向社会公众的应急知识宣传普及活动和必要的应急演练。"},{"i":43,"n":"第四十三条","txt":"各级各类学校应当把应急教育纳入教育教学计划，对学生及教职工开展应急知识教育和应急演练，培养安全意识，提高自救与互救能力。"},{"i":44,"n":"第四十四条","txt":"各级人民政府应当将突发事件应对工作所需经费纳入本级预算，并加强资金管理，提高资金使用绩效。"},{"i":45,"n":"第四十五条","txt":"国家按照集中管理、统一调拨、平时服务、灾时应急、采储结合、节约高效的原则，建立健全应急物资储备保障制度，动态更新应急物资储备品种目录，完善重要应急物资的监管、生产、采购、储备、调拨和紧急配送体系，促进安全应急产业发展，优化产业布局。"},{"i":46,"n":"第四十六条","txt":"设区的市级以上人民政府和突发事件易发、多发地区的县级人民政府应当建立应急救援物资、生活必需品和应急处置装备的储备保障制度。"},{"i":47,"n":"第四十七条","txt":"国家建立健全应急运输保障体系，统筹铁路、公路、水运、民航、邮政、快递等运输和服务方式，制定应急运输保障方案，保障应急物资、装备和人员及时运输。"},{"i":48,"n":"第四十八条","txt":"国家建立健全能源应急保障体系，提高能源安全保障能力，确保受突发事件影响地区的能源供应。"},{"i":49,"n":"第四十九条","txt":"国家建立健全应急通信、应急广播保障体系，加强应急通信系统、应急广播系统建设，确保突发事件应对工作的通信、广播安全畅通。"},{"i":50,"n":"第五十条","txt":"国家建立健全突发事件卫生应急体系，组织开展突发事件中的医疗救治、卫生学调查处置和心理援助等卫生应急工作，有效控制和消除危害。"},{"i":51,"n":"第五十一条","txt":"县级以上人民政府应当加强急救医疗服务网络的建设，配备相应的医疗救治物资、设施设备和人员，提高医疗卫生机构应对各类突发事件的救治能力。"},{"i":52,"n":"第五十二条","txt":"国家鼓励公民、法人和其他组织为突发事件应对工作提供物资、资金、技术支持和捐赠。"},{"i":53,"n":"第五十三条","txt":"红十字会在突发事件中，应当对伤病人员和其他受害者提供紧急救援和人道救助，并协助人民政府开展与其职责相关的其他人道主义服务活动。有关人民政府应当给予红十字会支持和资助，保障其依法参与应对突发事件。"},{"i":54,"n":"第五十四条","txt":"有关单位应当加强应急救援资金、物资的管理，提高使用效率。"},{"i":55,"n":"第五十五条","txt":"国家发展保险事业，建立政府支持、社会力量参与、市场化运作的巨灾风险保险体系，并鼓励单位和个人参加保险。"},{"i":56,"n":"第五十六条","txt":"国家加强应急管理基础科学、重点行业领域关键核心技术的研究，加强互联网、云计算、大数据、人工智能等现代技术手段在突发事件应对工作中的应用，鼓励、扶持有条件的教学科研机构、企业培养应急管理人才和科技人才，研发、推广新技术、新材料、新设备和新工具，提高突发事件应对能力。"},{"i":57,"n":"第五十七条","txt":"县级以上人民政府及其有关部门应当建立健全突发事件专家咨询论证制度，发挥专业人员在突发事件应对工作中的作用。"},{"i":58,"n":"第五十八条","txt":"国家建立健全突发事件监测制度。"},{"i":59,"n":"第五十九条","txt":"国务院建立全国统一的突发事件信息系统。"},{"i":60,"n":"第六十条","txt":"县级以上人民政府及其有关部门、专业机构应当通过多种途径收集突发事件信息。"},{"i":61,"n":"第六十一条","txt":"地方各级人民政府应当按照国家有关规定向上级人民政府报送突发事件信息。县级以上人民政府有关主管部门应当向本级人民政府相关部门通报突发事件信息，并报告上级人民政府主管部门。专业机构、监测网点和信息报告员应当及时向所在地人民政府及其有关主管部门报告突发事件信息。"},{"i":62,"n":"第六十二条","txt":"县级以上地方人民政府应当及时汇总分析突发事件隐患和监测信息，必要时组织相关部门、专业技术人员、专家学者进行会商，对发生突发事件的可能性及其可能造成的影响进行评估；认为可能发生重大或者特别重大突发事件的，应当立即向上级人民政府报告，并向上级人民政府有关部门、当地驻军和可能受到危害的毗邻或者相关地区的人民政府通报，及时采取预防措施。"},{"i":63,"n":"第六十三条","txt":"国家建立健全突发事件预警制度。"},{"i":64,"n":"第六十四条","txt":"可以预警的自然灾害、事故灾难或者公共卫生事件即将发生或者发生的可能性增大时，县级以上地方人民政府应当根据有关法律、行政法规和国务院规定的权限和程序，发布相应级别的警报，决定并宣布有关地区进入预警期，同时向上一级人民政府报告，必要时可以越级上报；具备条件的，应当进行网络直报或者自动速报；同时向当地驻军和可能受到危害的毗邻或者相关地区的人民政府通报。"},{"i":65,"n":"第六十五条","txt":"国家建立健全突发事件预警发布平台，按照有关规定及时、准确向社会发布突发事件预警信息。"},{"i":66,"n":"第六十六条","txt":"发布三级、四级警报，宣布进入预警期后，县级以上地方人民政府应当根据即将发生的突发事件的特点和可能造成的危害，采取下列措施："},{"i":67,"n":"第六十七条","txt":"发布一级、二级警报，宣布进入预警期后，县级以上地方人民政府除采取本法第六十六条规定的措施外，还应当针对即将发生的突发事件的特点和可能造成的危害，采取下列一项或者多项措施："},{"i":68,"n":"第六十八条","txt":"发布警报，宣布进入预警期后，县级以上人民政府应当对重要商品和服务市场情况加强监测，根据实际需要及时保障供应、稳定市场。必要时，国务院和省、自治区、直辖市人民政府可以按照《中华人民共和国价格法》等有关法律规定采取相应措施。"},{"i":69,"n":"第六十九条","txt":"对即将发生或者已经发生的社会安全事件，县级以上地方人民政府及其有关主管部门应当按照规定向上一级人民政府及其有关主管部门报告，必要时可以越级上报，具备条件的，应当进行网络直报或者自动速报。"},{"i":70,"n":"第七十条","txt":"发布突发事件警报的人民政府应当根据事态的发展，按照有关规定适时调整预警级别并重新发布。"},{"i":71,"n":"第七十一条","txt":"国家建立健全突发事件应急响应制度。"},{"i":72,"n":"第七十二条","txt":"突发事件发生后，履行统一领导职责或者组织处置突发事件的人民政府应当针对其性质、特点、危害程度和影响范围等，立即启动应急响应，组织有关部门，调动应急救援队伍和社会力量，依照法律、法规、规章和应急预案的规定，采取应急处置措施，并向上级人民政府报告；必要时，可以设立现场指挥部，负责现场应急处置与救援，统一指挥进入突发事件现场的单位和个人。"},{"i":73,"n":"第七十三条","txt":"自然灾害、事故灾难或者公共卫生事件发生后，履行统一领导职责的人民政府应当采取下列一项或者多项应急处置措施："},{"i":74,"n":"第七十四条","txt":"社会安全事件发生后，组织处置工作的人民政府应当立即启动应急响应，组织有关部门针对事件的性质和特点，依照有关法律、行政法规和国家其他有关规定，采取下列一项或者多项应急处置措施："},{"i":75,"n":"第七十五条","txt":"发生突发事件，严重影响国民经济正常运行时，国务院或者国务院授权的有关主管部门可以采取保障、控制等必要的应急措施，保障人民群众的基本生活需要，最大限度地减轻突发事件的影响。"},{"i":76,"n":"第七十六条","txt":"履行统一领导职责或者组织处置突发事件的人民政府及其有关部门，必要时可以向单位和个人征用应急救援所需设备、设施、场地、交通工具和其他物资，请求其他地方人民政府及其有关部门提供人力、物力、财力或者技术支援，要求生产、供应生活必需品和应急救援物资的企业组织生产、保证供给，要求提供医疗、交通等公共服务的组织提供相应的服务。"},{"i":77,"n":"第七十七条","txt":"突发事件发生地的居民委员会、村民委员会和其他组织应当按照当地人民政府的决定、命令，进行宣传动员，组织群众开展自救与互救，协助维护社会秩序；情况紧急的，应当立即组织群众开展自救与互救等先期处置工作。"},{"i":78,"n":"第七十八条","txt":"受到自然灾害危害或者发生事故灾难、公共卫生事件的单位，应当立即组织本单位应急救援队伍和工作人员营救受害人员，疏散、撤离、安置受到威胁的人员，控制危险源，标明危险区域，封锁危险场所，并采取其他防止危害扩大的必要措施，同时向所在地县级人民政府报告；对因本单位的问题引发的或者主体是本单位人员的社会安全事件，有关单位应当按照规定上报情况，并迅速派出负责人赶赴现场开展劝解、疏导工作。"},{"i":79,"n":"第七十九条","txt":"突发事件发生地的个人应当依法服从人民政府、居民委员会、村民委员会或者所属单位的指挥和安排，配合人民政府采取的应急处置措施，积极参加应急救援工作，协助维护社会秩序。"},{"i":80,"n":"第八十条","txt":"国家支持城乡社区组织健全应急工作机制，强化城乡社区综合服务设施和信息平台应急功能，加强与突发事件信息系统数据共享，增强突发事件应急处置中保障群众基本生活和服务群众能力。"},{"i":81,"n":"第八十一条","txt":"国家采取措施，加强心理健康服务体系和人才队伍建设，支持引导心理健康服务人员和社会工作者对受突发事件影响的各类人群开展心理健康教育、心理评估、心理疏导、心理危机干预、心理行为问题诊治等心理援助工作。"},{"i":82,"n":"第八十二条","txt":"对于突发事件遇难人员的遗体，应当按照法律和国家有关规定，科学规范处置，加强卫生防疫，维护逝者尊严。对于逝者的遗物应当妥善保管。"},{"i":83,"n":"第八十三条","txt":"县级以上人民政府及其有关部门根据突发事件应对工作需要，在履行法定职责所必需的范围和限度内，可以要求公民、法人和其他组织提供应急处置与救援需要的信息。公民、法人和其他组织应当予以提供，法律另有规定的除外。县级以上人民政府及其有关部门对获取的相关信息，应当严格保密，并依法保护公民的通信自由和通信秘密。"},{"i":84,"n":"第八十四条","txt":"在突发事件应急处置中，有关单位和个人因依照本法规定配合突发事件应对工作或者履行相关义务，需要获取他人个人信息的，应当依照法律规定的程序和方式取得并确保信息安全，不得非法收集、使用、加工、传输他人个人信息，不得非法买卖、提供或者公开他人个人信息。"},{"i":85,"n":"第八十五条","txt":"因依法履行突发事件应对工作职责或者义务获取的个人信息，只能用于突发事件应对，并在突发事件应对工作结束后予以销毁。确因依法作为证据使用或者调查评估需要留存或者延期销毁的，应当按照规定进行合法性、必要性、安全性评估，并采取相应保护和处理措施，严格依法使用。"},{"i":86,"n":"第八十六条","txt":"突发事件的威胁和危害得到控制或者消除后，履行统一领导职责或者组织处置突发事件的人民政府应当宣布解除应急响应，停止执行依照本法规定采取的应急处置措施，同时采取或者继续实施必要措施，防止发生自然灾害、事故灾难、公共卫生事件的次生、衍生事件或者重新引发社会安全事件，组织受影响地区尽快恢复社会秩序。"},{"i":87,"n":"第八十七条","txt":"突发事件应急处置工作结束后，履行统一领导职责的人民政府应当立即组织对突发事件造成的影响和损失进行调查评估，制定恢复重建计划，并向上一级人民政府报告。"},{"i":88,"n":"第八十八条","txt":"受突发事件影响地区的人民政府开展恢复重建工作需要上一级人民政府支持的，可以向上一级人民政府提出请求。上一级人民政府应当根据受影响地区遭受的损失和实际情况，提供资金、物资支持和技术指导，组织协调其他地区和有关方面提供资金、物资和人力支援。"},{"i":89,"n":"第八十九条","txt":"国务院根据受突发事件影响地区遭受损失的情况，制定扶持该地区有关行业发展的优惠政策。"},{"i":90,"n":"第九十条","txt":"公民参加应急救援工作或者协助维护社会秩序期间，其所在单位应当保证其工资待遇和福利不变，并可以按照规定给予相应补助。"},{"i":91,"n":"第九十一条","txt":"县级以上人民政府对在应急救援工作中伤亡的人员依法落实工伤待遇、抚恤或者其他保障政策，并组织做好应急救援工作中致病人员的医疗救治工作。"},{"i":92,"n":"第九十二条","txt":"履行统一领导职责的人民政府在突发事件应对工作结束后，应当及时查明突发事件的发生经过和原因，总结突发事件应急处置工作的经验教训，制定改进措施，并向上一级人民政府提出报告。"},{"i":93,"n":"第九十三条","txt":"突发事件应对工作中有关资金、物资的筹集、管理、分配、拨付和使用等情况，应当依法接受审计机关的审计监督。"},{"i":94,"n":"第九十四条","txt":"国家档案主管部门应当建立健全突发事件应对工作相关档案收集、整理、保护、利用工作机制。突发事件应对工作中形成的材料，应当按照国家规定归档，并向相关档案馆移交。"},{"i":95,"n":"第九十五条","txt":"地方各级人民政府和县级以上人民政府有关部门违反本法规定，不履行或者不正确履行法定职责的，由其上级行政机关责令改正；有下列情形之一，由有关机关综合考虑突发事件发生的原因、后果、应对处置情况、行为人过错等因素，对负有责任的领导人员和直接责任人员依法给予处分："},{"i":96,"n":"第九十六条","txt":"有关单位有下列情形之一，由所在地履行统一领导职责的人民政府有关部门责令停产停业，暂扣或者吊销许可证件，并处五万元以上二十万元以下的罚款；情节特别严重的，并处二十万元以上一百万元以下的罚款："},{"i":97,"n":"第九十七条","txt":"违反本法规定，编造并传播有关突发事件的虚假信息，或者明知是有关突发事件的虚假信息而进行传播的，责令改正，给予警告；造成严重后果的，依法暂停其业务活动或者吊销其许可证件；负有直接责任的人员是公职人员的，还应当依法给予处分。"},{"i":98,"n":"第九十八条","txt":"单位或者个人违反本法规定，不服从所在地人民政府及其有关部门依法发布的决定、命令或者不配合其依法采取的措施的，责令改正；造成严重后果的，依法给予行政处罚；负有直接责任的人员是公职人员的，还应当依法给予处分。"},{"i":99,"n":"第九十九条","txt":"单位或者个人违反本法第八十四条、第八十五条关于个人信息保护规定的，由主管部门依照有关法律规定给予处罚。"},{"i":100,"n":"第一百条","txt":"单位或者个人违反本法规定，导致突发事件发生或者危害扩大，造成人身、财产或者其他损害的，应当依法承担民事责任。"},{"i":101,"n":"第一百零一条","txt":"为了使本人或者他人的人身、财产免受正在发生的危险而采取避险措施的，依照《中华人民共和国民法典》、《中华人民共和国刑法》等法律关于紧急避险的规定处理。"},{"i":102,"n":"第一百零二条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":103,"n":"第一百零三条","txt":"发生特别重大突发事件，对人民生命财产安全、国家安全、公共安全、生态环境安全或者社会秩序构成重大威胁，采取本法和其他有关法律、法规、规章规定的应急处置措施不能消除或者有效控制、减轻其严重社会危害，需要进入紧急状态的，由全国人民代表大会常务委员会或者国务院依照宪法和其他有关法律规定的权限和程序决定。"},{"i":104,"n":"第一百零四条","txt":"中华人民共和国领域外发生突发事件，造成或者可能造成中华人民共和国公民、法人和其他组织人身伤亡、财产损失的，由国务院外交部门会同国务院其他有关部门、有关地方人民政府，按照国家有关规定做好应对工作。"},{"i":105,"n":"第一百零五条","txt":"在中华人民共和国境内的外国人、无国籍人应当遵守本法，服从所在地人民政府及其有关部门依法发布的决定、命令，并配合其依法采取的措施。"},{"i":106,"n":"第一百零六条","txt":"本法自2024年11月1日起施行。"}],"tufagonggongweishengshijianyingduifa":[{"i":1,"n":"第一条","txt":"为了预防和减少突发公共卫生事件的发生，控制、减轻和消除突发公共卫生事件的危害，提高突发公共卫生事件应对能力，规范突发公共卫生事件应对活动，保障公众生命安全和身体健康，维护国家安全、公共安全和社会秩序，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称突发公共卫生事件，是指突然发生，造成或者可能造成公众生命安全和身体健康严重损害，需要采取应急处置措施予以应对的重大传染病疫情、群体性不明原因疾病、群体性中毒以及其他严重影响公众生命安全和身体健康的事件。"},{"i":3,"n":"第三条","txt":"突发公共卫生事件应对工作坚持中国共产党的领导，贯彻总体国家安全观，统筹发展和安全，坚持人民至上、生命至上。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将突发公共卫生事件应对工作纳入国民经济和社会发展规划，加强公共卫生风险防控和治理体系建设，提高应对突发公共卫生事件的能力。"},{"i":5,"n":"第五条","txt":"国家建立应对突发公共卫生事件的社会动员机制，组织动员单位和个人依法有序参与突发公共卫生事件应对工作。"},{"i":6,"n":"第六条","txt":"国家坚持中西医并重，加强中西医结合，充分发挥中医药在突发公共卫生事件应对中的作用。"},{"i":7,"n":"第七条","txt":"国家支持和鼓励开展公共卫生应急领域的科学研究和技术创新，加强公共卫生应急科研攻关体系和能力建设，推广应用相关科研成果和先进技术。"},{"i":8,"n":"第八条","txt":"突发公共卫生事件应对中，收集、存储、使用、加工、传输、提供、公开、删除个人信息的，应当遵守《中华人民共和国个人信息保护法》等法律、行政法规的规定，遵循合法、正当、必要和诚信原则，采取必要措施确保个人信息安全，不得非法收集、使用、加工、传输他人个人信息，不得非法买卖、提供或者公开他人个人信息；涉及敏感个人信息的，应当采取严格的保护措施。突发公共卫生事件应对结束后，应当及时删除为应对突发公共卫生事件所处理的个人信息。"},{"i":9,"n":"第九条","txt":"采取突发公共卫生事件应对措施，应当依照法定权限和程序，与突发公共卫生事件的性质和可能造成危害的程度、范围等相适应；有多种措施可供选择的，应当选择有利于最大程度保护单位和个人合法权益，且对他人权益损害和生产生活影响较小的措施，并根据情况变化及时调整。"},{"i":10,"n":"第十条","txt":"国家支持和鼓励开展应对突发公共卫生事件的国际交流与合作。"},{"i":11,"n":"第十一条","txt":"对在突发公共卫生事件应对工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":12,"n":"第十二条","txt":"突发公共卫生事件应对工作实行党委领导、政府负责、部门协同联动、社会共同参与、属地管理和分类管理相结合的管理体制，明确属地、部门、单位和个人责任，加强公共卫生应急指挥能力建设。"},{"i":13,"n":"第十三条","txt":"县级人民政府对本行政区域突发公共卫生事件应对工作负责；涉及两个以上行政区域的，由有关行政区域共同的上一级人民政府负责，或者由各有关行政区域的上一级人民政府共同负责。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府设立由本级人民政府主要负责人、有关部门负责人、参与突发公共卫生事件应对的中国人民解放军和中国人民武装警察部队有关单位负责人等组成的突发公共卫生事件应急指挥机构，组织、协调、指挥本级人民政府各有关部门和下级人民政府开展突发公共卫生事件应对工作。"},{"i":15,"n":"第十五条","txt":"国务院卫生健康主管部门牵头组织协调全国重大传染病疫情应对工作，负责全国其他突发公共卫生事件应对工作。国务院疾病预防控制部门负责全国重大传染病疫情应对相关工作。国务院其他有关部门在各自职责范围内负责突发公共卫生事件应对有关工作。"},{"i":16,"n":"第十六条","txt":"街道办事处、乡镇人民政府应当指导居民委员会、村民委员会协助开展突发公共卫生事件应对有关工作，推动居民委员会、村民委员会与基层医疗卫生机构协同联动。"},{"i":17,"n":"第十七条","txt":"单位和个人应当支持突发公共卫生事件应对工作，执行依法采取的突发公共卫生事件应对措施。"},{"i":18,"n":"第十八条","txt":"国家加强突发公共卫生事件风险源头管理，减少突发公共卫生事件的发生，减轻突发公共卫生事件的危害。"},{"i":19,"n":"第十九条","txt":"国家建立健全突发公共卫生事件应急预案体系。"},{"i":20,"n":"第二十条","txt":"下列单位应当评估本单位发生突发公共卫生事件的风险，针对可能发生的突发公共卫生事件，制定相应的应急预案，并组织开展演练："},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府应当将突发公共卫生事件临时应急处置场所建设纳入国土空间规划等相关规划，依法推进公共设施平急两用改造。"},{"i":22,"n":"第二十二条","txt":"疾病预防控制机构应当提高突发公共卫生事件监测预警、流行病学调查、检验检测和应急处置能力，配备与其职责相适应的专职人员。"},{"i":23,"n":"第二十三条","txt":"二级以上医疗机构应当指定科室、配备专职人员承担卫生应急工作，组建本机构的卫生应急队伍。基层医疗卫生机构应当指定人员负责卫生应急工作。"},{"i":24,"n":"第二十四条","txt":"国家建立健全突发公共卫生事件应急医疗救治体系。县级以上地方人民政府应当确定各类突发公共卫生事件的定点救治医院，形成由定点救治医院、其他医院和基层医疗卫生机构、院前急救机构、临时性救治场所、血站等组成的突发公共卫生事件应急医疗救治网络。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府卫生健康主管部门、疾病预防控制部门、中医药管理部门应当加强卫生应急队伍建设，组建包括形势研判、流行病学调查、医疗救治、检验检测、消毒处理、社区指导、心理援助、物资调配等领域人员的卫生应急队伍，定期组织开展演练。"},{"i":26,"n":"第二十六条","txt":"国家采取措施，加强公共卫生应急领域人才培养。"},{"i":27,"n":"第二十七条","txt":"国家建立健全多点触发、反应快速、权威高效的突发公共卫生事件监测预警体系。"},{"i":28,"n":"第二十八条","txt":"国家加强突发公共卫生事件监测，建立突发公共卫生事件监测哨点，多途径、多渠道开展监测，建立智慧化多点触发机制，提高监测的敏感性和准确性，及时发现突发公共卫生事件。"},{"i":29,"n":"第二十九条","txt":"国家建立跨部门、跨地域的突发公共卫生事件监测信息共享机制，加强卫生健康、疾病预防控制、生态环境、农业农村、海关、市场监督管理、移民管理、林业草原等部门的联动监测和信息共享。"},{"i":30,"n":"第三十条","txt":"国家建立健全突发公共卫生事件报告制度。国务院卫生健康主管部门会同国务院疾病预防控制部门制定突发公共卫生事件报告规范。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人发现发生或者可能发生突发公共卫生事件时，应当立即通过热线电话等渠道向所在地人民政府、有关主管部门或者疾病预防控制机构报告。"},{"i":32,"n":"第三十二条","txt":"对单位和个人的报告，经调查不属于突发公共卫生事件的，报告的单位和个人不承担法律责任。"},{"i":33,"n":"第三十三条","txt":"疾病预防控制机构接到突发公共卫生事件报告后，应当立即进行调查、核实。"},{"i":34,"n":"第三十四条","txt":"卫生健康主管部门、疾病预防控制部门，医疗卫生机构及其执行职务的人员、检验检测机构以及发生或者可能发生突发公共卫生事件的单位，应当依照本法、突发公共卫生事件报告规范及时、准确报告。任何单位或者个人不得干预突发公共卫生事件报告。"},{"i":35,"n":"第三十五条","txt":"疾病预防控制机构发现可能发生突发公共卫生事件，经评估认为需要发布预警的，向同级卫生健康主管部门、疾病预防控制部门报告时应当同时提出发布预警的建议。卫生健康主管部门、疾病预防控制部门收到建议后，应当立即组织专家进行分析研判；需要发布预警的，应当立即报告本级人民政府。人民政府应当及时决定是否发布预警；发布预警的，应当同时报告上一级人民政府，必要时可以越级上报，并通报可能受到影响地区的同级人民政府；需要上级人民政府采取防范措施的，应当同时提出建议。"},{"i":36,"n":"第三十六条","txt":"县级以上人民政府发布预警，应当根据可能发生的突发公共卫生事件的性质、可能造成的危害，采取下列一项或者多项措施："},{"i":37,"n":"第三十七条","txt":"国家对突发公共卫生事件实行分级应急响应。"},{"i":38,"n":"第三十八条","txt":"疾病预防控制机构发现发生突发公共卫生事件的，向同级卫生健康主管部门、疾病预防控制部门报告时应当同时提出启动应急响应的建议。卫生健康主管部门、疾病预防控制部门收到建议后，应当立即组织专家进行分析研判，并报告本级人民政府。人民政府应当立即决定启动应急响应、向社会发布公告，同时报告上一级人民政府，必要时可以越级上报，并通报可能受到影响地区的同级人民政府。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府启动应急响应，应当组织有关部门按照突发公共卫生事件应急预案进行处置。县级以上人民政府处置突发公共卫生事件，可以在一定范围内采取下列一项或者多项应急处置措施："},{"i":40,"n":"第四十条","txt":"县级以上人民政府应当及时发布突发公共卫生事件事态发展、应急处置工作进展等信息。发现影响或者可能影响社会稳定、扰乱社会和经济管理秩序的虚假或者不完整信息的，应当及时发布准确的信息予以澄清。"},{"i":41,"n":"第四十一条","txt":"突发公共卫生事件发生后，疾病预防控制机构应当开展流行病学调查，对被污染的场所进行卫生处理。"},{"i":42,"n":"第四十二条","txt":"医疗机构应当开展突发公共卫生事件医疗救治，优化诊疗方案，提高诊断和救治能力。在医疗救治中，应当注重发挥中西医各自优势，提高救治效果。"},{"i":43,"n":"第四十三条","txt":"因突发公共卫生事件医疗救治紧急需要，医师可以按照国家统一制定的诊疗方案，在一定范围和期限内采用药品说明书中未明确的药品用法进行救治。"},{"i":44,"n":"第四十四条","txt":"突发公共卫生事件发生后，国务院及其有关部门有权在全国或者跨省级行政区域范围内，县级以上地方人民政府及其有关部门有权在本行政区域内，根据突发公共卫生事件应急处置需要，临时征用房屋、交通工具以及相关设施、设备、场地和其他物资，要求有关单位和个人提供技术支持，要求生产、供应基本生活必需品和突发公共卫生事件应急物资的单位组织生产、保障供应。"},{"i":45,"n":"第四十五条","txt":"突发公共卫生事件发生后，县级以上人民政府有关部门应当组织协调运输经营单位，优先运送参与突发公共卫生事件应急处置的人员以及药品、医疗器械、血液、防护用品和其他突发公共卫生事件应急物资。"},{"i":46,"n":"第四十六条","txt":"突发公共卫生事件应急处置期间，县级以上地方人民政府应当采取措施维持社会基本运行，保障食品、饮用水等基本生活必需品的供应，提供基本医疗服务；对未成年人、老年人、残疾人、孕产期和哺乳期的妇女以及需要及时救治的伤病人员等群体给予特殊照顾和安排，并确保相关人员获得医疗救治。"},{"i":47,"n":"第四十七条","txt":"突发公共卫生事件发生后，县级以上地方人民政府应当组织专业力量，对受到突发公共卫生事件影响的人员以及公众提供心理疏导、心理干预等心理援助服务。"},{"i":48,"n":"第四十八条","txt":"突发公共卫生事件应急处置期间，县级以上人民政府应当依照有关法律、行政法规的规定，组织开展医疗废物收集、贮存、运输、处置等工作。"},{"i":49,"n":"第四十九条","txt":"县级以上人民政府应当及时组织专家对突发公共卫生事件事态发展进行分析研判，并根据研判结果调整应急响应的级别和应急处置措施；突发公共卫生事件得到有效控制后，应当及时宣布解除应急响应，停止执行依法采取的应急处置措施。"},{"i":50,"n":"第五十条","txt":"突发公共卫生事件应急处置结束后，负责应对工作的地方人民政府应当及时总结应急处置工作，并向上一级人民政府报告。"},{"i":51,"n":"第五十一条","txt":"县级以上人民政府按照本级政府职责，妥善安排突发公共卫生事件应对工作经费。"},{"i":52,"n":"第五十二条","txt":"国家依托高水平医疗机构建设国家重大传染病防治基地等突发公共卫生事件医疗救治基地，依托省级疾病预防控制机构建设区域公共卫生应急协作平台。"},{"i":53,"n":"第五十三条","txt":"国家统筹医疗保障基金和公共卫生服务资金使用，促进公共卫生服务和医疗服务有效衔接，实现更好保障。"},{"i":54,"n":"第五十四条","txt":"国家建立健全公共卫生应急物资保障体系，提高突发公共卫生事件应急物资保障水平。县级以上人民政府发展改革部门统筹公共卫生应急物资保障工作。"},{"i":55,"n":"第五十五条","txt":"对参与突发公共卫生事件应急处置的人员，按照国家规定采取有效的卫生防护措施和医疗保健措施，并给予适当的津贴。"},{"i":56,"n":"第五十六条","txt":"违反本法规定，地方各级人民政府和县级以上人民政府卫生健康、疾病预防控制等部门在突发公共卫生事件应对工作中有下列情形之一的，由其上级行政机关责令改正，通报批评，对负有责任的领导人员和直接责任人员依法给予处分："},{"i":57,"n":"第五十七条","txt":"违反本法规定，疾病预防控制机构有下列情形之一的，由县级以上人民政府卫生健康主管部门、疾病预防控制部门依据职责责令改正，给予警告或者通报批评，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门责令有关责任人员暂停六个月以上一年以下的执业活动直至依法吊销执业证书："},{"i":58,"n":"第五十八条","txt":"违反本法规定，发生或者可能发生突发公共卫生事件的单位未依法履行报告职责，隐瞒、谎报、缓报、漏报突发公共卫生事件，或者干预突发公共卫生事件报告的，由县级以上人民政府卫生健康主管部门、疾病预防控制部门依据职责责令改正，给予警告或者通报批评；造成严重后果的，并处一万元以上十万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":59,"n":"第五十九条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府卫生健康主管部门、疾病预防控制部门依据职责责令改正，给予警告，对违法的单位可以并处二万元以下罚款，对违法的个人可以并处一千元以下罚款；情节严重的，由原发证部门依法吊销相关许可证或者营业执照："},{"i":60,"n":"第六十条","txt":"对突发公共卫生事件发生期间哄抬价格、牟取暴利、制假售假等扰乱市场秩序的行为，依法从重给予行政处罚。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，造成人身损害、财产损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"在中华人民共和国领域内的外国人、无国籍人应当遵守本法。对涉及外国驻中华人民共和国外交、领事机构和国际组织驻中华人民共和国代表机构以及上述机构的人员及其家属的突发公共卫生事件，有关县级以上地方人民政府在国务院外交部门的指导下开展应对工作。"},{"i":63,"n":"第六十三条","txt":"在中华人民共和国对外开放的口岸开展有关突发公共卫生事件监测、应急处置等，《中华人民共和国国境卫生检疫法》等法律另有规定的，依照其规定。"},{"i":64,"n":"第六十四条","txt":"中国人民解放军、中国人民武装警察部队的突发公共卫生事件应对工作，依照本法和中央军事委员会的有关规定执行，由中央军事委员会负责卫生工作的部门实施管理。"},{"i":65,"n":"第六十五条","txt":"本法自2025年11月1日起施行。"}],"jingshenweishengfa":[{"i":1,"n":"第一条","txt":"为了发展精神卫生事业，规范精神卫生服务，维护精神障碍患者的合法权益，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内开展维护和增进公民心理健康、预防和治疗精神障碍、促进精神障碍患者康复的活动，适用本法。"},{"i":3,"n":"第三条","txt":"精神卫生工作实行预防为主的方针，坚持预防、治疗和康复相结合的原则。"},{"i":4,"n":"第四条","txt":"精神障碍患者的人格尊严、人身和财产安全不受侵犯。"},{"i":5,"n":"第五条","txt":"全社会应当尊重、理解、关爱精神障碍患者。"},{"i":6,"n":"第六条","txt":"精神卫生工作实行政府组织领导、部门各负其责、家庭和单位尽力尽责、全社会共同参与的综合管理机制。"},{"i":7,"n":"第七条","txt":"县级以上人民政府领导精神卫生工作，将其纳入国民经济和社会发展规划，建设和完善精神障碍的预防、治疗和康复服务体系，建立健全精神卫生工作协调机制和工作责任制，对有关部门承担的精神卫生工作进行考核、监督。"},{"i":8,"n":"第八条","txt":"国务院卫生行政部门主管全国的精神卫生工作。县级以上地方人民政府卫生行政部门主管本行政区域的精神卫生工作。"},{"i":9,"n":"第九条","txt":"精神障碍患者的监护人应当履行监护职责，维护精神障碍患者的合法权益。"},{"i":10,"n":"第十条","txt":"中国残疾人联合会及其地方组织依照法律、法规或者接受政府委托，动员社会力量，开展精神卫生工作。"},{"i":11,"n":"第十一条","txt":"国家鼓励和支持开展精神卫生专门人才的培养，维护精神卫生工作人员的合法权益，加强精神卫生专业队伍建设。"},{"i":12,"n":"第十二条","txt":"各级人民政府和县级以上人民政府有关部门应当采取措施，鼓励和支持组织、个人提供精神卫生志愿服务，捐助精神卫生事业，兴建精神卫生公益设施。"},{"i":13,"n":"第十三条","txt":"各级人民政府和县级以上人民政府有关部门应当采取措施，加强心理健康促进和精神障碍预防工作，提高公众心理健康水平。"},{"i":14,"n":"第十四条","txt":"各级人民政府和县级以上人民政府有关部门制定的突发事件应急预案，应当包括心理援助的内容。发生突发事件，履行统一领导职责或者组织处置突发事件的人民政府应当根据突发事件的具体情况，按照应急预案的规定，组织开展心理援助工作。"},{"i":15,"n":"第十五条","txt":"用人单位应当创造有益于职工身心健康的工作环境，关注职工的心理健康；对处于职业发展特定时期或者在特殊岗位工作的职工，应当有针对性地开展心理健康教育。"},{"i":16,"n":"第十六条","txt":"各级各类学校应当对学生进行精神卫生知识教育；配备或者聘请心理健康教育教师、辅导人员，并可以设立心理健康辅导室，对学生进行心理健康教育。学前教育机构应当对幼儿开展符合其特点的心理健康教育。"},{"i":17,"n":"第十七条","txt":"医务人员开展疾病诊疗服务，应当按照诊断标准和治疗规范的要求，对就诊者进行心理健康指导；发现就诊者可能患有精神障碍的，应当建议其到符合本法规定的医疗机构就诊。"},{"i":18,"n":"第十八条","txt":"监狱、看守所、拘留所、强制隔离戒毒所等场所，应当对服刑人员，被依法拘留、逮捕、强制隔离戒毒的人员等，开展精神卫生知识宣传，关注其心理健康状况，必要时提供心理咨询和心理辅导。"},{"i":19,"n":"第十九条","txt":"县级以上地方人民政府人力资源社会保障、教育、卫生、司法行政、公安等部门应当在各自职责范围内分别对本法第十五条至第十八条规定的单位履行精神障碍预防义务的情况进行督促和指导。"},{"i":20,"n":"第二十条","txt":"村民委员会、居民委员会应当协助所在地人民政府及其有关部门开展社区心理健康指导、精神卫生知识宣传教育活动，创建有益于居民身心健康的社区环境。"},{"i":21,"n":"第二十一条","txt":"家庭成员之间应当相互关爱，创造良好、和睦的家庭环境，提高精神障碍预防意识；发现家庭成员可能患有精神障碍的，应当帮助其及时就诊，照顾其生活，做好看护管理。"},{"i":22,"n":"第二十二条","txt":"国家鼓励和支持新闻媒体、社会组织开展精神卫生的公益性宣传，普及精神卫生知识，引导公众关注心理健康，预防精神障碍的发生。"},{"i":23,"n":"第二十三条","txt":"心理咨询人员应当提高业务素质，遵守执业规范，为社会公众提供专业化的心理咨询服务。"},{"i":24,"n":"第二十四条","txt":"国务院卫生行政部门建立精神卫生监测网络，实行严重精神障碍发病报告制度，组织开展精神障碍发生状况、发展趋势等的监测和专题调查工作。精神卫生监测和严重精神障碍发病报告管理办法，由国务院卫生行政部门制定。"},{"i":25,"n":"第二十五条","txt":"开展精神障碍诊断、治疗活动，应当具备下列条件，并依照医疗机构的管理规定办理有关手续："},{"i":26,"n":"第二十六条","txt":"精神障碍的诊断、治疗，应当遵循维护患者合法权益、尊重患者人格尊严的原则，保障患者在现有条件下获得良好的精神卫生服务。"},{"i":27,"n":"第二十七条","txt":"精神障碍的诊断应当以精神健康状况为依据。"},{"i":28,"n":"第二十八条","txt":"除个人自行到医疗机构进行精神障碍诊断外，疑似精神障碍患者的近亲属可以将其送往医疗机构进行精神障碍诊断。对查找不到近亲属的流浪乞讨疑似精神障碍患者，由当地民政等有关部门按照职责分工，帮助送往医疗机构进行精神障碍诊断。"},{"i":29,"n":"第二十九条","txt":"精神障碍的诊断应当由精神科执业医师作出。"},{"i":30,"n":"第三十条","txt":"精神障碍的住院治疗实行自愿原则。"},{"i":31,"n":"第三十一条","txt":"精神障碍患者有本法第三十条第二款第一项情形的，经其监护人同意，医疗机构应当对患者实施住院治疗；监护人不同意的，医疗机构不得对患者实施住院治疗。监护人应当对在家居住的患者做好看护管理。"},{"i":32,"n":"第三十二条","txt":"精神障碍患者有本法第三十条第二款第二项情形，患者或者其监护人对需要住院治疗的诊断结论有异议，不同意对患者实施住院治疗的，可以要求再次诊断和鉴定。"},{"i":33,"n":"第三十三条","txt":"鉴定人应当到收治精神障碍患者的医疗机构面见、询问患者，该医疗机构应当予以配合。"},{"i":34,"n":"第三十四条","txt":"鉴定机构、鉴定人应当遵守有关法律、法规、规章的规定，尊重科学，恪守职业道德，按照精神障碍鉴定的实施程序、技术方法和操作规范，依法独立进行鉴定，出具客观、公正的鉴定报告。"},{"i":35,"n":"第三十五条","txt":"再次诊断结论或者鉴定报告表明，不能确定就诊者为严重精神障碍患者，或者患者不需要住院治疗的，医疗机构不得对其实施住院治疗。"},{"i":36,"n":"第三十六条","txt":"诊断结论表明需要住院治疗的精神障碍患者，本人没有能力办理住院手续的，由其监护人办理住院手续；患者属于查找不到监护人的流浪乞讨人员的，由送诊的有关部门办理住院手续。"},{"i":37,"n":"第三十七条","txt":"医疗机构及其医务人员应当将精神障碍患者在诊断、治疗过程中享有的权利，告知患者或者其监护人。"},{"i":38,"n":"第三十八条","txt":"医疗机构应当配备适宜的设施、设备，保护就诊和住院治疗的精神障碍患者的人身安全，防止其受到伤害，并为住院患者创造尽可能接近正常生活的环境和条件。"},{"i":39,"n":"第三十九条","txt":"医疗机构及其医务人员应当遵循精神障碍诊断标准和治疗规范，制定治疗方案，并向精神障碍患者或者其监护人告知治疗方案和治疗方法、目的以及可能产生的后果。"},{"i":40,"n":"第四十条","txt":"精神障碍患者在医疗机构内发生或者将要发生伤害自身、危害他人安全、扰乱医疗秩序的行为，医疗机构及其医务人员在没有其他可替代措施的情况下，可以实施约束、隔离等保护性医疗措施。实施保护性医疗措施应当遵循诊断标准和治疗规范，并在实施后告知患者的监护人。"},{"i":41,"n":"第四十一条","txt":"对精神障碍患者使用药物，应当以诊断和治疗为目的，使用安全、有效的药物，不得为诊断或者治疗以外的目的使用药物。"},{"i":42,"n":"第四十二条","txt":"禁止对依照本法第三十条第二款规定实施住院治疗的精神障碍患者实施以治疗精神障碍为目的的外科手术。"},{"i":43,"n":"第四十三条","txt":"医疗机构对精神障碍患者实施下列治疗措施，应当向患者或者其监护人告知医疗风险、替代医疗方案等情况，并取得患者的书面同意；无法取得患者意见的，应当取得其监护人的书面同意，并经本医疗机构伦理委员会批准："},{"i":44,"n":"第四十四条","txt":"自愿住院治疗的精神障碍患者可以随时要求出院，医疗机构应当同意。"},{"i":45,"n":"第四十五条","txt":"精神障碍患者出院，本人没有能力办理出院手续的，监护人应当为其办理出院手续。"},{"i":46,"n":"第四十六条","txt":"医疗机构及其医务人员应当尊重住院精神障碍患者的通讯和会见探访者等权利。除在急性发病期或者为了避免妨碍治疗可以暂时性限制外，不得限制患者的通讯和会见探访者等权利。"},{"i":47,"n":"第四十七条","txt":"医疗机构及其医务人员应当在病历资料中如实记录精神障碍患者的病情、治疗措施、用药情况、实施约束、隔离措施等内容，并如实告知患者或者其监护人。患者及其监护人可以查阅、复制病历资料；但是，患者查阅、复制病历资料可能对其治疗产生不利影响的除外。病历资料保存期限不得少于三十年。"},{"i":48,"n":"第四十八条","txt":"医疗机构不得因就诊者是精神障碍患者，推诿或者拒绝为其治疗属于本医疗机构诊疗范围的其他疾病。"},{"i":49,"n":"第四十九条","txt":"精神障碍患者的监护人应当妥善看护未住院治疗的患者，按照医嘱督促其按时服药、接受随访或者治疗。村民委员会、居民委员会、患者所在单位等应当依患者或者其监护人的请求，对监护人看护患者提供必要的帮助。"},{"i":50,"n":"第五十条","txt":"县级以上地方人民政府卫生行政部门应当定期就下列事项对本行政区域内从事精神障碍诊断、治疗的医疗机构进行检查："},{"i":51,"n":"第五十一条","txt":"心理治疗活动应当在医疗机构内开展。专门从事心理治疗的人员不得从事精神障碍的诊断，不得为精神障碍患者开具处方或者提供外科治疗。心理治疗的技术规范由国务院卫生行政部门制定。"},{"i":52,"n":"第五十二条","txt":"监狱、强制隔离戒毒所等场所应当采取措施，保证患有精神障碍的服刑人员、强制隔离戒毒人员等获得治疗。"},{"i":53,"n":"第五十三条","txt":"精神障碍患者违反治安管理处罚法或者触犯刑法的，依照有关法律的规定处理。"},{"i":54,"n":"第五十四条","txt":"社区康复机构应当为需要康复的精神障碍患者提供场所和条件，对患者进行生活自理能力和社会适应能力等方面的康复训练。"},{"i":55,"n":"第五十五条","txt":"医疗机构应当为在家居住的严重精神障碍患者提供精神科基本药物维持治疗，并为社区康复机构提供有关精神障碍康复的技术指导和支持。"},{"i":56,"n":"第五十六条","txt":"村民委员会、居民委员会应当为生活困难的精神障碍患者家庭提供帮助，并向所在地乡镇人民政府或者街道办事处以及县级人民政府有关部门反映患者及其家庭的情况和要求，帮助其解决实际困难，为患者融入社会创造条件。"},{"i":57,"n":"第五十七条","txt":"残疾人组织或者残疾人康复机构应当根据精神障碍患者康复的需要，组织患者参加康复活动。"},{"i":58,"n":"第五十八条","txt":"用人单位应当根据精神障碍患者的实际情况，安排患者从事力所能及的工作，保障患者享有同等待遇，安排患者参加必要的职业技能培训，提高患者的就业能力，为患者创造适宜的工作环境，对患者在工作中取得的成绩予以鼓励。"},{"i":59,"n":"第五十九条","txt":"精神障碍患者的监护人应当协助患者进行生活自理能力和社会适应能力等方面的康复训练。"},{"i":60,"n":"第六十条","txt":"县级以上人民政府卫生行政部门会同有关部门依据国民经济和社会发展规划的要求，制定精神卫生工作规划并组织实施。"},{"i":61,"n":"第六十一条","txt":"省、自治区、直辖市人民政府根据本行政区域的实际情况，统筹规划，整合资源，建设和完善精神卫生服务体系，加强精神障碍预防、治疗和康复服务能力建设。"},{"i":62,"n":"第六十二条","txt":"各级人民政府应当根据精神卫生工作需要，加大财政投入力度，保障精神卫生工作所需经费，将精神卫生工作经费列入本级财政预算。"},{"i":63,"n":"第六十三条","txt":"国家加强基层精神卫生服务体系建设，扶持贫困地区、边远地区的精神卫生工作，保障城市社区、农村基层精神卫生工作所需经费。"},{"i":64,"n":"第六十四条","txt":"医学院校应当加强精神医学的教学和研究，按照精神卫生工作的实际需要培养精神医学专门人才，为精神卫生工作提供人才保障。"},{"i":65,"n":"第六十五条","txt":"综合性医疗机构应当按照国务院卫生行政部门的规定开设精神科门诊或者心理治疗门诊，提高精神障碍预防、诊断、治疗能力。"},{"i":66,"n":"第六十六条","txt":"医疗机构应当组织医务人员学习精神卫生知识和相关法律、法规、政策。"},{"i":67,"n":"第六十七条","txt":"师范院校应当为学生开设精神卫生课程；医学院校应当为非精神医学专业的学生开设精神卫生课程。"},{"i":68,"n":"第六十八条","txt":"县级以上人民政府卫生行政部门应当组织医疗机构为严重精神障碍患者免费提供基本公共卫生服务。"},{"i":69,"n":"第六十九条","txt":"对符合城乡最低生活保障条件的严重精神障碍患者，民政部门应当会同有关部门及时将其纳入最低生活保障。"},{"i":70,"n":"第七十条","txt":"县级以上地方人民政府及其有关部门应当采取有效措施，保证患有精神障碍的适龄儿童、少年接受义务教育，扶持有劳动能力的精神障碍患者从事力所能及的劳动，并为已经康复的人员提供就业服务。"},{"i":71,"n":"第七十一条","txt":"精神卫生工作人员的人格尊严、人身安全不受侵犯，精神卫生工作人员依法履行职责受法律保护。全社会应当尊重精神卫生工作人员。"},{"i":72,"n":"第七十二条","txt":"县级以上人民政府卫生行政部门和其他有关部门未依照本法规定履行精神卫生工作职责，或者滥用职权、玩忽职守、徇私舞弊的，由本级人民政府或者上一级人民政府有关部门责令改正，通报批评，对直接负责的主管人员和其他直接责任人员依法给予警告、记过或者记大过的处分；造成严重后果的，给予降级、撤职或者开除的处分。"},{"i":73,"n":"第七十三条","txt":"不符合本法规定条件的医疗机构擅自从事精神障碍诊断、治疗的，由县级以上人民政府卫生行政部门责令停止相关诊疗活动，给予警告，并处五千元以上一万元以下罚款，有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予或者责令给予降低岗位等级或者撤职、开除的处分；对有关医务人员，吊销其执业证书。"},{"i":74,"n":"第七十四条","txt":"医疗机构及其工作人员有下列行为之一的，由县级以上人民政府卫生行政部门责令改正，给予警告；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予或者责令给予降低岗位等级或者撤职、开除的处分，并可以责令有关医务人员暂停一个月以上六个月以下执业活动："},{"i":75,"n":"第七十五条","txt":"医疗机构及其工作人员有下列行为之一的，由县级以上人民政府卫生行政部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予或者责令给予降低岗位等级或者撤职的处分；对有关医务人员，暂停六个月以上一年以下执业活动；情节严重的，给予或者责令给予开除的处分，并吊销有关医务人员的执业证书："},{"i":76,"n":"第七十六条","txt":"有下列情形之一的，由县级以上人民政府卫生行政部门、工商行政管理部门依据各自职责责令改正，给予警告，并处五千元以上一万元以下罚款，有违法所得的，没收违法所得；造成严重后果的，责令暂停六个月以上一年以下执业活动，直至吊销执业证书或者营业执照："},{"i":77,"n":"第七十七条","txt":"有关单位和个人违反本法第四条第三款规定，给精神障碍患者造成损害的，依法承担赔偿责任；对单位直接负责的主管人员和其他直接责任人员，还应当依法给予处分。"},{"i":78,"n":"第七十八条","txt":"违反本法规定，有下列情形之一，给精神障碍患者或者其他公民造成人身、财产或者其他损害的，依法承担赔偿责任："},{"i":79,"n":"第七十九条","txt":"医疗机构出具的诊断结论表明精神障碍患者应当住院治疗而其监护人拒绝，致使患者造成他人人身、财产损害的，或者患者有其他造成他人人身、财产损害情形的，其监护人依法承担民事责任。"},{"i":80,"n":"第八十条","txt":"在精神障碍的诊断、治疗、鉴定过程中，寻衅滋事，阻挠有关工作人员依照本法的规定履行职责，扰乱医疗机构、鉴定机构工作秩序的，依法给予治安管理处罚。"},{"i":81,"n":"第八十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":82,"n":"第八十二条","txt":"精神障碍患者或者其监护人、近亲属认为行政机关、医疗机构或者其他有关单位和个人违反本法规定侵害患者合法权益的，可以依法提起诉讼。"},{"i":83,"n":"第八十三条","txt":"本法所称精神障碍，是指由各种原因引起的感知、情感和思维等精神活动的紊乱或者异常，导致患者明显的心理痛苦或者社会适应等功能损害。"},{"i":84,"n":"第八十四条","txt":"军队的精神卫生工作，由国务院和中央军事委员会依据本法制定管理办法。"},{"i":85,"n":"第八十五条","txt":"本法自2013年5月1日起施行。"}],"zhiyejiaoyufa":[{"i":1,"n":"第一条","txt":"为了推动职业教育高质量发展，提高劳动者素质和技术技能水平，促进就业创业，建设教育强国、人力资源强国和技能型社会，推进社会主义现代化建设，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称职业教育，是指为了培养高素质技术技能人才，使受教育者具备从事某种职业或者实现职业发展所需要的职业道德、科学文化与专业知识、技术技能等职业综合素质和行动能力而实施的教育，包括职业学校教育和职业培训。"},{"i":3,"n":"第三条","txt":"职业教育是与普通教育具有同等重要地位的教育类型，是国民教育体系和人力资源开发的重要组成部分，是培养多样化人才、传承技术技能、促进就业创业的重要途径。"},{"i":4,"n":"第四条","txt":"职业教育必须坚持中国共产党的领导，坚持社会主义办学方向，贯彻国家的教育方针，坚持立德树人、德技并修，坚持产教融合、校企合作，坚持面向市场、促进就业，坚持面向实践、强化能力，坚持面向人人、因材施教。"},{"i":5,"n":"第五条","txt":"公民有依法接受职业教育的权利。"},{"i":6,"n":"第六条","txt":"职业教育实行政府统筹、分级管理、地方为主、行业指导、校企合作、社会参与。"},{"i":7,"n":"第七条","txt":"各级人民政府应当将发展职业教育纳入国民经济和社会发展规划，与促进就业创业和推动发展方式转变、产业结构调整、技术优化升级等整体部署、统筹实施。"},{"i":8,"n":"第八条","txt":"国务院建立职业教育工作协调机制，统筹协调全国职业教育工作。"},{"i":9,"n":"第九条","txt":"国家鼓励发展多种层次和形式的职业教育，推进多元办学，支持社会力量广泛、平等参与职业教育。"},{"i":10,"n":"第十条","txt":"国家采取措施，大力发展技工教育，全面提高产业工人素质。"},{"i":11,"n":"第十一条","txt":"实施职业教育应当根据经济社会发展需要，结合职业分类、职业标准、职业发展需求，制定教育标准或者培训方案，实行学历证书及其他学业证书、培训证书、职业资格证书和职业技能等级证书制度。"},{"i":12,"n":"第十二条","txt":"国家采取措施，提高技术技能人才的社会地位和待遇，弘扬劳动光荣、技能宝贵、创造伟大的时代风尚。"},{"i":13,"n":"第十三条","txt":"国家鼓励职业教育领域的对外交流与合作，支持引进境外优质资源发展职业教育，鼓励有条件的职业教育机构赴境外办学，支持开展多种形式的职业教育学习成果互认。"},{"i":14,"n":"第十四条","txt":"国家建立健全适应经济社会发展需要，产教深度融合，职业学校教育和职业培训并重，职业教育与普通教育相互融通，不同层次职业教育有效贯通，服务全民终身学习的现代职业教育体系。"},{"i":15,"n":"第十五条","txt":"职业学校教育分为中等职业学校教育、高等职业学校教育。"},{"i":16,"n":"第十六条","txt":"职业培训包括就业前培训、在职培训、再就业培训及其他职业性培训，可以根据实际情况分级分类实施。"},{"i":17,"n":"第十七条","txt":"国家建立健全各级各类学校教育与职业培训学分、资历以及其他学习成果的认证、积累和转换机制，推进职业教育国家学分银行建设，促进职业教育与普通教育的学习成果融通、互认。"},{"i":18,"n":"第十八条","txt":"残疾人职业教育除由残疾人教育机构实施外，各级各类职业学校和职业培训机构及其他教育机构应当按照国家有关规定接纳残疾学生，并加强无障碍环境建设，为残疾学生学习、生活提供必要的帮助和便利。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府教育行政部门应当鼓励和支持普通中小学、普通高等学校，根据实际需要增加职业教育相关教学内容，进行职业启蒙、职业认知、职业体验，开展职业规划指导、劳动教育，并组织、引导职业学校、职业培训机构、企业和行业组织等提供条件和支持。"},{"i":20,"n":"第二十条","txt":"国务院教育行政部门会同有关部门根据经济社会发展需要和职业教育特点，组织制定、修订职业教育专业目录，完善职业教育教学等标准，宏观管理指导职业学校教材建设。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府应当举办或者参与举办发挥骨干和示范作用的职业学校、职业培训机构，对社会力量依法举办的职业学校和职业培训机构给予指导和扶持。"},{"i":22,"n":"第二十二条","txt":"县级人民政府可以根据县域经济社会发展的需要，设立职业教育中心学校，开展多种形式的职业教育，实施实用技术培训。"},{"i":23,"n":"第二十三条","txt":"行业主管部门按照行业、产业人才需求加强对职业教育的指导，定期发布人才需求信息。"},{"i":24,"n":"第二十四条","txt":"企业应当根据本单位实际，有计划地对本单位的职工和准备招用的人员实施职业教育，并可以设置专职或者兼职实施职业教育的岗位。"},{"i":25,"n":"第二十五条","txt":"企业可以利用资本、技术、知识、设施、设备、场地和管理等要素，举办或者联合举办职业学校、职业培训机构。"},{"i":26,"n":"第二十六条","txt":"国家鼓励、指导、支持企业和其他社会力量依法举办职业学校、职业培训机构。"},{"i":27,"n":"第二十七条","txt":"对深度参与产教融合、校企合作，在提升技术技能人才培养质量、促进就业中发挥重要主体作用的企业，按照规定给予奖励；对符合条件认定为产教融合型企业的，按照规定给予金融、财政、土地等支持，落实教育费附加、地方教育附加减免及其他税费优惠。"},{"i":28,"n":"第二十八条","txt":"联合举办职业学校、职业培训机构的，举办者应当签订联合办学协议，约定各方权利义务。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府应当加强职业教育实习实训基地建设，组织行业主管部门、工会等群团组织、行业组织、企业等根据区域或者行业职业教育的需要建设高水平、专业化、开放共享的产教融合实习实训基地，为职业学校、职业培训机构开展实习实训和企业开展培训提供条件和支持。"},{"i":30,"n":"第三十条","txt":"国家推行中国特色学徒制，引导企业按照岗位总量的一定比例设立学徒岗位，鼓励和支持有技术技能人才培养能力的企业特别是产教融合型企业与职业学校、职业培训机构开展合作，对新招用职工、在岗职工和转岗职工进行学徒培训，或者与职业学校联合招收学生，以工学结合的方式进行学徒培养。有关企业可以按照规定享受补贴。"},{"i":31,"n":"第三十一条","txt":"国家鼓励行业组织、企业等参与职业教育专业教材开发，将新技术、新工艺、新理念纳入职业学校教材，并可以通过活页式教材等多种方式进行动态更新；支持运用信息技术和其他现代化教学方式，开发职业教育网络课程等学习资源，创新教学方式和学校管理方式，推动职业教育信息化建设与融合应用。"},{"i":32,"n":"第三十二条","txt":"国家通过组织开展职业技能竞赛等活动，为技术技能人才提供展示技能、切磋技艺的平台，持续培养更多高素质技术技能人才、能工巧匠和大国工匠。"},{"i":33,"n":"第三十三条","txt":"职业学校的设立，应当符合下列基本条件："},{"i":34,"n":"第三十四条","txt":"职业培训机构的设立，应当符合下列基本条件："},{"i":35,"n":"第三十五条","txt":"公办职业学校实行中国共产党职业学校基层组织领导的校长负责制，中国共产党职业学校基层组织按照中国共产党章程和有关规定，全面领导学校工作，支持校长独立负责地行使职权。民办职业学校依法健全决策机制，强化学校的中国共产党基层组织政治功能，保证其在学校重大事项决策、监督、执行各环节有效发挥作用。"},{"i":36,"n":"第三十六条","txt":"职业学校应当依法办学，依据章程自主管理。"},{"i":37,"n":"第三十七条","txt":"国家建立符合职业教育特点的考试招生制度。"},{"i":38,"n":"第三十八条","txt":"职业学校应当加强校风学风、师德师风建设，营造良好学习环境，保证教育教学质量。"},{"i":39,"n":"第三十九条","txt":"职业学校应当建立健全就业创业促进机制，采取多种形式为学生提供职业规划、职业体验、求职指导等就业创业服务，增强学生就业创业能力。"},{"i":40,"n":"第四十条","txt":"职业学校、职业培训机构实施职业教育应当注重产教融合，实行校企合作。"},{"i":41,"n":"第四十一条","txt":"职业学校、职业培训机构开展校企合作、提供社会服务或者以实习实训为目的举办企业、开展经营活动取得的收入用于改善办学条件；收入的一定比例可以用于支付教师、企业专家、外聘人员和受教育者的劳动报酬，也可以作为绩效工资来源，符合国家规定的可以不受绩效工资总量限制。"},{"i":42,"n":"第四十二条","txt":"职业学校按照规定的收费标准和办法，收取学费和其他必要费用；符合国家规定条件的，应当予以减免；不得以介绍工作、安排实习实训等名义违法收取费用。"},{"i":43,"n":"第四十三条","txt":"职业学校、职业培训机构应当建立健全教育质量评价制度，吸纳行业组织、企业等参与评价，并及时公开相关信息，接受教育督导和社会监督。"},{"i":44,"n":"第四十四条","txt":"国家保障职业教育教师的权利，提高其专业素质与社会地位。"},{"i":45,"n":"第四十五条","txt":"国家建立健全职业教育教师培养培训体系。"},{"i":46,"n":"第四十六条","txt":"国家建立健全符合职业教育特点和发展要求的职业学校教师岗位设置和职务（职称）评聘制度。"},{"i":47,"n":"第四十七条","txt":"国家鼓励职业学校聘请技能大师、劳动模范、能工巧匠、非物质文化遗产代表性传承人等高技能人才，通过担任专职或者兼职专业课教师、设立工作室等方式，参与人才培养、技术开发、技能传承等工作。"},{"i":48,"n":"第四十八条","txt":"国家制定职业学校教职工配备基本标准。省、自治区、直辖市应当根据基本标准，制定本地区职业学校教职工配备标准。"},{"i":49,"n":"第四十九条","txt":"职业学校学生应当遵守法律、法规和学生行为规范，养成良好的职业道德、职业精神和行为习惯，努力学习，完成规定的学习任务，按照要求参加实习实训，掌握技术技能。"},{"i":50,"n":"第五十条","txt":"国家鼓励企业、事业单位安排实习岗位，接纳职业学校和职业培训机构的学生实习。接纳实习的单位应当保障学生在实习期间按照规定享受休息休假、获得劳动安全卫生保护、参加相关保险、接受职业技能指导等权利；对上岗实习的，应当签订实习协议，给予适当的劳动报酬。"},{"i":51,"n":"第五十一条","txt":"接受职业学校教育，达到相应学业要求，经学校考核合格的，取得相应的学业证书；接受职业培训，经职业培训机构或者职业学校考核合格的，取得相应的培训证书；经符合国家规定的专门机构考核合格的，取得相应的职业资格证书或者职业技能等级证书。"},{"i":52,"n":"第五十二条","txt":"国家建立对职业学校学生的奖励和资助制度，对特别优秀的学生进行奖励，对经济困难的学生提供资助，并向艰苦、特殊行业等专业学生适当倾斜。国家根据经济社会发展情况适时调整奖励和资助标准。"},{"i":53,"n":"第五十三条","txt":"职业学校学生在升学、就业、职业发展等方面与同层次普通学校学生享有平等机会。"},{"i":54,"n":"第五十四条","txt":"国家优化教育经费支出结构，使职业教育经费投入与职业教育发展需求相适应，鼓励通过多种渠道依法筹集发展职业教育的资金。"},{"i":55,"n":"第五十五条","txt":"各级人民政府应当按照事权和支出责任相适应的原则，根据职业教育办学规模、培养成本和办学质量等落实职业教育经费，并加强预算绩效管理，提高资金使用效益。"},{"i":56,"n":"第五十六条","txt":"地方各级人民政府安排地方教育附加等方面的经费，应当将其中可用于职业教育的资金统筹使用；发挥失业保险基金作用，支持职工提升职业技能。"},{"i":57,"n":"第五十七条","txt":"各级人民政府加大面向农村的职业教育投入，可以将农村科学技术开发、技术推广的经费适当用于农村职业培训。"},{"i":58,"n":"第五十八条","txt":"企业应当根据国务院规定的标准，按照职工工资总额一定比例提取和使用职工教育经费。职工教育经费可以用于举办职业教育机构、对本单位的职工和准备招用人员进行职业教育等合理用途，其中用于企业一线职工职业教育的经费应当达到国家规定的比例。用人单位安排职工到职业学校或者职业培训机构接受职业教育的，应当在其接受职业教育期间依法支付工资，保障相关待遇。"},{"i":59,"n":"第五十九条","txt":"国家鼓励金融机构通过提供金融服务支持发展职业教育。"},{"i":60,"n":"第六十条","txt":"国家鼓励企业、事业单位、社会组织及公民个人对职业教育捐资助学，鼓励境外的组织和个人对职业教育提供资助和捐赠。提供的资助和捐赠，必须用于职业教育。"},{"i":61,"n":"第六十一条","txt":"国家鼓励和支持开展职业教育的科学技术研究、教材和教学资源开发，推进职业教育资源跨区域、跨行业、跨部门共建共享。"},{"i":62,"n":"第六十二条","txt":"新闻媒体和职业教育有关方面应当积极开展职业教育公益宣传，弘扬技术技能人才成长成才典型事迹，营造人人努力成才、人人皆可成才、人人尽展其才的良好社会氛围。"},{"i":63,"n":"第六十三条","txt":"在职业教育活动中违反《中华人民共和国教育法》、《中华人民共和国劳动法》等有关法律规定的，依照有关法律的规定给予处罚。"},{"i":64,"n":"第六十四条","txt":"企业未依照本法规定对本单位的职工和准备招用的人员实施职业教育、提取和使用职工教育经费的，由有关部门责令改正；拒不改正的，由县级以上人民政府收取其应当承担的职工教育经费，用于职业教育。"},{"i":65,"n":"第六十五条","txt":"职业学校、职业培训机构在职业教育活动中违反本法规定的，由教育行政部门或者其他有关部门责令改正；教育教学质量低下或者管理混乱，造成严重后果的，责令暂停招生、限期整顿；逾期不整顿或者经整顿仍达不到要求的，吊销办学许可证或者责令停止办学。"},{"i":66,"n":"第六十六条","txt":"接纳职业学校和职业培训机构学生实习的单位违反本法规定，侵害学生休息休假、获得劳动安全卫生保护、参加相关保险、接受职业技能指导等权利的，依法承担相应的法律责任。"},{"i":67,"n":"第六十七条","txt":"教育行政部门、人力资源社会保障行政部门或者其他有关部门的工作人员违反本法规定，滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"境外的组织和个人在境内举办职业学校、职业培训机构，适用本法；法律、行政法规另有规定的，从其规定。"},{"i":69,"n":"第六十九条","txt":"本法自2022年5月1日起施行。"}],"yaopinguanlifa":[{"i":1,"n":"第一条","txt":"为了加强药品管理，保证药品质量，保障公众用药安全和合法权益，保护和促进公众健康，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事药品研制、生产、经营、使用和监督管理活动，适用本法。"},{"i":3,"n":"第三条","txt":"药品管理应当以人民健康为中心，坚持风险管理、全程管控、社会共治的原则，建立科学、严格的监督管理制度，全面提升药品质量，保障药品的安全、有效、可及。"},{"i":4,"n":"第四条","txt":"国家发展现代药和传统药，充分发挥其在预防、医疗和保健中的作用。"},{"i":5,"n":"第五条","txt":"国家鼓励研究和创制新药，保护公民、法人和其他组织研究、开发新药的合法权益。"},{"i":6,"n":"第六条","txt":"国家对药品管理实行药品上市许可持有人制度。药品上市许可持有人依法对药品研制、生产、经营、使用全过程中药品的安全性、有效性和质量可控性负责。"},{"i":7,"n":"第七条","txt":"从事药品研制、生产、经营、使用活动，应当遵守法律、法规、规章、标准和规范，保证全过程信息真实、准确、完整和可追溯。"},{"i":8,"n":"第八条","txt":"国务院药品监督管理部门主管全国药品监督管理工作。国务院有关部门在各自职责范围内负责与药品有关的监督管理工作。国务院药品监督管理部门配合国务院有关部门，执行国家药品行业发展规划和产业政策。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府对本行政区域内的药品监督管理工作负责，统一领导、组织、协调本行政区域内的药品监督管理工作以及药品安全突发事件应对工作，建立健全药品监督管理工作机制和信息共享机制。"},{"i":10,"n":"第十条","txt":"县级以上人民政府应当将药品安全工作纳入本级国民经济和社会发展规划，将药品安全工作经费列入本级政府预算，加强药品监督管理能力建设，为药品安全工作提供保障。"},{"i":11,"n":"第十一条","txt":"药品监督管理部门设置或者指定的药品专业技术机构，承担依法实施药品监督管理所需的审评、检验、核查、监测与评价等工作。"},{"i":12,"n":"第十二条","txt":"国家建立健全药品追溯制度。国务院药品监督管理部门应当制定统一的药品追溯标准和规范，推进药品追溯信息互通互享，实现药品可追溯。"},{"i":13,"n":"第十三条","txt":"各级人民政府及其有关部门、药品行业协会等应当加强药品安全宣传教育，开展药品安全法律法规等知识的普及工作。"},{"i":14,"n":"第十四条","txt":"药品行业协会应当加强行业自律，建立健全行业规范，推动行业诚信体系建设，引导和督促会员依法开展药品生产经营等活动。"},{"i":15,"n":"第十五条","txt":"县级以上人民政府及其有关部门对在药品研制、生产、经营、使用和监督管理工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":16,"n":"第十六条","txt":"国家支持以临床价值为导向、对人的疾病具有明确或者特殊疗效的药物创新，鼓励具有新的治疗机理、治疗严重危及生命的疾病或者罕见病、对人体具有多靶向系统性调节干预功能等的新药研制，推动药品技术进步。"},{"i":17,"n":"第十七条","txt":"从事药品研制活动，应当遵守药物非临床研究质量管理规范、药物临床试验质量管理规范，保证药品研制全过程持续符合法定要求。"},{"i":18,"n":"第十八条","txt":"开展药物非临床研究，应当符合国家有关规定，有与研究项目相适应的人员、场地、设备、仪器和管理制度，保证有关数据、资料和样品的真实性。"},{"i":19,"n":"第十九条","txt":"开展药物临床试验，应当按照国务院药品监督管理部门的规定如实报送研制方法、质量指标、药理及毒理试验结果等有关数据、资料和样品，经国务院药品监督管理部门批准。国务院药品监督管理部门应当自受理临床试验申请之日起六十个工作日内决定是否同意并通知临床试验申办者，逾期未通知的，视为同意。其中，开展生物等效性试验的，报国务院药品监督管理部门备案。"},{"i":20,"n":"第二十条","txt":"开展药物临床试验，应当符合伦理原则，制定临床试验方案，经伦理委员会审查同意。"},{"i":21,"n":"第二十一条","txt":"实施药物临床试验，应当向受试者或者其监护人如实说明和解释临床试验的目的和风险等详细情况，取得受试者或者其监护人自愿签署的知情同意书，并采取有效措施保护受试者合法权益。"},{"i":22,"n":"第二十二条","txt":"药物临床试验期间，发现存在安全性问题或者其他风险的，临床试验申办者应当及时调整临床试验方案、暂停或者终止临床试验，并向国务院药品监督管理部门报告。必要时，国务院药品监督管理部门可以责令调整临床试验方案、暂停或者终止临床试验。"},{"i":23,"n":"第二十三条","txt":"对正在开展临床试验的用于治疗严重危及生命且尚无有效治疗手段的疾病的药物，经医学观察可能获益，并且符合伦理原则的，经审查、知情同意后可以在开展临床试验的机构内用于其他病情相同的患者。"},{"i":24,"n":"第二十四条","txt":"在中国境内上市的药品，应当经国务院药品监督管理部门批准，取得药品注册证书；但是，未实施审批管理的中药材和中药饮片除外。实施审批管理的中药材、中药饮片品种目录由国务院药品监督管理部门会同国务院中医药主管部门制定。"},{"i":25,"n":"第二十五条","txt":"对申请注册的药品，国务院药品监督管理部门应当组织药学、医学和其他技术人员进行审评，对药品的安全性、有效性和质量可控性以及申请人的质量管理、风险防控和责任赔偿等能力进行审查；符合条件的，颁发药品注册证书。"},{"i":26,"n":"第二十六条","txt":"对治疗严重危及生命且尚无有效治疗手段的疾病以及公共卫生方面急需的药品，药物临床试验已有数据显示疗效并能预测其临床价值的，可以附条件批准，并在药品注册证书中载明相关事项。"},{"i":27,"n":"第二十七条","txt":"国务院药品监督管理部门应当完善药品审评审批工作制度，加强能力建设，建立健全沟通交流、专家咨询等机制，优化审评审批流程，提高审评审批效率。"},{"i":28,"n":"第二十八条","txt":"药品应当符合国家药品标准。经国务院药品监督管理部门核准的药品质量标准高于国家药品标准的，按照经核准的药品质量标准执行；没有国家药品标准的，应当符合经核准的药品质量标准。"},{"i":29,"n":"第二十九条","txt":"列入国家药品标准的药品名称为药品通用名称。已经作为药品通用名称的，该名称不得作为药品商标使用。"},{"i":30,"n":"第三十条","txt":"药品上市许可持有人是指取得药品注册证书的企业或者药品研制机构等。"},{"i":31,"n":"第三十一条","txt":"药品上市许可持有人应当建立药品质量保证体系，配备专门人员独立负责药品质量管理。"},{"i":32,"n":"第三十二条","txt":"药品上市许可持有人可以自行生产药品，也可以委托药品生产企业生产。"},{"i":33,"n":"第三十三条","txt":"药品上市许可持有人应当建立药品上市放行规程，对药品生产企业出厂放行的药品进行审核，经质量受权人签字后方可放行。不符合国家药品标准的，不得放行。"},{"i":34,"n":"第三十四条","txt":"药品上市许可持有人可以自行销售其取得药品注册证书的药品，也可以委托药品经营企业销售。药品上市许可持有人从事药品零售活动的，应当取得药品经营许可证。"},{"i":35,"n":"第三十五条","txt":"药品上市许可持有人、药品生产企业、药品经营企业委托储存、运输药品的，应当对受托方的质量保证能力和风险管理能力进行评估，与其签订委托协议，约定药品质量责任、操作规程等内容，并对受托方进行监督。"},{"i":36,"n":"第三十六条","txt":"药品上市许可持有人、药品生产企业、药品经营企业和医疗机构应当建立并实施药品追溯制度，按照规定提供追溯信息，保证药品可追溯。"},{"i":37,"n":"第三十七条","txt":"药品上市许可持有人应当建立年度报告制度，每年将药品生产销售、上市后研究、风险管理等情况按照规定向省、自治区、直辖市人民政府药品监督管理部门报告。"},{"i":38,"n":"第三十八条","txt":"药品上市许可持有人为境外企业的，应当由其指定的在中国境内的企业法人履行药品上市许可持有人义务，与药品上市许可持有人承担连带责任。"},{"i":39,"n":"第三十九条","txt":"中药饮片生产企业履行药品上市许可持有人的相关义务，对中药饮片生产、销售实行全过程管理，建立中药饮片追溯体系，保证中药饮片安全、有效、可追溯。"},{"i":40,"n":"第四十条","txt":"经国务院药品监督管理部门批准，药品上市许可持有人可以转让药品上市许可。受让方应当具备保障药品安全性、有效性和质量可控性的质量管理、风险防控和责任赔偿等能力，履行药品上市许可持有人义务。"},{"i":41,"n":"第四十一条","txt":"从事药品生产活动，应当经所在地省、自治区、直辖市人民政府药品监督管理部门批准，取得药品生产许可证。无药品生产许可证的，不得生产药品。"},{"i":42,"n":"第四十二条","txt":"从事药品生产活动，应当具备以下条件："},{"i":43,"n":"第四十三条","txt":"从事药品生产活动，应当遵守药品生产质量管理规范，建立健全药品生产质量管理体系，保证药品生产全过程持续符合法定要求。"},{"i":44,"n":"第四十四条","txt":"药品应当按照国家药品标准和经药品监督管理部门核准的生产工艺进行生产。生产、检验记录应当完整准确，不得编造。"},{"i":45,"n":"第四十五条","txt":"生产药品所需的原料、辅料，应当符合药用要求、药品生产质量管理规范的有关要求。"},{"i":46,"n":"第四十六条","txt":"直接接触药品的包装材料和容器，应当符合药用要求，符合保障人体健康、安全的标准。"},{"i":47,"n":"第四十七条","txt":"药品生产企业应当对药品进行质量检验。不符合国家药品标准的，不得出厂。"},{"i":48,"n":"第四十八条","txt":"药品包装应当适合药品质量的要求，方便储存、运输和医疗使用。"},{"i":49,"n":"第四十九条","txt":"药品包装应当按照规定印有或者贴有标签并附有说明书。"},{"i":50,"n":"第五十条","txt":"药品上市许可持有人、药品生产企业、药品经营企业和医疗机构中直接接触药品的工作人员，应当每年进行健康检查。患有传染病或者其他可能污染药品的疾病的，不得从事直接接触药品的工作。"},{"i":51,"n":"第五十一条","txt":"从事药品批发活动，应当经所在地省、自治区、直辖市人民政府药品监督管理部门批准，取得药品经营许可证。从事药品零售活动，应当经所在地县级以上地方人民政府药品监督管理部门批准，取得药品经营许可证。无药品经营许可证的，不得经营药品。"},{"i":52,"n":"第五十二条","txt":"从事药品经营活动应当具备以下条件："},{"i":53,"n":"第五十三条","txt":"从事药品经营活动，应当遵守药品经营质量管理规范，建立健全药品经营质量管理体系，保证药品经营全过程持续符合法定要求。"},{"i":54,"n":"第五十四条","txt":"国家对药品实行处方药与非处方药分类管理制度。具体办法由国务院药品监督管理部门会同国务院卫生健康主管部门制定。"},{"i":55,"n":"第五十五条","txt":"药品上市许可持有人、药品生产企业、药品经营企业和医疗机构应当从药品上市许可持有人或者具有药品生产、经营资格的企业购进药品；但是，购进未实施审批管理的中药材除外。"},{"i":56,"n":"第五十六条","txt":"药品经营企业购进药品，应当建立并执行进货检查验收制度，验明药品合格证明和其他标识；不符合规定要求的，不得购进和销售。"},{"i":57,"n":"第五十七条","txt":"药品经营企业购销药品，应当有真实、完整的购销记录。购销记录应当注明药品的通用名称、剂型、规格、产品批号、有效期、上市许可持有人、生产企业、购销单位、购销数量、购销价格、购销日期及国务院药品监督管理部门规定的其他内容。"},{"i":58,"n":"第五十八条","txt":"药品经营企业零售药品应当准确无误，并正确说明用法、用量和注意事项；调配处方应当经过核对，对处方所列药品不得擅自更改或者代用。对有配伍禁忌或者超剂量的处方，应当拒绝调配；必要时，经处方医师更正或者重新签字，方可调配。"},{"i":59,"n":"第五十九条","txt":"药品经营企业应当制定和执行药品保管制度，采取必要的冷藏、防冻、防潮、防虫、防鼠等措施，保证药品质量。"},{"i":60,"n":"第六十条","txt":"城乡集市贸易市场可以出售中药材，国务院另有规定的除外。"},{"i":61,"n":"第六十一条","txt":"药品上市许可持有人、药品经营企业通过网络销售药品，应当遵守本法药品经营的有关规定。具体管理办法由国务院药品监督管理部门会同国务院卫生健康主管部门等部门制定。"},{"i":62,"n":"第六十二条","txt":"药品网络交易第三方平台提供者应当按照国务院药品监督管理部门的规定，向所在地省、自治区、直辖市人民政府药品监督管理部门备案。"},{"i":63,"n":"第六十三条","txt":"新发现和从境外引种的药材，经国务院药品监督管理部门批准后，方可销售。"},{"i":64,"n":"第六十四条","txt":"药品应当从允许药品进口的口岸进口，并由进口药品的企业向口岸所在地药品监督管理部门备案。海关凭药品监督管理部门出具的进口药品通关单办理通关手续。无进口药品通关单的，海关不得放行。"},{"i":65,"n":"第六十五条","txt":"医疗机构因临床急需进口少量药品的，经国务院药品监督管理部门或者国务院授权的省、自治区、直辖市人民政府批准，可以进口。进口的药品应当在指定医疗机构内用于特定医疗目的。"},{"i":66,"n":"第六十六条","txt":"进口、出口麻醉药品和国家规定范围内的精神药品，应当持有国务院药品监督管理部门颁发的进口准许证、出口准许证。"},{"i":67,"n":"第六十七条","txt":"禁止进口疗效不确切、不良反应大或者因其他原因危害人体健康的药品。"},{"i":68,"n":"第六十八条","txt":"国务院药品监督管理部门对下列药品在销售前或者进口时，应当指定药品检验机构进行检验；未经检验或者检验不合格的，不得销售或者进口："},{"i":69,"n":"第六十九条","txt":"医疗机构应当配备依法经过资格认定的药师或者其他药学技术人员，负责本单位的药品管理、处方审核和调配、合理用药指导等工作。非药学技术人员不得直接从事药剂技术工作。"},{"i":70,"n":"第七十条","txt":"医疗机构购进药品，应当建立并执行进货检查验收制度，验明药品合格证明和其他标识；不符合规定要求的，不得购进和使用。"},{"i":71,"n":"第七十一条","txt":"医疗机构应当有与所使用药品相适应的场所、设备、仓储设施和卫生环境，制定和执行药品保管制度，采取必要的冷藏、防冻、防潮、防虫、防鼠等措施，保证药品质量。"},{"i":72,"n":"第七十二条","txt":"医疗机构应当坚持安全有效、经济合理的用药原则，遵循药品临床应用指导原则、临床诊疗指南和药品说明书等合理用药，对医师处方、用药医嘱的适宜性进行审核。"},{"i":73,"n":"第七十三条","txt":"依法经过资格认定的药师或者其他药学技术人员调配处方，应当进行核对，对处方所列药品不得擅自更改或者代用。对有配伍禁忌或者超剂量的处方，应当拒绝调配；必要时，经处方医师更正或者重新签字，方可调配。"},{"i":74,"n":"第七十四条","txt":"医疗机构配制制剂，应当经所在地省、自治区、直辖市人民政府药品监督管理部门批准，取得医疗机构制剂许可证。无医疗机构制剂许可证的，不得配制制剂。"},{"i":75,"n":"第七十五条","txt":"医疗机构配制制剂，应当有能够保证制剂质量的设施、管理制度、检验仪器和卫生环境。"},{"i":76,"n":"第七十六条","txt":"医疗机构配制的制剂，应当是本单位临床需要而市场上没有供应的品种，并应当经所在地省、自治区、直辖市人民政府药品监督管理部门批准；但是，法律对配制中药制剂另有规定的除外。"},{"i":77,"n":"第七十七条","txt":"药品上市许可持有人应当制定药品上市后风险管理计划，主动开展药品上市后研究，对药品的安全性、有效性和质量可控性进行进一步确证，加强对已上市药品的持续管理。"},{"i":78,"n":"第七十八条","txt":"对附条件批准的药品，药品上市许可持有人应当采取相应风险管理措施，并在规定期限内按照要求完成相关研究；逾期未按照要求完成研究或者不能证明其获益大于风险的，国务院药品监督管理部门应当依法处理，直至注销药品注册证书。"},{"i":79,"n":"第七十九条","txt":"对药品生产过程中的变更，按照其对药品安全性、有效性和质量可控性的风险和产生影响的程度，实行分类管理。属于重大变更的，应当经国务院药品监督管理部门批准，其他变更应当按照国务院药品监督管理部门的规定备案或者报告。"},{"i":80,"n":"第八十条","txt":"药品上市许可持有人应当开展药品上市后不良反应监测，主动收集、跟踪分析疑似药品不良反应信息，对已识别风险的药品及时采取风险控制措施。"},{"i":81,"n":"第八十一条","txt":"药品上市许可持有人、药品生产企业、药品经营企业和医疗机构应当经常考察本单位所生产、经营、使用的药品质量、疗效和不良反应。发现疑似不良反应的，应当及时向药品监督管理部门和卫生健康主管部门报告。具体办法由国务院药品监督管理部门会同国务院卫生健康主管部门制定。"},{"i":82,"n":"第八十二条","txt":"药品存在质量问题或者其他安全隐患的，药品上市许可持有人应当立即停止销售，告知相关药品经营企业和医疗机构停止销售和使用，召回已销售的药品，及时公开召回信息，必要时应当立即停止生产，并将药品召回和处理情况向省、自治区、直辖市人民政府药品监督管理部门和卫生健康主管部门报告。药品生产企业、药品经营企业和医疗机构应当配合。"},{"i":83,"n":"第八十三条","txt":"药品上市许可持有人应当对已上市药品的安全性、有效性和质量可控性定期开展上市后评价。必要时，国务院药品监督管理部门可以责令药品上市许可持有人开展上市后评价或者直接组织开展上市后评价。"},{"i":84,"n":"第八十四条","txt":"国家完善药品采购管理制度，对药品价格进行监测，开展成本价格调查，加强药品价格监督检查，依法查处价格垄断、哄抬价格等药品价格违法行为，维护药品价格秩序。"},{"i":85,"n":"第八十五条","txt":"依法实行市场调节价的药品，药品上市许可持有人、药品生产企业、药品经营企业和医疗机构应当按照公平、合理和诚实信用、质价相符的原则制定价格，为用药者提供价格合理的药品。"},{"i":86,"n":"第八十六条","txt":"药品上市许可持有人、药品生产企业、药品经营企业和医疗机构应当依法向药品价格主管部门提供其药品的实际购销价格和购销数量等资料。"},{"i":87,"n":"第八十七条","txt":"医疗机构应当向患者提供所用药品的价格清单，按照规定如实公布其常用药品的价格，加强合理用药管理。具体办法由国务院卫生健康主管部门制定。"},{"i":88,"n":"第八十八条","txt":"禁止药品上市许可持有人、药品生产企业、药品经营企业和医疗机构在药品购销中给予、收受回扣或者其他不正当利益。"},{"i":89,"n":"第八十九条","txt":"药品广告应当经广告主所在地省、自治区、直辖市人民政府确定的广告审查机关批准；未经批准的，不得发布。"},{"i":90,"n":"第九十条","txt":"药品广告的内容应当真实、合法，以国务院药品监督管理部门核准的药品说明书为准，不得含有虚假的内容。"},{"i":91,"n":"第九十一条","txt":"药品价格和广告，本法未作规定的，适用《中华人民共和国价格法》、《中华人民共和国反垄断法》、《中华人民共和国反不正当竞争法》、《中华人民共和国广告法》等的规定。"},{"i":92,"n":"第九十二条","txt":"国家实行药品储备制度，建立中央和地方两级药品储备。"},{"i":93,"n":"第九十三条","txt":"国家实行基本药物制度，遴选适当数量的基本药物品种，加强组织生产和储备，提高基本药物的供给能力，满足疾病防治基本用药需求。"},{"i":94,"n":"第九十四条","txt":"国家建立药品供求监测体系，及时收集和汇总分析短缺药品供求信息，对短缺药品实行预警，采取应对措施。"},{"i":95,"n":"第九十五条","txt":"国家实行短缺药品清单管理制度。具体办法由国务院卫生健康主管部门会同国务院药品监督管理部门等部门制定。"},{"i":96,"n":"第九十六条","txt":"国家鼓励短缺药品的研制和生产，对临床急需的短缺药品、防治重大传染病和罕见病等疾病的新药予以优先审评审批。"},{"i":97,"n":"第九十七条","txt":"对短缺药品，国务院可以限制或者禁止出口。必要时，国务院有关部门可以采取组织生产、价格干预和扩大进口等措施，保障药品供应。"},{"i":98,"n":"第九十八条","txt":"禁止生产（包括配制，下同）、销售、使用假药、劣药。"},{"i":99,"n":"第九十九条","txt":"药品监督管理部门应当依照法律、法规的规定对药品研制、生产、经营和药品使用单位使用药品等活动进行监督检查，必要时可以对为药品研制、生产、经营、使用提供产品或者服务的单位和个人进行延伸检查，有关单位和个人应当予以配合，不得拒绝和隐瞒。"},{"i":100,"n":"第一百条","txt":"药品监督管理部门根据监督管理的需要，可以对药品质量进行抽查检验。抽查检验应当按照规定抽样，并不得收取任何费用；抽样应当购买样品。所需费用按照国务院规定列支。"},{"i":101,"n":"第一百零一条","txt":"国务院和省、自治区、直辖市人民政府的药品监督管理部门应当定期公告药品质量抽查检验结果；公告不当的，应当在原公告范围内予以更正。"},{"i":102,"n":"第一百零二条","txt":"当事人对药品检验结果有异议的，可以自收到药品检验结果之日起七日内向原药品检验机构或者上一级药品监督管理部门设置或者指定的药品检验机构申请复验，也可以直接向国务院药品监督管理部门设置或者指定的药品检验机构申请复验。受理复验的药品检验机构应当在国务院药品监督管理部门规定的时间内作出复验结论。"},{"i":103,"n":"第一百零三条","txt":"药品监督管理部门应当对药品上市许可持有人、药品生产企业、药品经营企业和药物非临床安全性评价研究机构、药物临床试验机构等遵守药品生产质量管理规范、药品经营质量管理规范、药物非临床研究质量管理规范、药物临床试验质量管理规范等情况进行检查，监督其持续符合法定要求。"},{"i":104,"n":"第一百零四条","txt":"国家建立职业化、专业化药品检查员队伍。检查员应当熟悉药品法律法规，具备药品专业知识。"},{"i":105,"n":"第一百零五条","txt":"药品监督管理部门建立药品上市许可持有人、药品生产企业、药品经营企业、药物非临床安全性评价研究机构、药物临床试验机构和医疗机构药品安全信用档案，记录许可颁发、日常监督检查结果、违法行为查处等情况，依法向社会公布并及时更新；对有不良信用记录的，增加监督检查频次，并可以按照国家规定实施联合惩戒。"},{"i":106,"n":"第一百零六条","txt":"药品监督管理部门应当公布本部门的电子邮件地址、电话，接受咨询、投诉、举报，并依法及时答复、核实、处理。对查证属实的举报，按照有关规定给予举报人奖励。"},{"i":107,"n":"第一百零七条","txt":"国家实行药品安全信息统一公布制度。国家药品安全总体情况、药品安全风险警示信息、重大药品安全事件及其调查处理信息和国务院确定需要统一公布的其他信息由国务院药品监督管理部门统一公布。药品安全风险警示信息和重大药品安全事件及其调查处理信息的影响限于特定区域的，也可以由有关省、自治区、直辖市人民政府药品监督管理部门公布。未经授权不得发布上述信息。"},{"i":108,"n":"第一百零八条","txt":"县级以上人民政府应当制定药品安全事件应急预案。药品上市许可持有人、药品生产企业、药品经营企业和医疗机构等应当制定本单位的药品安全事件处置方案，并组织开展培训和应急演练。"},{"i":109,"n":"第一百零九条","txt":"药品监督管理部门未及时发现药品安全系统性风险，未及时消除监督管理区域内药品安全隐患的，本级人民政府或者上级人民政府药品监督管理部门应当对其主要负责人进行约谈。"},{"i":110,"n":"第一百一十条","txt":"地方人民政府及其药品监督管理部门不得以要求实施药品检验、审批等手段限制或者排斥非本地区药品上市许可持有人、药品生产企业生产的药品进入本地区。"},{"i":111,"n":"第一百一十一条","txt":"药品监督管理部门及其设置或者指定的药品专业技术机构不得参与药品生产经营活动，不得以其名义推荐或者监制、监销药品。"},{"i":112,"n":"第一百一十二条","txt":"国务院对麻醉药品、精神药品、医疗用毒性药品、放射性药品、药品类易制毒化学品等有其他特殊管理规定的，依照其规定。"},{"i":113,"n":"第一百一十三条","txt":"药品监督管理部门发现药品违法行为涉嫌犯罪的，应当及时将案件移送公安机关。"},{"i":114,"n":"第一百一十四条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":115,"n":"第一百一十五条","txt":"未取得药品生产许可证、药品经营许可证或者医疗机构制剂许可证生产、销售药品的，责令关闭，没收违法生产、销售的药品和违法所得，并处违法生产、销售的药品（包括已售出和未售出的药品，下同）货值金额十五倍以上三十倍以下的罚款；货值金额不足十万元的，按十万元计算。"},{"i":116,"n":"第一百一十六条","txt":"生产、销售假药的，没收违法生产、销售的药品和违法所得，责令停产停业整顿，吊销药品批准证明文件，并处违法生产、销售的药品货值金额十五倍以上三十倍以下的罚款；货值金额不足十万元的，按十万元计算；情节严重的，吊销药品生产许可证、药品经营许可证或者医疗机构制剂许可证，十年内不受理其相应申请；药品上市许可持有人为境外企业的，十年内禁止其药品进口。"},{"i":117,"n":"第一百一十七条","txt":"生产、销售劣药的，没收违法生产、销售的药品和违法所得，并处违法生产、销售的药品货值金额十倍以上二十倍以下的罚款；违法生产、批发的药品货值金额不足十万元的，按十万元计算，违法零售的药品货值金额不足一万元的，按一万元计算；情节严重的，责令停产停业整顿直至吊销药品批准证明文件、药品生产许可证、药品经营许可证或者医疗机构制剂许可证。"},{"i":118,"n":"第一百一十八条","txt":"生产、销售假药，或者生产、销售劣药且情节严重的，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入百分之三十以上三倍以下的罚款，终身禁止从事药品生产经营活动，并可以由公安机关处五日以上十五日以下的拘留。"},{"i":119,"n":"第一百一十九条","txt":"药品使用单位使用假药、劣药的，按照销售假药、零售劣药的规定处罚；情节严重的，法定代表人、主要负责人、直接负责的主管人员和其他责任人员有医疗卫生人员执业证书的，还应当吊销执业证书。"},{"i":120,"n":"第一百二十条","txt":"知道或者应当知道属于假药、劣药或者本法第一百二十四条第一款第一项至第五项规定的药品，而为其提供储存、运输等便利条件的，没收全部储存、运输收入，并处违法收入一倍以上五倍以下的罚款；情节严重的，并处违法收入五倍以上十五倍以下的罚款；违法收入不足五万元的，按五万元计算。"},{"i":121,"n":"第一百二十一条","txt":"对假药、劣药的处罚决定，应当依法载明药品检验机构的质量检验结论。"},{"i":122,"n":"第一百二十二条","txt":"伪造、变造、出租、出借、非法买卖许可证或者药品批准证明文件的，没收违法所得，并处违法所得一倍以上五倍以下的罚款；情节严重的，并处违法所得五倍以上十五倍以下的罚款，吊销药品生产许可证、药品经营许可证、医疗机构制剂许可证或者药品批准证明文件，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员，处二万元以上二十万元以下的罚款，十年内禁止从事药品生产经营活动，并可以由公安机关处五日以上十五日以下的拘留；违法所得不足十万元的，按十万元计算。"},{"i":123,"n":"第一百二十三条","txt":"提供虚假的证明、数据、资料、样品或者采取其他手段骗取临床试验许可、药品生产许可、药品经营许可、医疗机构制剂许可或者药品注册等许可的，撤销相关许可，十年内不受理其相应申请，并处五十万元以上五百万元以下的罚款；情节严重的，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员，处二万元以上二十万元以下的罚款，十年内禁止从事药品生产经营活动，并可以由公安机关处五日以上十五日以下的拘留。"},{"i":124,"n":"第一百二十四条","txt":"违反本法规定，有下列行为之一的，没收违法生产、进口、销售的药品和违法所得以及专门用于违法生产的原料、辅料、包装材料和生产设备，责令停产停业整顿，并处违法生产、进口、销售的药品货值金额十五倍以上三十倍以下的罚款；货值金额不足十万元的，按十万元计算；情节严重的，吊销药品批准证明文件直至吊销药品生产许可证、药品经营许可证或者医疗机构制剂许可证，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入百分之三十以上三倍以下的罚款，十年直至终身禁止从事药品生产经营活动，并可以由公安机关处五日以上十五日以下的拘留："},{"i":125,"n":"第一百二十五条","txt":"违反本法规定，有下列行为之一的，没收违法生产、销售的药品和违法所得以及包装材料、容器，责令停产停业整顿，并处五十万元以上五百万元以下的罚款；情节严重的，吊销药品批准证明文件、药品生产许可证、药品经营许可证，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员处二万元以上二十万元以下的罚款，十年直至终身禁止从事药品生产经营活动："},{"i":126,"n":"第一百二十六条","txt":"除本法另有规定的情形外，药品上市许可持有人、药品生产企业、药品经营企业、药物非临床安全性评价研究机构、药物临床试验机构等未遵守药品生产质量管理规范、药品经营质量管理规范、药物非临床研究质量管理规范、药物临床试验质量管理规范等的，责令限期改正，给予警告；逾期不改正的，处十万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款，责令停产停业整顿直至吊销药品批准证明文件、药品生产许可证、药品经营许可证等，药物非临床安全性评价研究机构、药物临床试验机构等五年内不得开展药物非临床安全性评价研究、药物临床试验，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员，没收违法行为发生期间自本单位所获收入，并处所获收入百分之十以上百分之五十以下的罚款，十年直至终身禁止从事药品生产经营等活动。"},{"i":127,"n":"第一百二十七条","txt":"违反本法规定，有下列行为之一的，责令限期改正，给予警告；逾期不改正的，处十万元以上五十万元以下的罚款："},{"i":128,"n":"第一百二十八条","txt":"除依法应当按照假药、劣药处罚的外，药品包装未按照规定印有、贴有标签或者附有说明书，标签、说明书未按照规定注明相关信息或者印有规定标志的，责令改正，给予警告；情节严重的，吊销药品注册证书。"},{"i":129,"n":"第一百二十九条","txt":"违反本法规定，药品上市许可持有人、药品生产企业、药品经营企业或者医疗机构未从药品上市许可持有人或者具有药品生产、经营资格的企业购进药品的，责令改正，没收违法购进的药品和违法所得，并处违法购进药品货值金额二倍以上十倍以下的罚款；情节严重的，并处货值金额十倍以上三十倍以下的罚款，吊销药品批准证明文件、药品生产许可证、药品经营许可证或者医疗机构执业许可证；货值金额不足五万元的，按五万元计算。"},{"i":130,"n":"第一百三十条","txt":"违反本法规定，药品经营企业购销药品未按照规定进行记录，零售药品未正确说明用法、用量等事项，或者未按照规定调配处方的，责令改正，给予警告；情节严重的，吊销药品经营许可证。"},{"i":131,"n":"第一百三十一条","txt":"违反本法规定，药品网络交易第三方平台提供者未履行资质审核、报告、停止提供网络交易平台服务等义务的，责令改正，没收违法所得，并处二十万元以上二百万元以下的罚款；情节严重的，责令停业整顿，并处二百万元以上五百万元以下的罚款。"},{"i":132,"n":"第一百三十二条","txt":"进口已获得药品注册证书的药品，未按照规定向允许药品进口的口岸所在地药品监督管理部门备案的，责令限期改正，给予警告；逾期不改正的，吊销药品注册证书。"},{"i":133,"n":"第一百三十三条","txt":"违反本法规定，医疗机构将其配制的制剂在市场上销售的，责令改正，没收违法销售的制剂和违法所得，并处违法销售制剂货值金额二倍以上五倍以下的罚款；情节严重的，并处货值金额五倍以上十五倍以下的罚款；货值金额不足五万元的，按五万元计算。"},{"i":134,"n":"第一百三十四条","txt":"药品上市许可持有人未按照规定开展药品不良反应监测或者报告疑似药品不良反应的，责令限期改正，给予警告；逾期不改正的，责令停产停业整顿，并处十万元以上一百万元以下的罚款。"},{"i":135,"n":"第一百三十五条","txt":"药品上市许可持有人在省、自治区、直辖市人民政府药品监督管理部门责令其召回后，拒不召回的，处应召回药品货值金额五倍以上十倍以下的罚款；货值金额不足十万元的，按十万元计算；情节严重的，吊销药品批准证明文件、药品生产许可证、药品经营许可证，对法定代表人、主要负责人、直接负责的主管人员和其他责任人员，处二万元以上二十万元以下的罚款。药品生产企业、药品经营企业、医疗机构拒不配合召回的，处十万元以上五十万元以下的罚款。"},{"i":136,"n":"第一百三十六条","txt":"药品上市许可持有人为境外企业的，其指定的在中国境内的企业法人未依照本法规定履行相关义务的，适用本法有关药品上市许可持有人法律责任的规定。"},{"i":137,"n":"第一百三十七条","txt":"有下列行为之一的，在本法规定的处罚幅度内从重处罚："},{"i":138,"n":"第一百三十八条","txt":"药品检验机构出具虚假检验报告的，责令改正，给予警告，对单位并处二十万元以上一百万元以下的罚款；对直接负责的主管人员和其他直接责任人员依法给予降级、撤职、开除处分，没收违法所得，并处五万元以下的罚款；情节严重的，撤销其检验资格。药品检验机构出具的检验结果不实，造成损失的，应当承担相应的赔偿责任。"},{"i":139,"n":"第一百三十九条","txt":"本法第一百一十五条至第一百三十八条规定的行政处罚，由县级以上人民政府药品监督管理部门按照职责分工决定；撤销许可、吊销许可证件的，由原批准、发证的部门决定。"},{"i":140,"n":"第一百四十条","txt":"药品上市许可持有人、药品生产企业、药品经营企业或者医疗机构违反本法规定聘用人员的，由药品监督管理部门或者卫生健康主管部门责令解聘，处五万元以上二十万元以下的罚款。"},{"i":141,"n":"第一百四十一条","txt":"药品上市许可持有人、药品生产企业、药品经营企业或者医疗机构在药品购销中给予、收受回扣或者其他不正当利益的，药品上市许可持有人、药品生产企业、药品经营企业或者代理人给予使用其药品的医疗机构的负责人、药品采购人员、医师、药师等有关人员财物或者其他不正当利益的，由市场监督管理部门没收违法所得，并处三十万元以上三百万元以下的罚款；情节严重的，吊销药品上市许可持有人、药品生产企业、药品经营企业营业执照，并由药品监督管理部门吊销药品批准证明文件、药品生产许可证、药品经营许可证。"},{"i":142,"n":"第一百四十二条","txt":"药品上市许可持有人、药品生产企业、药品经营企业的负责人、采购人员等有关人员在药品购销中收受其他药品上市许可持有人、药品生产企业、药品经营企业或者代理人给予的财物或者其他不正当利益的，没收违法所得，依法给予处罚；情节严重的，五年内禁止从事药品生产经营活动。"},{"i":143,"n":"第一百四十三条","txt":"违反本法规定，编造、散布虚假药品安全信息，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":144,"n":"第一百四十四条","txt":"药品上市许可持有人、药品生产企业、药品经营企业或者医疗机构违反本法规定，给用药者造成损害的，依法承担赔偿责任。"},{"i":145,"n":"第一百四十五条","txt":"药品监督管理部门或者其设置、指定的药品专业技术机构参与药品生产经营活动的，由其上级主管机关责令改正，没收违法收入；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":146,"n":"第一百四十六条","txt":"药品监督管理部门或者其设置、指定的药品检验机构在药品监督检验中违法收取检验费用的，由政府有关部门责令退还，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重的，撤销其检验资格。"},{"i":147,"n":"第一百四十七条","txt":"违反本法规定，药品监督管理部门有下列行为之一的，应当撤销相关许可，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":148,"n":"第一百四十八条","txt":"违反本法规定，县级以上地方人民政府有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记过或者记大过处分；情节严重的，给予降级、撤职或者开除处分："},{"i":149,"n":"第一百四十九条","txt":"违反本法规定，药品监督管理等部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":150,"n":"第一百五十条","txt":"药品监督管理人员滥用职权、徇私舞弊、玩忽职守的，依法给予处分。"},{"i":151,"n":"第一百五十一条","txt":"本章规定的货值金额以违法生产、销售药品的标价计算；没有标价的，按照同类药品的市场价格计算。"},{"i":152,"n":"第一百五十二条","txt":"中药材种植、采集和饲养的管理，依照有关法律、法规的规定执行。"},{"i":153,"n":"第一百五十三条","txt":"地区性民间习用药材的管理办法，由国务院药品监督管理部门会同国务院中医药主管部门制定。"},{"i":154,"n":"第一百五十四条","txt":"中国人民解放军和中国人民武装警察部队执行本法的具体办法，由国务院、中央军事委员会依据本法制定。"},{"i":155,"n":"第一百五十五条","txt":"本法自2019年12月1日起施行。"}],"xingzhengchufafa":[{"i":1,"n":"第一条","txt":"为了规范行政处罚的设定和实施，保障和监督行政机关有效实施行政管理，维护公共利益和社会秩序，保护公民、法人或者其他组织的合法权益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"行政处罚是指行政机关依法对违反行政管理秩序的公民、法人或者其他组织，以减损权益或者增加义务的方式予以惩戒的行为。"},{"i":3,"n":"第三条","txt":"行政处罚的设定和实施，适用本法。"},{"i":4,"n":"第四条","txt":"公民、法人或者其他组织违反行政管理秩序的行为，应当给予行政处罚的，依照本法由法律、法规、规章规定，并由行政机关依照本法规定的程序实施。"},{"i":5,"n":"第五条","txt":"行政处罚遵循公正、公开的原则。"},{"i":6,"n":"第六条","txt":"实施行政处罚，纠正违法行为，应当坚持处罚与教育相结合，教育公民、法人或者其他组织自觉守法。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织对行政机关所给予的行政处罚，享有陈述权、申辩权；对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织因违法行为受到行政处罚，其违法行为对他人造成损害的，应当依法承担民事责任。"},{"i":9,"n":"第九条","txt":"行政处罚的种类："},{"i":10,"n":"第十条","txt":"法律可以设定各种行政处罚。"},{"i":11,"n":"第十一条","txt":"行政法规可以设定除限制人身自由以外的行政处罚。"},{"i":12,"n":"第十二条","txt":"地方性法规可以设定除限制人身自由、吊销营业执照以外的行政处罚。"},{"i":13,"n":"第十三条","txt":"国务院部门规章可以在法律、行政法规规定的给予行政处罚的行为、种类和幅度的范围内作出具体规定。"},{"i":14,"n":"第十四条","txt":"地方政府规章可以在法律、法规规定的给予行政处罚的行为、种类和幅度的范围内作出具体规定。"},{"i":15,"n":"第十五条","txt":"国务院部门和省、自治区、直辖市人民政府及其有关部门应当定期组织评估行政处罚的实施情况和必要性，对不适当的行政处罚事项及种类、罚款数额等，应当提出修改或者废止的建议。"},{"i":16,"n":"第十六条","txt":"除法律、法规、规章外，其他规范性文件不得设定行政处罚。"},{"i":17,"n":"第十七条","txt":"行政处罚由具有行政处罚权的行政机关在法定职权范围内实施。"},{"i":18,"n":"第十八条","txt":"国家在城市管理、市场监管、生态环境、文化市场、交通运输、应急管理、农业等领域推行建立综合行政执法制度，相对集中行政处罚权。"},{"i":19,"n":"第十九条","txt":"法律、法规授权的具有管理公共事务职能的组织可以在法定授权范围内实施行政处罚。"},{"i":20,"n":"第二十条","txt":"行政机关依照法律、法规、规章的规定，可以在其法定权限内书面委托符合本法第二十一条规定条件的组织实施行政处罚。行政机关不得委托其他组织或者个人实施行政处罚。"},{"i":21,"n":"第二十一条","txt":"受委托组织必须符合以下条件："},{"i":22,"n":"第二十二条","txt":"行政处罚由违法行为发生地的行政机关管辖。法律、行政法规、部门规章另有规定的，从其规定。"},{"i":23,"n":"第二十三条","txt":"行政处罚由县级以上地方人民政府具有行政处罚权的行政机关管辖。法律、行政法规另有规定的，从其规定。"},{"i":24,"n":"第二十四条","txt":"省、自治区、直辖市根据当地实际情况，可以决定将基层管理迫切需要的县级人民政府部门的行政处罚权交由能够有效承接的乡镇人民政府、街道办事处行使，并定期组织评估。决定应当公布。"},{"i":25,"n":"第二十五条","txt":"两个以上行政机关都有管辖权的，由最先立案的行政机关管辖。"},{"i":26,"n":"第二十六条","txt":"行政机关因实施行政处罚的需要，可以向有关机关提出协助请求。协助事项属于被请求机关职权范围内的，应当依法予以协助。"},{"i":27,"n":"第二十七条","txt":"违法行为涉嫌犯罪的，行政机关应当及时将案件移送司法机关，依法追究刑事责任。对依法不需要追究刑事责任或者免予刑事处罚，但应当给予行政处罚的，司法机关应当及时将案件移送有关行政机关。"},{"i":28,"n":"第二十八条","txt":"行政机关实施行政处罚时，应当责令当事人改正或者限期改正违法行为。"},{"i":29,"n":"第二十九条","txt":"对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚。同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。"},{"i":30,"n":"第三十条","txt":"不满十四周岁的未成年人有违法行为的，不予行政处罚，责令监护人加以管教；已满十四周岁不满十八周岁的未成年人有违法行为的，应当从轻或者减轻行政处罚。"},{"i":31,"n":"第三十一条","txt":"精神病人、智力残疾人在不能辨认或者不能控制自己行为时有违法行为的，不予行政处罚，但应当责令其监护人严加看管和治疗。间歇性精神病人在精神正常时有违法行为的，应当给予行政处罚。尚未完全丧失辨认或者控制自己行为能力的精神病人、智力残疾人有违法行为的，可以从轻或者减轻行政处罚。"},{"i":32,"n":"第三十二条","txt":"当事人有下列情形之一，应当从轻或者减轻行政处罚："},{"i":33,"n":"第三十三条","txt":"违法行为轻微并及时改正，没有造成危害后果的，不予行政处罚。初次违法且危害后果轻微并及时改正的，可以不予行政处罚。"},{"i":34,"n":"第三十四条","txt":"行政机关可以依法制定行政处罚裁量基准，规范行使行政处罚裁量权。行政处罚裁量基准应当向社会公布。"},{"i":35,"n":"第三十五条","txt":"违法行为构成犯罪，人民法院判处拘役或者有期徒刑时，行政机关已经给予当事人行政拘留的，应当依法折抵相应刑期。"},{"i":36,"n":"第三十六条","txt":"违法行为在二年内未被发现的，不再给予行政处罚；涉及公民生命健康安全、金融安全且有危害后果的，上述期限延长至五年。法律另有规定的除外。"},{"i":37,"n":"第三十七条","txt":"实施行政处罚，适用违法行为发生时的法律、法规、规章的规定。但是，作出行政处罚决定时，法律、法规、规章已被修改或者废止，且新的规定处罚较轻或者不认为是违法的，适用新的规定。"},{"i":38,"n":"第三十八条","txt":"行政处罚没有依据或者实施主体不具有行政主体资格的，行政处罚无效。"},{"i":39,"n":"第三十九条","txt":"行政处罚的实施机关、立案依据、实施程序和救济渠道等信息应当公示。"},{"i":40,"n":"第四十条","txt":"公民、法人或者其他组织违反行政管理秩序的行为，依法应当给予行政处罚的，行政机关必须查明事实；违法事实不清、证据不足的，不得给予行政处罚。"},{"i":41,"n":"第四十一条","txt":"行政机关依照法律、行政法规规定利用电子技术监控设备收集、固定违法事实的，应当经过法制和技术审核，确保电子技术监控设备符合标准、设置合理、标志明显，设置地点应当向社会公布。"},{"i":42,"n":"第四十二条","txt":"行政处罚应当由具有行政执法资格的执法人员实施。执法人员不得少于两人，法律另有规定的除外。"},{"i":43,"n":"第四十三条","txt":"执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当回避。"},{"i":44,"n":"第四十四条","txt":"行政机关在作出行政处罚决定之前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩、要求听证等权利。"},{"i":45,"n":"第四十五条","txt":"当事人有权进行陈述和申辩。行政机关必须充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由或者证据成立的，行政机关应当采纳。"},{"i":46,"n":"第四十六条","txt":"证据包括："},{"i":47,"n":"第四十七条","txt":"行政机关应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，归档保存。"},{"i":48,"n":"第四十八条","txt":"具有一定社会影响的行政处罚决定应当依法公开。"},{"i":49,"n":"第四十九条","txt":"发生重大传染病疫情等突发事件，为了控制、减轻和消除突发事件引起的社会危害，行政机关对违反突发事件应对措施的行为，依法快速、从重处罚。"},{"i":50,"n":"第五十条","txt":"行政机关及其工作人员对实施行政处罚过程中知悉的国家秘密、商业秘密或者个人隐私，应当依法予以保密。"},{"i":51,"n":"第五十一条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定。法律另有规定的，从其规定。"},{"i":52,"n":"第五十二条","txt":"执法人员当场作出行政处罚决定的，应当向当事人出示执法证件，填写预定格式、编有号码的行政处罚决定书，并当场交付当事人。当事人拒绝签收的，应当在行政处罚决定书上注明。"},{"i":53,"n":"第五十三条","txt":"对当场作出的行政处罚决定，当事人应当依照本法第六十七条至第六十九条的规定履行。"},{"i":54,"n":"第五十四条","txt":"除本法第五十一条规定的可以当场作出的行政处罚外，行政机关发现公民、法人或者其他组织有依法应当给予行政处罚的行为的，必须全面、客观、公正地调查，收集有关证据；必要时，依照法律、法规的规定，可以进行检查。"},{"i":55,"n":"第五十五条","txt":"执法人员在调查或者进行检查时，应当主动向当事人或者有关人员出示执法证件。当事人或者有关人员有权要求执法人员出示执法证件。执法人员不出示执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。"},{"i":56,"n":"第五十六条","txt":"行政机关在收集证据时，可以采取抽样取证的方法；在证据可能灭失或者以后难以取得的情况下，经行政机关负责人批准，可以先行登记保存，并应当在七日内及时作出处理决定，在此期间，当事人或者有关人员不得销毁或者转移证据。"},{"i":57,"n":"第五十七条","txt":"调查终结，行政机关负责人应当对调查结果进行审查，根据不同情况，分别作出如下决定："},{"i":58,"n":"第五十八条","txt":"有下列情形之一，在行政机关负责人作出行政处罚的决定之前，应当由从事行政处罚决定法制审核的人员进行法制审核；未经法制审核或者审核未通过的，不得作出决定："},{"i":59,"n":"第五十九条","txt":"行政机关依照本法第五十七条的规定给予行政处罚，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项："},{"i":60,"n":"第六十条","txt":"行政机关应当自行政处罚案件立案之日起九十日内作出行政处罚决定。法律、法规、规章另有规定的，从其规定。"},{"i":61,"n":"第六十一条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，行政机关应当在七日内依照《中华人民共和国民事诉讼法》的有关规定，将行政处罚决定书送达当事人。"},{"i":62,"n":"第六十二条","txt":"行政机关及其执法人员在作出行政处罚决定之前，未依照本法第四十四条、第四十五条的规定向当事人告知拟作出的行政处罚内容及事实、理由、依据，或者拒绝听取当事人的陈述、申辩，不得作出行政处罚决定；当事人明确放弃陈述或者申辩权利的除外。"},{"i":63,"n":"第六十三条","txt":"行政机关拟作出下列行政处罚决定，应当告知当事人有要求听证的权利，当事人要求听证的，行政机关应当组织听证："},{"i":64,"n":"第六十四条","txt":"听证应当依照以下程序组织："},{"i":65,"n":"第六十五条","txt":"听证结束后，行政机关应当根据听证笔录，依照本法第五十七条的规定，作出决定。"},{"i":66,"n":"第六十六条","txt":"行政处罚决定依法作出后，当事人应当在行政处罚决定书载明的期限内，予以履行。"},{"i":67,"n":"第六十七条","txt":"作出罚款决定的行政机关应当与收缴罚款的机构分离。"},{"i":68,"n":"第六十八条","txt":"依照本法第五十一条的规定当场作出行政处罚决定，有下列情形之一，执法人员可以当场收缴罚款："},{"i":69,"n":"第六十九条","txt":"在边远、水上、交通不便地区，行政机关及其执法人员依照本法第五十一条、第五十七条的规定作出罚款决定后，当事人到指定的银行或者通过电子支付系统缴纳罚款确有困难，经当事人提出，行政机关及其执法人员可以当场收缴罚款。"},{"i":70,"n":"第七十条","txt":"行政机关及其执法人员当场收缴罚款的，必须向当事人出具国务院财政部门或者省、自治区、直辖市人民政府财政部门统一制发的专用票据；不出具财政部门统一制发的专用票据的，当事人有权拒绝缴纳罚款。"},{"i":71,"n":"第七十一条","txt":"执法人员当场收缴的罚款，应当自收缴罚款之日起二日内，交至行政机关；在水上当场收缴的罚款，应当自抵岸之日起二日内交至行政机关；行政机关应当在二日内将罚款缴付指定的银行。"},{"i":72,"n":"第七十二条","txt":"当事人逾期不履行行政处罚决定的，作出行政处罚决定的行政机关可以采取下列措施："},{"i":73,"n":"第七十三条","txt":"当事人对行政处罚决定不服，申请行政复议或者提起行政诉讼的，行政处罚不停止执行，法律另有规定的除外。"},{"i":74,"n":"第七十四条","txt":"除依法应当予以销毁的物品外，依法没收的非法财物必须按照国家规定公开拍卖或者按照国家有关规定处理。"},{"i":75,"n":"第七十五条","txt":"行政机关应当建立健全对行政处罚的监督制度。县级以上人民政府应当定期组织开展行政执法评议、考核，加强对行政处罚的监督检查，规范和保障行政处罚的实施。"},{"i":76,"n":"第七十六条","txt":"行政机关实施行政处罚，有下列情形之一，由上级行政机关或者有关机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":77,"n":"第七十七条","txt":"行政机关对当事人进行处罚不使用罚款、没收财物单据或者使用非法定部门制发的罚款、没收财物单据的，当事人有权拒绝，并有权予以检举，由上级行政机关或者有关机关对使用的非法单据予以收缴销毁，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":78,"n":"第七十八条","txt":"行政机关违反本法第六十七条的规定自行收缴罚款的，财政部门违反本法第七十四条的规定向行政机关返还罚款、没收的违法所得或者拍卖款项的，由上级行政机关或者有关机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":79,"n":"第七十九条","txt":"行政机关截留、私分或者变相私分罚款、没收的违法所得或者财物的，由财政部门或者有关机关予以追缴，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":80,"n":"第八十条","txt":"行政机关使用或者损毁查封、扣押的财物，对当事人造成损失的，应当依法予以赔偿，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":81,"n":"第八十一条","txt":"行政机关违法实施检查措施或者执行措施，给公民人身或者财产造成损害、给法人或者其他组织造成损失的，应当依法予以赔偿，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":82,"n":"第八十二条","txt":"行政机关对应当依法移交司法机关追究刑事责任的案件不移交，以行政处罚代替刑事处罚，由上级行政机关或者有关机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":83,"n":"第八十三条","txt":"行政机关对应当予以制止和处罚的违法行为不予制止、处罚，致使公民、法人或者其他组织的合法权益、公共利益和社会秩序遭受损害的，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":84,"n":"第八十四条","txt":"外国人、无国籍人、外国组织在中华人民共和国领域内有违法行为，应当给予行政处罚的，适用本法，法律另有规定的除外。"},{"i":85,"n":"第八十五条","txt":"本法中“二日”“三日”“五日”“七日”的规定是指工作日，不含法定节假日。"},{"i":86,"n":"第八十六条","txt":"本法自2021年7月15日起施行。"}],"xingzhengfuyifa":[{"i":1,"n":"第一条","txt":"为了防止和纠正违法的或者不当的行政行为，保护公民、法人和其他组织的合法权益，监督和保障行政机关依法行使职权，发挥行政复议化解行政争议的主渠道作用，推进法治政府建设，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为行政机关的行政行为侵犯其合法权益，向行政复议机关提出行政复议申请，行政复议机关办理行政复议案件，适用本法。"},{"i":3,"n":"第三条","txt":"行政复议工作坚持中国共产党的领导。"},{"i":4,"n":"第四条","txt":"县级以上各级人民政府以及其他依照本法履行行政复议职责的行政机关是行政复议机关。"},{"i":5,"n":"第五条","txt":"行政复议机关办理行政复议案件，可以进行调解。"},{"i":6,"n":"第六条","txt":"国家建立专业化、职业化行政复议人员队伍。"},{"i":7,"n":"第七条","txt":"行政复议机关应当确保行政复议机构的人员配备与所承担的工作任务相适应，提高行政复议人员专业素质，根据工作需要保障办案场所、装备等设施。县级以上各级人民政府应当将行政复议工作经费列入本级预算。"},{"i":8,"n":"第八条","txt":"行政复议机关应当加强信息化建设，运用现代信息技术，方便公民、法人或者其他组织申请、参加行政复议，提高工作质量和效率。"},{"i":9,"n":"第九条","txt":"对在行政复议工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":10,"n":"第十条","txt":"公民、法人或者其他组织对行政复议决定不服的，可以依照《中华人民共和国行政诉讼法》的规定向人民法院提起行政诉讼，但是法律规定行政复议决定为最终裁决的除外。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议："},{"i":12,"n":"第十二条","txt":"下列事项不属于行政复议范围："},{"i":13,"n":"第十三条","txt":"公民、法人或者其他组织认为行政机关的行政行为所依据的下列规范性文件不合法，在对行政行为申请行政复议时，可以一并向行政复议机关提出对该规范性文件的附带审查申请："},{"i":14,"n":"第十四条","txt":"依照本法申请行政复议的公民、法人或者其他组织是申请人。"},{"i":15,"n":"第十五条","txt":"同一行政复议案件申请人人数众多的，可以由申请人推选代表人参加行政复议。"},{"i":16,"n":"第十六条","txt":"申请人以外的同被申请行政复议的行政行为或者行政复议案件处理结果有利害关系的公民、法人或者其他组织，可以作为第三人申请参加行政复议，或者由行政复议机构通知其作为第三人参加行政复议。"},{"i":17,"n":"第十七条","txt":"申请人、第三人可以委托一至二名律师、基层法律服务工作者或者其他代理人代为参加行政复议。"},{"i":18,"n":"第十八条","txt":"符合法律援助条件的行政复议申请人申请法律援助的，法律援助机构应当依法为其提供法律援助。"},{"i":19,"n":"第十九条","txt":"公民、法人或者其他组织对行政行为不服申请行政复议的，作出行政行为的行政机关或者法律、法规、规章授权的组织是被申请人。"},{"i":20,"n":"第二十条","txt":"公民、法人或者其他组织认为行政行为侵犯其合法权益的，可以自知道或者应当知道该行政行为之日起六十日内提出行政复议申请；但是法律规定的申请期限超过六十日的除外。"},{"i":21,"n":"第二十一条","txt":"因不动产提出的行政复议申请自行政行为作出之日起超过二十年，其他行政复议申请自行政行为作出之日起超过五年的，行政复议机关不予受理。"},{"i":22,"n":"第二十二条","txt":"申请人申请行政复议，可以书面申请；书面申请有困难的，也可以口头申请。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，申请人应当先向行政复议机关申请行政复议，对行政复议决定不服的，可以再依法向人民法院提起行政诉讼："},{"i":24,"n":"第二十四条","txt":"县级以上地方各级人民政府管辖下列行政复议案件："},{"i":25,"n":"第二十五条","txt":"国务院部门管辖下列行政复议案件："},{"i":26,"n":"第二十六条","txt":"对省、自治区、直辖市人民政府依照本法第二十四条第二款的规定、国务院部门依照本法第二十五条第一项的规定作出的行政复议决定不服的，可以向人民法院提起行政诉讼；也可以向国务院申请裁决，国务院依照本法的规定作出最终裁决。"},{"i":27,"n":"第二十七条","txt":"对海关、金融、外汇管理等实行垂直领导的行政机关、税务和国家安全机关的行政行为不服的，向上一级主管部门申请行政复议。"},{"i":28,"n":"第二十八条","txt":"对履行行政复议机构职责的地方人民政府司法行政部门的行政行为不服的，可以向本级人民政府申请行政复议，也可以向上一级司法行政部门申请行政复议。"},{"i":29,"n":"第二十九条","txt":"公民、法人或者其他组织申请行政复议，行政复议机关已经依法受理的，在行政复议期间不得向人民法院提起行政诉讼。"},{"i":30,"n":"第三十条","txt":"行政复议机关收到行政复议申请后，应当在五日内进行审查。对符合下列规定的，行政复议机关应当予以受理："},{"i":31,"n":"第三十一条","txt":"行政复议申请材料不齐全或者表述不清楚，无法判断行政复议申请是否符合本法第三十条第一款规定的，行政复议机关应当自收到申请之日起五日内书面通知申请人补正。补正通知应当一次性载明需要补正的事项。"},{"i":32,"n":"第三十二条","txt":"对当场作出或者依据电子技术监控设备记录的违法事实作出的行政处罚决定不服申请行政复议的，可以通过作出行政处罚决定的行政机关提交行政复议申请。"},{"i":33,"n":"第三十三条","txt":"行政复议机关受理行政复议申请后，发现该行政复议申请不符合本法第三十条第一款规定的，应当决定驳回申请并说明理由。"},{"i":34,"n":"第三十四条","txt":"法律、行政法规规定应当先向行政复议机关申请行政复议、对行政复议决定不服再向人民法院提起行政诉讼的，行政复议机关决定不予受理、驳回申请或者受理后超过行政复议期限不作答复的，公民、法人或者其他组织可以自收到决定书之日起或者行政复议期限届满之日起十五日内，依法向人民法院提起行政诉讼。"},{"i":35,"n":"第三十五条","txt":"公民、法人或者其他组织依法提出行政复议申请，行政复议机关无正当理由不予受理、驳回申请或者受理后超过行政复议期限不作答复的，申请人有权向上级行政机关反映，上级行政机关应当责令其纠正；必要时，上级行政复议机关可以直接受理。"},{"i":36,"n":"第三十六条","txt":"行政复议机关受理行政复议申请后，依照本法适用普通程序或者简易程序进行审理。行政复议机构应当指定行政复议人员负责办理行政复议案件。"},{"i":37,"n":"第三十七条","txt":"行政复议机关依照法律、法规、规章审理行政复议案件。"},{"i":38,"n":"第三十八条","txt":"上级行政复议机关根据需要，可以审理下级行政复议机关管辖的行政复议案件。"},{"i":39,"n":"第三十九条","txt":"行政复议期间有下列情形之一的，行政复议中止："},{"i":40,"n":"第四十条","txt":"行政复议期间，行政复议机关无正当理由中止行政复议的，上级行政机关应当责令其恢复审理。"},{"i":41,"n":"第四十一条","txt":"行政复议期间有下列情形之一的，行政复议机关决定终止行政复议："},{"i":42,"n":"第四十二条","txt":"行政复议期间行政行为不停止执行；但是有下列情形之一的，应当停止执行："},{"i":43,"n":"第四十三条","txt":"行政复议证据包括："},{"i":44,"n":"第四十四条","txt":"被申请人对其作出的行政行为的合法性、适当性负有举证责任。"},{"i":45,"n":"第四十五条","txt":"行政复议机关有权向有关单位和个人调查取证，查阅、复制、调取有关文件和资料，向有关人员进行询问。"},{"i":46,"n":"第四十六条","txt":"行政复议期间，被申请人不得自行向申请人和其他有关单位或者个人收集证据；自行收集的证据不作为认定行政行为合法性、适当性的依据。"},{"i":47,"n":"第四十七条","txt":"行政复议期间，申请人、第三人及其委托代理人可以按照规定查阅、复制被申请人提出的书面答复、作出行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密、个人隐私或者可能危及国家安全、公共安全、社会稳定的情形外，行政复议机构应当同意。"},{"i":48,"n":"第四十八条","txt":"行政复议机构应当自行政复议申请受理之日起七日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起十日内，提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。"},{"i":49,"n":"第四十九条","txt":"适用普通程序审理的行政复议案件，行政复议机构应当当面或者通过互联网、电话等方式听取当事人的意见，并将听取的意见记录在案。因当事人原因不能听取意见的，可以书面审理。"},{"i":50,"n":"第五十条","txt":"审理重大、疑难、复杂的行政复议案件，行政复议机构应当组织听证。"},{"i":51,"n":"第五十一条","txt":"行政复议机构组织听证的，应当于举行听证的五日前将听证的时间、地点和拟听证事项书面通知当事人。"},{"i":52,"n":"第五十二条","txt":"县级以上各级人民政府应当建立相关政府部门、专家、学者等参与的行政复议委员会，为办理行政复议案件提供咨询意见，并就行政复议工作中的重大事项和共性问题研究提出意见。行政复议委员会的组成和开展工作的具体办法，由国务院行政复议机构制定。"},{"i":53,"n":"第五十三条","txt":"行政复议机关审理下列行政复议案件，认为事实清楚、权利义务关系明确、争议不大的，可以适用简易程序："},{"i":54,"n":"第五十四条","txt":"适用简易程序审理的行政复议案件，行政复议机构应当自受理行政复议申请之日起三日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起五日内，提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。"},{"i":55,"n":"第五十五条","txt":"适用简易程序审理的行政复议案件，行政复议机构认为不宜适用简易程序的，经行政复议机构的负责人批准，可以转为普通程序审理。"},{"i":56,"n":"第五十六条","txt":"申请人依照本法第十三条的规定提出对有关规范性文件的附带审查申请，行政复议机关有权处理的，应当在三十日内依法处理；无权处理的，应当在七日内转送有权处理的行政机关依法处理。"},{"i":57,"n":"第五十七条","txt":"行政复议机关在对被申请人作出的行政行为进行审查时，认为其依据不合法，本机关有权处理的，应当在三十日内依法处理；无权处理的，应当在七日内转送有权处理的国家机关依法处理。"},{"i":58,"n":"第五十八条","txt":"行政复议机关依照本法第五十六条、第五十七条的规定有权处理有关规范性文件或者依据的，行政复议机构应当自行政复议中止之日起三日内，书面通知规范性文件或者依据的制定机关就相关条款的合法性提出书面答复。制定机关应当自收到书面通知之日起十日内提交书面答复及相关材料。"},{"i":59,"n":"第五十九条","txt":"行政复议机关依照本法第五十六条、第五十七条的规定有权处理有关规范性文件或者依据，认为相关条款合法的，在行政复议决定书中一并告知；认为相关条款超越权限或者违反上位法的，决定停止该条款的执行，并责令制定机关予以纠正。"},{"i":60,"n":"第六十条","txt":"依照本法第五十六条、第五十七条的规定接受转送的行政机关、国家机关应当自收到转送之日起六十日内，将处理意见回复转送的行政复议机关。"},{"i":61,"n":"第六十一条","txt":"行政复议机关依照本法审理行政复议案件，由行政复议机构对行政行为进行审查，提出意见，经行政复议机关的负责人同意或者集体讨论通过后，以行政复议机关的名义作出行政复议决定。"},{"i":62,"n":"第六十二条","txt":"适用普通程序审理的行政复议案件，行政复议机关应当自受理申请之日起六十日内作出行政复议决定；但是法律规定的行政复议期限少于六十日的除外。情况复杂，不能在规定期限内作出行政复议决定的，经行政复议机构的负责人批准，可以适当延长，并书面告知当事人；但是延长期限最多不得超过三十日。"},{"i":63,"n":"第六十三条","txt":"行政行为有下列情形之一的，行政复议机关决定变更该行政行为："},{"i":64,"n":"第六十四条","txt":"行政行为有下列情形之一的，行政复议机关决定撤销或者部分撤销该行政行为，并可以责令被申请人在一定期限内重新作出行政行为："},{"i":65,"n":"第六十五条","txt":"行政行为有下列情形之一的，行政复议机关不撤销该行政行为，但是确认该行政行为违法："},{"i":66,"n":"第六十六条","txt":"被申请人不履行法定职责的，行政复议机关决定被申请人在一定期限内履行。"},{"i":67,"n":"第六十七条","txt":"行政行为有实施主体不具有行政主体资格或者没有依据等重大且明显违法情形，申请人申请确认行政行为无效的，行政复议机关确认该行政行为无效。"},{"i":68,"n":"第六十八条","txt":"行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，行政复议机关决定维持该行政行为。"},{"i":69,"n":"第六十九条","txt":"行政复议机关受理申请人认为被申请人不履行法定职责的行政复议申请后，发现被申请人没有相应法定职责或者在受理前已经履行法定职责的，决定驳回申请人的行政复议请求。"},{"i":70,"n":"第七十条","txt":"被申请人不按照本法第四十八条、第五十四条的规定提出书面答复、提交作出行政行为的证据、依据和其他有关材料的，视为该行政行为没有证据、依据，行政复议机关决定撤销、部分撤销该行政行为，确认该行政行为违法、无效或者决定被申请人在一定期限内履行，但是行政行为涉及第三人合法权益，第三人提供证据的除外。"},{"i":71,"n":"第七十一条","txt":"被申请人不依法订立、不依法履行、未按照约定履行或者违法变更、解除行政协议的，行政复议机关决定被申请人承担依法订立、继续履行、采取补救措施或者赔偿损失等责任。"},{"i":72,"n":"第七十二条","txt":"申请人在申请行政复议时一并提出行政赔偿请求，行政复议机关对依照《中华人民共和国国家赔偿法》的有关规定应当不予赔偿的，在作出行政复议决定时，应当同时决定驳回行政赔偿请求；对符合《中华人民共和国国家赔偿法》的有关规定应当给予赔偿的，在决定撤销或者部分撤销、变更行政行为或者确认行政行为违法、无效时，应当同时决定被申请人依法给予赔偿；确认行政行为违法的，还可以同时责令被申请人采取补救措施。"},{"i":73,"n":"第七十三条","txt":"当事人经调解达成协议的，行政复议机关应当制作行政复议调解书，经各方当事人签字或者签章，并加盖行政复议机关印章，即具有法律效力。"},{"i":74,"n":"第七十四条","txt":"当事人在行政复议决定作出前可以自愿达成和解，和解内容不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、法规的强制性规定。"},{"i":75,"n":"第七十五条","txt":"行政复议机关作出行政复议决定，应当制作行政复议决定书，并加盖行政复议机关印章。"},{"i":76,"n":"第七十六条","txt":"行政复议机关在办理行政复议案件过程中，发现被申请人或者其他下级行政机关的有关行政行为违法或者不当的，可以向其制发行政复议意见书。有关机关应当自收到行政复议意见书之日起六十日内，将纠正相关违法或者不当行政行为的情况报送行政复议机关。"},{"i":77,"n":"第七十七条","txt":"被申请人应当履行行政复议决定书、调解书、意见书。"},{"i":78,"n":"第七十八条","txt":"申请人、第三人逾期不起诉又不履行行政复议决定书、调解书的，或者不履行最终裁决的行政复议决定的，按照下列规定分别处理："},{"i":79,"n":"第七十九条","txt":"行政复议机关根据被申请行政复议的行政行为的公开情况，按照国家有关规定将行政复议决定书向社会公开。"},{"i":80,"n":"第八十条","txt":"行政复议机关不依照本法规定履行行政复议职责，对负有责任的领导人员和直接责任人员依法给予警告、记过、记大过的处分；经有权监督的机关督促仍不改正或者造成严重后果的，依法给予降级、撤职、开除的处分。"},{"i":81,"n":"第八十一条","txt":"行政复议机关工作人员在行政复议活动中，徇私舞弊或者有其他渎职、失职行为的，依法给予警告、记过、记大过的处分；情节严重的，依法给予降级、撤职、开除的处分；构成犯罪的，依法追究刑事责任。"},{"i":82,"n":"第八十二条","txt":"被申请人违反本法规定，不提出书面答复或者不提交作出行政行为的证据、依据和其他有关材料，或者阻挠、变相阻挠公民、法人或者其他组织依法申请行政复议的，对负有责任的领导人员和直接责任人员依法给予警告、记过、记大过的处分；进行报复陷害的，依法给予降级、撤职、开除的处分；构成犯罪的，依法追究刑事责任。"},{"i":83,"n":"第八十三条","txt":"被申请人不履行或者无正当理由拖延履行行政复议决定书、调解书、意见书的，对负有责任的领导人员和直接责任人员依法给予警告、记过、记大过的处分；经责令履行仍拒不履行的，依法给予降级、撤职、开除的处分。"},{"i":84,"n":"第八十四条","txt":"拒绝、阻挠行政复议人员调查取证，故意扰乱行政复议工作秩序的，依法给予处分、治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":85,"n":"第八十五条","txt":"行政机关及其工作人员违反本法规定的，行政复议机关可以向监察机关或者公职人员任免机关、单位移送有关人员违法的事实材料，接受移送的监察机关或者公职人员任免机关、单位应当依法处理。"},{"i":86,"n":"第八十六条","txt":"行政复议机关在办理行政复议案件过程中，发现公职人员涉嫌贪污贿赂、失职渎职等职务违法或者职务犯罪的问题线索，应当依照有关规定移送监察机关，由监察机关依法调查处置。"},{"i":87,"n":"第八十七条","txt":"行政复议机关受理行政复议申请，不得向申请人收取任何费用。"},{"i":88,"n":"第八十八条","txt":"行政复议期间的计算和行政复议文书的送达，本法没有规定的，依照《中华人民共和国民事诉讼法》关于期间、送达的规定执行。"},{"i":89,"n":"第八十九条","txt":"外国人、无国籍人、外国组织在中华人民共和国境内申请行政复议，适用本法。"},{"i":90,"n":"第九十条","txt":"本法自2024年1月1日起施行。"}],"xingzhengqiangzhifa":[{"i":1,"n":"第一条","txt":"为了规范行政强制的设定和实施，保障和监督行政机关依法履行职责，维护公共利益和社会秩序，保护公民、法人和其他组织的合法权益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称行政强制，包括行政强制措施和行政强制执行。"},{"i":3,"n":"第三条","txt":"行政强制的设定和实施，适用本法。"},{"i":4,"n":"第四条","txt":"行政强制的设定和实施，应当依照法定的权限、范围、条件和程序。"},{"i":5,"n":"第五条","txt":"行政强制的设定和实施，应当适当。采用非强制手段可以达到行政管理目的的，不得设定和实施行政强制。"},{"i":6,"n":"第六条","txt":"实施行政强制，应当坚持教育与强制相结合。"},{"i":7,"n":"第七条","txt":"行政机关及其工作人员不得利用行政强制权为单位或者个人谋取利益。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织对行政机关实施行政强制，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼；因行政机关违法实施行政强制受到损害的，有权依法要求赔偿。"},{"i":9,"n":"第九条","txt":"行政强制措施的种类："},{"i":10,"n":"第十条","txt":"行政强制措施由法律设定。"},{"i":11,"n":"第十一条","txt":"法律对行政强制措施的对象、条件、种类作了规定的，行政法规、地方性法规不得作出扩大规定。"},{"i":12,"n":"第十二条","txt":"行政强制执行的方式："},{"i":13,"n":"第十三条","txt":"行政强制执行由法律设定。"},{"i":14,"n":"第十四条","txt":"起草法律草案、法规草案，拟设定行政强制的，起草单位应当采取听证会、论证会等形式听取意见，并向制定机关说明设定该行政强制的必要性、可能产生的影响以及听取和采纳意见的情况。"},{"i":15,"n":"第十五条","txt":"行政强制的设定机关应当定期对其设定的行政强制进行评价，并对不适当的行政强制及时予以修改或者废止。"},{"i":16,"n":"第十六条","txt":"行政机关履行行政管理职责，依照法律、法规的规定，实施行政强制措施。"},{"i":17,"n":"第十七条","txt":"行政强制措施由法律、法规规定的行政机关在法定职权范围内实施。行政强制措施权不得委托。"},{"i":18,"n":"第十八条","txt":"行政机关实施行政强制措施应当遵守下列规定："},{"i":19,"n":"第十九条","txt":"情况紧急，需要当场实施行政强制措施的，行政执法人员应当在二十四小时内向行政机关负责人报告，并补办批准手续。行政机关负责人认为不应当采取行政强制措施的，应当立即解除。"},{"i":20,"n":"第二十条","txt":"依照法律规定实施限制公民人身自由的行政强制措施，除应当履行本法第十八条规定的程序外，还应当遵守下列规定："},{"i":21,"n":"第二十一条","txt":"违法行为涉嫌犯罪应当移送司法机关的，行政机关应当将查封、扣押、冻结的财物一并移送，并书面告知当事人。"},{"i":22,"n":"第二十二条","txt":"查封、扣押应当由法律、法规规定的行政机关实施，其他任何行政机关或者组织不得实施。"},{"i":23,"n":"第二十三条","txt":"查封、扣押限于涉案的场所、设施或者财物，不得查封、扣押与违法行为无关的场所、设施或者财物；不得查封、扣押公民个人及其所扶养家属的生活必需品。"},{"i":24,"n":"第二十四条","txt":"行政机关决定实施查封、扣押的，应当履行本法第十八条规定的程序，制作并当场交付查封、扣押决定书和清单。"},{"i":25,"n":"第二十五条","txt":"查封、扣押的期限不得超过三十日；情况复杂的，经行政机关负责人批准，可以延长，但是延长期限不得超过三十日。法律、行政法规另有规定的除外。"},{"i":26,"n":"第二十六条","txt":"对查封、扣押的场所、设施或者财物，行政机关应当妥善保管，不得使用或者损毁；造成损失的，应当承担赔偿责任。"},{"i":27,"n":"第二十七条","txt":"行政机关采取查封、扣押措施后，应当及时查清事实，在本法第二十五条规定的期限内作出处理决定。对违法事实清楚，依法应当没收的非法财物予以没收；法律、行政法规规定应当销毁的，依法销毁；应当解除查封、扣押的，作出解除查封、扣押的决定。"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，行政机关应当及时作出解除查封、扣押决定："},{"i":29,"n":"第二十九条","txt":"冻结存款、汇款应当由法律规定的行政机关实施，不得委托给其他行政机关或者组织；其他任何行政机关或者组织不得冻结存款、汇款。"},{"i":30,"n":"第三十条","txt":"行政机关依照法律规定决定实施冻结存款、汇款的，应当履行本法第十八条第一项、第二项、第三项、第七项规定的程序，并向金融机构交付冻结通知书。"},{"i":31,"n":"第三十一条","txt":"依照法律规定冻结存款、汇款的，作出决定的行政机关应当在三日内向当事人交付冻结决定书。冻结决定书应当载明下列事项："},{"i":32,"n":"第三十二条","txt":"自冻结存款、汇款之日起三十日内，行政机关应当作出处理决定或者作出解除冻结决定；情况复杂的，经行政机关负责人批准，可以延长，但是延长期限不得超过三十日。法律另有规定的除外。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，行政机关应当及时作出解除冻结决定："},{"i":34,"n":"第三十四条","txt":"行政机关依法作出行政决定后，当事人在行政机关决定的期限内不履行义务的，具有行政强制执行权的行政机关依照本章规定强制执行。"},{"i":35,"n":"第三十五条","txt":"行政机关作出强制执行决定前，应当事先催告当事人履行义务。催告应当以书面形式作出，并载明下列事项："},{"i":36,"n":"第三十六条","txt":"当事人收到催告书后有权进行陈述和申辩。行政机关应当充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行记录、复核。当事人提出的事实、理由或者证据成立的，行政机关应当采纳。"},{"i":37,"n":"第三十七条","txt":"经催告，当事人逾期仍不履行行政决定，且无正当理由的，行政机关可以作出强制执行决定。"},{"i":38,"n":"第三十八条","txt":"催告书、行政强制执行决定书应当直接送达当事人。当事人拒绝接收或者无法直接送达当事人的，应当依照《中华人民共和国民事诉讼法》的有关规定送达。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，中止执行："},{"i":40,"n":"第四十条","txt":"有下列情形之一的，终结执行："},{"i":41,"n":"第四十一条","txt":"在执行中或者执行完毕后，据以执行的行政决定被撤销、变更，或者执行错误的，应当恢复原状或者退还财物；不能恢复原状或者退还财物的，依法给予赔偿。"},{"i":42,"n":"第四十二条","txt":"实施行政强制执行，行政机关可以在不损害公共利益和他人合法权益的情况下，与当事人达成执行协议。执行协议可以约定分阶段履行；当事人采取补救措施的，可以减免加处的罚款或者滞纳金。"},{"i":43,"n":"第四十三条","txt":"行政机关不得在夜间或者法定节假日实施行政强制执行。但是，情况紧急的除外。"},{"i":44,"n":"第四十四条","txt":"对违法的建筑物、构筑物、设施等需要强制拆除的，应当由行政机关予以公告，限期当事人自行拆除。当事人在法定期限内不申请行政复议或者提起行政诉讼，又不拆除的，行政机关可以依法强制拆除。"},{"i":45,"n":"第四十五条","txt":"行政机关依法作出金钱给付义务的行政决定，当事人逾期不履行的，行政机关可以依法加处罚款或者滞纳金。加处罚款或者滞纳金的标准应当告知当事人。"},{"i":46,"n":"第四十六条","txt":"行政机关依照本法第四十五条规定实施加处罚款或者滞纳金超过三十日，经催告当事人仍不履行的，具有行政强制执行权的行政机关可以强制执行。"},{"i":47,"n":"第四十七条","txt":"划拨存款、汇款应当由法律规定的行政机关决定，并书面通知金融机构。金融机构接到行政机关依法作出划拨存款、汇款的决定后，应当立即划拨。"},{"i":48,"n":"第四十八条","txt":"依法拍卖财物，由行政机关委托拍卖机构依照《中华人民共和国拍卖法》的规定办理。"},{"i":49,"n":"第四十九条","txt":"划拨的存款、汇款以及拍卖和依法处理所得的款项应当上缴国库或者划入财政专户。任何行政机关或者个人不得以任何形式截留、私分或者变相私分。"},{"i":50,"n":"第五十条","txt":"行政机关依法作出要求当事人履行排除妨碍、恢复原状等义务的行政决定，当事人逾期不履行，经催告仍不履行，其后果已经或者将危害交通安全、造成环境污染或者破坏自然资源的，行政机关可以代履行，或者委托没有利害关系的第三人代履行。"},{"i":51,"n":"第五十一条","txt":"代履行应当遵守下列规定："},{"i":52,"n":"第五十二条","txt":"需要立即清除道路、河道、航道或者公共场所的遗洒物、障碍物或者污染物，当事人不能清除的，行政机关可以决定立即实施代履行；当事人不在场的，行政机关应当在事后立即通知当事人，并依法作出处理。"},{"i":53,"n":"第五十三条","txt":"当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行行政决定的，没有行政强制执行权的行政机关可以自期限届满之日起三个月内，依照本章规定申请人民法院强制执行。"},{"i":54,"n":"第五十四条","txt":"行政机关申请人民法院强制执行前，应当催告当事人履行义务。催告书送达十日后当事人仍未履行义务的，行政机关可以向所在地有管辖权的人民法院申请强制执行；执行对象是不动产的，向不动产所在地有管辖权的人民法院申请强制执行。"},{"i":55,"n":"第五十五条","txt":"行政机关向人民法院申请强制执行，应当提供下列材料："},{"i":56,"n":"第五十六条","txt":"人民法院接到行政机关强制执行的申请，应当在五日内受理。"},{"i":57,"n":"第五十七条","txt":"人民法院对行政机关强制执行的申请进行书面审查，对符合本法第五十五条规定，且行政决定具备法定执行效力的，除本法第五十八条规定的情形外，人民法院应当自受理之日起七日内作出执行裁定。"},{"i":58,"n":"第五十八条","txt":"人民法院发现有下列情形之一的，在作出裁定前可以听取被执行人和行政机关的意见："},{"i":59,"n":"第五十九条","txt":"因情况紧急，为保障公共安全，行政机关可以申请人民法院立即执行。经人民法院院长批准，人民法院应当自作出执行裁定之日起五日内执行。"},{"i":60,"n":"第六十条","txt":"行政机关申请人民法院强制执行，不缴纳申请费。强制执行的费用由被执行人承担。"},{"i":61,"n":"第六十一条","txt":"行政机关实施行政强制，有下列情形之一的，由上级行政机关或者有关部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":62,"n":"第六十二条","txt":"违反本法规定，行政机关有下列情形之一的，由上级行政机关或者有关部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":63,"n":"第六十三条","txt":"行政机关将查封、扣押的财物或者划拨的存款、汇款以及拍卖和依法处理所得的款项，截留、私分或者变相私分的，由财政部门或者有关部门予以追缴；对直接负责的主管人员和其他直接责任人员依法给予记大过、降级、撤职或者开除的处分。"},{"i":64,"n":"第六十四条","txt":"行政机关及其工作人员利用行政强制权为单位或者个人谋取利益的，由上级行政机关或者有关部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，金融机构有下列行为之一的，由金融业监督管理机构责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":66,"n":"第六十六条","txt":"违反本法规定，金融机构将款项划入国库或者财政专户以外的其他账户的，由金融业监督管理机构责令改正，并处以违法划拨款项二倍的罚款；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":67,"n":"第六十七条","txt":"人民法院及其工作人员在强制执行中有违法行为或者扩大强制执行范围的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":68,"n":"第六十八条","txt":"违反本法规定，给公民、法人或者其他组织造成损失的，依法给予赔偿。"},{"i":69,"n":"第六十九条","txt":"本法中十日以内期限的规定是指工作日，不含法定节假日。"},{"i":70,"n":"第七十条","txt":"法律、行政法规授权的具有管理公共事务职能的组织在法定授权范围内，以自己的名义实施行政强制，适用本法有关行政机关的规定。"},{"i":71,"n":"第七十一条","txt":"本法自2012年1月1日起施行。"}],"xingzhengxukefa":[{"i":1,"n":"第一条","txt":"为了规范行政许可的设定和实施，保护公民、法人和其他组织的合法权益，维护公共利益和社会秩序，保障和监督行政机关有效实施行政管理，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称行政许可，是指行政机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。"},{"i":3,"n":"第三条","txt":"行政许可的设定和实施，适用本法。"},{"i":4,"n":"第四条","txt":"设定和实施行政许可，应当依照法定的权限、范围、条件和程序。"},{"i":5,"n":"第五条","txt":"设定和实施行政许可，应当遵循公开、公平、公正、非歧视的原则。"},{"i":6,"n":"第六条","txt":"实施行政许可，应当遵循便民的原则，提高办事效率，提供优质服务。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织对行政机关实施行政许可，享有陈述权、申辩权；有权依法申请行政复议或者提起行政诉讼；其合法权益因行政机关违法实施行政许可受到损害的，有权依法要求赔偿。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织依法取得的行政许可受法律保护，行政机关不得擅自改变已经生效的行政许可。"},{"i":9,"n":"第九条","txt":"依法取得的行政许可，除法律、法规规定依照法定条件和程序可以转让的外，不得转让。"},{"i":10,"n":"第十条","txt":"县级以上人民政府应当建立健全对行政机关实施行政许可的监督制度，加强对行政机关实施行政许可的监督检查。"},{"i":11,"n":"第十一条","txt":"设定行政许可，应当遵循经济和社会发展规律，有利于发挥公民、法人或者其他组织的积极性、主动性，维护公共利益和社会秩序，促进经济、社会和生态环境协调发展。"},{"i":12,"n":"第十二条","txt":"下列事项可以设定行政许可："},{"i":13,"n":"第十三条","txt":"本法第十二条所列事项，通过下列方式能够予以规范的，可以不设行政许可："},{"i":14,"n":"第十四条","txt":"本法第十二条所列事项，法律可以设定行政许可。尚未制定法律的，行政法规可以设定行政许可。"},{"i":15,"n":"第十五条","txt":"本法第十二条所列事项，尚未制定法律、行政法规的，地方性法规可以设定行政许可；尚未制定法律、行政法规和地方性法规的，因行政管理的需要，确需立即实施行政许可的，省、自治区、直辖市人民政府规章可以设定临时性的行政许可。临时性的行政许可实施满一年需要继续实施的，应当提请本级人民代表大会及其常务委员会制定地方性法规。"},{"i":16,"n":"第十六条","txt":"行政法规可以在法律设定的行政许可事项范围内，对实施该行政许可作出具体规定。"},{"i":17,"n":"第十七条","txt":"除本法第十四条、第十五条规定的外，其他规范性文件一律不得设定行政许可。"},{"i":18,"n":"第十八条","txt":"设定行政许可，应当规定行政许可的实施机关、条件、程序、期限。"},{"i":19,"n":"第十九条","txt":"起草法律草案、法规草案和省、自治区、直辖市人民政府规章草案，拟设定行政许可的，起草单位应当采取听证会、论证会等形式听取意见，并向制定机关说明设定该行政许可的必要性、对经济和社会可能产生的影响以及听取和采纳意见的情况。"},{"i":20,"n":"第二十条","txt":"行政许可的设定机关应当定期对其设定的行政许可进行评价；对已设定的行政许可，认为通过本法第十三条所列方式能够解决的，应当对设定该行政许可的规定及时予以修改或者废止。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府对行政法规设定的有关经济事务的行政许可，根据本行政区域经济和社会发展情况，认为通过本法第十三条所列方式能够解决的，报国务院批准后，可以在本行政区域内停止实施该行政许可。"},{"i":22,"n":"第二十二条","txt":"行政许可由具有行政许可权的行政机关在其法定职权范围内实施。"},{"i":23,"n":"第二十三条","txt":"法律、法规授权的具有管理公共事务职能的组织，在法定授权范围内，以自己的名义实施行政许可。被授权的组织适用本法有关行政机关的规定。"},{"i":24,"n":"第二十四条","txt":"行政机关在其法定职权范围内，依照法律、法规、规章的规定，可以委托其他行政机关实施行政许可。委托机关应当将受委托行政机关和受委托实施行政许可的内容予以公告。"},{"i":25,"n":"第二十五条","txt":"经国务院批准，省、自治区、直辖市人民政府根据精简、统一、效能的原则，可以决定一个行政机关行使有关行政机关的行政许可权。"},{"i":26,"n":"第二十六条","txt":"行政许可需要行政机关内设的多个机构办理的，该行政机关应当确定一个机构统一受理行政许可申请，统一送达行政许可决定。"},{"i":27,"n":"第二十七条","txt":"行政机关实施行政许可，不得向申请人提出购买指定商品、接受有偿服务等不正当要求。"},{"i":28,"n":"第二十八条","txt":"对直接关系公共安全、人身健康、生命财产安全的设备、设施、产品、物品的检验、检测、检疫，除法律、行政法规规定由行政机关实施的外，应当逐步由符合法定条件的专业技术组织实施。专业技术组织及其有关人员对所实施的检验、检测、检疫结论承担法律责任。"},{"i":29,"n":"第二十九条","txt":"公民、法人或者其他组织从事特定活动，依法需要取得行政许可的，应当向行政机关提出申请。申请书需要采用格式文本的，行政机关应当向申请人提供行政许可申请书格式文本。申请书格式文本中不得包含与申请行政许可事项没有直接关系的内容。"},{"i":30,"n":"第三十条","txt":"行政机关应当将法律、法规、规章规定的有关行政许可的事项、依据、条件、数量、程序、期限以及需要提交的全部材料的目录和申请书示范文本等在办公场所公示。"},{"i":31,"n":"第三十一条","txt":"申请人申请行政许可，应当如实向行政机关提交有关材料和反映真实情况，并对其申请材料实质内容的真实性负责。行政机关不得要求申请人提交与其申请的行政许可事项无关的技术资料和其他材料。"},{"i":32,"n":"第三十二条","txt":"行政机关对申请人提出的行政许可申请，应当根据下列情况分别作出处理："},{"i":33,"n":"第三十三条","txt":"行政机关应当建立和完善有关制度，推行电子政务，在行政机关的网站上公布行政许可事项，方便申请人采取数据电文等方式提出行政许可申请；应当与其他行政机关共享有关行政许可信息，提高办事效率。"},{"i":34,"n":"第三十四条","txt":"行政机关应当对申请人提交的申请材料进行审查。"},{"i":35,"n":"第三十五条","txt":"依法应当先经下级行政机关审查后报上级行政机关决定的行政许可，下级行政机关应当在法定期限内将初步审查意见和全部申请材料直接报送上级行政机关。上级行政机关不得要求申请人重复提供申请材料。"},{"i":36,"n":"第三十六条","txt":"行政机关对行政许可申请进行审查时，发现行政许可事项直接关系他人重大利益的，应当告知该利害关系人。申请人、利害关系人有权进行陈述和申辩。行政机关应当听取申请人、利害关系人的意见。"},{"i":37,"n":"第三十七条","txt":"行政机关对行政许可申请进行审查后，除当场作出行政许可决定的外，应当在法定期限内按照规定程序作出行政许可决定。"},{"i":38,"n":"第三十八条","txt":"申请人的申请符合法定条件、标准的，行政机关应当依法作出准予行政许可的书面决定。"},{"i":39,"n":"第三十九条","txt":"行政机关作出准予行政许可的决定，需要颁发行政许可证件的，应当向申请人颁发加盖本行政机关印章的下列行政许可证件："},{"i":40,"n":"第四十条","txt":"行政机关作出的准予行政许可决定，应当予以公开，公众有权查阅。"},{"i":41,"n":"第四十一条","txt":"法律、行政法规设定的行政许可，其适用范围没有地域限制的，申请人取得的行政许可在全国范围内有效。"},{"i":42,"n":"第四十二条","txt":"除可以当场作出行政许可决定的外，行政机关应当自受理行政许可申请之日起二十日内作出行政许可决定。二十日内不能作出决定的，经本行政机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请人。但是，法律、法规另有规定的，依照其规定。"},{"i":43,"n":"第四十三条","txt":"依法应当先经下级行政机关审查后报上级行政机关决定的行政许可，下级行政机关应当自其受理行政许可申请之日起二十日内审查完毕。但是，法律、法规另有规定的，依照其规定。"},{"i":44,"n":"第四十四条","txt":"行政机关作出准予行政许可的决定，应当自作出决定之日起十日内向申请人颁发、送达行政许可证件，或者加贴标签、加盖检验、检测、检疫印章。"},{"i":45,"n":"第四十五条","txt":"行政机关作出行政许可决定，依法需要听证、招标、拍卖、检验、检测、检疫、鉴定和专家评审的，所需时间不计算在本节规定的期限内。行政机关应当将所需时间书面告知申请人。"},{"i":46,"n":"第四十六条","txt":"法律、法规、规章规定实施行政许可应当听证的事项，或者行政机关认为需要听证的其他涉及公共利益的重大行政许可事项，行政机关应当向社会公告，并举行听证。"},{"i":47,"n":"第四十七条","txt":"行政许可直接涉及申请人与他人之间重大利益关系的，行政机关在作出行政许可决定前，应当告知申请人、利害关系人享有要求听证的权利；申请人、利害关系人在被告知听证权利之日起五日内提出听证申请的，行政机关应当在二十日内组织听证。"},{"i":48,"n":"第四十八条","txt":"听证按照下列程序进行："},{"i":49,"n":"第四十九条","txt":"被许可人要求变更行政许可事项的，应当向作出行政许可决定的行政机关提出申请；符合法定条件、标准的，行政机关应当依法办理变更手续。"},{"i":50,"n":"第五十条","txt":"被许可人需要延续依法取得的行政许可的有效期的，应当在该行政许可有效期届满三十日前向作出行政许可决定的行政机关提出申请。但是，法律、法规、规章另有规定的，依照其规定。"},{"i":51,"n":"第五十一条","txt":"实施行政许可的程序，本节有规定的，适用本节规定；本节没有规定的，适用本章其他有关规定。"},{"i":52,"n":"第五十二条","txt":"国务院实施行政许可的程序，适用有关法律、行政法规的规定。"},{"i":53,"n":"第五十三条","txt":"实施本法第十二条第二项所列事项的行政许可的，行政机关应当通过招标、拍卖等公平竞争的方式作出决定。但是，法律、行政法规另有规定的，依照其规定。"},{"i":54,"n":"第五十四条","txt":"实施本法第十二条第三项所列事项的行政许可，赋予公民特定资格，依法应当举行国家考试的，行政机关根据考试成绩和其他法定条件作出行政许可决定；赋予法人或者其他组织特定的资格、资质的，行政机关根据申请人的专业人员构成、技术条件、经营业绩和管理水平等的考核结果作出行政许可决定。但是，法律、行政法规另有规定的，依照其规定。"},{"i":55,"n":"第五十五条","txt":"实施本法第十二条第四项所列事项的行政许可的，应当按照技术标准、技术规范依法进行检验、检测、检疫，行政机关根据检验、检测、检疫的结果作出行政许可决定。"},{"i":56,"n":"第五十六条","txt":"实施本法第十二条第五项所列事项的行政许可，申请人提交的申请材料齐全、符合法定形式的，行政机关应当当场予以登记。需要对申请材料的实质内容进行核实的，行政机关依照本法第三十四条第三款的规定办理。"},{"i":57,"n":"第五十七条","txt":"有数量限制的行政许可，两个或者两个以上申请人的申请均符合法定条件、标准的，行政机关应当根据受理行政许可申请的先后顺序作出准予行政许可的决定。但是，法律、行政法规另有规定的，依照其规定。"},{"i":58,"n":"第五十八条","txt":"行政机关实施行政许可和对行政许可事项进行监督检查，不得收取任何费用。但是，法律、行政法规另有规定的，依照其规定。"},{"i":59,"n":"第五十九条","txt":"行政机关实施行政许可，依照法律、行政法规收取费用的，应当按照公布的法定项目和标准收费；所收取的费用必须全部上缴国库，任何机关或者个人不得以任何形式截留、挪用、私分或者变相私分。财政部门不得以任何形式向行政机关返还或者变相返还实施行政许可所收取的费用。"},{"i":60,"n":"第六十条","txt":"上级行政机关应当加强对下级行政机关实施行政许可的监督检查，及时纠正行政许可实施中的违法行为。"},{"i":61,"n":"第六十一条","txt":"行政机关应当建立健全监督制度，通过核查反映被许可人从事行政许可事项活动情况的有关材料，履行监督责任。"},{"i":62,"n":"第六十二条","txt":"行政机关可以对被许可人生产经营的产品依法进行抽样检查、检验、检测，对其生产经营场所依法进行实地检查。检查时，行政机关可以依法查阅或者要求被许可人报送有关材料；被许可人应当如实提供有关情况和材料。"},{"i":63,"n":"第六十三条","txt":"行政机关实施监督检查，不得妨碍被许可人正常的生产经营活动，不得索取或者收受被许可人的财物，不得谋取其他利益。"},{"i":64,"n":"第六十四条","txt":"被许可人在作出行政许可决定的行政机关管辖区域外违法从事行政许可事项活动的，违法行为发生地的行政机关应当依法将被许可人的违法事实、处理结果抄告作出行政许可决定的行政机关。"},{"i":65,"n":"第六十五条","txt":"个人和组织发现违法从事行政许可事项的活动，有权向行政机关举报，行政机关应当及时核实、处理。"},{"i":66,"n":"第六十六条","txt":"被许可人未依法履行开发利用自然资源义务或者未依法履行利用公共资源义务的，行政机关应当责令限期改正；被许可人在规定期限内不改正的，行政机关应当依照有关法律、行政法规的规定予以处理。"},{"i":67,"n":"第六十七条","txt":"取得直接关系公共利益的特定行业的市场准入行政许可的被许可人，应当按照国家规定的服务标准、资费标准和行政机关依法规定的条件，向用户提供安全、方便、稳定和价格合理的服务，并履行普遍服务的义务；未经作出行政许可决定的行政机关批准，不得擅自停业、歇业。"},{"i":68,"n":"第六十八条","txt":"对直接关系公共安全、人身健康、生命财产安全的重要设备、设施，行政机关应当督促设计、建造、安装和使用单位建立相应的自检制度。"},{"i":69,"n":"第六十九条","txt":"有下列情形之一的，作出行政许可决定的行政机关或者其上级行政机关，根据利害关系人的请求或者依据职权，可以撤销行政许可："},{"i":70,"n":"第七十条","txt":"有下列情形之一的，行政机关应当依法办理有关行政许可的注销手续："},{"i":71,"n":"第七十一条","txt":"违反本法第十七条规定设定的行政许可，有关机关应当责令设定该行政许可的机关改正，或者依法予以撤销。"},{"i":72,"n":"第七十二条","txt":"行政机关及其工作人员违反本法的规定，有下列情形之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分："},{"i":73,"n":"第七十三条","txt":"行政机关工作人员办理行政许可、实施监督检查，索取或者收受他人财物或者谋取其他利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":74,"n":"第七十四条","txt":"行政机关实施行政许可，有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":75,"n":"第七十五条","txt":"行政机关实施行政许可，擅自收费或者不按照法定项目和标准收费的，由其上级行政机关或者监察机关责令退还非法收取的费用；对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":76,"n":"第七十六条","txt":"行政机关违法实施行政许可，给当事人的合法权益造成损害的，应当依照国家赔偿法的规定给予赔偿。"},{"i":77,"n":"第七十七条","txt":"行政机关不依法履行监督职责或者监督不力，造成严重后果的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"行政许可申请人隐瞒有关情况或者提供虚假材料申请行政许可的，行政机关不予受理或者不予行政许可，并给予警告；行政许可申请属于直接关系公共安全、人身健康、生命财产安全事项的，申请人在一年内不得再次申请该行政许可。"},{"i":79,"n":"第七十九条","txt":"被许可人以欺骗、贿赂等不正当手段取得行政许可的，行政机关应当依法给予行政处罚；取得的行政许可属于直接关系公共安全、人身健康、生命财产安全事项的，申请人在三年内不得再次申请该行政许可；构成犯罪的，依法追究刑事责任。"},{"i":80,"n":"第八十条","txt":"被许可人有下列行为之一的，行政机关应当依法给予行政处罚；构成犯罪的，依法追究刑事责任："},{"i":81,"n":"第八十一条","txt":"公民、法人或者其他组织未经行政许可，擅自从事依法应当取得行政许可的活动的，行政机关应当依法采取措施予以制止，并依法给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":82,"n":"第八十二条","txt":"本法规定的行政机关实施行政许可的期限以工作日计算，不含法定节假日。"},{"i":83,"n":"第八十三条","txt":"本法自2004年7月1日起施行。"}],"daolujiaotonganquanfa":[{"i":1,"n":"第一条","txt":"为了维护道路交通秩序，预防和减少交通事故，保护人身安全，保护公民、法人和其他组织的财产安全及其他合法权益，提高通行效率，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的车辆驾驶人、行人、乘车人以及与道路交通活动有关的单位和个人，都应当遵守本法。"},{"i":3,"n":"第三条","txt":"道路交通安全工作，应当遵循依法管理、方便群众的原则，保障道路交通有序、安全、畅通。"},{"i":4,"n":"第四条","txt":"各级人民政府应当保障道路交通安全管理工作与经济建设和社会发展相适应。"},{"i":5,"n":"第五条","txt":"国务院公安部门负责全国道路交通安全管理工作。县级以上地方各级人民政府公安机关交通管理部门负责本行政区域内的道路交通安全管理工作。"},{"i":6,"n":"第六条","txt":"各级人民政府应当经常进行道路交通安全教育，提高公民的道路交通安全意识。"},{"i":7,"n":"第七条","txt":"对道路交通安全管理工作，应当加强科学研究，推广、使用先进的管理方法、技术、设备。"},{"i":8,"n":"第八条","txt":"国家对机动车实行登记制度。机动车经公安机关交通管理部门登记后，方可上道路行驶。尚未登记的机动车，需要临时上道路行驶的，应当取得临时通行牌证。"},{"i":9,"n":"第九条","txt":"申请机动车登记，应当提交以下证明、凭证："},{"i":10,"n":"第十条","txt":"准予登记的机动车应当符合机动车国家安全技术标准。申请机动车登记时，应当接受对该机动车的安全技术检验。但是，经国家机动车产品主管部门依据机动车国家安全技术标准认定的企业生产的机动车型，该车型的新车在出厂时经检验符合机动车国家安全技术标准，获得检验合格证的，免予安全技术检验。"},{"i":11,"n":"第十一条","txt":"驾驶机动车上道路行驶，应当悬挂机动车号牌，放置检验合格标志、保险标志，并随车携带机动车行驶证。"},{"i":12,"n":"第十二条","txt":"有下列情形之一的，应当办理相应的登记："},{"i":13,"n":"第十三条","txt":"对登记后上道路行驶的机动车，应当依照法律、行政法规的规定，根据车辆用途、载客载货数量、使用年限等不同情况，定期进行安全技术检验。对提供机动车行驶证和机动车第三者责任强制保险单的，机动车安全技术检验机构应当予以检验，任何单位不得附加其他条件。对符合机动车国家安全技术标准的，公安机关交通管理部门应当发给检验合格标志。"},{"i":14,"n":"第十四条","txt":"国家实行机动车强制报废制度，根据机动车的安全技术状况和不同用途，规定不同的报废标准。"},{"i":15,"n":"第十五条","txt":"警车、消防车、救护车、工程救险车应当按照规定喷涂标志图案，安装警报器、标志灯具。其他机动车不得喷涂、安装、使用上述车辆专用的或者与其相类似的标志图案、警报器或者标志灯具。"},{"i":16,"n":"第十六条","txt":"任何单位或者个人不得有下列行为："},{"i":17,"n":"第十七条","txt":"国家实行机动车第三者责任强制保险制度，设立道路交通事故社会救助基金。具体办法由国务院规定。"},{"i":18,"n":"第十八条","txt":"依法应当登记的非机动车，经公安机关交通管理部门登记后，方可上道路行驶。"},{"i":19,"n":"第十九条","txt":"驾驶机动车，应当依法取得机动车驾驶证。"},{"i":20,"n":"第二十条","txt":"机动车的驾驶培训实行社会化，由交通运输主管部门对驾驶培训学校、驾驶培训班实行备案管理，并对驾驶培训活动加强监督，其中专门的拖拉机驾驶培训学校、驾驶培训班由农业（农业机械）主管部门实行监督管理。"},{"i":21,"n":"第二十一条","txt":"驾驶人驾驶机动车上道路行驶前，应当对机动车的安全技术性能进行认真检查；不得驾驶安全设施不全或者机件不符合技术标准等具有安全隐患的机动车。"},{"i":22,"n":"第二十二条","txt":"机动车驾驶人应当遵守道路交通安全法律、法规的规定，按照操作规范安全驾驶、文明驾驶。"},{"i":23,"n":"第二十三条","txt":"公安机关交通管理部门依照法律、行政法规的规定，定期对机动车驾驶证实施审验。"},{"i":24,"n":"第二十四条","txt":"公安机关交通管理部门对机动车驾驶人违反道路交通安全法律、法规的行为，除依法给予行政处罚外，实行累积记分制度。公安机关交通管理部门对累积记分达到规定分值的机动车驾驶人，扣留机动车驾驶证，对其进行道路交通安全法律、法规教育，重新考试；考试合格的，发还其机动车驾驶证。"},{"i":25,"n":"第二十五条","txt":"全国实行统一的道路交通信号。"},{"i":26,"n":"第二十六条","txt":"交通信号灯由红灯、绿灯、黄灯组成。红灯表示禁止通行，绿灯表示准许通行，黄灯表示警示。"},{"i":27,"n":"第二十七条","txt":"铁路与道路平面交叉的道口，应当设置警示灯、警示标志或者安全防护设施。无人看守的铁路道口，应当在距道口一定距离处设置警示标志。"},{"i":28,"n":"第二十八条","txt":"任何单位和个人不得擅自设置、移动、占用、损毁交通信号灯、交通标志、交通标线。"},{"i":29,"n":"第二十九条","txt":"道路、停车场和道路配套设施的规划、设计、建设，应当符合道路交通安全、畅通的要求，并根据交通需求及时调整。"},{"i":30,"n":"第三十条","txt":"道路出现坍塌、坑漕、水毁、隆起等损毁或者交通信号灯、交通标志、交通标线等交通设施损毁、灭失的，道路、交通设施的养护部门或者管理部门应当设置警示标志并及时修复。"},{"i":31,"n":"第三十一条","txt":"未经许可，任何单位和个人不得占用道路从事非交通活动。"},{"i":32,"n":"第三十二条","txt":"因工程建设需要占用、挖掘道路，或者跨越、穿越道路架设、增设管线设施，应当事先征得道路主管部门的同意；影响交通安全的，还应当征得公安机关交通管理部门的同意。"},{"i":33,"n":"第三十三条","txt":"新建、改建、扩建的公共建筑、商业街区、居住区、大（中）型建筑等，应当配建、增建停车场；停车泊位不足的，应当及时改建或者扩建；投入使用的停车场不得擅自停止使用或者改作他用。"},{"i":34,"n":"第三十四条","txt":"学校、幼儿园、医院、养老院门前的道路没有行人过街设施的，应当施划人行横道线，设置提示标志。"},{"i":35,"n":"第三十五条","txt":"机动车、非机动车实行右侧通行。"},{"i":36,"n":"第三十六条","txt":"根据道路条件和通行需要，道路划分为机动车道、非机动车道和人行道的，机动车、非机动车、行人实行分道通行。没有划分机动车道、非机动车道和人行道的，机动车在道路中间通行，非机动车和行人在道路两侧通行。"},{"i":37,"n":"第三十七条","txt":"道路划设专用车道的，在专用车道内，只准许规定的车辆通行，其他车辆不得进入专用车道内行驶。"},{"i":38,"n":"第三十八条","txt":"车辆、行人应当按照交通信号通行；遇有交通警察现场指挥时，应当按照交通警察的指挥通行；在没有交通信号的道路上，应当在确保安全、畅通的原则下通行。"},{"i":39,"n":"第三十九条","txt":"公安机关交通管理部门根据道路和交通流量的具体情况，可以对机动车、非机动车、行人采取疏导、限制通行、禁止通行等措施。遇有大型群众性活动、大范围施工等情况，需要采取限制交通的措施，或者作出与公众的道路交通活动直接有关的决定，应当提前向社会公告。"},{"i":40,"n":"第四十条","txt":"遇有自然灾害、恶劣气象条件或者重大交通事故等严重影响交通安全的情形，采取其他措施难以保证交通安全时，公安机关交通管理部门可以实行交通管制。"},{"i":41,"n":"第四十一条","txt":"有关道路通行的其他具体规定，由国务院规定。"},{"i":42,"n":"第四十二条","txt":"机动车上道路行驶，不得超过限速标志标明的最高时速。在没有限速标志的路段，应当保持安全车速。"},{"i":43,"n":"第四十三条","txt":"同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车："},{"i":44,"n":"第四十四条","txt":"机动车通过交叉路口，应当按照交通信号灯、交通标志、交通标线或者交通警察的指挥通过；通过没有交通信号灯、交通标志、交通标线或者交通警察指挥的交叉路口时，应当减速慢行，并让行人和优先通行的车辆先行。"},{"i":45,"n":"第四十五条","txt":"机动车遇有前方车辆停车排队等候或者缓慢行驶时，不得借道超车或者占用对面车道，不得穿插等候的车辆。"},{"i":46,"n":"第四十六条","txt":"机动车通过铁路道口时，应当按照交通信号或者管理人员的指挥通行；没有交通信号或者管理人员的，应当减速或者停车，在确认安全后通过。"},{"i":47,"n":"第四十七条","txt":"机动车行经人行横道时，应当减速行驶；遇行人正在通过人行横道，应当停车让行。"},{"i":48,"n":"第四十八条","txt":"机动车载物应当符合核定的载质量，严禁超载；载物的长、宽、高不得违反装载要求，不得遗洒、飘散载运物。"},{"i":49,"n":"第四十九条","txt":"机动车载人不得超过核定的人数，客运机动车不得违反规定载货。"},{"i":50,"n":"第五十条","txt":"禁止货运机动车载客。"},{"i":51,"n":"第五十一条","txt":"机动车行驶时，驾驶人、乘坐人员应当按规定使用安全带，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。"},{"i":52,"n":"第五十二条","txt":"机动车在道路上发生故障，需要停车排除故障时，驾驶人应当立即开启危险报警闪光灯，将机动车移至不妨碍交通的地方停放；难以移动的，应当持续开启危险报警闪光灯，并在来车方向设置警告标志等措施扩大示警距离，必要时迅速报警。"},{"i":53,"n":"第五十三条","txt":"警车、消防车、救护车、工程救险车执行紧急任务时，可以使用警报器、标志灯具；在确保安全的前提下，不受行驶路线、行驶方向、行驶速度和信号灯的限制，其他车辆和行人应当让行。"},{"i":54,"n":"第五十四条","txt":"道路养护车辆、工程作业车进行作业时，在不影响过往车辆通行的前提下，其行驶路线和方向不受交通标志、标线限制，过往车辆和人员应当注意避让。"},{"i":55,"n":"第五十五条","txt":"高速公路、大中城市中心城区内的道路，禁止拖拉机通行。其他禁止拖拉机通行的道路，由省、自治区、直辖市人民政府根据当地实际情况规定。"},{"i":56,"n":"第五十六条","txt":"机动车应当在规定地点停放。禁止在人行道上停放机动车；但是，依照本法第三十三条规定施划的停车泊位除外。"},{"i":57,"n":"第五十七条","txt":"驾驶非机动车在道路上行驶应当遵守有关交通安全的规定。非机动车应当在非机动车道内行驶；在没有非机动车道的道路上，应当靠车行道的右侧行驶。"},{"i":58,"n":"第五十八条","txt":"残疾人机动轮椅车、电动自行车在非机动车道内行驶时，最高时速不得超过十五公里。"},{"i":59,"n":"第五十九条","txt":"非机动车应当在规定地点停放。未设停放地点的，非机动车停放不得妨碍其他车辆和行人通行。"},{"i":60,"n":"第六十条","txt":"驾驭畜力车，应当使用驯服的牲畜；驾驭畜力车横过道路时，驾驭人应当下车牵引牲畜；驾驭人离开车辆时，应当拴系牲畜。"},{"i":61,"n":"第六十一条","txt":"行人应当在人行道内行走，没有人行道的靠路边行走。"},{"i":62,"n":"第六十二条","txt":"行人通过路口或者横过道路，应当走人行横道或者过街设施；通过有交通信号灯的人行横道，应当按照交通信号灯指示通行；通过没有交通信号灯、人行横道的路口，或者在没有过街设施的路段横过道路，应当在确认安全后通过。"},{"i":63,"n":"第六十三条","txt":"行人不得跨越、倚坐道路隔离设施，不得扒车、强行拦车或者实施妨碍道路交通安全的其他行为。"},{"i":64,"n":"第六十四条","txt":"学龄前儿童以及不能辨认或者不能控制自己行为的精神疾病患者、智力障碍者在道路上通行，应当由其监护人、监护人委托的人或者对其负有管理、保护职责的人带领。"},{"i":65,"n":"第六十五条","txt":"行人通过铁路道口时，应当按照交通信号或者管理人员的指挥通行；没有交通信号和管理人员的，应当在确认无火车驶临后，迅速通过。"},{"i":66,"n":"第六十六条","txt":"乘车人不得携带易燃易爆等危险物品，不得向车外抛洒物品，不得有影响驾驶人安全驾驶的行为。"},{"i":67,"n":"第六十七条","txt":"行人、非机动车、拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车以及其他设计最高时速低于七十公里的机动车，不得进入高速公路。高速公路限速标志标明的最高时速不得超过一百二十公里。"},{"i":68,"n":"第六十八条","txt":"机动车在高速公路上发生故障时，应当依照本法第五十二条的有关规定办理；但是，警告标志应当设置在故障车来车方向一百五十米以外，车上人员应当迅速转移到右侧路肩上或者应急车道内，并且迅速报警。"},{"i":69,"n":"第六十九条","txt":"任何单位、个人不得在高速公路上拦截检查行驶的车辆，公安机关的人民警察依法执行紧急公务除外。"},{"i":70,"n":"第七十条","txt":"在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。"},{"i":71,"n":"第七十一条","txt":"车辆发生交通事故后逃逸的，事故现场目击人员和其他知情人员应当向公安机关交通管理部门或者交通警察举报。举报属实的，公安机关交通管理部门应当给予奖励。"},{"i":72,"n":"第七十二条","txt":"公安机关交通管理部门接到交通事故报警后，应当立即派交通警察赶赴现场，先组织抢救受伤人员，并采取措施，尽快恢复交通。"},{"i":73,"n":"第七十三条","txt":"公安机关交通管理部门应当根据交通事故现场勘验、检查、调查情况和有关的检验、鉴定结论，及时制作交通事故认定书，作为处理交通事故的证据。交通事故认定书应当载明交通事故的基本事实、成因和当事人的责任，并送达当事人。"},{"i":74,"n":"第七十四条","txt":"对交通事故损害赔偿的争议，当事人可以请求公安机关交通管理部门调解，也可以直接向人民法院提起民事诉讼。"},{"i":75,"n":"第七十五条","txt":"医疗机构对交通事故中的受伤人员应当及时抢救，不得因抢救费用未及时支付而拖延救治。肇事车辆参加机动车第三者责任强制保险的，由保险公司在责任限额范围内支付抢救费用；抢救费用超过责任限额的，未参加机动车第三者责任强制保险或者肇事后逃逸的，由道路交通事故社会救助基金先行垫付部分或者全部抢救费用，道路交通事故社会救助基金管理机构有权向交通事故责任人追偿。"},{"i":76,"n":"第七十六条","txt":"机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，按照下列规定承担赔偿责任："},{"i":77,"n":"第七十七条","txt":"车辆在道路以外通行时发生的事故，公安机关交通管理部门接到报案的，参照本法有关规定办理。"},{"i":78,"n":"第七十八条","txt":"公安机关交通管理部门应当加强对交通警察的管理，提高交通警察的素质和管理道路交通的水平。"},{"i":79,"n":"第七十九条","txt":"公安机关交通管理部门及其交通警察实施道路交通安全管理，应当依据法定的职权和程序，简化办事手续，做到公正、严格、文明、高效。"},{"i":80,"n":"第八十条","txt":"交通警察执行职务时，应当按照规定着装，佩带人民警察标志，持有人民警察证件，保持警容严整，举止端庄，指挥规范。"},{"i":81,"n":"第八十一条","txt":"依照本法发放牌证等收取工本费，应当严格执行国务院价格主管部门核定的收费标准，并全部上缴国库。"},{"i":82,"n":"第八十二条","txt":"公安机关交通管理部门依法实施罚款的行政处罚，应当依照有关法律、行政法规的规定，实施罚款决定与罚款收缴分离；收缴的罚款以及依法没收的违法所得，应当全部上缴国库。"},{"i":83,"n":"第八十三条","txt":"交通警察调查处理道路交通安全违法行为和交通事故，有下列情形之一的，应当回避："},{"i":84,"n":"第八十四条","txt":"公安机关交通管理部门及其交通警察的行政执法活动，应当接受行政监察机关依法实施的监督。"},{"i":85,"n":"第八十五条","txt":"公安机关交通管理部门及其交通警察执行职务，应当自觉接受社会和公民的监督。"},{"i":86,"n":"第八十六条","txt":"任何单位不得给公安机关交通管理部门下达或者变相下达罚款指标；公安机关交通管理部门不得以罚款数额作为考核交通警察的标准。"},{"i":87,"n":"第八十七条","txt":"公安机关交通管理部门及其交通警察对道路交通安全违法行为，应当及时纠正。"},{"i":88,"n":"第八十八条","txt":"对道路交通安全违法行为的处罚种类包括：警告、罚款、暂扣或者吊销机动车驾驶证、拘留。"},{"i":89,"n":"第八十九条","txt":"行人、乘车人、非机动车驾驶人违反道路交通安全法律、法规关于道路通行规定的，处警告或者五元以上五十元以下罚款；非机动车驾驶人拒绝接受罚款处罚的，可以扣留其非机动车。"},{"i":90,"n":"第九十条","txt":"机动车驾驶人违反道路交通安全法律、法规关于道路通行规定的，处警告或者二十元以上二百元以下罚款。本法另有规定的，依照规定处罚。"},{"i":91,"n":"第九十一条","txt":"饮酒后驾驶机动车的，处暂扣六个月机动车驾驶证，并处一千元以上二千元以下罚款。因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的，处十日以下拘留，并处一千元以上二千元以下罚款，吊销机动车驾驶证。"},{"i":92,"n":"第九十二条","txt":"公路客运车辆载客超过额定乘员的，处二百元以上五百元以下罚款；超过额定乘员百分之二十或者违反规定载货的，处五百元以上二千元以下罚款。"},{"i":93,"n":"第九十三条","txt":"对违反道路交通安全法律、法规关于机动车停放、临时停车规定的，可以指出违法行为，并予以口头警告，令其立即驶离。"},{"i":94,"n":"第九十四条","txt":"机动车安全技术检验机构实施机动车安全技术检验超过国务院价格主管部门核定的收费标准收取费用的，退还多收取的费用，并由价格主管部门依照《中华人民共和国价格法》的有关规定给予处罚。"},{"i":95,"n":"第九十五条","txt":"上道路行驶的机动车未悬挂机动车号牌，未放置检验合格标志、保险标志，或者未随车携带行驶证、驾驶证的，公安机关交通管理部门应当扣留机动车，通知当事人提供相应的牌证、标志或者补办相应手续，并可以依照本法第九十条的规定予以处罚。当事人提供相应的牌证、标志或者补办相应手续的，应当及时退还机动车。"},{"i":96,"n":"第九十六条","txt":"伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处十五日以下拘留，并处二千元以上五千元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":97,"n":"第九十七条","txt":"非法安装警报器、标志灯具的，由公安机关交通管理部门强制拆除，予以收缴，并处二百元以上二千元以下罚款。"},{"i":98,"n":"第九十八条","txt":"机动车所有人、管理人未按照国家规定投保机动车第三者责任强制保险的，由公安机关交通管理部门扣留车辆至依照规定投保后，并处依照规定投保最低责任限额应缴纳的保险费的二倍罚款。"},{"i":99,"n":"第九十九条","txt":"有下列行为之一的，由公安机关交通管理部门处二百元以上二千元以下罚款："},{"i":100,"n":"第一百条","txt":"驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废。"},{"i":101,"n":"第一百零一条","txt":"违反道路交通安全法律、法规的规定，发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证。"},{"i":102,"n":"第一百零二条","txt":"对六个月内发生二次以上特大交通事故负有主要责任或者全部责任的专业运输单位，由公安机关交通管理部门责令消除安全隐患，未消除安全隐患的机动车，禁止上道路行驶。"},{"i":103,"n":"第一百零三条","txt":"国家机动车产品主管部门未按照机动车国家安全技术标准严格审查，许可不合格机动车型投入生产的，对负有责任的主管人员和其他直接责任人员给予降级或者撤职的行政处分。"},{"i":104,"n":"第一百零四条","txt":"未经批准，擅自挖掘道路、占用道路施工或者从事其他影响道路交通安全活动的，由道路主管部门责令停止违法行为，并恢复原状，可以依法给予罚款；致使通行的人员、车辆及其他财产遭受损失的，依法承担赔偿责任。"},{"i":105,"n":"第一百零五条","txt":"道路施工作业或者道路出现损毁，未及时设置警示标志、未采取防护措施，或者应当设置交通信号灯、交通标志、交通标线而没有设置或者应当及时变更交通信号灯、交通标志、交通标线而没有及时变更，致使通行的人员、车辆及其他财产遭受损失的，负有相关职责的单位应当依法承担赔偿责任。"},{"i":106,"n":"第一百零六条","txt":"在道路两侧及隔离带上种植树木、其他植物或者设置广告牌、管线等，遮挡路灯、交通信号灯、交通标志，妨碍安全视距的，由公安机关交通管理部门责令行为人排除妨碍；拒不执行的，处二百元以上二千元以下罚款，并强制排除妨碍，所需费用由行为人负担。"},{"i":107,"n":"第一百零七条","txt":"对道路交通违法行为人予以警告、二百元以下罚款，交通警察可以当场作出行政处罚决定，并出具行政处罚决定书。"},{"i":108,"n":"第一百零八条","txt":"当事人应当自收到罚款的行政处罚决定书之日起十五日内，到指定的银行缴纳罚款。"},{"i":109,"n":"第一百零九条","txt":"当事人逾期不履行行政处罚决定的，作出行政处罚决定的行政机关可以采取下列措施："},{"i":110,"n":"第一百一十条","txt":"执行职务的交通警察认为应当对道路交通违法行为人给予暂扣或者吊销机动车驾驶证处罚的，可以先予扣留机动车驾驶证，并在二十四小时内将案件移交公安机关交通管理部门处理。"},{"i":111,"n":"第一百一十一条","txt":"对违反本法规定予以拘留的行政处罚，由县、市公安局、公安分局或者相当于县一级的公安机关裁决。"},{"i":112,"n":"第一百一十二条","txt":"公安机关交通管理部门扣留机动车、非机动车，应当当场出具凭证，并告知当事人在规定期限内到公安机关交通管理部门接受处理。"},{"i":113,"n":"第一百一十三条","txt":"暂扣机动车驾驶证的期限从处罚决定生效之日起计算；处罚决定生效前先予扣留机动车驾驶证的，扣留一日折抵暂扣期限一日。"},{"i":114,"n":"第一百一十四条","txt":"公安机关交通管理部门根据交通技术监控记录资料，可以对违法的机动车所有人或者管理人依法予以处罚。对能够确定驾驶人的，可以依照本法的规定依法予以处罚。"},{"i":115,"n":"第一百一十五条","txt":"交通警察有下列行为之一的，依法给予行政处分："},{"i":116,"n":"第一百一十六条","txt":"依照本法第一百一十五条的规定，给予交通警察行政处分的，在作出行政处分决定前，可以停止其执行职务；必要时，可以予以禁闭。"},{"i":117,"n":"第一百一十七条","txt":"交通警察利用职权非法占有公共财物，索取、收受贿赂，或者滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任。"},{"i":118,"n":"第一百一十八条","txt":"公安机关交通管理部门及其交通警察有本法第一百一十五条所列行为之一，给当事人造成损失的，应当依法承担赔偿责任。"},{"i":119,"n":"第一百一十九条","txt":"本法中下列用语的含义："},{"i":120,"n":"第一百二十条","txt":"中国人民解放军和中国人民武装警察部队在编机动车牌证、在编机动车检验以及机动车驾驶人考核工作，由中国人民解放军、中国人民武装警察部队有关部门负责。"},{"i":121,"n":"第一百二十一条","txt":"对上道路行驶的拖拉机，由农业（农业机械）主管部门行使本法第八条、第九条、第十三条、第十九条、第二十三条规定的公安机关交通管理部门的管理职权。"},{"i":122,"n":"第一百二十二条","txt":"国家对入境的境外机动车的道路交通安全实施统一管理。"},{"i":123,"n":"第一百二十三条","txt":"省、自治区、直辖市人民代表大会常务委员会可以根据本地区的实际情况，在本法规定的罚款幅度内，规定具体的执行标准。"},{"i":124,"n":"第一百二十四条","txt":"本法自2004年5月1日起施行。"}],"fangzhenjianzaifa":[{"i":1,"n":"第一条","txt":"为了防御和减轻地震灾害，保护人民生命和财产安全，促进经济社会的可持续发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域从事地震监测预报、地震灾害预防、地震应急救援、地震灾后过渡性安置和恢复重建等防震减灾活动，适用本法。"},{"i":3,"n":"第三条","txt":"防震减灾工作，实行预防为主、防御与救助相结合的方针。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当加强对防震减灾工作的领导，将防震减灾工作纳入本级国民经济和社会发展规划，所需经费列入财政预算。"},{"i":5,"n":"第五条","txt":"在国务院的领导下，国务院地震工作主管部门和国务院经济综合宏观调控、建设、民政、卫生、公安以及其他有关部门，按照职责分工，各负其责，密切配合，共同做好防震减灾工作。"},{"i":6,"n":"第六条","txt":"国务院抗震救灾指挥机构负责统一领导、指挥和协调全国抗震救灾工作。县级以上地方人民政府抗震救灾指挥机构负责统一领导、指挥和协调本行政区域的抗震救灾工作。"},{"i":7,"n":"第七条","txt":"各级人民政府应当组织开展防震减灾知识的宣传教育，增强公民的防震减灾意识，提高全社会的防震减灾能力。"},{"i":8,"n":"第八条","txt":"任何单位和个人都有依法参加防震减灾活动的义务。"},{"i":9,"n":"第九条","txt":"中国人民解放军、中国人民武装警察部队和民兵组织，依照本法以及其他有关法律、行政法规、军事法规的规定和国务院、中央军事委员会的命令，执行抗震救灾任务，保护人民生命和财产安全。"},{"i":10,"n":"第十条","txt":"从事防震减灾活动，应当遵守国家有关防震减灾标准。"},{"i":11,"n":"第十一条","txt":"国家鼓励、支持防震减灾的科学技术研究，逐步提高防震减灾科学技术研究经费投入，推广先进的科学研究成果，加强国际合作与交流，提高防震减灾工作水平。"},{"i":12,"n":"第十二条","txt":"国务院地震工作主管部门会同国务院有关部门组织编制国家防震减灾规划，报国务院批准后组织实施。"},{"i":13,"n":"第十三条","txt":"编制防震减灾规划，应当遵循统筹安排、突出重点、合理布局、全面预防的原则，以震情和震害预测结果为依据，并充分考虑人民生命和财产安全及经济社会发展、资源环境保护等需要。"},{"i":14,"n":"第十四条","txt":"防震减灾规划的内容应当包括：震情形势和防震减灾总体目标，地震监测台网建设布局，地震灾害预防措施，地震应急救援措施，以及防震减灾技术、信息、资金、物资等保障措施。"},{"i":15,"n":"第十五条","txt":"防震减灾规划报送审批前，组织编制机关应当征求有关部门、单位、专家和公众的意见。"},{"i":16,"n":"第十六条","txt":"防震减灾规划一经批准公布，应当严格执行；因震情形势变化和经济社会发展的需要确需修改的，应当按照原审批程序报送审批。"},{"i":17,"n":"第十七条","txt":"国家加强地震监测预报工作，建立多学科地震监测系统，逐步提高地震监测预报水平。"},{"i":18,"n":"第十八条","txt":"国家对地震监测台网实行统一规划，分级、分类管理。"},{"i":19,"n":"第十九条","txt":"水库、油田、核电站等重大建设工程的建设单位，应当按照国务院有关规定，建设专用地震监测台网或者强震动监测设施，其建设资金和运行经费由建设单位承担。"},{"i":20,"n":"第二十条","txt":"地震监测台网的建设，应当遵守法律、法规和国家有关标准，保证建设质量。"},{"i":21,"n":"第二十一条","txt":"地震监测台网不得擅自中止或者终止运行。"},{"i":22,"n":"第二十二条","txt":"沿海县级以上地方人民政府负责管理地震工作的部门或者机构，应当加强海域地震活动监测预测工作。海域地震发生后，县级以上地方人民政府负责管理地震工作的部门或者机构，应当及时向海洋主管部门和当地海事管理机构等通报情况。"},{"i":23,"n":"第二十三条","txt":"国家依法保护地震监测设施和地震观测环境。"},{"i":24,"n":"第二十四条","txt":"新建、扩建、改建建设工程，应当避免对地震监测设施和地震观测环境造成危害。建设国家重点工程，确实无法避免对地震监测设施和地震观测环境造成危害的，建设单位应当按照县级以上地方人民政府负责管理地震工作的部门或者机构的要求，增建抗干扰设施；不能增建抗干扰设施的，应当新建地震监测设施。"},{"i":25,"n":"第二十五条","txt":"国务院地震工作主管部门建立健全地震监测信息共享平台，为社会提供服务。"},{"i":26,"n":"第二十六条","txt":"国务院地震工作主管部门和县级以上地方人民政府负责管理地震工作的部门或者机构，根据地震监测信息研究结果，对可能发生地震的地点、时间和震级作出预测。"},{"i":27,"n":"第二十七条","txt":"观测到可能与地震有关的异常现象的单位和个人，可以向所在地县级以上地方人民政府负责管理地震工作的部门或者机构报告，也可以直接向国务院地震工作主管部门报告。"},{"i":28,"n":"第二十八条","txt":"国务院地震工作主管部门和省、自治区、直辖市人民政府负责管理地震工作的部门或者机构，应当组织召开震情会商会，必要时邀请有关部门、专家和其他有关人员参加，对地震预测意见和可能与地震有关的异常现象进行综合分析研究，形成震情会商意见，报本级人民政府；经震情会商形成地震预报意见的，在报本级人民政府前，应当进行评审，作出评审结果，并提出对策建议。"},{"i":29,"n":"第二十九条","txt":"国家对地震预报意见实行统一发布制度。"},{"i":30,"n":"第三十条","txt":"国务院地震工作主管部门根据地震活动趋势和震害预测结果，提出确定地震重点监视防御区的意见，报国务院批准。"},{"i":31,"n":"第三十一条","txt":"国家支持全国地震烈度速报系统的建设。"},{"i":32,"n":"第三十二条","txt":"国务院地震工作主管部门和县级以上地方人民政府负责管理地震工作的部门或者机构，应当对发生地震灾害的区域加强地震监测，在地震现场设立流动观测点，根据震情的发展变化，及时对地震活动趋势作出分析、判定，为余震防范工作提供依据。"},{"i":33,"n":"第三十三条","txt":"外国的组织或者个人在中华人民共和国领域和中华人民共和国管辖的其他海域从事地震监测活动，必须经国务院地震工作主管部门会同有关部门批准，并采取与中华人民共和国有关部门或者单位合作的形式进行。"},{"i":34,"n":"第三十四条","txt":"国务院地震工作主管部门负责制定全国地震烈度区划图或者地震动参数区划图。"},{"i":35,"n":"第三十五条","txt":"新建、扩建、改建建设工程，应当达到抗震设防要求。"},{"i":36,"n":"第三十六条","txt":"有关建设工程的强制性标准，应当与抗震设防要求相衔接。"},{"i":37,"n":"第三十七条","txt":"国家鼓励城市人民政府组织制定地震小区划图。地震小区划图由国务院地震工作主管部门负责审定。"},{"i":38,"n":"第三十八条","txt":"建设单位对建设工程的抗震设计、施工的全过程负责。"},{"i":39,"n":"第三十九条","txt":"已经建成的下列建设工程，未采取抗震设防措施或者抗震设防措施未达到抗震设防要求的，应当按照国家有关规定进行抗震性能鉴定，并采取必要的抗震加固措施："},{"i":40,"n":"第四十条","txt":"县级以上地方人民政府应当加强对农村村民住宅和乡村公共设施抗震设防的管理，组织开展农村实用抗震技术的研究和开发，推广达到抗震设防要求、经济适用、具有当地特色的建筑设计和施工技术，培训相关技术人员，建设示范工程，逐步提高农村村民住宅和乡村公共设施的抗震设防水平。"},{"i":41,"n":"第四十一条","txt":"城乡规划应当根据地震应急避难的需要，合理确定应急疏散通道和应急避难场所，统筹安排地震应急避难所必需的交通、供水、供电、排污等基础设施建设。"},{"i":42,"n":"第四十二条","txt":"地震重点监视防御区的县级以上地方人民政府应当根据实际需要，在本级财政预算和物资储备中安排抗震救灾资金、物资。"},{"i":43,"n":"第四十三条","txt":"国家鼓励、支持研究开发和推广使用符合抗震设防要求、经济实用的新技术、新工艺、新材料。"},{"i":44,"n":"第四十四条","txt":"县级人民政府及其有关部门和乡、镇人民政府、城市街道办事处等基层组织，应当组织开展地震应急知识的宣传普及活动和必要的地震应急救援演练，提高公民在地震灾害中自救互救的能力。"},{"i":45,"n":"第四十五条","txt":"国家发展有财政支持的地震灾害保险事业，鼓励单位和个人参加地震灾害保险。"},{"i":46,"n":"第四十六条","txt":"国务院地震工作主管部门会同国务院有关部门制定国家地震应急预案，报国务院批准。国务院有关部门根据国家地震应急预案，制定本部门的地震应急预案，报国务院地震工作主管部门备案。"},{"i":47,"n":"第四十七条","txt":"地震应急预案的内容应当包括：组织指挥体系及其职责，预防和预警机制，处置程序，应急响应和应急保障措施等。"},{"i":48,"n":"第四十八条","txt":"地震预报意见发布后，有关省、自治区、直辖市人民政府根据预报的震情可以宣布有关区域进入临震应急期；有关地方人民政府应当按照地震应急预案，组织有关部门做好应急防范和抗震救灾准备工作。"},{"i":49,"n":"第四十九条","txt":"按照社会危害程度、影响范围等因素，地震灾害分为一般、较大、重大和特别重大四级。具体分级标准按照国务院规定执行。"},{"i":50,"n":"第五十条","txt":"地震灾害发生后，抗震救灾指挥机构应当立即组织有关部门和单位迅速查清受灾情况，提出地震应急救援力量的配置方案，并采取以下紧急措施："},{"i":51,"n":"第五十一条","txt":"特别重大地震灾害发生后，国务院抗震救灾指挥机构在地震灾区成立现场指挥机构，并根据需要设立相应的工作组，统一组织领导、指挥和协调抗震救灾工作。"},{"i":52,"n":"第五十二条","txt":"地震灾区的县级以上地方人民政府应当及时将地震震情和灾情等信息向上一级人民政府报告，必要时可以越级上报，不得迟报、谎报、瞒报。"},{"i":53,"n":"第五十三条","txt":"国家鼓励、扶持地震应急救援新技术和装备的研究开发，调运和储备必要的应急救援设施、装备，提高应急救援水平。"},{"i":54,"n":"第五十四条","txt":"国务院建立国家地震灾害紧急救援队伍。"},{"i":55,"n":"第五十五条","txt":"县级以上人民政府有关部门应当按照职责分工，协调配合，采取有效措施，保障地震灾害紧急救援队伍和医疗救治队伍快速、高效地开展地震灾害紧急救援活动。"},{"i":56,"n":"第五十六条","txt":"县级以上地方人民政府及其有关部门可以建立地震灾害救援志愿者队伍，并组织开展地震应急救援知识培训和演练，使志愿者掌握必要的地震应急救援技能，增强地震灾害应急救援能力。"},{"i":57,"n":"第五十七条","txt":"国务院地震工作主管部门会同有关部门和单位，组织协调外国救援队和医疗队在中华人民共和国开展地震灾害紧急救援活动。"},{"i":58,"n":"第五十八条","txt":"国务院或者地震灾区的省、自治区、直辖市人民政府应当及时组织对地震灾害损失进行调查评估，为地震应急救援、灾后过渡性安置和恢复重建提供依据。"},{"i":59,"n":"第五十九条","txt":"地震灾区受灾群众需要过渡性安置的，应当根据地震灾区的实际情况，在确保安全的前提下，采取灵活多样的方式进行安置。"},{"i":60,"n":"第六十条","txt":"过渡性安置点应当设置在交通条件便利、方便受灾群众恢复生产和生活的区域，并避开地震活动断层和可能发生严重次生灾害的区域。"},{"i":61,"n":"第六十一条","txt":"实施过渡性安置应当尽量保护农用地，并避免对自然保护区、饮用水水源保护区以及生态脆弱区域造成破坏。"},{"i":62,"n":"第六十二条","txt":"过渡性安置点所在地的县级人民政府，应当组织有关部门加强对次生灾害、饮用水水质、食品卫生、疫情等的监测，开展流行病学调查，整治环境卫生，避免对土壤、水环境等造成污染。"},{"i":63,"n":"第六十三条","txt":"地震灾区的县级以上地方人民政府及其有关部门和乡、镇人民政府，应当及时组织修复毁损的农业生产设施，提供农业生产技术指导，尽快恢复农业生产；优先恢复供电、供水、供气等企业的生产，并对大型骨干企业恢复生产提供支持，为全面恢复农业、工业、服务业生产经营提供条件。"},{"i":64,"n":"第六十四条","txt":"各级人民政府应当加强对地震灾后恢复重建工作的领导、组织和协调。"},{"i":65,"n":"第六十五条","txt":"国务院有关部门应当组织有关专家开展地震活动对相关建设工程破坏机理的调查评估，为修订完善有关建设工程的强制性标准、采取抗震设防措施提供科学依据。"},{"i":66,"n":"第六十六条","txt":"特别重大地震灾害发生后，国务院经济综合宏观调控部门会同国务院有关部门与地震灾区的省、自治区、直辖市人民政府共同组织编制地震灾后恢复重建规划，报国务院批准后组织实施；重大、较大、一般地震灾害发生后，由地震灾区的省、自治区、直辖市人民政府根据实际需要组织编制地震灾后恢复重建规划。"},{"i":67,"n":"第六十七条","txt":"地震灾后恢复重建规划应当根据地质条件和地震活动断层分布以及资源环境承载能力，重点对城镇和乡村的布局、基础设施和公共服务设施的建设、防灾减灾和生态环境以及自然资源和历史文化遗产保护等作出安排。"},{"i":68,"n":"第六十八条","txt":"地震灾区的地方各级人民政府应当根据地震灾后恢复重建规划和当地经济社会发展水平，有计划、分步骤地组织实施地震灾后恢复重建。"},{"i":69,"n":"第六十九条","txt":"地震灾区的县级以上地方人民政府应当组织有关部门和专家，根据地震灾害损失调查评估结果，制定清理保护方案，明确典型地震遗址、遗迹和文物保护单位以及具有历史价值与民族特色的建筑物、构筑物的保护范围和措施。"},{"i":70,"n":"第七十条","txt":"地震灾后恢复重建，应当统筹安排交通、铁路、水利、电力、通信、供水、供电等基础设施和市政公用设施，学校、医院、文化、商贸服务、防灾减灾、环境保护等公共服务设施，以及住房和无障碍设施的建设，合理确定建设规模和时序。"},{"i":71,"n":"第七十一条","txt":"地震灾区的县级以上地方人民政府应当组织有关部门和单位，抢救、保护与收集整理有关档案、资料，对因地震灾害遗失、毁损的档案、资料，及时补充和恢复。"},{"i":72,"n":"第七十二条","txt":"地震灾后恢复重建应当坚持政府主导、社会参与和市场运作相结合的原则。"},{"i":73,"n":"第七十三条","txt":"地震灾区的地方各级人民政府应当组织做好救助、救治、康复、补偿、抚慰、抚恤、安置、心理援助、法律服务、公共文化服务等工作。"},{"i":74,"n":"第七十四条","txt":"对地震灾后恢复重建中需要办理行政审批手续的事项，有审批权的人民政府及有关部门应当按照方便群众、简化手续、提高效率的原则，依法及时予以办理。"},{"i":75,"n":"第七十五条","txt":"县级以上人民政府依法加强对防震减灾规划和地震应急预案的编制与实施、地震应急避难场所的设置与管理、地震灾害紧急救援队伍的培训、防震减灾知识宣传教育和地震应急救援演练等工作的监督检查。"},{"i":76,"n":"第七十六条","txt":"县级以上人民政府建设、交通、铁路、水利、电力、地震等有关部门应当按照职责分工，加强对工程建设强制性标准、抗震设防要求执行情况和地震安全性评价工作的监督检查。"},{"i":77,"n":"第七十七条","txt":"禁止侵占、截留、挪用地震应急救援、地震灾后过渡性安置和恢复重建的资金、物资。"},{"i":78,"n":"第七十八条","txt":"地震灾区的地方人民政府应当定期公布地震应急救援、地震灾后过渡性安置和恢复重建的资金、物资以及社会捐赠款物的来源、数量、发放和使用情况，接受社会监督。"},{"i":79,"n":"第七十九条","txt":"审计机关应当加强对地震应急救援、地震灾后过渡性安置和恢复重建的资金、物资的筹集、分配、拨付、使用的审计，并及时公布审计结果。"},{"i":80,"n":"第八十条","txt":"监察机关应当加强对参与防震减灾工作的国家行政机关和法律、法规授权的具有管理公共事务职能的组织及其工作人员的监察。"},{"i":81,"n":"第八十一条","txt":"任何单位和个人对防震减灾活动中的违法行为，有权进行举报。"},{"i":82,"n":"第八十二条","txt":"国务院地震工作主管部门、县级以上地方人民政府负责管理地震工作的部门或者机构，以及其他依照本法规定行使监督管理权的部门，不依法作出行政许可或者办理批准文件的，发现违法行为或者接到对违法行为的举报后不予查处的，或者有其他未依照本法规定履行职责的行为的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":83,"n":"第八十三条","txt":"未按照法律、法规和国家有关标准进行地震监测台网建设的，由国务院地震工作主管部门或者县级以上地方人民政府负责管理地震工作的部门或者机构责令改正，采取相应的补救措施；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":84,"n":"第八十四条","txt":"违反本法规定，有下列行为之一的，由国务院地震工作主管部门或者县级以上地方人民政府负责管理地震工作的部门或者机构责令停止违法行为，恢复原状或者采取其他补救措施；造成损失的，依法承担赔偿责任："},{"i":85,"n":"第八十五条","txt":"违反本法规定，未按照要求增建抗干扰设施或者新建地震监测设施的，由国务院地震工作主管部门或者县级以上地方人民政府负责管理地震工作的部门或者机构责令限期改正；逾期不改正的，处二万元以上二十万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":86,"n":"第八十六条","txt":"违反本法规定，外国的组织或者个人未经批准，在中华人民共和国领域和中华人民共和国管辖的其他海域从事地震监测活动的，由国务院地震工作主管部门责令停止违法行为，没收监测成果和监测设施，并处一万元以上十万元以下的罚款；情节严重的，并处十万元以上五十万元以下的罚款。"},{"i":87,"n":"第八十七条","txt":"未依法进行地震安全性评价，或者未按照地震安全性评价报告所确定的抗震设防要求进行抗震设防的，由国务院地震工作主管部门或者县级以上地方人民政府负责管理地震工作的部门或者机构责令限期改正；逾期不改正的，处三万元以上三十万元以下的罚款。"},{"i":88,"n":"第八十八条","txt":"违反本法规定，向社会散布地震预测意见、地震预报意见及其评审结果，或者在地震灾后过渡性安置、地震灾后恢复重建中扰乱社会秩序，构成违反治安管理行为的，由公安机关依法给予处罚。"},{"i":89,"n":"第八十九条","txt":"地震灾区的县级以上地方人民政府迟报、谎报、瞒报地震震情、灾情等信息的，由上级人民政府责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":90,"n":"第九十条","txt":"侵占、截留、挪用地震应急救援、地震灾后过渡性安置或者地震灾后恢复重建的资金、物资的，由财政部门、审计机关在各自职责范围内，责令改正，追回被侵占、截留、挪用的资金、物资；有违法所得的，没收违法所得；对单位给予警告或者通报批评；对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":91,"n":"第九十一条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":92,"n":"第九十二条","txt":"本法下列用语的含义："},{"i":93,"n":"第九十三条","txt":"本法自2009年5月1日起施行。"}],"feiwuzhiwenhuayichanfa":[{"i":1,"n":"第一条","txt":"为了继承和弘扬中华民族优秀传统文化，促进社会主义精神文明建设，加强非物质文化遗产保护、保存工作，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称非物质文化遗产，是指各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，以及与传统文化表现形式相关的实物和场所。包括："},{"i":3,"n":"第三条","txt":"国家对非物质文化遗产采取认定、记录、建档等措施予以保存，对体现中华民族优秀传统文化，具有历史、文学、艺术、科学价值的非物质文化遗产采取传承、传播等措施予以保护。"},{"i":4,"n":"第四条","txt":"保护非物质文化遗产，应当注重其真实性、整体性和传承性，有利于增强中华民族的文化认同，有利于维护国家统一和民族团结，有利于促进社会和谐和可持续发展。"},{"i":5,"n":"第五条","txt":"使用非物质文化遗产，应当尊重其形式和内涵。"},{"i":6,"n":"第六条","txt":"县级以上人民政府应当将非物质文化遗产保护、保存工作纳入本级国民经济和社会发展规划，并将保护、保存经费列入本级财政预算。"},{"i":7,"n":"第七条","txt":"国务院文化主管部门负责全国非物质文化遗产的保护、保存工作；县级以上地方人民政府文化主管部门负责本行政区域内非物质文化遗产的保护、保存工作。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当加强对非物质文化遗产保护工作的宣传，提高全社会保护非物质文化遗产的意识。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持公民、法人和其他组织参与非物质文化遗产保护工作。"},{"i":10,"n":"第十条","txt":"对在非物质文化遗产保护工作中做出显著贡献的组织和个人，按照国家有关规定予以表彰、奖励。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府根据非物质文化遗产保护、保存工作需要，组织非物质文化遗产调查。非物质文化遗产调查由文化主管部门负责进行。"},{"i":12,"n":"第十二条","txt":"文化主管部门和其他有关部门进行非物质文化遗产调查，应当对非物质文化遗产予以认定、记录、建档，建立健全调查信息共享机制。"},{"i":13,"n":"第十三条","txt":"文化主管部门应当全面了解非物质文化遗产有关情况，建立非物质文化遗产档案及相关数据库。除依法应当保密的外，非物质文化遗产档案及相关数据信息应当公开，便于公众查阅。"},{"i":14,"n":"第十四条","txt":"公民、法人和其他组织可以依法进行非物质文化遗产调查。"},{"i":15,"n":"第十五条","txt":"境外组织或者个人在中华人民共和国境内进行非物质文化遗产调查，应当报经省、自治区、直辖市人民政府文化主管部门批准；调查在两个以上省、自治区、直辖市行政区域进行的，应当报经国务院文化主管部门批准；调查结束后，应当向批准调查的文化主管部门提交调查报告和调查中取得的实物图片、资料复制件。"},{"i":16,"n":"第十六条","txt":"进行非物质文化遗产调查，应当征得调查对象的同意，尊重其风俗习惯，不得损害其合法权益。"},{"i":17,"n":"第十七条","txt":"对通过调查或者其他途径发现的濒临消失的非物质文化遗产项目，县级人民政府文化主管部门应当立即予以记录并收集有关实物，或者采取其他抢救性保存措施；对需要传承的，应当采取有效措施支持传承。"},{"i":18,"n":"第十八条","txt":"国务院建立国家级非物质文化遗产代表性项目名录，将体现中华民族优秀传统文化，具有重大历史、文学、艺术、科学价值的非物质文化遗产项目列入名录予以保护。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市人民政府可以从本省、自治区、直辖市非物质文化遗产代表性项目名录中向国务院文化主管部门推荐列入国家级非物质文化遗产代表性项目名录的项目。推荐时应当提交下列材料："},{"i":20,"n":"第二十条","txt":"公民、法人和其他组织认为某项非物质文化遗产体现中华民族优秀传统文化，具有重大历史、文学、艺术、科学价值的，可以向省、自治区、直辖市人民政府或者国务院文化主管部门提出列入国家级非物质文化遗产代表性项目名录的建议。"},{"i":21,"n":"第二十一条","txt":"相同的非物质文化遗产项目，其形式和内涵在两个以上地区均保持完整的，可以同时列入国家级非物质文化遗产代表性项目名录。"},{"i":22,"n":"第二十二条","txt":"国务院文化主管部门应当组织专家评审小组和专家评审委员会，对推荐或者建议列入国家级非物质文化遗产代表性项目名录的非物质文化遗产项目进行初评和审议。"},{"i":23,"n":"第二十三条","txt":"国务院文化主管部门应当将拟列入国家级非物质文化遗产代表性项目名录的项目予以公示，征求公众意见。公示时间不得少于二十日。"},{"i":24,"n":"第二十四条","txt":"国务院文化主管部门根据专家评审委员会的审议意见和公示结果，拟订国家级非物质文化遗产代表性项目名录，报国务院批准、公布。"},{"i":25,"n":"第二十五条","txt":"国务院文化主管部门应当组织制定保护规划，对国家级非物质文化遗产代表性项目予以保护。"},{"i":26,"n":"第二十六条","txt":"对非物质文化遗产代表性项目集中、特色鲜明、形式和内涵保持完整的特定区域，当地文化主管部门可以制定专项保护规划，报经本级人民政府批准后，实行区域性整体保护。确定对非物质文化遗产实行区域性整体保护，应当尊重当地居民的意愿，并保护属于非物质文化遗产组成部分的实物和场所，避免遭受破坏。"},{"i":27,"n":"第二十七条","txt":"国务院文化主管部门和省、自治区、直辖市人民政府文化主管部门应当对非物质文化遗产代表性项目保护规划的实施情况进行监督检查；发现保护规划未能有效实施的，应当及时纠正、处理。"},{"i":28,"n":"第二十八条","txt":"国家鼓励和支持开展非物质文化遗产代表性项目的传承、传播。"},{"i":29,"n":"第二十九条","txt":"国务院文化主管部门和省、自治区、直辖市人民政府文化主管部门对本级人民政府批准公布的非物质文化遗产代表性项目，可以认定代表性传承人。"},{"i":30,"n":"第三十条","txt":"县级以上人民政府文化主管部门根据需要，采取下列措施，支持非物质文化遗产代表性项目的代表性传承人开展传承、传播活动："},{"i":31,"n":"第三十一条","txt":"非物质文化遗产代表性项目的代表性传承人应当履行下列义务："},{"i":32,"n":"第三十二条","txt":"县级以上人民政府应当结合实际情况，采取有效措施，组织文化主管部门和其他有关部门宣传、展示非物质文化遗产代表性项目。"},{"i":33,"n":"第三十三条","txt":"国家鼓励开展与非物质文化遗产有关的科学技术研究和非物质文化遗产保护、保存方法研究，鼓励开展非物质文化遗产的记录和非物质文化遗产代表性项目的整理、出版等活动。"},{"i":34,"n":"第三十四条","txt":"学校应当按照国务院教育主管部门的规定，开展相关的非物质文化遗产教育。"},{"i":35,"n":"第三十五条","txt":"图书馆、文化馆、博物馆、科技馆等公共文化机构和非物质文化遗产学术研究机构、保护机构以及利用财政性资金举办的文艺表演团体、演出场所经营单位等，应当根据各自业务范围，开展非物质文化遗产的整理、研究、学术交流和非物质文化遗产代表性项目的宣传、展示。"},{"i":36,"n":"第三十六条","txt":"国家鼓励和支持公民、法人和其他组织依法设立非物质文化遗产展示场所和传承场所，展示和传承非物质文化遗产代表性项目。"},{"i":37,"n":"第三十七条","txt":"国家鼓励和支持发挥非物质文化遗产资源的特殊优势，在有效保护的基础上，合理利用非物质文化遗产代表性项目开发具有地方、民族特色和市场潜力的文化产品和文化服务。"},{"i":38,"n":"第三十八条","txt":"文化主管部门和其他有关部门的工作人员在非物质文化遗产保护、保存工作中玩忽职守、滥用职权、徇私舞弊的，依法给予处分。"},{"i":39,"n":"第三十九条","txt":"文化主管部门和其他有关部门的工作人员进行非物质文化遗产调查时侵犯调查对象风俗习惯，造成严重后果的，依法给予处分。"},{"i":40,"n":"第四十条","txt":"违反本法规定，破坏属于非物质文化遗产组成部分的实物和场所的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚。"},{"i":41,"n":"第四十一条","txt":"境外组织违反本法第十五条规定的，由文化主管部门责令改正，给予警告，没收违法所得及调查中取得的实物、资料；情节严重的，并处十万元以上五十万元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"建立地方非物质文化遗产代表性项目名录的办法，由省、自治区、直辖市参照本法有关规定制定。"},{"i":44,"n":"第四十四条","txt":"使用非物质文化遗产涉及知识产权的，适用有关法律、行政法规的规定。"},{"i":45,"n":"第四十五条","txt":"本法自2011年6月1日起施行。"}],"yubeiyirenyuanfa":[{"i":1,"n":"第一条","txt":"为了健全预备役人员制度，规范预备役人员管理，维护预备役人员合法权益，保障预备役人员有效履行职责使命，加强国防力量建设，根据宪法和《中华人民共和国国防法》、《中华人民共和国兵役法》，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称预备役人员，是指依法履行兵役义务，预编到中国人民解放军现役部队或者编入中国人民解放军预备役部队服预备役的公民。"},{"i":3,"n":"第三条","txt":"预备役人员工作坚持中国共产党的领导，贯彻习近平强军思想，坚持总体国家安全观，贯彻新时代军事战略方针，以军事需求为牵引，以备战打仗为指向，以质量建设为着力点，提高预备役人员履行使命任务的能力和水平。"},{"i":4,"n":"第四条","txt":"预备役人员必须服从命令、严守纪律，英勇顽强、不怕牺牲，按照规定参加政治教育和军事训练、担负战备勤务、执行非战争军事行动任务，随时准备应召参战，保卫祖国。"},{"i":5,"n":"第五条","txt":"中央军事委员会领导预备役人员工作。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府和有关军事机关应当根据预备役人员工作需要召开军地联席会议，协调解决有关问题。"},{"i":7,"n":"第七条","txt":"机关、团体、企业事业组织和乡镇人民政府、街道办事处应当支持预备役人员履行预备役职责，协助做好预备役人员工作。"},{"i":8,"n":"第八条","txt":"国家加强预备役人员工作信息化建设。"},{"i":9,"n":"第九条","txt":"预备役人员工作所需经费，按照财政事权和支出责任划分原则列入中央和地方预算。"},{"i":10,"n":"第十条","txt":"预备役人员在履行预备役职责中做出突出贡献的，按照国家和军队有关规定给予表彰和奖励。"},{"i":11,"n":"第十一条","txt":"国家实行预备役军衔制度。"},{"i":12,"n":"第十二条","txt":"预备役军衔分为预备役军官军衔、预备役军士军衔和预备役兵军衔。"},{"i":13,"n":"第十三条","txt":"预备役军衔按照军种划分种类，在预备役军衔前冠以军种名称。"},{"i":14,"n":"第十四条","txt":"预备役军衔的授予和晋升，以预备役人员任职岗位、德才表现、服役时间和做出的贡献为依据，具体办法由中央军事委员会规定。"},{"i":15,"n":"第十五条","txt":"预备役人员退出预备役的，其预备役军衔予以保留，在其军衔前冠以“退役”。"},{"i":16,"n":"第十六条","txt":"对违反军队纪律的预备役人员，按照中央军事委员会的有关规定，可以降低其预备役军衔等级。"},{"i":17,"n":"第十七条","txt":"预备役人员应当符合下列条件："},{"i":18,"n":"第十八条","txt":"预备役人员主要从符合服预备役条件、经过预备役登记的退役军人和专业技术人才、专业技能人才中选拔补充。"},{"i":19,"n":"第十九条","txt":"预备役人员的选拔补充计划由中央军事委员会确定。中央军事委员会机关有关部门会同有关中央国家机关，指导部队和县级以上地方人民政府兵役机关实施。"},{"i":20,"n":"第二十条","txt":"部队应当按照规定的标准条件，会同县级以上地方人民政府兵役机关遴选确定预备役人员。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府兵役机关应当向部队及时、准确地提供本行政区域公民预备役登记信息，组织预备役人员选拔补充对象的政治考核、体格检查等工作，办理相关入役手续。"},{"i":22,"n":"第二十二条","txt":"机关、团体、企业事业组织和乡镇人民政府、街道办事处，应当根据部队需要和县、自治县、不设区的市、市辖区人民政府兵役机关的安排，组织推荐本单位、本行政区域符合条件的人员参加预备役人员选拔补充。"},{"i":23,"n":"第二十三条","txt":"部队应当按照规定，对选拔补充的预备役人员授予预备役军衔、任用岗位职务。"},{"i":24,"n":"第二十四条","txt":"预备役人员的教育训练，坚持院校教育、训练实践、职业培训相结合，纳入国家和军队教育培训体系。"},{"i":25,"n":"第二十五条","txt":"预备役人员在被授予和晋升预备役军衔、任用岗位职务前，应当根据需要接受相应的教育训练。"},{"i":26,"n":"第二十六条","txt":"预备役人员应当按照规定参加军事训练，达到军事训练大纲规定的训练要求。"},{"i":27,"n":"第二十七条","txt":"预备役人员在服预备役期间应当按照规定参加职业培训，提高履行预备役职责的能力。"},{"i":28,"n":"第二十八条","txt":"对预备役人员应当进行考核。考核工作由部队按照规定组织实施，考核结果作为其预备役军衔晋升、职务任用、待遇调整、奖励惩戒等的依据。"},{"i":29,"n":"第二十九条","txt":"预备役人员表现优秀、符合条件的，可以按照规定晋升预备役军衔、任用部队相应岗位职务。"},{"i":30,"n":"第三十条","txt":"预备役人员有单位变更、迁居、出国（境）、患严重疾病、身体残疾等重要事项以及联系方式发生变化的，应当及时向部队报告。"},{"i":31,"n":"第三十一条","txt":"预备役人员因迁居等原因需要变更预备役登记地的，相关县、自治县、不设区的市、市辖区人民政府兵役机关应当及时变更其预备役登记信息。"},{"i":32,"n":"第三十二条","txt":"预备役人员参加军事训练、担负战备勤务、执行非战争军事行动任务等的召集，由部队通知本人，并通报其所在单位和预备役登记地县、自治县、不设区的市、市辖区人民政府兵役机关。"},{"i":33,"n":"第三十三条","txt":"预备役人员参加军事训练、担负战备勤务、执行非战争军事行动任务等期间，由部队按照军队有关规定管理。"},{"i":34,"n":"第三十四条","txt":"预备役人员按照军队有关规定穿着预备役制式服装、佩带预备役标志服饰。"},{"i":35,"n":"第三十五条","txt":"预备役人员应当落实军队战备工作有关规定，做好执行任务的准备。"},{"i":36,"n":"第三十六条","txt":"在国家发布动员令或者国务院、中央军事委员会依法采取必要的国防动员措施后，部队应当根据上级的命令，迅速向被征召的预备役人员下达征召通知，并通报其预备役登记地县、自治县、不设区的市、市辖区人民政府兵役机关和所在单位。"},{"i":37,"n":"第三十七条","txt":"预备役登记地县、自治县、不设区的市、市辖区人民政府兵役机关，预备役人员所在单位和乡镇人民政府、街道办事处，应当督促预备役人员响应征召，为预备役人员征召提供必要的支持和协助，帮助解决困难，维护预备役人员合法权益。"},{"i":38,"n":"第三十八条","txt":"预备役人员有下列情形之一的，经其预备役登记地县、自治县、不设区的市、市辖区人民政府兵役机关核实，并经部队批准，可以暂缓征召："},{"i":39,"n":"第三十九条","txt":"被征召的预备役人员，根据军队有关规定转服现役。"},{"i":40,"n":"第四十条","txt":"国家解除国防动员后，由预备役人员转服现役的军人需要退出现役的，按照军人退出现役的有关规定由各级人民政府妥善安置。被征召的预备役人员未转服现役的，部队应当安排其返回，并通知其预备役登记地县、自治县、不设区的市、市辖区人民政府兵役机关和所在单位。"},{"i":41,"n":"第四十一条","txt":"国家建立激励与补偿相结合的预备役人员津贴补贴制度。"},{"i":42,"n":"第四十二条","txt":"预备役人员参战，享受军人同等医疗待遇；参加军事训练、担负战备勤务、执行非战争军事行动任务期间，按照规定享受国家和军队相应医疗待遇。"},{"i":43,"n":"第四十三条","txt":"预备役人员参加军事训练、担负战备勤务、执行非战争军事行动任务期间，军队为其购买人身意外伤害保险。"},{"i":44,"n":"第四十四条","txt":"预备役人员参战、参加军事训练、担负战备勤务、执行非战争军事行动任务期间，其家庭因自然灾害、意外事故、重大疾病等原因，基本生活出现严重困难的，地方人民政府和部队应当按照有关规定给予救助和慰问。"},{"i":45,"n":"第四十五条","txt":"预备役人员所在单位不得因预备役人员履行预备役职责，对其作出辞退、解聘或者解除劳动关系、免职、降低待遇、处分等处理。"},{"i":46,"n":"第四十六条","txt":"预备役人员所在单位按照国家有关规定享受优惠和扶持政策。"},{"i":47,"n":"第四十七条","txt":"预备役人员按照规定享受优待。"},{"i":48,"n":"第四十八条","txt":"预备役人员被授予和晋升预备役军衔，获得功勋荣誉表彰，以及退出预备役时，部队应当举行仪式。"},{"i":49,"n":"第四十九条","txt":"女性预备役人员的合法权益受法律保护。部队应当根据女性预备役人员的特点，合理安排女性预备役人员的岗位和任务。"},{"i":50,"n":"第五十条","txt":"预备役人员退出预备役后，按照规定享受相应的荣誉和待遇。"},{"i":51,"n":"第五十一条","txt":"预备役军官、预备役军士在本衔级服预备役的最低年限为四年。"},{"i":52,"n":"第五十二条","txt":"预备役人员服预备役达到最高年龄的，应当退出预备役。预备役人员服预备役的最高年龄："},{"i":53,"n":"第五十三条","txt":"预备役军官、预备役军士服预备役未满本衔级最低年限或者未达到最高年龄，预备役兵服预备役未满规定年限或者未达到最高年龄，有下列情形之一的，应当安排退出预备役："},{"i":54,"n":"第五十四条","txt":"预备役军官、预备役军士服预备役满本衔级最低年限或者达到最高年龄，预备役兵服预备役满规定年限或者达到最高年龄，有下列情形之一的，不得退出预备役："},{"i":55,"n":"第五十五条","txt":"预备役人员有下列情形之一的，应当取消预备役人员身份："},{"i":56,"n":"第五十六条","txt":"预备役人员退出预备役的时间为下达退出预备役命令之日。"},{"i":57,"n":"第五十七条","txt":"批准预备役人员退出预备役的权限，与批准晋升相应预备役军衔的权限相同。"},{"i":58,"n":"第五十八条","txt":"经过预备役登记的公民拒绝、逃避参加预备役人员选拔补充的，预备役人员拒绝、逃避参加军事训练、担负战备勤务、执行非战争军事行动任务和征召的，由县级人民政府责令限期改正；逾期不改的，由县级人民政府强制其履行兵役义务，并处以罚款；属于公职人员的，还应当依法给予处分。"},{"i":59,"n":"第五十九条","txt":"预备役人员参战、参加军事训练、担负战备勤务、执行非战争军事行动任务期间，违反纪律的，由部队按照有关规定给予处分。"},{"i":60,"n":"第六十条","txt":"国家机关及其工作人员、军队单位及其工作人员在预备役人员工作中滥用职权、玩忽职守、徇私舞弊，或者有其他违反本法规定行为的，由其所在单位、主管部门或者上级机关责令改正；对负有责任的领导人员和直接责任人员，依法给予处分。"},{"i":61,"n":"第六十一条","txt":"机关、团体、企业事业组织拒绝完成本法规定的预备役人员工作任务的，阻挠公民履行预备役义务的，或者有其他妨害预备役人员工作行为的，由县级以上地方人民政府责令改正，并可以处以罚款；对负有责任的领导人员和直接责任人员，依法给予处分、处罚。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"本法第五十八条、第六十一条第一款规定的处罚，由县级以上地方人民政府兵役机关会同有关部门查明事实，经同级地方人民政府作出处罚决定后，由县级以上地方人民政府兵役机关和有关部门按照职责分工具体执行。"},{"i":64,"n":"第六十四条","txt":"中国人民武装警察部队退出现役的人员服预备役的，适用本法。"},{"i":65,"n":"第六十五条","txt":"本法自2023年3月1日起施行。《中华人民共和国预备役军官法》同时废止。"}],"shipinanquanfa":[{"i":1,"n":"第一条","txt":"为了保证食品安全，保障公众身体健康和生命安全，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事下列活动，应当遵守本法："},{"i":3,"n":"第三条","txt":"食品安全工作实行预防为主、风险管理、全程控制、社会共治，建立科学、严格的监督管理制度。"},{"i":4,"n":"第四条","txt":"食品生产经营者对其生产经营食品的安全负责。"},{"i":5,"n":"第五条","txt":"国务院设立食品安全委员会，其职责由国务院规定。"},{"i":6,"n":"第六条","txt":"县级以上地方人民政府对本行政区域的食品安全监督管理工作负责，统一领导、组织、协调本行政区域的食品安全监督管理工作以及食品安全突发事件应对工作，建立健全食品安全全程监督管理工作机制和信息共享机制。"},{"i":7,"n":"第七条","txt":"县级以上地方人民政府实行食品安全监督管理责任制。上级人民政府负责对下一级人民政府的食品安全监督管理工作进行评议、考核。县级以上地方人民政府负责对本级食品安全监督管理部门和其他有关部门的食品安全监督管理工作进行评议、考核。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当将食品安全工作纳入本级国民经济和社会发展规划，将食品安全工作经费列入本级政府财政预算，加强食品安全监督管理能力建设，为食品安全工作提供保障。"},{"i":9,"n":"第九条","txt":"食品行业协会应当加强行业自律，按照章程建立健全行业规范和奖惩机制，提供食品安全信息、技术等服务，引导和督促食品生产经营者依法生产经营，推动行业诚信建设，宣传、普及食品安全知识。"},{"i":10,"n":"第十条","txt":"各级人民政府应当加强食品安全的宣传教育，普及食品安全知识，鼓励社会组织、基层群众性自治组织、食品生产经营者开展食品安全法律、法规以及食品安全标准和知识的普及工作，倡导健康的饮食方式，增强消费者食品安全意识和自我保护能力。"},{"i":11,"n":"第十一条","txt":"国家鼓励和支持开展与食品安全有关的基础研究、应用研究，鼓励和支持食品生产经营者为提高食品安全水平采用先进技术和先进管理规范。"},{"i":12,"n":"第十二条","txt":"任何组织或者个人有权举报食品安全违法行为，依法向有关部门了解食品安全信息，对食品安全监督管理工作提出意见和建议。"},{"i":13,"n":"第十三条","txt":"对在食品安全工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":14,"n":"第十四条","txt":"国家建立食品安全风险监测制度，对食源性疾病、食品污染以及食品中的有害因素进行监测。"},{"i":15,"n":"第十五条","txt":"承担食品安全风险监测工作的技术机构应当根据食品安全风险监测计划和监测方案开展监测工作，保证监测数据真实、准确，并按照食品安全风险监测计划和监测方案的要求报送监测数据和分析结果。"},{"i":16,"n":"第十六条","txt":"食品安全风险监测结果表明可能存在食品安全隐患的，县级以上人民政府卫生行政部门应当及时将相关信息通报同级食品安全监督管理等部门，并报告本级人民政府和上级人民政府卫生行政部门。食品安全监督管理等部门应当组织开展进一步调查。"},{"i":17,"n":"第十七条","txt":"国家建立食品安全风险评估制度，运用科学方法，根据食品安全风险监测信息、科学数据以及有关信息，对食品、食品添加剂、食品相关产品中生物性、化学性和物理性危害因素进行风险评估。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，应当进行食品安全风险评估："},{"i":19,"n":"第十九条","txt":"国务院食品安全监督管理、农业行政等部门在监督管理工作中发现需要进行食品安全风险评估的，应当向国务院卫生行政部门提出食品安全风险评估的建议，并提供风险来源、相关检验数据和结论等信息、资料。属于本法第十八条规定情形的，国务院卫生行政部门应当及时进行食品安全风险评估，并向国务院有关部门通报评估结果。"},{"i":20,"n":"第二十条","txt":"省级以上人民政府卫生行政、农业行政部门应当及时相互通报食品、食用农产品安全风险监测信息。"},{"i":21,"n":"第二十一条","txt":"食品安全风险评估结果是制定、修订食品安全标准和实施食品安全监督管理的科学依据。"},{"i":22,"n":"第二十二条","txt":"国务院食品安全监督管理部门应当会同国务院有关部门，根据食品安全风险评估结果、食品安全监督管理信息，对食品安全状况进行综合分析。对经综合分析表明可能具有较高程度安全风险的食品，国务院食品安全监督管理部门应当及时提出食品安全风险警示，并向社会公布。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府食品安全监督管理部门和其他有关部门、食品安全风险评估专家委员会及其技术机构，应当按照科学、客观、及时、公开的原则，组织食品生产经营者、食品检验机构、认证机构、食品行业协会、消费者协会以及新闻媒体等，就食品安全风险评估信息和食品安全监督管理信息进行交流沟通。"},{"i":24,"n":"第二十四条","txt":"制定食品安全标准，应当以保障公众身体健康为宗旨，做到科学合理、安全可靠。"},{"i":25,"n":"第二十五条","txt":"食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准。"},{"i":26,"n":"第二十六条","txt":"食品安全标准应当包括下列内容："},{"i":27,"n":"第二十七条","txt":"食品安全国家标准由国务院卫生行政部门会同国务院食品安全监督管理部门制定、公布，国务院标准化行政部门提供国家标准编号。"},{"i":28,"n":"第二十八条","txt":"制定食品安全国家标准，应当依据食品安全风险评估结果并充分考虑食用农产品安全风险评估结果，参照相关的国际标准和国际食品安全风险评估结果，并将食品安全国家标准草案向社会公布，广泛听取食品生产经营者、消费者、有关部门等方面的意见。"},{"i":29,"n":"第二十九条","txt":"对地方特色食品，没有食品安全国家标准的，省、自治区、直辖市人民政府卫生行政部门可以制定并公布食品安全地方标准，报国务院卫生行政部门备案。食品安全国家标准制定后，该地方标准即行废止。"},{"i":30,"n":"第三十条","txt":"国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。"},{"i":31,"n":"第三十一条","txt":"省级以上人民政府卫生行政部门应当在其网站上公布制定和备案的食品安全国家标准、地方标准和企业标准，供公众免费查阅、下载。"},{"i":32,"n":"第三十二条","txt":"省级以上人民政府卫生行政部门应当会同同级食品安全监督管理、农业行政等部门，分别对食品安全国家标准和地方标准的执行情况进行跟踪评价，并根据评价结果及时修订食品安全标准。"},{"i":33,"n":"第三十三条","txt":"食品生产经营应当符合食品安全标准，并符合下列要求："},{"i":34,"n":"第三十四条","txt":"禁止生产经营下列食品、食品添加剂、食品相关产品："},{"i":35,"n":"第三十五条","txt":"国家对食品生产经营实行许可制度。从事食品生产、食品销售、餐饮服务，应当依法取得许可。但是，销售食用农产品和仅销售预包装食品的，不需要取得许可。仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案。"},{"i":36,"n":"第三十六条","txt":"食品生产加工小作坊和食品摊贩等从事食品生产经营活动，应当符合本法规定的与其生产经营规模、条件相适应的食品安全要求，保证所生产经营的食品卫生、无毒、无害，食品安全监督管理部门应当对其加强监督管理。"},{"i":37,"n":"第三十七条","txt":"利用新的食品原料生产食品，或者生产食品添加剂新品种、食品相关产品新品种，应当向国务院卫生行政部门提交相关产品的安全性评估材料。国务院卫生行政部门应当自收到申请之日起六十日内组织审查；对符合食品安全要求的，准予许可并公布；对不符合食品安全要求的，不予许可并书面说明理由。"},{"i":38,"n":"第三十八条","txt":"生产经营的食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。按照传统既是食品又是中药材的物质目录由国务院卫生行政部门会同国务院食品安全监督管理部门制定、公布。"},{"i":39,"n":"第三十九条","txt":"国家对食品添加剂生产实行许可制度。从事食品添加剂生产，应当具有与所生产食品添加剂品种相适应的场所、生产设备或者设施、专业技术人员和管理制度，并依照本法第三十五条第二款规定的程序，取得食品添加剂生产许可。"},{"i":40,"n":"第四十条","txt":"食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠，方可列入允许使用的范围；有关食品安全国家标准应当根据技术必要性和食品安全风险评估结果及时修订。"},{"i":41,"n":"第四十一条","txt":"生产食品相关产品应当符合法律、法规和食品安全国家标准。对直接接触食品的包装材料等具有较高风险的食品相关产品，按照国家有关工业产品生产许可证管理的规定实施生产许可。食品安全监督管理部门应当加强对食品相关产品生产活动的监督管理。"},{"i":42,"n":"第四十二条","txt":"国家建立食品安全全程追溯制度。"},{"i":43,"n":"第四十三条","txt":"地方各级人民政府应当采取措施鼓励食品规模化生产和连锁经营、配送。"},{"i":44,"n":"第四十四条","txt":"食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训，加强食品检验工作，依法从事生产经营活动。"},{"i":45,"n":"第四十五条","txt":"食品生产经营者应当建立并执行从业人员健康管理制度。患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。"},{"i":46,"n":"第四十六条","txt":"食品生产企业应当就下列事项制定并实施控制要求，保证所生产的食品符合食品安全标准："},{"i":47,"n":"第四十七条","txt":"食品生产经营者应当建立食品安全自查制度，定期对食品安全状况进行检查评价。生产经营条件发生变化，不再符合食品安全要求的，食品生产经营者应当立即采取整改措施；有发生食品安全事故潜在风险的，应当立即停止食品生产经营活动，并向所在地县级人民政府食品安全监督管理部门报告。"},{"i":48,"n":"第四十八条","txt":"国家鼓励食品生产经营企业符合良好生产规范要求，实施危害分析与关键控制点体系，提高食品安全管理水平。"},{"i":49,"n":"第四十九条","txt":"食用农产品生产者应当按照食品安全标准和国家有关规定使用农药、肥料、兽药、饲料和饲料添加剂等农业投入品，严格执行农业投入品使用安全间隔期或者休药期的规定，不得使用国家明令禁止的农业投入品。禁止将剧毒、高毒农药用于蔬菜、瓜果、茶叶和中草药材等国家规定的农作物。"},{"i":50,"n":"第五十条","txt":"食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明；对无法提供合格证明的食品原料，应当按照食品安全标准进行检验；不得采购或者使用不符合食品安全标准的食品原料、食品添加剂、食品相关产品。"},{"i":51,"n":"第五十一条","txt":"食品生产企业应当建立食品出厂检验记录制度，查验出厂食品的检验合格证和安全状况，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、检验合格证号、销售日期以及购货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法第五十条第二款的规定。"},{"i":52,"n":"第五十二条","txt":"食品、食品添加剂、食品相关产品的生产者，应当按照食品安全标准对所生产的食品、食品添加剂、食品相关产品进行检验，检验合格后方可出厂或者销售。"},{"i":53,"n":"第五十三条","txt":"食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明（以下称合格证明文件）。"},{"i":54,"n":"第五十四条","txt":"食品经营者应当按照保证食品安全的要求贮存食品，定期检查库存食品，及时清理变质或者超过保质期的食品。"},{"i":55,"n":"第五十五条","txt":"餐饮服务提供者应当制定并实施原料控制要求，不得采购不符合食品安全标准的食品原料。倡导餐饮服务提供者公开加工过程，公示食品原料及其来源等信息。"},{"i":56,"n":"第五十六条","txt":"餐饮服务提供者应当定期维护食品加工、贮存、陈列等设施、设备；定期清洗、校验保温设施及冷藏、冷冻设施。"},{"i":57,"n":"第五十七条","txt":"学校、托幼机构、养老机构、建筑工地等集中用餐单位的食堂应当严格遵守法律、法规和食品安全标准；从供餐单位订餐的，应当从取得食品生产经营许可的企业订购，并按照要求对订购的食品进行查验。供餐单位应当严格遵守法律、法规和食品安全标准，当餐加工，确保食品安全。"},{"i":58,"n":"第五十八条","txt":"餐具、饮具集中消毒服务单位应当具备相应的作业场所、清洗消毒设备或者设施，用水和使用的洗涤剂、消毒剂应当符合相关食品安全国家标准和其他国家标准、卫生规范。"},{"i":59,"n":"第五十九条","txt":"食品添加剂生产者应当建立食品添加剂出厂检验记录制度，查验出厂产品的检验合格证和安全状况，如实记录食品添加剂的名称、规格、数量、生产日期或者生产批号、保质期、检验合格证号、销售日期以及购货者名称、地址、联系方式等相关内容，并保存相关凭证。记录和凭证保存期限应当符合本法第五十条第二款的规定。"},{"i":60,"n":"第六十条","txt":"食品添加剂经营者采购食品添加剂，应当依法查验供货者的许可证和产品合格证明文件，如实记录食品添加剂的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法第五十条第二款的规定。"},{"i":61,"n":"第六十一条","txt":"集中交易市场的开办者、柜台出租者和展销会举办者，应当依法审查入场食品经营者的许可证，明确其食品安全管理责任，定期对其经营环境和条件进行检查，发现其有违反本法规定行为的，应当及时制止并立即报告所在地县级人民政府食品安全监督管理部门。"},{"i":62,"n":"第六十二条","txt":"网络食品交易第三方平台提供者应当对入网食品经营者进行实名登记，明确其食品安全管理责任；依法应当取得许可证的，还应当审查其许可证。"},{"i":63,"n":"第六十三条","txt":"国家建立食品召回制度。食品生产者发现其生产的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止生产，召回已经上市销售的食品，通知相关生产经营者和消费者，并记录召回和通知情况。"},{"i":64,"n":"第六十四条","txt":"食用农产品批发市场应当配备检验设备和检验人员或者委托符合本法规定的食品检验机构，对进入该批发市场销售的食用农产品进行抽样检验；发现不符合食品安全标准的，应当要求销售者立即停止销售，并向食品安全监督管理部门报告。"},{"i":65,"n":"第六十五条","txt":"食用农产品销售者应当建立食用农产品进货查验记录制度，如实记录食用农产品的名称、数量、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限不得少于六个月。"},{"i":66,"n":"第六十六条","txt":"进入市场销售的食用农产品在包装、保鲜、贮存、运输中使用保鲜剂、防腐剂等食品添加剂和包装材料等食品相关产品，应当符合食品安全国家标准。"},{"i":67,"n":"第六十七条","txt":"预包装食品的包装上应当有标签。标签应当标明下列事项："},{"i":68,"n":"第六十八条","txt":"食品经营者销售散装食品，应当在散装食品的容器、外包装上标明食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容。"},{"i":69,"n":"第六十九条","txt":"生产经营转基因食品应当按照规定显著标示。"},{"i":70,"n":"第七十条","txt":"食品添加剂应当有标签、说明书和包装。标签、说明书应当载明本法第六十七条第一款第一项至第六项、第八项、第九项规定的事项，以及食品添加剂的使用范围、用量、使用方法，并在标签上载明“食品添加剂”字样。"},{"i":71,"n":"第七十一条","txt":"食品和食品添加剂的标签、说明书，不得含有虚假内容，不得涉及疾病预防、治疗功能。生产经营者对其提供的标签、说明书的内容负责。"},{"i":72,"n":"第七十二条","txt":"食品经营者应当按照食品标签标示的警示标志、警示说明或者注意事项的要求销售食品。"},{"i":73,"n":"第七十三条","txt":"食品广告的内容应当真实合法，不得含有虚假内容，不得涉及疾病预防、治疗功能。食品生产经营者对食品广告内容的真实性、合法性负责。"},{"i":74,"n":"第七十四条","txt":"国家对保健食品、特殊医学用途配方食品和婴幼儿配方食品等特殊食品实行严格监督管理。"},{"i":75,"n":"第七十五条","txt":"保健食品声称保健功能，应当具有科学依据，不得对人体产生急性、亚急性或者慢性危害。"},{"i":76,"n":"第七十六条","txt":"使用保健食品原料目录以外原料的保健食品和首次进口的保健食品应当经国务院食品安全监督管理部门注册。但是，首次进口的保健食品中属于补充维生素、矿物质等营养物质的，应当报国务院食品安全监督管理部门备案。其他保健食品应当报省、自治区、直辖市人民政府食品安全监督管理部门备案。"},{"i":77,"n":"第七十七条","txt":"依法应当注册的保健食品，注册时应当提交保健食品的研发报告、产品配方、生产工艺、安全性和保健功能评价、标签、说明书等材料及样品，并提供相关证明文件。国务院食品安全监督管理部门经组织技术审评，对符合安全和功能声称要求的，准予注册；对不符合要求的，不予注册并书面说明理由。对使用保健食品原料目录以外原料的保健食品作出准予注册决定的，应当及时将该原料纳入保健食品原料目录。"},{"i":78,"n":"第七十八条","txt":"保健食品的标签、说明书不得涉及疾病预防、治疗功能，内容应当真实，与注册或者备案的内容相一致，载明适宜人群、不适宜人群、功效成分或者标志性成分及其含量等，并声明“本品不能代替药物”。保健食品的功能和成分应当与标签、说明书相一致。"},{"i":79,"n":"第七十九条","txt":"保健食品广告除应当符合本法第七十三条第一款的规定外，还应当声明“本品不能代替药物”；其内容应当经生产企业所在地省、自治区、直辖市人民政府食品安全监督管理部门审查批准，取得保健食品广告批准文件。省、自治区、直辖市人民政府食品安全监督管理部门应当公布并及时更新已经批准的保健食品广告目录以及批准的广告内容。"},{"i":80,"n":"第八十条","txt":"特殊医学用途配方食品应当经国务院食品安全监督管理部门注册。注册时，应当提交产品配方、生产工艺、标签、说明书以及表明产品安全性、营养充足性和特殊医学用途临床效果的材料。"},{"i":81,"n":"第八十一条","txt":"婴幼儿配方食品生产企业应当实施从原料进厂到成品出厂的全过程质量控制，对出厂的婴幼儿配方食品实施逐批检验，保证食品安全。"},{"i":82,"n":"第八十二条","txt":"保健食品、特殊医学用途配方食品、婴幼儿配方乳粉、婴幼儿配方液态乳的注册人或者备案人应当对其提交材料的真实性负责。"},{"i":83,"n":"第八十三条","txt":"生产保健食品，特殊医学用途配方食品、婴幼儿配方食品和其他专供特定人群的主辅食品的企业，应当按照良好生产规范的要求建立与所生产食品相适应的生产质量管理体系，定期对该体系的运行情况进行自查，保证其有效运行，并向所在地县级人民政府食品安全监督管理部门提交自查报告。"},{"i":84,"n":"第八十四条","txt":"食品检验机构按照国家有关认证认可的规定取得资质认定后，方可从事食品检验活动。但是，法律另有规定的除外。"},{"i":85,"n":"第八十五条","txt":"食品检验由食品检验机构指定的检验人独立进行。"},{"i":86,"n":"第八十六条","txt":"食品检验实行食品检验机构与检验人负责制。食品检验报告应当加盖食品检验机构公章，并有检验人的签名或者盖章。食品检验机构和检验人对出具的食品检验报告负责。"},{"i":87,"n":"第八十七条","txt":"县级以上人民政府食品安全监督管理部门应当对食品进行定期或者不定期的抽样检验，并依据有关规定公布检验结果，不得免检。进行抽样检验，应当购买抽取的样品，委托符合本法规定的食品检验机构进行检验，并支付相关费用；不得向食品生产经营者收取检验费和其他费用。"},{"i":88,"n":"第八十八条","txt":"对依照本法规定实施的检验结论有异议的，食品生产经营者可以自收到检验结论之日起七个工作日内向实施抽样检验的食品安全监督管理部门或者其上一级食品安全监督管理部门提出复检申请，由受理复检申请的食品安全监督管理部门在公布的复检机构名录中随机确定复检机构进行复检。复检机构出具的复检结论为最终检验结论。复检机构与初检机构不得为同一机构。复检机构名录由国务院认证认可监督管理、食品安全监督管理、卫生行政、农业行政等部门共同公布。"},{"i":89,"n":"第八十九条","txt":"食品生产企业可以自行对所生产的食品进行检验，也可以委托符合本法规定的食品检验机构进行检验。"},{"i":90,"n":"第九十条","txt":"食品添加剂的检验，适用本法有关食品检验的规定。"},{"i":91,"n":"第九十一条","txt":"国家出入境检验检疫部门对进出口食品安全实施监督管理。"},{"i":92,"n":"第九十二条","txt":"进口的食品、食品添加剂、食品相关产品应当符合我国食品安全国家标准。"},{"i":93,"n":"第九十三条","txt":"进口尚无食品安全国家标准的食品，由境外出口商、境外生产企业或者其委托的进口商向国务院卫生行政部门提交所执行的相关国家（地区）标准或者国际标准。国务院卫生行政部门对相关标准进行审查，认为符合食品安全要求的，决定暂予适用，并及时制定相应的食品安全国家标准。进口利用新的食品原料生产的食品或者进口食品添加剂新品种、食品相关产品新品种，依照本法第三十七条的规定办理。"},{"i":94,"n":"第九十四条","txt":"境外出口商、境外生产企业应当保证向我国出口的食品、食品添加剂、食品相关产品符合本法以及我国其他有关法律、行政法规的规定和食品安全国家标准的要求，并对标签、说明书的内容负责。"},{"i":95,"n":"第九十五条","txt":"境外发生的食品安全事件可能对我国境内造成影响，或者在进口食品、食品添加剂、食品相关产品中发现严重食品安全问题的，国家出入境检验检疫部门应当及时采取风险预警或者控制措施，并向国务院食品安全监督管理、卫生行政、农业行政部门通报。接到通报的部门应当及时采取相应措施。"},{"i":96,"n":"第九十六条","txt":"向我国境内出口食品的境外出口商或者代理商、进口食品的进口商应当向国家出入境检验检疫部门备案。向我国境内出口食品的境外食品生产企业应当经国家出入境检验检疫部门注册。已经注册的境外食品生产企业提供虚假材料，或者因其自身的原因致使进口食品发生重大食品安全事故的，国家出入境检验检疫部门应当撤销注册并公告。"},{"i":97,"n":"第九十七条","txt":"进口的预包装食品、食品添加剂应当有中文标签；依法应当有说明书的，还应当有中文说明书。标签、说明书应当符合本法以及我国其他有关法律、行政法规的规定和食品安全国家标准的要求，并载明食品的原产地以及境内代理商的名称、地址、联系方式。预包装食品没有中文标签、中文说明书或者标签、说明书不符合本条规定的，不得进口。"},{"i":98,"n":"第九十八条","txt":"进口商应当建立食品、食品添加剂进口和销售记录制度，如实记录食品、食品添加剂的名称、规格、数量、生产日期、生产或者进口批号、保质期、境外出口商和购货者名称、地址及联系方式、交货日期等内容，并保存相关凭证。记录和凭证保存期限应当符合本法第五十条第二款的规定。"},{"i":99,"n":"第九十九条","txt":"出口食品生产企业应当保证其出口食品符合进口国（地区）的标准或者合同要求。"},{"i":100,"n":"第一百条","txt":"国家出入境检验检疫部门应当收集、汇总下列进出口食品安全信息，并及时通报相关部门、机构和企业："},{"i":101,"n":"第一百零一条","txt":"国家出入境检验检疫部门可以对向我国境内出口食品的国家（地区）的食品安全管理体系和食品安全状况进行评估和审查，并根据评估和审查结果，确定相应检验检疫要求。"},{"i":102,"n":"第一百零二条","txt":"国务院组织制定国家食品安全事故应急预案。"},{"i":103,"n":"第一百零三条","txt":"发生食品安全事故的单位应当立即采取措施，防止事故扩大。事故单位和接收病人进行治疗的单位应当及时向事故发生地县级人民政府食品安全监督管理、卫生行政部门报告。"},{"i":104,"n":"第一百零四条","txt":"医疗机构发现其接收的病人属于食源性疾病病人或者疑似病人的，应当按照规定及时将相关信息向所在地县级人民政府卫生行政部门报告。县级人民政府卫生行政部门认为与食品安全有关的，应当及时通报同级食品安全监督管理部门。"},{"i":105,"n":"第一百零五条","txt":"县级以上人民政府食品安全监督管理部门接到食品安全事故的报告后，应当立即会同同级卫生行政、农业行政等部门进行调查处理，并采取下列措施，防止或者减轻社会危害："},{"i":106,"n":"第一百零六条","txt":"发生食品安全事故，设区的市级以上人民政府食品安全监督管理部门应当立即会同有关部门进行事故责任调查，督促有关部门履行职责，向本级人民政府和上一级人民政府食品安全监督管理部门提出事故责任调查处理报告。"},{"i":107,"n":"第一百零七条","txt":"调查食品安全事故，应当坚持实事求是、尊重科学的原则，及时、准确查清事故性质和原因，认定事故责任，提出整改措施。"},{"i":108,"n":"第一百零八条","txt":"食品安全事故调查部门有权向有关单位和个人了解与事故有关的情况，并要求提供相关资料和样品。有关单位和个人应当予以配合，按照要求提供相关资料和样品，不得拒绝。"},{"i":109,"n":"第一百零九条","txt":"县级以上人民政府食品安全监督管理部门根据食品安全风险监测、风险评估结果和食品安全状况等，确定监督管理的重点、方式和频次，实施风险分级管理。"},{"i":110,"n":"第一百一十条","txt":"县级以上人民政府食品安全监督管理部门履行食品安全监督管理职责，有权采取下列措施，对生产经营者遵守本法的情况进行监督检查："},{"i":111,"n":"第一百一十一条","txt":"对食品安全风险评估结果证明食品存在安全隐患，需要制定、修订食品安全标准的，在制定、修订食品安全标准前，国务院卫生行政部门应当及时会同国务院有关部门规定食品中有害物质的临时限量值和临时检验方法，作为生产经营和监督管理的依据。"},{"i":112,"n":"第一百一十二条","txt":"县级以上人民政府食品安全监督管理部门在食品安全监督管理工作中可以采用国家规定的快速检测方法对食品进行抽查检测。"},{"i":113,"n":"第一百一十三条","txt":"县级以上人民政府食品安全监督管理部门应当建立食品生产经营者食品安全信用档案，记录许可颁发、日常监督检查结果、违法行为查处等情况，依法向社会公布并实时更新；对有不良信用记录的食品生产经营者增加监督检查频次，对违法行为情节严重的食品生产经营者，可以通报投资主管部门、证券监督管理机构和有关的金融机构。"},{"i":114,"n":"第一百一十四条","txt":"食品生产经营过程中存在食品安全隐患，未及时采取措施消除的，县级以上人民政府食品安全监督管理部门可以对食品生产经营者的法定代表人或者主要负责人进行责任约谈。食品生产经营者应当立即采取措施，进行整改，消除隐患。责任约谈情况和整改情况应当纳入食品生产经营者食品安全信用档案。"},{"i":115,"n":"第一百一十五条","txt":"县级以上人民政府食品安全监督管理等部门应当公布本部门的电子邮件地址或者电话，接受咨询、投诉、举报。接到咨询、投诉、举报，对属于本部门职责的，应当受理并在法定期限内及时答复、核实、处理；对不属于本部门职责的，应当移交有权处理的部门并书面通知咨询、投诉、举报人。有权处理的部门应当在法定期限内及时处理，不得推诿。对查证属实的举报，给予举报人奖励。"},{"i":116,"n":"第一百一十六条","txt":"县级以上人民政府食品安全监督管理等部门应当加强对执法人员食品安全法律、法规、标准和专业知识与执法能力等的培训，并组织考核。不具备相应知识和能力的，不得从事食品安全执法工作。"},{"i":117,"n":"第一百一十七条","txt":"县级以上人民政府食品安全监督管理等部门未及时发现食品安全系统性风险，未及时消除监督管理区域内的食品安全隐患的，本级人民政府可以对其主要负责人进行责任约谈。"},{"i":118,"n":"第一百一十八条","txt":"国家建立统一的食品安全信息平台，实行食品安全信息统一公布制度。国家食品安全总体情况、食品安全风险警示信息、重大食品安全事故及其调查处理信息和国务院确定需要统一公布的其他信息由国务院食品安全监督管理部门统一公布。食品安全风险警示信息和重大食品安全事故及其调查处理信息的影响限于特定区域的，也可以由有关省、自治区、直辖市人民政府食品安全监督管理部门公布。未经授权不得发布上述信息。"},{"i":119,"n":"第一百一十九条","txt":"县级以上地方人民政府食品安全监督管理、卫生行政、农业行政部门获知本法规定需要统一公布的信息，应当向上级主管部门报告，由上级主管部门立即报告国务院食品安全监督管理部门；必要时，可以直接向国务院食品安全监督管理部门报告。"},{"i":120,"n":"第一百二十条","txt":"任何单位和个人不得编造、散布虚假食品安全信息。"},{"i":121,"n":"第一百二十一条","txt":"县级以上人民政府食品安全监督管理等部门发现涉嫌食品安全犯罪的，应当按照有关规定及时将案件移送公安机关。对移送的案件，公安机关应当及时审查；认为有犯罪事实需要追究刑事责任的，应当立案侦查。"},{"i":122,"n":"第一百二十二条","txt":"违反本法规定，未取得食品生产经营许可从事食品生产经营活动，或者未取得食品添加剂生产许可从事食品添加剂生产活动的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂以及用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五万元以上十万元以下罚款；货值金额一万元以上的，并处货值金额十倍以上二十倍以下罚款。"},{"i":123,"n":"第一百二十三条","txt":"违反本法规定，有下列情形之一，尚不构成犯罪的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品货值金额不足一万元的，并处十万元以上十五万元以下罚款；货值金额一万元以上的，并处货值金额十五倍以上三十倍以下罚款；情节严重的，吊销许可证，并可以由公安机关对其直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留："},{"i":124,"n":"第一百二十四条","txt":"违反本法规定，有下列情形之一，尚不构成犯罪的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五万元以上十万元以下罚款；货值金额一万元以上的，并处货值金额十倍以上二十倍以下罚款；情节严重的，吊销许可证："},{"i":125,"n":"第一百二十五条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五千元以上五万元以下罚款；货值金额一万元以上的，并处货值金额五倍以上十倍以下罚款；情节严重的，责令停产停业，直至吊销许可证："},{"i":126,"n":"第一百二十六条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处五千元以上五万元以下罚款；情节严重的，责令停产停业，直至吊销许可证："},{"i":127,"n":"第一百二十七条","txt":"对食品生产加工小作坊、食品摊贩等的违法行为的处罚，依照省、自治区、直辖市制定的具体管理办法执行。"},{"i":128,"n":"第一百二十八条","txt":"违反本法规定，事故单位在发生食品安全事故后未进行处置、报告的，由有关主管部门按照各自职责分工责令改正，给予警告；隐匿、伪造、毁灭有关证据的，责令停产停业，没收违法所得，并处十万元以上五十万元以下罚款；造成严重后果的，吊销许可证。"},{"i":129,"n":"第一百二十九条","txt":"违反本法规定，有下列情形之一的，由出入境检验检疫机构依照本法第一百二十四条的规定给予处罚："},{"i":130,"n":"第一百三十条","txt":"违反本法规定，集中交易市场的开办者、柜台出租者、展销会的举办者允许未依法取得许可的食品经营者进入市场销售食品，或者未履行检查、报告等义务的，由县级以上人民政府食品安全监督管理部门责令改正，没收违法所得，并处五万元以上二十万元以下罚款；造成严重后果的，责令停业，直至由原发证部门吊销许可证；使消费者的合法权益受到损害的，应当与食品经营者承担连带责任。"},{"i":131,"n":"第一百三十一条","txt":"违反本法规定，网络食品交易第三方平台提供者未对入网食品经营者进行实名登记、审查许可证，或者未履行报告、停止提供网络交易平台服务等义务的，由县级以上人民政府食品安全监督管理部门责令改正，没收违法所得，并处五万元以上二十万元以下罚款；造成严重后果的，责令停业，直至由原发证部门吊销许可证；使消费者的合法权益受到损害的，应当与食品经营者承担连带责任。"},{"i":132,"n":"第一百三十二条","txt":"违反本法规定，未按要求进行食品贮存、运输和装卸的，由县级以上人民政府食品安全监督管理等部门按照各自职责分工责令改正，给予警告；拒不改正的，责令停产停业，并处一万元以上五万元以下罚款；情节严重的，吊销许可证。"},{"i":133,"n":"第一百三十三条","txt":"违反本法规定，拒绝、阻挠、干涉有关部门、机构及其工作人员依法开展食品安全监督检查、事故调查处理、风险监测和风险评估的，由有关主管部门按照各自职责分工责令停产停业，并处二千元以上五万元以下罚款；情节严重的，吊销许可证；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":134,"n":"第一百三十四条","txt":"食品生产经营者在一年内累计三次因违反本法规定受到责令停产停业、吊销许可证以外处罚的，由食品安全监督管理部门责令停产停业，直至吊销许可证。"},{"i":135,"n":"第一百三十五条","txt":"被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起五年内不得申请食品生产经营许可，或者从事食品生产经营管理工作、担任食品生产经营企业食品安全管理人员。"},{"i":136,"n":"第一百三十六条","txt":"食品经营者履行了本法规定的进货查验等义务，有充分证据证明其不知道所采购的食品不符合食品安全标准，并能如实说明其进货来源的，可以免予处罚，但应当依法没收其不符合食品安全标准的食品；造成人身、财产或者其他损害的，依法承担赔偿责任。"},{"i":137,"n":"第一百三十七条","txt":"违反本法规定，承担食品安全风险监测、风险评估工作的技术机构、技术人员提供虚假监测、评估信息的，依法对技术机构直接负责的主管人员和技术人员给予撤职、开除处分；有执业资格的，由授予其资格的主管部门吊销执业证书。"},{"i":138,"n":"第一百三十八条","txt":"违反本法规定，食品检验机构、食品检验人员出具虚假检验报告的，由授予其资质的主管部门或者机构撤销该食品检验机构的检验资质，没收所收取的检验费用，并处检验费用五倍以上十倍以下罚款，检验费用不足一万元的，并处五万元以上十万元以下罚款；依法对食品检验机构直接负责的主管人员和食品检验人员给予撤职或者开除处分；导致发生重大食品安全事故的，对直接负责的主管人员和食品检验人员给予开除处分。"},{"i":139,"n":"第一百三十九条","txt":"违反本法规定，认证机构出具虚假认证结论，由认证认可监督管理部门没收所收取的认证费用，并处认证费用五倍以上十倍以下罚款，认证费用不足一万元的，并处五万元以上十万元以下罚款；情节严重的，责令停业，直至撤销认证机构批准文件，并向社会公布；对直接负责的主管人员和负有直接责任的认证人员，撤销其执业资格。"},{"i":140,"n":"第一百四十条","txt":"违反本法规定，在广告中对食品作虚假宣传，欺骗消费者，或者发布未取得批准文件、广告内容与批准文件不一致的保健食品广告的，依照《中华人民共和国广告法》的规定给予处罚。"},{"i":141,"n":"第一百四十一条","txt":"违反本法规定，编造、散布虚假食品安全信息，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。"},{"i":142,"n":"第一百四十二条","txt":"违反本法规定，县级以上地方人民政府有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分；造成严重后果的，其主要负责人还应当引咎辞职："},{"i":143,"n":"第一百四十三条","txt":"违反本法规定，县级以上地方人民政府有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予警告、记过或者记大过处分；造成严重后果的，给予降级或者撤职处分："},{"i":144,"n":"第一百四十四条","txt":"违反本法规定，县级以上人民政府食品安全监督管理、卫生行政、农业行政等部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分；造成严重后果的，其主要负责人还应当引咎辞职："},{"i":145,"n":"第一百四十五条","txt":"违反本法规定，县级以上人民政府食品安全监督管理、卫生行政、农业行政等部门有下列行为之一，造成不良后果的，对直接负责的主管人员和其他直接责任人员给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分："},{"i":146,"n":"第一百四十六条","txt":"食品安全监督管理等部门在履行食品安全监督管理职责过程中，违法实施检查、强制等执法措施，给生产经营者造成损失的，应当依法予以赔偿，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":147,"n":"第一百四十七条","txt":"违反本法规定，造成人身、财产或者其他损害的，依法承担赔偿责任。生产经营者财产不足以同时承担民事赔偿责任和缴纳罚款、罚金时，先承担民事赔偿责任。"},{"i":148,"n":"第一百四十八条","txt":"消费者因不符合食品安全标准的食品受到损害的，可以向经营者要求赔偿损失，也可以向生产者要求赔偿损失。接到消费者赔偿要求的生产经营者，应当实行首负责任制，先行赔付，不得推诿；属于生产者责任的，经营者赔偿后有权向生产者追偿；属于经营者责任的，生产者赔偿后有权向经营者追偿。"},{"i":149,"n":"第一百四十九条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":150,"n":"第一百五十条","txt":"本法下列用语的含义："},{"i":151,"n":"第一百五十一条","txt":"转基因食品和食盐的食品安全管理，本法未作规定的，适用其他法律、行政法规的规定。"},{"i":152,"n":"第一百五十二条","txt":"铁路、民航运营中食品安全的管理办法由国务院食品安全监督管理部门会同国务院有关部门依照本法制定。"},{"i":153,"n":"第一百五十三条","txt":"国务院根据实际需要，可以对食品安全监督管理体制作出调整。"},{"i":154,"n":"第一百五十四条","txt":"本法自2015年10月1日起施行。"}],"zhuwaiwaijiaorenyuanfa":[{"i":1,"n":"第一条","txt":"为了建设高素质的驻外外交人员队伍，保证驻外外交机构依法履行职责，规范驻外外交人员的管理，保障驻外外交人员的合法权益，根据宪法和公务员法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称驻外外交人员，是指在中华人民共和国驻外外交机构中从事外交、领事等工作，使用驻外行政编制，具有外交衔级的人员。"},{"i":3,"n":"第三条","txt":"驻外外交人员依法履行职责，受法律保护。"},{"i":4,"n":"第四条","txt":"外交部统一领导驻外外交机构的工作，会同其他派出部门对驻外外交人员实施管理。"},{"i":5,"n":"第五条","txt":"驻外外交人员应当根据职务和工作分工，履行下列职责："},{"i":6,"n":"第六条","txt":"驻外外交人员应当具备下列条件："},{"i":7,"n":"第七条","txt":"有下列情形之一的，不得任用为驻外外交人员："},{"i":8,"n":"第八条","txt":"驻外外交人员应当履行下列义务："},{"i":9,"n":"第九条","txt":"驻外外交人员享有下列权利："},{"i":10,"n":"第十条","txt":"驻外外交人员依照中华人民共和国缔结或者参加的国际条约，在驻外工作期间享有相应的特权和豁免。"},{"i":11,"n":"第十一条","txt":"驻外外交人员的职务分为外交职务和领事职务。"},{"i":12,"n":"第十二条","txt":"驻外外交人员实行外交衔级制度。"},{"i":13,"n":"第十三条","txt":"外交职务与外交衔级的基本对应关系为："},{"i":14,"n":"第十四条","txt":"领事职务与外交衔级的基本对应关系为："},{"i":15,"n":"第十五条","txt":"驻外外交人员的职务和外交衔级与公务员职务级别的对应关系另行规定。"},{"i":16,"n":"第十六条","txt":"驻外外交人员的职务按照下列权限决定："},{"i":17,"n":"第十七条","txt":"外交衔级按照下列权限批准和授予："},{"i":18,"n":"第十八条","txt":"驻外外交人员晋升三等秘书、副领事以及相应的衔级，按照规定的晋升条件、期限，分别依照本法第十六条、第十七条规定的权限逐级晋升；经考核不具备晋升条件的，根据驻外外交机构的意见，经派出部门批准，延期晋升。"},{"i":19,"n":"第十九条","txt":"驻外外交人员在受处分期间，其职务和衔级不予晋升。"},{"i":20,"n":"第二十条","txt":"驻外外交人员受到降级、撤职处分的，应当按照规定降低衔级。降低衔级不适用于随员衔。"},{"i":21,"n":"第二十一条","txt":"馆长是驻外外交机构的行政首长。特命全权大使为大使馆的馆长。代表为常驻联合国等政府间国际组织的代表机构的馆长。总领事为总领事馆的馆长。领事为领事馆的馆长。"},{"i":22,"n":"第二十二条","txt":"馆长缺位或者因故不能执行职务时，由被指定的人员代理馆长行使职责。"},{"i":23,"n":"第二十三条","txt":"馆长应当向派出部门提交到任和离任的书面报告。"},{"i":24,"n":"第二十四条","txt":"特命全权大使和代表、副代表为特命全权大使的，由中华人民共和国主席根据全国人民代表大会常务委员会的决定派遣和召回。"},{"i":25,"n":"第二十五条","txt":"驻外外交人员实行任期制度。根据工作需要，经派出部门批准，驻外外交人员的任职期限可以适当缩短或者延长。"},{"i":26,"n":"第二十六条","txt":"驻外外交人员有下列情形之一的，应当提前调回："},{"i":27,"n":"第二十七条","txt":"国家可以根据需要紧急召回、调回或者撤出相关驻外外交机构的部分人员或者全部人员。"},{"i":28,"n":"第二十八条","txt":"对驻外外交人员的考核分为平时考核和定期考核，由驻外外交机构或者派出部门按照国家规定组织实施。"},{"i":29,"n":"第二十九条","txt":"派遣前和驻外工作期间，根据工作职责的要求，应当对驻外外交人员进行任职和专业培训。"},{"i":30,"n":"第三十条","txt":"驻外外交人员应当在驻外外交机构之间进行任职交流；根据工作需要，也可以在派出部门或者其他机关之间进行任职交流。"},{"i":31,"n":"第三十一条","txt":"驻外外交人员的培训情况和任职交流经历，列入考核内容。"},{"i":32,"n":"第三十二条","txt":"驻外外交机构或者驻外外交人员有下列情形之一的，依法给予奖励："},{"i":33,"n":"第三十三条","txt":"驻外外交人员有下列行为之一的，依法给予相应的处分；构成犯罪的，依法追究刑事责任："},{"i":34,"n":"第三十四条","txt":"外交部或者其他派出部门依照法定的权限和程序对驻外外交机构进行奖励，对驻外外交人员给予奖励或者惩戒。"},{"i":35,"n":"第三十五条","txt":"驻外外交人员实行职务、衔级与级别相结合的驻外工资制度。"},{"i":36,"n":"第三十六条","txt":"国家建立驻外外交人员工资调整机制，适时调整驻外外交人员的工资和生活待遇。"},{"i":37,"n":"第三十七条","txt":"驻外外交人员按照国家规定享受津贴、补贴。"},{"i":38,"n":"第三十八条","txt":"国家为驻外外交人员提供必要的医疗保障和安全措施，并按照有关规定提供必要的人身意外伤害保险。"},{"i":39,"n":"第三十九条","txt":"驻外外交人员享受国家规定的带薪年休假和任期假。"},{"i":40,"n":"第四十条","txt":"驻外外交人员办理结婚手续前，应当按照规定如实向派出部门报告结婚对象的身份等情况。"},{"i":41,"n":"第四十一条","txt":"驻外外交人员的配偶随任，应当经派出部门批准。"},{"i":42,"n":"第四十二条","txt":"驻外外交人员配偶随任期间，根据驻外外交人员的职务和衔级、任职年限和驻在国生活条件，享受规定的休假待遇。"},{"i":43,"n":"第四十三条","txt":"驻外外交人员配偶为国家机关、事业单位在编人员，国有独资企业、国有独资公司、国有资本控股公司人员或者现役军人的，随任期间和结束随任回国后在原单位的工作安排，按照国家规定办理；原单位不得因其随任将其开除、辞退或者收取补偿金、管理费等费用。"},{"i":44,"n":"第四十四条","txt":"驻外外交人员配偶未随任的，经派出部门批准，可以赴驻外外交机构探亲，按照规定享受相应的探亲假、旅费和补贴。"},{"i":45,"n":"第四十五条","txt":"驻外外交人员的未成年子女，经派出部门批准，可以赴驻外外交机构随居或者探亲。"},{"i":46,"n":"第四十六条","txt":"随任、随居和探亲的驻外外交人员配偶、子女，应当遵守驻外外交机构规章制度，尊重驻在国的法律和风俗习惯。"},{"i":47,"n":"第四十七条","txt":"驻外外交机构武官参照本法管理，具体办法由中央军事委员会制定。"},{"i":48,"n":"第四十八条","txt":"本法自2010年1月1日起施行。"}],"gaodengjiaoyufa":[{"i":1,"n":"第一条","txt":"为了发展高等教育事业，实施科教兴国战略，促进社会主义物质文明和精神文明建设，根据宪法和教育法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事高等教育活动，适用本法。"},{"i":3,"n":"第三条","txt":"国家坚持以马克思列宁主义、毛泽东思想、邓小平理论为指导，遵循宪法确定的基本原则，发展社会主义的高等教育事业。"},{"i":4,"n":"第四条","txt":"高等教育必须贯彻国家的教育方针，为社会主义现代化建设服务、为人民服务，与生产劳动和社会实践相结合，使受教育者成为德、智、体、美等方面全面发展的社会主义建设者和接班人。"},{"i":5,"n":"第五条","txt":"高等教育的任务是培养具有社会责任感、创新精神和实践能力的高级专门人才，发展科学技术文化，促进社会主义现代化建设。"},{"i":6,"n":"第六条","txt":"国家根据经济建设和社会发展的需要，制定高等教育发展规划，举办高等学校，并采取多种形式积极发展高等教育事业。"},{"i":7,"n":"第七条","txt":"国家按照社会主义现代化建设和发展社会主义市场经济的需要，根据不同类型、不同层次高等学校的实际，推进高等教育体制改革和高等教育教学改革，优化高等教育结构和资源配置，提高高等教育的质量和效益。"},{"i":8,"n":"第八条","txt":"国家根据少数民族的特点和需要，帮助和支持少数民族地区发展高等教育事业，为少数民族培养高级专门人才。"},{"i":9,"n":"第九条","txt":"公民依法享有接受高等教育的权利。"},{"i":10,"n":"第十条","txt":"国家依法保障高等学校中的科学研究、文学艺术创作和其他文化活动的自由。"},{"i":11,"n":"第十一条","txt":"高等学校应当面向社会，依法自主办学，实行民主管理。"},{"i":12,"n":"第十二条","txt":"国家鼓励高等学校之间、高等学校与科学研究机构以及企业事业组织之间开展协作，实行优势互补，提高教育资源的使用效益。"},{"i":13,"n":"第十三条","txt":"国务院统一领导和管理全国高等教育事业。"},{"i":14,"n":"第十四条","txt":"国务院教育行政部门主管全国高等教育工作，管理由国务院确定的主要为全国培养人才的高等学校。国务院其他有关部门在国务院规定的职责范围内，负责有关的高等教育工作。"},{"i":15,"n":"第十五条","txt":"高等教育包括学历教育和非学历教育。"},{"i":16,"n":"第十六条","txt":"高等学历教育分为专科教育、本科教育和研究生教育。"},{"i":17,"n":"第十七条","txt":"专科教育的基本修业年限为二至三年，本科教育的基本修业年限为四至五年，硕士研究生教育的基本修业年限为二至三年，博士研究生教育的基本修业年限为三至四年。非全日制高等学历教育的修业年限应当适当延长。高等学校根据实际需要，可以对本学校的修业年限作出调整。"},{"i":18,"n":"第十八条","txt":"高等教育由高等学校和其他高等教育机构实施。"},{"i":19,"n":"第十九条","txt":"高级中等教育毕业或者具有同等学力的，经考试合格，由实施相应学历教育的高等学校录取，取得专科生或者本科生入学资格。"},{"i":20,"n":"第二十条","txt":"接受高等学历教育的学生，由所在高等学校或者经批准承担研究生教育任务的科学研究机构根据其修业年限、学业成绩等，按照国家有关规定，发给相应的学历证书或者其他学业证书。"},{"i":21,"n":"第二十一条","txt":"国家实行高等教育自学考试制度，经考试合格的，发给相应的学历证书或者其他学业证书。"},{"i":22,"n":"第二十二条","txt":"国家实行学位制度。学位分为学士、硕士和博士。"},{"i":23,"n":"第二十三条","txt":"高等学校和其他高等教育机构应当根据社会需要和自身办学条件，承担实施继续教育的工作。"},{"i":24,"n":"第二十四条","txt":"设立高等学校，应当符合国家高等教育发展规划，符合国家利益和社会公共利益。"},{"i":25,"n":"第二十五条","txt":"设立高等学校，应当具备教育法规定的基本条件。"},{"i":26,"n":"第二十六条","txt":"设立高等学校，应当根据其层次、类型、所设学科类别、规模、教学和科学研究水平，使用相应的名称。"},{"i":27,"n":"第二十七条","txt":"申请设立高等学校的，应当向审批机关提交下列材料："},{"i":28,"n":"第二十八条","txt":"高等学校的章程应当规定以下事项："},{"i":29,"n":"第二十九条","txt":"设立实施本科及以上教育的高等学校，由国务院教育行政部门审批；设立实施专科教育的高等学校，由省、自治区、直辖市人民政府审批，报国务院教育行政部门备案；设立其他高等教育机构，由省、自治区、直辖市人民政府教育行政部门审批。审批设立高等学校和其他高等教育机构应当遵守国家有关规定。"},{"i":30,"n":"第三十条","txt":"高等学校自批准设立之日起取得法人资格。高等学校的校长为高等学校的法定代表人。"},{"i":31,"n":"第三十一条","txt":"高等学校应当以培养人才为中心，开展教学、科学研究和社会服务，保证教育教学质量达到国家规定的标准。"},{"i":32,"n":"第三十二条","txt":"高等学校根据社会需求、办学条件和国家核定的办学规模，制定招生方案，自主调节系科招生比例。"},{"i":33,"n":"第三十三条","txt":"高等学校依法自主设置和调整学科、专业。"},{"i":34,"n":"第三十四条","txt":"高等学校根据教学需要，自主制定教学计划、选编教材、组织实施教学活动。"},{"i":35,"n":"第三十五条","txt":"高等学校根据自身条件，自主开展科学研究、技术开发和社会服务。"},{"i":36,"n":"第三十六条","txt":"高等学校按照国家有关规定，自主开展与境外高等学校之间的科学技术文化交流与合作。"},{"i":37,"n":"第三十七条","txt":"高等学校根据实际需要和精简、效能的原则，自主确定教学、科学研究、行政职能部门等内部组织机构的设置和人员配备；按照国家有关规定，评聘教师和其他专业技术人员的职务，调整津贴及工资分配。"},{"i":38,"n":"第三十八条","txt":"高等学校对举办者提供的财产、国家财政性资助、受捐赠财产依法自主管理和使用。"},{"i":39,"n":"第三十九条","txt":"国家举办的高等学校实行中国共产党高等学校基层委员会领导下的校长负责制。中国共产党高等学校基层委员会按照中国共产党章程和有关规定，统一领导学校工作，支持校长独立负责地行使职权，其领导职责主要是：执行中国共产党的路线、方针、政策，坚持社会主义办学方向，领导学校的思想政治工作和德育工作，讨论决定学校内部组织机构的设置和内部组织机构负责人的人选，讨论决定学校的改革、发展和基本管理制度等重大事项，保证以培养人才为中心的各项任务的完成。"},{"i":40,"n":"第四十条","txt":"高等学校的校长，由符合教育法规定的任职条件的公民担任。高等学校的校长、副校长按照国家有关规定任免。"},{"i":41,"n":"第四十一条","txt":"高等学校的校长全面负责本学校的教学、科学研究和其他行政管理工作，行使下列职权："},{"i":42,"n":"第四十二条","txt":"高等学校设立学术委员会，履行下列职责："},{"i":43,"n":"第四十三条","txt":"高等学校通过以教师为主体的教职工代表大会等组织形式，依法保障教职工参与民主管理和监督，维护教职工合法权益。"},{"i":44,"n":"第四十四条","txt":"高等学校应当建立本学校办学水平、教育质量的评价制度，及时公开相关信息，接受社会监督。"},{"i":45,"n":"第四十五条","txt":"高等学校的教师及其他教育工作者享有法律规定的权利，履行法律规定的义务，忠诚于人民的教育事业。"},{"i":46,"n":"第四十六条","txt":"高等学校实行教师资格制度。中国公民凡遵守宪法和法律，热爱教育事业，具有良好的思想品德，具备研究生或者大学本科毕业学历，有相应的教育教学能力，经认定合格，可以取得高等学校教师资格。不具备研究生或者大学本科毕业学历的公民，学有所长，通过国家教师资格考试，经认定合格，也可以取得高等学校教师资格。"},{"i":47,"n":"第四十七条","txt":"高等学校实行教师职务制度。高等学校教师职务根据学校所承担的教学、科学研究等任务的需要设置。教师职务设助教、讲师、副教授、教授。"},{"i":48,"n":"第四十八条","txt":"高等学校实行教师聘任制。教师经评定具备任职条件的，由高等学校按照教师职务的职责、条件和任期聘任。"},{"i":49,"n":"第四十九条","txt":"高等学校的管理人员，实行教育职员制度。高等学校的教学辅助人员及其他专业技术人员，实行专业技术职务聘任制度。"},{"i":50,"n":"第五十条","txt":"国家保护高等学校教师及其他教育工作者的合法权益，采取措施改善高等学校教师及其他教育工作者的工作条件和生活条件。"},{"i":51,"n":"第五十一条","txt":"高等学校应当为教师参加培训、开展科学研究和进行学术交流提供便利条件。"},{"i":52,"n":"第五十二条","txt":"高等学校的教师、管理人员和教学辅助人员及其他专业技术人员，应当以教学和培养人才为中心做好本职工作。"},{"i":53,"n":"第五十三条","txt":"高等学校的学生应当遵守法律、法规，遵守学生行为规范和学校的各项管理制度，尊敬师长，刻苦学习，增强体质，树立爱国主义、集体主义和社会主义思想，努力学习马克思列宁主义、毛泽东思想、邓小平理论，具有良好的思想品德，掌握较高的科学文化知识和专业技能。"},{"i":54,"n":"第五十四条","txt":"高等学校的学生应当按照国家规定缴纳学费。"},{"i":55,"n":"第五十五条","txt":"国家设立奖学金，并鼓励高等学校、企业事业组织、社会团体以及其他社会组织和个人按照国家有关规定设立各种形式的奖学金，对品学兼优的学生、国家规定的专业的学生以及到国家规定的地区工作的学生给予奖励。"},{"i":56,"n":"第五十六条","txt":"高等学校的学生在课余时间可以参加社会服务和勤工助学活动，但不得影响学业任务的完成。"},{"i":57,"n":"第五十七条","txt":"高等学校的学生，可以在校内组织学生团体。学生团体在法律、法规规定的范围内活动，服从学校的领导和管理。"},{"i":58,"n":"第五十八条","txt":"高等学校的学生思想品德合格，在规定的修业年限内学完规定的课程，成绩合格或者修满相应的学分，准予毕业。"},{"i":59,"n":"第五十九条","txt":"高等学校应当为毕业生、结业生提供就业指导和服务。"},{"i":60,"n":"第六十条","txt":"高等教育实行以举办者投入为主、受教育者合理分担培养成本、高等学校多种渠道筹措经费的机制。"},{"i":61,"n":"第六十一条","txt":"高等学校的举办者应当保证稳定的办学经费来源，不得抽回其投入的办学资金。"},{"i":62,"n":"第六十二条","txt":"国务院教育行政部门会同国务院其他有关部门根据在校学生年人均教育成本，规定高等学校年经费开支标准和筹措的基本原则；省、自治区、直辖市人民政府教育行政部门会同有关部门制订本行政区域内高等学校年经费开支标准和筹措办法，作为举办者和高等学校筹措办学经费的基本依据。"},{"i":63,"n":"第六十三条","txt":"国家对高等学校进口图书资料、教学科研设备以及校办产业实行优惠政策。高等学校所办产业或者转让知识产权以及其他科学技术成果获得的收益，用于高等学校办学。"},{"i":64,"n":"第六十四条","txt":"高等学校收取的学费应当按照国家有关规定管理和使用，其他任何组织和个人不得挪用。"},{"i":65,"n":"第六十五条","txt":"高等学校应当依法建立、健全财务管理制度，合理使用、严格管理教育经费，提高教育投资效益。"},{"i":66,"n":"第六十六条","txt":"对高等教育活动中违反教育法规定的，依照教育法的有关规定给予处罚。"},{"i":67,"n":"第六十七条","txt":"中国境外个人符合国家规定的条件并办理有关手续后，可以进入中国境内高等学校学习、研究、进行学术交流或者任教，其合法权益受国家保护。"},{"i":68,"n":"第六十八条","txt":"本法所称高等学校是指大学、独立设置的学院和高等专科学校，其中包括高等职业学校和成人高等学校。"},{"i":69,"n":"第六十九条","txt":"本法自1999年1月1日起施行。"}],"zhongguorenminjiefangjunjunguanjunxiantiaoli":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国宪法》和《中华人民共和国兵役法》的有关规定，制定本条例。"},{"i":2,"n":"第二条","txt":"为加强中国人民解放军的革命化、现代化、正规化建设，有利于军队的指挥和管理，增强军官的责任心和荣誉感，实行军官军衔制度。"},{"i":3,"n":"第三条","txt":"军官军衔是区分军官等级、表明军官身份的称号、标志和国家给予军官的荣誉。"},{"i":4,"n":"第四条","txt":"军官军衔按照军官的服役性质分为现役军官军衔和预备役军官军衔。"},{"i":5,"n":"第五条","txt":"军衔高的军官对军衔低的军官，军衔高的为上级。当军衔高的军官在职务上隶属于军衔低的军官时，职务高的为上级。"},{"i":6,"n":"第六条","txt":"现役军官转入预备役的，在其军衔前冠以“预备役”。现役军官退役的，其军衔予以保留，在其军衔前冠以“退役”。"},{"i":7,"n":"第七条","txt":"军官军衔设下列三等十级："},{"i":8,"n":"第八条","txt":"军官军衔依照下列规定区分："},{"i":9,"n":"第九条","txt":"人民解放军实行军官职务等级编制军衔。"},{"i":10,"n":"第十条","txt":"中华人民共和国中央军事委员会领导全国武装力量。中央军事委员会实行主席负责制。中央军事委员会主席不授予军衔。"},{"i":11,"n":"第十一条","txt":"军事、政治、后勤军官实行下列职务等级编制军衔："},{"i":12,"n":"第十二条","txt":"专业技术军官实行下列职务等级编制军衔："},{"i":13,"n":"第十三条","txt":"军官军衔按照军官职务等级编制军衔授予。"},{"i":14,"n":"第十四条","txt":"授予军官军衔以军官所任职务、德才表现、工作实绩、对革命事业的贡献和在军队中服役的经历为依据。"},{"i":15,"n":"第十五条","txt":"初任军官职务的人员依照下列规定首次授予军衔："},{"i":16,"n":"第十六条","txt":"首次授予军官军衔，依照下列规定的权限予以批准："},{"i":17,"n":"第十七条","txt":"军官军衔按照下列期限晋级："},{"i":18,"n":"第十八条","txt":"军官军衔一般应当按照规定的期限逐级晋升。"},{"i":19,"n":"第十九条","txt":"军官军衔晋级的期限届满，因违犯军纪，按照中央军事委员会的有关规定不够晋级条件的，延期晋级或者退出现役。"},{"i":20,"n":"第二十条","txt":"军官由于职务提升，其军衔低于新任职务等级编制军衔的最低军衔的，提前晋升至新任职务等级编制军衔的最低军衔。"},{"i":21,"n":"第二十一条","txt":"军官在作战或者工作中建立突出功绩的，其军衔可以提前晋级。"},{"i":22,"n":"第二十二条","txt":"被决定任命为中央军事委员会副主席、委员职务的军官晋升为上将的，由中央军事委员会主席授予上将军衔。"},{"i":23,"n":"第二十三条","txt":"本法第二十二条规定以外的军官军衔的晋级，按照军官职务的任免权限批准。但是，下列军官军衔晋级，按照以下规定批准："},{"i":24,"n":"第二十四条","txt":"军官因不胜任现任职务被调任下级职务，其军衔高于新任职务等级编制军衔的最高军衔的，应当调整至新任职务等级编制军衔的最高军衔。调整军衔的批准权限与其原军衔的批准权限相同。"},{"i":25,"n":"第二十五条","txt":"军官违犯军纪的，按照中央军事委员会的有关规定，可以给予军衔降级处分。军衔降级的批准权限与首次批准授予该级军衔的权限相同。"},{"i":26,"n":"第二十六条","txt":"军官军衔降级的，其军衔晋级的期限按照降级后的军衔等级重新计算。"},{"i":27,"n":"第二十七条","txt":"对撤销军官职务并取消军官身份的人员，取消其军官军衔。取消军官军衔的批准权限与首次批准授予该级军衔的权限相同。"},{"i":28,"n":"第二十八条","txt":"军官犯罪，被依法判处剥夺政治权利或者三年以上有期徒刑的，由法院判决剥夺其军衔。"},{"i":29,"n":"第二十九条","txt":"军官军衔的肩章、符号式样和佩带办法，由中央军事委员会颁布。"},{"i":30,"n":"第三十条","txt":"军官佩带的肩章、符号必须与其军衔相符。"},{"i":31,"n":"第三十一条","txt":"预备役军官军衔制度，另行规定。"},{"i":32,"n":"第三十二条","txt":"士兵军衔制度，由国务院和中央军事委员会规定。"},{"i":33,"n":"第三十三条","txt":"中国人民武装警察部队实行警衔制度，具体办法由国务院和中央军事委员会规定。"},{"i":34,"n":"第三十四条","txt":"人民解放军总参谋部、总政治部根据本条例制定实施办法，报中央军事委员会批准后施行。"},{"i":35,"n":"第三十五条","txt":"本条例自公布之日起施行。"}],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyuzh9bf693":[],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyupi68432d":[],"diwujiequanguorenmindaibiaodahuichangwuweiyuanhuig4ce5b2":[]};
